INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DokunMAlar', 'dokunmalar-bahri-yildirim-05t82', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kördür

             göremez

                            sağırdır

                                          duyamaz

Ama iyi yakıştırır.

Ve de kılıcı keskindir sensizliğin.

Yıkılır

        umut

                 ölür 

                        sevda

Yapacağı şey bu değildir 

Sevdalının ama

Okur tekmili birden

Ruhumuza fatiha.

Neden düştün öyleyse aklıma? 

Neden geldin ki  kapıma? 

                  Uzak dur benden

                  Uzakta dur tenimden

                  Ellerime dokunma.

Seni sevmiyorum

Bana yaklaşma

Şeytanlık yapma.

Git! Canın cehenneme

Beynim bile seni tanımadı

Bundan ötesi var mı? Sensizliğin', 'Kördür              göremez                             sağırdır                                           duyamaz Ama iyi yakıştırır. Ve de...', ARRAY['Türk Edebiyatı','Şiir','Bahri Yıldırım']::text[], 8.5, '{"poet":"Bahri Yıldırım","poet_slug":"bahri-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/dokunmalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Loş', 'los-alper-yildiz-jqx4s', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ardında bir giz gibi bırakırsın beni

Sonra dönüp umutlarsın ''yerdeki sarhoş''

Liyakat olup bende sır edersin seni

Izdırap içinde gelsem hoş gelmesem hoş

Hangi hissimin ağır gelirki kefeni

Bir tabuta konulsam yükün bu demde boş

Dön bak bana kendinde bir hoş gör kendini

Gece gündüz yaksan beni ruhum yine Loş.', 'Ardında bir giz gibi bırakırsın beni Sonra dönüp umutlarsın ''yerdeki sarhoş'' Liyakat olup bende sır edersin seni Izdırap içinde gelsem hoş g...', ARRAY['Türk Edebiyatı','Şiir','Alper Yıldız']::text[], 8.5, '{"poet":"Alper Yıldız","poet_slug":"alper-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/los-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbulum', 'i-stanbulum-alper-yildiz-q15rp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bulutlardan istanbul yağıyor üzerime,

Gözyaşımı karıştırıp kendine,

Ben oluyor sırılsıklam...

Merhametli,acımasız...

Sıcak,soğuk...

İstanbul diye manzara yaptım kendimi,

Seyre durdum,daldım,içtim beni.

Eyüp kalbim oluyor,Onda atıyorum...

Topkapı yumruğum,

Yedikulede vicdanım sızlıyor hala...', 'Bulutlardan istanbul yağıyor üzerime, Gözyaşımı karıştırıp kendine, Ben oluyor sırılsıklam... Merhametli,acımasız... Sıcak,soğuk... İstanbul...', ARRAY['Türk Edebiyatı','Şiir','Alper Yıldız']::text[], 8.5, '{"poet":"Alper Yıldız","poet_slug":"alper-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/istanbulum-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Asigim ben ogretmenim', 'asigim-ben-ogretmenim-husamettin-guven-f640j', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'O mekanda olmasaydim

Guzel kizi gormeseydim

Hayallere dalmasaydim

Asigim ben ogretmenim

Gordugum o gunden beri 

Dusunurum geceleri

Neden bir daha gormem seni

Asigim ben ogretmenim

Tesaduf ya ogretmenmis

Bir daha gelmeyecekmis

Beni sonkez gormeyecekmis

Asigim ben ogretmenim', 'O mekanda olmasaydim Guzel kizi gormeseydim Hayallere dalmasaydim Asigim ben ogretmenim Gordugum o gunden beri  Dusunurum geceleri Neden bir...', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Güven']::text[], 8.5, '{"poet":"Hüsamettin Güven","poet_slug":"husamettin-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/asigim-ben-ogretmenim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çile', 'cile-murat-demirbas-29g5l', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sabah kazma kürek sırtında torba

Ye doyabilirsen bir kaşık çorba

Sırtında yok ise giyecek urba

Yaşamaya hakkın mı var be dostum

Çarpılır bacağın tutulur kolun

Dilerse kurtarır mübarek ölüm

Insana laik mi böyle bir zulüm

Allah''ın hikmeti ne dersin dostum

Ne kara yazıdır ne ister benden

Allah iyileri korusun kemden

Ama nasip buysa ne gelir elden

Aç elini dua eyle be dostum

Ekmeğin üstünde bir kaşık ağda

Buğday mı yetişir yeşermiş bağda

Allah kimseleri koymasın darda

Olacak o kadar ne dersin dostum', 'Sabah kazma kürek sırtında torba Ye doyabilirsen bir kaşık çorba Sırtında yok ise giyecek urba Yaşamaya hakkın mı var be dostum Çarpılır bac...', ARRAY['Türk Edebiyatı','Şiir','Murat Demirbaş']::text[], 8.5, '{"poet":"Murat Demirbaş","poet_slug":"murat-demirbas","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/cile-38-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdaman', 'sevdaman-ozan-korkusuz-8g7mb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'önce ince bir yağmur yağdı

sevimli bir köpeğin başını okşar gibi

sonra deli bir toprak kokusu kapladı

boyası dökülmeye yüz tutmuş odamı

ve ben sevgili

sevdanın bagımlısı...

içimde dehşet özlemlerle dolanırım sokaklarında

yüzüm kızarır,söyleyemem

sanki utanılacak birşeymiş gibi gelir

seni özlemek...', 'önce ince bir yağmur yağdı sevimli bir köpeğin başını okşar gibi sonra deli bir toprak kokusu kapladı boyası dökülmeye yüz tutmuş odamı ve b...', ARRAY['Türk Edebiyatı','Şiir','Ozan Korkusuz']::text[], 8.5, '{"poet":"Ozan Korkusuz","poet_slug":"ozan-korkusuz","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sevdaman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Asi sevda', 'asi-sevda-ozan-korkusuz-nbf8x', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bir sevdanın orta yerinde bıraktın beni

öznesi bile belli olmayan bir şiirin

belirtisiz isim tamlamasına sıkıştırdın beni

bir hikayenin düğümünde

hani tamda çözülecekken karışmış ipler

öylece kaldım

yumağa dolaşan bir kedi çaresizliğinde

uçma arzusu dorukta,kırılan kanadıyla

bir serçe yüreğinin ağrısında

kaldım bir başıma...

sırf anlamı kuvvetlendirsin diye

yani başka bir işe yaramayan

devrik cümle gibiyim şimdi

devrik cümlelere inanan bir eşkiyayım

mağrur ve asi

kızıla vurulmuşum

sevdanın en çetrefellisine...

ağzımda sevda sözleri

yüreğimde buruk bir tat

yürüyorum yarım kalan şiirimin yüklemine...', 'bir sevdanın orta yerinde bıraktın beni öznesi bile belli olmayan bir şiirin belirtisiz isim tamlamasına sıkıştırdın beni bir hikayenin düğü...', ARRAY['Türk Edebiyatı','Şiir','Ozan Korkusuz']::text[], 8.5, '{"poet":"Ozan Korkusuz","poet_slug":"ozan-korkusuz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/asi-sevda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mumbai Theme Tune /iç bıçağı...', 'mumbai-theme-tune-ic-bicagi-zafer-zengin-etnika-cllzr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 've ar rahman*

