INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel Sevdim Sevdirmedim', 'guzel-sevdim-sevdirmedim-yusuf-onder-bahceci-pr778', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seven kalbe kim dayanır,

Gözler görür, kâlp uyanır,

Yiğit Allah''ına dayanır,

Güzel sevdim sevdirmedim.

Gözlerinde yaşlar olur,

Güzel sever kalbi durur,

Verdiği sözünde durur,

Güzel sevdim sevdirmedim.

Gözden değil özden sever,

Seven kalbi Dünya değer,

Sevgisi bir ömür sürer,

Güzel sevdim sevdirmedim.

Solmasın dalında güller,

Söyleyin gelsin bülbüller,

Yarimin saçında güller,

Güzel sevdim sevdirmedim....

Bu şiirim de diğerleri gibi Adana''dan Bursa''ya gitsin..', 'Seven kalbe kim dayanır, Gözler görür, kâlp uyanır, Yiğit Allah''ına dayanır, Güzel sevdim sevdirmedim. Gözlerinde yaşlar olur, Güzel sever k...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/guzel-sevdim-sevdirmedim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tatlı dil *', 'tatli-dil-ali-riza-unal-45ih3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne güzel demişsin,dut ile  bal yemişsin,

Tatlı dil helal sihir,sen bu dilden ermişsin

Bizim dilimiz köhnedir,na ehil merde,

Bu bir dür-ü kelamdır,devadır her derde,', 'Ne güzel demişsin,dut ile  bal yemişsin, Tatlı dil helal sihir,sen bu dilden ermişsin Bizim dilimiz köhnedir,na ehil merde, Bu bir dür-ü kel...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/tatli-dil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat Kadını*', 'hayat-kadini-edip-caki-1i4jn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'sakla adını

gelir zamanı

sen düşerimin

hayat kadını

*Başka hayatların hayatlarına giren kadınlara verilen ad...', 'sakla adını gelir zamanı sen düşerimin hayat kadını *Başka hayatların hayatlarına giren kadınlara verilen ad......', ARRAY['Türk Edebiyatı','Şiir','Edip Çakı']::text[], 8.5, '{"poet":"Edip Çakı","poet_slug":"edip-caki","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/hayat-kadini-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlem Damlıyor Yufka Yüreğimden', 'ozlem-damliyor-yufka-yuregimden-i-brahim-halil-demir-kl4tu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Durup dinlenmeden, daim kaçtım. merhametsiz felekten,

Su misali özlem damlıyor, yari seven yufka yürekten.

Vazgeçmek nedir bilmez misin sen ey zalim, gaddar felek? 

Aşkında amele olmuşum, harçlar düşmüyor kürekten. 

Felek, daha ne istiyorsun benden, yaptıkların yetmedi mi? 

Sen ve düşmanlarım  yeterince alay edip gülmediniz mi? 

Azgın dalgalar içinde canhıraşhane kulaç atarken,

Düşmanımsı sinsi planlarının sonu hala daha gelmedi mi? 

Günün birinde girersen sende,  hayatın çıkmaz sokaklarına,

meraklanma senin yaptıklarını ben asla yapmam sana,

Zira ben çile yumağı olan annemden helal süt emmişim,

Seni mahçup etmek için, yapabileceğim  güzellikleri yaparım sana.

22/12/2005', 'Durup dinlenmeden, daim kaçtım. merhametsiz felekten, Su misali özlem damlıyor, yari seven yufka yürekten. Vazgeçmek nedir bilmez misin sen ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Halil Demir']::text[], 8.5, '{"poet":"İbrahim Halil Demir","poet_slug":"i-brahim-halil-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ozlem-damliyor-yufka-yuregimden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönlümün Zindanları', 'gonlumun-zindanlari-hulya-kandemir-xtyj0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Tutsaklara geçit vermez 

Küçük hücrelerle dolu gönlümün zindanları

Taşkın suları andırıyor

Dün ile bugününe koşut olmuş akıl parmaklıkları

Kelepçeler ellerde kelepçelerle bağlanmış

Düşünmeyi unutan yokluğun tutsakları 

Sürgün olmuş bedenim 

Umarsızca geleceğe atıyor adımları

Ara sokaklara dalıyorum ensemde nefesinin sıcaklığı

Korkular üretiyorum tüketirken umutları

Peşimi bırakmıyor inatçı çocuk gibi

Benimle yürüyor yüreğimin gardiyanları.

Zifiri karanlıklarda kulaklarıma vuruyor 

Gönlümün çarpıntıları.

Bilmem nerelerde bıraktım 

Adını hatırlamadığım soysuz sevdaları.

Belki bir bakışta ya da gülüşte

Bir bebek çığlığında ya da eski bir sözde

Sardılar etrafımı gönlümün zindanları…', 'Tutsaklara geçit vermez  Küçük hücrelerle dolu gönlümün zindanları Taşkın suları andırıyor Dün ile bugününe koşut olmuş akıl parmaklıkları K...', ARRAY['Türk Edebiyatı','Şiir','Hülya Kandemir']::text[], 8.5, '{"poet":"Hülya Kandemir","poet_slug":"hulya-kandemir","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/gonlumun-zindanlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '** Sen', 'sen-olgun-ekinci-jhuui', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yabanıl olduğum  ayazlardayken sen

Buz tutarken kirpiklerin akşam alacasında

Bahar oluyorsun keskin sabahlarıma..

Hücrelerim işgalinde, badem kokulu dal''sın..

Yüreğim bahar, mevsim kış

Kar''sız, yağmur''suz

İs..pus..kömür kokulu sokakların

Kaldırımında soluklanıyorum…

Soluduğum her hava sensin

Beyazı ben, sarısı sen Papatya''m

İçime doluyor çiçek çiçek açıyorsun

Gönlüm sana ait bahar bahçedir artık..

Aralık - 2005 - Adana', 'Yabanıl olduğum  ayazlardayken sen Buz tutarken kirpiklerin akşam alacasında Bahar oluyorsun keskin sabahlarıma.. Hücrelerim işgalinde, bade...', ARRAY['Türk Edebiyatı','Şiir','Olgun Ekinci']::text[], 8.5, '{"poet":"Olgun Ekinci","poet_slug":"olgun-ekinci","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sen-713-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Oldum', 'sen-oldum-hulya-kandemir-a6due', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hayatlar gördüm dehlizlerde buz tutan

Bakışlara dokundum suskunluğa kök salan

Kopuşlarda tutundum kimsesiz çığlıklara

Değişmeyen tekrarın değişkenliğinde ses oldum

Şaşırdım pişkin yüzlerin pervasız tebessümlerine

Benliğimi yitirdim, sen oldum

Yok oldum...', 'Hayatlar gördüm dehlizlerde buz tutan Bakışlara dokundum suskunluğa kök salan Kopuşlarda tutundum kimsesiz çığlıklara Değişmeyen tekrarın de...', ARRAY['Türk Edebiyatı','Şiir','Hülya Kandemir']::text[], 8.5, '{"poet":"Hülya Kandemir","poet_slug":"hulya-kandemir","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sen-oldum-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Olmasanda', 'sen-olmasanda-ramazan-karatas-ws4k2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Boynum bükük olsada yaşarım sen git 

Sen olmasanda olur bu yalan hayat 

Seninki sevgi degilmiş bana ihanet 

Sen olmasanda yaşarım bırakta git 

Sen vermedinki alasın benden bu canı 

Yüce mevladır bu canın tek sahibi 

Sana verilecek neyim kaldıki 

Sen olmasanda yaşarım bırakta git 

Acılara tutunmaktır benim kaderim 

Bu hayata böyle alıştım böyle giderim 

Sende vefasız çıktıysan kaderim derim 

Sen olmasanda yaşarım bırakta git 

Ömür dedigin neki üç günlük bir dünya 

Ha mutlu olmuşum ha olmamışım ne fayda 

Bu gün varız yarın yokuz ne çare 

Sen olmasanda yaşarım bırakta git', 'Boynum bükük olsada yaşarım sen git  Sen olmasanda olur bu yalan hayat  Seninki sevgi degilmiş bana ihanet  Sen olmasanda yaşarım bırakta gi...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Karataş']::text[], 8.5, '{"poet":"Ramazan Karataş","poet_slug":"ramazan-karatas","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sen-olmasanda-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey sevgili', 'ey-sevgili-meryem-i-sler-wxlzh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Boşuna kapımı çalma açmam 

Telefonumu arayıp durma bakmam

 Benim için çiçekleri koparma  almam 

Şimdi nafile diz çöküp yalvarman

Yıldızları toplayıp sersen önüme

Sabahları etsen penceremin önünde

Tövbeler dilesen ben ettim sen etme diye

Senin sözün geçmez artık kalbime

Giderken düşünecektin geri dönmemeyi

Ardında bıraktığın seni seveni

Pişmanlık fayda etmez ey sevgili

Yaktın canımı ciğerimi affetmem asla seni', 'Boşuna kapımı çalma açmam  Telefonumu arayıp durma bakmam  Benim için çiçekleri koparma  almam  Şimdi nafile diz çöküp yalvarman Yıldızları ...', ARRAY['Türk Edebiyatı','Şiir','Meryem İşler']::text[], 8.5, '{"poet":"Meryem İşler","poet_slug":"meryem-i-sler","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ey-sevgili-44-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gökyüzü ağlıyor', 'gokyuzu-agliyor-hulya-kandemir-rot9f', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gökyüzü ağlıyor

Ben seni düşünüyorum, gökyüzü ağlıyor…

Elimi uzatıyorum karanlığa

Ellerim titriyor…

Umutla açıyorum kollarımı 

Körpe bakışlar karanlıklarda yitiyor

Aklıma geliyor sensizlik ve şimşekler çakıyor

Korkuyorum sevmekten gökyüzü ağlıyor…', 'Gökyüzü ağlıyor Ben seni düşünüyorum, gökyüzü ağlıyor… Elimi uzatıyorum karanlığa Ellerim titriyor… Umutla açıyorum kollarımı  Körpe bakışla...', ARRAY['Türk Edebiyatı','Şiir','Hülya Kandemir']::text[], 8.5, '{"poet":"Hülya Kandemir","poet_slug":"hulya-kandemir","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gokyuzu-agliyor-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kolay değildi', 'kolay-degildi-hulya-kandemir-nl35n', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kolay değildi doğruyu bilirken yalana koşmak

Ve tükenen umut teknesini riya ile doldurmak

Kumdan kaleler yaptım yaşamak için

Dalgalar vururken bedenime 

Direndim korkuyla savaşmak için

Hücreler ördüm buzdan kaleler üstüne 

Ve kelepçeledim sensizliğin tadını

Müebbet hapiste gardiyanım olsun diye…', 'Kolay değildi doğruyu bilirken yalana koşmak Ve tükenen umut teknesini riya ile doldurmak Kumdan kaleler yaptım yaşamak için Dalgalar vururk...', ARRAY['Türk Edebiyatı','Şiir','Hülya Kandemir']::text[], 8.5, '{"poet":"Hülya Kandemir","poet_slug":"hulya-kandemir","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kolay-degildi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Mektup', 'son-mektup-ramazan-karatas-2pp2o', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Son mektubum sana hatıra olsun 

Öyle bir mektup''ki yırtmayasın 

Yazısı yok diye yakmayasın 

Derinden oku anlayacaksın 

Son mektubum sana hatıra olsun 

Ne yazısı var, nede bir not 

Anlarsan eğer manası çok 

Kelime, satıra ihtiyacı yok 

Derinden derine okursan eğer 

Saklaki belki bir gün bakarsın 

Yüreğin yanınca beni anlarsın 

Gözlerin yaşla dolduğu zaman 

Boş bir mektuba bakıp ağlarsın 

İçinde birdamla göz yaşı olan 

Aklına düştükce hergün ağlayan 

Aşkların en yücesini kalbinde tutan 

Bir garip savenin son namesidir 

Son mektubum sana hatıra olsun...', 'Son mektubum sana hatıra olsun  Öyle bir mektup''ki yırtmayasın  Yazısı yok diye yakmayasın  Derinden oku anlayacaksın  Son mektubum sana hat...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Karataş']::text[], 8.5, '{"poet":"Ramazan Karataş","poet_slug":"ramazan-karatas","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/son-mektup-40-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutfakta yalnızlık', 'mutfakta-yalnizlik-hulya-kandemir-9mvrf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Tükenmiş umut teknesinde hazırladım

Sınırsız sevda hamurunu

İçine bir tutam hüzün

Bir tutam da hasret koydum.

Kesilen hatırlanışlara serzenişler ekledim. 

Göz kararı özlemle üzerini süsledim

Karşılıksız sevgi ateşinde pişirdim

Altı yanmasın diye…', 'Tükenmiş umut teknesinde hazırladım Sınırsız sevda hamurunu İçine bir tutam hüzün Bir tutam da hasret koydum. Kesilen hatırlanışlara serzeni...', ARRAY['Türk Edebiyatı','Şiir','Hülya Kandemir']::text[], 8.5, '{"poet":"Hülya Kandemir","poet_slug":"hulya-kandemir","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/mutfakta-yalnizlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni seviyorum', 'seni-seviyorum-hulya-kandemir-yakk4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir tay oldum dağları aştım. 

Dörtnala koştum aşkına. 

Gel yârim tut ellerimden, gel kollarıma. 

Öyle açım ki sana sar bedenimi, al beni ruhuna. 

Su gibi ak benliğimde. Yıka sensiz geçen dünleri. 

Çok sev beni, çok sev ki coşsun yüreğim. 

Coştukça alevlensin sevgimiz. 

Yılma sevmekten, zorluklar karşısında yıkılma. 

Acıyla sev, özlemle sev. 

Hem gül hem ağla kollarımda. 

Yüreğindeki acılar mutluluğumuzun yolu olsun. 

Sev beni sev ki alevlensin bedenim. 

Yıldızlar altında sevişelim, birleşsin kalplerimiz. 

Düşünme yarınları, anı yaşa ve sar benliğimi. 

Doruğa çıkalım seninle hadi bekleme gel kollarıma. 

Vücudumuz ay ışığında kenetlensin. 

Sakın bırakma ellerimi bil ki varlığınla hayat bulurum… 

Denize haykıralım sevgimizi.

Dalgalar götürsün hüzünleri. 

Hiç yaşadın mı sensizliği? Bir bilsen sensizliği! 

Sensizlikte ölmek! Gel, gel ki öldürme beni. 

Köprüler kuralım aşka.

Adım adım göklere yükselmektir seni sevmek.

Korkulu rüyalar görmek yok, yok artık karamsarlık. 

Güçlü ol! Sev beni sev ki gökyüzünde yıldız olalım. 

Dörtnala koşalım aşka. 

Kimseyle paylaşamam gözlerini, 

Başkasıyla düşünemem seni. 

Sakın bırakma ellerimi. 

Beni sensiz, beni nefessiz bırakma. 

Yaşayamam hasretinle; 

Varlığımsın, hazinemsin, düşlerimsin. 

Bugünüm ve yarınlarımsın. 

Yüreğimdeki yaram seni seviyorum… 

Bir güvercin bıraktım gökyüzüne 

Hissettiklerimi sana götürsün diye. 

Duyuyor musun kalp atışımı? 

Anlıyor musun ıstırabımı? 

Acıyla sevmek özledikçe sevmek sevdikçe özlemek… 

Duy artık sesimi! Yaşayamam sensiz. 

Elini ver bana. 

Hayatımızın kararını ver 

Benimle yaşa… 

Kalbim kalbin olsun gör içimdeki seni. 

Kaybetme sevgimi. 

Boşluğa sürükleme beni. 

Kapanırsa kapılarım sen de yaşayamazsın. 

Bensizlikte kaybolma sevdiğim. 

Dünya bizim etrafımızda dönsün. 

Mutluluktan sarhoş olalım. 

İnan seni hiç üzmeyeceğim. 

Seni hep seveceğim

Gözlerim sonsuzluğa kapanıncaya dek seninim…', 'Bir tay oldum dağları aştım.  Dörtnala koştum aşkına.  Gel yârim tut ellerimden, gel kollarıma.  Öyle açım ki sana sar bedenimi, al beni ruh...', ARRAY['Türk Edebiyatı','Şiir','Hülya Kandemir']::text[], 8.5, '{"poet":"Hülya Kandemir","poet_slug":"hulya-kandemir","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/seni-seviyorum-312-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Veda', 'veda-hulya-kandemir-hq5ws', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ellerimi açtım gökyüzüne

Uçurdum bana bıraktığın yarım kalmış aşkı

Kapattım gözlerimi görmedim bakışlarını

Başımı çevirdim dünlerime

Unuttum senden gelecek yarınları

Pencereye vuran damlalara aldırmadım

Akıttım boşluğa akmayan gözyaşlarını

Gönderdiğin mektupları okumadım

Ve çalan telefonları açmadım

Hatırlamadım çarpıntılarımı

Titremedi ellerim ucu yanık sevdanı silerken

Ve pişman olmadım sevmekten,

İnatla güldüm sen yokken.', 'Ellerimi açtım gökyüzüne Uçurdum bana bıraktığın yarım kalmış aşkı Kapattım gözlerimi görmedim bakışlarını Başımı çevirdim dünlerime Unuttum...', ARRAY['Türk Edebiyatı','Şiir','Hülya Kandemir']::text[], 8.5, '{"poet":"Hülya Kandemir","poet_slug":"hulya-kandemir","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/veda-183-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gurbet Gülü', 'gurbet-gulu-ramazan-karatas-hsrnf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Vatanından uzakta; Gubet ellerde

Bir gonca gül açtı! yüregi mertce

Unutmadı; unutamadı vatanını

Sevgi dolu yürek dolu gurbet gülü

Yücedir sevdası vatanına yurduna

Saygısı sonsuzdur bayragına dinine

Geçit vermez haksızlıga zulme

İşte böyledir gurbet gülü

Damarında taşıdıgı asil kanı

Yüreginde taşıdıgı türkün yeri

Sıgındıgı tek yüce rabbi

İşte gerçek gurbet gülü

Her nefeste binlerce can taşır

Gurbet ellerde yüreginde vatan aşıgıdır

Vatan sensin.! Yüreginin izinde yürü

İşte gurbette vatan! Gurbet gülü', 'Vatanından uzakta; Gubet ellerde Bir gonca gül açtı! yüregi mertce Unutmadı; unutamadı vatanını Sevgi dolu yürek dolu gurbet gülü Yücedir se...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Karataş']::text[], 8.5, '{"poet":"Ramazan Karataş","poet_slug":"ramazan-karatas","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gurbet-gulu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saadete Arzu -2-', 'saadete-arzu-2-alper-kuruk-mk48t', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Başım göğsündeyken

Sıcak nefesin

Nem nem otursun 

Şu alnımın üstüne.

Bir hayat boyu 

Neş''eli sesin

Kulağımı doldursun 

Ses ses üstüne.

Eksilmesin bir yastıkta

Çift başımızın izi,

Çocuklarımızla süsleyelim

Keyfimizce evimizi.

Sabah umutla açılan

Kapanan akşam üstü bereketle

Bir kapımız olsun.

Kuşlar yuvasına dönerken

Çocuklarıma sevinç dolsun

Sabırsızlıkla yolumu bekleyen

Bir sevgili karım olsun...', 'Başım göğsündeyken Sıcak nefesin Nem nem otursun  Şu alnımın üstüne. Bir hayat boyu  Neş''eli sesin Kulağımı doldursun  Ses ses üstüne. Eksil...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/saadete-arzu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm Rüzgarı', 'olum-ruzgari-muharrem-kemal-gunduz-43gqs', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ölüm rüzgarlarının uğultusu

Sensizliğin her gecesi kulaklarımda.

Beni çağırıyor uzatmış ellerini

Son duam adındır dudaklarımda.

Böylemiydi andımız sevgimiz,

Ömür boyu sürecekti tertemiz,

Doymadan hayata her birimiz

Kapıldık gideriz ölüm rüzgarlarına.

Sevda baharıyla dolu bu aşka

Kıyan olmazdı ölümden başka

Ağarmadan saçlar, genç yaşta

kul köle olduk ölüm rüzgarına..

28. Nisan. 1984-ŞIRNAK', 'Ölüm rüzgarlarının uğultusu Sensizliğin her gecesi kulaklarımda. Beni çağırıyor uzatmış ellerini Son duam adındır dudaklarımda. Böylemiydi a...', ARRAY['Türk Edebiyatı','Şiir','Muharrem Kemal Gündüz']::text[], 8.5, '{"poet":"Muharrem Kemal Gündüz","poet_slug":"muharrem-kemal-gunduz","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/olum-ruzgari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neydi?', 'neydi-hulya-kandemir-fyoqx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Giderken düşündün mü ardında bıraktıklarını? 

Neydi ağladığım, beni kahreden neydi? 

Küserken duvar kesildiğim,

Severken coştuğum neydi? 

Sessizce gittin sevdiğim 

Bir veda bile edemedik.

Oysa konuşacak ne çok şey vardı! 

Uçurtmamızı gezdiremedik göklerde

Ve yüreğimizi açamadık poyraza karşı.

El ele verip, meydan okuyamadık acılara…

Uyu sevdiğim, huzur içinde uyu

Bil ki yüreğim atıyor senin yerine de

Unutmayacağım acıyla gülen gözlerini…', 'Giderken düşündün mü ardında bıraktıklarını?  Neydi ağladığım, beni kahreden neydi?  Küserken duvar kesildiğim, Severken coştuğum neydi?  Se...', ARRAY['Türk Edebiyatı','Şiir','Hülya Kandemir']::text[], 8.5, '{"poet":"Hülya Kandemir","poet_slug":"hulya-kandemir","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/neydi-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Turnam', 'turnam-kul-costuk-o7u5j', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Badı seheri esersin yaren ne

İmam Hüseyin''im yaralı Turnam

Ilgıt,ılgıt ötersin derdin ne

İmam Hüseyin''im yaralı Turnam

Ciğer parçalandı o derde çare

İçim sızılar Şah elinden çare

Durmayıp yanar derinde ol yare

İmam Hüseyin''im yaralı Turnam

Sana kıyanlar ki ol Hak''ın nesi

Ali atası Muhammed dedesi

Fatima-tü zühre yari bendesi

İmam Hüseyin''im yaralı Turnam

Şah derdinden Bülbül beter ahuzar

Feryat eder Hü çeker dağla taşlar

Güzel şahıma akar çeşm-i yaşlar

İmam Hüseyin''im yaralı Turnam

Kul Coştuk bu cihan şahsız neyine

Yuh ola Mervan''ın canına yezide

Yarelerim sızlar inmiş derine

Şahım Hüseyin''im yaralı Turnam

Mahi Muharrem 12.02.2005

Peygamber efendimizin Torununa', 'Badı seheri esersin yaren ne İmam Hüseyin''im yaralı Turnam Ilgıt,ılgıt ötersin derdin ne İmam Hüseyin''im yaralı Turnam Ciğer parçalandı o de...', ARRAY['Türk Edebiyatı','Şiir','Kul Coştuk']::text[], 8.5, '{"poet":"Kul Coştuk","poet_slug":"kul-costuk","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/turnam-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstedi Ki', 'i-stedi-ki-sacide-yaylaz-j40d5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Son çırpınışlarıydı,

Tutunmak için yaşama,

Umutsuzca bakındı

Bekledi sıcacık bir el,

Uzansın tutsun onu,

Alsın avuçlarının içine,

Usulca bağrına bassın,

Nefesiyle ısıtsın,

Son çırpınışlarda

Tutunmak için yaşama

Sevgisiyle,yüreğiyle istedi ki

Onu yaşama bağlasın…..', 'Son çırpınışlarıydı, Tutunmak için yaşama, Umutsuzca bakındı Bekledi sıcacık bir el, Uzansın tutsun onu, Alsın avuçlarının içine, Usulca bağ...', ARRAY['Türk Edebiyatı','Şiir','Sacide Yaylaz']::text[], 8.5, '{"poet":"Sacide Yaylaz","poet_slug":"sacide-yaylaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/istedi-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'D-Şiir ve Şarkı Sözleri 3', 'd-siir-ve-sarki-sozleri-3-huseyin-avdic-cbeat', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Şehid Mehmedim/(Hüzünlü)

-Bir asker eşinin ağıdı-

Bir yârim vardı, gitti askere.

Çok gördü kader, sardı kefene.

Kaderin cilvesi mi, ne bu böyle! 

Neydi Rabbim tecellim, bana söyle? 

*   *   *

Bir gece rüyamda gördüm Mehmed''i.

Etme dedi tenkid, sakın kaderi.

Herşeyde bir hikmet, bir hayır vardır.

Mevlâ''ya sığınmak en büyük kârdır.

*   *   *

Sonra aldı beni kollarına.

Ben ölmedim ki, şehidim dedi.

Beni bir daha, sardı sımsıkı.

Üzülme, vatan sağolsun dedi.

Not: TSM olarak bestelendi.

Batı Berlin, 1980-86.', 'Şehid Mehmedim/(Hüzünlü) -Bir asker eşinin ağıdı- Bir yârim vardı, gitti askere. Çok gördü kader, sardı kefene. Kaderin cilvesi mi, ne bu bö...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Avdic']::text[], 8.5, '{"poet":"Hüseyin Avdic","poet_slug":"huseyin-avdic","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/d-siir-ve-sarki-sozleri-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Teselli Değil', 'teselli-degil-alper-kuruk-7xysl', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kahrol sen de ömür güzel kahrına

Bunca zaman kahrolan sen değilsin,

Aldırma dünyanın yokla varına

Ruhun güzel için her dem eğilsin.

Güzel olmasaydı dünyada eğer

Göz verir miydi hiç boş yere Allah? 

Tüm güzellikleri görmeğe değer

Bence şu göz dediğin vallah, billah.

Çocukca küssün mü Yaradanına

Güzel olmadıksa diye çirkinler,

Aşkın kör gözleriyle bakanına

Güzelleşir çirkinler bu da yeter...', 'Kahrol sen de ömür güzel kahrına Bunca zaman kahrolan sen değilsin, Aldırma dünyanın yokla varına Ruhun güzel için her dem eğilsin. Güzel ol...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/teselli-degil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsterim', 'i-sterim-muharrem-kemal-gunduz-0d70k', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Varmasın üstüme yokluğun 

Ben biraz hayat biraz ölümüm.

Yakarım yokluğunda yarınları

Kara bir bulutum, zulümüm..

Gelmesin aklıma saçların

Tutup okşamak isterim

Gözlerin yakmasın benliğimi

Gül kurusu dudakların,

Dayanamam öpmek isterim..

Cana gelmesin güzelliğin gözlerimde

Bitimsiz bakmak isterim

Karanlık bir dünyanın içindeyim

Senin aydınlığında çıkmak isterim..

Ellerin değmesin tenime,

Sarmasın sonunda ayrılık varsa kolların

Bırakmam seni doymak isterim

Bir fısıltıyla değil,

Sen sevdiğimi haykırmak isterim

Seninle açtım dünyaya gözlerimi

Öleceksem seninle ölmek isterim..

  24. Nisan. 1984 - ŞIRNAK', 'Varmasın üstüme yokluğun  Ben biraz hayat biraz ölümüm. Yakarım yokluğunda yarınları Kara bir bulutum, zulümüm.. Gelmesin aklıma saçların Tu...', ARRAY['Türk Edebiyatı','Şiir','Muharrem Kemal Gündüz']::text[], 8.5, '{"poet":"Muharrem Kemal Gündüz","poet_slug":"muharrem-kemal-gunduz","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/isterim-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şarkı', 'sarki-asima-azra-5buyv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hayatın kaldırımda yürürken yalnız

içindeki çocuk yoldan çıkar apansız

sonra inceden bir yağmur değer diline

zamansızlığı bağışlar senin yerine

değer diline

………kimse tatmaz senin yerine

Anlarsın ki irdelenmez yarım sevmeler

ve bilirsin kanıt değil gözle görmeler

sonsuz kuşkular saplanır derinlerine

güneş örtsen kâfi gelmez serinliğine

derinliğine

………..kimse girmez senin yerine

Şimdi terkedilmiş limanlar bile razı değil

örselenmekten mustarip demirlerine! ...

22/12/2005', 'Hayatın kaldırımda yürürken yalnız içindeki çocuk yoldan çıkar apansız sonra inceden bir yağmur değer diline zamansızlığı bağışlar senin yer...', ARRAY['Türk Edebiyatı','Şiir','Asima Azra']::text[], 8.5, '{"poet":"Asima Azra","poet_slug":"asima-azra","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/s-rki-m-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Kendimde Değilim', 'ben-kendimde-degilim-hasan-gorgu-gbp14', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İlk görüşte beni yaktın derin izler bıraktın

Dipsiz kör kuyuya attın ben kendimde değilim

Aşk oldun kalbime aktın kor ateşlerde yaktın

İçecekmiş gibi baktın ben kendimde değilim

              

Bakışlarında büyü var esir etti gözlerin

Aldı aklımı başımdan o sevdalı sözlerin

Yumuşak bir yastık gibi baş koyduğum dizlerin

Aldı artık beni benden ben kendimde değilim

22.12.2005

Saat: 14,30', 'İlk görüşte beni yaktın derin izler bıraktın Dipsiz kör kuyuya attın ben kendimde değilim Aşk oldun kalbime aktın kor ateşlerde yaktın İçece...', ARRAY['Türk Edebiyatı','Şiir','Hasan Görgü']::text[], 8.5, '{"poet":"Hasan Görgü","poet_slug":"hasan-gorgu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ben-kendimde-degilim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hazan', 'hazan-tulay-i-cen-g6bhm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Her ölüm erkendir.

Sensizlik hergün  bir ölüm.

Bu benim kacıncı ölümüm.

Yaşarken ölmek  bu herhalde.

Vurgun yemiş gibiyim,

Sensizlik benim her gün ölümüm.

Sürgündeyim,beni yordu bu diyar.

Yaşarken ölmek  bu....

Yaşamak ne? biliyormusun anlat,

Anlata bilirmisin bu yaşamı....

Ölüm..

Ölümü sor bana işte onu biliyorum.

Benim yaşamım  ölümün ta kendisi.

Ağlıyorum sessiz sessiz.

Eylül ne zaman gelse  o kanına girmeyen hançer,

Bir kez daha  saplanır  yüreğime.

Karanlık  günlerimin başlangıcı Eylül.

Benim yarımı alıp götüren hazan ayı.

Hüzün yine karabulut gibi kapladı,

Bedenimi,  ruhumu.

Hasret yine yakıyor beni.

Sensizlik yüreğime saplanan bir hançer.

Bekliyorum  O kara  treni,

beni sana getirecek  o tren.

Nezaman kalkıcak  O tren.

Biliyorum boş düşünceler,

Bu saatten sonra bütün Eylüller 

Hep böyle acı vericek.

Seni seviyorum ölüme kadar

Ölümden  sonra bile.

07/10/2000', 'Her ölüm erkendir. Sensizlik hergün  bir ölüm. Bu benim kacıncı ölümüm. Yaşarken ölmek  bu herhalde. Vurgun yemiş gibiyim, Sensizlik benim h...', ARRAY['Türk Edebiyatı','Şiir','Tülay İçen']::text[], 8.5, '{"poet":"Tülay İçen","poet_slug":"tulay-i-cen","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/hazan-36-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Belli Değil', 'belli-degil-alper-kuruk-515if', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aşkı göz göze bakışmak sandım

Sandım da bakındım yeşil gözlerine,

Çakmak çakmaktı gözümdeki umut

Ki parladı aşktan yana.

Gelecek gecelerin uykusuzluğu

Daha şimdiden üstümde

Şaşkınım,affet

Ama ilk defa âşık değil.

Gelecekte bir günlük olsa insan ömrü

Sevişmekle geçerdi o gün

Kavaklar boyusıra aşklara gebe...

Aşıkım bir şeye işte

Sana mı, gözlerine mi belli değil? 

İçimde ilahlara has sevgi

İlah ki seni yaratan

Sense ilah değil.

Seviyorum,sevmek sevmemekten çok daha iyi

Hayatı mı,seni mi belli değil?', 'Aşkı göz göze bakışmak sandım Sandım da bakındım yeşil gözlerine, Çakmak çakmaktı gözümdeki umut Ki parladı aşktan yana. Gelecek gecelerin u...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/belli-degil-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaralar Beni', 'yaralar-beni-kul-costuk-2syxf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Nazlı yarim matem eza içinde

Figan eder canan yaralar beni

Hali sedası kalmamış dilinde

Figan eder canan yaralar beni

Nerede gönül,çağlar neşelerin

Bakana mis,can alıcı hallerin

Garib Bülbül''e sunduğun güllerin

Figan eder canan yaralar beni

Arzuhal içinde feryadı dertli

Durmaz akar kara gözleri selli

Sazıda ahuzar kalmış az telli

Figan eder canan yaralar beni

Nazın içinde muhabbet edelim

Arş edip alemi diyar gidelim

Aşkın od''unu Hak için verelim

Figan eder canan yaralar beni

Kul Coştuk alınma yarin nazına

Hoş bak müsteri ol ayan halına

Yarsız girme sefa alem balına

Figan eder canan yaralar beni

12.02.2005', 'Nazlı yarim matem eza içinde Figan eder canan yaralar beni Hali sedası kalmamış dilinde Figan eder canan yaralar beni Nerede gönül,çağlar ne...', ARRAY['Türk Edebiyatı','Şiir','Kul Coştuk']::text[], 8.5, '{"poet":"Kul Coştuk","poet_slug":"kul-costuk","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yaralar-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerin TUTSAKTıR Gözlerimde…', 'gozlerin-tutsaktir-gozlerimde-olgun-ekinci-xa5l5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Terk edilmişliğe soyunan gecenin 					

Tutsak saatlerindeyim  yürürken kendime					

Ela''sı düşünce gözlerinin usuma					

Işıksız yanıltmanın kristal parıltısında yollar..					

					

Yıldızlardan, ay ışığına dönüşüyor ıssızlıkta gece					

Ay çekiliyor geceden, zifiri kaplarken göğü					

İzdüşümü oluyor yollarıma yansıyan gözlerin					

Işık oluyor, aydınlık doğuyorsun yollarıma..					

					

Serçe ürkekliğinde bastığım arnavut kaldırımları					

Titrek, ölgün  yanılsamadan					

Ana caddeleri ışıklandırılmış  metropole					

Bayram arifelerinin şenlik panayırına,					

Sevinç çığlıklarına dönüşüyor çocukların..					

					

Gözlerin gelince aklıma,					

Tutsak saatlerim firar ediyor F tipi esaretten					

Arşınladığım anlardayım geceden sabaha ve					

Bilmediğim sokaklarında bu kentin					

Yalnızlığımla buluşur gözlerin- ki					

Ortak olur geceden tutsaklığıma…					

					

					

Aralık - 2005 - Adana', 'Terk edilmişliğe soyunan gecenin 					 Tutsak saatlerindeyim  yürürken kendime					 Ela''sı düşünce gözlerinin usuma					 Işıksız yanıltmanın...', ARRAY['Türk Edebiyatı','Şiir','Olgun Ekinci']::text[], 8.5, '{"poet":"Olgun Ekinci","poet_slug":"olgun-ekinci","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gozlerin-tutsaktir-gozlerimde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Visâlin cefa değildir', 'vis-lin-cefa-degildir-ali-riza-unal-4vcro', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sevdayı nar-ın kör etti dideyi,

Bu seviş mest-i heva değildir,

Nazargâhın eyle bu sineyi,

Firakın neş’u deva değildir,

Göz yaşım boşamı,bilmez hileyi,

Sil at ar-ını visâlin,cefa değildir..', 'Sevdayı nar-ın kör etti dideyi, Bu seviş mest-i heva değildir, Nazargâhın eyle bu sineyi, Firakın neş’u deva değildir, Göz yaşım boşamı,bilm...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/visalin-cefa-degildir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Metris ve Annem....', 'metris-ve-annem-bahtiyar-arslan-tp5uu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Metrisin önünde 

Artık bekleme anne.

Türkümü dinleme…

Ben artık gittim anne

O kulaktan sağır

O kurşundan ağır, kahvede bekleme…

Metrisin önünde 

Artık durma anne.

Çeşmesinden su içme…

Haberin yok mu?  ben yittim anne

Duyamam, 

O kulaktan sağır

O kurşundan ağır, kahvede türkümü söyleme…

Şafağı bekle anne…', 'Metrisin önünde  Artık bekleme anne. Türkümü dinleme… Ben artık gittim anne O kulaktan sağır O kurşundan ağır, kahvede bekleme… Metrisin önü...', ARRAY['Türk Edebiyatı','Şiir','Bahtiyar Arslan']::text[], 8.5, '{"poet":"Bahtiyar Arslan","poet_slug":"bahtiyar-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/metris-ve-annem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kabahat', 'kabahat-esma-ozdemir-tfnac', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'benim de günahlarım var

sizin gibi, sizler kadar

sevaplarımdan öte…

doğmadan öldürdüğüm

bebe''lerim var gözelerimde; 

bağrıma koyamadığım,

doyamadığım

öksüz çocuklarım var

anneler gibi…

benim de sizin gibi…

kıyımlarım var; 

affedemediğim kendimi…

yalnız bir meşe gibi

sisler arasında

dağ başlarında 

bıraktığım kurda - kuşa

yem diye, yabanıl oğlaklara

vardır herkes gibi 

benim de

en büyük kazancım

en büyük kabahatim!

sahip çıkamadığım

filizi kırık sevgilerim…

susmuyor dereler

ne olur

çağlama sevdiğim!', 'benim de günahlarım var sizin gibi, sizler kadar sevaplarımdan öte… doğmadan öldürdüğüm bebe''lerim var gözelerimde;  bağrıma koyamadığım, do...', ARRAY['Türk Edebiyatı','Şiir','Esma Özdemir']::text[], 8.5, '{"poet":"Esma Özdemir","poet_slug":"esma-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/kabahat-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutluluğu Yaşayamadım...', 'mutlulugu-yasayamadim-i-brahim-ethem-bingul-qojwf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Beni görünce mevsimlerin neşesi kaçıyor

Yoldaşım hazan peşimde, bırakmıyor

İzimi gönlümün kırıklarından buluyor

Ben yaş dökerken o da dünyaya ağlıyor...

Yıkık dökük duygularımın esaretinde

Kaybolmuşum, yanıyorum kaderime

Puslu sabahlara olmuş merhabam

Geçen eskici bile ses vermedi sesime...

Grilerle bakmayı sevmem hayata

Biraz mavi katarım hep duyguma, aşkıma

Nedense mutluluğu yaşayamam doyasıya

Karalar karışır saf bakışıma...

www. iebingül.com', 'Beni görünce mevsimlerin neşesi kaçıyor Yoldaşım hazan peşimde, bırakmıyor İzimi gönlümün kırıklarından buluyor Ben yaş dökerken o da dünyay...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/mutlulugu-yasayamadim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sırça yılan', 'sirca-yilan-necmettin-davulcu-jrclz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'soğuktu yaşanmışlığı tüm çıplaklığıyla

tüm çıplaktı söylenmişleri

rüzgarda eğilen selviydi

yılandı gülmeleri

saman sarısı gözleri ölümdü

sanırdım gülümdü

soğuktu çıplaklığı tümden

dere yatağı yollarında kuşkonmaz üzümüydü bağlarında yetişen

dün sendeydi

bugün bende

yarın onlarda olacak belki

sırası gelen tanıyacak sırça yılanı

duyacak sarı çiyan ıslıklarını

bir bakış kalacak geriye

kimi korkmuş

ağlamaklı kimi

ürkmüş

kimi dalda asılı kalmış

kimi yanacak geçen günlerine

yıllarına

sarılacak kimi yeni bulmuş gibi

hep akıllarda olacak

sırça yılan

en yakının olacak birgün belki

kaçamayacaksın

tanıyamayacaksın', 'soğuktu yaşanmışlığı tüm çıplaklığıyla tüm çıplaktı söylenmişleri rüzgarda eğilen selviydi yılandı gülmeleri saman sarısı gözleri ölümdü san...', ARRAY['Türk Edebiyatı','Şiir','Necmettin Davulcu']::text[], 8.5, '{"poet":"Necmettin Davulcu","poet_slug":"necmettin-davulcu","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/sirca-yilan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gideceksen...', 'gideceksen-bahri-yildirim-trdv9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yılların arkasından baktım bin bir hüzünle

Baktım ki ne göreyim! 

Geriye kalan  sevdam tek senmişsin  gerçekte

Buğulu gözlerinle dalıp gitmişsin yine

Biliyorsun o gözler,hep dokunmuştur bana

Ne olursun? 

Bir daha  öyle hüzünlü  bakma

....

Birde duydum ki  elden,eller söyledi yazık

Ellerden alır olduk haberini 

İğne iplik hesapları yapar olmuş yüreğin

Bu da dokundu bana.

...

Bizim ne ipliğimiz var ki pazara çıkaracak

Pazardan iplik almaya gideriz ama

O bambaşka bir ipliktir.

Benzemez söylenene

Yıkılan,yırtılan,incinen yürekleri

Tamirde kullanılır.

Tamire yarar sadece 

İncedir inceden ince

Ama keskindir her kılıçtan.

Düşmüşsek sevdalı bir yüreğe

Dört bir köşesine tutunup aşkın

Nakış nakış sevdasını işler yarimiz

Gerisi yatmaz kavuğuma

İğne ipliği bırak dostum

O iş değil sana göre.

Gönülden gönüle akmaktır

En doğru yol,

Yolun açık olsun dostum,gideceksen....', 'Yılların arkasından baktım bin bir hüzünle Baktım ki ne göreyim!  Geriye kalan  sevdam tek senmişsin  gerçekte Buğulu gözlerinle dalıp gitmi...', ARRAY['Türk Edebiyatı','Şiir','Bahri Yıldırım']::text[], 8.5, '{"poet":"Bahri Yıldırım","poet_slug":"bahri-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/gideceksen-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Farkeder', 'ne-farkeder-h-hikmet-esen-1rngp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gülse, ne farkeder Güneş,

Batacaksa,

Nesos''un ardından,

Dalgaların koynuna.

Yelkovan,

Akrebin peşi sıra

Yaksa ne çıkar zamanı; 

Soluk soluğa,

An''ın intikamıyla..

Özgür olsa ne çıkar kelebekler; 

Kozasında yaktığı türkülerin,

Genetik aktarımı,

Tırtılın ömrü kadar..

Ve insan; 

Yaşamı kabul ediyorsa,

Onuruyla.

Sokaklarına,

Soluklarıyla adını kazıyorsa ömrün; 

Su''da yansa ne farkeder, 

İnsanın

Kendine rağmen

Anıların sentezinde büyür umutlar.

20/12/2005

...Ayvalık...', 'Gülse, ne farkeder Güneş, Batacaksa, Nesos''un ardından, Dalgaların koynuna. Yelkovan, Akrebin peşi sıra Yaksa ne çıkar zamanı;  Soluk soluğa...', ARRAY['Türk Edebiyatı','Şiir','H Hikmet Esen']::text[], 8.5, '{"poet":"H Hikmet Esen","poet_slug":"h-hikmet-esen","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ne-farkeder-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Divane ha divane', 'divane-ha-divane-kul-costuk-2druc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Açtım nazlıma gönül sayfasını

Sundu yarimde çöller sahrasını

Deldirdi bana dağlar deltasını

Böyleyim Ben divane ha divane

Lal olan dilleri açıp cözdüren

Bende ruhuma sevdalar sezdiren

Tarifsiz tadı sevgiyle gezdiren

Böyleyim Ben divane ha divane

Derya olup susuzu kandıran

Aşkınla ummanlarına daldıran

Mecnun edipde çöllere saldıran

Böyleyim Ben divane ha divane

Tarif edem yare kurbanım işte

Uyardın uyurken ebedi düşte

Oldun sağıma,soluma ol gölge

Böyleyim Ben divane ha divane

Kul Coştuk kurban düştü Şah aşkına

Cevirdin beni pervane şaşkına

Ulu Şahımdan Mürvet bu kuluna

Böyleyim Ben divane ha divane

12.02.2005', 'Açtım nazlıma gönül sayfasını Sundu yarimde çöller sahrasını Deldirdi bana dağlar deltasını Böyleyim Ben divane ha divane Lal olan dilleri a...', ARRAY['Türk Edebiyatı','Şiir','Kul Coştuk']::text[], 8.5, '{"poet":"Kul Coştuk","poet_slug":"kul-costuk","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/divane-ha-divane-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgilerle', 'sevgilerle-ercan-eyvaz-2yf96', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bakışını benden esirgeme diyorum

Kelimelerini de

Sana, benden sevgiler sunuyorken sürekli,

Bunu, platonik bir sevgiye dönüştürme.

Bak aklımdasın.

Dün gece, bugün, şimdi bile

Ne yapsam, neye keşke desem, sen oluyorsun

Ellerimi açıyor 

Dilimde dualarım oluyor.

Donup kalıyorum öylece, gitme diyorum

Bırakma diyorum, beni tek başıma böyle.

Ortada bırakıp bu bedeni

Ben sana gitme diyebiliyorum.

Bak…

Yine akmayan gözyaşım olu veriyorsun.

Boğazıma takılıyor, 

Yarı, kısık sesle, 

Seviyorum seni, demekle yetinebiliyorum. 

Sensiz gidemem, veda edemem.

Yaşayamam…

Hasretim, sevdiğimsin.

Hayatım, yaşamadı böyle baharı

Unuttur hadi, bana bu ağlamaları

Hasretin paslı,kör bir bıçakken

Tekrar, tekrar batırma bu sevdayı

Göğsüme batırıp, çevirme etrafında 

Gece olduğunda uyumak, konuşmak yasak 

Olur, olmaz dolanırsın dilime 

Gelirken gecelerime

Olur, olmaz kıpırtıda işte

Seni gözlerimin önüne alıp 

Kızdığını bile, bile sigarayla

Elimde, sana bakıyorum. 

Hoşça kal diyemiyorum ki… 

Demeye çalışmıyorum da

Bu sevgi, bende olduktan sonra

Bu odada sensiz konuşmak yasak 

Her şey yasak sen yoksan

Bu sevgi bu aşk 

En son bitecek şeydir hayatımda 

Bitecekse eğer sende 

Öldür durma beni, 

Öldür bu genç bedeni

Yaşamayı isteyen kim

Bir köşede bırakıp seni

İsteyen kim cenneti

Seninle tatmak benim için cehennemi

Buna ölüm diyemem 

Bırakma alın yazısına

Dön geri hadi,hemen bana.', 'Bakışını benden esirgeme diyorum Kelimelerini de Sana, benden sevgiler sunuyorken sürekli, Bunu, platonik bir sevgiye dönüştürme. Bak aklımd...', ARRAY['Türk Edebiyatı','Şiir','Ercan Eyvaz']::text[], 8.5, '{"poet":"Ercan Eyvaz","poet_slug":"ercan-eyvaz","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/sevgilerle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Islık kokar yanlızlıklar', 'islik-kokar-yanlizliklar-berrak-su-ssauy', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Açıktan başladı yağmaya,

Sokakların, üzgün şarkısıydı.

Erdem biçmiş,

İhanet giymişti.

Çizilmemişti yüzü,

Ama herkese aşinaydı,

Yanlız, kuru bir yağmur,

Değmeden gidiyordu gözlerine.

Üşütmeden iliklerini.

Kurgusunu yaşıyordu yanlızlığın,

Kendi de yazmamıştı oysa..

Islığına yaslandı 

Ve kapattı gözlerini.

Şimdilerde derin bir uykuda..

Berrak Su', 'Açıktan başladı yağmaya, Sokakların, üzgün şarkısıydı. Erdem biçmiş, İhanet giymişti. Çizilmemişti yüzü, Ama herkese aşinaydı, Yanlız, kuru ...', ARRAY['Türk Edebiyatı','Şiir','Berrak Su']::text[], 8.5, '{"poet":"Berrak Su","poet_slug":"berrak-su","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/islik-kokar-yanlizliklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aldırma', 'aldirma-berrak-su-0ioth', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu uzun bir soluktur,

Acıtan ciğerlerini.

Sıyrıklarda olacak,

Gözyaşlarıda.

Aldırma,

Yolculuk, henüz başladı.

Berrak Su', 'Bu uzun bir soluktur, Acıtan ciğerlerini. Sıyrıklarda olacak, Gözyaşlarıda. Aldırma, Yolculuk, henüz başladı. Berrak Su...', ARRAY['Türk Edebiyatı','Şiir','Berrak Su']::text[], 8.5, '{"poet":"Berrak Su","poet_slug":"berrak-su","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/aldirma-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasretlik Destanım', 'hasretlik-destanim-abdullah-odabas-q91gv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Nedem Erzurumun cümle varını,           	

Kale, burcu, hisar, duvar, surunu,      	

Karlı dağlar soğuk pınar suyunu,        	

Muhubbi sadıkın olmazsa benim,           	

Konuşamam kimseyle hasbihal,            	

Dilim dönmez ebsem lisan sanki lal,     	

Çok dolaşma garib ilde durma gel,       	

Muhubbi sadıkın olmazsa benim,         

Gözüm yoktur çayır çimen taşında,       	

Ne caddesi nede havuz başında,          	

Görsem yeter bir gececik düşümde,       	

Muhubbi sadıkın olmazsa benim,           	

Cami cemaat sanki yabancı,

İçinde olmazsa kardeşim hacı,

Koysalar başıma altından tacı,

Muhubbi sadıkın olmazsa benim,

İstemem dadaş ile efesin,

Altın olsa bülbül kırar kafesin,

Ağlatma bizleri dönüp gelesin,

Muhubbi sadıkın olmazsa benim,

Gayet çoktur meftuninin elemi,

Destan yazar kan ağlıyor kalemi,

Emanet var Selçuk beyin selamı,

Muhubbi sadıkın olmazsa benim,', 'Nedem Erzurumun cümle varını,           	 Kale, burcu, hisar, duvar, surunu,      	 Karlı dağlar soğuk pınar suyunu,        	 Muhubbi sadıkı...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Odabaş']::text[], 8.5, '{"poet":"Abdullah Odabaş","poet_slug":"abdullah-odabas","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/hasretlik-destanim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasretname -I', 'hasretname-i-abdullah-odabas-r0zg4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gurbetlik canıma kar etti yeter,        	

Lutfeyle azizim dön bize doğru,         	

Erzurum dağları karla kaplıdır,         	

Lutfeyle azizim dön bize doğru,         	

Ne yaman eyledin gurbet elinde,         	

Kaldım yad eller nadan elinde,          	

Her zaman isminiz döner dilimde,        	

Lutfeyle azizim dön bize doğru,         	

Herzaman gelirim saadet haneye,         	

Sanki Erzurum dönmüş bir viraneye,      	

Çektim bu acıyı ben de sineye,          	

Lutfeyle azizim dön bize doğru,         	

Mahmut ustadan sormaya geldim dostumu,

Sıcak muhabbetle sıktı destimi,

O anda anladı maksat kastimi,

Lutfeyle azizim dön bize doğru,

Maksadın bizleri yakmak mı nara,

Aç bir telefon bizleri ara,

Gel efendim gel yanmışam nara,

Lutfeyle azizim dön bize doğru,

Ne yazsam sönmüyor içte ateşim,

Gönül ister gelsin benim kardeşim,

Meftuni gamkusar bulmazsam eşim,

Lutfeyle azizim dön bize doğru,', 'Gurbetlik canıma kar etti yeter,        	 Lutfeyle azizim dön bize doğru,         	 Erzurum dağları karla kaplıdır,         	 Lutfeyle azizi...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Odabaş']::text[], 8.5, '{"poet":"Abdullah Odabaş","poet_slug":"abdullah-odabas","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/hasretname-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ziyaret', 'ziyaret-abdullah-odabas-p6vok', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu gün mektubunuz değdi elime,          	

Okuyup tadından doyamaz oldum,          	

Şeker şerbet bal döküyor lisanın,       	

Okuyup tadından doyamaz oldum,        

Ne mutlusun öptün Şahın elini,          	

Hakikat bağının gonca gülünü,           	

Doksan altı rakam büktü belimi,       

Ağlamak yakışır gülemez oldum,          	

Her işleri ustalıkla yaparsın,

Her fırsatta pamuk eli öpersin,

Cenabı hak mükafatın bol versin,

Akan göz yaşlarım silemez oldum,

Ne olur Meftuniye himmette bulun,

Ustası oldun mukaddes yolun,

Bülbülün sefası dalında gülün,

Akan göz yaşlarım silemez oldum,', 'Bu gün mektubunuz değdi elime,          	 Okuyup tadından doyamaz oldum,          	 Şeker şerbet bal döküyor lisanın,       	 Okuyup tadında...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Odabaş']::text[], 8.5, '{"poet":"Abdullah Odabaş","poet_slug":"abdullah-odabas","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ziyaret-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk..', 'ask-bilal-i-lhami-koksal-5dpm7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çok sevdiğin bir şarkıyı

Radyoda

Ne kadar cızırtılı çalsa da hala dinlemek..

Bence aşk cızırtılı radyoda ''kör bıçak'' demek...', 'Çok sevdiğin bir şarkıyı Radyoda Ne kadar cızırtılı çalsa da hala dinlemek.. Bence aşk cızırtılı radyoda ''kör bıçak'' demek......', ARRAY['Türk Edebiyatı','Şiir','Bilal İlhami Köksal']::text[], 8.5, '{"poet":"Bilal İlhami Köksal","poet_slug":"bilal-i-lhami-koksal","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ask-502-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaklaşan Gazap', 'yaklasan-gazap-kadir-albayrak-gpxvg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Denizlerin öfkesi gizlidir dalgalarda

Dövdüğü o kayalar sanma ki muradıdır

İcazet vakti değil  kıvrılıp kalır orda

İşaret alsa bil ki cümleyi tutacaktır

Hoş görü Yaradan da bunca günaha rağmen

Aczini düşün bir an gem azıya gelmeden

Bağışlayan İlahi o son emri vermeden

Gazabın kor narından nefsin kurtulacaktır

Yer yerinden oynayıp şu gökler sarsılınca

Birbirinden kaçarken hem evlat hem de ata

O korkunç gün de telaş nedametse boş çaba

Güneş bile tersine batıdan doğacaktır

Azamet kula değil Yaradan’a yaraşır

Kul olana tevekkül ile secde yakışır 

Tamahın mal mülk ise hep yakana yapışır

Şirk koşarsan cezası ebedi olacaktır', 'Denizlerin öfkesi gizlidir dalgalarda Dövdüğü o kayalar sanma ki muradıdır İcazet vakti değil  kıvrılıp kalır orda İşaret alsa bil ki cümley...', ARRAY['Türk Edebiyatı','Şiir','Kadir Albayrak']::text[], 8.5, '{"poet":"Kadir Albayrak","poet_slug":"kadir-albayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yaklasan-gazap-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Masal', 'masal-hikmet-uzun-qqypk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Son Çarşambası olan çıkmaz aylar yok,

Kaf  Dağını aşacak doru taylar yok,

Nerde tünerse şimdi Zümrüd ü Anka,

Gönlüm gibi çökmüş,sırça saraylar yok.', 'Son Çarşambası olan çıkmaz aylar yok, Kaf  Dağını aşacak doru taylar yok, Nerde tünerse şimdi Zümrüd ü Anka, Gönlüm gibi çökmüş,sırça sarayl...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Uzun']::text[], 8.5, '{"poet":"Hikmet Uzun","poet_slug":"hikmet-uzun","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/masal-112-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Statik çam=Duran çam', 'statik-cam-duran-cam-taner-yusuf-bul-5ww66', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'hey gidi duran

adın gibi statik olmasan

arasan sevdanı ötelerde

korkmasan olmazmı

bildiğin halde

gidi statik seni

onca bilirsinde hayatı

neden bulmazsın sevdanı berilerde

utanmasan olmazmı

olduğun yerde

yakışmaz sana durgunluk,durağanlık

adın statik olabilir

koşmazsan kendine doğru hızla

benden beter düşersin

hayallerinin gerisine

zaman kalmadı diyorum sana

daha öncede demiştim

duy artık

duy artık

aralık 2005', 'hey gidi duran adın gibi statik olmasan arasan sevdanı ötelerde korkmasan olmazmı bildiğin halde gidi statik seni onca bilirsinde hayatı ned...', ARRAY['Türk Edebiyatı','Şiir','Taner Yusuf Bul']::text[], 8.5, '{"poet":"Taner Yusuf Bul","poet_slug":"taner-yusuf-bul","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/statik-cam-duran-cam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öğretmen', 'ogretmen-hasan-geneyikli-kplfn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ÖĞRETMEN

Köy, kasaba, şehir, demez yaşarsın

Şüpheleri yener, güven saglarsın

Gerçeği yıktırmaz, sahip çkarsın

Cehalet satana, korku öğretmen

Sözleri büyülü, ruhları kaplar

Fakir zengin aynı, okula toplar

Bilgi, görgü, sevgi, okunu saplar

Bildiğin saklamaz, saçar öğretmen

Suyu büngül, büngül, sebil pınarı

Karı, kışı, yazı, aynı baharı

Kralı, padişahı, köyde muhtarı

Okutan,yazdıran, bilge öğretmen

Gücüne güç yetmez, zoru devirir

Bilgi bezendırıp, akla güç verir

Ruhların mimarı, cehli giderir

Kararmış kalblere, ışık öğretmen

Fikir, amaç, ilke, kaplamış özü

Aşkı vatan, millet, ilimde gözü

Dine, dile, ırka, ters gelmez sözü

Dünyada dinlenir, sözün öğretmen

Sanal, hülya, rüya, esiri olmaz

Zorlukta pes demez, çözümsüz kalmaz

Sabırla çalışır, güçlükten yılmaz

İrade, karekter, sende öğretmen

Geneyikli, dinleme, izlemeyi

Anlama, anlatım, resim çizmeyi

Sayı, şekil, işlem, proplem çözmeyi

Davranış, becerim, senden öğretmen', 'ÖĞRETMEN Köy, kasaba, şehir, demez yaşarsın Şüpheleri yener, güven saglarsın Gerçeği yıktırmaz, sahip çkarsın Cehalet satana, korku öğretmen...', ARRAY['Türk Edebiyatı','Şiir','Hasan Geneyikli']::text[], 8.5, '{"poet":"Hasan Geneyikli","poet_slug":"hasan-geneyikli","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/ogretmen-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ülkü Eri', 'ulku-eri-hasan-geneyikli-oek5t', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ÜLKÜ ERİ

Görev yeri; şehir, belde, köyler de

İnsan varsa, ocak yanan, her yerde

Ova, yayla, orman, dağda gider de

Engel tanımayan, bir ülkü eri

Katır, at sırtında, bazende yaya

Lazımlar yanında, bakmaz havaya

Yüksek ülkülerle, girmiş davaya

Ruhu, kalbi ile, irfan neferi

Rehberlik, denetim, yapma ödevi

Eğitip, öğretme, kutsal görevi

Cehalete karşı, aydınlık devi

Ruhlar imar eden, egitim eri

Eğiten, öğreten, alır ilhamı

Çareler üretir, giderir gamı

Pedegog, sosyolog, gönül adamı

Dünya siyasetli, düşünce eri

Dünyadan haberli, bilgisi yeni

Amaç, ilkelerde, çağdaş medeni

Tecrübe, bilgiyle, çözer nedeni

Bilgi, beceriler, öğretme eri

Muhakkik, naifdir, kanun namına

Yetkili, sorumlu, makam adına

Adaletle erer, mazlum hakkına

Hakim savcı gibi, adalet eri

Geneyikli, gezdin ufuklar açtın

Gençlik pınarında, su oldun taştın

Dere, nehir, göller, dağları aştın

İnsanlık aşısı, yapan bir ersin', 'ÜLKÜ ERİ Görev yeri; şehir, belde, köyler de İnsan varsa, ocak yanan, her yerde Ova, yayla, orman, dağda gider de Engel tanımayan, bir ülkü ...', ARRAY['Türk Edebiyatı','Şiir','Hasan Geneyikli']::text[], 8.5, '{"poet":"Hasan Geneyikli","poet_slug":"hasan-geneyikli","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/ulku-eri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlarım, Sonra Senden Bilirim', 'aglarim-sonra-senden-bilirim-gunday-duman-efmqf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sebebim olma

Sonra,

Herşeyi senden bilir

Öfkeli bir kırılganlık taşırım.

Akşama çalan saatlerde içer

yanına iliştirilmiş ağız dolusu küfürler savururum.

Ağlarım...

Sonra ben herşeyi

Senden bilir 

Susarım...', 'Sebebim olma Sonra, Herşeyi senden bilir Öfkeli bir kırılganlık taşırım. Akşama çalan saatlerde içer yanına iliştirilmiş ağız dolusu küfürle...', ARRAY['Türk Edebiyatı','Şiir','Günday Duman']::text[], 8.5, '{"poet":"Günday Duman","poet_slug":"gunday-duman","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/aglarim-sonra-senden-bilirim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tümsekler', 'tumsekler-hasan-geneyikli-64u6d', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'TÜMSEK

Onüç piyade taburu

Onbir top bataryası

Süvari, tankı, tayyaresi

Zalimden sayısız mermi

Yetmişbin top güllesi

Karşı koyan, bindörtyüz tüfek

Siper oldu tümsekler

Onay, on gün mücadele

Dendi girilemez, biz varız

Güherçile, kükürtle barut

Tencere,tabağı fişek yaparız

Yurt verilmez düşmana

Silahsız, tırnak, yumrukla kovarız

Diyenlerle oldu tümsekler

Yedi yaşında Kâmil

Dağ gibi Mehmet Karayılan

Bin askere, tek başına yiğit

Şahin Bey Mehmet Sait

Altıbin üçyüz kırk şehit

Bilinen kutsal tümsekler

Bomba gürültüsü, şarapnel

Kurşunlar vızıldadı

Döndü haksız, zalime ecel

Yenilmezliği, Antep’i yazdı tarih

Tutsak edemedi, kırıldı boğacak el

Tarihim, şahidim, şehidim 

Bu mübarek tümsekler

Nur yüzlü ihtiyarlar

Cefakâr analar

Çileli bacılar

Cennet kuşu çocuklar

Gelincikleri bayrak olur

Şehitlerini örter

Al, al renklenir tümsekler

Bu topraklar için verildi can

Kokusu kan, rengi kan

Kurtuluş şehitleri yatan

Vatan için buradalar bilirim

Anar, dualarımı gönderirim

Geneyikli’nin yüreğidir tümsekler', 'TÜMSEK Onüç piyade taburu Onbir top bataryası Süvari, tankı, tayyaresi Zalimden sayısız mermi Yetmişbin top güllesi Karşı koyan, bindörtyüz ...', ARRAY['Türk Edebiyatı','Şiir','Hasan Geneyikli']::text[], 8.5, '{"poet":"Hasan Geneyikli","poet_slug":"hasan-geneyikli","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/tumsekler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hani', 'hani-taner-yusuf-bul-tphs8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'sana yazdım 

gece düştükçe içime

uludukça pusudaki şerefsiz kurtlar

korkma diye bağırdım

duymadın

sana yazdım

unutamadığımı fısıldamak

kan gövdeyi götürürken,koparken en kara fırtınalar

hala benim diyebilmek için seslendim

duymadın

seni andım

her mutlu şarkıda seni

tüm hüzünlerde bizi andım

koştum çaresizce anılarımın ardından

yüreklice durdum geçmişimin karanlıklarında

tutup saçlarından sürüdüm aşkları

anlatırım sandım ama

umursamadın

aralık 2005

ankara', 'sana yazdım  gece düştükçe içime uludukça pusudaki şerefsiz kurtlar korkma diye bağırdım duymadın sana yazdım unutamadığımı fısıldamak kan g...', ARRAY['Türk Edebiyatı','Şiir','Taner Yusuf Bul']::text[], 8.5, '{"poet":"Taner Yusuf Bul","poet_slug":"taner-yusuf-bul","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/hani-90-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şehidim', 'sehidim-zekeriya-yeniyol-9qrqa', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şehit Fuat Bal''ın anısına,tüm şehitlerimize..

Gözün arkada kalmasın! 

Huzurla yat yüce yerinde

Cennetlerdir ki

Onurlandı seninle..

Yum gözlerini,rahat uyu Şehidim! 

Yum gözlerini; 

Bil ki ardında kalanları,

Senin kalbinden süzen,

Senin gözünle gören

Binlerce gözlerin var.

Yum gözlerini,rahat uyu Şehidim! 

Sakın! sakın aklına o meşum soru gelmesin; 

Bil ki yolundan dönenlerin

Yollarını kesecek

Sözünün erleri var.

Bil ki sana uzanan dili

İnlerine gömecek

Binlerce ellerin var.

Yum gözlerini,rahat uyu Şehidim! 

Biliyor kardeşlerin neden adının burada

Yazılı olduğunu.

Bil ki; biliyor kardeşlerin

Mezarının kanla kazılı olduğunu! ...

                                        01.12.05', 'Şehit Fuat Bal''ın anısına,tüm şehitlerimize.. Gözün arkada kalmasın!  Huzurla yat yüce yerinde Cennetlerdir ki Onurlandı seninle.. Yum gözle...', ARRAY['Türk Edebiyatı','Şiir','Zekeriya Yeniyol']::text[], 8.5, '{"poet":"Zekeriya Yeniyol","poet_slug":"zekeriya-yeniyol","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sehidim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ana''dan Mehmede mektup! ...', 'ana-dan-mehmede-mektup-kadir-albayrak-n549m', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Vatana nöbetin sırası gelmiş

Seni de yollara koyduk Mehmedim

Bayrağa sancağa erlik gerekmiş

Dağın da bağın da yel ol Mehmedim

Ak sütüm helalim duam başına

Sahip ol toprağın her karışına

Sen bakma ey oğul gözüm yaşına

Düşmana yol geçit verme Mehmedim

Deden Çanakkale atan Yemen de

Dönüşü olmadı onlar gidende

Bilsem ki ey oğul kurşun sinen de

Vatanım sağ olsun derim Mehmedim

Anayım yüreğim çok özler seni

Bilirim düşün de görürsün beni

Düşünme ey oğul bacı kardeşi

Bu bayrak bu toprak “benim” Mehmedim

Siper de Hasanım hat-ta Muradım

Ali-si Ahmed-i hepsi evladım

Sen iste ey oğul ben de varayım

Silahın tetiğin benim Mehmedim

Dilin de tekbirin gönlün de iman

Vermesin haine düşmana aman

Unutma ey oğul “Var ki bir zaman”

Sakarya su değil kan-dı Mehmedim

Canımın parçası evladım benim

Buram buram tüten ocağım benim

Boş kalsa ey oğul kucağım benim

Can düşer o bayrak düşmez Mehmedim

Bayrak ki gönder de sakin mi durur

Dalgalanmıyorsa rüzgarı durdur

Dileğim ey oğul isteğim budur

Allah-a emanet ettim Mehmedim', 'Vatana nöbetin sırası gelmiş Seni de yollara koyduk Mehmedim Bayrağa sancağa erlik gerekmiş Dağın da bağın da yel ol Mehmedim Ak sütüm helal...', ARRAY['Türk Edebiyatı','Şiir','Kadir Albayrak']::text[], 8.5, '{"poet":"Kadir Albayrak","poet_slug":"kadir-albayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/ana-dan-mehmede-mektup-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yollar Uzak Gelemem', 'yollar-uzak-gelemem-yusuf-onder-bahceci-yg3dw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Senin için ağlıyor,

Seni seven gözlerim,

Sitem değil sevdiğim,

Şikayet bu sözlerim.

Yollar uzak gelemem,

Nerdesin sen bilemem,

Ayrıyım ben gülemem,

Senden haber alamadım.

Yollar uzak sıra dağlar,

Yârim gurbet elde ağlar,

Güzel sevdim kader bağlar,

Şikayet bu sözlerim.

Üzülme sen sevdiğim,

Benim gönül verdiğim,

Senin suçun yok bunda,

Benim cânım dediğim.....', 'Senin için ağlıyor, Seni seven gözlerim, Sitem değil sevdiğim, Şikayet bu sözlerim. Yollar uzak gelemem, Nerdesin sen bilemem, Ayrıyım ben g...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yollar-uzak-gelemem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mehmet-ten ana''ya mektup! ...', 'mehmet-ten-ana-ya-mektup-kadir-albayrak-9uod2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gönlünün sultanı ben idim senin

Bilirim yolumu gözlersin anam

Her gece hasrete vardır seferin

Ha akşam ha sabah beklersin anam

Babacım nasıldır ya Zeynep bacı

Burada bir selam gönlün ilacı

Cümleniz olmuştur bize duacı

Sıladan havadis veriver anam

Nöbetteyim şu an bir dağ başın da

O dağ ki kan vardır her bir taşın da

Ahmed-i Mehmed-i yirmi yaşın da

Bir resim gönderdim bakıver anam

Rüzgarı pek serttir soğuk geceler

Bizden önce geldi geçti niceler

Hele bayrağıma bir göz dikeler

Sen bana şahinim deyiver anam

Süleyman emminin oğlu Mustafa

Bir kahpe kurşunla düştü toprağa

Öyle bir sardık ki onu bayrağa

İmrendim ardından biliver anam

Gün olur nöbetim sona erende

Elini öperek geldim diyende

Bir hasret daha var yüreciğimde

Ayşe-me bir haber ediver anam

Kırk gün olmasa da on beş gün düğün

Yavuklum gönlüm de inan kör düğüm

Bir sensin rüyam da bir o gördüğüm

Şafakları bir bir sayıver anam

Ama darılmak yok dönemez isem

Olur da kanlanır yeşil elbisem

Hak vaki olur da şehit ben isem

Ağlama yaşını siliver anam

Ben ki evladınım ben ki Mehmedim

Düşmana haine geçit vermedim

Bayraksız bir ova bir dağ görmedim

Bu Vatan sağ olsun deyiver anam', 'Gönlünün sultanı ben idim senin Bilirim yolumu gözlersin anam Her gece hasrete vardır seferin Ha akşam ha sabah beklersin anam Babacım nasıl...', ARRAY['Türk Edebiyatı','Şiir','Kadir Albayrak']::text[], 8.5, '{"poet":"Kadir Albayrak","poet_slug":"kadir-albayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/mehmet-ten-ana-ya-mektup-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerimden Gözlerin Yansıyor', 'gozlerimden-gozlerin-yansiyor-ayfer-ersoy-pfjz3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bağrıma düşen sancı yansıyor sokak aralarına 

Ne soğukluğunu anladım ne sıcaklığını 

Her gece ayrılığın saatinde 

Avuçlarımda sancıyor yokluğun.......... 

İster aşk de 

İster tutku 

İster gel geç bir melankoli 

Yada rüzgar de 

Eserken bir dalın yaprağını koparıp giden........... 

İçimdesin:................ 

Gözlerimden gözlerin yansıyor 

24/08/2005', 'Bağrıma düşen sancı yansıyor sokak aralarına  Ne soğukluğunu anladım ne sıcaklığını  Her gece ayrılığın saatinde  Avuçlarımda sancıyor yoklu...', ARRAY['Türk Edebiyatı','Şiir','Ayfer Ersoy']::text[], 8.5, '{"poet":"Ayfer Ersoy","poet_slug":"ayfer-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gozlerimden-gozlerin-yansiyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadınımıza', 'kadinimiza-deli-mavi-3etzx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Tarlada çapada, sırtında bebe 

Savaşta cephede, olsa da gebe 

Emeği çok yerde, para yok cebe 

Sevgi saygı haktır kadınımıza...............Hülya Ekmekçi 

1. 

Bir gül kadar güzel, nazik ve ince 

Eşin olur yarin, günü gelince 

Mutludur gülümser, az sevilince 

Kırılsın kalkan el kadınımıza................Hülya Ekmekçi 

2. 

Kadın bir gül gibi,sevilmelidir 

Sevgiyi saygıyı, hep görmelidir 

Kadına hakları, verilmelidir 

Sevgi ile bakın kadınımıza..................Feride Ömür 

3. 

Evden koparılır, ele karışır 

Ezayla cefayla, hergün yarışır 

Bugün kavga etse, yarın barışır 

Şiddet göstermeyin, kadınımıza.........Burhanettin Akdağ 

4. 

Dokuz ay karnında taşır insanı 

Gül kokar nefesi asildir kanı 

Narindir yapısı sıkılır canı 

Sevgi saygı göster kadınımıza...........Mustafa Alpaydın 

5. 

Ak eli yoğurur işler hamuru 

Kapatıp yok eder her tür çamuru 

Kaderine razı, yoktur samuru 

Öfke değil bir gül, kadınımıza.............Hülya Ekmekçi 

6. 

Kadın hem anamız hem de bacımız 

Eşimiz dostumuz hep baş tacımız 

Şifa kaynağımız tek ilacımız 

Layık olmalıyız kadınımıza.................Ahmet Sefer Koçer 

7. 

Elinin deydiği işte bereket, 

Onunla şan bulur milli hareket, 

Hem kutsal davadır hem de tarikat, 

Dervişan olunur kadınımıza................Şemsettin Dervişoğlu 

8. 

Yöntem olmuş dayak, yoz fikriyatta 

Yok demek olmaz mı, cinsel hayatta 

Köle gibi kabul, yok şeriatta 

Eziyet hak değil, kadınımıza...............Kazım UZUN 

9. 

Kadınlar gününde, olmaz ki dayak 

Gelir de yalvarır,hep yalınayak 

Çileli doğmuşum, yeter bu dayak 

Dayağa sebep ne kadınımıza.............Feride Ömür 

10. 

Kadına saygı ve hak verilmeli 

Kadın fedakardır, hep sevilmeli 

O bir eş bir ana, taç edilmeli 

Eza cefa etme, kadınımıza...............Dilek Hokkaömeroğlu 

11. 

Beyaz camda gördüm, daha dün akşam 

Eşi tarafından, dövülmüş adam 

Dünyada ilk diye, çıldırdı medyam 

Haksızlık etmeyin, kadınımıza............Burhanettin Akdağ 

12. 

kadınlar çiçektir, vurursan solar, 

yüreği ipektir, kızarsan kopar, 

gözleri narindir, bakarsan ağlar, 

Hak değildir dayak kadınımıza.............Emrah Çetinkaya 

13. 

Bin yıldır inanır bu biçim yoktu 

Hanenin hatunu itibar çoktu 

Kimseye aç bakmaz yüreği toktu 

Kapatmak hakaret kadınımıza...........Esat Korkmaz 

14. 

ekmek su gibidir kutsaldır kadın 

Başarının adıdır her daim kadın 

Onsuz olurmu hiç yaşamda tadın 

Her erkek muhtaçtır kadınımıza.............Metin Yaltı 

15. 

Sevgiyi bulmamış, hep ağlamışsın 

Yazgı demiş yine, sen yalvarmışsın 

Hep ezmişler seni, çile çekmişsin 

Ezilmek yakışmaz kadınımıza................Feride Ömür 

16. 

Beni de seni de, doğurdu kadın 

Her zaman yanında, darda kalmadın 

Seni hep doyurdu, yokluk tatmadın 

Saygı hak değil mi, kadınımıza...............Burhanettin Akdağ 

17. 

O sevgi besleyen, koca yürektir 

Şefkati isteyen, nazlı bebektir 

Size gülümseyen, narin çiçektir 

İhtimam lazımdır, kadınımıza..................Kazım Uzun 

18. 

Gün, gece çalışır, bin bir emekle 

Kıt kanaat geçim, az bir yemekle 

Ne geçer eline, yumruk kötekle 

Dar etme dünyayı kadınımıza.................Hülya Ekmekçi 

19. 

Kaşık düşmanıdır, o eksik etek 

Karnındaki sıpa, cinsel bir istek 

Hiç inmeyecek der, sırtından kötek 

Bu nasıl bakıştır, kadınımıza.................Kazim Uzun 

20. 

Karnında taşırken bebeğimizi, 

Merhamet gerekir kadınımıza, 

Göğsünden beslerken biçareleri, 

Kutsama yakışır kadınımıza..................Fikret İnceoğlu 

21. 

Yaz kış usanmadan,o hep koşturur 

Kimi üzgün görse hemen coşturur 

Diyemezler evde,zaten boş durur 

Yardımcı olalım kadınımıza....................Ahmet Sefer Koçer 

22. 

Yüreği hassastır,dili bal şeker, 

Gömer kötülüğü,sevgiler eker. 

Katlanır zorluğa,sineye çeker, 

Değer vermek gerek,kadınımıza.............İshak ÖZLÜ 

23. 

Asla boyun eğmez, bilmez yılgınlık 

Sakindir her zaman,etmez çılgınlık 

Affedici olur, yapmaz kızgınlık 

Kalpsizlik etmeyin, kadınımıza..............Burhanettin Akdağ 

24. 

Sözü öz olanın özü köz olur, 

Yücelik yakışır kadınımıza, 

Namus iffet haya ondan sorulur, 

Ne desek az olur kadınımıza..................Fikret İnceoğlu 

25. 

Dünyaya getirir, gözetir korur 

Besleyip büyütür, doğası gurur 

Yemeyip yedirir, adam oldurur 

Saygı sevgi göster kadınımıza...............Hülya Ekmekçi 

26. 

Gönlünün yarası,içimi yaktı. 

Gözlerinin yaşı,kalbime aktı. 

Üzerine çöken,üzüntü hak mı? 

Kurban olayım ben,kadınım/ız/a............Ahmet Bektaş 

27. 

Kıyafet namusu korur mu sence 

Yüreğine yaslan eğlen gönlünce 

Yakışanı giyin süslen kendince 

Zarafet yakışır kadınımıza....................Esat Korkmaz 

28. 

Kimi tarlalarda tahılb üretir 

Kimi salonlarda koro yönetir 

Kimi sınıflarda ilim öğretir 

Şapka çıkaralım kadınımıza................Ahmet Sefer Koçer 

29. 

Sözün eri olur yurdum kadını, 

Evine hükmeder yazar adını, 

Aman ha dikkat et alma ahını, 

Ululuk yakışır kadınımıza...................Fikret İnceoğlu 

30. 

Kadın bir çiçektir sevipte kokla 

Eline ne geçer oyalanmakla 

Gecikmiş değilsin gururu sakla 

Yüceltip değer ver kadınımıza..............Ramazan Sağlam 

31. 

Cennetin tahtı mı, ayağın altı 

Sinesi iremdir, girmesi tatlı 

Anadır bacıdır yardır kanatlı 

Kadirsiz olmayın kadınımıza................Vesel Koşar 

32. 

Daha kurumadan elde kınası 

Nasıl kıydın ateşlerde yanası 

Bu gün üçü daha şehit anası 

Allah sabır versin kadınımıza.................Ahmet Sefer Koçer', 'Tarlada çapada, sırtında bebe  Savaşta cephede, olsa da gebe  Emeği çok yerde, para yok cebe  Sevgi saygı haktır kadınımıza...............Hü...', ARRAY['Türk Edebiyatı','Şiir','Deli Mavi']::text[], 8.5, '{"poet":"Deli Mavi","poet_slug":"deli-mavi","theme":"Türk Şiiri","is_hero":false,"total_lines":164,"source_url":"https://www.antoloji.com/kadinimiza-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Senli Sensiz Sohbetlerde', 'sana-senli-sensiz-sohbetlerde-ayfer-ersoy-ghn44', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '---1

Yine bir yanım eksik karşıladım sabahı 

Yine güne yarım başladım 

İçimde bir gülüş yarım.............22/08/05

----2

SANDALIM BEN acık denizlerde yüzüyorum...kendi kendime... 

İçinde ne varsa akıtırsın... açık açık söylersinde anlaşılmazsın.... 

Saklarsın saklanırsın... 

Bir gün bir bakmışın 

Hiç bilmediğin, hiç bilinmeyene en çok bildiğin ve en çok bilen olmuş.... 

Ve bir bakmışın okyanusun ortasında bir ada ve herşey sen..........18/08/05

----3

Herkes kafesinde mutluyken 

Kim anlar ki bayırlarda rüzgarla kanat çıpmanın tadını... 

Ve o anın 

İçinde sakladığın çığlığın serbest kaldığı an olduğunu...18/08/2005', '---1 Yine bir yanım eksik karşıladım sabahı  Yine güne yarım başladım  İçimde bir gülüş yarım.............22/08/05 ----2 SANDALIM BEN acık d...', ARRAY['Türk Edebiyatı','Şiir','Ayfer Ersoy']::text[], 8.5, '{"poet":"Ayfer Ersoy","poet_slug":"ayfer-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sana-senli-sensiz-sohbetlerde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şans', 'sans-ayfer-ersoy-m5fvf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İki ayrı gözde tek yürek olmak....

Bu bir şanstır seven ve sevilen için, 

Bir kısmet belki de bir daha bulunamayacak; 

El ele tutuşmanın coşkusunu tekrar yaşama şansı 

Belki; belki de bir hayal...

Hayal kurmanın bile insanı mutlu ettiği,

Eskiyi Yaşayıp acı çekmeyi göze alabildiği,

Acı çekmenin bile güzel geldiği.... şans işi...

HEPİMİZ HAYALLERİMİZ KADAR VAROLURUZ; 

VE HEPİMİZ SÖYLEDİĞİMİZ KADAR DEĞİL 

HİSSETTİĞİMİZ KADAR SEVERİZ...21/07/2005', 'İki ayrı gözde tek yürek olmak.... Bu bir şanstır seven ve sevilen için,  Bir kısmet belki de bir daha bulunamayacak;  El ele tutuşmanın coş...', ARRAY['Türk Edebiyatı','Şiir','Ayfer Ersoy']::text[], 8.5, '{"poet":"Ayfer Ersoy","poet_slug":"ayfer-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sans-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiliye Mektup', 'sevgiliye-mektup-ahmet-mansuroglu-4p3rx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sana sarhoş demişler benim için

Ayyaş demişler

Gün boyu yalpa yapıyor demişler

Antakya sokaklarında

İnandın mı? ...

Yalan değil sarhoşluğum

Ayaklarım takılıyor hep sokak taşlarına

Bu sarhoş gövdeyi taşımaktan

Yorgun düşmüş ayaklarım...

Oysa sen bilrsin

Benim sarhoşluğum, şaraptan rakıdan değil

Aşk şarabını gözlerinden içmişim

Gidişinle kahroldum

Kendimden geçtim

Meyhane köşelerinde sızanlar

Ayılıyor sabahları

Bense, günün yirimi dört saatinde

Özlemin dolu kaseden içiyorum sarhoşluğumu

Ayılmak mümkün değil

Dilersen gel artık yeter

Bitsin bu zindan günler geceler

Yeter dostun düşmanın güldüğü

Sarhoş dediği yeter...

Sana sarhoş demişler benim için

Ayyaş demişler inandın mı? ...

    18.06.1966

 Antakya - Hatay

 Tlf: 0 326 2156779', 'Sana sarhoş demişler benim için Ayyaş demişler Gün boyu yalpa yapıyor demişler Antakya sokaklarında İnandın mı? ... Yalan değil sarhoşluğum ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Mansuroğlu']::text[], 8.5, '{"poet":"Ahmet Mansuroğlu","poet_slug":"ahmet-mansuroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/sevgiliye-mektup-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '**Hesaplaşmalar', 'hesaplasmalar-nurten-altinok-y5jrb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hoşgeldiniz 

                                 

Varma üstüme

Eşeleme küllerini zamanın

Kolay olmadı esen rüzgarlara kafa tutmam

Kolay olmadı poyrazlarda ayakta kalabilmem

Sütliman bir denizin adasındayım şimdi

Kocaman bir yanardağ içimde 

Patlamaya hazır gibi

Varma üstüme

Çocuktur yüreğim

Tez kanar bir elma şekerine

Sen değil miydin geri tepen umutları

Sen değil miydin 

Elinin tersiyle iten

Ve sen değil miydin

Kendini başkalarına aşık bilen

Ben’in Ben olmadığımı söyleyen

Sen değil miydin? 

Oysa sen, hep o sen’din

Biliyordun

Sustun 

Üstüne gitmek olamazdı sevginin

Biliyordum

Sustum

Varma üstüme

Çocuktur yüreğim

Doğru söyler ne söylerse

Yağmur kokusu var gözlerimde şimdi

Korkuyor muyum ne! ..', 'Hoşgeldiniz                                    Varma üstüme Eşeleme küllerini zamanın Kolay olmadı esen rüzgarlara kafa tutmam Kolay olmadı ...', ARRAY['Türk Edebiyatı','Şiir','Nurten Altınok']::text[], 8.5, '{"poet":"Nurten Altınok","poet_slug":"nurten-altinok","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/hesaplasmalar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anılar Karışır/Şiir Başkalaşır', 'anilar-karisir-siir-baskalasir-cenk-aksal-m0ght', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ah! şu yılların ettiğine bak,

nasılda duygusal etti beni,

ya da yaşlandıkça alıngan.

kimse bilemez ki:

zamanın bendeki hesabını,

anıların alıp götürdüklerini,

oysa anlatmıştım:

onyedimde aşk,şiirimde

-----------------------

taze bir liseliyken yaşadıklarımı,

ve yirmi yıl önceki istanbul resimlerini,

seyreylerken daldım işte geçmişe,

o zamandan kalmadır hüzünbaz şiirlerim,

ve sevdaya büyülü dalgınlıklarım...

------------------------

anlamsız ayrılıklara isyanım,

insan sevgisi kalmayanlara

ve sahte sevgilere kör bakışım

yirmi yıl önceki İstanbul gibidir...

saf kalplerde büyük aşkların

menfaate döndüğü bugünlerde

at gözlüğü takanlaradır isyanım...

------------------------

binlerce yürek yandı sebepsiz,

binlerce ayrılık ve ölüm  yaşandı,

yıllar önce güzel bir dünya dileğim,

şimdi kapkara yüreklerde zehirlendi,

isimsiz mezarlar kazıldı,

zamansız ölümlerin ardından...

-------------------------

yitmeyen umutlarımla ben şimdi,

unutulmuş aşkların şiirlerini yazıyorum,

bazen anılara dalarak hüzünlü,

bazen eski aşkları hatırlayarak,

yirmi yıl öncesi sevinci yazıyorum.

ellerim kalem tuttukça ben yine:

bazen kızgın,bazen neşeli,

sevdaları,aşkları

yazmaya devam edeceğim....', 'ah! şu yılların ettiğine bak, nasılda duygusal etti beni, ya da yaşlandıkça alıngan. kimse bilemez ki: zamanın bendeki hesabını, anıların al...', ARRAY['Türk Edebiyatı','Şiir','Cenk Aksal']::text[], 8.5, '{"poet":"Cenk Aksal","poet_slug":"cenk-aksal","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/anilar-karisir-siir-baskalasir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni yazmamak elde değil', 'seni-yazmamak-elde-degil-eyup-selahattin-dalkiran-e0rlu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen var ya sen

Aptal olan seni yaşar

İnan aptalın teki olur

Yüreğini sana bağlayan

Çünkü sen çok zekisin inan 

Unutma ki akıllının da

Akıllısı vardır seni yener.

Biliyorum oltayı atmışsın

Bekliyorsun düşecek diye

Ama ben bildiğin balıklara benzemem 

Bir bakmışsın ki oltanı koparıp gitmişim

Ben seni düşünmem 

Düşünen sen olursun 

Ne uykusuz kalırım

Nede üzüntüden sarhoş olurum.

Hani şair ve yazarlar

Şiir ve roman yazarlar ya aşk üstüne

Ha bire kalemleriyle kağıt içine 

Kendilerini doğrarlar kokoreç gibi

Sonra kendilerini yerler acımasızca

Acımadan yapılarına 

Oysa ben doğramam kendimi 

Çünkü ben senden daha akıllıyım

Ben ne oltaya gelirim 

Nede kalem ile seni yazarım kağıt içine 

Tüh yine yazdırdın kendini.', 'Sen var ya sen Aptal olan seni yaşar İnan aptalın teki olur Yüreğini sana bağlayan Çünkü sen çok zekisin inan  Unutma ki akıllının da Akıllı...', ARRAY['Türk Edebiyatı','Şiir','Eyüp Selahattin Dalkıran']::text[], 8.5, '{"poet":"Eyüp Selahattin Dalkıran","poet_slug":"eyup-selahattin-dalkiran","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/seni-yazmamak-elde-degil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doksan Derece Düşüş', 'doksan-derece-dusus-alper-kuruk-qjrhi', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hepsine hamdolsun diyoruz

Hamdetmesek elimizden ne gelir? 

Şu günahkâr ömrümüz içinde

Kâh düşüp,kâh kalkıp

Geçinip gidiyoruz.

Şİmdi düşsek de hiç olmazsa

Bir el uzanır kaldırmak için,

Ama ömrün

Bizi doksan derece yatırdığı gün

Dünya elini uzatsa

Gömülür toprağa gömülüp giden...', 'Hepsine hamdolsun diyoruz Hamdetmesek elimizden ne gelir?  Şu günahkâr ömrümüz içinde Kâh düşüp,kâh kalkıp Geçinip gidiyoruz. Şİmdi düşsek d...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/doksan-derece-dusus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülen Yanım', 'gulen-yanim-ayfer-ersoy-rh0zw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Tutulur bir an gözleri 

Hayale ne hacet gerçeğin ta kendisi 

Umudun - mutluluğun müjdecisi 

Dediğin an dilin.......

Başlar kanamaya sözlerin.... 

Mısraların yetersiz.... 

Yüreğin çaresiz..... 

Kılı kırk yarar da..... bulduğunu sandığın an kaybettiğin... 

Gün doğar... 

Gözlerin bakar..... 

Ve içinden bir ses..... işte huzurum.... 

Uyandım yanında.... bir çift gülen göz... 

Gülen yanım.................. yalnızlığım.

20/07/2005', 'Tutulur bir an gözleri  Hayale ne hacet gerçeğin ta kendisi  Umudun - mutluluğun müjdecisi  Dediğin an dilin....... Başlar kanamaya sözlerin...', ARRAY['Türk Edebiyatı','Şiir','Ayfer Ersoy']::text[], 8.5, '{"poet":"Ayfer Ersoy","poet_slug":"ayfer-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/gulen-yanim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güle Kanatlanmak', 'gule-kanatlanmak-erhan-tigli-yksx9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'GÜLE KANATLANMAK

Çıktık gül-diken yokuşarı

sevdanın güzelliğine ulaşmak sevdasiyle

çektik sonunda tutkumuzun bayrağını

mutluluk burcuna

Güle kanatlandık canım

özveriyle dirençle el ele gönül gönüle

Tomurcuklarımızda özgürlük

doru taylarla dört nala

ırmaklara büründük taa derinden

özlemle umut aydınlattı ufkumuzu

kuşlar kucakladı çabamızı cıvıl cıvıl

Güle kanatlandık canım

Sıyrıldık dikenimizden.', 'GÜLE KANATLANMAK Çıktık gül-diken yokuşarı sevdanın güzelliğine ulaşmak sevdasiyle çektik sonunda tutkumuzun bayrağını mutluluk burcuna Güle...', ARRAY['Türk Edebiyatı','Şiir','Erhan Tığlı']::text[], 8.5, '{"poet":"Erhan Tığlı","poet_slug":"erhan-tigli","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/gule-kanatlanmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzak Kader', 'uzak-kader-ayfer-ersoy-wpqwi', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bazen susarım söyleyemem 

Dilim varmaz 

Şarkılar mırıldanırım belki bir çare 

Ormanda kaybolurum en çok bildiğim patika yolda 

Susarım bazen 

Bazen şarkılar mırıldanırım.......... 

Kaybolurum.......... 

Patika yolda........... 

Oramanda..... 

Karanlıkta.............. 

Bir şey uzak bana............. 

Çok yakınımda......... 

Ruhuma dokunduğu anda........... 

ağlarım................

21/07/2005', 'Bazen susarım söyleyemem  Dilim varmaz  Şarkılar mırıldanırım belki bir çare  Ormanda kaybolurum en çok bildiğim patika yolda  Susarım bazen...', ARRAY['Türk Edebiyatı','Şiir','Ayfer Ersoy']::text[], 8.5, '{"poet":"Ayfer Ersoy","poet_slug":"ayfer-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/uzak-kader-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Delikanlı', 'delikanli-sair-oksamen-n13e2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Delikanlı yüreğim                                                                    

Seni sevsede söylemeyecek kadar

İstesede artık

Sana dokunmayacak kadar

Sen geç kaldın

Geç anladın sevmeyi

İstiyorsun beni fazlasıyla 

Ama nafile

Gözyaşlarını

Pişmanlığını

Yakarışlarını 

Görüpte gidecek kadar

YAR

Delikanlı Yüreğim', 'Delikanlı yüreğim                                                                     Seni sevsede söylemeyecek kadar İstesede artık Sana do...', ARRAY['Türk Edebiyatı','Şiir','Şair Oksamen']::text[], 8.5, '{"poet":"Şair Oksamen","poet_slug":"sair-oksamen","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/delikanli-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana...4', 'sana-4-ayfer-ersoy-b28ai', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bazen beklemek... sevmek... 

Nefret etmek beklemek... 

Tek tek bir parçanı alıp götürmek........beklemek... 

Bekledikçe özlemi çoğalan.. çoğaldıkça yalnızlığı artan..... 

Ve her gün biraz daha umut çiçekleriyle bahçesini donatan... 

Bilirsin.. 

Beklemekle bekleyebilmek arası uçurum...........

12/09/2005', 'Bazen beklemek... sevmek...  Nefret etmek beklemek...  Tek tek bir parçanı alıp götürmek........beklemek...  Bekledikçe özlemi çoğalan.. çoğ...', ARRAY['Türk Edebiyatı','Şiir','Ayfer Ersoy']::text[], 8.5, '{"poet":"Ayfer Ersoy","poet_slug":"ayfer-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sana-4-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelecekmisin', 'gelecekmisin-taner-yusuf-bul-nv735', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gün doğduğunda

bu kahpe kentin semalarına 

kızıla döndüğünde uykusuzluğum

gelecekmisin

söyle bekleyeyimmi

yaşamak için tüm yorgunluklarını hayatın

kahrını bu tatsız çehrelerin

tüm yabancı dosyluk

ve tüm şerefsizliklerin

üstesinden geleyimmi söyle 

gelecekmisin

kızdınsa kızdın

yeter umutsuzluk deryasında boğulmuşluğum

beş yıl sonra de beklemezsem kızılay meydanında insan değilim

yeterki bileyim

gelecekmisin

ölmem şerefsizim varsa bir ümit

bakarım kendime yokluğunda şaşar kalırsın

bu yaşıma rağmen bekletirim kapımda azraili daha bir yirmi sene

ne olur bir kez olsun

gelecekmisin

hadi öldüm diyelim

mezarıma herkes gittikten sonra

hakkını helal etmek için gelecekmisin

aralık 2005', 'Gün doğduğunda bu kahpe kentin semalarına  kızıla döndüğünde uykusuzluğum gelecekmisin söyle bekleyeyimmi yaşamak için tüm yorgunluklarını h...', ARRAY['Türk Edebiyatı','Şiir','Taner Yusuf Bul']::text[], 8.5, '{"poet":"Taner Yusuf Bul","poet_slug":"taner-yusuf-bul","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/gelecekmisin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Masal Gecesi', 'masal-gecesi-hasan-can-29kht', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir masal gecesi gibiydi...

Gözümde oyuncak elleriyle bir çocuk,

İçimde narin dokunuşlu sevgili,

Ruhumda bir rüzgar esiyordu.

Kırık bir pencere kenarında,

Farkında olmadan fısıldadığım şarkılarla,

Yorgun bakışlarımla,

Bakıyordum gökyüzünde parlayan yıldızlara.

Yada bir hayal gecesiydi,

Görmediğim onca şeydi gördüklerim,

Sinemada yanyana, omuz omuza,

Göz göze, dudak dudağa ikimiz...

Ellerin narin... 

Tenime dokunduğunda ürperirdim.

Sımsıkı sarardın beni, sırılsıklam olurdum,

Sırılsıklam aşık yeniden,

Hep yenilerdi kendini aşk...

Sonsuz bir uykuydu belkide,

Uyanmadığım sürece hep sen vardın,

Düşlerimde sınırsız bir aşktın sen.

Aniden bir uyanışla koptum senden,

Masal gecemi terkettin,

Sonsuzdu uykum ve uyandım,

Herşey bitti...', 'Bir masal gecesi gibiydi... Gözümde oyuncak elleriyle bir çocuk, İçimde narin dokunuşlu sevgili, Ruhumda bir rüzgar esiyordu. Kırık bir penc...', ARRAY['Türk Edebiyatı','Şiir','Hasan Can']::text[], 8.5, '{"poet":"Hasan Can","poet_slug":"hasan-can","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/masal-gecesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üzüm Yalnızlığı', 'uzum-yalnizligi-sair-psiyah-ypnkb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'benim yalnızlığım 

üzüm yalnızlığı

gecelerde buz gibi yenilen 

tek salkım kaldığında

hep terkedilen', 'benim yalnızlığım  üzüm yalnızlığı gecelerde buz gibi yenilen  tek salkım kaldığında hep terkedilen...', ARRAY['Türk Edebiyatı','Şiir','Şair Psiyah']::text[], 8.5, '{"poet":"Şair Psiyah","poet_slug":"sair-psiyah","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/uzum-yalnizligi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umuttan İnsan', 'umuttan-i-nsan-alper-kuruk-fqr3j', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir rüya ertesi düşünceler

Tatlı anılarca gönülde takıntı,

Gündüz ve geceler

Yokluğa taraf bir akıntı.

Coşma gönlüm coşma

Bak yine oluyor akşam

Karanlıklara kızacak sen değil misin? 

Sen gücenmiyecek misin yine kaderine? 

Umut kur geleceğin üzerine

Bekâr yatağında kimsesiz

İnan olamıyorsunuz bir türlü

Sen umutsuz

Umut sensiz...

Tüm insanların ruhu var

Sende ruh yerine umut

Ki ondan yaşıyorsun

Umutlu dünyalarda...

Umutlu rüyalarda...', 'Bir rüya ertesi düşünceler Tatlı anılarca gönülde takıntı, Gündüz ve geceler Yokluğa taraf bir akıntı. Coşma gönlüm coşma Bak yine oluyor ak...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/umuttan-insan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlatamadım', 'anlatamadim-yucel-karakilic-pz791', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Demek ki sevenler deli oluyor,

Aşkınla mecnuna çıktı da adım.

Seni sevdiğimi, herkes biliyor,

Bir sana sevdamı, anlatamadım.

Sanki hafızama çivi çakıldı,

Ben seni bir türlü unutamadım.

Sözler boğazıma geldi takıldı,

Bir sana sevdamı, anlatamadım.

Ben ben de değilim, aklım dağıldı,

Kimi sersem sandı, kimi bunadım.

Görenler acıya yasa boğuldu,

Bir sana sevdamı, anlatamadım.

İsyanımı sağır sultan duyarken,

Sana ulaşmadı benim feryadım.

Uğrunda koskoca hayat kayarken,

Bir sana sevdamı, anlatamadım.

Dizlerim, gövdemi taşımaz oldu,

Felç oldu, tutmuyor kolum kanadım.

Duyanlar, saçını başını yoldu,

Bir sana sevdamı, anlatamadım.

Her bir yerde senin izini sürdüm,

Sana doğru gitti attığım adım.

Her gece rüyamda canımı verdim,

Bir sana sevdamı, anlatamadım.

İsmin, dudağımda teshibe döndü,

Erenlere dua oldu feryadım.

Kafir, iman edip, dinime döndü,

Bir sana sevdamı, anlatamadım.', 'Demek ki sevenler deli oluyor, Aşkınla mecnuna çıktı da adım. Seni sevdiğimi, herkes biliyor, Bir sana sevdamı, anlatamadım. Sanki hafızama ...', ARRAY['Türk Edebiyatı','Şiir','Yücel Karakılıç']::text[], 8.5, '{"poet":"Yücel Karakılıç","poet_slug":"yucel-karakilic","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/anlatamadim-34-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Senle Sensiz Sohbetlerde-2', 'sana-senle-sensiz-sohbetlerde-2-ayfer-ersoy-6mydh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '-1-

Dalıp gitmek gece bakışlarının içine 

Maviliğinle yıkanmak 

Yoğrulmak gözyaşlarınla 

..... Sessizce..........................11/10/2005

-2-

Şu sessizlik 

İçerimdeki serinlik 

Ve avuçlarımda alev 

Ruhum yarım 

Umudum ay ışığında saklı yine 

Titriyor bedenim 

Yağmura hasret..........................26/10/2005

-3-

Günaydın 

Güne gülen yanımla başladım günaydın 

Güne sözümle başladım günaydın 

Güne neşemle başladım günaydın 

Güne rengarenk başladım günaydın 

Güne (yine sensiz)  ama seninle başladım günaydın.......02/11/2005', '-1- Dalıp gitmek gece bakışlarının içine  Maviliğinle yıkanmak  Yoğrulmak gözyaşlarınla  ..... Sessizce..........................11/10/2005 ...', ARRAY['Türk Edebiyatı','Şiir','Ayfer Ersoy']::text[], 8.5, '{"poet":"Ayfer Ersoy","poet_slug":"ayfer-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sana-senle-sensiz-sohbetlerde-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karanfil', 'karanfil-erhan-tigli-07pjd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'KARANFİL

Baktım gözündeydi karanfil

bir özlem yakamozlanıyordu

gözlerinin denizinde

Semiramisin asma bahçelerini gezdim

bakışlarıyla  bahar yeli gibi

Tuttum elindeydi karanfil

ışıttı benliğimi sımsıcak

tepeden tırnağa apak oldum

silindi yalnızlığımın katran geceleri

Öptüm dudaklarındaydı karanfil

çiçeklendimdal dal

özünün bereketiyle

güzellik meyvaya durdu

kuşlar kondu gönül tellerime

Açtım göğsündeydi karanfil

Aşkım şiir oldu.', 'KARANFİL Baktım gözündeydi karanfil bir özlem yakamozlanıyordu gözlerinin denizinde Semiramisin asma bahçelerini gezdim bakışlarıyla  bahar ...', ARRAY['Türk Edebiyatı','Şiir','Erhan Tığlı']::text[], 8.5, '{"poet":"Erhan Tığlı","poet_slug":"erhan-tigli","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/karanfil-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Gece', 'bu-gece-sair-oksamen-pwbab', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu gece döşeğim ıssız sokaklar

Yorganım sema-semayı kaplayan yıldızlar

Sensizliğimle üşüyorum çekiyorum yıldızları üzerime

Acıyan kalbimi bi nefeslik izmaritle bastırıyorum

Şimdi bana oldu sokak çocukları arkadaş

Hepsinin yüreğinde bi yangın ortada yanan bi ateş

Bi kedi mi   den ses veriyor miyavlıyor

Hep beraber okuyoruz şarkıları olduk kardeş

Anam yok,babam yok yalnızlık korkusu çöktü üstüme

Kimsem yok yarim yok yalnızlık korkusu çöktü üstüme

Bir kulunu çok sevdim o beni hiç sevmiyor

Kalbimi ona verdim artık geri vermiyor

Şarkılar bitmez,dilimizde hep söylenir

Bize geceler yetmez,sabahlar olur

Kader yine kişiler için ağlarını örer 

Bizi bilinmeyen yarılara sürükler durur

Kimbilir hayatımız nasıl olacak

Gelmesi gerekenler geliverse

Ümitler gerçekleşse

Herkesin hayatına güneş doğacak

İnsanlar mutlu

Yaşam daha da güzel olacak', 'Bu gece döşeğim ıssız sokaklar Yorganım sema-semayı kaplayan yıldızlar Sensizliğimle üşüyorum çekiyorum yıldızları üzerime Acıyan kalbimi bi...', ARRAY['Türk Edebiyatı','Şiir','Şair Oksamen']::text[], 8.5, '{"poet":"Şair Oksamen","poet_slug":"sair-oksamen","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/bu-gece-175-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilek', 'dilek-yucel-karakilic-57bqj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yıllar yılı, bu gün için yaşadım,

Şükür, kabul oldu tutduğum dilek.,

Bir seven bulmaktı, en son muradım,

Demek sabrın sonu selamet Dilek.

Yalnızlığa dosttum, neşeye kırgın,

Mutluluğa küstüm, huzura dargın,

Benliğim tutsaktı, yüreğim sürgün,

Bitti, sona erdi esaret Dilek.

Gel, sen ve ben varız bu kainatta,

Ayrılık sözü yok bizim lügatta,

Doludizgin, bundan böyle hayatta,

Ne yaşarsak, hayra alamet Dilek.

Gökkuşağı gibi, sevdanın rengi,

Feth etti ruhumu, sardı ahengi,

Gönlüme hediye ettiğin sevgi,

Dünya da en kutsal emanet Dilek.

Aşktan daha büyük lütuf bekleme,

Aşktan başka duygu kalbe yükleme,

Aşk denince, cennet gelir aklıma,

Seni sevmek, bana ibadet Dilek.

Sultanım, seni çok seviyorum çok,

Senin yaydan çıktı, bağrımda ki ok,

Geç kavuştum ama, tez yitirmek yok,

Senden geçmem, kopsa kıyamet Dilek.', 'Yıllar yılı, bu gün için yaşadım, Şükür, kabul oldu tutduğum dilek., Bir seven bulmaktı, en son muradım, Demek sabrın sonu selamet Dilek. Ya...', ARRAY['Türk Edebiyatı','Şiir','Yücel Karakılıç']::text[], 8.5, '{"poet":"Yücel Karakılıç","poet_slug":"yucel-karakilic","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/dilek-109-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'M e l e ğ i m', 'm-e-l-e-g-i-m-belgin-erturk-nm90h', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Beni dün gece bir melek,

şefkatle okşadı.

Bir gülüş bıraktı gözlerime.

Kömür karası saçlarımın arasına

aşkı serpip,

yeni sayfaları 

koyuverdi yastığıma.

Tan ağardığında,

aşka hasret gönlümün

mayası tutmuştu.

Hiç sabah olmasın,

şafak söktüğü vakit

her şey rüya olmasın

diye,

uykulardayım halen..! 

22.12.2005 01.00', 'Beni dün gece bir melek, şefkatle okşadı. Bir gülüş bıraktı gözlerime. Kömür karası saçlarımın arasına aşkı serpip, yeni sayfaları  koyuverd...', ARRAY['Türk Edebiyatı','Şiir','Belgin Erturk']::text[], 8.5, '{"poet":"Belgin Erturk","poet_slug":"belgin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/m-e-l-e-g-i-m-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sersefil', 'sersefil-taner-yusuf-bul-oiiq4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Uzak bir kentin

ucuz bir lokantasında

belki darmadağın olmuş,yapayanlız

hasta bir yürekle

sersefilsem

ümitsiz bir durağanlıkla bekliyosam

sarılmıyorsam yaşamın güzelliklerine

uzaksam kendime,sana

boğulmuşsam efkara

içimde kopuyorsa en azgın fırtınalar

sersefilsem

iyice küçük düşmüşsem

maskara olmuşsam köpeğe,kurda,çakala

tanıyamıyorsa dostlarım

hatta hiçkimsem yoksa hatrımı bilen

sersefilsem

yani sersefil olmuşsam

en açık dille sefilsem

herkes bilsinki

doğrudur', 'Uzak bir kentin ucuz bir lokantasında belki darmadağın olmuş,yapayanlız hasta bir yürekle sersefilsem ümitsiz bir durağanlıkla bekliyosam sa...', ARRAY['Türk Edebiyatı','Şiir','Taner Yusuf Bul']::text[], 8.5, '{"poet":"Taner Yusuf Bul","poet_slug":"taner-yusuf-bul","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sersefil-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cenge Gidiyorum Cenge', 'cenge-gidiyorum-cenge-mehmet-akif-gulhan-pceyz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yıkılmaz duvarlar sarmış etrafımı

Bu ne yükseklik, güneş bile görünmüyor

Gök yüzünü de kara bir bulut kaplamış

Gece mi gündüz mü şimdi bilinmiyor

Ben ise kuşanmışım zırhlarımı

Duvarların ardına yapılan kaçıncı seferim

Her defasında yenik düştüm

Her defasında bitap,harap kaldım

Bu defa yanıma müttefik ordular aldım

Bölük bölük umutsuzluk askerleri

Bir sürü vefasızlık neferleri var

Birkaç manga hayırsızlık 

Bir tümen aldatılmışlık

Kalbi kırıklar zaten hiç ayrılmazlar yanımdan

Kuşanmışız birde hepimiz umutsuz beklemelerle

Nicedir ölümü de sarmışım belime cephane diye

Mehmet Akif Gülhan 22.12.2005 Saat 17.54', 'Yıkılmaz duvarlar sarmış etrafımı Bu ne yükseklik, güneş bile görünmüyor Gök yüzünü de kara bir bulut kaplamış Gece mi gündüz mü şimdi bilin...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Gülhan']::text[], 8.5, '{"poet":"Mehmet Akif Gülhan","poet_slug":"mehmet-akif-gulhan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/cenge-gidiyorum-cenge-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen...-2-', 'sen-2-alper-kuruk-j0vq8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Zevkin tükenmeden bildir

Zevk doğuran aşk

Bilsen ne güzeldir...

Rüyalarımı

İstediğin gibi düzenle

Şeytanı da çıkar istersen

Yeter ki kalasın sen...

İstemiyorum artık geceleri

Göz kapaklarıma dökülsün siyah  saçların,

Şimdi sarhoş etsin öpüşlerin

Ve ayıltsın yarın.

Varlığım varlığında erisin

Yitirip yitirip

Sende bulmalıyım kendimi,

Sen bana o kadar yakın

O kadar yakın ruhumdan da

Daha berisin...', 'Zevkin tükenmeden bildir Zevk doğuran aşk Bilsen ne güzeldir... Rüyalarımı İstediğin gibi düzenle Şeytanı da çıkar istersen Yeter ki kalasın...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sen-2-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Olan', 'sana-olan-sair-oksamen-o17l0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sana olan aşkımın özü 

Yürekte saklıdır bilemezsin bunu

Kalbimin bu kaçıncı sözü

Boşver bu sözleri kalp unutamazsın onu

Önce sevgisini sezersin

Sonra dile gelen sözleri dinlersin

Birkaç dokunuş,bir öpüş kendinden geçersin

Böylece canım maneviyata girersin

Aşk olur yakaladığın

Tanrı olur taptığın

Her dokunuş bir ibadete girer

Kendini birşeyden sayarsın', 'Sana olan aşkımın özü  Yürekte saklıdır bilemezsin bunu Kalbimin bu kaçıncı sözü Boşver bu sözleri kalp unutamazsın onu Önce sevgisini sezer...', ARRAY['Türk Edebiyatı','Şiir','Şair Oksamen']::text[], 8.5, '{"poet":"Şair Oksamen","poet_slug":"sair-oksamen","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sana-olan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Neden Sevdin Söyle', 'beni-neden-sevdin-soyle-eyup-selahattin-dalkiran-qxep4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sormak istiyorum sana

Beni niye sevdin? 

Ne günlerden gelmiştin? 

Anlatırmısın? 

Çaresizmiydin? ,Sevgisizmiydin? 

Yine sormak istiyorum

Beni niye sevdin? 

Tanıştık,sevdik,seviştik

kavga ettik yalan söyledik.

Beni sevmende ki sebep neydi? 

Gerçekten söylermisin bana? 

Neydi çıkarımız birbirimizden? 

Haydi bana söyle? 

Neden bu kadar sevdik birbirimizi? 

Eğer sorarsan bana

Ben sade bir aşk için

Seni bilemem yinede ne olursun

Beni gerçekten niye sevdin? 

Yoksa baharın sarhoşluğu

Seni vurdudamı beni sevdin? 

Hadi ne olursun söyle

Beni niye sevdin? 

Eğer doğruysa

Ölürcesine...', 'Sormak istiyorum sana Beni niye sevdin?  Ne günlerden gelmiştin?  Anlatırmısın?  Çaresizmiydin? ,Sevgisizmiydin?  Yine sormak istiyorum Beni...', ARRAY['Türk Edebiyatı','Şiir','Eyüp Selahattin Dalkıran']::text[], 8.5, '{"poet":"Eyüp Selahattin Dalkıran","poet_slug":"eyup-selahattin-dalkiran","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/beni-neden-sevdin-soyle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi nerde', 'sevgi-nerde-erhan-tigli-lo3d7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'SEVGİ NERDE

Sevgi nerde

güvendiğimiz dağlara yağan

karı küremeye gitti.

Sevgi nerde

aramızdaki duvarları yıkmaya

köprüler kurmaya gitti.

Sevgi nerde

ezilen otları yeşertmeye

sökülen çiçekleri dikmeye gitti

Sevgi nerde

dostluğun tozlarını silmeye

hoşgörünün kirlerini temizlemeye gitti

Sevgi nerde

Bencilliğimiz,çıkarcılığımız

yedi bitirdi umudu özlemi

kim vurduya gitti...', 'SEVGİ NERDE Sevgi nerde güvendiğimiz dağlara yağan karı küremeye gitti. Sevgi nerde aramızdaki duvarları yıkmaya köprüler kurmaya gitti. Sev...', ARRAY['Türk Edebiyatı','Şiir','Erhan Tığlı']::text[], 8.5, '{"poet":"Erhan Tığlı","poet_slug":"erhan-tigli","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sevgi-nerde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin için inan', 'senin-icin-inan-eyup-selahattin-dalkiran-b44yk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu kadar ızdırap çektikten sonra

Hasret zehiri içtikten sonra

Ne çıkar,bu iş geçtikten sonra

Yani sevecek gücüm kalmadı.

Kendimden bile düşkünüm sana

Acıdan başka ne verdin bana

Sonunda dünyayı yıktın başıma

Hayatta gülecek gücüm kalmadı.

Yağmur yağarken dolu başladı

Sen senidin eller beni taşladı

Sanki kuru topraklar avuçladı beni

Yandım kül oldum.', 'Bu kadar ızdırap çektikten sonra Hasret zehiri içtikten sonra Ne çıkar,bu iş geçtikten sonra Yani sevecek gücüm kalmadı. Kendimden bile düşk...', ARRAY['Türk Edebiyatı','Şiir','Eyüp Selahattin Dalkıran']::text[], 8.5, '{"poet":"Eyüp Selahattin Dalkıran","poet_slug":"eyup-selahattin-dalkiran","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/senin-icin-inan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Can İçinde', 'can-i-cinde-sair-oksamen-e786m', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Can içinde canan

Bir seni sevdim inan

Gözlerimden bu yansıyan

Sana karşı olan sevdam

Kalp içinde kor sevdan

İçin için yanıp bedeni saran

Beni böyle deli divane yapan

Sana karşı olan sevdam

Dilimde türkü olan

İçimde ağıt yakan

Gözlerime bu dolan

Sana karşı olan sevdam

Tutmuyor ki elim yazam

Yorgun yürek,dil susan

Beni yaşayan ölü yapan

Sana karşı olan sevdam', 'Can içinde canan Bir seni sevdim inan Gözlerimden bu yansıyan Sana karşı olan sevdam Kalp içinde kor sevdan İçin için yanıp bedeni saran Ben...', ARRAY['Türk Edebiyatı','Şiir','Şair Oksamen']::text[], 8.5, '{"poet":"Şair Oksamen","poet_slug":"sair-oksamen","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/can-icinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdalım', 'sevdalim-eyup-selahattin-dalkiran-xb60t', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Baktık ya gözlerimizle gözlerimize

Öptük ya dudaklarımızla dudaklarımızı

El ele tuttuk ya ellerimizi

Tenlerimiz tenlerimizi tanıdı ya

Sevdalı tutkular için.

Çıkmazlar,açmazlar artık

Vız gelir tırıs gider olaylar.

Bu günden sonra odana kokum sinecek

Ben taşıyacağım dağlarda yetişen

Mis kokulu dağ çiçekleri gibi teninin kokusunu.

Ne bir yalan ne bir yanlış olacaktır bu aşkta

Sevdalı tutkular için.', 'Baktık ya gözlerimizle gözlerimize Öptük ya dudaklarımızla dudaklarımızı El ele tuttuk ya ellerimizi Tenlerimiz tenlerimizi tanıdı ya Sevdal...', ARRAY['Türk Edebiyatı','Şiir','Eyüp Selahattin Dalkıran']::text[], 8.5, '{"poet":"Eyüp Selahattin Dalkıran","poet_slug":"eyup-selahattin-dalkiran","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sevdalim-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdi', 'sevdi-eyup-selahattin-dalkiran-h5tj9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bulutlar ağladı 

Rüzgarlar uludu 

Denizler kabardı

Ve benim yüreğim 

Hiç mi hiç böyle olmadı

Nedense

Ne ağladı

Ne uludu

Ne kabardı

Belki de benim yüreğimi

Gerçekten sevdi

Rastlantıları

Doğanın kendisi yaratır 

Nasıl bulutlar doğada ki

                      Rastlantılarla

Buluşup ağlıyorsa

Nasıl rüzgarlar doğada ki

                      Rastlantılarla

Buluşup uluyorsa

Nasıl denizler doğada ki

                      Rastlantılarla

Buluşup kabarıyorsa

Benim yüreğimde ki sevgiyi

Aşkı bir kenara ittiği zaman 

Bulutlar gibi ağlayabilir

Rüzgarlar gibi uluyabilir

Denizler gibi kabarabilir.', 'Bulutlar ağladı  Rüzgarlar uludu  Denizler kabardı Ve benim yüreğim  Hiç mi hiç böyle olmadı Nedense Ne ağladı Ne uludu Ne kabardı Belki de ...', ARRAY['Türk Edebiyatı','Şiir','Eyüp Selahattin Dalkıran']::text[], 8.5, '{"poet":"Eyüp Selahattin Dalkıran","poet_slug":"eyup-selahattin-dalkiran","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/sevdi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarmaşık', 'sarmasik-alper-kuruk-in7c4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Benden ne kaçarsın öyle

Sana birşey yapmadım ki? 

Seni çok seviyorsam

Kötü mü sanki? 

Yaklaş bana biraz

Ruhun yaklaşmazsa bile

Vücudun yaklaşsın.

Bak,sana birşey göstereceğim:

Bahçedeki kuru bir deyneğe

Sarılan sarmaşığı görüyor musun? 

Evet,sarmaşık...

O bile kuru bir deyneğe

Sarım sarım sarılmış

Belli ki âşık.

Gel seninle sarmaş-dolaş olalım

Sar beni kollarınla

Ben kupkuru değilim o deynek gibi

Başımda düşünceler,içimde aşk

Boynumda senin kolların var

Gözlerimde ışık.

Şuna da dikkat et sararken:

Ne erkekliğimi çiğne

Ne kadınlığını unut

Olma yılışık...', 'Benden ne kaçarsın öyle Sana birşey yapmadım ki?  Seni çok seviyorsam Kötü mü sanki?  Yaklaş bana biraz Ruhun yaklaşmazsa bile Vücudun yakla...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sarmasik-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mucize', 'mucize-yucel-karakilic-pkwi6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çok güzel tanıdım, çok güzel gördüm,

Senin gibisine rastlamadım ben.

Bir ömür yaşadım, tek güzel gördüm,

Senin gibisine rastlamadım ben.

Tabiatta, bin bir türlü hallerde,

Topraklarda, yapraklarda, güllerde,

Birbirine benzeyen tüm kullarda,

Senin gibisine rastalamadım ben.

Bırakmadım tepesini düzünü,

Bulamadım hiç bir yerde izini,

Adım adım dolaştığım yeryüzünü,

Senin gibisine rastlamadım ben.

Deryaların dalgasında koyunda,

Gökyüzünün yıldızında ayında,

Yüce Rab''bin güzellik sarayında,

Senin gibisine rastlamadım ben.

Benzerin yok senin bu kainatta,

Ne tarihte varsın, ne de lügatta,

A''dan, Z''ye kadara edebiyatta,

Senin gibisine rastlamadım ben.

Mucizesin, Allah''ın aleminde,

Bir meçhulsun, ozanın kelamında,

Yıllar yılı, şairin kaleminde,

Senin gibisine rastlamadım ben.', 'Çok güzel tanıdım, çok güzel gördüm, Senin gibisine rastlamadım ben. Bir ömür yaşadım, tek güzel gördüm, Senin gibisine rastlamadım ben. Tab...', ARRAY['Türk Edebiyatı','Şiir','Yücel Karakılıç']::text[], 8.5, '{"poet":"Yücel Karakılıç","poet_slug":"yucel-karakilic","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/mucize-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi içinde', 'sevgi-icinde-eyup-selahattin-dalkiran-m3v2o', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu gün bir ağlamaklıyım 

Basıncım sensin gülüm 

Damarlarımda dolaşan kan şaşırmış

Ne yana akacağını bilmiyor.

Sarhoş bir vaziyette.

Vücudum titriyor

Beynim kalk diyor yerinden

Git kapısına çık ulan dışarı deyip,

Ellerinden tutup o gözlerine bakarak

Ağlamaklı halimi gösterip

Ağlamalıyım yüzüne bakarak.

Derler erkekler ağlamaz

Pöh öyle bir ağlar ki

Hele aşıksa delice

Yüreği hep onun için çarpıyorsa 

Bu gün bir ağlamaklıyım,gülüm

İçim patlayacak gibi.

Kahr olasıca  aşk

Çırpındırıyor insanı

O ve gözleri olmayınca 

Dayanamıyor kendi kendine

Cehennem içinde insan,debelenip 

Yanar gibi oluyor.', 'Bu gün bir ağlamaklıyım  Basıncım sensin gülüm  Damarlarımda dolaşan kan şaşırmış Ne yana akacağını bilmiyor. Sarhoş bir vaziyette. Vücudum ...', ARRAY['Türk Edebiyatı','Şiir','Eyüp Selahattin Dalkıran']::text[], 8.5, '{"poet":"Eyüp Selahattin Dalkıran","poet_slug":"eyup-selahattin-dalkiran","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/sevgi-icinde-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgilim', 'sevgilim-eyup-selahattin-dalkiran-ntso6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Biz ikimiz 

Dudaklarımızla

Ellerimizle 

Gözlerimizle 

Günah mı taşıdık birbirimize 

Böyle zor bir ayrılık yaşadık

Bu yaşadığımız acı bundan mı 

SÖYLERMİSİN

ÖZGÜRLÜĞÜMÜN ADI OLAN

GÜNEŞİN KIZI.', 'Biz ikimiz  Dudaklarımızla Ellerimizle  Gözlerimizle  Günah mı taşıdık birbirimize  Böyle zor bir ayrılık yaşadık Bu yaşadığımız acı bundan ...', ARRAY['Türk Edebiyatı','Şiir','Eyüp Selahattin Dalkıran']::text[], 8.5, '{"poet":"Eyüp Selahattin Dalkıran","poet_slug":"eyup-selahattin-dalkiran","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sevgilim-93-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgin', 'sevgin-eyup-selahattin-dalkiran-zl0gu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir sonbahar daha geldi 

İnan seni silip atamadım gönlümden

Yağmurlar,şimşekler,gök gürlemeleri

Seni anımsatıyor.

Caddeler sokaklar sel içinde yüreğim gibi

Gözyaşım aktıkça içime 

Sonbahar sensiz yapraklar gibi

Sensiz içim kavrulmakta.

Neyi anlatabilirim ki olmuş bir sefer

Acı,sevgi,aşk,hüzün,gözyaşı

Hepsi birbirine karışmış çözülmez sorun olmuş

Acı günler gibi sevgim.', 'Bir sonbahar daha geldi  İnan seni silip atamadım gönlümden Yağmurlar,şimşekler,gök gürlemeleri Seni anımsatıyor. Caddeler sokaklar sel için...', ARRAY['Türk Edebiyatı','Şiir','Eyüp Selahattin Dalkıran']::text[], 8.5, '{"poet":"Eyüp Selahattin Dalkıran","poet_slug":"eyup-selahattin-dalkiran","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sevgin-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Azrail''le Başbaşa', 'azrail-le-basbasa-alper-kuruk-z0wl1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ne o? 

Sen mi geldin? 

Kimsin? 

Tanıyamadım ben seni.

Dostlarım evime gelirken

Ya kapımı çalar ya penceremi

Bana bir haber verirler.

Duymadım senin geldiğini.

Hastayım kaç zamandır

Yatıyorum yalnız

Dostlardan bir haber yok...

Bir sen varsın gelen.

Ama,in misin,cin misin? 

Dilim varmıyor söylemeye

Sen Azrail''sin...

Biliyorum canımı almaya geldin

Yalvarırım canımı alma! 

Daha gencim...

Yok! yok! olmaz 

Sözüme bakma benim

Can tadı böyle söyletir insanı...

Yalnızca genç olan ben değilim ya! 

O kadar öldürdüğün

Gencin de vardı canı...

Sen de bir emir kulusun

Gel işini bitir...

Ne oldu? 

Gidiyor musun? 

Ümidini kestin mi benden? 

Fakat,biliyorum birgün yine geleceksin

Yalnız,o gelişinde odama

Haber ver de gir

Çünkü elin dolu döneceksin...', 'Ne o?  Sen mi geldin?  Kimsin?  Tanıyamadım ben seni. Dostlarım evime gelirken Ya kapımı çalar ya penceremi Bana bir haber verirler. Duymadı...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/azrail-le-basbasa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevginin kıskançlığı', 'sevginin-kiskancligi-eyup-selahattin-dalkiran-8tjhe', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sana türkü tadında 

Şiirler yazmak

Kalbimde sevgiler yazmak

Güzel oluyor

Bir anlayabilsen.

Kıskanıyorum işte yine onunlasın

Kıskanıyorum işte yine onunla el elesin

Ağrıma gidiyor alaca karanlığın içinde

Yıldızlara isyan ediyorum

Başlarınızda yıldızların parlamasından.

İsyan ediyorum

Öpülen dudakların için

Kahrediyor alaca karanlığın aydınlığında.', 'Sana türkü tadında  Şiirler yazmak Kalbimde sevgiler yazmak Güzel oluyor Bir anlayabilsen. Kıskanıyorum işte yine onunlasın Kıskanıyorum işt...', ARRAY['Türk Edebiyatı','Şiir','Eyüp Selahattin Dalkıran']::text[], 8.5, '{"poet":"Eyüp Selahattin Dalkıran","poet_slug":"eyup-selahattin-dalkiran","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sevginin-kiskancligi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayalimdesin', 'hayalimdesin-eyup-selahattin-dalkiran-uxhk8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen benim en gizli yanımsın

Sevinçlerin,mutlulukların dili

Her an

Beni gören

Her an 

Beni duyan

Anlayansın.

   Hiç dokunulmamış yanımsın

   Gizli ırmakların şırıltısıyla beslenen

   En kahraman yanımsın

   Sevdaların uzağındadır tezgahım.

   En yakınıma uzatamadığım elimsin

   Sevgimin sana uzandığı 

   Ve hiç kimsenin bilmediği 

   SEVGİLİMSİN

   OLSUN YANIMDASIN YA

   SENİ GÖRMEM BİLE BANA YETER.', 'Sen benim en gizli yanımsın Sevinçlerin,mutlulukların dili Her an Beni gören Her an  Beni duyan Anlayansın.    Hiç dokunulmamış yanımsın    ...', ARRAY['Türk Edebiyatı','Şiir','Eyüp Selahattin Dalkıran']::text[], 8.5, '{"poet":"Eyüp Selahattin Dalkıran","poet_slug":"eyup-selahattin-dalkiran","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/hayalimdesin-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ortaköy Sahilindelerdi', 'ortakoy-sahilindelerdi-hasan-can-krere', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kederli bir adam,

Bağışlanmak isteyen bir kadın,

Ortaköy sahilindelerdi.

Adam isyankardı kaderine,

Onca zaman sonramı geldin der gibi,

Birşeyler söylendi,

Elini kaldırdı vuracak gibi,

İki damla düştü gözlerinden,

Yumruk elini cemine soktu sonra.

Kadının yüzündeki ifade hiç değişmiyordu,

Hep aynı sözleri tekrarlıyordu,

Affet beni, yalvarır gibi ezik bir şekilde.

Adamın sevgisi derindi,

Ne git diyordu nede kal,

Acılı bir yüz ifadesiyle döndü kadına,

Hafif gülümsedi,

Ve seni affettim dedi.

Kadın belkide,

Hayatının en mutlu dakikalarını yaşıyordu,

Ama bir anlık sevinçti onunkisi,

Adam son sözünü bitirmeden,

Umutlu bir gülümsemede bulundu kadın.

Ve adam son sözünü söylüyordu,

Seni affettim, şimdi beni kaderime terket,

Yalnızlığıma terket ve git,

Dedi ve arkasını döndü.

Kadın diyecek hiçbir şey bulamadı,

Ve oradan uzaklaşmaya başladı...

Kaderine yenik düşmüş bir adam,

Ve onu yalnızlığına terkeden kadın,

Ortaköy sahilindelerdi,

Deniz durgundu,

Ve herşey bitmişti...', 'Kederli bir adam, Bağışlanmak isteyen bir kadın, Ortaköy sahilindelerdi. Adam isyankardı kaderine, Onca zaman sonramı geldin der gibi, Birşe...', ARRAY['Türk Edebiyatı','Şiir','Hasan Can']::text[], 8.5, '{"poet":"Hasan Can","poet_slug":"hasan-can","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/ortakoy-sahilindelerdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hani Söz Vermiştin', 'hani-soz-vermistin-emre-saricicek-4v0kp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hani söz vermiştin, beni sevecektin.? 

Yokluğumda, hep beni özleyecektin.? 

Hani beni, yüreğine ekleyecektin.? 

Hani beni, hiç incitmeyecektin.? 

Hani aşkımız, sonsuza kadar sürecekti.? 

Hani bizi, ancak, ölüm ayırırdı.? 

Hani ben senin, ayrılmaz bir parçandım.? 

Hani beni, ölümsüz, bir aşkla seviyordun.? 

Hani nerde kaldı, o sevişlerin.? 

Hani nerde o, güzel gülüşlerin.? 

Hani ben nereye gidersem, gelecektin.? 

Artık çok geç, biliyorum, gelmeyeceksin...', 'Hani söz vermiştin, beni sevecektin.?  Yokluğumda, hep beni özleyecektin.?  Hani beni, yüreğine ekleyecektin.?  Hani beni, hiç incitmeyecekt...', ARRAY['Türk Edebiyatı','Şiir','Emre Sarıçiçek']::text[], 8.5, '{"poet":"Emre Sarıçiçek","poet_slug":"emre-saricicek","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hani-soz-vermistin-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğimdesin', 'yuregimdesin-birsen-ates-vj349', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'hüzün sinmiş gözlerime

yüreğimde de acı

hüzün yağmurları

akıyor avuçlarımdan

seni düşünüyorum

üşüyorum

duygularım burada

mantığım nerede

bilmiyorum

yaşamın

çıkmaz sokaklarındayım

sözcüklerim hasrete bulanmış 

intiharında mavilerim

üşüyorum

sarılıyorum düşlerime

ısınıyorum

uzaklardan çıkıp gelsen

ah bir gelebilsen

biliyor musun ben seni

hiç unutmadım

her daim yüreğimdesin… 

22.12.05', 'hüzün sinmiş gözlerime yüreğimde de acı hüzün yağmurları akıyor avuçlarımdan seni düşünüyorum üşüyorum duygularım burada mantığım nerede bil...', ARRAY['Türk Edebiyatı','Şiir','Birsen Ateş']::text[], 8.5, '{"poet":"Birsen Ateş","poet_slug":"birsen-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/yuregimdesin-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Değil', 'son-degil-birsen-ates-vg53w', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'hep derdim

erken daha ölümü öpme

bilmezdim ki

emir büyük yerden

oyun gibiydi yaşamak

zannederdim sırayla

yaşanır ölüm

her an her yerde

nefes kadar yakınmış

anlamadık

korkma çocuk

son değil başlangıç

yeter ki arınmalı

gelip öpse de ölüm

hazır olmalı

22.12.05', 'hep derdim erken daha ölümü öpme bilmezdim ki emir büyük yerden oyun gibiydi yaşamak zannederdim sırayla yaşanır ölüm her an her yerde nefes...', ARRAY['Türk Edebiyatı','Şiir','Birsen Ateş']::text[], 8.5, '{"poet":"Birsen Ateş","poet_slug":"birsen-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/son-degil-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öcümü alacağım senden', 'ocumu-alacagim-senden-sair-gaddar-16-1k7ez', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Birgün mutlaka birgün,

Öcümü alacağım senden,

Gözlerin durduramayacak beni,

Bırakıpta gittin ya beni,

Mutlaka öcümü alacağım senden.

...

Hani o kahpe kursunlarla geldin ya,

Hani o masummuş gözlerinle vurdun ya,

Sonrada çekip gittin ya,

Beni benden ettin ya,

Öcümü senden alacağım.

...

Uzun dipsiz kuyulara ittin,

Dertlerle bırakıp gittin,

Seni sevdiğime pişman ettin,

Mutlaka öcümü alacağım senden.

...

Fırtına olacağım, gözlerini yaşartan,

Hancer olacağım, yüreğinden delen,

Güneş olacağım, yanı başında seni eriten,

Ama mutlaka öcümü alacağım senden.

...

Kör sakin karanlıkta kaldım,

Günlerce perişan açıkta kaldim,

Yüreğimde aşkın, bide onu yaşadım,

İnan öcümü alacağım senden.

...

Geleceğim birgün ap ayrı adeta yeni,

Durduramayacaksın beni,

Mutluluktan mahrum edeceğim seni,

Ancak ozaman anlarsın beni,

Mutlaka birgün,

Öcümü alacağım senden.

...

Sormadın beni, anmayacağım seni,

Beni mahfettin, haykırmayacağım seni,

Girip te ruhuma aldın ya beni,

Öcümü alacağım senden.

...

Korkma inletmeyeceğim,

Haykırmayacaksın,

Ama benim gibi,

Tadacaksın aşk acisini.

Yüregin parcalanır,

Gözlerin kan dolduğun da,

Kalbinin sevilmeye ihtiyacı,

Ellerin ellere muhtaç

Olacak...

Ne dost ne eş,

Kimsen yok olmayacak,

Seni sana sadece seninle

Bırakacağım...

Kilitleyip istikbalini kapılarını,

Hayatından bıktıracağım.

Aşık ettirip uzaklara göndereceğim.

Sevgi kelebeklerinin boynunu,

Mutluluklarının beynini alacağım.

Tek tesellinin,

Gözlerini cıkaracagim,

Sadece ve sadece,

Seni sana bırakacağım.

Yüreğindeki aşk acısına,

Kursunlara yağdırıp, asacağım,

Mutlaka birgün,

Öcümü alacağım senden...', 'Birgün mutlaka birgün, Öcümü alacağım senden, Gözlerin durduramayacak beni, Bırakıpta gittin ya beni, Mutlaka öcümü alacağım senden. ... Han...', ARRAY['Türk Edebiyatı','Şiir','Şair Gaddar__16']::text[], 8.5, '{"poet":"Şair Gaddar__16","poet_slug":"sair-gaddar-16","theme":"Türk Şiiri","is_hero":false,"total_lines":65,"source_url":"https://www.antoloji.com/ocumu-alacagim-senden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiyi aramak', 'sevgiyi-aramak-eyup-selahattin-dalkiran-zqyrt', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Elinde küçük bir balta

Kazdı kocaman dağı

Sanki bir şey arar gibi

Bulmak istediği neydi ki? 

Kocaman

	Bir 

	    hiç	

Kırk yıllık kazıdan

Beklediği neydi? 

Kazdığı dağın mutluluğumu? 

Ya da göz yaşınımı? 

Yok yok

Dağ ona bir şey vermedi

Elinde küçük bir balta ile

Dağın öbür tarafındaydı artık

Aradığını bulmuştu

Sevinçten fırlattı baltasını

Baltası havada dönerken

Bir koşu verdi ki

Yetişmek imkansız hızına

Ve sevgisinin içinde kayboldu

Baltası yere düşmeden.', 'Elinde küçük bir balta Kazdı kocaman dağı Sanki bir şey arar gibi Bulmak istediği neydi ki?  Kocaman 	Bir  	    hiç	 Kırk yıllık kazıdan Bek...', ARRAY['Türk Edebiyatı','Şiir','Eyüp Selahattin Dalkıran']::text[], 8.5, '{"poet":"Eyüp Selahattin Dalkıran","poet_slug":"eyup-selahattin-dalkiran","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sevgiyi-aramak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmek çok acı', 'sevmek-cok-aci-eyup-selahattin-dalkiran-3b6we', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ne acı değil mi sevgilim 

Seven insanın engellenmesi

Bir başıma kalmaktan korkuyorum

Acı ve hüzün içinde,ne yaparım ben

Seni sevmek suç değil ki her şeye karşı.

Ah sevgilim ah 

Sen dertli ben dertli

Ne olur ki karşılarına çıkıp 

Sevgim sizi ilgilendirmez

Diye bilmek sen ve ben için.

Her sıkıntı yıkar bizi 

Bir yıldızın gökten düşüşü gibi

Kızıl bir alev olur düşüncemiz

Sonsuz zamanın içinde,acımasız

Ah sevgilim ah sevmek ne acı değil mi?', 'Ne acı değil mi sevgilim  Seven insanın engellenmesi Bir başıma kalmaktan korkuyorum Acı ve hüzün içinde,ne yaparım ben Seni sevmek suç deği...', ARRAY['Türk Edebiyatı','Şiir','Eyüp Selahattin Dalkıran']::text[], 8.5, '{"poet":"Eyüp Selahattin Dalkıran","poet_slug":"eyup-selahattin-dalkiran","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sevmek-cok-aci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küstüren şiir', 'kusturen-siir-eyup-selahattin-dalkiran-w1425', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seni sevmek acı çekmekse

Ben seni sevmeyeceğim 

Seni sevmek devamlı söz duymaksa 

Ben seni sevmeyeceğim 

Seni sevmek ayrılıksa 

Ben seni sevmeyeceğim

Seni sevmek duyguların körelmesiyse

Ben seni sevmeyeceğim

Seni sevmek ağlamaksa 

Ben seni sevmeyeceğim

Seni sevmek sürekli hüsransa

Ben seni sevmeyeceğim 

Seni sevmek yağmurlu havalarda  üzülmekse

Ben seni sevmeyeceğim.', 'Seni sevmek acı çekmekse Ben seni sevmeyeceğim  Seni sevmek devamlı söz duymaksa  Ben seni sevmeyeceğim  Seni sevmek ayrılıksa  Ben seni sev...', ARRAY['Türk Edebiyatı','Şiir','Eyüp Selahattin Dalkıran']::text[], 8.5, '{"poet":"Eyüp Selahattin Dalkıran","poet_slug":"eyup-selahattin-dalkiran","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kusturen-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sınıra dayandı acılar', 'sinira-dayandi-acilar-eyup-selahattin-dalkiran-165y8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Karagözlüm gel elini uzat bana

Sınırsız sevgi ile büyümeli sevgimiz

Uzat elini bana karagözlüm

Gönlüm bugün kırgın,ateşli

Sınıra dayandı acılar

Gel karagözlüm gel sarıl bana

Bırak omzunda ağlayayım

Bırak dizlerinde uyuyayım

Bırak sana sıkı sıkı sarılayım

Gel karagözlüm gel

Senle bir ömür boyu yaşayayım

Gel su serp şu gönlüme

Bir ömür boyu senle olayım

Gel karagözlüm gel sarıl bana

Kırgınım ben bu hayata sensizlik ile.', 'Karagözlüm gel elini uzat bana Sınırsız sevgi ile büyümeli sevgimiz Uzat elini bana karagözlüm Gönlüm bugün kırgın,ateşli Sınıra dayandı acı...', ARRAY['Türk Edebiyatı','Şiir','Eyüp Selahattin Dalkıran']::text[], 8.5, '{"poet":"Eyüp Selahattin Dalkıran","poet_slug":"eyup-selahattin-dalkiran","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sinira-dayandi-acilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sustum', 'sustum-eyup-selahattin-dalkiran-wxriv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Nedir bu bende ki şaşkınlık

Ne yazdığım mısraları

Nede yarım kalmış şarkıları

Beğenir dudaklarım.

Sanki düşüncelerim avluya düşmüş gibi

Sanki sonuncu esnemesi

Yazdığım kağıtlar mısra beğenmez

Yolcular hafızam eski anıları

Söyletir dudaklarıma bir şeyler

Ayak izlerim kapılarına

Kapıma geliverir

İhtiyar bir rüzgarla

Her şey pencereden ötededir

Çizgisizlik ise yan,yana

Sanki geceyle gündüzün birleştiği

Yerde kalmış şaşkınlığım senin için.

Yüreğim harpten kalan

Süngülerle harcanmış,acı içinde

Kovalıyor düşüncelerim 

Issız rüzgarları.

Manasız bir gökyüzü gürültüsü duymak

İstemiyor kulaklarım

En yırtık çığlıklara karşı

Seni senle yaşamadığım için 

Bu dünyada.', 'Nedir bu bende ki şaşkınlık Ne yazdığım mısraları Nede yarım kalmış şarkıları Beğenir dudaklarım. Sanki düşüncelerim avluya düşmüş gibi Sank...', ARRAY['Türk Edebiyatı','Şiir','Eyüp Selahattin Dalkıran']::text[], 8.5, '{"poet":"Eyüp Selahattin Dalkıran","poet_slug":"eyup-selahattin-dalkiran","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sustum-40-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkak', 'korkak-esma-ozdemir-g7p8b', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'korkaksın sen korkak! 

yaşayamazsın

korkulara sığınarak! 

korkaksın sen

korkarak

eskimiş bir sevdadan artakalan

dudakların patlak! 

korkaksın sen

korkuların kendinden uzak! 

mahşer yeri gözlerinde bir ışık

yüzün yok aynada

yüzün yok, 

sevdaya doyasıya bakacak! 

kıyametin ortasında ellerim; bak! 

korkum yok, 

tut; yoksa, ecel gelip alacak!', 'korkaksın sen korkak!  yaşayamazsın korkulara sığınarak!  korkaksın sen korkarak eskimiş bir sevdadan artakalan dudakların patlak!  korkaksı...', ARRAY['Türk Edebiyatı','Şiir','Esma Özdemir']::text[], 8.5, '{"poet":"Esma Özdemir","poet_slug":"esma-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/korkak-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lirik 33', 'lirik-33-fevzi-cebe-8s0bg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'sadakat

düşlere

düşlerime

sadakat

yolum bu

hepsi bu...

00.40- 04.12.2004', 'sadakat düşlere düşlerime sadakat yolum bu hepsi bu... 00.40- 04.12.2004...', ARRAY['Türk Edebiyatı','Şiir','Fevzi Cebe']::text[], 8.5, '{"poet":"Fevzi Cebe","poet_slug":"fevzi-cebe","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/lirik-33-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Meyveler Sebzeler', 'meyveler-sebzeler-altay-taskin-s07g8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Acılar tatlılar ekşiler

Bağlarda bahçelerde yetişir

Sarılar kırmızılar yeşiller

Toplanıp pazara erişir

Sandıkta küfede filede

Kışın olan yazın yoktur

Bizimledir hepsi sevinçte kederde

Serti yumuşağı vitamin deposudur

Kimi kaynatılır şekerle

Kimi yenir tuzla

Kimi saklanır yaza

Kimi hazırlanır kışa', 'Acılar tatlılar ekşiler Bağlarda bahçelerde yetişir Sarılar kırmızılar yeşiller Toplanıp pazara erişir Sandıkta küfede filede Kışın olan yaz...', ARRAY['Türk Edebiyatı','Şiir','Altay Taşkın']::text[], 8.5, '{"poet":"Altay Taşkın","poet_slug":"altay-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/meyveler-sebzeler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sır...!', 'sir-pinar-koc-712d2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ey taş gibi görünen sır dolu duvarlar! 

Siz neler duyupta ,duymamazlıktan

Neler görüpte görmemezlikten geliyorsunuz…

Geceler boyunca uyumadığımı,

Geceler boyunca ağladığımı,

Sadece siz biliyorsunuz…

Sır duvarları,

Hani hatırlıyor musunuz

Bir gece size ağladığımı! 

Size dert yandığım zamanı,

Ne kadar rahatlamıştım

Anlatınca size,

Sizde teselli etmiştiniz beni 

Kendi dilinizle…

Ey dert ortağım,biricik sırdaşım

Sır duvarları…

Siz han duvarlarından daha gerçek,

Zindan duvarlarından daha cömertsiniz…! 

Siz sır duvarları,

Siz hayatımın yegane yoldaşları…

                                                                                     KASIM 1992', 'Ey taş gibi görünen sır dolu duvarlar!  Siz neler duyupta ,duymamazlıktan Neler görüpte görmemezlikten geliyorsunuz… Geceler boyunca uyumadı...', ARRAY['Türk Edebiyatı','Şiir','Pınar Koç']::text[], 8.5, '{"poet":"Pınar Koç","poet_slug":"pinar-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sir-82-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüzsüzsün Gece,Sitemler Sana! ! !', 'yuzsuzsun-gece-sitemler-sana-pinar-koc-56mzd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne karanlığı boğmaya,

Ne de beni öldürmeye yüzün yok senin…! 

Ey gece yüzün yok senin,

Ne boğuk sesleri kısmaya,

Nede güneşi boğmaya yüzün yok senin…

Yüzsüzsün gece,

Yüzün olsaydı,seni öpebilirdim! ! ! 

Karanlığı susturduğun,

Güneşi boğduğun için

Yüzsüzsün gece yüzsüz…

Ne sevdiğimi unutturabildin,

Nede kendini sevdirdin! ! ! 

Yalnız bıraktın beni bir ömür boyu

Sessiz,sensiz…

Sıkıldım artık biliyor musun? 

Sessiz saatlerden,yüzsüz geceden…

Bırak,

Sen yapamıyorsan,

Ben savaşayım karanlığı susturmakla…

Yeter diyorum

Yeter…

Bunca yıl hep sen söyledin,

Ben sustum dinledim.

Yeter…

Bıkmadın mı göz yaşlarımla bozulan sessizlikten,

Bıkmadın mı güneşi karartmaktan…

Yeter artık

YETER…………..

                                                                                       1992', 'Ne karanlığı boğmaya, Ne de beni öldürmeye yüzün yok senin…!  Ey gece yüzün yok senin, Ne boğuk sesleri kısmaya, Nede güneşi boğmaya yüzün y...', ARRAY['Türk Edebiyatı','Şiir','Pınar Koç']::text[], 8.5, '{"poet":"Pınar Koç","poet_slug":"pinar-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/yuzsuzsun-gece-sitemler-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayata Dair', 'hayata-dair-sami-ekici-sx5kn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Eller vardır tutar elinden,

Eller vardır anlar derdinden.

Gözler vardır kamaşır karanlıktan,

Gözler vardır sulanır mutluluktan.

Sözler vardır açılır suskunluktan,

Sözler vardır bir kez çıkar ağızdan.

Kalpler vardır ısınır soğuktan,

Kalpler vardır soğur üzüntüden.

Günler vardır uzun yıllardan,

Günler vardır biter gün batmadan.

Güller vardır açılır susuzluktan,

Güller vardır solar koparılmaktan.

Sevgili vardır utanır sevilmekten,

Sevgili vardır usanır sevmekten.

Bir can vardır doğar candan,

Bir can vardır ölür ayrılıktan.

Sevmek vardır çıkmaz akıldan,

Sevmek vardır dağılır rüzgardan.

Sevilmek vardır ayrılır herşeyden,

Sevilmek vardır ta derinden.

Can ayrılamaz canandan! 

Sevmek ötürüdür yaratandan! 

Sevilmek değerlidir dünyadan.', 'Eller vardır tutar elinden, Eller vardır anlar derdinden. Gözler vardır kamaşır karanlıktan, Gözler vardır sulanır mutluluktan. Sözler vardı...', ARRAY['Türk Edebiyatı','Şiir','Sami Ekici']::text[], 8.5, '{"poet":"Sami Ekici","poet_slug":"sami-ekici","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/hayata-dair-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gerçek', 'gercek-eyup-selahattin-dalkiran-pke38', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Biliyormusun bazen kendime gülüyorum 

Gidip aynaya bakıyorum tabi sen aklımdayken.

Bakıp,bakıp gülüyorum,gözlerime acıyorum o an

Neden diye hep seni buluyor bu tip sevgiler? 

neden seni gerçekten sevemiyorlar? 

yoksa çokmu iyisinde ondanmı? 

her biri kendinimi beğendi acaba? 

O gün bir sorular yumağı alır benliğimi,şaşkınca

Yanımdan geçen sevgililere bakar dururum,hüzünlü

Sanki benim yaşadılarımı yaşayacak gibiler

Üzülüyorum sonra diyorum ki işşallah mutlu olurlar

benim gibi bedbaht olmazlar bu dünyada.

İnan o kadar kadın tanıdım ki hiç biri seni eline su dökemez.

Bunu sende biliyordum,her zaman söylemişimdir sana.

Türlü anılarımı,yaşadığım zamanı,öyle bir işğal etmişsin ki; 

kendime yer bulacak bir santi metre kare yer kalmamamış.

Mutsuzum biliyormusun hemde ne mutsuz...? 

Yok,yok ben böyle bir adam olamam

sanki suda,havada dağılıp giden bir şeyler oluyorum.

Temiz elbiseler,şık giyinirdim her zaman

Ama şimdi öyle değilim,ben bunları söylerken

kimbilir kiminle neler konuşuyorsundur,umurundamı sanki

Benim şıklığım,mutsuz dolaşmam,ama ben seni yine düşünüyorum

Anlayamadığım kendime neden kızdığımdır bunca yaşadıklarımla

Ama sensin bunlara meydan veren,sen,sensin  anlıyormusun? 

Bir şeylerden haber bekliyorum sen için.bir kuştan,bir çiçekten,

Bir karıncadan,bir yapraktan,ve hatta allahtan bile ama yok.

Ne olursun bir ara,bir merhaba de,sağ olduğunu  bileyim yeter

Şu an ağlıyorum; inan gözlerimden yağmur damlaları gibi iniyor yaşlar.

Göğüs kafesim patlayacak gibi,öyle bedbahttım ki sevgilim,ah,ah,ah...

Başıma ağrılar girmekte,çıldırıyorum sanki,inan sana beddua etmiyorum.

seven beddua edebilirmi ki,senin gözlerin her şeye değer,anlatmıştım da sana

Doğrular ortada iken sen neyi savunabilirsin ki

ben savunurum ama sen olmasanda.', 'Biliyormusun bazen kendime gülüyorum  Gidip aynaya bakıyorum tabi sen aklımdayken. Bakıp,bakıp gülüyorum,gözlerime acıyorum o an Neden diye ...', ARRAY['Türk Edebiyatı','Şiir','Eyüp Selahattin Dalkıran']::text[], 8.5, '{"poet":"Eyüp Selahattin Dalkıran","poet_slug":"eyup-selahattin-dalkiran","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/gercek-58-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasıl Geçti Seneler', 'nasil-gecti-seneler-cemile-duzgun-kiv17', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ömür bağ salkımıydı,

Tatlıydı ilk taneler.

Elimde kaldı çöpü,

Nasıl geçti seneler...

Çirkin yürekler gördüm,

Gönle siperler ördüm,

Tükenirken kırk dördüm,

Nasıl geçti seneler...

İyi günüm olmadı

Artık gücüm kalmadı

Aklım fikrim almadı

Nasıl geçti seneler...

Önü kapalı yoldu

Güller goncada soldu,

Yüzüm çizgiyle doldu

Nasıl geçti seneler...

Poyraz savurdu,itti

Umutlar battı gitti

Ne acı herşey bitti,

Nasıl geçti seneler...', 'Ömür bağ salkımıydı, Tatlıydı ilk taneler. Elimde kaldı çöpü, Nasıl geçti seneler... Çirkin yürekler gördüm, Gönle siperler ördüm, Tükenirke...', ARRAY['Türk Edebiyatı','Şiir','Cemile Düzgün']::text[], 8.5, '{"poet":"Cemile Düzgün","poet_slug":"cemile-duzgun","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/nasil-gecti-seneler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kul Güzel Görsün', 'kul-guzel-gorsun-cemile-duzgun-skfl9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Biline ki en sevgili vatandır,

		Essin ova,bayı yel güzel görsün,

		Zümrütler doğuran nazlı sultandır,

		Al,yeşil yüklensin,dal güzel görsün...

		Yöremizde güneş dallarda uyur,

		Yağmur ninnidedir,fidanlar büyür

		Köyümde kentimde dostluğa buyur,

		Yaratan özenmiş,kul güzel görsün...

		Güzeller dal boylu,ince saz gibi

		Bakışları,cilve gibi,naz gibi

		Bağlar,görücüye çıkmış kız gibi

		Açılır mor,beyaz; gül güzel görsün...

		Kıyılarda yelkenliler,takalar 

		Kumsallara dantel olur dalgalar,

		Çift taraflı dizilmiş akasyalar

		Irgandıkça dallar,yol güzel görsün...

		Kızılırmak,Yeşilırmak deltası

		Bereketin yurdu bolluk yuvası

		KARA adındadır,aktır sayfası

		Bu güzel bizimdir,el güzel görsün...

		Ezgimiz kıvraktır,şartlarsa çetin

		Çıkıp kemençeyle oluruz bütün,

		Bölmeye kalkanlar,bunu unutun

                                Tatlıya bağlarız,bal güzel görsün..', 'Biline ki en sevgili vatandır, 		Essin ova,bayı yel güzel görsün, 		Zümrütler doğuran nazlı sultandır, 		Al,yeşil yüklensin,dal güzel görsün...', ARRAY['Türk Edebiyatı','Şiir','Cemile Düzgün']::text[], 8.5, '{"poet":"Cemile Düzgün","poet_slug":"cemile-duzgun","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/kul-guzel-gorsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Gömsünler Beni', 'sana-gomsunler-beni-ali-osman-yilmaz-dj4sw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Böyle yaşamak istemem,

Sende ölmek isterim,

Ve sana gömsünler beni,

Yaşadım hep sensizliğin koynunda,

Ölünce bari,

Sana gömsünler ki,

Sende yaşayayım,

Sonsuzluğu.

(Perili Kalp''e)', 'Böyle yaşamak istemem, Sende ölmek isterim, Ve sana gömsünler beni, Yaşadım hep sensizliğin koynunda, Ölünce bari, Sana gömsünler ki, Sende ...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sana-gomsunler-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yürek Acısı', 'yurek-acisi-ali-osman-yilmaz-tj6t6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yürek acısı! 

Benzemez hiçbir şeye,

Yitirmeye gör,aşkını,

‘O’nun kara sevdası,

Yıkar adamı,

Dev gibi olsan da,

Gönül yarası.

Yaşam dediğin nedir ki? 

Doğarsın,ve ölürsün,

Arada yaşadığın,

Alev alev yandığın,

Yüreğini yakan,

Aşk Acısı

(Perili Kalp''e)', 'Yürek acısı!  Benzemez hiçbir şeye, Yitirmeye gör,aşkını, ‘O’nun kara sevdası, Yıkar adamı, Dev gibi olsan da, Gönül yarası. Yaşam dediğin n...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yurek-acisi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Niye Büyüdüm Ki! ! ! !', 'niye-buyudum-ki-ramazan-ates-p263b', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Küçüktüm,

Büyük sevdalar anlatırdı büyüklerim,

Kerem ile Aslı’yı, Leyla ile Mecnun’u

İmrenirdim,

Büyüyünce bende öyle sevda yaşıyacam derdim.

Biraz daha büyüdük,

Sinemalarda büyük aşklar görür olduk

Zengin kız fakir oglan aşkları,

Onlarada imrendik, hayaller kurduk.

Leyla ile Mecnun’u, Ferhat ile Şirin’i

Ne Aslı oldu yanımızda, nede biz döndük Kerem’e

Ne bir zengin kız aşık oldu,

Nede biz zengin olduk.

Ne ugruna dağ delecegimiz oldu,

Nede uğrumuza can verenimiz.

Dillere destan sevdalarımız olmadı,

Nede Şirin gibi bir sevenimiz.

Aceba halen küçükmüyüm? 

Bir gün büyüyüp yaşıyacakmıyım o aşkları? 

Aceba o sevdalar mı kalmadı? 

Sevdalar yerini şehvete mi bıraktı.

Büyüdüm yeterince,

Çalındı umutlarım,

Bölündü sevdalarım,

Ne Leyla’m oldu benim, nede ben Mecnun’a döndüm.

Büyüdüm olduğunca,

Ne küçüklerime anlatacak bir sevda masalım var,

Nede o masallardaki gibi sevdaları yaşayanlar.

Gün bulup gün yaşıyoruz, hepsi bu kadar.

Zaman mı değişti? 

Bizmi yanlış büyüdük yoksa? 

Sevdalar mı başkalaştı? 

Kalplerimiz mi taşlaştı yoksa? 

Böyle büyümeyi istemezdim,

Bana göre körü körüne.

Bölünmüş sevdalar, çalınmış umutlar,

Neyi yaşadım ki? Anlatacak neyim var? 

Ramazan Ateş/Enschede-22.12.2005', 'Küçüktüm, Büyük sevdalar anlatırdı büyüklerim, Kerem ile Aslı’yı, Leyla ile Mecnun’u İmrenirdim, Büyüyünce bende öyle sevda yaşıyacam derdim...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Ateş']::text[], 8.5, '{"poet":"Ramazan Ateş","poet_slug":"ramazan-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/niye-buyudum-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pes Etmez Miyim?', 'pes-etmez-miyim-cemile-duzgun-zdobh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yüzüme kanmayın,yüreğim ağlar

	Bir ıssız çölmüşüm,pes etmez miyim? 

	Derdimi duyarsa yıkılır dağlar,

	Çilekeş kulmuşum,pes etmez miyim? 

	Madem kardelendim,nerede bahar? 

	Nerede cemreyle yükselen buhar? 

	Gönlüm öyle yuhka,canım öyle dar,

	Dert küpü olmuşum,pes etmez miyim? 

	İşte bu kırık gül hazân eserİ

                Yağmur duasına artık yok feri

                Harman yerlerinin saman değeri,

                Yükünü almışım,pes etmez miyim? 

                Pınarın gözüyüm,taşsam ne olur? 

                Aşkın deryasına taşsam ne olur? 

                Baharın peşinden koşsam ne olur? 

                Kışa takılmışım,pes etmez miyim? 

                Kabuğu zorlayıp geçeyim derken,

                Bir pembe bulutla uçayım derken

                Kaç kez niyet kurdum,açayım derken

                Kökümden solmuşum,pes etmez miyim? 

                                                                   22-01-05', 'Yüzüme kanmayın,yüreğim ağlar 	Bir ıssız çölmüşüm,pes etmez miyim?  	Derdimi duyarsa yıkılır dağlar, 	Çilekeş kulmuşum,pes etmez miyim?  	Ma...', ARRAY['Türk Edebiyatı','Şiir','Cemile Düzgün']::text[], 8.5, '{"poet":"Cemile Düzgün","poet_slug":"cemile-duzgun","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/pes-etmez-miyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Efendim', 'efendim-cemile-duzgun-2d3du', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu cânan hâlende dönsün,dolaşsın,

			Öyle asil,ender soysun efendim.

			Gönül ister,tâ fizana ulaşsın,

			Bu sevinci âlem duysun efendim...

			Ağular bozulup,şerbet karıldı,

			O bulanık umman nasıl duruldu

			Vuslatta kuşsütü sofra kuruldu

			Gönlüm açlığına doysun efendim...

			Engin tastan kana kana içsin de

			Bir hoş olsun canlar, hüznü biçsin de.

			Ömrü didik didik, seçsin seçsin de

			O  anı en başa koysun efendim...

			Artık toparlansın kırık dalları

			Şenlendiriversin kuru çölleri.

			Açılsın saçılsın kübra gülleri,

			Bizi taze bahar saysın efendim...

			Halimiz mi kalmış acı çekmeye 

			Kanımız nazlanır coşup akmaya

			Mevlâm kararlıysa bizi yakmaya,

			Hatırımız için caysın efendim...', 'Bu cânan hâlende dönsün,dolaşsın, 			Öyle asil,ender soysun efendim. 			Gönül ister,tâ fizana ulaşsın, 			Bu sevinci âlem duysun efendim... ...', ARRAY['Türk Edebiyatı','Şiir','Cemile Düzgün']::text[], 8.5, '{"poet":"Cemile Düzgün","poet_slug":"cemile-duzgun","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/efendim-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'A Gülüm', 'a-gulum-cemile-duzgun-es7ig', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hâlâ uslanmayıp aşkı ararsın

Her bulduğun göle dalma a gülüm

Yine üzülürsün yine ağlarsın

Sakın aşık maşık olma a gülüm

Kimisi koparır, kimi fırlatır

Kimi övünerek, gider anlatır

Olur olmaz kulağını çınlatır

Vefa yollarında kalma a gülüm

Sen iyiysen iyi çoktur çevrede

Yamyam ruhlu fırsatçılar devrede

Bencilliğin kokuştuğu evrede

Herkesi sen gibi bilme a gülüm

Bir coşar gürlersin, dindiremezsin

Bir kıvılım yeter, söndüremezsin

Kaçın kur`asıyım kandıramazsın

İçerin ağlarken gülme a gülüm

Her geçen gün belki hüzün yükledi

Lâkin pes etmeyi sana kim dedi.

Hâlâ vaktimiz var, toparlan hadi

Kendini bu kadar salma a gülüm

Sözüm sana gönlüm duydun mu beni? 

Boşuna arama koyup gideni

Sevgini sömürüp talân edeni

Adam sırasına alma a gülüm', 'Hâlâ uslanmayıp aşkı ararsın Her bulduğun göle dalma a gülüm Yine üzülürsün yine ağlarsın Sakın aşık maşık olma a gülüm Kimisi koparır, kimi...', ARRAY['Türk Edebiyatı','Şiir','Cemile Düzgün']::text[], 8.5, '{"poet":"Cemile Düzgün","poet_slug":"cemile-duzgun","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/a-gulum-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arabesk / canımın i(ş) çisi...', 'arabesk-canimin-i-s-cisi-zafer-zengin-etnika-bdskf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Mavi gülüme; 

Mavi göllerin çevre çiçeği 

Varlığındır dünya''yı kabulüm 

Yokluğunsa 

Dipler de sonum 

Son umudum 

Canımın sevda pınarı 

Yokluğun her şeyin kayıplığı 

Sürümsel alanlarda 

Sürünüyorum ellerim bağlı... 

Biliyorum ki; Dönüşün muhteşem olacak 

Beni yatak döşekten kaldıracak 

Erken gel ne olur 

Yastıklar hakkımda dava açacak... 

O kadar sensizim ki sevdam 

Yandım eridim bittim 

Bi r deri bir kemik hayaletim... 

Seni halen seviyorum 

Ve çok özlüyorum canımın işçisi 

Seni seviyorum bir tanem... 

Nar tanem... 

Can tanem... 

20 Eylül 2005 / kendine gülmenin başladığı yer', 'Mavi gülüme;  Mavi göllerin çevre çiçeği  Varlığındır dünya''yı kabulüm  Yokluğunsa  Dipler de sonum  Son umudum  Canımın sevda pınarı  Yoklu...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/arabesk-canimin-i-s-cisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Naz / Ağlamaya dair...', 'naz-aglamaya-dair-zafer-zengin-etnika-x150k', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ağlamaya dair; 

yağdı 

yağacak yağmur 

kafada dalgınlık 

istemek öteleri 

dilenmek gözleri 

yanıyor gözler 

yağdı 

yağacak yağmur…

14 09 2005', 'ağlamaya dair;  yağdı  yağacak yağmur  kafada dalgınlık  istemek öteleri  dilenmek gözleri  yanıyor gözler  yağdı  yağacak yağmur… 14 09 200...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/naz-aglamaya-dair-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Katıl / Aşkı yaşamamışlara...', 'katil-aski-yasamamislara-zafer-zengin-etnika-lqr9e', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aşkı yaşamamışlara; 

korkun dirilmektir 

korkun yeniden sevmek 

ölümsüzlüğünü yitirmek 

oysa bir gün 

çocukta ölür tanrıda 

yabani bu dünya 

kıyısı dalgasında 

katıl haydi 

ölümlülerin arasına...

20 Eylül 2005', 'Aşkı yaşamamışlara;  korkun dirilmektir  korkun yeniden sevmek  ölümsüzlüğünü yitirmek  oysa bir gün  çocukta ölür tanrıda  yabani bu dünya ...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/katil-aski-yasamamislara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen, aşk ve üç nokta..', 'sen-ask-ve-uc-nokta-rezzan-ersoy-2vlgb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gözyaşları saklanmıyor artık gecenın bir yarısı..

Kaldırımlar da yürünmüyor..

Yaşamak acı veriyor..

Ve yaram kanıyor yine..

Acı yineleniyor..

Her yeni gün dönümünde..

Yavaş yavaş, ağır ağır..

Sonbahar yaprakları düşüyor ellerine..

Yağmur taneleri gözleri ıslatıyor..

ki zaten ıslak..

Ellerinde öyle..

Sırılsıklam benliğin

yavaş ve emin; seviyorsun..

Gözleri hem karanlık, hem ışık oluyor..

Aşk bir korku içini yakan..

derin derin işliyor kanına yöneliyor..

Damarların genişliyor,gözlerin kapanıyor..

Seni her sevdiğimde sabahlarım uzaklaşıyor..

Gecem uzuyor..

Sen uzaksın şimdi geceler dost; 

Ki hiç yakışmıyor..', 'Gözyaşları saklanmıyor artık gecenın bir yarısı.. Kaldırımlar da yürünmüyor.. Yaşamak acı veriyor.. Ve yaram kanıyor yine.. Acı yineleniyor....', ARRAY['Türk Edebiyatı','Şiir','Rezzan Ersoy']::text[], 8.5, '{"poet":"Rezzan Ersoy","poet_slug":"rezzan-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sen-ask-ve-uc-nokta-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çanakkale Gelibolu', 'canakkale-gelibolu-umut-gungor-obaro', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çanakkale Gelibolu,

Şehit dolu sağı solu,

Dört kıtaya nam salmıştır,

Türkün yiğit öncü kolu.

Çanakkale Çanakkale, 

Şanla Dolu Çanakkale, 

Bütün Dünya'' ya nam Saldın, 

Atatürk''le Çanakkale. 

Toprağında kan bulursun,

Gezip görüp can bulursun,

Dört dünyaya nam saldılar,

Şehit gazi selam olsun.

Anlatmaya dil çaresiz,

Aşk olurmu hiç yaresiz,

Dünyaya meydan okunan,

Conk dururmu hiç paresiz.

Anafarta ayaklandı,

Kapıları dayaklandı,

Şaşa kaldı koca dünya,

Şehit gazi ayaklandı.', 'Çanakkale Gelibolu, Şehit dolu sağı solu, Dört kıtaya nam salmıştır, Türkün yiğit öncü kolu. Çanakkale Çanakkale,  Şanla Dolu Çanakkale,  Bü...', ARRAY['Türk Edebiyatı','Şiir','Ümüt Güngör']::text[], 8.5, '{"poet":"Ümüt Güngör","poet_slug":"umut-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/canakkale-gelibolu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karanlık, Çığlık ve Siyam Kedisi', 'karanlik-ciglik-ve-siyam-kedisi-ozgur-celik-s3xph', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bir çocuk belirdi karanlığın tam ortasında,

yürüdü çocuk ürkek adımlarla

yanıbaşında çığlık

ve ötesinde siyam kedisi.

dağnıktı saçları

karanlığa inat güneş kadar sarı.

bir okadar sıcaktı bakışları.

siyam kedisi dolandı ayaklarına

takılıp düştü çocuk

dilinde çığlık.

kan içinde kaldı karanlık, çığlık, siyam kedisi.

neydi bunun ötesi

ne vardı karanlığın tükendiği yerde

bunu ne karanlık biliyordu

ne siyam kedisi ne de çığlık.

doğruldu olduğu yerden çocuk

yürüdü, adımları küçük

yürüdükçe kayboldu karanlık

sonra kayboldu çığlık

yutuverdi çocuğu aydınlık

kamaştı çocuğun gözleri

siyan kedisini aradı ilkin

ne karanlık vardı yanında

ne siyam kedisi ne de  çığlık

yapayalnızdı artık çocuk

etraf göz alabildiğine aydınlık

kalakalmıştı tek başına

bakındı şöyle bir etrafına

karanlığı aradı ilk

alışkın değildi bukadar ışığa

bir çığlık atmak istedi

sesi çıkmadı

siyam kedisinin gözleri parladı

yanıbaşındaki karanlığın ortasında

geri dönmek istedi, beceremedi

karardı gözleri çocuğun

çoktu bu kadar ışık

pişmandı artık

sordu kedine

neye yarardı görmeyen göze aydınlık

oysa gözlerini ilk açtığında

karanlığı görmüştü ilk

sonra siyam kedisini

en son çığlığı duymuştu

şimdi herşey susmuştu....', 'bir çocuk belirdi karanlığın tam ortasında, yürüdü çocuk ürkek adımlarla yanıbaşında çığlık ve ötesinde siyam kedisi. dağnıktı saçları karan...', ARRAY['Türk Edebiyatı','Şiir','Özgür Çelik']::text[], 8.5, '{"poet":"Özgür Çelik","poet_slug":"ozgur-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/karanlik-ciglik-ve-siyam-kedisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tüberküloz Zihniyetli Bir Aşk', 'tuberkuloz-zihniyetli-bir-ask-ahmet-degirmenci-vurud', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'basımın agrısına teslim olmayacak gibiyim

sigarasızlıktan titriyor ellerim 

ne vardı hiç içmemiş olsaydım su laneti

böyle konusmak dogru degil ama

aynı seyleri senın içinde söylüyorum

hernekadarda bir zamanlar

deli gibi sevsemde seni..

tüberkloz zihniyetli bir caresizlikle bogusuyorum 

cogu zaman..

sana emanet vermemıstım yüregimi

düşündükçe sinirleniyorum

evladiyelik bir ask teslim ettim sana

saklamak yerine ezmenın ne alemı vardı

en azından saygı duyulmaya degmezmiydi

sana sundugum ask..

bırakıp gitmiş olmanı umursamıyorum artık

baskasını sevmenıde 

unutulmak koyuyor insana

ben öldüm mü? ki diyesim geliyor

çaresizlikle bogusmakla geçiriyorum günlerimi

hayatta kalama pahasına bir çok sey uçup gidiyor elimden

gençligimden ve en güzel zamanlarımdan ziyade..

kahpe gülüşlere silleyi basacak kadar 

delikanlı mevcut bululurken kırılmıs yüregimde

yeni bir askla ugrasamayacak kadar çelimsiz buluyorum kendimi

aşk..

münakasalarına ayıracak zaman yoktu bende

kendimi avutuyorum cogu zaman

allahım bu kız nekadar güzel diye! 

güzelliginden ziyade 

gözlerine bakmaya bile mecelim yok çogu zaman..

tanımadıgım kızlara 

önyargılı

bakmakla 

geçiriyorum senden kalan zamanı,

sonra senı tanımadan sevdigim aklıma geliyor 

önyargısız seviyorum seni 

yani kusursuz

aynı mahalde kusursuz bir işkence çekiyor yüregim

ne olurdu seni biraz tanısaydım

giden gitmiş zaten aglamak cok yersiz

yalnızlık hat safhada

savasmak ölmekten daha yersiz...

bunca bıcak darbesınden sonra hala adını solemek

bir orospuya evlilik ümidi vermek 

veya bir cenazeye

mutluluk hapı içirmek gibi birsey...

caresızken çare aramakta degil

eger seviyorsam hala seni

inan daha fazla saçmalayamam

ölmüşken saklanan paranın hesabını yapmak gibi birsey

anla işte

ne sen bana 

gel nede 

ben sana

ister sev

ister evlen

istersen agla

ben

yolumu

coktan

AYIRIYORUM ASKLA...', 'basımın agrısına teslim olmayacak gibiyim sigarasızlıktan titriyor ellerim  ne vardı hiç içmemiş olsaydım su laneti böyle konusmak dogru deg...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Degirmenci']::text[], 8.5, '{"poet":"Ahmet Degirmenci","poet_slug":"ahmet-degirmenci","theme":"Türk Şiiri","is_hero":false,"total_lines":62,"source_url":"https://www.antoloji.com/tuberkuloz-zihniyetli-bir-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Aglama', 'sen-aglama-ahmet-degirmenci-iau4r', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'duyduklarım hosuma gitmedi

mutsuzmusun sıkılmısın yasadıgın hayattan

hatta ben gibi aglıyormusuun sessiz sessız

beni kırdın üzgünüm

iyi degilim ama sen neden üzgünsün

yakısmıyor dudaklarına sitem

hele gözlerin ıslak ıslak

ne olur sen aglama yanaklarından kayıyor yıldızlar

gökyüzü yıldızsız kalmasın 

yoksa ben ne yaparım geceleri

beni sakın düşünme

iyi olmaya çalısıyorum

ama

sen sakın aglama

kızsamda sana

senden vazgeçemiyor yüregim

eger ben isem derdın

çeker giderim

ismimi duyamıyacagın kadar uzaga

baskası ise sevdigin 

egilirim onun önünde 

sırf sen onu sevdin diye

ben aglamam sen üzülüyorsun diye

içime dolar acıların yagmuru

yinede aglamam sen üzülme diye

bakma sen bana

sana

üzülme diyorum

aslında

kendimi

düşünüyorum

biliyorum ki sen üzülünce

param parça olacak yüregim

ne olur sen aglama

üzülen ben olayım

ne olursun aglama

ıstemiyorsan gideyim

yetmedimi hıçkırıklarını durdurmaya

ben

orada

öleyim..

sırf sen aglama diye...

senı sevdım seveli

gözlerine kıyamıyor yüregim

eger ıslanırsa gözlerin

yüregimdende geçerim

gülen gözleri sevdim ben

musade ette

sevdigim gibi kalsın GÖZLERİN....', 'duyduklarım hosuma gitmedi mutsuzmusun sıkılmısın yasadıgın hayattan hatta ben gibi aglıyormusuun sessiz sessız beni kırdın üzgünüm iyi degi...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Degirmenci']::text[], 8.5, '{"poet":"Ahmet Degirmenci","poet_slug":"ahmet-degirmenci","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/sen-aglama-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Değer Mi?', 'deger-mi-ufuk-coban-s39bb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hayat değer mi yaşamaya iki günün ardından,

Sevdiğin, en sevdiğin anda alınmışsa elinden? 

Tek başına düşmüşsen yağmurlu sokaklara,

Yürümek değer mi gidecek yerin yoksa? 

Ben bir kış rüzgarı içindeyim,

Aldığı gibi buz kesip atılıyorum köşelere,

Sırtımı dönmeye korkuyorum sevgilere,

Sevgiler hep sırtını dönmüşken gözlerime.

Ağlamak istiyorum, faydası yok biliyorum,

Gitmek istiyorum, zaten uzaktayım görüyorum.

Hiçbirşey değmiyor düşünmeye üzerinde,

Kendim değmemişim birşeye yüreğim değse ne olur ki sevdiğine? 

Yaşamak değer mi sevdiğin gözünün ucunda bakıyorsa,

Durmak fayda eder mi cam duvarlar dikilmişse önüne.

Bana değmez sen üzülme senden gidişime,

Bu senden gidiş değil, bu dönüş sevgimdeki yalnızlığıma.

22/12/2005 21:15', 'Hayat değer mi yaşamaya iki günün ardından, Sevdiğin, en sevdiğin anda alınmışsa elinden?  Tek başına düşmüşsen yağmurlu sokaklara, Yürümek ...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Çoban']::text[], 8.5, '{"poet":"Ufuk Çoban","poet_slug":"ufuk-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/deger-mi-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Memleketli yarim', 'memleketli-yarim-guler-atas-bkw5e', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sana yar desem 

Yanan yüreğimdir sevdalım

Bir yanın memleket kokar 

Bir yanın ben koksam

Versen elini 

Memleketli yarin olsam

                                   22/12/2005', 'Sana yar desem  Yanan yüreğimdir sevdalım Bir yanın memleket kokar  Bir yanın ben koksam Versen elini  Memleketli yarin olsam               ...', ARRAY['Türk Edebiyatı','Şiir','Güler Ataş']::text[], 8.5, '{"poet":"Güler Ataş","poet_slug":"guler-atas","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/memleketli-yarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geleceğim Demiştin', 'gelecegim-demistin-muzaffer-tekbiyik-5nnbt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sana şarkılar yazdım,hatıralar adına

Gönül dayanmaz olur,bu aşkın feryadına

Bu isyan kuyusunda,yetiş yar imdadıma

Unutmadım unutamam,ah seni sevgilim.

Gözlerime bakarak bir şeyler söylemiştin

Bekle beni sevdiğim geleceğim demiştin.

Aşk belası yüzünden şimdi eller gibiyim

Ateşten sona kalan sanki küller gibiyim

Aynaya sordum söyle.söyle eski benmiyim

Unutmadım unutamam,ah seni sevdiğim

Gözlerime bakarak bir şeyler söylemiştin

Bekle beni sevdiğim geleceğim demiştin

Anılar tazelenir,gezdiğimiz yerlerde

Şu yayla eteğinde,hele mavi sahilde

Ulu çınar altında,ellerin ellerimde

Unutmadım unutamam,ah seni sevgilim

Gözlerime bakarak bir şeyler söylemiştin

Bekle beni sevdiğim geleceğim demiştin

(19.04.2004)', 'Sana şarkılar yazdım,hatıralar adına Gönül dayanmaz olur,bu aşkın feryadına Bu isyan kuyusunda,yetiş yar imdadıma Unutmadım unutamam,ah seni...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Tekbıyık']::text[], 8.5, '{"poet":"Muzaffer Tekbıyık","poet_slug":"muzaffer-tekbiyik","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/gelecegim-demistin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şükrü Paşa Edirne''nin Tarihi,', 'sukru-pasa-edirne-nin-tarihi-umut-gungor-htrbh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şükrü Paşa Edirne''nin Tarihi,

Tarih yetmez hatta birde Fatih''i,

Kara etmiş düşmanına talihi,

İn ararmış düşman kaçıp girmeye.

Şükrü Paşa Edirne''nin kalesi,

Sökmez ona düşmanların hilesi,

Savrulunca yağız atlar yelesi,

İn ararmış düşman kaçıp girmeye.

Askeriyle çoğu zaman aç durmuş,

Yüreklere sökülmeyen taç kurmuş,

Düşmanına pençe gibi baç vurmuş,

İn ararmış düşman kaçıp girmeye.

Not: Bu şiir bizzat Edirne''de gidip gördüğüm Şükrü Paşa anısına yapılmış ziyaret yerindeki anıt vede sığınakları görüp fazlasıyla duygulandığımdan dolayı içimden gelen duygularla tarafımdan Edirne''yede özellikle bir hatıra olsun diye yazılmıştır.', 'Şükrü Paşa Edirne''nin Tarihi, Tarih yetmez hatta birde Fatih''i, Kara etmiş düşmanına talihi, İn ararmış düşman kaçıp girmeye. Şükrü Paşa Edi...', ARRAY['Türk Edebiyatı','Şiir','Ümüt Güngör']::text[], 8.5, '{"poet":"Ümüt Güngör","poet_slug":"umut-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sukru-pasa-edirne-nin-tarihi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat', 'hayat-utku-demir-8qa0g', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bileceksin hiçliğin tutuşunu yakandan

Öğreneceksin nefes almadan yaşamayı

Herkesten uzaklarda bir başına yalnızlığın

Hayal meyal dalışlarda geçmişe

Kelimelerini duyacaksın sessizliğin

Kaçmadan dövüşeceksin düşe kalka

Sonra herşeye çözüm dost olacaksın

Onun haykırışlarını anlatacaksın

Özlemin zarifliğindendir uykusuzlukların

Sonsuz bir bekleyişin yeğnikliğinde

Zaman yoktur bilesin, 

Sevgi gücündür istediğini yarattığın

Bırakırsan onsuz alıp götürür seni hayat

Çırpınırsan yeni bir hedef çıkar karşına

Seni tüketircesine engeller koyar

İyisimi soyun kalbin rahat atsın 

Getirsin gideceğin yeri gönlüne 

Tümden yaşamalı hayatı, esirgemeden kendini

Acıysa derinlerine batışını hissedersin

Aşıksan kalbinden fışkırır yalımlar

Seviyorsan ruhuna gömüp çıkartmazsın

Hüzünlerinin izleri yansır gözlerine

Sarıldım mı yapışırsın tepeden tırnağa 

Akıp gider titreye titreye enerjin

Yorulursun adım atamaz olur halin

Taşınmaz sanırsın sığmayan duyguları

Sınırsızdır yüreğin anlarsın sırrını

İnadına bıkmazsın mücadeleden hayatla

Başarırsın sonunda öldüğünde dirilmeyi

Bir de bakarsınki ansızın

Buzdan bir duvarın dibine çökmüşsün 

Kaldığını düşünürsün oysa hep gidersin

Her nefesinde her anında kımıltısızca

Düşlerinde bile duramazsın esaretinde

Yapışıp gerçeğin şeffaf kuyruğuna

Elekten geçirirsin bakışları insanları

Dinlersin şarkıları her gece başka bir yıldızdan

Paylaşırsın yüreğini döktüğün şiirlerde 

Ağaçla,çiçekle,kuşla,böcekle

Doğanın içinden akan şarapla', 'Bileceksin hiçliğin tutuşunu yakandan Öğreneceksin nefes almadan yaşamayı Herkesten uzaklarda bir başına yalnızlığın Hayal meyal dalışlarda ...', ARRAY['Türk Edebiyatı','Şiir','Utku Demir']::text[], 8.5, '{"poet":"Utku Demir","poet_slug":"utku-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/hayat-272-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sev dedim amma,', 'sev-dedim-amma-fikret-dundar-i5xam', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seviyorum seni dediğimde 

Şöyle demiştin güzelim.

Sev dedim amma,

Beni,

Beni sev demedim ya! 

Özlemiştim,

Kıpır kıpırdı içim,

Görüşelim demiştim.

Yüzyüze,

Kısa zaman içinde! 

Vaktim yok,

Bu olamaz,

Şimdi bu mümkün değil,

Diyen de

Sen oldun be bir danem,

Sen oldun yine.

Beni cezbeden,

Beni kendine aşık eden

Sen oldun güzelim.

Çok, 

Hem de çok ürkek bir halin

Kaçmıyor hiç gözümden

Sanki,

Sanki korkar gibi bir halin var,

Sana acılar çektiren,

Seni mahveden,

Başka birisinden! 

Kendine aşık eden de sen oldun,

Aman uzakta kal,

Gelme,

Bu mümkün değil 

Diyen de.

Etme be güzelim,

Yetti artık,

İnsafa gel, ne olur

Kalp taşıyorsun sen de,

Azıcık kulak ver,

Yen korkularını,

Geçmişten ders al.

Bekliyorum,

En azından elimden geleni 

Yapacağım de.

Bana da çektirme

Bastırmaya çalıştığın duygularla,

O güzel, o yapayalnız,

O yaralı yüreğine  de,

Yazık be güzelim,

Evet, evet,

Ben de arzuluyorum,

Hem de en kısa zamanda

Bekliyorum,

İçtenlikle hem de,

Desene.

O kadar, ama o kadar 

Mecalin  kalmadı mı,

O kadar da  duygu

Yoksunu musun be güzelim! 

Bahane  üstüne başka bahane 

Söyleme, 

Sürme onları önüme  biteviye! 

Durma,

Ne olur durma artık,

Durma,

Bana bir şeyler söyle! 

Erenköy – İstanbul

20.09.2005', 'Seviyorum seni dediğimde  Şöyle demiştin güzelim. Sev dedim amma, Beni, Beni sev demedim ya!  Özlemiştim, Kıpır kıpırdı içim, Görüşelim demi...', ARRAY['Türk Edebiyatı','Şiir','Fikret Dündar']::text[], 8.5, '{"poet":"Fikret Dündar","poet_slug":"fikret-dundar","theme":"Türk Şiiri","is_hero":false,"total_lines":66,"source_url":"https://www.antoloji.com/sev-dedim-amma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kızılderili Kadına Türkü', 'kizilderili-kadina-turku-suna-aras-826y3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kurşun sesi yakınlarda gece üç

Perdeyi sıkıladım

Ölü nergis kokuyordu balkonum.

O kadını hatırladım Kızılderili

Silahı omzunda memesinde çocuğu

Hayatın kulağını dişleriyle çekiyor

İçimin ölen yanı kıpırdandı dur gitme

İyi ki insanda umut bitmiyor.

Bir kuş sesi uzaklarda gece üç

Perdeyi araladım

Anne sütü kokuyordu balkonum.', 'Kurşun sesi yakınlarda gece üç Perdeyi sıkıladım Ölü nergis kokuyordu balkonum. O kadını hatırladım Kızılderili Silahı omzunda memesinde çoc...', ARRAY['Türk Edebiyatı','Şiir','Suna Aras']::text[], 8.5, '{"poet":"Suna Aras","poet_slug":"suna-aras","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/kizilderili-kadina-turku-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarhoş ettin kız beni', 'sarhos-ettin-kiz-beni-fikret-dundar-1tdxx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kalemin yazmaz oldu,

Haberin varmaz oldu,

Uykular tutmaz  oldu,

Sarhoş ettin kız beni! 

Gülerdin, sen baktıkça,

Yakardın sen yaktıkça,

Sen uzağa kaçtıkça,

Sarhoş ettin  kız beni! 

Erenköy – İstanbul

17.09.2005', 'Kalemin yazmaz oldu, Haberin varmaz oldu, Uykular tutmaz  oldu, Sarhoş ettin kız beni!  Gülerdin, sen baktıkça, Yakardın sen yaktıkça, Sen u...', ARRAY['Türk Edebiyatı','Şiir','Fikret Dündar']::text[], 8.5, '{"poet":"Fikret Dündar","poet_slug":"fikret-dundar","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sarhos-ettin-kiz-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben böyleyim işte', 'ben-boyleyim-iste-fikret-dundar-v2u2t', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben böyleyim 

Ben böyleyim işte! 

İster,  fırlat uzağa.

İster, böyle kabul et,

Bas git sıcak bağrına!', 'Ben böyleyim  Ben böyleyim işte!  İster,  fırlat uzağa. İster, böyle kabul et, Bas git sıcak bağrına!...', ARRAY['Türk Edebiyatı','Şiir','Fikret Dündar']::text[], 8.5, '{"poet":"Fikret Dündar","poet_slug":"fikret-dundar","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ben-boyleyim-iste-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çokkkk / uzaklara', 'cokkkk-uzaklara-guler-atas-hxayl', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Afet bir rüzgar çıksa

Sürüse beni......

                 

Öpsen.....

                Canlansam dudaklarında

Titrek

          Ürkek

                    Ama cesur...........

Vatan  gibi

                  İnsan gibi

                               Kadın gibi koksam

Alsam seni yaban ellerden

Sürgünde kalmasan

             Başı dik

                           Yiğitçe

                                       İnsan gibi

Bitse özlemin ülkene

                                      

                                                22/05/2005', 'Afet bir rüzgar çıksa Sürüse beni......                   Öpsen.....                 Canlansam dudaklarında Titrek           Ürkek          ...', ARRAY['Türk Edebiyatı','Şiir','Güler Ataş']::text[], 8.5, '{"poet":"Güler Ataş","poet_slug":"guler-atas","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/cokkkk-uzaklara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Yapsam Bilmiyorum-! ! ! Bilinen SıR! ! !', 'ne-yapsam-bilmiyorum-bilinen-sir-ahmet-kesici-cvk9e', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '! ! ! Bilinen SıR! ! ! 

İlk tanıştığımız günden bahsetsem, 

aklına hep sakarlıklarım geliyor. 

Mutlu bir anımızı hatırlatsam, 

ağzından tek kelime çıkmıyor. 

Ne zaman seni neşelendirmeye çalışsam, 

yüzünde var olan tebessüm de kayboluyor. 

Ne yapsam,bilmiyorum 

sana böyle ne oluyor? ? ? 

Kırmızı bir gül alıp yanına gelsem, 

adeta bakışlarınla kokluyorsun 

Güzel bir söz söylesem, 

en son anlaması gereken kişiymiş gibi duruyorsun 

Elimi uzatıp da elinden tutsam, 

soğukluğunla yüreğimi yakıyorsun 

Ne yapsam bilmiyorum,

Seviyorum desem,,, 

zaten çok söylemiştim,,,belki bıkmıştır bu sözden. 

Ayrılık isteyip de tenkit etsem, 

korkuyorum,biliyorum ki artık bıktın benden. 

Bir sırrımı söylesem,,? Öleceğim desem,! ! ! 

umurunda olur mu ki,? .zaten bıkmış bu can bu bedenden... 

Ne yapsam bilmiyorum, 

seni çok Seviyorum,... 

Ahmet Kesici

AHMET KESİCİ', '! ! ! Bilinen SıR! ! !  İlk tanıştığımız günden bahsetsem,  aklına hep sakarlıklarım geliyor.  Mutlu bir anımızı hatırlatsam,  ağzından tek ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kesici']::text[], 8.5, '{"poet":"Ahmet Kesici","poet_slug":"ahmet-kesici","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/ne-yapsam-bilmiyorum-bilinen-sir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüz Sürsem Eşiğine', 'yuz-sursem-esigine-muzaffer-tekbiyik-sz353', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seni seven bu alemde,bir başkayı yar etmez

Hangi göz seni görür,bağrı yanıp har etmez

Cihan denen gülşende,güzeller başka başka

Kara gözlü,gül yüzlü,aşka giriftar etmez

Yüz sürsem eşiğine

Vallahi hiç ar etmem

Ölsem hergün uğruna

Asla intizar etmem

Gece gündüz demeden,yüz sürsem eşiğine

Bu can asla kapından,hiç terki diyar etmez

Senin aşkın sevdayı,sultanlara şah eder

Aşkın için çırpınsam,gönlüm asla ar etmez

Yüz sürsem eşiğine

Vallahi hiç ar etmem

Ölsem hergün uğruna

Asla intizar etmem

Kimki senin gölünün,kapısını çalarsa

Seni bir an sevse bile,vallahi zarar etmez

Sana kader,sana gam,sana melekler tutkun

Bilmem ama hiç kimse,böyle intizar etmez

Yüz sürsem eşiğine 

Vallahi hiç ar etmem

Ölsem hergün uğruna

Asla intizar etmem

(17.08.2005)', 'Seni seven bu alemde,bir başkayı yar etmez Hangi göz seni görür,bağrı yanıp har etmez Cihan denen gülşende,güzeller başka başka Kara gözlü,g...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Tekbıyık']::text[], 8.5, '{"poet":"Muzaffer Tekbıyık","poet_slug":"muzaffer-tekbiyik","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yuz-sursem-esigine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mechula dönen aşkım.', 'mechula-donen-askim-gulnare-leman-xfx93', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yaşam boyu  neyi sevdim 

Biliyormusun? .....

Ben seni sevdim,sensin diye.

Kalbimi sevdim....

Seni ölümüne  sevdi diye.

Yarınlarımı sevdim...

Umutlarımı sevdim..

Bir gün beni seversin diye.

Denizlere yelken açtım,

Yakamozları sevdim,

Saatlerle seyre daldım..

Mavi gözlerine benziyor diye.

Ben geceleri sevdim....

Yıldızlara benziyorsun diye.

İlk önce yıkılmağı  hak ettim..

Sonra kalkmağı başardım,

Bir daha düşmeyeyim diye.

Alevlere tutuştum...acılar çektim...

Sana aşık oldum diye.

Daha sonra terk edilmeği..

Sayende unutulmağı da öğrendim..

Ama ben unuta bilmedim..

Kalbim seninle atıyordu diye.

Ben sensiz acıları taşırken....

Sen sevgini eğlence eğledin

Ben daha yoktum diye.

Ama neden hiç düşünmedin

Bir gün sen de seveceksin..

Cehennem yağmurlarına düşecek

Kurtulmak isteyeceksin..

Onlar benim gözyaşlarım diye.

Kolaymı sandın kaçmayı...

Ben  gönlümü vermedim kimseye

Seni görürler orada diye.

Ben bu dünyayı sevdim..

Sen varsın  diye.

Şimdi söyle....

Can bedensiz,beden kalbsiz..

Kalbim  sensiz  nasıl yaşar...

Ey mechula dönen  aşkım? ...

22.XII.2005', 'Yaşam boyu  neyi sevdim  Biliyormusun? ..... Ben seni sevdim,sensin diye. Kalbimi sevdim.... Seni ölümüne  sevdi diye. Yarınlarımı sevdim......', ARRAY['Türk Edebiyatı','Şiir','Gulnare Leman']::text[], 8.5, '{"poet":"Gulnare Leman","poet_slug":"gulnare-leman","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/mechula-donen-askim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arar durur', 'arar-durur-fikret-dundar-s47iu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Geçti gitti bir ömür öylesine,

Hiç de anlamadan, telaş içinde.

Gönül,  fasl -ı baharı arar durur,

Başka bir fasl - ı baharın içinde.

Onu nasıl, nasıl avutabilirsin ki? 

Fasl - ı bahar  yine gelecek diye.

Fasl-ı bahar da, arar baharını 

Başka bir fasl-ı baharın içinde.

Erenköy – İstanbul

09.03.2005', 'Geçti gitti bir ömür öylesine, Hiç de anlamadan, telaş içinde. Gönül,  fasl -ı baharı arar durur, Başka bir fasl - ı baharın içinde. Onu nas...', ARRAY['Türk Edebiyatı','Şiir','Fikret Dündar']::text[], 8.5, '{"poet":"Fikret Dündar","poet_slug":"fikret-dundar","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/arar-durur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ZaMaN TüNeLi,', 'zaman-tuneli-mine-ozdemirtas-12inm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'zamanı durdurun demiş hatunun biri

inecekmiş durakta ve

yürüyecekmiş geri.

güler misin, ağlar mısın

tanrım 

işte tam bir deli

nasıl durduralım ki 

asırları yüklenmiş şu koskoca treni.

atla desem.! 

korkarım

ya... atarsa kendini

kal desem

isyan çıkaracak

besbelli

bir an önce akıl edip

kolundaki saatten çıkarsa ya şu pili

sadece 

dürmek kalır defteri

bir de 

not düşülür üstüne

firar nedeni

............

şüpheli

22/12/2005', 'zamanı durdurun demiş hatunun biri inecekmiş durakta ve yürüyecekmiş geri. güler misin, ağlar mısın tanrım  işte tam bir deli nasıl durdural...', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/zaman-tuneli-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sosyete Gençlik-1 (Hiciv) Dam Üstünde Saksağan', 'sosyete-genclik-1-hiciv-dam-ustunde-saksagan-kemal-tahir-ozcan-vo24a', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yaşamanın tadını, çıkarmaya bakarız.

Bir yerde çok duramaz, sıkılırız,bıkarız.

Gece yarılarında, yarışlara çıkarız,

Bize derler bırakın,tembel tembel gezmeyi,

Dam üstünde saksağan, vur beline kazmayı.

Ekmek elden su gölden, yaşıyoruz ne güzel,

Hiç engel tanımıyor, aşıyoruz ne güzel,

Her zaman eğlencede, coşuyoruz ne güzel,

Boşver şimdi laf edip, kükremeyi,kızmayı,

Dam üstünde saksağan, vur beline kazmayı.

Birinci adresimiz, kafeler, diskotekler,

Eğlenceli geceler, canımıza can ekler,

Bak dansa kalkıyorlar, bir içim su bebekler,

Çılgınca eğlenelim, bırakalım sızmayı,

Dam üstünde saksağan, vur beline kazmayı.

Hep uçlarda gezeriz, bilmeyiz orta yolu,

Hayatı herşeyiyle, yaşarız dolu dolu,

Bazen sağcı oluruz, bazen severiz solu,

İstemeyiz üzülmek, istemeyiz üzmeyi,

Dam üstünde saksağan, vur beline kazmayı.

Vatan,millet,sakarya, ilgilendirmez bizi,

Caddelerde gezerken, güzeller dizi dizi,

Kot pantolon ayakta, gömlekler şile bezi,

Sen de gel katıl bize, bırak artık yazmayı,

Dam üstünde saksağan, vur beline kazmayı.', 'Yaşamanın tadını, çıkarmaya bakarız. Bir yerde çok duramaz, sıkılırız,bıkarız. Gece yarılarında, yarışlara çıkarız, Bize derler bırakın,temb...', ARRAY['Türk Edebiyatı','Şiir','Kemal Tahir Özcan']::text[], 8.5, '{"poet":"Kemal Tahir Özcan","poet_slug":"kemal-tahir-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sosyete-genclik-1-hiciv-dam-ustunde-saksagan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öyküm', 'oykum-derya-aslan-jb8yj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Böyle yalnızım her  zaman,

Böyle bir başıma yaralı.

Düşlerim uzak diyarları

Yüreğimde dinmeyen bir sızı

Ve sana olan özlemim köyüm; 

Sis kaplar ulu dağlarını,

Çiğ  taneleri kaplar yaban otlarını

Ve sonra güneş tebessüm eder

Kızıl ufukların ardından.

Isıtır engin yürekleri,

Isıtır eşsiz sevgileri

Ve bir gün daha başlar böyle; 

Kuş cıvıltıları karışır

Irmakların içli melodisine.

Senli günlerde ayaklarım sırılsıklam

Ayaklarım buz keser sabahın seherinde.

Koşar yorulmam,kuzuların peşinde.

Yüreğim öyle hafif öyle kedersiz,

Bedenim öyle dinç öyle tasasız.

Sonra emek ekerim,

Can veririm Toprak Anaya

Mahsulü öyle bereketli öyle yerinde.

Sonra orakla birleştiririm altın başakları

Kağnılarla çekerim harman yerine.

Kurulur düven savrulur başaklar

Ve değirmene yolculuk başlar.

Başlar buğdayın hikayesi ve soframda 

                                   son bulur……', 'Böyle yalnızım her  zaman, Böyle bir başıma yaralı. Düşlerim uzak diyarları Yüreğimde dinmeyen bir sızı Ve sana olan özlemim köyüm;  Sis kap...', ARRAY['Türk Edebiyatı','Şiir','Derya Aslan']::text[], 8.5, '{"poet":"Derya Aslan","poet_slug":"derya-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/oykum-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşam sanatı', 'yasam-sanati-fatma-guven-ciyi7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Zenginlik, yoksulluk değildir, yaşama sanatı.

Değirmenin taşları arasında,

Ezilmemektir önemli olan.

Nice yoksullar vardır ki! 

Değme zenginlerin; 

Keyfinde yoktur onun keyfi.

Nice zenginlerde vardır ki! 

Yoksuldan daha yoksul yaşar sanki....

(21.03.1998)', 'Zenginlik, yoksulluk değildir, yaşama sanatı. Değirmenin taşları arasında, Ezilmemektir önemli olan. Nice yoksullar vardır ki!  Değme zengin...', ARRAY['Türk Edebiyatı','Şiir','Fatma Güven']::text[], 8.5, '{"poet":"Fatma Güven","poet_slug":"fatma-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yasam-sanati-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dar Geliyor Buralar', 'dar-geliyor-buralar-hasan-ulusoy-nuzf3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Örselenen gönüller kırıklığı can yakar

Can yakar canan diye, cana can bildiklerim.

Parsellenen dünyada bir bedenlik yerim var

Gözlerim menziline, özlemle yanmış bakar

Canım seni özledi, dar geliyor buralar

Kahırlanıp  bastığım toprak yorulur şimdi

Hayallerim adressiz illere gönderildi

Toprağın bağrındaki taş kederli yaslıdır

Göklerin anahtarı münkirlerin elinde

Yer yüzü ceviz içi kadar küçücük ve dar

Canım seni özledi, dar geliyor buralar

Yalancı havanlarda, doğruları dövdüler

Tohumun genlerinde, şeytanların izi var

Kozasından çıkarken sersem ipek böceği

Ölüm için kendine bir gölgecik yer arar

Yıllardır hasretine, gönlümü yaktığım yar

Canım seni özledi, dar geliyor buralar.

Gözlerim bir saadet devrini arar durur

Mihnetlerin inanmış gönüllerde işi ne

Avucum kan taşıyor, şeytanın ordusuna

Namlular bana dönük, kurşunlar beni vurur

Vefa mezarlıktadır, ahde değer söz mü var

Canım seni özledi, dar geliyor buralar.

Mabetler meyhaneden feyiz alır ölürken

Tilki başlı çakallar, dünyada düzen kurdu

Sevgi bilmez gönüller, nefes almaz sevdalar

Ağladığım şu gece nasıl nura susamış

Şafaklar bir sevdaya yönelmiş nasıl yanar

Canım seni özledi, dar geliyor buralar.', 'Örselenen gönüller kırıklığı can yakar Can yakar canan diye, cana can bildiklerim. Parsellenen dünyada bir bedenlik yerim var Gözlerim menzi...', ARRAY['Türk Edebiyatı','Şiir','Hasan Ulusoy']::text[], 8.5, '{"poet":"Hasan Ulusoy","poet_slug":"hasan-ulusoy","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/dar-geliyor-buralar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Göz Deyince', 'goz-deyince-kevser-gulistan-cakir-3ogtt', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Göz dediğin

Onunkiler gibi olmalı

Manalı, sevecen, ürkek

Baktığı yeri kavuran

Değdiği yeri eriten

Her dilden konuşabilen...

Işıkta yeşil

Karanlıkta kahverengi

Üstünde renkler deryası

Arkasında umutlar dünyası

İçinde yaşama kıpırtıları

Dibinde hayat çığlıkları

Göz dediğin arkadaş

Onunkiler gibi olmalı...', 'Göz dediğin Onunkiler gibi olmalı Manalı, sevecen, ürkek Baktığı yeri kavuran Değdiği yeri eriten Her dilden konuşabilen... Işıkta yeşil Kar...', ARRAY['Türk Edebiyatı','Şiir','Kevser Gülistan Çakır']::text[], 8.5, '{"poet":"Kevser Gülistan Çakır","poet_slug":"kevser-gulistan-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/goz-deyince-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilir', 'bilir-ugur-aydin-2-j9hbx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'yüreğinde sakladığın duygular va hala

aşk acısı böyle olur cekenler bilir

gözlerinden okunuyor saklamak ne ala

aşk acısı böyle olur cekenler bilir

her gün yanan bedeninden bir parca kopar

ayrılıklar böyle olur cekenler bilir

yüreğide saklasan da gözlerin söyler

unutulmak böyle olur  tatanlar bilir', 'yüreğinde sakladığın duygular va hala aşk acısı böyle olur cekenler bilir gözlerinden okunuyor saklamak ne ala aşk acısı böyle olur cekenler...', ARRAY['Türk Edebiyatı','Şiir','Uğur Aydin 2']::text[], 8.5, '{"poet":"Uğur Aydin 2","poet_slug":"ugur-aydin-2","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bilir-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nazar', 'nazar-kemal-tahir-ozcan-hnpbt', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sana bir nazar etsem, hicabım ayaklanır.

Korku duyar hasretim, yüreğime saklanır.

Kirpiğini görmeye, bir türlü katlanamaz,

Çektiğim kara sevda, utancımla aklanır.', 'Sana bir nazar etsem, hicabım ayaklanır. Korku duyar hasretim, yüreğime saklanır. Kirpiğini görmeye, bir türlü katlanamaz, Çektiğim kara sev...', ARRAY['Türk Edebiyatı','Şiir','Kemal Tahir Özcan']::text[], 8.5, '{"poet":"Kemal Tahir Özcan","poet_slug":"kemal-tahir-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/nazar-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özgürlük İsteyen Sevgiliye', 'ozgurluk-i-steyen-sevgiliye-kevser-gulistan-cakir-r8ct1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir gün

Yüreğimde kendini bulamayacaksın

Aniden vurup kapıyı gideceğim

O, en şaşkın sabahın olacak

Alışmıştım diyeceksin

Yollara düşeceksin

Tükeneceksin...

İstasyonlarda gözlerin 

Beni seçmeye çalışacak

Yolcular arasından

Sonra hatıralar gelecek

Gözlerinin önüne

Sana trenle gelişim her perşembe

İstemesen de kulağına çok uzaklardan

Bir türkü gelip dayanacak nasılsa

Yüreğin arı kanadı gibi çırpacak

Artık seni sevmediğimi

Ve asla

Geri dönmeyeceğimi bildikçe

Kahrolacaksın...

Bir gün yüreğimde

Heyecanını bulamayacaksın

Dolaşacaksın yollarda perişan

Ara sıra bir genç kızın

Omuzuna gidecek ellerin

Ben sanacaksın

Utanacaksın...

Bilmem niye sevmiştim diyeceksin

Bu kadar derin

Ve neden

Hep kaybettikten sonra

Farkına vardım kıymetinin...

Boş ver

Artık düşünmek nafile

Şimdi

Bütün akşamlar bitti...

İnsanları yalnız bu şehirde

Hepsinden yalnız sen kalacaksın

İşte o zaman sen de

Beni anlayacaksın...', 'Bir gün Yüreğimde kendini bulamayacaksın Aniden vurup kapıyı gideceğim O, en şaşkın sabahın olacak Alışmıştım diyeceksin Yollara düşeceksin ...', ARRAY['Türk Edebiyatı','Şiir','Kevser Gülistan Çakır']::text[], 8.5, '{"poet":"Kevser Gülistan Çakır","poet_slug":"kevser-gulistan-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/ozgurluk-isteyen-sevgiliye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneşe Sarı', 'gunese-sari-ahmet-hani-h9dwn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Soyuqdur hava,

Şaxtadı qardı,

Yaşayış evi,

Qefesdı dardı.

Elimden yapış,

Atları minek,

Güneşe sarı,

Dörd nala gedek.

Kulek sındırır,

Qapı bacanı,

Zulmet alıbdır,

Bütün her yanı.

Elimden yapış,

Atları minek,

Güneşe sarı,

Dörd nala gedek.

Ressam resminde,

Qefes çekmeye.

Hava qalmayıb,

Nefes çekmeye.

Elimden yapış,

Atları minek,

Güneşe sarı,

Dörd nala gedek.

İnanma gülüm,

Gülen üzlere,

Aşaq dağları,

Yenek düzlere.

Elimden yapış,

Atları minek,

Güneşe sarı,

Dörd nala gedek.', 'Soyuqdur hava, Şaxtadı qardı, Yaşayış evi, Qefesdı dardı. Elimden yapış, Atları minek, Güneşe sarı, Dörd nala gedek. Kulek sındırır, Qapı ba...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Hani']::text[], 8.5, '{"poet":"Ahmet Hani","poet_slug":"ahmet-hani","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/gunese-sari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yusuf Olsam Yunus Olsam', 'yusuf-olsam-yunus-olsam-murat-usta-t4rv4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yusuf olsam sende kuyu,

Alsan beni bogarmisin? 

Yunus olsam sende balik,

Yutup beni doyarmisin? 

Ben bir bülbül, sen bir saka,

Pencereme konarmisin? 

Ates olsam sende anka,

Yanip tekrar dogarmisin? 

Ben Istanbul sende Fatih,

Beni fethe cikarmisin? 

Sen Neron ol, bende Roma; 

Gelip beni yakarmisin? 

Sen Azrail ben kul olsam,

Su canimi alirmisin? 

Sultan olsam hem Süleyman,

Dünya bana kalirmisin? 

Sikar olsam sende avci,

Acep beni vururmusun? 

Sen yelkovan ben akrepsem,

Hic yanimda dururmusun? 

Sen ok olsan, bende hedef,

Onikiden vururmusun? 

Bir kaybolsam cocuk gibi,

Arar beni bulurmusun? 

Yola düsüp seyyah olsam,

Bana yoldas olurmusun? 

Cöle düsüp mecnun olsam,

Benim leylam olurmusun? 

Bembeyaz bir bulut olsam.

Yagmur olur yagarmisin? 

Kücük bir karinca olsam.

Yüregime sigarmisin? 

Ölüversem birdenbire.

Cenazeme gelirmisin? 

Mezarima gelip hergün.

Bana Kurán okurmusun? 

                                     

                                        (09.07.2005 – münih)', 'Yusuf olsam sende kuyu, Alsan beni bogarmisin?  Yunus olsam sende balik, Yutup beni doyarmisin?  Ben bir bülbül, sen bir saka, Pencereme kon...', ARRAY['Türk Edebiyatı','Şiir','Murat Usta']::text[], 8.5, '{"poet":"Murat Usta","poet_slug":"murat-usta","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/yusuf-olsam-yunus-olsam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Erken Davranmak', 'erken-davranmak-sultan-mustafa-eipzu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'mezar taşıma

Her gidenin ardından günlerce yanmışım

Az yanmak için önden gitmeye inanmışım

Bilirim dostlar yürekte sızınız var bu gün

Sızlanmamak için size, erken davranmışım.', 'mezar taşıma Her gidenin ardından günlerce yanmışım Az yanmak için önden gitmeye inanmışım Bilirim dostlar yürekte sızınız var bu gün Sızlan...', ARRAY['Türk Edebiyatı','Şiir','Sultan Mustafa']::text[], 8.5, '{"poet":"Sultan Mustafa","poet_slug":"sultan-mustafa","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/erken-davranmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsyan', 'i-syan-saliha-gulenler-8heo4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sevmenin suç sayıldığı

Sevenin ayıplandığı

Küçük dünyalarda

Ben yokum! 

Kalbimin derin okyanusları

Kızgın çöllere dönüştüğünde

Yaşamıyorum! 

Seni sevmek suçsa

Kessinler cezamı

Tanımıyorum!', 'Sevmenin suç sayıldığı Sevenin ayıplandığı Küçük dünyalarda Ben yokum!  Kalbimin derin okyanusları Kızgın çöllere dönüştüğünde Yaşamıyorum! ...', ARRAY['Türk Edebiyatı','Şiir','Saliha Gülenler']::text[], 8.5, '{"poet":"Saliha Gülenler","poet_slug":"saliha-gulenler","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/isyan-128-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eskilerde Kalan..', 'eskilerde-kalan-zeliha-bicer-m48rn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yollarına alıştığınız,taşını toprağını

Gözünüz kapalı yürüdüğünüz

Sokaklarınız olmuştur sizinde.

Manavını bakkalını tanıdığınız simalarınız

Anahtarı kapının üzerinde bırakıp

Bahçe kapısını kilitleyip

Komşuya geçeniniz de vardır.

Değişen ne oldu bunca zamanda? 

Radyolarımız vardı dinlediğimiz

Sohbetlerimiz olurdu

Kuzine sobalarımızda

Kestane kavururduk

Bozacı geçerdi kapı önlerinden

Giysilerin kalitesi değildi kıstasımız

Yamalı da olsa elbisemiz

İnsanı esas tutardık hep birlikte....', 'Yollarına alıştığınız,taşını toprağını Gözünüz kapalı yürüdüğünüz Sokaklarınız olmuştur sizinde. Manavını bakkalını tanıdığınız simalarınız ...', ARRAY['Türk Edebiyatı','Şiir','Zeliha Bicer']::text[], 8.5, '{"poet":"Zeliha Bicer","poet_slug":"zeliha-bicer","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/eskilerde-kalan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Taş Yerinde Duramadı', 'tas-yerinde-duramadi-umut-gungor-u618s', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Taş yerinde duramadı,

Gediğini bulamadı,

Baba ekti toprağını,

Evlat gelip sulamadı.

Yeşertmedi selvi dalı,

Hep bekledi dünya falı,

Baba ekti bahçesini,

Oğul aldı oldu çalı.

İlim bilim okumadı,

Yüreğine dokumadı,

Babasının nasihatı,

Bir gün olsun tutamadı.

Söz sükuta uzak kaldı,

Sarrafını bulamadı,

Evlat fani zevke daldı,

Söz yerini bulamadı.', 'Taş yerinde duramadı, Gediğini bulamadı, Baba ekti toprağını, Evlat gelip sulamadı. Yeşertmedi selvi dalı, Hep bekledi dünya falı, Baba ekti...', ARRAY['Türk Edebiyatı','Şiir','Ümüt Güngör']::text[], 8.5, '{"poet":"Ümüt Güngör","poet_slug":"umut-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/tas-yerinde-duramadi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşünmeden Uyumam Lazım', 'dusunmeden-uyumam-lazim-zeliha-bicer-skmz3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Düşünmeden uyumam lazım

Aklıma seni getirmeden

Özlemini hissetmeden

Denizin kum tanesini

Kendisine çekmesi gibi

Uykunun kollarında 

Gözümü kapamalıyım

Sakın yüreğime oturma bu gece

Bu gece yüküm olmamalı

Bu gece gücüm yok çünkü

Darmadağın olurum sensizlikte

Tek bir çivi tutuyor bedenimi

Dağılırım,kırılırım,incinirim

Uykularıma girme.. sakın girme

Emi......', 'Düşünmeden uyumam lazım Aklıma seni getirmeden Özlemini hissetmeden Denizin kum tanesini Kendisine çekmesi gibi Uykunun kollarında  Gözümü k...', ARRAY['Türk Edebiyatı','Şiir','Zeliha Bicer']::text[], 8.5, '{"poet":"Zeliha Bicer","poet_slug":"zeliha-bicer","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/dusunmeden-uyumam-lazim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Banane', 'banane-muzaffer-tekbiyik-vpmi5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ağaçlar yaprak dökmüş,sonbahar mı ne

Mevsimsiz terk edildim,herşey bahane

Yıllar böyle geçsede,ismin dilime 

Gelmiyor ah vicdansız,senden banane

Yapayalnız kaldım artık yuvada

Gelsende faydasız senden banane

Sensiz bin bahar gelip,bin yaz geçsede

Maziden sildim seni ömür bitsede

Ne resmin kaldı nede bir tek kelime

Kalmadı tek hatıran senden banane

Yapayalnız kaldım şimdi yuvada

Gelsende faydasız senden banane

Paramparça bırakıp bir yaz sabahı

Giderken düşünmedin bir gün eyvahı

Gelsende faydasız bu son baharı

Yaşamak imkansız senden banane

Yapyalnız kaldım şimdi yuvada

Gelsende faydasız senden banane

(11.10.2003)', 'Ağaçlar yaprak dökmüş,sonbahar mı ne Mevsimsiz terk edildim,herşey bahane Yıllar böyle geçsede,ismin dilime  Gelmiyor ah vicdansız,senden ba...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Tekbıyık']::text[], 8.5, '{"poet":"Muzaffer Tekbıyık","poet_slug":"muzaffer-tekbiyik","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/banane-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '-Seni Bulduğun An-', 'seni-buldugun-an-elif-gulay-81ac2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Biryerlerde mi kaybettim sevgileri? 

Yoksa hiçbir zaman olmadılar mı? 

Adını bile anmaya korkuyorum artık korkularımın,

Yıldızlarım kayarken yüreğimden

Dilek bile tutamıyorum onlar için

Çaresiz gökyüzünden inerken güneş 

Bir gözyaşı sesi duyuluyor damlarken yere

Bir elveda bile diyemiyorum gidenlere..

Hayatın kaçınılmazı galiba yalnız olmak

Ya bir gün terkedilmek,

Terkedilmeyi beklemek,

Ya da birdenbire herşeyi terketmek! 

O gün geldiğinde,

Güllerin rengi önemli değil,

Havada uçuşan kuşların yankıları duyulmaz,

Ne ödenecek boçlar,

Ne de geçilecek sınav,

Sonsuzlukta kabolacak! 

Ve gerçekten yalnız başınıza

kendin ve sen kaldığınızda

O ömür boyu aradığın ya da kaçmaya çalıştığın

Sen, sana kavuşacak! 

Kuçak dolusu hayatın avuçlarında..', 'Biryerlerde mi kaybettim sevgileri?  Yoksa hiçbir zaman olmadılar mı?  Adını bile anmaya korkuyorum artık korkularımın, Yıldızlarım kayarken...', ARRAY['Türk Edebiyatı','Şiir','Elif Gülay']::text[], 8.5, '{"poet":"Elif Gülay","poet_slug":"elif-gulay","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/seni-buldugun-an-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Türkülerim', 'turkulerim-halil-soyuer-k8jqt', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Koşar telden tele,dökülür sese

Ben,beni söylerim,türkülerimde

Özlem çağıl çağıl,aşk yığın yığın

Ben,ben,söylerim,türkülerimde 

Gah Emrah olurum,dert ile dolan

Gah bir Köroğluyum,mert ile dolan

Seyrani,Sümmani,Karacaoğlan

Ben,beni söylerim,türkülerimde

Değirmen,değirmen dönen taş,benim

Yaylalar içinde öten kuş,benim

Vatanım,gönlüme oturmuş,benim

Ben,beni söylerim,türkülerimde

Ezo gelin hıçkırırken,derinden

Kalbim parçalanır orta yerinden

Sen de beni söyle bildiklerinden

Ben,beni söylerim,türkülerimde.', 'Koşar telden tele,dökülür sese Ben,beni söylerim,türkülerimde Özlem çağıl çağıl,aşk yığın yığın Ben,ben,söylerim,türkülerimde  Gah Emrah olu...', ARRAY['Türk Edebiyatı','Şiir','Halil Soyuer']::text[], 8.5, '{"poet":"Halil Soyuer","poet_slug":"halil-soyuer","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/turkulerim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Müziğe Aşk', 'muzige-ask-demiss-vangelis-5kpkw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Büyük bir macera

Heyecan ve tutku

Bir aşk benimkisi

Büyük bir aşk

Soluksuz notaların

Bitmeyen kovalamalarını

Hayranlıkla izlemek

Ve dinlemek...

Kuru dudakların çatladığı gibi

Arpejlerin çıtlaması

Majörlerin işvesi, yedililerin cilvesi

Minörlerin cefası, susların sefası

Saman kağıdı üzerindeki 

O silik partisyonlar

Kendini bile okuyamayan...

Soluklanan bir ensturman

Müziğe doyamayan bir adam

Ve ben...

Müziğe aşk

Müziğe aşk...', 'Büyük bir macera Heyecan ve tutku Bir aşk benimkisi Büyük bir aşk Soluksuz notaların Bitmeyen kovalamalarını Hayranlıkla izlemek Ve dinlemek...', ARRAY['Türk Edebiyatı','Şiir','Demiss Vangelis']::text[], 8.5, '{"poet":"Demiss Vangelis","poet_slug":"demiss-vangelis","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/muzige-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Omzunda Ağlayacağım', 'omzunda-aglayacagim-rengin-alacaatli-ti9d8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'OMZUNDA AĞLAYACAĞIM 

iklimsiz bir şehirde

iplik iplik çözülüyorum

sımsıkı sarıl bana

omzunda ağlayacağım

tel tel dökülüp

sırlarımı açacağım

öksüzlüğümü

yetimliğimi

akıtacağım gözyaşımda

düşlerimin gizeminde

tuzumun tadında

sarıl bana

kavrulmuş yüreğimin 

yanık kokusunda

omzunda ağlayacağım

dramdan komedi 

çıkarma çabamın

yorgunluğunda,

umutlarımın 

tükendiği anda

sarıl bana

kurmaca yaşamın

kıyısından uzan bana

omzunda ağlayacağım

RENGİN ALACAATLI', 'OMZUNDA AĞLAYACAĞIM  iklimsiz bir şehirde iplik iplik çözülüyorum sımsıkı sarıl bana omzunda ağlayacağım tel tel dökülüp sırlarımı açacağım ...', ARRAY['Türk Edebiyatı','Şiir','Rengin Alacaatlı']::text[], 8.5, '{"poet":"Rengin Alacaatlı","poet_slug":"rengin-alacaatli","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/omzunda-aglayacagim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşte hayatım', 'i-ste-hayatim-elazigli-mustafa-kaya-ms30t', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'işte hayatım, 

soluk bir fon. 

hüzünsüz 

ve ağlamasız 

çok az gün. 

ve, 

ince bir istihza 

hayattan

bin acılı yastığa 

düştü yine başım. 

sığınacak bir oda ancak, 

kaçış ihtiyacım. 

dört duvarın örtüleri 

siyah yalnızlık.. 

bir garip sürgün 

kaldığım rutubetli oda. 

içimde bir gemi 

batıp çıkmakta 

ve, 

gurbet ellerine 

yelken açmış dünyam

mutluluktan yoksun. 

kötü oyuncaklar 

peşinde koşan çocukluğum, 

yamalı pantolonlu gençliğim

bir şehrin varoşlarında

sancılı büyümüşlüğüm

bir aşkı itiraftan korktuğum

imkansız umutlarımı

kalbimden sorun.. 

Mustafa kaya

23.12.2005 / Üsküdar

www.mustafakaya.net', 'işte hayatım,  soluk bir fon.  hüzünsüz  ve ağlamasız  çok az gün.  ve,  ince bir istihza  hayattan bin acılı yastığa  düştü yine başım.  sı...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/iste-hayatim-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarın', 'yarin-elazigli-mustafa-kaya-150l8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'yarın,

uçacağım üşümüş ruhuna.

başını sineme alacağım

ilk güneş ışınlarıyla.

ve,

temiz kalbine bir güvercin

yuva kurmuş 

susuz ve yemsiz.

oturup bir mindere.

kokusunu sereceğim sahillerin

ve o ağacın dertli yalnızlığını

dinleyeceğim sessiz.

eski ve yeni

kaplayacak bizi

dün, bugün ve 

yarın …

Mustafa kaya

22.12.2005 / eyüp

www.mustafakaya.net', 'yarın, uçacağım üşümüş ruhuna. başını sineme alacağım ilk güneş ışınlarıyla. ve, temiz kalbine bir güvercin yuva kurmuş  susuz ve yemsiz. ot...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/yarin-34-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdadandır...', 'sevdadandir-aysun-erat-l13bi', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevdadandır bendeki hoşluk

Başka şeyler sanılmaya sakın! 

Her tanrının günü

Denizi daha çok maviye boyayışım,

Yıldız serpişim gündüz vakti gökyüzüne,

Bütün çiçeklerden medet umuşum,

Güzel günlere öykünüşüm,

Türlü hayallere kapılıp 

Dalıp dalıp gidişim de,

Gülümseyişim de durup dururken,

Sevdadandır hep.

Böyle biline! 

12/2005', 'Sevdadandır bendeki hoşluk Başka şeyler sanılmaya sakın!  Her tanrının günü Denizi daha çok maviye boyayışım, Yıldız serpişim gündüz vakti g...', ARRAY['Türk Edebiyatı','Şiir','Aysun Erat']::text[], 8.5, '{"poet":"Aysun Erat","poet_slug":"aysun-erat","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sevdadandir-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölgün bir mum', 'olgun-bir-mum-elazigli-mustafa-kaya-czwdo', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ateş yanıyor sokakları

şehrin.

her yanımda karanlıklar.

gözlerindeki ışığı aradım

gözlerine iyi bak

onlar,

ölgün bir muma 

dönüşmesin.

usançsız döndüm

deniz kenarlarından.

geceye çağrıldım

yapayalnızım

hasretim bir yıldıza 

soğuk yağdırıyor gök

yine,

bir mum ışığına asılı

kaldı sevdam

titrek ve zayıfca.



Mustafa kaya

22.12.2005 / KADIKÖY

www.mustafakaya.net', 'ateş yanıyor sokakları şehrin. her yanımda karanlıklar. gözlerindeki ışığı aradım gözlerine iyi bak onlar, ölgün bir muma  dönüşmesin. usanç...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/olgun-bir-mum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlüyorum Eski Sokakları', 'ozluyorum-eski-sokaklari-hatice-bediroglu-9q5dq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yüzyıllar önce bestelenmiş bir müzik

Nasıl da boğuyor beni onca hüzne 

Hüzün mü bize en çok yakışan

Biz mi sevdik hüznü millet olarak 

Fırtına ıslık çalıyor dışarıda

Camları çiziyor yağmur ince ince 

Nasıl da yapayalnız hissediyorum

Bir uçuruma düşüyormuşum gibi 

Hangi dala tutunsam kopacak

Sürüklenecek... 

Bilinmez bir karanlığa ellerimde

Özlüyorum...

Kıvrım kıvrım dans eden

Ucu görünmeyen eski sokakları 

Sarı ışık yayan sokak lambalarını

Yakın olduğu sesinden belli 

Çeşmenin şıkırtılarını

Cumbalı evin taş duvarından

Kırıta kırıta boynunu uzatmış 

Mor salkımlı koca koca dalları

Penceresinden...

İri kara gözleriyle sokağı seyreden 

Her gün ekmeğini aldığım 

Boğazı urlu Ayşe teyzeyi 

Evinin içindeki 

Yaşanmışlıkların eski kokusunu

Düzensiz Arnavut kaldırımlarını

At arabalarının bildik seslerini 

Mangal ve mis gibi kahve kokusunu 

Karlı buzlu titreyen gecelerde 

Boza satan Mustafa amcayı 

İşliyor işte müzik işliyor 

Dalga dalga ruhuma 

Anlamıyorum kelimelerini

Olsun ne önemi var

Özlemin yürekteki ıssızlığı çalıyor kapımı 

Kucaklıyor sevdamın kolları sımsıkı 

Müziğin lezzeti. 

Doluşuyor gözpınarlarıma 

'' Düş Kuruyor Gece '' adlı kitabımdan - Ocak 2008 - 

www.haticebediroglu.net', 'Yüzyıllar önce bestelenmiş bir müzik Nasıl da boğuyor beni onca hüzne  Hüzün mü bize en çok yakışan Biz mi sevdik hüznü millet olarak  Fırtı...', ARRAY['Türk Edebiyatı','Şiir','Hatice Bediroğlu']::text[], 8.5, '{"poet":"Hatice Bediroğlu","poet_slug":"hatice-bediroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/ozluyorum-eski-sokaklari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kesmezdi beni..', 'kesmezdi-beni-hasan-esat-heptunali-s0mhw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'akşamları kül kokardı

ve bolca alkol tabii ki

sarı lambalar altındaki bu viranenin....

en azgın ayyaş hallerim bile kesmezdi beni

gecenin ince kesikleri kadar...

ne bir damla kan...

ne de bir damla göz yaşı...

sadece suskunlukların en ağırı....', 'akşamları kül kokardı ve bolca alkol tabii ki sarı lambalar altındaki bu viranenin.... en azgın ayyaş hallerim bile kesmezdi beni gecenin in...', ARRAY['Türk Edebiyatı','Şiir','Hasan Esat Heptunalı']::text[], 8.5, '{"poet":"Hasan Esat Heptunalı","poet_slug":"hasan-esat-heptunali","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kesmezdi-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıllar Geçti Bir Hediye Almayalı', 'yillar-gecti-bir-hediye-almayali-melih-coskun-sj143', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yıllar geçti bir hediye almayalı 

Ellerini getirsen yeterdi bana

Yüzüme sürseydim uzun uzun 

Varsın son günüm olsun bu deseydim

Varsın son günüm olsun 

Ne için yaşar ki insan 

Aşk için ölmek te 

Yaşamak kadar kutsaldır

Ellerini getirseydin sadece diyorum 

Gözlerine baksaydım uzun uzun 

Hiçbir zaman yazmadığım güzellikte 

Bir şiir yazsaydım o anda sana 

Dökseydim içimdeki milyonlarca dizeyi ayaklarına 

Böyle olduğuma bakma 

Çocuk olmayı unutturdular çoktan bana 

Öğretmediler korkmadan bir sevgiyi söylemeyi 

Ne zaman gözlerin gözlerime değse 

Kaçırırdım bakışlarımı büyük bir günahtan kaçar gibi 

Yüzüme baksan yeterdi 

Uzun uzun ve hiçbir şey söylemeden 

Bana çocukluğumu hatırlatsaydın 

Anlatsaydın nasıl söylenir bir sevda

Dedim ya 

Yıllar geçti bir hediye almayalı 

Ellerini getirsen yeterdi

İnsan yanımı hatırlatmak için yeniden bana...', 'Yıllar geçti bir hediye almayalı  Ellerini getirsen yeterdi bana Yüzüme sürseydim uzun uzun  Varsın son günüm olsun bu deseydim Varsın son g...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/yillar-gecti-bir-hediye-almayali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılıklar Şimdi Bize Koymuyor', 'ayriliklar-simdi-bize-koymuyor-nesrin-gocmen-np96r', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yazgıya isyanım bitti bu gece

Yerleşmiş tüm taşlar bir bir oynuyor

Deşilen boşluklar sanki bilmece

Ne şiir, ne gönül aşka doyuyor... 

.

Kaybolan umutlar geri gelmişler 

Bulutlar dağılıp hüznü delmişler

Yağmurlar kıskanıp sarhoş olmuşlar

Gökyüzü boyansa hüsran olmuyor

.

Asılan tüm yüzler gülmüş yuvamda

Uzanan ellerim kalmaz havada

Bahçelerim değil ıssız bir ada

Tomurcuk çiçekler kışın solmuyor

.

Şefkatle silindi gamlar, kahırlar

Barış doğumunda bitti zehirler

Sevgimizle doldu, taştı nehirler

Tadını bilenler içip aymıyor

.

Kahkahalar uçar gülen dudaktan

Yarının şarkısı çınlar uzaktan

İçmişiz güveni aynı bardaktan

Ayrılıklar şimdi bize koymuyor

.

22 Aralık  2005', 'Yazgıya isyanım bitti bu gece Yerleşmiş tüm taşlar bir bir oynuyor Deşilen boşluklar sanki bilmece Ne şiir, ne gönül aşka doyuyor...  . Kayb...', ARRAY['Türk Edebiyatı','Şiir','Nesrin Göçmen']::text[], 8.5, '{"poet":"Nesrin Göçmen","poet_slug":"nesrin-gocmen","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/ayriliklar-simdi-bize-koymuyor-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
