INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiir Deposu', 'siir-deposu-meral-vurgun-qfm3b', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şiir Deposu

(Zum Alte Schluch)

boşuna bir kolaylık arıyorum

dağılmalar buluyorum biraz

çevirirken Nazım Hikmet’in lirik sayfalarını 

meyhane kapısında Noel donanımları

gece katlamış kendini güne

oturuyorum bilinmeyen bir ahşap bank üstünde

bira kavranmaya hazır, duruyor önümde

olsaydı keşke bir şiir deposu

dolması için boş kafalarımızın

uygun bir zaman

bakışlarım ayrılmıyor servis kadının dolgun kıçından

gözleri temelli yanmış, gülümseyen ağzı 

ayça gibi 

meyhane kısa bir hortum

selamet

boşuna kolaylık arıyorum

düşünceler sessiz ve tedirgin meyve sinekleri gibi

geçiyor ruhumun önünden

yolculuk bu günden yarına 

huzursuzluktur

bilinmeyen ahşap bir bankta oturan 

bira bardağına hazırlanan bir misafirim

Nazım Hikmet lirikleri gözler önünde

garson kadının dolgun kalçası gibi mi? 

olsaydı bir şiir deposu keşke dolması için

boş kafalarımızın

uygun bir zaman

yabancı insanlar dokunuyor duygularıma

sanki bir sanat eseriymiş gibi şefkatle düzenlenmiş 

bir serginin 

meyhane masalarında gaz lambaları yanıyor

kendini kasan bir kadının boş göbeği 

anne bebeğini alıyor pusetinden 

göğsünde sallıyor

küçük yaratık yakalıyor bir parmağını

ışıldıyor gözlerimiz

gece günü getirdiğinde

donatılmış şehrin soğuk kışında 

boşuna bir kolaylık arıyorum

kronik bir dumağı altında inliyor ruhum

olsaydı bir şiir deposu dolması için 

boş kafamın 

uygun bir zaman

Ralph Raske

Çeviren Meral Vurgun

(Zum Alte Schluch)   =Şiirdeki meyhanenin ismi

Die Poetentankstelle

(Zum Alte Schluch)

Vergeblich suche ich die Leichtigkeit

finde etwas Zerstreuung beim Blättern durch die Lyrik

von Nazim Hikmet

weihnachtliche Illumination vor der Kneipentür

die Nacht hat sich den Tag gepackt

ich sitze auf einer verwetzten Holzbank

das Bier griffbereit vor mir

gäbe es doch eine Poetentankstelle für das Auftanken

unserer leeren Köpfe

zu gegebener Zeit

an dem opulenten Arsch der Bedienung kommen meine

Blicke nicht vorbei

ihre Augen sind ständig entzündet, und ihr lächelnder Mund

wie eine Mondsichel -

die Kneipe ein kurzer Schlauch

Geborgenheit

Vergeblich suche ich die Leichtigkeit

Gedanken huschen wie lästige Fruchtfliegen vor meinem

Geist

die Reise vom Heute in das Morgen

ist Unruhe

bin ich der Gast, der auf der verwetzten Holzbank sitzt

das Bierglas ansetzend

die Lyrik von Nazim Hikmet vor Augen

wie den opulenten Arsch der Bedienung? 

gäbe es doch eine Poetentankstelle für das Auftanken

unserer leeren Köpfe

zu gegebener Zeit

die fremden Menschen rücken in mein Gefühl

als wären sie Kunstwerke einer liebevoll arrangierten

Ausstellung

Öllampen brennen auf den Kneipentischen

der freie Bauchnabel einer Frau, die sich streckt

die Mutter hebt das Baby aus dem Kinderwagen

und wiegt es an ihrer Brust

das kleine Wesen fasst sich einen Finger

unsere Augen leuchten

Die Nacht, die den Tag geholt hat

die Kälte der illuminierten Stadt im Winter

vergeblich suche ich die Leichtigkeit

ich leide unter einem chronischen Katarrh der Seele

gäbe es doch eine Poetentankstelle für das Auftanken

meines leeren Kopfes

zu gegebener Zeit

Ralph Raske', 'Şiir Deposu (Zum Alte Schluch) boşuna bir kolaylık arıyorum dağılmalar buluyorum biraz çevirirken Nazım Hikmet’in lirik sayfalarını  meyhane...', ARRAY['Türk Edebiyatı','Şiir','Meral Vurgun']::text[], 8.5, '{"poet":"Meral Vurgun","poet_slug":"meral-vurgun","theme":"Türk Şiiri","is_hero":false,"total_lines":95,"source_url":"https://www.antoloji.com/siir-deposu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mülâhaza', 'mul-haza-cahit-pehlivan-qmn8s', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir cam önünde oturuyorum.

Dudağımda da sigaramı içiyorum.

Dirseğim cam kenarında iken.

Elimde kalem, bir şeyler yazıyorum.

Kalemim, kağıdıma birşeyler yazar,

Benim mülâhazamı, yalnız o anlar.

Kalbim gibi temiz olan kağıdıma,

Mülâhazamı, oya oya oyalar.

Mülâhazamı arıyordum, şimdi burada,

Bazen sigaramın dumanında,

Bazen satırlarımı yazan kalemin,

Kirpiklerin gibi olan, ipincecik ucunda.

Ah! ... bu mülâhazamı anlatamam,

Bir dilenci misali, kimseciklerden de,

El açıp, ne saadet, nede aşk aramam,

Ben buyum işte, başkada olamam.

Ayakta duruyoruz, işte yine sen olmadan,

Sensiz olan ben ve mülâhazam.

Kars', 'Bir cam önünde oturuyorum. Dudağımda da sigaramı içiyorum. Dirseğim cam kenarında iken. Elimde kalem, bir şeyler yazıyorum. Kalemim, kağıdım...', ARRAY['Türk Edebiyatı','Şiir','Cahit Pehlivan']::text[], 8.5, '{"poet":"Cahit Pehlivan","poet_slug":"cahit-pehlivan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/mulahaza-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tarık Akan', 'tarik-akan-yusuf-ter-pvjlt', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bakırköy’de taş okulu

Omuzdan yaralı kolu

Tarık Akan içi dolu

Sanat kokar Tarık akan

Yeşil çamın temel taşı

Yılmaz Güneyin sırdaşı

Sürgün olmuş arkadaşı

Sanat kokar Tarık akan

Mahpusta çeker çileyi

Kitapta kaldı dileği

Bükülmez onun bileği 

Sanat kokar Tarık akan

Yusuf Ter 01.11.05

Saat 22:32 İsviçre', 'Bakırköy’de taş okulu Omuzdan yaralı kolu Tarık Akan içi dolu Sanat kokar Tarık akan Yeşil çamın temel taşı Yılmaz Güneyin sırdaşı Sürgün ol...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ter']::text[], 8.5, '{"poet":"Yusuf Ter","poet_slug":"yusuf-ter","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/tarik-akan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'AşK MaSaLı', 'ask-masali-mine-ozdemirtas-b2d3r', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'sen / hiç kaybolmadın mı yani? 

kendi bozkırlarında gece yarısı

senin göklerine yıldızlar 

hiç mi doğmadı

belki de hep 

karanlığa bakmışsındır da

sadece düşlemişsindir

samanyolunu

bu yüzden görememişsindir

kayan yıldızların da olduğunu

dilekte tutmadın

adakta adamadın öyle mi? 

yani senin

tütün kokan parmakların

hiç papatya yolmadı

öksüz kalan falına

bakan kimse olmadı

öyle mi? 

hiç üşümediyse ayak izlerin

demek ki karda hiç yürümedin

öyle mi? 

hep /minicik  adımlarla  mı / bastın toprağa

hiç mi çakmazsın, hiç mi gürlemezsin.

tamam, 

tamam

rüzgarların şarkısız

mevsimlerin baharsız 

olduğu yerdensin / 

anlıyorum

kuşun kanadından 

nem kapmazsın

hiç üşümez 

hiç ağlamaz

üstelik

aşık ta olmazsın

öyle mi? 

o halde neden kirpikerin nemli? 

neden yanakların ıslandı? 

yoksa! 

çöllere yağmur mu yağdı

23/12/2005', 'sen / hiç kaybolmadın mı yani?  kendi bozkırlarında gece yarısı senin göklerine yıldızlar  hiç mi doğmadı belki de hep  karanlığa bakmışsınd...', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/ask-masali-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dedemin Hizmetindeyim.', 'dedemin-hizmetindeyim-cahit-pehlivan-g80fr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ne oldu bugün  neden güneş doğmuyor? 

Bir kara bulut çöktü köye, neden  gitmiyor? 

Cenazemi  var?  Hoca  sela veriyor.

Tanrım, bu fani dünyadan kim gidiyor? 

Sabahın  mahmurunda, gözleri ovuşturarak,

Kim öldü, bu selayı  hayra mı, şerre mi yorak? 

Diyerek, gözler yaşarır birbirlerine bakarak

Çok geçmeden çığlıklar gelir, semayı  yırtarak.

Üç beş kişinin elinde var, kürek ile kazma,

Vasiyetin varsa oraya  başlarlar, mezarını kazmaya.

Kürek kürek topraklar atılır kıyıya,

Burada  verileceksin, sadık dostun kucağına.

Mezar hazır olunca imam tekbir alır.

Yıkamak için dedemi, teneşire yatıttırır.

Orada, dedemin  bütün vücudu güzelce yıkanır.

Bu temizlikle de vücudu,  günahlardan arınmıştır.

Hoca ister Dünya''daki gerçek malını,

Verin bana, verin der kefenini.

İyice  beyaza  sararlar  dedemin  her yerini,

Artık  herkes, varsa helal eder sana olan hakkını.

Tutulur donmuş vücudun, konulur tabuta.

Oradan alıp getirirler, cami avlusuna.

Her gelen geçen yolcu, Fatiha okur sana.

Tanrım dedemin günahları af ola.

Abdest  alır  tüm cemaat sıra sıra,

Alanların  kimisi kolunu, kimisi yüzünü kurulamakta,

Cami’nin  içinde de mevlit okunmakta,

Sevabını arz eden, girip içeri oturmakta.

O hoş sesiyle inletir imam cami’yi 

Ne güzel okur mevlidi, şerifi,

Molla durmaz getirir tekbiri, okur  aşiri

Cümle cemaate ettirir tövbesini.

Gelinir mevlidin  ol kısmına,

...............  der hoca bütün mümin kula,

Sonra şeker dağıtılır bütün cemaate,

Tanrım mevlidinizi kabul  kıla.

Kılınır namaz  alınır tekbir,

Salâvat ile tutularak kaldırılır bir bir

Ahiret  yoluna  tabutun  getirilir.

Bu yolda  yavaş adımlarla  gidilir.

Getirilsin el  üstünde, taşına taşına,

Konur tabutun musalla taşına,

Kılınır namazın tabutun başında,

Orada helalleşirsin bütün cemaatle.

Kaldırılınca gelirsin ebedi istirahate,

Kimi elinden, kimi ayağından  tutar,

Koyarlar senin vücudunu özenle,

Allah yerinde rahatlık vere.

Dolaşır ruhun etrafımızda,

Bakarsın kim güle, kim ağlaya,

Bir grup Müslüman kürek başında,

Mezarını, toprakla kapatmakta.

Atılır naciz  vücuduna  topraklar,

Sona erer artık  ağlaşmalar.

Getirilen sular koyulur kabrine,

Allah sana, kabir rahatlığı vere.

Hoca yapar talgun’unu  tümseğinde

Oradan gelenler bulunurlar, başsağlığı dileğinde

Bu acıya Tanrım yardım eyleye,

Misafirler artık geçsin içeriye.

O deminde misafirlere kurulur sofra

Gelir yemeklerin tamamıda sofra başına

Yenilir yemek, edilir dua,

Tanrım bunu ziyade kıla.

Herkes yavaş yavaş  evine dağılır.

Seninle geçen günler hatırlanır.

Yaptığın iyiliklerden bahis yapılır.

Fatihalar okunup, okunup ruhuna bağışlanır.

Dedem artık gitti, gelmez bize,

Tatlı dilinde karışmaz söze,

Hakkını helal et hepimize,

Allah’ta seni gani gani rahmet eyleye.        

Merzifon/Amasya', 'Ne oldu bugün  neden güneş doğmuyor?  Bir kara bulut çöktü köye, neden  gitmiyor?  Cenazemi  var?  Hoca  sela veriyor. Tanrım, bu fani dünya...', ARRAY['Türk Edebiyatı','Şiir','Cahit Pehlivan']::text[], 8.5, '{"poet":"Cahit Pehlivan","poet_slug":"cahit-pehlivan","theme":"Türk Şiiri","is_hero":false,"total_lines":73,"source_url":"https://www.antoloji.com/dedemin-hizmetindeyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsan Oğlu!', 'i-nsan-oglu-cahit-pehlivan-y106l', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen ömrünü, hep böyle güler yüzlü mü? 

Sen hayatı, hep böyle üzüntüsüz mü? 

Sen yaşantını, hep böyle kaygısız mı? 

Sürdüreceğini düşünüyorsun? İnsan oğlu! ...

Uyan gaflet uykusundan. Aç gözlerini,

Gör Dünya’daki hakikatleri ve gerçeği.

Belirle ona göre, hayatının ilkelerini,

Düzgün bir yolda, daima ileri,

Gitmek olmalıdır. Tek arzun ve emelin,

İşte o zaman, mutluyum diye bilirsin.

Evreni ve insanları, sevebilirsin.

İzmir.', 'Sen ömrünü, hep böyle güler yüzlü mü?  Sen hayatı, hep böyle üzüntüsüz mü?  Sen yaşantını, hep böyle kaygısız mı?  Sürdüreceğini düşünüyorsu...', ARRAY['Türk Edebiyatı','Şiir','Cahit Pehlivan']::text[], 8.5, '{"poet":"Cahit Pehlivan","poet_slug":"cahit-pehlivan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/insan-oglu-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecenin Dökümü', 'gecenin-dokumu-alev-i-sler-j7aao', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Birlikte yapmıştık gecenin dökümünü

Önümüzde yığınlar damarlarımızdan koparılmış

Yalnızlığa mahkum olmuştuk hep birlikte

Bitmez tükenmez karanlıkları taşıdık

Küçük bir sevinç bile yeterdi belki

Oysa yüzlerimizi sahnelere hapsetmiştik

Oynayanlar bizdik seyredenler biz

Bitirdik kendimizi perdeleri indirdik

Çılgın haykırışlarla aradık birbirimizi

Tam bulduğumuz anda birden kaybettik

Dilsiz tanıklar bıraktık arkamızda

Seslerimizi geniş alanlara gömdük

Kalın çizgiler çektik kısa ömrümüze

Su içtik ırmaktan denizlere döktük

Tarihi sıkıştırdık küçük yüreklerimize

Patlayacak diye umutla bekledik', 'Birlikte yapmıştık gecenin dökümünü Önümüzde yığınlar damarlarımızdan koparılmış Yalnızlığa mahkum olmuştuk hep birlikte Bitmez tükenmez kar...', ARRAY['Türk Edebiyatı','Şiir','Alev İşler']::text[], 8.5, '{"poet":"Alev İşler","poet_slug":"alev-i-sler","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gecenin-dokumu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Muhtaç', 'muhtac-hikmet-uzun-seg9a', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Olmazsa olmasın sarayım taçım,

İdrake ermekti bütün amaçım,

İki cihan için bu devlet yeter,

Açzimi ilandır; sana muhtaçım.', 'Olmazsa olmasın sarayım taçım, İdrake ermekti bütün amaçım, İki cihan için bu devlet yeter, Açzimi ilandır; sana muhtaçım....', ARRAY['Türk Edebiyatı','Şiir','Hikmet Uzun']::text[], 8.5, '{"poet":"Hikmet Uzun","poet_slug":"hikmet-uzun","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/muhtac-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dalındaki Yaprak', 'dalindaki-yaprak-alev-i-sler-marw7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dalındaki yaprak

Güneş vuruyor yüzüne

Gülümsüyorsun

Sen o dalda yüzlerce

O ağaçta binlercesin

Dansediyorsun rüzgarla

Sevinçlisin

Biz insanlar seni gördük

Senden öncekileri

Göreceğiz senden sonrakileri

Yine de sen

O kısacık ömrünle

Gülüyorsun bizlere

Öleceğimize değil

Ölümü bekleyişimize', 'Dalındaki yaprak Güneş vuruyor yüzüne Gülümsüyorsun Sen o dalda yüzlerce O ağaçta binlercesin Dansediyorsun rüzgarla Sevinçlisin Biz insanla...', ARRAY['Türk Edebiyatı','Şiir','Alev İşler']::text[], 8.5, '{"poet":"Alev İşler","poet_slug":"alev-i-sler","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/dalindaki-yaprak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneşin Çocukları', 'gunesin-cocuklari-umut-beylik-n40gr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Arar oldum,

Kaf dağı ardında bir yalnızlık türküsü.

Tutturunca darmadağın kıyamet türkülerini

Yüreğim çarpar 

Kıpır kıpır olurdu.

Anlayamadım ya,

Neyin ne olduğunu.

Hayal sarhoşluğunda 

Güneşin nereden doğduğunu.

Mayışmış coşkuydu erişilmez menzil

Kızıla boyanmış

Çil çil gün doğumu,

Gün batımı.

Kaşarlanmış aşık neyi çaldığını bilemez,

Kim dinler göremez.

Aşina sözlerle türkü tutturur doruklara

Sevdayı anlamadan sevdayı söyler

Nereden duymuş sevdayı

Bülbülmü olmuş gül bahçesinde

Yoksa Mem''mi olmuş 

Cizre yöresinde

Ferman almış kan akıtmış ya Dicle''de.

Kendine kalleş bir cellat gibiydi sözleri

Tüfek çatanlar ezdi geçti 

Bağları,bahçeleri.

Sonradan turna sürüleriyle 

Canlandı yürekleri.

Yılmadan canlandım,aradım 

''''Tanrılardan ateş çaldım''''

Kefensiz bedenlerle yargılandım

Güneşin çocuklarıyla secdeye daldım

Onlara doyamadım,

Onlar insan dı,

Ben de insan kaldım...

(21.03.2004)  

Umut KIYLIK

^^Mitolojiye göre PROMETE, ilk uygarlığın öncüsüdür. Tanrı ZEUS, balçıktan yaratılan insana can vermek için gökyüzünden ateşi çalan PROMETE''yi müthiş bir şekilde cezalandırır. Her sabah bir kartal gelerek Kafkas dağlarında bir kayaya bağlanan PROMETE''nin ciğerlerini söker ve yer; ama PROMETE '' nin Ciğerleri her gece mucizevi bir şekilde yeniden oluşur. 

Bu dehşet verici işkence uzayıp giderken günü birinde ünlü kahraman HERKÜL çıkar gelir ve her sabah PROMETE '' nin ciğerlerini söküp yiyen kartalı öldürür. Böylelikle insanlığa ateş ve ışık getiren PROMETE işkenceden kurtulur, İnsanlık ise ilkellikten uygarlığa adımını atar. 

O gün bugündür PROMETE daima insanlık uğruna çile çeken ve bu uğurda her türlü cevr- ü cefaya katlananların sembolü; Tanrı ZEUS ise zulmün, haksızlığın, keyfiliğin ve zorbalığın timsali olarak anımsanır... ^^', 'Arar oldum, Kaf dağı ardında bir yalnızlık türküsü. Tutturunca darmadağın kıyamet türkülerini Yüreğim çarpar  Kıpır kıpır olurdu. Anlayamadı...', ARRAY['Türk Edebiyatı','Şiir','Umut Beylik']::text[], 8.5, '{"poet":"Umut Beylik","poet_slug":"umut-beylik","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/gunesin-cocuklari-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geçmişte Kalan', 'gecmiste-kalan-alev-i-sler-7dk9l', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yeni şeylerin umuduyla başlayan gün

Kaybolur güneşin batışıyla birlikte

Unutulan bir ayrıntı

Yazılmamış bir kaç yaprak

Vurur damgasını geleceğimize

Varmak için mutlu yarınlara

Karanlığa gömülü bir şeylerin

Eksikliğini duyarız yaşamboyu

Bir saplantıdır artık

Durmadan geriye dönmek arzusu

Hep düşlerimizde kalır

Ayrıntılar ve tamamlanmış satırlar

Sürükleyip götürür günlerimizi

Bir türlü doldurulamayan yapraklar

Bitmeyen bir roman gibidir yaşamak

En güzel sayfalarını aradığımız

Belki de farkına bile varamadan

Atladığımız', 'Yeni şeylerin umuduyla başlayan gün Kaybolur güneşin batışıyla birlikte Unutulan bir ayrıntı Yazılmamış bir kaç yaprak Vurur damgasını gelec...', ARRAY['Türk Edebiyatı','Şiir','Alev İşler']::text[], 8.5, '{"poet":"Alev İşler","poet_slug":"alev-i-sler","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/gecmiste-kalan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kış İndi Yüreğime', 'kis-i-ndi-yuregime-ahmet-hakan-yilmazturk-scku2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'yollar da kapandı, kış indi yüreğime

sokulsun usulca, nefesin bedenime 

buğusu terletsin, çözülsün karım, buzum

hiç görmediğimsin, delice hissettiğim

loş koridorlarda, benim esmer liselim

otuzdört yaşının olgunluğu teninde 

bak yine pişmanım olmayacak şeylerden

buruğum, üzgünüm, insan yanılır bazen

içimden gelen ses benim değilmiş meğer

Aralık 2005', 'yollar da kapandı, kış indi yüreğime sokulsun usulca, nefesin bedenime  buğusu terletsin, çözülsün karım, buzum hiç görmediğimsin, delice hi...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Hakan Yılmaztürk']::text[], 8.5, '{"poet":"Ahmet Hakan Yılmaztürk","poet_slug":"ahmet-hakan-yilmazturk","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/kis-indi-yuregime-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kar Tanesi', 'kar-tanesi-ethem-turan-r2o95', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İnci gibi yağan kar tanelerini seyrediyorum 

Öyle öz gür ve sessizler ki 

Kıskanmadan edemiyorum 

Gecenin sessizliğinde ilerleyen yelkenli gibi

Kopup gitmek geliyor içimden özgürlüğe koşmak 

Cadde lambalarının ışıklarında seyrediyorum

Durup fotoğraflarını çekmek geliyor içimden

Seninle sarmaş dolaş bu ışıkların altında

İnci yağmuruyla örtünmek geliyor 

Bir yere varmamak için yürümek 

Sımsıkı sarılmışçasına

Türkmen kızının elbisesindeki işlemeler geliyor aklıma 

Hani her  bir motifin manası var ya

İşte her lambanın ışığındaki kar tanesinin

Anlamı farklı geliyor bana

Her adımda farklı duygular la dolu 

Yürümek geliyor bu lamba altında

Masum ve sevgi dolu duygularla 

Yaşama isteğiyle doluyorum 

Soğuk kış akşamında 

Isıtıyor içimi  bir o kadarda

Aşık oluyorum 

Baharın çiçekleri yok ortalıkta 

Nede leylaklar açmış baksana

Ağaçların dalları beyaza bürünmüş 

Sanki gelin olacakmışçasına', 'İnci gibi yağan kar tanelerini seyrediyorum  Öyle öz gür ve sessizler ki  Kıskanmadan edemiyorum  Gecenin sessizliğinde ilerleyen yelkenli g...', ARRAY['Türk Edebiyatı','Şiir','Ethem Turan']::text[], 8.5, '{"poet":"Ethem Turan","poet_slug":"ethem-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/kar-tanesi-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçim Burkuluyor Sensiz', 'i-cim-burkuluyor-sensiz-umut-beylik-41qqu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Mevsimler değişiyor bak.

Görüyormusun? 

İçim burkuluyor sensiz

Kimsesiz bir geceye kucak açıyorum

Şimşekler çakıyor

Bir turna sürüsüne takılıyor gözlerim

Ve

Bir ilkbahar yağmuru istiyorum

Ellerin ellerime değsin,

Gözlerin gözlerimde olsun diye

Islanmak istiyorum

Tomurcuklar çiçek açsın

Güle dönsün ağaçlar.

Boynu bükük bir yaprak dalına 

Vursun gün ışığı.

Nasıl olsa sayısızca mevsim değişir

Gün geceye döner 

Sen dönermisin bilmem? 

Şimdi ise,

Karanlık bir ayazdayım

Bir sesini duysam,

Bir yüzünü görebilsem

Kırılgan bir tebessüm düşer yüzümden.

Neleri aldı benden? 

Bu tel örgüler

Neleri yok saydı? 

Bir seni koparamadı içimden

Ne içimden,

Nede Yüreğimden.', 'Mevsimler değişiyor bak. Görüyormusun?  İçim burkuluyor sensiz Kimsesiz bir geceye kucak açıyorum Şimşekler çakıyor Bir turna sürüsüne takıl...', ARRAY['Türk Edebiyatı','Şiir','Umut Beylik']::text[], 8.5, '{"poet":"Umut Beylik","poet_slug":"umut-beylik","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/icim-burkuluyor-sensiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öylesi Ko(r) kusu Uz', 'oylesi-ko-r-kusu-uz-yasemin-sezer-tulgar-9e3qx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Uykulardan sıyrılırken yüzümde susuz soğuk

Silemiyorsa da kuytularımı, yorgun yanlarımı

Tazeliyor ışıyan sabahlara doğan u/mutsuzluğun

Sebepli sanrılarını..

İki adımda bir geri yolunda teselli yoksunu varışsızlığım

Düşüyorum korkmadan, sekmeden tek tökez.

Çoklu kelimeler diziyorum sensizliğime

Sendeleyen mumlarını acımla yaktığım gecelerde

Korkamıyorum artık

Ne çok kara gece

Ne çok yalnızlığım cümle can içinde

Tek korkumu giydim yapıştı üzerime

Kalbe tekmeyi zorluyor kim yanaşır yanarsa iç/ime

Öylesi 

Sus/uz dem

Öylesi

Korkusuzum işte...

Ağırlaşıyor ayaklarım

Yarımlıklarımızı biriktirdiğim hayal kesesinde

Yürümüyorum artık

Dur sus korkma üçgeninde

Kapmaca seyrinde

Her köşe ben yine...

Öylesi

Ko(r) kusu uz

Öylesi...

Öylesi 

Ben

Öylesi

Susuz

İşte...

23.12.2005', 'Uykulardan sıyrılırken yüzümde susuz soğuk Silemiyorsa da kuytularımı, yorgun yanlarımı Tazeliyor ışıyan sabahlara doğan u/mutsuzluğun Sebep...', ARRAY['Türk Edebiyatı','Şiir','Yasemin Sezer Tulgar']::text[], 8.5, '{"poet":"Yasemin Sezer Tulgar","poet_slug":"yasemin-sezer-tulgar","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/oylesi-ko-r-kusu-uz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şehit', 'sehit-sair-ahrazi-f1puv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Işıktan bir tepeydi sanki 

Dün gece gördüğüm o yer:

Serviler içinde bir ay ışığı 

Bir temiz suretti,besbelli ki. 

Islaktı henüz toprağındaki hüznü 

Dökülen yaşlardan mı? Kim bilir? 

Kırmızı güllerle çevrilen mermer: 

Beyaz bir örtüydü sanki,

Şehidin kanıyla örülmüş gibi yer yer. 

Böyle kızıl değildi belki de 

Şehit düştüğü akşam ki mevziler. 

Kim bilir,kimleri bıraktı ardında 

Hangi evinde bir yangın var şimdi 

Koca dünyanın 

Parçalıyor bir anne kendini belkide 

Henüz körpe yaşında bir çocuk 

Bir eş ki,açmış ellerini’’Şehidim! ’’diye. 

Kim bilir kaç bayrak eğdi başını? 

Kaybederken imanlı bir Türk askerini dünya

Kaç yüz ordu kaybetti bir anda! 

Ağlamış bir anne… 

Bir eş haykırmış…Çok mu? 

Nasıl sığmış kabrine? Hayret! 

Semadan bir kubbe yıkılmış gibi

Yatıyor ruhuyla bir şehit

Yatıyor en kızıl akşamlarda.

* * *', 'Işıktan bir tepeydi sanki  Dün gece gördüğüm o yer: Serviler içinde bir ay ışığı  Bir temiz suretti,besbelli ki.  Islaktı henüz toprağındaki...', ARRAY['Türk Edebiyatı','Şiir','Şair Ahrazi']::text[], 8.5, '{"poet":"Şair Ahrazi","poet_slug":"sair-ahrazi","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/sehit-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tek Perde', 'tek-perde-ahmet-hakan-yilmazturk-q0eev', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ayrılık vakti gelince

hayaller yitip gitti önce

arzular köreldi ardından

hiç yaşanmadığı kadar

yoğunlaştı çaresizlik

inanır mıydın bu kadar

ümitsiz kalacağına

tüm yitişler, ard arda

anılarsa saf saf sırada

düğümlenmiş içinde aşklar

Ciğerini dağlamakta

sen doğuştan suçlusun

ilk andan ölüme ağlamaklı

dolu dolu bir oyundun, seyirlik

lakin sahnelendin tek perde

1993', 'ayrılık vakti gelince hayaller yitip gitti önce arzular köreldi ardından hiç yaşanmadığı kadar yoğunlaştı çaresizlik inanır mıydın bu kadar ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Hakan Yılmaztürk']::text[], 8.5, '{"poet":"Ahmet Hakan Yılmaztürk","poet_slug":"ahmet-hakan-yilmazturk","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/tek-perde-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlamı Mazide Kalır', 'anlami-mazide-kalir-kamil-at-l49gy', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kaplumbağa hızı ile 

Menzile giden yolcu

Başı ezelden döner

Her buna rağmen

Kusursuz bilinen dost

Hayatı uzaktan kumandalı

Ezelden beri umarını düşünmez

Neyleyim der

Adayı bağışlayan okyanus

Çemberin sahibi bellidir

Görünmezdir

Kendi kendisini aklayan hırsız

Karayip sahilinde dalgadır

Ayağının dibindeki yol ayrımı

Özür nedamet bilmez beyler

Agoraya düşüp donan Meteor

Parası hemen hemen 

Beyni fakir aristokrat

Damlasını zorlayan bulut

Asimile yoluna düşkün insanlar

Çember daralır

İyesiz çember

Anlamı mazide kalır hayatın.', 'Kaplumbağa hızı ile  Menzile giden yolcu Başı ezelden döner Her buna rağmen Kusursuz bilinen dost Hayatı uzaktan kumandalı Ezelden beri umar...', ARRAY['Türk Edebiyatı','Şiir','Kamil At']::text[], 8.5, '{"poet":"Kamil At","poet_slug":"kamil-at","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/anlami-mazide-kalir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sahibim', 'sahibim-guzin-osmancik-my4ja', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sensin benim sahibim.

Görmediğim her şeyde

Duymadığım her seste', 'Sensin benim sahibim. Görmediğim her şeyde Duymadığım her seste...', ARRAY['Türk Edebiyatı','Şiir','Güzin Osmancık']::text[], 8.5, '{"poet":"Güzin Osmancık","poet_slug":"guzin-osmancik","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/sahibim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayırlara yordu!', 'hayirlara-yordu-mikdat-bal-56hst', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hayallerim  gerçekleşecek midir? 

Hayallerim gerçekleşecek mi? 

Hayallerim  gerçekleşecek! 

Hayallerim gerçekleşe

Hayallerim gerçekleş

Hayallerim gerçekle

Hayallerim gerçek

Hayallerim

Hayalleri

Hayaller

Hayal

Haya

Hay

Hayır

Hayırlar

Hayırlara

Hayırlara yor

Hayırlara yordu

Hayırlara yorduğu

Hayırlara yorduğum

Hayırlara yorduğumu

Hayırlara yorduğumuz

Hayırlara yorduğumuzu

Hayırlara yorduğumuzun 

......................................', 'Hayallerim  gerçekleşecek midir?  Hayallerim gerçekleşecek mi?  Hayallerim  gerçekleşecek!  Hayallerim gerçekleşe Hayallerim gerçekleş Hayal...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/hayirlara-yordu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ulan, dünya değil misin?', 'ulan-dunya-degil-misin-mikdat-bal-0olb8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Üzerime yıkıldın sen

Yeter artık çok oldun sen

Evet,evet bıkıldın sen

Ulan, dünya değil misin? 

Ömrümün son yarısıyla

Başağıyla darısıyla

Yeşiliyle sarısıyla

Solan dünya değil misin? 

Allah bilir doğrusunu

Çoban çalmış sürüsünü

Zalimlerin borusunu

Çalan dünya değil misin? 

Yaktın da çevirdin küle

Gözyaşlarım döndü göle

Genç yaşımda gurbet ele

Salan dünya değil misin? 

Bir gün ömrün sona erer

Ölenler bağrına girer

Saçlarımı birer birer

Yolan dünya değil misin? 

Boynuma yükünü sarıp

Derdinden oldum muztarip

Beni böyle garip garip

Bulan dünya değil misin? 

Güldürmedin beni niçin

Bana mı yetiyor gücün? 

Boğazıma boğmak için

Dalan dünya değil misin? 

Mikdati dal ilimlere 

Değerin yok alimlere 

Sen sadece zalimlere 

Kalan dünya değil misin?', 'Üzerime yıkıldın sen Yeter artık çok oldun sen Evet,evet bıkıldın sen Ulan, dünya değil misin?  Ömrümün son yarısıyla Başağıyla darısıyla Ye...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/ulan-dunya-degil-misin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Mevsim ki', 'bir-mevsim-ki-samiha-i-kbal-i4li1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kanatsız bir demdi

Kara düğüm olmuş duygularla

Bedbinlik  her dem

Fersiz gözlerinde sadece

Gözyaşı vardı çocukların

Ne yapalım yangınını söndürmek için

Kaba eller üzerinde kafatasları

Taşınır bir merminin ışığında ruhlar

Dağınık ve kudsi ve de binlerce.

Sana ne oluyor ey melek

Ters çevir gazab rüzgarını

Meydan okurdum sana olmasa

Olmasa ilahi emir.', 'Kanatsız bir demdi Kara düğüm olmuş duygularla Bedbinlik  her dem Fersiz gözlerinde sadece Gözyaşı vardı çocukların Ne yapalım yangınını sön...', ARRAY['Türk Edebiyatı','Şiir','Samiha İkbal']::text[], 8.5, '{"poet":"Samiha İkbal","poet_slug":"samiha-i-kbal","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bir-mevsim-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sendeki Beni Hatırla', 'sendeki-beni-hatirla-emre-saricicek-7qs4u', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yaşamın kıyısında yüreğim.

Tek ayağım çukurda.

İçimde anlatamadığım binlerce anı

Ve yırtıp atamadığım onlarca mektup.

Silip atamadığım gözyaşlarım.

Terkedilişime değil bu sitem.

Yaşayamadığım bu aşkın izleri belkide.

Yada engin denizlerde yüzen bir gemi.

Neye yararki olmasan bu son baharda.

Benim üzüntüm geçen zamanda.

Bulutlardan süzülen her damla yaşta

Islandığım, sendeki beni hatırla.', 'Yaşamın kıyısında yüreğim. Tek ayağım çukurda. İçimde anlatamadığım binlerce anı Ve yırtıp atamadığım onlarca mektup. Silip atamadığım gözya...', ARRAY['Türk Edebiyatı','Şiir','Emre Sarıçiçek']::text[], 8.5, '{"poet":"Emre Sarıçiçek","poet_slug":"emre-saricicek","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sendeki-beni-hatirla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dileğim', 'dilegim-mustafa-ceylan-exg2r', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çimen yeşil gözlerinde ilk bahar

Ak göğsüne çiçek diye tak beni.

Omuzlarda sarı çiğdem saçların

Tellerinin arasına sok beni.

Ellerinde saatleri tutarsın,

Takvimleri söker söker atarsın,

Pamuk olur, bulutlarda yatarsın

Yorganların arasında yak beni.

Can evimi duman eder gülüşün,

Neden beni böyle yaktın, bir düşün? ! 

Aşkım olsun gece gündüz hep düş''ün

Gözlerinle yıldızlara çak beni.

Çöle yağan yağmur gibi serinsin

Okyanussun, girdap girdap derinsin

Sar bağrına, deli gönlüm sevinsin

Avucunda santim santim sık beni.

Bu Ceylan''ı vuran avcı sensin sen,

Bir kenarda derimi yüz istersen,

Dünya batmaz billah candan seversen

Sevdalandım yollarında yık beni.

(2000)', 'Çimen yeşil gözlerinde ilk bahar Ak göğsüne çiçek diye tak beni. Omuzlarda sarı çiğdem saçların Tellerinin arasına sok beni. Ellerinde saatl...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/dilegim-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duruyor', 'duruyor-mustafa-ceylan-2bf4s', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Boşa çevirmişiz değirmenleri

Şimdi üstümüzde taşı duruyor.

Uğurladık gitti sevgilileri

Şimdi gözümüzde yaşı duruyor.

Nerde göğsümüzde uyuyan güzel? 

Nerde gökyüzünü boyayan güzel? 

Nerde ''gelir diye'' gün sayan güzel? 

Halâ yastığımda başı duruyor.

Bir gece ansızın çalıp kapımı

Alsa baştanbaşa gönül tapumu.

Söyleyin ey dostlar, mutluluk bu mu? ! 

Isırdığı yerde dişi duruyor.

Nerde canımıza can veren güzel? 

Nerde kanımıza kan veren güzel? 

Nerde mevsimlere son veren güzel? 

Halâ başımızda kışı duruyor.

Kışın ortasında güldü açan o,

Sonra yalnız koyup, benden kaçan o,

Bir martı benzeri göğe uçan o

Şimdi kanat kanat işi duruyor.

Nerde oturup ta ağlayan güzel? 

Hasrete karalar bağlayan güzel? 

Nerde gürül gürül çağlayan güzel? 

Beynimde hayâli, düşü duruyor.

Değirmen, değirmen boşa dönüyor

Al, git beni benden; ışık sönüyor.

Hayat bu, anladım, perde iniyor

Ceylan gider amma, eşi duruyor.

(21.03.2001)', 'Boşa çevirmişiz değirmenleri Şimdi üstümüzde taşı duruyor. Uğurladık gitti sevgilileri Şimdi gözümüzde yaşı duruyor. Nerde göğsümüzde uyuyan...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/duruyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deuc', 'deuc-ercan-cengiz-z3mkd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Qom qoma xorti ênê

Meymani serê cımê mı

Ênê sonê marê tırqi wanê

Cımat cımati ser gırêdanê

Allê Qerşi ser nê sonê

İna wanê oligarşiyo çı 

Ez wonı Allê Qêrşi

Dêuci i rınd nasqene

Bono xo qi mara düridero

Rüyê xo qi mara tadaiso

İndi sımarê sawaci

Çiyo dı piso, zalımo

Watênamı na a qı 

Hêntoqı xorti amê qema

Cı beno sa röura bıbo

Bışiyeni qê Alle Qêrşi

Ma zanimı o tersonıqo

Hegai ma qi cêverdeno

Ceniqa xo qi cêverdeno

Hêrdê ma dı nê fındeno 

Tersona bıbo qi remêno.

K-06

Gırs Benê

Wonı qı ni domani 

Cıka röu benê gırs

Bıne orxanora

Lınge xo wecine

K-12

Kata Sêri

Reçi qute jübini

Ezo fıqarı kata sêri 

Ji recı esta

Wane mara nejdiya

Qunnı dıma sonnı

Rocdı sonnı newênı

Taridı sonnı windıbonı

Araqê şaidı monnı

Kor pısman peyser enı

Adır quto zerre mı qızqeno

Hürindiya xodı tadinı

Qunnı rêca binıra

Ai dıma qi xellê sonı 

Reçi qunne jübini

Serê mı tadino

Wesano zımıstano

Teqa mı bırina

Qes çinniyo

Raodı monı

Xetê mıdı qutiqi

Xete mıdı cınauri

Ez qı nabenra veci

İna jübinira beşi.

K-15', 'Qom qoma xorti ênê Meymani serê cımê mı Ênê sonê marê tırqi wanê Cımat cımati ser gırêdanê Allê Qerşi ser nê sonê İna wanê oligarşiyo çı  Ez...', ARRAY['Türk Edebiyatı','Şiir','Ercan Cengiz']::text[], 8.5, '{"poet":"Ercan Cengiz","poet_slug":"ercan-cengiz","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/deuc-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Felek', 'felek-mustafa-ceylan-kyxfz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Nasılsın, nicesin bilmedim gitti

Önüme dağları gerdin be felek.

Koştum gece-gündüz çalıştım, lâkin

Sırtımı yerlere serdin be felek.

Büktürdün boynumu geline, kıza

Tutsağa çevirdin çok ile aza; 

Benzettin inleyen bir dertli saza

Ömrümü tellere verdin be felek.

Ele mutluluklar, bana hep çile

Çile yetmez gibi kapında köle...

Bayramın olsun  bak, düşmüşüz dile

Aşkın defterini dürdün be felek.

Ferhat, Mecnun değil garip Ceylan''ım

Verdiğin dert ile sızlar her yanım.

Unutma taş değil ben de insanım

Kanıma sonunda girdin be felek...

Ceylanı yerlere serdin be felek...

(Mart 2001)', 'Nasılsın, nicesin bilmedim gitti Önüme dağları gerdin be felek. Koştum gece-gündüz çalıştım, lâkin Sırtımı yerlere serdin be felek. Büktürdü...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/felek-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim yontma taş devrinden beri başım dönüyor', 'benim-yontma-tas-devrinden-beri-basim-donuyor-yalcin-bayar-0n4ev', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'BENİM YONTMA TAŞ DEVRİNDEN BERİ BAŞIM DÖNÜYOR

Sabrın bendine kalyonlar çekilir akşam üzeri

boşuğundan düşer kalır çakırkeyf bir yürek sakatlığı

takılır efsununa giyinmiş çambardak imzalarım

imzalarım kimliğinden soyunmuş

-eyvah! - uçsuz mağaralarında yankılanır karasevdam

ayrılığım gelinliğini kuşanmış yorumsuz kraliçe

çığlığım serpilmiş bir yosmanın düştüğü karanlıklarda

imzalarım kimliğinden soyunmuş

şarkılar yüreğimde

bana bende irkilmelerden-bana bende bir ses kalır

ince bir ses-

                    kimliğinden soyunmuş

bildiğim yetmiş bin sesin kefeni yok/param yok

sevabı,kan gmlekli şeytanların meme uçlarında

Yalçın Bayar', 'BENİM YONTMA TAŞ DEVRİNDEN BERİ BAŞIM DÖNÜYOR Sabrın bendine kalyonlar çekilir akşam üzeri boşuğundan düşer kalır çakırkeyf bir yürek sakatl...', ARRAY['Türk Edebiyatı','Şiir','Yalçın Bayar']::text[], 8.5, '{"poet":"Yalçın Bayar","poet_slug":"yalcin-bayar","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/benim-yontma-tas-devrinden-beri-basim-donuyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hepgül Kızım', 'hepgul-kizim-fahrettin-selcik-9ya5h', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'H E P G ÜL  K I Z I M

Aylardan şubat,günlerden bir pazar,

Geçmişten günümüze atalım nazar,

Sana altın gibi canım oğlumu verdim,

Onunla yaşama ve sevgiye erdin.

Orta öğrenciyken gelirdin buket çiçekle,

Onları sunardın reverans ve gülücükle,

Sonradan anlamadım ortamda ne değişti,

Vazgeçtik çiçekten,selam sabahın kesti.

Günler geçiyor,geldiniz otuz beş yaşına,

Oğlun var,bir gün gelecek senin de başına,

Gelecek olan da el kızıdır bakmaz gözün yaşına,

Gördüğün eylemden döneceksin şaşkına.

Mevlana der ki; olduğun gibi  görün’

Değildir bu benim yapım,kaderim,

Çıt demedim,bekledim anlarsın diye,

Mutlu oldum Can ın EGS de sunulan karnesine,

Kadındır yuvayı yapan derler,

Laftır, inanmadan söyler geçerler

Yuva tabiri mutlu bir simgedir,

Bunu değerlendiren  ancak bilgedir.

Bilmem seyrettin mi Tahta Çanaklar’

Bu sahneyi yaşar bütün ocaklar,

Mutlu olmak için duymamak gerek,

Her kişi kendi y0lunu belirleyecek.

Nesrin felç geçirdi siz evlendiğinize,

Tanrının takdiriydi,yoktu bir güç elimizde,

O kadın ki paralandı senin düğününüzde,

Umarım yarayı manyak İnci den aldı.

İnsanın hayatında görünür bazen kötü kader,

Onu yaşarsın ama sonra bakarsın geçer

Ardından gelecek olan güzel günlerdir,

Dileğimiz kötünün son bulup gitmesidir.

Diyeceksin bu şiir nedendir,

Babadan kızına imalı sitemdir,

Bunları yazdım,kalmadı içimde sızım,

Sen mutlu ol yeter sevgili kızım.

Fahrettin  Selcik  1992', 'H E P G ÜL  K I Z I M Aylardan şubat,günlerden bir pazar, Geçmişten günümüze atalım nazar, Sana altın gibi canım oğlumu verdim, Onunla yaşam...', ARRAY['Türk Edebiyatı','Şiir','Fahrettin Selçik']::text[], 8.5, '{"poet":"Fahrettin Selçik","poet_slug":"fahrettin-selcik","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/hepgul-kizim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'A li Dursun', 'a-li-dursun-fahrettin-selcik-tbq3h', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'A L İ   D U R S U N

    ANISINA

Duydum,benim için övgüler etmişin,

Birde haber geldi,göçüp gitmişsin,

Sana dünyadan uğurlar ola,

Tanrı  senide koydu yola.

Köyde kaldı efelik,sen gideli beri,

Tekrar dönüşü olmamış,dönen yok geri,

Aklıma,kanala düşürdüğün dana gelir,

Aptal sanmıştın, bekledin Fahrettin para verir,

Gün geldi Ali, bak çukuru sen doldurdun,

Allah ın emri ile dünyadan göçüp kayboldun,

Bilmem ki orada ne konu ve görevler buldun,

Köy seni arıyor,daha kötülere imkan koydun.

Senin hayatına destanlar yazılır,

Dışarıda köy senin adınla anılır,

Sen gidince kaldı köyümüz hamisiz,

Bundan böyle,İnegöl nasıl olacak Ali siz.

Fahrettin Selcik  15-6-2003', 'A L İ   D U R S U N     ANISINA Duydum,benim için övgüler etmişin, Birde haber geldi,göçüp gitmişsin, Sana dünyadan uğurlar ola, Tanrı  seni...', ARRAY['Türk Edebiyatı','Şiir','Fahrettin Selçik']::text[], 8.5, '{"poet":"Fahrettin Selçik","poet_slug":"fahrettin-selcik","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/a-li-dursun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üsküdarlı', 'uskudarli-fahrettin-selcik-uh8qb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'S E N İ   U N U T M U Y O R U M

Üsküdarlı Melahat Kanıdinç,

Yaşamımda unutamadım seni hiç,

Üniversite gençliğimde sevmiştim seni,

Sayende bulmuştum kendi benliğimi.

Yaşlı bir anan vardı vurdum duymaz,

Köpeğin  adı spot,rengi siyah beyaz,

Siz yemekten fedakarlık ederdiniz, o anlamaz,

Sen olmayınca inadından sokak turuna çıkmaz.

Seninle özel ve güzel günlerimiz oldu,

 Hatırlasana piyanodaki serenadı,

Sen benim kucağımda parmaklar beraber çalardı,

Anan ne dinler ne yoklar nede arardı.

Aşkı,sevgiyi,cinselliği sende tattım,

Yanından geçmeye korktuğum mezarlıkta yattım,

Senin için Üsküdar -yıldız arasını yol yaptım,

Banyoda önünde oturup pamuk ellerinle kirimi attım.

İstemesek de şartlar ayırmıştı,mezuniyetimle,

Sümerbank Beykoz kundura da başlamıştım ilk işime,

Aşiyanda kolej kampusünde kiralamıştım  bir fakirhane,

Hizmet üretiyordu  bana sanki pansiyon değilbir kerhane.

Sende o hışımla evlendin,yollarımız ayrıldı,

Herkes kendi hayat ve işine koyuldu,

Bilmiyorum,ama dilerim mutlu oldu,

Onun adı hayat boyu ceni olarak anıldı.

F.Selçik  30.11.2005', 'S E N İ   U N U T M U Y O R U M Üsküdarlı Melahat Kanıdinç, Yaşamımda unutamadım seni hiç, Üniversite gençliğimde sevmiştim seni, Sayende bu...', ARRAY['Türk Edebiyatı','Şiir','Fahrettin Selçik']::text[], 8.5, '{"poet":"Fahrettin Selçik","poet_slug":"fahrettin-selcik","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/uskudarli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Siren gözlerin', 'siren-gozlerin-burhan-kucuk-hzo70', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Siren gözlerin

Çektin beni  batırdın derinlere

Aldanmışım bir kere siren gözlerine

Doğduğum gün otuz hazirandı hani

Kurumuş kalbime çaktın kibriti

Geçtim denizleri birer birer

Siren gözlerinde aldandım ilk sefer

Ben aklımı kandırdım ilk defa

Kalbime yolladım bitiren bir veba

Ah zehirse gözlerin suç benim mi

Gönlüm sevmişse içmeyeyim mi

Burhan KÜÇÜK

Kdz.Ereğli-22.12.2005', 'Siren gözlerin Çektin beni  batırdın derinlere Aldanmışım bir kere siren gözlerine Doğduğum gün otuz hazirandı hani Kurumuş kalbime çaktın k...', ARRAY['Türk Edebiyatı','Şiir','Burhan Küçük']::text[], 8.5, '{"poet":"Burhan Küçük","poet_slug":"burhan-kucuk","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/siren-gozlerin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzak Ülkeler Ötesinden...', 'uzak-ulkeler-otesinden-alper-kuruk-9uwy5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Uzak ülkeler ötesinden

Büyücek bir selâmım var,

Bir küçücük mektup onu sana ileten

Ve hasretlikten boynu bükük satırlar.

Uzak ülkeler ötesinde

Rüyalarıma aktarıyorum seni,

Kokular taşıyan rüzgârlarla

Bir hayat başlar hergün yepyeni.

Uzak ülkeler ötesinde

Aşklarla birlikte başlar masallar,

Öten her kuşun sesinde

Bir teselli aramakta insanlar.

Uzak ülkeler ötesinde

Dört mevsim geçse de her yıl,

Üç mevsimim var benim

Sevdiğim de o mevsimdi asıl.

Uzak ülkeler ötesi

Benim de anlayamadığım yer,

Umut dolu başlayan aşklar

Gördüm göreli acı biter.

Uzak ülkeler ötesinde

Yeter,gördüğüm esmer akşamlar,

Artık uzak ülkeler ötesinden

Dört mevsimli ülkeme yolculuğum var...', 'Uzak ülkeler ötesinden Büyücek bir selâmım var, Bir küçücük mektup onu sana ileten Ve hasretlikten boynu bükük satırlar. Uzak ülkeler ötesin...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/uzak-ulkeler-otesinden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eğer Gelirsen', 'eger-gelirsen-ufuk-coban-iuhb0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben seni göremedim sırlarının ardında,

Kurduğun yalnızlığın sessiz karanlığında.

Br kelime istedim gözlerini kaçırırken,

Bir söz bekledim ellerim öylece beklerken.

Bir kış geldi fırtınalarla yüreğime,

Dayanamadım zamanın uzaklaşan bakışına.

Bir sen koyamadım gecelerin batışına,

Bir ben koyamadım sabahların uyanışına.

Gitme zamanı geldi hayatın senle olan yarısından,

Koparıp hayalleri umutların yosun tutan kıyısından.

Ardımda ne kalır ben bilemem sen de gör istemem,

Ben bilemem kimse demedi ki kelimeleri ben bilemem.

Eğer birgün kapadığım kapının önüne gelirsen,

Tüm bilmem gerekenlerle gel karşıma,

Eğer birgün o kapıyı çalmaya kalkarsan,

Herşeye rağmenleri yanına al da çık karşıma.

23/12/2005 08:45', 'Ben seni göremedim sırlarının ardında, Kurduğun yalnızlığın sessiz karanlığında. Br kelime istedim gözlerini kaçırırken, Bir söz bekledim el...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Çoban']::text[], 8.5, '{"poet":"Ufuk Çoban","poet_slug":"ufuk-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/eger-gelirsen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerim', 'gozlerim-alper-kuruk-javqy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gözlerim geceden almış rengini

Rengi biraz

Talihime de çalar.

Gözlerimdeki ışıltılar

Gözlerimdeki arzular

Ki gece gökteki yıldızlar misâli.

Onlar kadar uzak bana

Onlar gibi kendi hâlinde

Söner,yanar...

Aşkıyla ruhuma ışık saçan

Yolumu açan,aydınlatan

Bir kız hayâli var.

Gecelerin hâkimi ay

Gönlümün ise o kız

Geceler uyku getirir

 Benim gözlerim uykusuz...', 'Gözlerim geceden almış rengini Rengi biraz Talihime de çalar. Gözlerimdeki ışıltılar Gözlerimdeki arzular Ki gece gökteki yıldızlar misâli. ...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gozlerim-32-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Can Nebi-"siz hiç ay aşığında ağladınız mı" Kitabından', 'can-nebi-siz-hic-ay-asiginda-agladiniz-mi-kitabindan-omer-ekinci-micingirt-rbe0e', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kokuna hayranım 

Hasretim gül yüzlüm

Yoluna kurbanım 

Şefaat Sultanım 

Bayramın bayramım 

Gam keder her anım 

Yoksun ya üryanım 

Şefaat Sultanım 

Virandır dört yanım 

Yaslıdır Kur’anım 

Ulvîdir çıbanım 

Şefaat Sultanım 

Geçmiyor zamanım 

Kalmadı dermanım 

Sendedir gümânım 

Şefaat Sultanım 

Mecruhum viranım

Masiyet harmanım 

Tabuttur yârenim 

Şefaat Sultanım 

Yokluğun amanım 

Garibim cananım 

İmanın imanım

Şefaat Sultanım', 'Kokuna hayranım  Hasretim gül yüzlüm Yoluna kurbanım  Şefaat Sultanım  Bayramın bayramım  Gam keder her anım  Yoksun ya üryanım  Şefaat Sult...', ARRAY['Türk Edebiyatı','Şiir','Ömer Ekinci Micingirt']::text[], 8.5, '{"poet":"Ömer Ekinci Micingirt","poet_slug":"omer-ekinci-micingirt","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sefaat-sultanim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel Deseydin Gelmezmiydim', 'gel-deseydin-gelmezmiydim-yusuf-onder-bahceci-1a817', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Güzel seven güzel görür,

Gönül senin için ölür,

Seni sevmiş bunca ömür,

Gel deseydin gelmezmiydim.

Yollarına cânı verir,

Seni sevmiş cânı bilir,

Sen bendende yaralasın,

Belki sende kimbilir.

Bekle beni geleceğim,

Ben uğrunda öleceğim,

Dostlar yalan diyeceğim,

Gel deseydin gelmezmiydim.

Gel deseydin gelmezmiydim,

Yoluna ben ölmezmiydim,

Şimdi nasıl nasıl edim,

Gel deseydin gelmezmiydim.....', 'Güzel seven güzel görür, Gönül senin için ölür, Seni sevmiş bunca ömür, Gel deseydin gelmezmiydim. Yollarına cânı verir, Seni sevmiş cânı bi...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gel-deseydin-gelmezmiydim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alanya', 'alanya-serdar-ahmet-guzel-hehfa', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Şimdi Alanya da olsam

Ne güzeldir dağda çiçeklerin kokusu

Sahilde parlar güneşin ışıltısı

Rüzgâr olsam, essem poyraz misali

Savrulsam savrulsam kum taneleri gibi

Maviliklerine dalsam uyanmasam

Akşamlar olsam da şafağa kadar

Sahillerinde dolaşsam

Hüznü bıraksam ayılsam

Fosforlu mağarada balık olsam

Yüzsem meze olana kadar

Âşıklar girdabında bulunsam

Atlasam derinliklerine

Sonsuza kadar sır olsam.

2000 Mayıs', 'Şimdi Alanya da olsam Ne güzeldir dağda çiçeklerin kokusu Sahilde parlar güneşin ışıltısı Rüzgâr olsam, essem poyraz misali Savrulsam savrul...', ARRAY['Türk Edebiyatı','Şiir','Serdar Ahmet Güzel']::text[], 8.5, '{"poet":"Serdar Ahmet Güzel","poet_slug":"serdar-ahmet-guzel","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/alanya-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günahttır', 'gunahttir-semsettin-veli-erbilli-p7bum', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gel gezip dolaşalım dünyanın her yerini

Yaşamı tadmadık biz keyfimiz döndü aha

Bu ömür sonu gelir bakmaz sultana şaha

Gel gezip dolaşalım dünyanın her yerini

Dur koşturma pesinden gam,keder,kahır olursun

Dindir kafanı dindir gel bekleme yarını

Her çile çekip durma ruhun gökte bulursun

Gel gezip dolaşalım dünyanın her yerini

Sen bu bedene kıma çok yazıkttır günahttır

Bağrında bin bir det var eğlen gidert birini

İçini telaşlıyan ezelinden bir ahttır

Gel gezip dolaşalım dünyanın her yerini

Sıkılma görmediğin her şeyi göreceksin

Sen bırakma dünyayı kimse tutmaz yerini

Ağlarsın açılırsın gözlerin sileceksin

Gel gezip dolaşalım dünyanın her yerini.', 'Gel gezip dolaşalım dünyanın her yerini Yaşamı tadmadık biz keyfimiz döndü aha Bu ömür sonu gelir bakmaz sultana şaha Gel gezip dolaşalım dü...', ARRAY['Türk Edebiyatı','Şiir','Şemsettin Veli Erbilli']::text[], 8.5, '{"poet":"Şemsettin Veli Erbilli","poet_slug":"semsettin-veli-erbilli","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gunahttir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yara', 'yara-gulsen-gonenc-xkqhh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben niye saklayayım yaramı? 

Yarayı açanlar saklansın; 

Yalanlarını sakladıkları pis bohçada.

Ah, bir de kokmasa o bohça! 

Bırak, sarmaya çalışma yaramı.

Dışarıdan mikrop kapmadıkça iyileşecektir, nasıl olsa...', 'Ben niye saklayayım yaramı?  Yarayı açanlar saklansın;  Yalanlarını sakladıkları pis bohçada. Ah, bir de kokmasa o bohça!  Bırak, sarmaya ça...', ARRAY['Türk Edebiyatı','Şiir','Gülsen Gönenç']::text[], 8.5, '{"poet":"Gülsen Gönenç","poet_slug":"gulsen-gonenc","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yara-35-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk', 'ask-hakan-kocaoglu-mwmar', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Neyi arar bu dünyada insan, bildim ne için

Neyi kaybettiyse arar insan onu, Aşk için

Ezel yitirdiğin bilmezmi, aramasın niçin

Bulmuşsa izin, bulduğuyla yanar, bu gün için.', 'Neyi arar bu dünyada insan, bildim ne için Neyi kaybettiyse arar insan onu, Aşk için Ezel yitirdiğin bilmezmi, aramasın niçin Bulmuşsa izin,...', ARRAY['Türk Edebiyatı','Şiir','Hakan Kocaoğlu']::text[], 8.5, '{"poet":"Hakan Kocaoğlu","poet_slug":"hakan-kocaoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ask-503-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arızalıyım', 'arizaliyim-murat-polat-2-j62j1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yaşlanıyoruz herhalde artık

Yaş elliye mi döndü desek

Yada kırkı geçtik mi yavaşça…

İçmeyi bile beceremiyorum artık

Şöyle “kıya sıya” ne demekse öyle

Ha…sabahı buluyor kendimle yüzleşmem

Fakat sonunda sarhoş olamıyorum artık

Sonra gel de uyu, dinlen, rahatla

Yok yok bu böyle gitmez farkındayım.

Ben yine; Ya bir alkolik olmalıyım… sızmalı

Yada hiç ağzıma vurmamalı…ayık durmalı

Demek istediğim şu kısaca

Ruhumla bedenim yine

Her zamanki gibi karşı karşıya! 

Ha öyle…ha böyle

Huzuru bulamadım…ne onda ne bunda

Ben arızalı bir ürünüm…

Hem de iadesi imkansız.

Garanti süresi geçmiş

Eskiden kalan, yeniye uymayan! 

Evet arızalıyım

Bana bıraksa beni şartlar

En kısa yoldan imalatçıya! 

Geri dönüşsüz postalarım…', 'Yaşlanıyoruz herhalde artık Yaş elliye mi döndü desek Yada kırkı geçtik mi yavaşça… İçmeyi bile beceremiyorum artık Şöyle “kıya sıya” ne dem...', ARRAY['Türk Edebiyatı','Şiir','Murat Polat 2']::text[], 8.5, '{"poet":"Murat Polat 2","poet_slug":"murat-polat-2","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/arizaliyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '**Dokunmayın Keyfime', 'dokunmayin-keyfime-nurten-altinok-ygvl0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İçim içime sığmıyor

Bir telaş ki, o kadar güzel olur işte

Kuzum geliyor bugün

Anasının kınalısı

Anasının yürek yarası

Oy, başımın tacı benim.

Oy, gurbet kuşum benim

Yavrum geliyor

ÖZLEM’im geliyor

Kara gözlerini özlediğim

Burnumun sızısı geliyor

Dokunmayın keyfime…

23/12/2005

.

Sürpriz yapayım demiş

Anasına haber vermemiş

İzin alıp komutanından

ONUR’um da geldi Ankara’dan

İstanbul’da kar var bugün

Evimde bayram

Dokunmayın keyfime...

24/12/2005', 'İçim içime sığmıyor Bir telaş ki, o kadar güzel olur işte Kuzum geliyor bugün Anasının kınalısı Anasının yürek yarası Oy, başımın tacı benim...', ARRAY['Türk Edebiyatı','Şiir','Nurten Altınok']::text[], 8.5, '{"poet":"Nurten Altınok","poet_slug":"nurten-altinok","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/dokunmayin-keyfime-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nergis Çiçekleri', 'nergis-cicekleri-serdar-ahmet-guzel-x1j63', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gökyüzünden güneş görünmüyor artık,

Gün ışığı da vurmuyor ya üzerime,

Bu karanlık yeryüzünde! 

Yağmurda yağıyor  hala gökyüzünde,

İçim üşümüş, dışım ıslak...

Hasret rüzgârları da; 

Sert! 

Poyraz! 

Kavurmuşlar...

Kavuruyorlar, buğday başaklarını...

Eskisi gibi değil ekmeğin kokusu.

Selamsız! 

Akıp gidiyor hasret ırmakları...

Karlarda erimeye başladı  artık,

Nergis çiçekleri de fışkırdı,

Yardı toprağı,

Can evinde, çığlık çığlığa çıldıracak! 

Nisan 2000', 'Gökyüzünden güneş görünmüyor artık, Gün ışığı da vurmuyor ya üzerime, Bu karanlık yeryüzünde!  Yağmurda yağıyor  hala gökyüzünde, İçim üşümü...', ARRAY['Türk Edebiyatı','Şiir','Serdar Ahmet Güzel']::text[], 8.5, '{"poet":"Serdar Ahmet Güzel","poet_slug":"serdar-ahmet-guzel","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/nergis-cicekleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasır...', 'nasir-necla-aktan-msnpq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ah biri geldi nasırıma bastı 

İçime çöktü parmağımın acısı 

Yüreğimi yardı 

Beni kanattı... 

Yürürken bastığım yere dikkat etmem o yüzden 

O yüzden bazen yürürken istemeden sendelemelerim 

Yüreğimi nasırlatmamam da o yüzden 

Ya gelir de, yüreğime basarsa biri....

22.12.2005', 'Ah biri geldi nasırıma bastı  İçime çöktü parmağımın acısı  Yüreğimi yardı  Beni kanattı...  Yürürken bastığım yere dikkat etmem o yüzden  O...', ARRAY['Türk Edebiyatı','Şiir','Necla Aktan']::text[], 8.5, '{"poet":"Necla Aktan","poet_slug":"necla-aktan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/nasir-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeşil Kart 2', 'yesil-kart-2-i-rfan-kayagil-w75kp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Memleket tütüyor burnuma,

Dönmeyi yediremem ki gururuma

Dolarda çok ucuz diyorlar

Sanırım çaldıklarını yiyorlar.

Boşuna mı çektik onca zahmeti

Babamıza bile okuttuk rahmeti

Bak unutuldu her şey,

Kurumlar batarken, nedir ki birey

Nice civanlar can verirken sılada

Kim arar  bizi bu kıta da.

Söyleyin,  götürenlerde tek miyim?

Ben gurbeti böyle çekecek miyim? 

Çok ama çok yalnızım

Dönmekte kararsızım.

En çok korktuğum, sakladığım dolarlar

Bir bulunsa; çocuklar sakalımı yolarlar.

Yok, kalmak  lazım dönemem

Çocuklarımın geleceğini gömemem.

Hanıma da söyledim, düşünme artık ananı

Zaten yerinde de bulamazsın babanı

Şimdi dönmek değil kalmak zamanı.

Kim kurtarır sonra bizi,

Kurtaramadıktan sonra yeğenimizi.

Yeni iki villa alırız en iyisi

Birisi dağda, birisi deniz seviyesi

Hortumdan falan uzak

Kimse kurmadan bize tuzak

Gerçi bize de hortumcu  dediler

Onlar ciğere uzanamayan kediler

Öğrendim hortumun ne olduğunu

Bizi ta Amerikalarda bulduğunu

Dümdüz olmuş önceki aldığımız

Demek anlaşılmış çaldığımız

Bu hafta Noel tatili

Ver elini Miami, olmadı Tahiti

Artık Vatandaş sayılırız

Ne giderken sorarlar 

Ne gümrükte yorarlar

Hanım, saçlarımızı sarıya boyatalım

Bizi arayanları uyutalım

Saçlarımız sarı gözlerimiz maviyse; 

Anadolu da işimiz ne,

Tatil yapacak yer mi yok

Sırtımız pek karnımız  tok

Orada içki de yasaklanacak

Bize göre yer bulamayız kalacak

Artık vatanımız burası,

Vatandaşlığımız çıkacak, ne kaldı şunun şurası

Sevgilim dur havyarcıya gelmişiz.

Burada yaşamak ne rahat, tart usta tart

Seni çok ama çok seviyorum yeşil kart

Ankara, Aralık 2005', 'Memleket tütüyor burnuma, Dönmeyi yediremem ki gururuma Dolarda çok ucuz diyorlar Sanırım çaldıklarını yiyorlar. Boşuna mı çektik onca zahme...', ARRAY['Türk Edebiyatı','Şiir','İrfan Kayagil']::text[], 8.5, '{"poet":"İrfan Kayagil","poet_slug":"i-rfan-kayagil","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/yesil-kart-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nuruaynım', 'nuruaynim-hakan-kocaoglu-b3o1t', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aşk şarabın sunarlar, testinden bir gün

Dolar her kadeh o düğün, olur düğüm

Ne testin elim değer, ne kadehte ün

Bensiz olsanda yâr, sensiz geçmez bak gün

Gül olup ol cemaline, her gün baksam

Bülbül gibi şol zikrimle, her an yaksam

Aşk olup ol gönlüne bende, her dem aksam

Kulun gibi ol rahmetin, her an tatsam.', 'Aşk şarabın sunarlar, testinden bir gün Dolar her kadeh o düğün, olur düğüm Ne testin elim değer, ne kadehte ün Bensiz olsanda yâr, sensiz g...', ARRAY['Türk Edebiyatı','Şiir','Hakan Kocaoğlu']::text[], 8.5, '{"poet":"Hakan Kocaoğlu","poet_slug":"hakan-kocaoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/nuruaynim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arkadaş', 'arkadas-serdar-ahmet-guzel-9pssw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevmek aslında…

Bir gün geri gelmektir…

Sevenlerine ağlamaktır…

Üzülsen de üzmemektir arkadaş…

07.07.2005 22:45', 'Sevmek aslında… Bir gün geri gelmektir… Sevenlerine ağlamaktır… Üzülsen de üzmemektir arkadaş… 07.07.2005 22:45...', ARRAY['Türk Edebiyatı','Şiir','Serdar Ahmet Güzel']::text[], 8.5, '{"poet":"Serdar Ahmet Güzel","poet_slug":"serdar-ahmet-guzel","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/arkadas-105-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayatı şiir gibi....', 'hayati-siir-gibi-necla-aktan-cs428', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hayatı bir şiir gibi yaşamalısın...

Dize, dize

her dize de kendi içinde uyumlu 

Bir bütün olarak 

Bir armoni yaratmalısın... 

Hayatı bir şiir gibi yaşamalısın...

İstediğini uzun 

İstediğini kısa 

İstediğini süslü 

ya  da sade, yalın 

Kimseden kopya çekme sakın 

Sana özel, senin için olmalı 

Her harf

Her harfte sen olmalısın 

Hayatı bir şiir gibi yaşamalısın... 

20.07.2005', 'Hayatı bir şiir gibi yaşamalısın... Dize, dize her dize de kendi içinde uyumlu  Bir bütün olarak  Bir armoni yaratmalısın...  Hayatı bir şii...', ARRAY['Türk Edebiyatı','Şiir','Necla Aktan']::text[], 8.5, '{"poet":"Necla Aktan","poet_slug":"necla-aktan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hayati-siir-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman kendi havasında...', 'zaman-kendi-havasinda-necla-aktan-6j2j8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bitmesini istemediğin an 

Daha çabuk geçiyor zaman 

Ne tutmak mümkün 

Ne de durdurmak 

Su gibi akıyor kendi debisinde... 

Bitmesini istediğin an 

Sanki duruyor zaman 

Ne ittirmek mümkün 

Ne de koşturmak 

Durup duruyor kendi yerinde... 

22.12.2005', 'Bitmesini istemediğin an  Daha çabuk geçiyor zaman  Ne tutmak mümkün  Ne de durdurmak  Su gibi akıyor kendi debisinde...  Bitmesini istediği...', ARRAY['Türk Edebiyatı','Şiir','Necla Aktan']::text[], 8.5, '{"poet":"Necla Aktan","poet_slug":"necla-aktan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/zaman-kendi-havasinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğru - Yanlış', 'dogru-yanlis-unal-karabulut-racfg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yağmur yağıyor

Üstelik şemsiyemde yok

Yamurun yağışı 

ve 

Şemsiyemin olmayışı sayesinde

Ağladığımı kimse farketmedi

Doğru birini sevdim 

Yanlış bir zamanda

Doğru birini sevdim

Yanlış bir mekanda

Aynı kişiyi

Yanlış bir zamanda

ve yanlış bir mekanda 

Gene sevmiştim zaten......', 'Yağmur yağıyor Üstelik şemsiyemde yok Yamurun yağışı  ve  Şemsiyemin olmayışı sayesinde Ağladığımı kimse farketmedi Doğru birini sevdim  Yan...', ARRAY['Türk Edebiyatı','Şiir','Ünal Karabulut']::text[], 8.5, '{"poet":"Ünal Karabulut","poet_slug":"unal-karabulut","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/dogru-yanlis-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaybetmek', 'kaybetmek-unal-karabulut-a32l1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ufakkende sevmezdim kaybetmeyi

Misket oynardık,kaybederdim hep

O yüzden hiç çuval çuval misketim olmadı benim

Sora büyüdüm 

Kumarlar oynadım 

Gene kaybettim tabiki

Ama bu sefer üzülmedim

Çünkü kumarda kaybeden aşka kazanır demişlerdi

Kazanacaktım 

Seni o sıralar tanımıştım

Yaklaşırken sana hep düşündüm 

Ya yalandıysa; 

Kumarda kaybedenin aşkta kazanacağı 

Misketler benimdi 

Kaybettim

Para benimdi 

Kaybettim

Sen......

Sen benim olmamalıydın

Seni de kaybetmek istemiyordum.....', 'Ufakkende sevmezdim kaybetmeyi Misket oynardık,kaybederdim hep O yüzden hiç çuval çuval misketim olmadı benim Sora büyüdüm  Kumarlar oynadım...', ARRAY['Türk Edebiyatı','Şiir','Ünal Karabulut']::text[], 8.5, '{"poet":"Ünal Karabulut","poet_slug":"unal-karabulut","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kaybetmek-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yasak', 'yasak-unal-karabulut-yl4o4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Orta yaşta kadın

Genç bir adam

Evlidir adam ve duldur kadın

Çarpıştılar.....

birincisi çarpışma

ikincisi tesadüf

üçüncüsü sohbet

dördüncüsü arkadaşlık

beşincisi sevgiyi getirdi.....

sevgi de acıyı

çocukça bir evcilik oynadılar

biri anne diğeri baba oldu

her şey yolundaydı 

taki o güne kadar

adam baktı kadının gözlerine 

seni seviyorum dedi 

seni seviyorum

kadın inandı adamın söylediğine ve sustu bi süre

kalkarken masadan 

''bende''

diyebildi kısık bir sesle

kadına çekip gitmek düştü

adama oturup düşünmek

kadın çekti gitti

adam hala düşünüyor....', 'Orta yaşta kadın Genç bir adam Evlidir adam ve duldur kadın Çarpıştılar..... birincisi çarpışma ikincisi tesadüf üçüncüsü sohbet dördüncüsü ...', ARRAY['Türk Edebiyatı','Şiir','Ünal Karabulut']::text[], 8.5, '{"poet":"Ünal Karabulut","poet_slug":"unal-karabulut","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yasak-52-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Muhterem', 'muhterem-unal-karabulut-a3xby', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Askerdeyken tanıdım Muhterem''i

İsmi gibi kendide muhteremdi

Hep uzaktan seyrederdim kendisini

Doğa bile doğal değildi onun kadar

Muhterem 

sempatik, iri kıyımlı

Yemyeşil gözlü, hep güleç yüzlü 

Taşı sıksa suyunu çıkartacak 

Güçlü kuvvetli bir delikanlı

O kadar saf ki Muhterem 

Neslinin tek örneği sanki

İçin için seyrederim uzaktan 

Bazen gülerdim hallerine bazen keder…..

Bir gün sohbet ettim kendisiyle

Çok güldürdü beni ve çokca doldu gözlerim yaşla 

Sordum kaç kardeşsiniz Muhterem

Dört kardeşiz abi bir abim bir ablam birde kardeşim var

Peki baban ne iş yapıyor Muhterem

Babam vefat etti

Gözleri daldı uzaklara …….

Bi muddet ne ben sordum ne o cevapladı

Sora baktı gözlerime ve anlattı

Bir kaza oldu yatalak kaldı babam

Sora eridi dağ gibi babam gözümün önünde

İstanbul büyük şehirmiş

Çok camisinde dilendim ben

Sağ olsun büyüklerimiz ….

Köylülerim sağ olsun yardım etmeselerdi ……..

Hastaneden köyüme zor getirdim

Ben, el arabasında taşıdım babamı aylarca 

Sen bakma benim güldüğüme acım büyüktür benim

Yutkundum 

sustum

Bana baktı ve güldü

Sana bişey anlatıcam abi

Geçen gece nişanlandım 

Şaşırma abi rüya felan değildi 

Anam bi kız istemiş bana..... 

Vermişler 

Bende bi garip oldum abi 

Bitince şu askerlik evlencem 

Alcam onu istanbula gidicem 

Sonra sonra anamıda alıcam yanıma 

Çalışırım abi bir ev tutarım 

Bu sefer dilenmek için değil çalışmak için orda olucam

Hayalleri ve hayalleri gerçekleştirecek bir inancı vardı Muhterem''in

Bende kalkarken masadan 

İnşallah Muhterem inşallah diyebildim

bu dünya sizlerle güzel.......', 'Askerdeyken tanıdım Muhterem''i İsmi gibi kendide muhteremdi Hep uzaktan seyrederdim kendisini Doğa bile doğal değildi onun kadar Muhterem  s...', ARRAY['Türk Edebiyatı','Şiir','Ünal Karabulut']::text[], 8.5, '{"poet":"Ünal Karabulut","poet_slug":"unal-karabulut","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/muhterem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yutmaz bir daha!', 'yutmaz-bir-daha-mikdat-bal-7z538', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gül diye sarıldık diken çıktınız

Yutmaz be, yutmaz be, yutmaz, bir daha! 

Tam işin başında iken çıktınız

Yutmaz be, yutmaz be, yutmaz, bir daha! 

Çok duyduk,dinledik size, çok kandık

Kalıbına baktık  becerir sandık

İyi ki tanıdık sizi, uyandık

Yutmaz be, yutmaz be, yutmaz bir daha! 

Kenyadan gelmişti ayının teki

Onun hesabına kestiniz çeki

Sana destek verdik ne ettin peki

Yutmaz be, yutmaz be, yutmaz bir daha! 

Şehitlerin kanı tırnağınızda

Boğulun o kandan ırmağınızda

Bunun hesabını sormağınız da! 

Yutmaz be, yutmaz be, yutmaz bir daha! 

Mikdat der peşinden daha koşturmam 

Bu gençlere yalan deyip coşturmam

Gerçeği söylerim asla boş durmam

Yutmaz be, yutmaz be, yutmaz bir daha!', 'Gül diye sarıldık diken çıktınız Yutmaz be, yutmaz be, yutmaz, bir daha!  Tam işin başında iken çıktınız Yutmaz be, yutmaz be, yutmaz, bir d...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yutmaz-bir-daha-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mecnunun Suçu Ne?', 'mecnunun-sucu-ne-hakan-kocaoglu-eyaqg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bakıversen ne olur, bu mecnun gözlere

Çaredir bil ki nazarın, yanan gönlüme

Baktın mı hiç mecnunun gözüyle kendine

Sende mecnunu oldun, O Leyla’nın İşte

Çok mu görürsün a güzel bir bûseni

Zahirde dilim yanar, sanma dudaktaki

Bilsen mecnunun, Leylâ’m mı olursun sanki

Nazlanan sen değilsin, kanma; O sendeki

Seni gönlüme nakşeden, sevgili diye

Etse haber ne olur O, seven bu diye

Sevenin gözüyle bakıver, sen kendine

Sende Mecnun oldun, Mecnununun suçu ne.', 'Bakıversen ne olur, bu mecnun gözlere Çaredir bil ki nazarın, yanan gönlüme Baktın mı hiç mecnunun gözüyle kendine Sende mecnunu oldun, O Le...', ARRAY['Türk Edebiyatı','Şiir','Hakan Kocaoğlu']::text[], 8.5, '{"poet":"Hakan Kocaoğlu","poet_slug":"hakan-kocaoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/mecnunun-sucu-ne-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğum günün için...', 'dogum-gunun-icin-necla-aktan-ya0ai', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yaş nedir ki, gelir geçer... 

Zamanı durdurabilir misin? 

Her yaş yeni bir umut 

Her yaş yeni bir ufuk 

Biraz hüzün 

Biraz keder 

Bunlar unutulur gider 

Hatırlarken geçmişini

Hafızana hep güzellikler düşer....

Her yeni yaş 

Yeni bir umuttur aslında 

Bir bilinmezdir 

Büyük bir beklentidir 

Umutların devridir 

Olmadı seneye 

Olmadı seneye 

Seneye devredebilmenin keyfidir.... 

Her yeni yaş 

Yaşlanmak değildir 

Yenilenmektir 

Tecrübedir 

Kabuk değiştirmektir

Değerini bilmektir 

Her gülümseyişin

Her yeni sevginin 

Her yeni günün...

Her yeni şey güzeldir 

Işıltıdır 

Pırıltıdır 

Yana döner, yanar döner 

Umutların bitince söner...

Işıltın sönmesin..

Yan! Dön! 

Yan! Dön! 

Yana yana 

Döne Döne 

Doğum günün kutlu olsun 

Daha nice senelere.... 

23.12.2005', 'Yaş nedir ki, gelir geçer...  Zamanı durdurabilir misin?  Her yaş yeni bir umut  Her yaş yeni bir ufuk  Biraz hüzün  Biraz keder  Bunlar unu...', ARRAY['Türk Edebiyatı','Şiir','Necla Aktan']::text[], 8.5, '{"poet":"Necla Aktan","poet_slug":"necla-aktan","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/dogum-gunun-icin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk:Bir Sohbetin Detayında', 'ask-bir-sohbetin-detayinda-zehra-bulutlar-lj5qo', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Vuslatında bir gece yağarken kentlere 

Ben usulca düşüyorum 

Bir mum alevinin zemherisine… 

Aşk nerede Sevgili, duygu nerede 

Daralmış anlarının ellerinle boğduğun heyecanlarında mı? 

Düşlerinle sınırlandırıp 

Kimliklerini yitirdiğin doğumlarda mı? 

Tarifini yapabilir misin, 

Bir coğrafyada yerini çizebilir misin bana? 

Susmalarından bir şiir yazıp 

Genzine kaçan birkaç mısra ile 

Satır arasında hatırını sorabilir misin imgelerin? 

Ya da 

Kalbin her atışında 

Bir çarpma boyu heyecanlarda 

Sevdalarını sancılarından devşirebilir misin? 

Aşk bulutlardadır sevgili, bulutlar semada 

Sema ise sana döndüğüm sana yandığım her yerde 

Aşk yıldızlardadır sevgili,yıldızlar gecede 

Gece ise sensizlikle kavrulan kağıtlarda 

Aşk gönüllerdedir sevgili,gönül ise sende 

Ben yanmışım sana,sen yanmışsın aşka 

O aşk aşk mıdır sence...!', 'Vuslatında bir gece yağarken kentlere  Ben usulca düşüyorum  Bir mum alevinin zemherisine…  Aşk nerede Sevgili, duygu nerede  Daralmış anlar...', ARRAY['Türk Edebiyatı','Şiir','Zehra Bulutlar']::text[], 8.5, '{"poet":"Zehra Bulutlar","poet_slug":"zehra-bulutlar","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/ask-bir-sohbetin-detayinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Veda', 'veda-zehra-bulutlar-h9kps', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevginin suali sorulmaz senden 

Nice aşklar geçti gönül bahçenden

''Unutmak zor imiş'' dedin ya içten

Vurdun yüreğimi ince yerinden... 

Fayda etmez artık beste ve güfte

Sevsen de incindi gönül ne çare

Dayanacak güç kalmadı bedende

Anladım ki; 

Her sevda bir V E D A '' ya gebe...', 'Sevginin suali sorulmaz senden  Nice aşklar geçti gönül bahçenden ''Unutmak zor imiş'' dedin ya içten Vurdun yüreğimi ince yerinden...  Fayda ...', ARRAY['Türk Edebiyatı','Şiir','Zehra Bulutlar']::text[], 8.5, '{"poet":"Zehra Bulutlar","poet_slug":"zehra-bulutlar","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/veda-184-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdiğim Elimden Gitti', 'sevdigim-elimden-gitti-yusuf-onder-bahceci-yw77g', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Derdi beni deli eyler,

Seven kalbi şimdi neyler,

Dertli çalar bütün neyler,

Sevdiğim elimden gitti.

Şimdi acep ne haldedir,

Seven kalbi ne eyletir,

Kalbim kırık dert söyletir,

Sevdiğim elimden gitti.

Bu Dünya''da yüzüm gülmez,

Çok sevdiğim gitti gelmez,

Bir mektupla haber salmaz,

Sevdiğim elimden gitti.....', 'Derdi beni deli eyler, Seven kalbi şimdi neyler, Dertli çalar bütün neyler, Sevdiğim elimden gitti. Şimdi acep ne haldedir, Seven kalbi ne e...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sevdigim-elimden-gitti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÖZLEM '' im...', 'ozlem-im-tulay-sustam-8g1pd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'rüzgârın bir ıslığına 

ağacın dalları kımıldamasaydı

ve gölgesindeki kumrunun

etekleri tutuşmasaydı

toprak ana

zemheriyi alır mıydı koynuna?', 'rüzgârın bir ıslığına  ağacın dalları kımıldamasaydı ve gölgesindeki kumrunun etekleri tutuşmasaydı toprak ana zemheriyi alır mıydı koynuna?...', ARRAY['Türk Edebiyatı','Şiir','Tülay Sustam']::text[], 8.5, '{"poet":"Tülay Sustam","poet_slug":"tulay-sustam","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ozlem-im-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgili''ye', 'sevgili-ye-zehra-bulutlar-hv45l', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bakmasını bilebilseydin 

gözlerime 

bende söyleyebilseydim 

duygularımı yüreklice 

d e ğ i ş i r m i y d i n... 

''Sebepsizdi gidişin

noktasız bitirişin'' 

Özgürlüğü vurgun yedi yüreğimin 

yasaklı sevdalara artık 

kozasına çekildi kelebeğin... 

Çok şey istemedim 

ömrümün son demlerinde

İlgiydi tek beklediğim; 

keşke anlayabilseydin 

a n l a t a b i l s e y d i m... 

Özgürce yaşanmalıydı 

sevdalar derdin 

ve tutamadım 

kayıp gittin ellerimden 

sen haklıydın...

a n l a d ı m...', 'Bakmasını bilebilseydin  gözlerime  bende söyleyebilseydim  duygularımı yüreklice  d e ğ i ş i r m i y d i n...  ''Sebepsizdi gidişin noktası...', ARRAY['Türk Edebiyatı','Şiir','Zehra Bulutlar']::text[], 8.5, '{"poet":"Zehra Bulutlar","poet_slug":"zehra-bulutlar","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sevgili-ye-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dönemem', 'donemem-hulya-kandemir-j8c9d', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dön gel deme bana

Dönemem…

Yıkılmaz duvarlar aştım bu yolda

Bitmeyen adımları atarken nefes nefese kaldım.

Gücüm yetmedi ayaklarım titrerken koşmaya

Yine de durmadım

Küskün yüzlere aldırmadım giderken

Yalnızlığı öğrenirken bir ben kaldım kendimle

Alıştım sensizliğe

Dönemem…

Yaşananların gerçek olmadığını hayal ederken

Avundum sırtımdaki kamburla yaşamaya

Bir sızı saplandı bedenime 

Dinmiyor ıstırabım dönemem…

Aklıma gelmiyor değil mutlu olduğum anlar

Ben de sevdim sevildim de

Sadece sevmek yetmiyor hayatla yarış tutmaya

Umudumu yitirdim dönemem…', 'Dön gel deme bana Dönemem… Yıkılmaz duvarlar aştım bu yolda Bitmeyen adımları atarken nefes nefese kaldım. Gücüm yetmedi ayaklarım titrerken...', ARRAY['Türk Edebiyatı','Şiir','Hülya Kandemir']::text[], 8.5, '{"poet":"Hülya Kandemir","poet_slug":"hulya-kandemir","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/donemem-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sayende', 'sayende-zehra-bulutlar-z5tco', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevmek, 

acı çekmekse eğer

acı çekmek

olgunlaşmaksa

olgunlaştım 

seninle... 

Hüzünde mutluluğu

mutlulukta gözyaşını

kargaşada huzuru

umutsuzlukta umudu 

yaşadım seninle...

Seninle doluyken sensiz

ayrılıkta ölümü tattım

Sayende...', 'Sevmek,  acı çekmekse eğer acı çekmek olgunlaşmaksa olgunlaştım  seninle...  Hüzünde mutluluğu mutlulukta gözyaşını kargaşada huzuru umutsuz...', ARRAY['Türk Edebiyatı','Şiir','Zehra Bulutlar']::text[], 8.5, '{"poet":"Zehra Bulutlar","poet_slug":"zehra-bulutlar","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sayende-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '**Anneme Şikayet 1**', 'anneme-sikayet-1-sakine-aydin-fdxv4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu dünya ne garip bir yermiş anne,

Herkes kendi kendine kendi halinde … 	

İnsanlar ne garip bir varlıkmış anne,

Yalan hile ve fitne peşinde ….

Herkes şan şöhret için yarışır olmuş,

En kahpe insanlar başta dururmuş,

Adaletsizliğin adı medeniyet konmuş,

Bu dünya ne garip bir yermiş anne….

Paran varsa adında, şanında varmış burada,

Paran yoksa hor görülürsün sokakta,

Devir ye kürküm ye devri olmuş da,

Biz hala insanlığa inanıyoruz anne….

Biz bilirdik ki  komşun açken tok yatılmaz,

Biz bilirdik ki öksüz gariban ezilmez,

Bizde insanın kıyafetine bakılmaz,

Şimdi ise bunlar yok olmuş anne…..

Çocuklarımız paçavra gibi sağda solda,

Kimsede yok vicdan, kalmamış imanda,

Bir çocuk ekmek topluyor sokaklarda,

Biri düşüyor bataklıklara, yatıyor soğuklarda….

Kimisi para serer dansözün ayak altına,

Kimi altın kolye alır köpeğinin boynuna,

Adalet varmış özgürmüşüz biz anne…

Bu nasıl bir adalet söyleyin bana…

Biri diyor ki medeniyet! ... medeniyet! ...

Özgürlük sokaklarda  sevişmekle başlarmış,

Medeniyet anlayışları eğer buysa,

Ben çok çağdışı kalmışım anne ….

Benim medeniyetten anladığım şey anne..

Herkese davranmalı dürüstçe dostça,

İnsanları ayırt etmemeli  kılığıyla, huyuyla,

Herkese saygılı olabilmeli anne …

Çıplak gezmekle olmasın özgürlüğüm,

Diskoteklerde barlarda çürümesin gençliğim,

Bir Türk gibi yaşamalı Türk gibi ölmeliyim,

Ben ne Amerikalı, ne Arabistanlıyım anne….

Bir söz vermiştim galu belada  RAB ‘bime ,

ALLAH BİR…. MUHAMMED RESUL  diye …

Oysa yaşayamaz olmuşum imanım ile,

Başörtüme bile el atmışlar anne….

Bu dünya ne garip bir yermiş anne,

Gücü yeten yeteni vurur olmuş….

Sağ sol diye ayırmışlar bizleri 

Kardeş kardeşe tuzak kurmuş….

İçimize girmişler kanımızı emmişler,

Bizi kendimize düşman etmişler,

Bizleri uyutmuşlar hem de ne ninnilerle,

Bu dünya ne garip bir yermiş anne ….

Bu dünya ne garip bir yermiş anne,

Gelen bir pişman, yaşayansa öyle,

Bu dünyada çok kandırılmışım adice,

İnsanlar ne garip bir varlıkmış anne….

11.09.1997 Perşembe', 'Bu dünya ne garip bir yermiş anne, Herkes kendi kendine kendi halinde … 	 İnsanlar ne garip bir varlıkmış anne, Yalan hile ve fitne peşinde ...', ARRAY['Türk Edebiyatı','Şiir','Sakine Aydın']::text[], 8.5, '{"poet":"Sakine Aydın","poet_slug":"sakine-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/anneme-sikayet-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Güzele Sevdalıyım', 'bir-guzele-sevdaliyim-yusuf-onder-bahceci-jwq3h', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seni görüp sevmezmiyim,

Ben yolunda ölmezmiyim,

Sorun hele delimiyim,

Bir güzele sevdalıyım.

Önüme Dünya''yı serseler,

Bütün güzelleri getirseler,

Hepsi senin deseler,

Bir güzele sevdalıyım.

Uğraşmasınlar hele benimle,

Kalbim dolu sevginle,

Kırılmasın şu kalbimde,

Bir güzele sevdalıyım.

Güzel gözler ağlamasın,

Sular gibi çağlamasın,

Yare deyin ağlamasın,

Ona özden sevdalıyım....', 'Seni görüp sevmezmiyim, Ben yolunda ölmezmiyim, Sorun hele delimiyim, Bir güzele sevdalıyım. Önüme Dünya''yı serseler, Bütün güzelleri getirs...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-guzele-sevdaliyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kayıp''''lar...', 'kayip-lar-ali-baksi-p491f', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ay gecelerim,yalnız,üşüyorum, 

Beyaza inat seviyorum seni, 

Sorgusuz derinden iniyorum kıyılara, 

Yanğın yeri bedenim,kacıyorum, 

Yıllardır bekledigim yetmezmi? 

Baharı yaşıyorum,yapragın torultularında, 

Düşlerim soguk,sensiz bu diyarda, 

Dilek''ler tutuyorum,defalarca, 

Şimdi yoksun,yağmurlarımda, 

Göz yaşları gibi,yitiyorum yollarda! ! 

Sebesiz seviyorum,maviliğini...', 'Ay gecelerim,yalnız,üşüyorum,  Beyaza inat seviyorum seni,  Sorgusuz derinden iniyorum kıyılara,  Yanğın yeri bedenim,kacıyorum,  Yıllardır ...', ARRAY['Türk Edebiyatı','Şiir','Ali Baksı']::text[], 8.5, '{"poet":"Ali Baksı","poet_slug":"ali-baksi","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/kayip-lar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mahzun Güzel', 'mahzun-guzel-selcuk-celik-5n1m7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hiçbir yüce dağda esmedi böyle rüzğar,

Senin gönlümde estirdiğin gibi.

Gözlerim gördü mü bilmiyorum böyle bir yüz,

Ayın ondördünü andırır gibi.

Güzele gülmek yaraşır derler,

Seni görmeden önce ben de inanmıştım buna.

Yüzünün güzelliği çeldi aklımı,

Mahzun olmak bu kadar yakışıyorsa sana,

Mahzun Güzel! Benden başka kimse görmesin güldüğünü.', 'Hiçbir yüce dağda esmedi böyle rüzğar, Senin gönlümde estirdiğin gibi. Gözlerim gördü mü bilmiyorum böyle bir yüz, Ayın ondördünü andırır gi...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Çelik']::text[], 8.5, '{"poet":"Selçuk Çelik","poet_slug":"selcuk-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/mahzun-guzel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Sokak Çocuğu', 'i-ki-sokak-cocugu-selcuk-celik-61dnh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kimsesizdir sokaklar, bu soğuk kış gününde; 

İki çocuk istisna, karşı sokak köşesinde.

Geçerken ışıktan parıldar yanaklardaki yaşlar,

Belli ki ağlamışlar, hala da ağlıyorlar.

Hüzünlü bir şarkıya eşlik edercesine,

Esiyor sokakta rüzğar, sanki ''Yazık! '' dercesine.

Bu ne hazin bir görünüş... Dayanamaz gözlerim,

Süzülür iki damla yaş...Parçalanır yüreğim.

Bilinmez, karanlıklar içinde nereyedir yolculuk,

Hayal mi yoksa gerçek mi, şu simsiyah sonsuzluk? 

Kapanır gözlerim, koybolunca gölgeler; 

Haberi geldi, acıdır: Gece sokakta ölmüşler.', 'Kimsesizdir sokaklar, bu soğuk kış gününde;  İki çocuk istisna, karşı sokak köşesinde. Geçerken ışıktan parıldar yanaklardaki yaşlar, Belli ...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Çelik']::text[], 8.5, '{"poet":"Selçuk Çelik","poet_slug":"selcuk-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/iki-sokak-cocugu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Bûsen', 'son-b-sen-timur-i-likan-eh1l3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Geçiyor ömrüm hep seni beklemekle

Soldu günüm derdime dert eklemekle

Bittim bu aşk yolunda emeklemekle

Eridi gönlüm hep seni beklemekle

Dön gel ne olur artık dön gel bana sen

Dudaklarıma mühür oldu son bûsen

Vedândan sonraki hâlimi bir görsen

Kalbimdeki sancıyı bir bilebilsen

Dünyâm yıkıldı sanki birden başıma

Hançer vurdu felek su kattı aşıma

Hiç mi hiç bakmadı akan gözyaşıma

Bir taş da sen ekledin mezar taşıma

Ümitlerim bir kuş olup uçup gitti

Yokluğun beni uçurumlara itti

Ağlamaktan gözlerimin feri gitti

Bilmiyorum ki aşkımız neden bitti

Gel artık canım sil gözümün yaşını

Eskisi gibi koy omzuma başını

Benimle yârim yine paylaş aşını

Verelim senle bu hayat savaşını

(23 Aralık 2005/ İstanbul)', 'Geçiyor ömrüm hep seni beklemekle Soldu günüm derdime dert eklemekle Bittim bu aşk yolunda emeklemekle Eridi gönlüm hep seni beklemekle Dön ...', ARRAY['Türk Edebiyatı','Şiir','Timur İlikan']::text[], 8.5, '{"poet":"Timur İlikan","poet_slug":"timur-i-likan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/son-busen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Edalım', 'edalim-yusuf-onder-bahceci-zgz4j', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hele sorun mutlu varmı Dünya''da,

Kimler sevmiş, kimler almış Dünya''da,

Süremedim birgün devran Dünya''da,

Kalbim kırık, gönlüm mahzun edalım.

O yâr bana sitem eder naz eder,

Beni sevmiş ama ellere gider,

Şu genç ömrüm yolunda oldu da heder,

Kalbim kırık, gönlüm mahzun edalım.

Başına karalar bağlayıp gezme,

Ben seni severim kötülük sezme,

Kadermi, talihmi diyelim biz bu düzene,

Kalbim kırık, gönlüm mahzun edalım.', 'Hele sorun mutlu varmı Dünya''da, Kimler sevmiş, kimler almış Dünya''da, Süremedim birgün devran Dünya''da, Kalbim kırık, gönlüm mahzun edalım....', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/edalim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Toprak Atam', 'toprak-atam-recep-uslu-p5y7a', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Toprakdan bir adam,kocaman

Kolları değdi uzaya

Ayakları arş-ı alaya

Dirildi birden.

Kan kattı yüce tanrı damarlarına,can verdi.

Yürüdü toprak adam.

Unuttu anası toprağı ve çiğnedi onu.

Yapayalnızdı çamur adam

Ellerini açtı...

Eş istedi kendisine

Konuşur olsun,sevişir olsun.

Bir zaman uyurken

Sıcaklık duydu,nefes duydu kalbinde

Açtı gözlerini

Aşkı tanıdı

Oturdu...

Yanındaki onun kadınıydı.

Ayağa kalktı ve şeytana uydu.

Toprakdan bu koca adam

Dünyayı buldu.

Çalıştı,çalıştı yaşam öğrendi

Sevgi tüttü burnunda

Kadınım dedi.

Bilmem kaç tarihinin

Bilmem kaçında

Buluştular ikisi masal dağında.

Derken

İnsanlık türedi

Ev edindiler,bark edindiler

Eş edindiler,yurt edindiler

Her taraf...

Yiyen içen

Gülen,ağlayan

Çalışan,didinen

Canlıyla doldu.

Onlar hükmetti doğaya

Onlar boyunduruk vurdu boğaya.

Aslanı kapattı,fili ağlattı

Yetmedi...

Sebzelere,bitkilere

Börtülere,böceklere

Bu kocaman toprak adamın

Kısacık torunları yol gösterdi.

Ama bir gün bir yerden

Bir şeyler koptu.

Kısacık torunlar girdi birbirine

Koşular yaptı olmadı,

Dövüşler yaptı olmadı,

Başladı savaşmaya

Koca dünyaya sığmadı.

Söyleyin kardeşlerim! 

Toprak anamızdan olan babamızın

Sevgisi inancı nerede kaldı.

Sevişmek varken,konuşmak varken

Savaşmak niye...

Gittiğimiz yer toprak

Bunu bile bile

Öldürmek niye? 

Kime kar sağladı şimdiye değin

Kime kaldı kocaman dünya.

Var varanın sür sürenin

Toprak adam dedemin

Sevgisi üstünüze,aşkı üstünüze

İnancı üstünüze,kardeşliği üstünüze.

16.12.1982', 'Toprakdan bir adam,kocaman Kolları değdi uzaya Ayakları arş-ı alaya Dirildi birden. Kan kattı yüce tanrı damarlarına,can verdi. Yürüdü topra...', ARRAY['Türk Edebiyatı','Şiir','Recep Uslu']::text[], 8.5, '{"poet":"Recep Uslu","poet_slug":"recep-uslu","theme":"Türk Şiiri","is_hero":false,"total_lines":65,"source_url":"https://www.antoloji.com/toprak-atam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendi Hikayeni Kendin Yaz', 'kendi-hikayeni-kendin-yaz-i-dris-aydin-utjw6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'KENDİ HİKAYENİ KENDİN YAZ

Bir şarkının mısralarından gelen

Ansızın açtığın ela gözlerinden

Bir düş,bir yaşam,bir aşk çaldım

Akşamın en soluksuz zamanlarında.

Yüreğinin ırmaklarında kaç kez yıkandın

Dolaşmadığın kaç kent kaldı

Sevemeden yitirdiğin kaç insan

Şimdi gözlerin bir yıldız haresi

Yüreğin bir düşler ülkesi

Al benide en soğuk mevsimlerine

Ellerin ellerimle ısınsın sonbahar gecelerinde

Bir beyni dolduran sevgidir

Bir bedeni doyuran aşk

Kendini sunduğun sulardan geriye arılık kalsın

Her aşk bir serüvendir yelkensiz gemilerle

Yaşamın kıyısına vuran dalgalara

Kendi hikayeni kendin yaz...

İdris Aydın', 'KENDİ HİKAYENİ KENDİN YAZ Bir şarkının mısralarından gelen Ansızın açtığın ela gözlerinden Bir düş,bir yaşam,bir aşk çaldım Akşamın en soluk...', ARRAY['Türk Edebiyatı','Şiir','İdris Aydın']::text[], 8.5, '{"poet":"İdris Aydın","poet_slug":"i-dris-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/kendi-hikayeni-kendin-yaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Sevgim Allah İçim', 'benim-sevgim-allah-i-cim-yusuf-onder-bahceci-lxkp4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İçimden geldiği gibi şiir yazarım,

Çok iyi niyetliyim, iyi yazarım,

Çakallardan, sırtlanlardan bir hayli bizarım,

Benim sevgim Allah için......

Hak rızası denince akan sular durur,

Boşa geçen zamana vah derim eyvah derim,

Hainleri görürüm kendi kendimi yerim,

Benim sevgim Allah için.

Sabrım çoktur gözlerim bakar durur,

Bu yılanlar herkesi böylece sokar durur,

Bazıları kuduz köpek olmuş kudurur,

Benim sevgim Allah için.....', 'İçimden geldiği gibi şiir yazarım, Çok iyi niyetliyim, iyi yazarım, Çakallardan, sırtlanlardan bir hayli bizarım, Benim sevgim Allah için......', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/benim-sevgim-allah-icim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gerçek Acılara Mahkum Kaldık', 'gercek-acilara-mahkum-kaldik-tunahan-ermihan-6w3my', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gönül bağında solmakta olan bir kır çiçeği olmaya razıyken yürek

Hazan vurdu masalımsı düşlerimizi gerçek acılara mahkum kaldık

Şimdi şiirimsi satırlarda nazlasam da yitik düşlerimizi

Karlar altında ısıtmak için yaktım tüm hayallerimizi

Geceni aydınlatmaya çalışan bir sokak lambası olmaya razıyken yürek

Koyu yalnızlıkların ağına düştü aydınlık yeminlerimiz

Ben bir mum misali ışıtmaya çalışsam da anılarda kalan hazineyi

Yanmak için yakıyorum her an tüm hayallerimizi

Canım dediğin bir anın kölesi olmaya razıyken yürek

Boşlukta asılı kalan sessiz sözlerin mahkumu olduk

Kara bir kışta durdu zamanımız camlarımız kırık

Hayallerimizi yakıyorum bebeğim evimizi ısıtmak için', 'Gönül bağında solmakta olan bir kır çiçeği olmaya razıyken yürek Hazan vurdu masalımsı düşlerimizi gerçek acılara mahkum kaldık Şimdi şiirim...', ARRAY['Türk Edebiyatı','Şiir','Tunahan Ermihan']::text[], 8.5, '{"poet":"Tunahan Ermihan","poet_slug":"tunahan-ermihan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gercek-acilara-mahkum-kaldik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adını sen koy', 'adini-sen-koy-perihan-dosgul-ouxak', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Nice sevdalar kavuşmaktan yoksunlaşarak

Yüreklere sığmaz, taşar taşar...

Sızan sevdasızlığın gölgesine sığınarak, 

Issız gecelerin, yıldızsız yanlızlığında avunarak...

Ve ay ışığında mehtaba karşı haykırışlarını...

Dalgalanarak yüreklerden, gecenin karanlığına

Sevgilinin pervasızlında gizlediği,

Umutlarla besleyerek, sonsuzluğa sunuşlar gibi

Mabedininde sonsuza kadar saklayarak sevmek....

Aşkı kutsallaştır...', 'Nice sevdalar kavuşmaktan yoksunlaşarak Yüreklere sığmaz, taşar taşar... Sızan sevdasızlığın gölgesine sığınarak,  Issız gecelerin, yıldızsı...', ARRAY['Türk Edebiyatı','Şiir','Perihan Dosgül']::text[], 8.5, '{"poet":"Perihan Dosgül","poet_slug":"perihan-dosgul","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/adini-sen-koy-42-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Selam', 'selam-abdullah-odabas-4ff1y', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Besmele ile olunur işimiz,                   	

Hayır olsun ağır geldi kışımız,                  	

Gece gündüz memlekettir düşümüz,             	

Selam size sefa size dostlarım,                

Erzurumun kışı hüküm sürüyor,                    	

Vesaitler yürümekten duruyor,                    	

Püsen tutmuş ağaç dalın kırıyor,                 	

Selam size sefa size dostlarım,                  	

Cümle dostun sürsün evlat sefası,                	

Gardaş sayesinde aldım baba duası,              	

Bekir, Musa, Hüseyin’le Şakiri alıp gelsin,   	

Gözüm yolda gözler sizi dostlarım,               	

Her tarafta fakirlerin hali o,                   	

Kömür odun yok doya doya içmez su,          	

Takdirine razı derki kısmet bu,            	

Kalbi nazik,gönlü yufka fakirlerim dostlarım,	

Zenginlerin servet sağman bir de ahuru,          	

Düşünür mü yetim,mazlum,düşkün ile fakiri,	

Vur patlasın çal oynasın bulur keyfi çakırı,    	

Keder eder iman ehli mümin olan dostlarım, 	

Bugün bizler hep şaşırdık rotayı,                	

Peygamberi koyduk tuttuk modayı,           	

Düşünen yok günah ile hatayı,                    	

Bu gidişle hal felaket dostlarım,             	

Çok derine dalmayalım bö çıkar,

Anarşistler dükkan hamam han yakar,

Gün geçmeden talebeler can yakar,

Bu gidişten dönüş lazım dostlarım,

Bırakalım lafı söze dönelim,

Aşkı vatan ile her an yanalım,

Yaz gelince vesaite binelim,

O günleri bekliyoruz dostlarım,

Kahvelerde çay içeriz yan yana,

Hoş sohbetler ne hikmetler hayranım o irfana,

Selam olsun eşe dosta vatana,

Gurbet elde garip ağlar dostlarım,

Gene şu an kabuk kalktı yaradan,

Karlı dağlar kalkarmı hiç aradan,

Sabırlar ver yeri göğü yaradan,

Vatanından cüda ağlar dostlarım,

Seherlerde ah edermiş ayıklar,

Gurbet elde garip vatan sayıklar,

Dua kılın bize ey uyanıklar,

Kavuşalım vatana biz dostlarım,

Hızır İlyas görünürse bize sal,

Meftuniye nasip olsun o visal,

Üç ay sonra gelir elbet o bahar,

Salim kardaş, Bekir Odabaş nice dostlarım,

Dert dökmeye arıyorum bahane,

Sizin gibi dostlarım var daha ne,

Kabristanda baba, kardeş bir anne,

Ruhlarına bir fatiha dostlarım,', 'Besmele ile olunur işimiz,                   	 Hayır olsun ağır geldi kışımız,                  	 Gece gündüz memlekettir düşümüz,          ...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Odabaş']::text[], 8.5, '{"poet":"Abdullah Odabaş","poet_slug":"abdullah-odabas","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/selam-45-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Onuru İle Yaşansın...', 'ask-onuru-i-le-yasansin-i-brahim-ethem-bingul-1d6wf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yaşadığımız hayat sonu meçhul masaldı

Pusulamızdaki tek yön sadece aşktı

Birlikte aldığımız her nefes

Bizi birbirimize sarmaşık gibi sardı...

Yollarımız mutlulukta kesişti

Başlangıç kaderdi, seçimimiz değildi

Sonu da yoktur bunun, bilirsin nedenini

Bu aşkın kaynağı o tükenmez yerdendi...

Di''li geçmiş zaman yanıltmasın

Sevda rafa kalktı sanılmasın

Her şey taze, daha yeni başlıyor

Yeter ki aşk onuru ile yaşansın...

www.iebingul.com', 'Yaşadığımız hayat sonu meçhul masaldı Pusulamızdaki tek yön sadece aşktı Birlikte aldığımız her nefes Bizi birbirimize sarmaşık gibi sardı.....', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ask-onuru-ile-yasansin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Erzurum', 'erzurum-abdullah-odabas-cx647', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '(Salim AKÇA''ya) 

Erzurumun dağı duman gönlü hoş,         	

Seherlerde öter türlü çeşit kuş,        	

Yazı azdır tatlı serin olur kış,        		

Dua almış velilerden Erzurum,           	

Serhat şehir şehitlerle doludur,        	

Doğu illerinin bir tek gülüdür,         	

Hafızlar kuran okuyor camii doludur,    	

Binbir hatim okutuyor Erzurum,          	

Ramazanı güzel her gün vaazlar,         	

Vaaz coşmuş yaş döküyor hep gözler,     	

Bir ok gibi tesir eder o sözler,        		

Alimi çok dervişi bol Erzurum,         	

Manevi bir nazar vardır özünde,

Kışı soğuk sefa vardır yazında,

Abdurrahman Gazi yatar yüzünde,

Velilerin durağıdır Erzurum,

Palandöken Dumlu Baba çevresi,

Yüreğinde vardır düşman yaresi,

Türkiyenin kilit nokta kalası,

Dağı taşı dolu asker Erzurum,

Ismarladım beni yazla kışına,

Gezme kardeş bu kem terin peşine,

Okudum destanın baksan yaşıma,

Gözüm ağlar gönül ağlar Erzurum,

Meftuniden teşekkürler Salim''e

Sadık dostum vakıf olur halime,

Size karşı söz bilemem kelime,

İşte böyle dostum vardır Erzurum,', '(Salim AKÇA''ya)  Erzurumun dağı duman gönlü hoş,         	 Seherlerde öter türlü çeşit kuş,        	 Yazı azdır tatlı serin olur kış,       ...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Odabaş']::text[], 8.5, '{"poet":"Abdullah Odabaş","poet_slug":"abdullah-odabas","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/erzurum-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdan Yakar', 'sevdan-yakar-ahmet-unal-cam-r5jst', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu diyarlar beni boğar,

Ben giderim, zalim bakar.

Sen üzülme zalim yarim,

Sen yokken de sevdan yakar.

“Karadır bu bahtım kara”

Düşmüşüm bir zalim yara

Hele bakın, bakın hal’a

Ben yanarım, eller bakar', 'Bu diyarlar beni boğar, Ben giderim, zalim bakar. Sen üzülme zalim yarim, Sen yokken de sevdan yakar. “Karadır bu bahtım kara” Düşmüşüm bir ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ünal Çam']::text[], 8.5, '{"poet":"Ahmet Ünal Çam","poet_slug":"ahmet-unal-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sevdan-yakar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cane', 'cane-ayten-ozlem-yesilcali-istvd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gül idim daldan kopardılar..

Canımı candan ayırdılar.

Sözün idim dilden etiler beni.

Gözün idim.ferden etiler 

Beni senden ayırdılar.

Gönlüm figan eder..

Kimse bilmez hiç durmaz aglarım.

İsyan ederim feleğe..

Karaları bağlarım yüreğime.

Kalbim kırk,kaldı yürek dağlandı.

Kimi sevsin kime bağlansın.

Cane bırak gönül daglansın.

Gözler durmazsın ağlasın.

Kayıp olmuş bir ömür karaları baglasın', 'Gül idim daldan kopardılar.. Canımı candan ayırdılar. Sözün idim dilden etiler beni. Gözün idim.ferden etiler  Beni senden ayırdılar. Gönlüm...', ARRAY['Türk Edebiyatı','Şiir','Ayten Özlem Yeşilçalı']::text[], 8.5, '{"poet":"Ayten Özlem Yeşilçalı","poet_slug":"ayten-ozlem-yesilcali","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/cane-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şairim, kimsesizim', 'sairim-kimsesizim-ahmet-unal-cam-1eh68', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Karartmadan, kendi bahtlarını

Son şiirimi sökecekler kalbimden

“Atın, hayır yok artık bu bedenden”

deyip, sürecekler atlarını...', 'Karartmadan, kendi bahtlarını Son şiirimi sökecekler kalbimden “Atın, hayır yok artık bu bedenden” deyip, sürecekler atlarını......', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ünal Çam']::text[], 8.5, '{"poet":"Ahmet Ünal Çam","poet_slug":"ahmet-unal-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sairim-kimsesizim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözgöze Gelince', 'gozgoze-gelince-ahmet-unal-cam-90gom', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gülümseyişim 

     önceden kalmıştı

                  gözümde

  Bir an  gözgöze  gelince

               Alınıverdin üstüne', 'Gülümseyişim       önceden kalmıştı                   gözümde   Bir an  gözgöze  gelince                Alınıverdin üstüne...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ünal Çam']::text[], 8.5, '{"poet":"Ahmet Ünal Çam","poet_slug":"ahmet-unal-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/gozgoze-gelince-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkuyorum (2)', 'korkuyorum-2-murat-polat-2-jnh8h', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ölümden korkmuyorum

Sakat kalmaktan

Hasta yatmaktan

Düşüp kalmaktan...

Günahtan korkmuyorum

Yaratandan da, ona kavuşmadan

Hesap anından

Geçeceğim o köprüden...

Sokaktan kormuyorum

Evde yalnızlıktan

Kalabalıktan, kargaşadan

Sessizlikten, gürültüden...

Ben artık yoruldum

Ben artık...

Korkmamaktan korkuyorum

                   Murat Polat

                   23/12/2005', 'Ölümden korkmuyorum Sakat kalmaktan Hasta yatmaktan Düşüp kalmaktan... Günahtan korkmuyorum Yaratandan da, ona kavuşmadan Hesap anından Geçe...', ARRAY['Türk Edebiyatı','Şiir','Murat Polat 2']::text[], 8.5, '{"poet":"Murat Polat 2","poet_slug":"murat-polat-2","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/korkuyorum-2-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kör Kıskançlığa Dair', 'kor-kiskancliga-dair-alper-kuruk-ojjrl', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Elimde değil

Kıskanıyorum.

Dünya çirkinleşiyor gözümde

Yalnız ve yalnız o güzel

Bir o bana benden

Ondan gayrısı el...

O,benim için gerçek

O,erişilmeyen umut

Birgün ölecek

Yine de kıskanıyorum.

Tutuşup hûri oğlanlarıyla elele

Bensiz bahçelerde gezecek

Allah''ım yine kıskanıyorum

Ellerini tutacak temiz elleri çek! 

Ne de olsa bir insan oğluyum...

Kötü düşünebilirim ne de olsa.

Allah''ım,Allah''ım kıskanıyorum

Onu,niçin bilmiyorum? 

Bir türlü içim rahat etmeyecek...', 'Elimde değil Kıskanıyorum. Dünya çirkinleşiyor gözümde Yalnız ve yalnız o güzel Bir o bana benden Ondan gayrısı el... O,benim için gerçek O,...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/kor-kiskancliga-dair-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Demet Demet', 'demet-demet-alper-kuruk-ucscq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aşkını demet demet

Satılığa çıkardın,

Bir demet te bin nazla 

Bana sattın.

Diğerlerindeki demetler

Eminim ki soldu,buruştu

Pörsük pörsük...

Bana verdiğin demet

İnan dün kadar taze

Gıcır gıcır...

Ama beni koyduğun gibi bulamazsın

Ben çok değiştim

Hâlimi gören acır.

Gönlüm çöktü 

Sen altında kaldın...', 'Aşkını demet demet Satılığa çıkardın, Bir demet te bin nazla  Bana sattın. Diğerlerindeki demetler Eminim ki soldu,buruştu Pörsük pörsük... ...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/demet-demet-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaderimsin Ey Ben..Ey Sen..!', 'kaderimsin-ey-ben-ey-sen-okan-nar-4ntp6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bana yakın nefes gibi,

Ve fakat ulaşılmaz sen..! 

Güneşi kovaladım durdum sürekli,

Gölegeleri avuçladım,

Ama ellerim kanadı,avuçlarımda çakıllar..! 

Gecelerde yıldızlara uzandım,düştüm..

Uyandığımda ellerim hep boş.

Seni bekledim,

Seni sorguladım,

Senle hemhal oldum,

Ey gerçek..! 

Batınında varlığını yaşadığim, 

Seviştiğim sulet,ey Sen..! 

Gerçeklikte ne zaman? 

Gecikme artık vuslat..! 

Seni hissettim,yudumladım her dem.

Ne arkamda nede önümde Güneş,

Tepemde gerçeklik,gölgen bende..! 

Ruhum sen..Gölgen bende ey sen..! 

Kase kase içtim,

Kuruyan dudaklarda..yanan yürekte..

Hasret ey sen..! 

Ey gerçeklik..

Ey sen..Ey ben..Ey sevgili...! 

(22-12.2005 00:30)', 'Bana yakın nefes gibi, Ve fakat ulaşılmaz sen..!  Güneşi kovaladım durdum sürekli, Gölegeleri avuçladım, Ama ellerim kanadı,avuçlarımda çakı...', ARRAY['Türk Edebiyatı','Şiir','Okan Nar']::text[], 8.5, '{"poet":"Okan Nar","poet_slug":"okan-nar","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/kaderimsin-ey-ben-ey-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Masal', 'masal-hulya-kandemir-zy8af', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir masaldın sen, sevdalılara anlatılan

Her kalpte bir tutam tükenmişlikle yaşanan

Bir masaldın sen, 

Kahramanı olmayan

Her rengin ebruliydi ve

Solgun renklerdendi gökkuşağın

Toprakların kurumuştu susuzluktan

Bir masaldın sen

Sessizce vedalaşırken 

Gökten düşen üç elma ile noktalanan…', 'Bir masaldın sen, sevdalılara anlatılan Her kalpte bir tutam tükenmişlikle yaşanan Bir masaldın sen,  Kahramanı olmayan Her rengin ebruliydi...', ARRAY['Türk Edebiyatı','Şiir','Hülya Kandemir']::text[], 8.5, '{"poet":"Hülya Kandemir","poet_slug":"hulya-kandemir","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/masal-113-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir avuç gözyaşı', 'bir-avuc-gozyasi-hulya-kandemir-7zg6r', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Geldiğinde mevsim bahardı

Gönlümde açıyordu nergizler…

Gittiğinde yaşadım sonbaharı

Yanaklarımda bir avuç gözyaşı…

Kalbimde kopan fırtınalar

Boğazımda düğümleniyor. 

Nefes aldırmıyor senden kalan her bir an,

Silinmiyor görüntüler…

Ellerin saçlarımda geziniyor

Dudaklarımda bir acı…

Kaçsam da her defasında yakalanıyorum karamsarlığa

Unutmak istedikçe seni hatırlatıyor:

Bir avuç gözyaşı…', 'Geldiğinde mevsim bahardı Gönlümde açıyordu nergizler… Gittiğinde yaşadım sonbaharı Yanaklarımda bir avuç gözyaşı… Kalbimde kopan fırtınalar...', ARRAY['Türk Edebiyatı','Şiir','Hülya Kandemir']::text[], 8.5, '{"poet":"Hülya Kandemir","poet_slug":"hulya-kandemir","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bir-avuc-gozyasi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah Yitirilmişliğim', 'ah-yitirilmisligim-saadet-un-fod22', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'yitirilmişliğimin

yollarında buldum seni

yıkıklığımın 

en sitemli anında

tomurcuklar daha bir güzel açtı

güller daha bir güzel koktular

göremedim dikenlerini

biliyordum ve diliyordum

biliyordum

on adımın hep benden

bir adımın senden geleceğini

daha dünden

diliyordum

kaybetmemeyi seni

çünkü

koca yürekli küçücük dünyamdın

çünkü yalnızlık 

iki başlı bir canavardı! İliklerimde gezinen

çünkü 

ben sana

muhtaçtım

silmeliydim ve bitirmeliydim

yitirilmişliğimin

yollarına götürüp koydum seni

yıkıklığımın en sitemli anında

tek kalem de yeterdi bana

kendini beğenmişliğini

küçümseyen sözlerini

güllerini

dikenlerini

sildim ve bitirdim

ah yitirilmişliğim...', 'yitirilmişliğimin yollarında buldum seni yıkıklığımın  en sitemli anında tomurcuklar daha bir güzel açtı güller daha bir güzel koktular göre...', ARRAY['Türk Edebiyatı','Şiir','Saadet Ün']::text[], 8.5, '{"poet":"Saadet Ün","poet_slug":"saadet-un","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/ah-yitirilmisligim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Giz', 'giz-ugur-aydin-2-dojil', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bilmem hatırlıyormusun sende kar tanelerini..

hep bir hüzün bırakır dı yüreğimize 

seyredirdik karanlık gecelerde semadan düşüşlerini

o gün hüzün bıraktı  bügünse ayrılık..yüreklerimize

bilirsin anam beni, karlı bir kış günü dünyaya getirdi

aylardan ocaktı ben üsüyordum 

yıllar sonra sordum ona oda sevememişti benim gibi 

bu yüzdendir belkibe sevemedim kar tanelerini

hep anlatırlar kartanelerinin melek hikayelerini 

bize getirtikleri saklı bir giz di

ogün hüzün bügünse ayrılık bize 

 bu yüzden sevemedim kar tanelerini..', 'bilmem hatırlıyormusun sende kar tanelerini.. hep bir hüzün bırakır dı yüreğimize  seyredirdik karanlık gecelerde semadan düşüşlerini o gün ...', ARRAY['Türk Edebiyatı','Şiir','Uğur Aydin 2']::text[], 8.5, '{"poet":"Uğur Aydin 2","poet_slug":"ugur-aydin-2","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/giz-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanıyorum', 'yaniyorum-emre-yildirim-ibhfh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dışarıda zifiri karanlık,

Herkesin bildiği bir kış akşamını yaşıyorum  yine.

Hava,buz gibi

Sigaramın dumanı yakıyor gözlerimi.

Dalıyorum uzaklara,

Tane tane yağan karları izliyorum.

Aklıma düşüyor gözlerin,

Ağlıyorum.

Üşümüyormusun diye sakın sorma,

Hasretinleyim,

........................yanıyorum', 'Dışarıda zifiri karanlık, Herkesin bildiği bir kış akşamını yaşıyorum  yine. Hava,buz gibi Sigaramın dumanı yakıyor gözlerimi. Dalıyorum uza...', ARRAY['Türk Edebiyatı','Şiir','Emre Yıldırım']::text[], 8.5, '{"poet":"Emre Yıldırım","poet_slug":"emre-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/yaniyorum-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ateş Benimle Yürür', 'ates-benimle-yurur-elvan-genc-di7j7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir melek dokunuşuydu gülüşün,

Çok uzaklardan gelmiş

Veya uzaklara götürecek beni...

Bir anlıktı, tadımlıktı belki..

Derinimdi gözlerin; 

Kaybolmalı dercesine

Kendimden geçercesine...

Tonuydu binbir çeşidinde yeşilin,

Ruhunu kucağıma dökercesine..

Şiiri yazılır güzelliğinde,

Saklı günlerin bahçesinde..

Biliyorum; Ateş Benimle Yürür,

Sevginin her merhalesinde...

                           Haziran 2005', 'Bir melek dokunuşuydu gülüşün, Çok uzaklardan gelmiş Veya uzaklara götürecek beni... Bir anlıktı, tadımlıktı belki.. Derinimdi gözlerin;  Ka...', ARRAY['Türk Edebiyatı','Şiir','Elvan Genç']::text[], 8.5, '{"poet":"Elvan Genç","poet_slug":"elvan-genc","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ates-benimle-yurur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasıl anlatmalı', 'nasil-anlatmali-i-brahim-kamis-e09gs', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Nasıl anlatmalı ki sana..

		Seni..

	

Gözlerimin önünde uçuşan,

 migren parçaları gibi sesin.

Sesin, sessizliği yaran ikinci bir ses olmalı şimdi.

Duvarlara çarpan sevgin mi yoksa? 

Ellerim ayalarıyla sana dönük,

İçlerini görebiliyor musun? 

Kızıl bir rüzgar içinde,

Kokun yayılıyor.

Odaların içlerinde sesinden başka

Umutsuzluk var..

Bir rüzgar çıkacak orta yerde

Şeytan düğümlerine takacak,

		Tüm olumsuzlukları..

Götürecek bizden uzaklara..

Artık ekmeğin bayat olmasının önemi olmayacak.

Yada yemeğin soğuk oluşunun..

Yine büyük bir devinimle çalacak plakta ezgiler,

Çocuklar açlıktan ölecekler yine,

Yine dayak yiyecekler sofralarında..

Ama ekmeğin bayatlığının 

Yemeğin soğuk oluşunun önemi yok..

Bu gün o gün...', 'Nasıl anlatmalı ki sana.. 		Seni.. 	 Gözlerimin önünde uçuşan,  migren parçaları gibi sesin. Sesin, sessizliği yaran ikinci bir ses olmalı ş...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Kamış']::text[], 8.5, '{"poet":"İbrahim Kamış","poet_slug":"i-brahim-kamis","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/nasil-anlatmali-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Belki de', 'belki-de-gulcan-sakal-zdwzb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bilmiyorum neredeyim

Öylesine kafama esti geldim işte

Farklı bir hava solumak 

İstedi canım belki...

Belki İstanbul''u özlemek istedim

Kıymetini anlamak istedim

Geldim işte yabancı bir şehre 

Umutlarıma yabancı 

İçimdeki dostcanlısı hayallere yabancı

Yürüdüğüm yollar

Oturduğum yer yabancı

Garson yabancı

Çayın tadı yabancı

Aslında huzur dolacaktı içime

Kafamı dinleyecektim bir süre

Tadını çıkaracaktım uzaklığın

Ama öyle olmadı nedense...

Sıkıldım bu yabancı şehirde

Gitmek istedim bir an önce

İstanbul''uma

Benim şehrime

Neydi arayıpta bulamadığım

Yanlış bir seçimdi kimbilir 

Belki de......', 'Bilmiyorum neredeyim Öylesine kafama esti geldim işte Farklı bir hava solumak  İstedi canım belki... Belki İstanbul''u özlemek istedim Kıymet...', ARRAY['Türk Edebiyatı','Şiir','Gülcan Sakal']::text[], 8.5, '{"poet":"Gülcan Sakal","poet_slug":"gulcan-sakal","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/belki-de-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmuyor*', 'olmuyor-elvan-genc-vj7v9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gözümün ucunda bir damla yaş,

Damlayamıyor,

Görmek istedikleri var..

Yüreğimde buruk, tuhaf bir sızı

Sızlayamıyor,

Yaşamak için sebepleri var

Dilimin ucunda birikmiş sözler,

Söyleyemiyor,

Üzüleceklerin umutları var..

        21.04.2005/Trb.

*Bu şiir Annem tarafından bana yazılmıştır.', 'Gözümün ucunda bir damla yaş, Damlayamıyor, Görmek istedikleri var.. Yüreğimde buruk, tuhaf bir sızı Sızlayamıyor, Yaşamak için sebepleri va...', ARRAY['Türk Edebiyatı','Şiir','Elvan Genç']::text[], 8.5, '{"poet":"Elvan Genç","poet_slug":"elvan-genc","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/olmuyor-48-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SANTEK - Üç yalan! ..', 'santek-uc-yalan-mehmet-coban-f86uz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Nasılsın? 

İyiyim……….

İşler nasıl? 

İyi…………

Çocuklar nasıl? 

İyiler………..

Her gün,

Sorarız usulünce

Alacağımız cevabı bile, bile

Her gün,

Söyleriz herkese

Vereceğimiz cevabı bile, bile

İçimiz kan ağlasa da, 

İşlerimiz kötü olsa da, 

Evde her şey yolunda olmasa da

İyidir, 

İyiyimdir, 

İyilerdir! ..

Hep birlikte inanırız

Masumdur yalanımız

Sevdiklerimizi 

Üzmemektir kastımız

Ama,

Yalan yalandır

Amaç,

Böyle inanmak, 

Böyle inandırmaktır

Yalanı sokmak istemeyiz

Kimliğimize kişiliğimize

Yetiştirdiğimiz neslimize

Evimize, işimize, benliğimize! ..

Ama kurtulamayız 

Ortak yalanımızdan

Yalan olmaktan çıkmıştır

Her gün söylediğimiz yalan

23.12.2005-İzmir', 'Nasılsın?  İyiyim………. İşler nasıl?  İyi………… Çocuklar nasıl?  İyiler……….. Her gün, Sorarız usulünce Alacağımız cevabı bile, bile Her gün, Söy...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Çoban']::text[], 8.5, '{"poet":"Mehmet Çoban","poet_slug":"mehmet-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/santek-uc-yalan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüyalar Alemi', 'ruyalar-alemi-ertugrul-gokceli-hzl2q', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Şu an sanırım uyuyorsun

Ben gözlerinden yoksun

Yaşarmıyım sanıyorsun 

Rüyalar aleminde

Aşktan kaçmak çok zor

Yüreğimde bir kor

Yandıkça yanıyor 

Rüyalar aleminde

Sensiz gecem gündüz olmaz

Benim yüreğim çarpar durmaz

Güller ağlar artık solmaz

Rüyalar aleminde

Gözler oldu bir pınar 

Sular koca bir çınar

Benim gönlüm kime yanar

Rüyalar aleminde

Ben ne düşteyim ne rüyada

Gönlüm bir güzele tutuldu yanar

İnsan arkasına dönüp bakarda 

Bu güzel  kimmiş diye bir sorar', 'Şu an sanırım uyuyorsun Ben gözlerinden yoksun Yaşarmıyım sanıyorsun  Rüyalar aleminde Aşktan kaçmak çok zor Yüreğimde bir kor Yandıkça yanı...', ARRAY['Türk Edebiyatı','Şiir','Ertugrul Gokceli']::text[], 8.5, '{"poet":"Ertugrul Gokceli","poet_slug":"ertugrul-gokceli","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ruyalar-alemi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşantım Siyah Beyaz', 'yasantim-siyah-beyaz-seyhmus-sait-aydin-pxxi2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yaşantım Siyah Beyaz,

Yedi rengi İsterim.

Boz buluttan sıyrılıp,

Güneş Görmek isterim.

Durgun Akan bir suyum

Sakin Deniz İsterim,

Ama heyhat ümüt yok,

Hiç yanılmaz hislerim.

Sahipsizdir şiirlerim,

resimsizdir düşlerim,

seversem şaşırırım,

Düz yol’da da düşerim.', 'Yaşantım Siyah Beyaz, Yedi rengi İsterim. Boz buluttan sıyrılıp, Güneş Görmek isterim. Durgun Akan bir suyum Sakin Deniz İsterim, Ama heyhat...', ARRAY['Türk Edebiyatı','Şiir','Şeyhmus Sait Aydın']::text[], 8.5, '{"poet":"Şeyhmus Sait Aydın","poet_slug":"seyhmus-sait-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yasantim-siyah-beyaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ebediyet Yolcusu', 'ebediyet-yolcusu-hamza-mamas-ecrdo', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ebediyet yolcusu git güle güle…

Ardında yıllar var yollar var ardında,

Sonsuzluk şarkı olmuştu dilinde,

Şimdi ise sen sonsuzluğun içinde.

Ne kaldı ki bakışlarından geriye,

Sevilende unutulurmuş anladım.

Eller sallanırda gidenlerin ardından,

Ve yollar vefasızmış farkına vardım.

Bir boşluk var şimdi gönlümde,

Sönmeyen bir ateş yanar yüreğimde,

Hazan şarkıları susmaz dilimde,

Yoksun, yolcusun sen; isyanım yalnızlığa.

Gözyaşı mukaddestir onu da döktüm,

Acırda dönersin diye boynumu büktüm,

Şimdi seni sensizliğe bıraktım,

Dönmeyeceksin; ebediyet yolcususun anladım.

               23/06/2000-çağlayan', 'Ebediyet yolcusu git güle güle… Ardında yıllar var yollar var ardında, Sonsuzluk şarkı olmuştu dilinde, Şimdi ise sen sonsuzluğun içinde. Ne...', ARRAY['Türk Edebiyatı','Şiir','Hamza Mamaş']::text[], 8.5, '{"poet":"Hamza Mamaş","poet_slug":"hamza-mamas","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ebediyet-yolcusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ya sev Ya da...', 'ya-sev-ya-da-elvan-genc-zu6zq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ya beni seversin ya da seversin..

Çünkü bundan böyle artık benimsin..

Sahibin değil, bil ki kölenim...

Ya beni seversin ya da seversin...

         23.12.2005/Cuma', 'Ya beni seversin ya da seversin.. Çünkü bundan böyle artık benimsin.. Sahibin değil, bil ki kölenim... Ya beni seversin ya da seversin...   ...', ARRAY['Türk Edebiyatı','Şiir','Elvan Genç']::text[], 8.5, '{"poet":"Elvan Genç","poet_slug":"elvan-genc","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ya-sev-ya-da-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çerkez mahmut kalfanın hazin sonu', 'cerkez-mahmut-kalfanin-hazin-sonu-munevver-senol-999hb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çerkez mahmut kalfanın hazin sonu.

Çerkez mahmut kalfa çekirdekten yetişme bir inşaat ustasıdır,ona arsayı ver

projeyidever gerisie karışma,çatıya bayrağı asar teslim eder,içinin badanasınıda filit pompasına koyduğu renkli badanalarla püskürterek çiçek

motifleriyle şimdiki duvar kağıdı gibi badana yapardı,yıllarca devlet su işlerinde çalıştı,taaki kızı münevverin okul hayatı başlayana dek münevver ilk okul biri elazığda ikiyi malatyada okurken,istanbuldaki kızkardeşi nebiyenin

kocası eski pehlivanlardan vahit üsküdar da kereste tüccarıdır mahmut sen

inşaatten anlıyorsun gel ortak mütehatlik yapalım teklifine çok sevinir,

kızkardeşi üsküdarsultantepede büyük bir köşkte oyurmaktadır ve taras katı

nıda abisine tutacaklardır,ama o zaman rahmetli tugut özalın abisi korkutözal

d.s.i.müdürüdür mahmut kalfanın istifa dilekçesini geri çevirir,kalfa iyi bir

eleman olduğu kadar arkadaşları tarafındanda sevilen biridir,ama onun için

münevverin okul hayatı daha önemlidir münevver büyük şehirde okumalı

öğretmen olmalı çünki idealibudur kalfanın,ve istanbula gelir o şirin tarasa taşınırlar,oradada ikinci kızları münire doğar,ama işler umdukları gibi gitmemektedir,çok soğuk birkış hüküm sürmektedir akşamdan yarına hazır olsun diye kardıkları harç gece ayaz yapınca taş kesilir,ekonomi altüst olmuş

küçük esnafın kepenk kapattığı bir yıl alım gücü azalınca pahalı aldıkları demir

bile yarı fiatına inince inşaati zararına verip işçilerin parasını ödemişler iflas

kaçınılmaz olmuş,eniştesi herkes başının çaresine baksın der kendisinin

silahtarda üç katlı evi vardır onu satar ama mahmut kalfa zaten birikimini

inşaate yatırmıştırkarısı ayşenin kolundaki üç beş bilezikten başka birşey

kalmamıştırköşkün tarasından pendikte bir gecekonduya taşınır,hergün

aletlerini koyduğu zembil dediği çantasıyla amele pazarı tabir edilen bir kahve vardır herkes orda toplanır işçi arayanlargelirler ama mahmut kalfa

her seferinde eli boş gelir çünki taşaron dedikleri insanlar orayı tekeline almış hem işçiden hemde müşteriden para alıp fiat kırmaktadır,kalfanın evinde sefalet başlamıştır,üç öğün tarhanaya talim ederler,ev kirasıda birikmiş ev sahibinin karısı eğer şu ipek duvar halısını satarsanız haberim olsun iki aylık kiraya sayarım annem çaresiz verirdi çünki bozduracak altında kalmamuştı,bigün komşumuz gülser teyze geldi bak mahmut abi namusuyla çalışmak ayıp değil benim çalıştığım tarım koruma fabrikası kadın işçi alıyor ayşede girsin hiç olmassa sen devamlı bir iş bulana kadar bak her ay bir eşyan gidiyor nereye kadar,mahmut kalfa çaresiz kabul eder  ama kadrolu iş bulunca çıkmak şartıyla,ayşe işe başlar baharda gelmiştir inşaatlerin başladığı ay birgün sevinçle gelir eve cevizlide bir fabrika inşaatine ek bina yapılacak çalışan işçilerde kadrolu işe alınacaktır,ek binayı yaparlar ama kadroya geçmesi için üç ay çalşması lazımdır,fabrika sahibi bir çekme kat daha çıkalım der ama mahmut kalfa gerilim hattının çok yakın olduğu için tehlikeli olduğunu söyler,oda siz çerkezler  korkmazssınız diye ısrar edince

çaresiz kabul eder kadroya geçecek karısını işten çıkaracaktır ya,neyse oda,bitmiş bir çatısını kapatması kalmıştır ağızlıkla içtiği sigarasını bile yarım bırakıp çıkar çatıya ama korktuğu olur belindeki keser den geriim hattından ceryanı çeker büyük bir patlama kalfayı aldığı gibi beyinüstü yere çakar

beyni bir bomba gibi patlamış elinde tutnmak için yakaladığı kalasla son nefesini vermiştir,halbuki o sabah evden çıkarken münevvere kardeşine iyi bak bugün para vericekler kardeşinle sana bebek alıcm demişti,fabrika 

sahibi hemen işçileri topluyo,bakın böyle olmasını istemezdim şimdi hepiniz çok uğraştık ikna edemedik kendini attı diye ifae verin sizi kadroya alıcam 

giden gitti burası kapansa hepimize zararı olucak işçiler çaresiz kabul ediyor

zaten hükümet tabibi bende ağır yaralıydı yolda öldü derim ama kimliği lazım eve iki adamını yolluyo münevverede baban  düştü atağı kırıldı hastane nufus kağıdı istiyor deyince oda veriyor ne bilsin insanların art niyetini,süreyyapaşa hastanesinin mogunda boşalan beyinin yerine hastanenin amblemini taşıyan havluyu tampon yapıyorlar,zavallı ayşe eşinemi yansın yoksa çocuklarıyla

ikidebir intiharın sebebi ne diye savcının ifadesinemi münevverde hayır babam bize bebek getirecekti diye ifade veriyor kalfanın kırk mevlüyünde bir 

adam çıkageliyor bakın ben onun en iyi arkadaşıydım diye olanbiteni anlatıyor ve ben pişmanım böyle ifade verdiğime her gece rüyama giriyo sen bana bunu nasıl yaparsın diyo ben size şahilik yapıcam diyor,mahkemede beynine konab havluda delil olarak gösterilinceayşe kazanıor maaşa bağandığı gibi tazminatta ödeniyor,oa o parayla evine yakın arsa alıyor,bu arada münevver arifiye öğretme okulunu kazanmıştır ama annesi çalışmak zorunda kardeşine kim bakacakevet münevverin oul hayatı malesef sona eriyor,arasan iki sene sonra gazetelere ölüm ilanı kalfanın fabika sahibi amansız hastalığa yenildi,dahasonra fabrika mirasçıların alaşamamaları yüzünden battı gitti,aradan seneler geçer münevver evlenmiş üçüncü çocuğuna hamiledir ana sağlığa son kontürolüne gitiğinde bayraklar yarıya inmiş bir matem havası var sorduğunda adeta kanı donar çünki mahmut kalfaya yıllar önce itihar etti rapornu veren şimdi başhekim olan

doktorun bir kızı vardır ancak ne acıdırki doğum yaparken ölmüş oğlan bebek yetim kalmıştır,işte bir babanın hatasını evladımı ödüyor yoksa

ilhi adalet bumu demeden edemiyor insan.     paylaşığınız için teşekkürler.', 'Çerkez mahmut kalfanın hazin sonu. Çerkez mahmut kalfa çekirdekten yetişme bir inşaat ustasıdır,ona arsayı ver projeyidever gerisie karışma,...', ARRAY['Türk Edebiyatı','Şiir','Münevver Şenol']::text[], 8.5, '{"poet":"Münevver Şenol","poet_slug":"munevver-senol","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/cerkez-mahmut-kalfanin-hazin-sonu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Şiirler Okunacak', 'bu-siirler-okunacak-yusuf-onder-bahceci-4iooi', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu şiirler okunacak,

Ucu yâre dokunacak,

Suçlu belli olacak,

Kaçacak köşe bucak.

Açtım torbanın ağzını,

Ne varsa diyeceğim,

''Seni çok sevdim Gülüm'',

''Çok sevdim'' diyeceğim.

Bu şiirleri okuyorsa,

Bana dua ediyorsa,

''Seni sevdim'' diyorsa,

Affet onu Allahım.

Senden başka yâr sevmedim,

Çekip gittin hiç gülmedim,

Bana yılda bir gelmedin,

Güldüğüme bakma sen.....', 'Bu şiirler okunacak, Ucu yâre dokunacak, Suçlu belli olacak, Kaçacak köşe bucak. Açtım torbanın ağzını, Ne varsa diyeceğim, ''Seni çok sevdim...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bu-siirler-okunacak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuklar', 'cocuklar-latif-bati-u8wn8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gözleri var ışıl ışıl,

Oynarlar hep cıvıl cıvıl.

Uykuları mışıl mışıl,

Ne güzeldir çocuklar! 

Hepsi açılan birer gül,

Kokuları birer sümbül.

Evimizde öten bülbül,

Ne güzeldir çocuklar! 

Evlerimizdeki çiçek,

Açılırlar hep rengârenk.

Kötülükleri bilmez  pek,

Ne güzeldir çocuklar! 

Yürekleri var tertemiz,

Düşünceleri bir deniz.

Onları incitmeyiniz,

Ne güzeldir çocuklar!', 'Gözleri var ışıl ışıl, Oynarlar hep cıvıl cıvıl. Uykuları mışıl mışıl, Ne güzeldir çocuklar!  Hepsi açılan birer gül, Kokuları birer sümbül....', ARRAY['Türk Edebiyatı','Şiir','Latif Batı']::text[], 8.5, '{"poet":"Latif Batı","poet_slug":"latif-bati","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/cocuklar-44-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dizlerinde Uyusam', 'dizlerinde-uyusam-i-smet-bora-binatli-0xzoo', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Şimdi sen olmalıydın buralarda

Sen olmalıydın sıcaklığın ellerimde

Yosun gözlerinde kaybolmuşumu

Yüzümde ilik nefesin

İçimde tatlı bir heyecan

Gönlümde sevdan.

Şimdi senin başın olmalıydı yastığımda

Bitimsiz bir heyecan.

Şimdi sen olmalıydın dudaklarımda

Söylenmemiş şarkılar mırıldansaydın

Kulaklarımda tatlı sesin

Aşk sözleri fısıldarken kalbinin ataşını duysam

Sen olsan şimdi buralarda 

Dizlerinde uyusam.', 'Şimdi sen olmalıydın buralarda Sen olmalıydın sıcaklığın ellerimde Yosun gözlerinde kaybolmuşumu Yüzümde ilik nefesin İçimde tatlı bir heyec...', ARRAY['Türk Edebiyatı','Şiir','İsmet Bora Binatlı']::text[], 8.5, '{"poet":"İsmet Bora Binatlı","poet_slug":"i-smet-bora-binatli","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/dizlerinde-uyusam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünya Değirmendir', 'dunya-degirmendir-latif-bati-ct3bp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dünya değirmendir, devamlı döner,

İnsanları öğütür birer birer.', 'Dünya değirmendir, devamlı döner, İnsanları öğütür birer birer....', ARRAY['Türk Edebiyatı','Şiir','Latif Batı']::text[], 8.5, '{"poet":"Latif Batı","poet_slug":"latif-bati","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/dunya-degirmendir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sende Doğarım', 'sende-dogarim-i-smet-bora-binatli-9fbee', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sana uyanırım ezan sesleriyle

Sen dolarsın her şafak vakti ruhuma

Gecenin bir yerinde apansız uyanmalarım

Sanadır

Sana uyurum, gecenin bir yarısında

Sana uyanırım.

Seni solurum hava diye

Sende umutlanırım.

Yine de sana hasrettir yüreğim

Ayın suya düştüğü saatlerde

Düşersin içime

Aydınlanırım

Seni ayda, ayı sende ararım

Yok olduğunu hissederim ikinizin de

Aşkınla yeniden canlanırım.

Ben sende ölürüm her gece

Her sabah sende doğarım.', 'Sana uyanırım ezan sesleriyle Sen dolarsın her şafak vakti ruhuma Gecenin bir yerinde apansız uyanmalarım Sanadır Sana uyurum, gecenin bir y...', ARRAY['Türk Edebiyatı','Şiir','İsmet Bora Binatlı']::text[], 8.5, '{"poet":"İsmet Bora Binatlı","poet_slug":"i-smet-bora-binatli","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sende-dogarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdaya davet', 'sevdaya-davet-fatma-guven-kreht', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hak için sever,Hak için ölürüz.

Yar senin yüzünde Hak''ı görürüz.

Pirler gibi bu sırra erdikçe çoşarız,

Biz bu yoldan koşarak geçeriz,

Kimimiz asılır,kimimiz yakılırız.

Salon soytarısı gibi gururlanır gezersin.

Şa''şalı ömründe yalanları söylersin.

Bilmezsin ki; etrafına tel örgüler çekersin.

Hak almak için divana çıkarsın,

Hak ''a ne verdin ki; sen ne istersin? 

Soysuzu baş tacı edip,soytarılık edersin.

Severim dersin,sevgi nedir bilmezsin.

Gönlümdeki Hak ''ın divanını yıkarsın,

Zalimin ekmeğini yer,kılıcını sallarsın

Bilesin ki sen; kendi boynunu kendin vurursun,

(2.6.1999)', 'Hak için sever,Hak için ölürüz. Yar senin yüzünde Hak''ı görürüz. Pirler gibi bu sırra erdikçe çoşarız, Biz bu yoldan koşarak geçeriz, Kimimi...', ARRAY['Türk Edebiyatı','Şiir','Fatma Güven']::text[], 8.5, '{"poet":"Fatma Güven","poet_slug":"fatma-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sevdaya-davet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canözüm', 'canozum-i-smet-bora-binatli-nblgc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Can özüm,

İki gözüm

Gönül sultanım

Geceme ışık

Ruhuma dinginlik

Yüreğime sürür kadınım

Adınla başlarım güne

Adınla sonlarım.

Rüyalarımın adı sen

Hayallerimin konusu sen

Gülüyorsa yüzüm

Sebebi sen

Ah birde gelebilsen ara sıra

Bir de gelebilsen.', 'Can özüm, İki gözüm Gönül sultanım Geceme ışık Ruhuma dinginlik Yüreğime sürür kadınım Adınla başlarım güne Adınla sonlarım. Rüyalarımın adı...', ARRAY['Türk Edebiyatı','Şiir','İsmet Bora Binatlı']::text[], 8.5, '{"poet":"İsmet Bora Binatlı","poet_slug":"i-smet-bora-binatli","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/canozum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlasana', 'anlasana-i-smet-bora-binatli-3ibih', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen düşersin aklıma uykum kaçar

Sırt üstü uzanıp tavana dikerim gözlerimi

Gecenin karanlığında

Resmini çizerim tavana

Güler resmin bana

Işır ortalık

İçim aydınlanır.

Yokluğuna çare diye böyle yaşarım seni

Böyle sevişirim gece boyu hayalinle

Bazen seni inersin yanı başıma tavandan

Bazen ben yükselirim yanına

Nerede bütünleşirsek bütünleşelim

İkimiz tek oluruz

Böyle ulaşırız  sabahlara.

Sonra güneş doğar. Aydınlanır her yer

Resmin silinir tavandan

Ben hayallerimi ertelerim

Bir başka zamana

Dayanılmaz özlemlerle yorgun yüreğim

Sevgilim, anlasana.', 'Sen düşersin aklıma uykum kaçar Sırt üstü uzanıp tavana dikerim gözlerimi Gecenin karanlığında Resmini çizerim tavana Güler resmin bana Işır...', ARRAY['Türk Edebiyatı','Şiir','İsmet Bora Binatlı']::text[], 8.5, '{"poet":"İsmet Bora Binatlı","poet_slug":"i-smet-bora-binatli","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/anlasana-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Odaklanır Duygularım', 'sana-odaklanir-duygularim-i-smet-bora-binatli-0xg7f', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gecenin bir yerinde dağılır uykularım

Seni çağırırım yalnızlığıma 

Gelirsen yeniden dönerim 

Süslü rüyalarıma 

Gelmezsen karabasanlar çöker üstüme 

Bin parçaya bölünür uykularım

Bende bin parça olurum

Sonra sana uyanırım tan vakitlerinde

Gözlerimde ışık olursun

Dilimde dua

İçimde huzur olursun

İkimiz bir potada eririz

Ben sende bütünleşirim

Sen bende yok olursun

Her aklıma düşüşünde durur zaman

Yıldızlar seninle parlar, sana ışır ay

Seni söyler şarkılar

Tüm duygularım sana odaklanır

Sen olurum tekmil varlığımla

Sende yok olurum.', 'Gecenin bir yerinde dağılır uykularım Seni çağırırım yalnızlığıma  Gelirsen yeniden dönerim  Süslü rüyalarıma  Gelmezsen karabasanlar çöker ...', ARRAY['Türk Edebiyatı','Şiir','İsmet Bora Binatlı']::text[], 8.5, '{"poet":"İsmet Bora Binatlı","poet_slug":"i-smet-bora-binatli","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sana-odaklanir-duygularim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elden Başka Ne Gelir', 'elden-baska-ne-gelir-yusuf-onder-bahceci-1suy7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gizli gizli ağlıyorsun,

Derdin derin biliyorsun,

Sabır sabır diyorsun,

Elden başka ne gelir.

Sabaha dek uyuyamam,

Yıkıldı hayal Dünyam,

Bu ellerden ayrılam,

Elden başka ne gelir.

Bu sözlerim duyulmalı,

Sonu mutluluk olmalı,

Seni sevdim demez ise,

Elden başka ne gelir.

Gitti gelmez güzel günler,

Önder şimdi hayal eder,

Bu Dünya''dan birgün gider,

Elden başka ne gelir......', 'Gizli gizli ağlıyorsun, Derdin derin biliyorsun, Sabır sabır diyorsun, Elden başka ne gelir. Sabaha dek uyuyamam, Yıkıldı hayal Dünyam, Bu e...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/elden-baska-ne-gelir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gör Nasılmış Sevda', 'gor-nasilmis-sevda-i-smet-bora-binatli-s1yzv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Haydi bir  de sen yaşa sensizliği

Kolay sanıyorsan

Koy kendini uzaklara

Gör bak ıstırap neymiş, acı neymiş

Sen bir kez sev seni

Gör sevda neymiş…

Ben ki uzaklardayım sensiz

Ve çaresiz

Ben ki bütün ıstıraplara

Ben ki tüm ayrılık acılarına göğüs germiş

Ve de bastırıp acılarını

Gülümseyebilmiş; 

Bir de sen yaşa sensizliği 

Gör bakalım sevda neymiş.', 'Haydi bir  de sen yaşa sensizliği Kolay sanıyorsan Koy kendini uzaklara Gör bak ıstırap neymiş, acı neymiş Sen bir kez sev seni Gör sevda ne...', ARRAY['Türk Edebiyatı','Şiir','İsmet Bora Binatlı']::text[], 8.5, '{"poet":"İsmet Bora Binatlı","poet_slug":"i-smet-bora-binatli","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/gor-nasilmis-sevda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ateş', 'ates-seyfettin-bilal-ozluk-kmttv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Uzak sevdama zamansız yıldırım düştü

Yaktı içimi ama dışıma belli değil.

''Korkuyorum lütfen'' demem neye yarar

Ateş düştüğü yeri çoktan yaktı...

İçimde büyüttüğüm zamansız sevdama ne oluyor

Titriyor kalbim ürkek bedenimde

Ne, neden, niçin, niyeler beynimde raksediyor

Ama ateş düştüğü yeri yakıyor...

Bir tesadüf mü yoksa rastlantı mı? 

Yoksa...yoksalar peşin sıra gidiyor

Hayır inanmak istemiyorum, inanmiyorum da

Ateş sönüyor ama külü kalıyor...

Uyumak istiyorum gözlerimi kapatamıyorum

Düşen yıldırımın kıvılcımı hala içimde

Hadi çıkar lütfen nasıl çıkarabileceksen

Karıştırma külleri içinde ateş kalmıştır...', 'Uzak sevdama zamansız yıldırım düştü Yaktı içimi ama dışıma belli değil. ''Korkuyorum lütfen'' demem neye yarar Ateş düştüğü yeri çoktan yaktı...', ARRAY['Türk Edebiyatı','Şiir','Seyfettin Bilal Özlük']::text[], 8.5, '{"poet":"Seyfettin Bilal Özlük","poet_slug":"seyfettin-bilal-ozluk","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ates-44-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tanrıyı sevdiğim kadar.', 'tanriyi-sevdigim-kadar-ercan-akbay-iakae', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Tanrıyı sevdiğim kadar çok sevdim

     Ruhumda yaşattım,yücelttim seni 

     Dokunmadım bir an,bir kez öpmedim

     Kalbimde sakladım,gizledim seni.

     Ateşinle yandım,kavruldum çölde

     Adını adımla,andım her yerde

     Bir izin bile yok,susayan tende

     Aşkına kul oldum,taparcasına.

     Tanrıyı sevdiğim kadar çok sevdim

     Varmıydın,yokmuydun,hiç bilemedim

     Sadece özledim,her nefesimde

     Vuslatsa o dünya,de öleceğim....

                                           23.12.2005   İST.', 'Tanrıyı sevdiğim kadar çok sevdim      Ruhumda yaşattım,yücelttim seni       Dokunmadım bir an,bir kez öpmedim      Kalbimde sakladım,gizled...', ARRAY['Türk Edebiyatı','Şiir','Ercan Akbay']::text[], 8.5, '{"poet":"Ercan Akbay","poet_slug":"ercan-akbay","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/tanriyi-sevdigim-kadar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerin Düşer Aklıma', 'gozlerin-duser-aklima-i-smet-bora-binatli-d5vyj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hep ayrılıklara gebemidir

Büyük mutluluklar

Sevdalar hep sancımı çekmelidir

Seher vakitlerinde 

Sevgi ateşini kim yakar bilirmisin içimizde

Kim söndürür bizden habersiz

Nedir bizi bizde yok eden duygu

Nedir bu titremeler

Ellerimizde? 

Bu sancılı akşamlar hüzün dolu

Yeni umutlara uyanmak istiyorum

Özlemin beynimi kemiriyor

Her yanımda doğum sancısı sevdaların

Rüyalarımı yorumlayamıyorum

Gözlerin düşüyor aklıma apansız

Ben sevdalara düşüyorum.

Uzanır ellerin ellerime rüyalarda

Ben kanatlanıp uçarım

Bazen dipsiz kuyulara düşer çırpınırım

Bazen sen düşersin soğuk yatağıma 

Ben mutluluk denizinde boğulurum.

Sende bulurum kendimi 

Sende kaybolurum.', 'Hep ayrılıklara gebemidir Büyük mutluluklar Sevdalar hep sancımı çekmelidir Seher vakitlerinde  Sevgi ateşini kim yakar bilirmisin içimizde ...', ARRAY['Türk Edebiyatı','Şiir','İsmet Bora Binatlı']::text[], 8.5, '{"poet":"İsmet Bora Binatlı","poet_slug":"i-smet-bora-binatli","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/gozlerin-duser-aklima-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasretin Yakar Canı', 'hasretin-yakar-cani-i-smet-bora-binatli-u21zh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Adın aklıma gelir içime ateş düşer

Bu sevdanın çilesi benim gönlümde pişer

Gama aşina dilim güllere şarkı okur

Istırap; ağlarını benim beynimde dokur

Atılır kuyulara acıyla dolu canım

Ulaşmaz başkasına bende kalır isyanım

Feryadım arşa çıkar dağ taş inler ahımdan

Yanıp yakınmaktayım şu bahtı siyahımdan

Ne yana dönse başım, seni görür gözlerim

Öyle büyük hasret ki gördükçe de özlerim

Ne  yaman bir dertmiş bu, vermiyor bana aman

Sen varsan yaşıyorum, yoksan duruyor zaman.', 'Adın aklıma gelir içime ateş düşer Bu sevdanın çilesi benim gönlümde pişer Gama aşina dilim güllere şarkı okur Istırap; ağlarını benim beyni...', ARRAY['Türk Edebiyatı','Şiir','İsmet Bora Binatlı']::text[], 8.5, '{"poet":"İsmet Bora Binatlı","poet_slug":"i-smet-bora-binatli","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hasretin-yakar-cani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Daha Asla Aynı Olmayacağım', 'bir-daha-asla-ayni-olmayacagim-seyfettin-bilal-ozluk-h28vu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Eski sınırlamalarım olmayacak

Dünyayı kendi etrafımda döndürmeyeceğim

Kafamda rahatsız eden sesler olmayacak

Çünki bir daha asla aynı olmayacağım...

Benden önce yaşayanlar gibi

Belki ilk başta anlamsız gelecek

İlk defa başka insanları anlama düşüncesi beni rahatsız edecek

Ama bir daha asla aynı olmayacağım...

Kendimi suçlama lüksüm yok artık

Bilinçaltımdaki iletişimsizlikler korkutucu gelmeyecek

Yüzleştiğimde içimdeki çocuğu görüyorum

Çünki bir daha asla aynı olmayacağım...

Aylardır biriktirdiğim değerleri kaybedivermek bende boşluk yaratacak

Uzun süredir o sıkıntılarım hep içimdeydi

Benden önce ve benden sonra yaşanacaklar gibi

Ama bir daha asla aynı olmayacağım...', 'Eski sınırlamalarım olmayacak Dünyayı kendi etrafımda döndürmeyeceğim Kafamda rahatsız eden sesler olmayacak Çünki bir daha asla aynı olmaya...', ARRAY['Türk Edebiyatı','Şiir','Seyfettin Bilal Özlük']::text[], 8.5, '{"poet":"Seyfettin Bilal Özlük","poet_slug":"seyfettin-bilal-ozluk","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-daha-asla-ayni-olmayacagim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sesin Ulaşınca Bana', 'sesin-ulasinca-bana-i-smet-bora-binatli-lgzvj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sesin ulaşınca bana denizler durulur

Rüzgar susar, yüreğim sütliman olur

Güler yüzüm, her taraf güzelleşir

Utanırsın..

Yanakların pembeleşir.

Saçlarının kokusuyla bahar dolar içime

Ellerime siner kokun

Yüreğime siner

Sevmenin doruğuna çıkarım seninle

Ay ve yıldızlar yere iner..

Karanlık çöker ve hüzün kaplar her yanı

İçimde özlem, içimde vuslat ümidi büyür

Korkarım kendi  yalnızlığımdan

Yalnızlığım beni kovalar.

Sesin ulaşır sonra bana biter korkularım

Acılar yok olur dünyamda seni yaşarım

Seninle yeniden mutluluğu bulur

Sevincimi tüm insanlarla paylaşırım.', 'Sesin ulaşınca bana denizler durulur Rüzgar susar, yüreğim sütliman olur Güler yüzüm, her taraf güzelleşir Utanırsın.. Yanakların pembeleşir...', ARRAY['Türk Edebiyatı','Şiir','İsmet Bora Binatlı']::text[], 8.5, '{"poet":"İsmet Bora Binatlı","poet_slug":"i-smet-bora-binatli","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sesin-ulasinca-bana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Büyüme Çocuk Büyüme', 'sen-buyume-cocuk-buyume-kamil-soylemez-r2u6d', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen büyüme çocuk büyüme

Bu dünyü büyüklerin 

Kendini büyük görenlerin

Mezbereligi sevenlerin

Sen büyüme çocuk büyüme

Bu savaş büyüklerin 

Savaşı büyütüp 

Dünyayı zehir edenlerin

Sen büyüme çocuk büyüme

Bu dünya kan içenlerin

Kızılcık şerbeti diye kan kusturanların

Soysuz devlet soyanların

Sen büyüme çocuk büyüme

Babası ile kurşuna dizilen çocuk

Kundakta otomatikle taranan küçük

Hele bir düşünsene

Sen büyüme çocuk büyüme

Baba oğul terörist diye vurulan

Silahlı çatışmaya girdi diyenlerin

Yalan söyleyenlerin dünyası bu dünya

Sen büyüme çocuk büyüme

Bu dünya zalimlerin

Saf temiz duyguların katli vacip diyenlerin

Din kispesi altında soyanların

Sen büyüme çocuk büyüme', 'Sen büyüme çocuk büyüme Bu dünyü büyüklerin  Kendini büyük görenlerin Mezbereligi sevenlerin Sen büyüme çocuk büyüme Bu savaş büyüklerin  Sa...', ARRAY['Türk Edebiyatı','Şiir','Kamil Söylemez']::text[], 8.5, '{"poet":"Kamil Söylemez","poet_slug":"kamil-soylemez","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sen-buyume-cocuk-buyume-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Soyut Gülüşler', 'soyut-gulusler-aynur-sultan-yiuo1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '..........Hasretler, özlemler şuramda, 

...............yokluğunda çıldırmamak için

......................fotograflarınla konuşuyorum

..............özlemi, hasreti sevdama ekleyip 

........sualer soruyorum

......soyut gülüşlerine', '..........Hasretler, özlemler şuramda,  ...............yokluğunda çıldırmamak için ......................fotograflarınla konuşuyorum ..........', ARRAY['Türk Edebiyatı','Şiir','Aynur Sultan']::text[], 8.5, '{"poet":"Aynur Sultan","poet_slug":"aynur-sultan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/soyut-gulusler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nesin Sen?', 'nesin-sen-i-smet-bora-binatli-7mtv4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kokladığım her çiçekte

Gördüğüm her güzellikte

Senden bir iz var.

Nesin sen? Adını koyamıyorum

Beni benden alıyorsun

Bana uçmayı, bana gülmeyi

Yasaklıyorsun

Sen nesin? 

Uzakta da yakında da

Bendesin.

Üşüyor yüreğim yangınlardayken bedenim

Beni ateşleyen sensin

Sensin donduran yüreğimi

Bu telaş öldürüyor beni 

Seni seviyorum, ayaklarım titriyor

Seni seviyorum, buz kesiliyorum

Baştan ayağa

Ateşler içindeyim, seni seviyorum

Anlayamıyorum 

Sen nesin?', 'Kokladığım her çiçekte Gördüğüm her güzellikte Senden bir iz var. Nesin sen? Adını koyamıyorum Beni benden alıyorsun Bana uçmayı, bana gülme...', ARRAY['Türk Edebiyatı','Şiir','İsmet Bora Binatlı']::text[], 8.5, '{"poet":"İsmet Bora Binatlı","poet_slug":"i-smet-bora-binatli","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/nesin-sen-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Soluyorum', 'seni-soluyorum-i-smet-bora-binatli-k9c8r', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sular karardığında 

İnersin dolunay gibi sahillerime

İçim ışır, içim ısınır

Sevgin göz kırpar yakamozlarda bana

Sen sonlandırırsın elemlerimi

Yıldızlar benim gökyüzümde ışıldar

Sen düşersin sahillerime

Susar rüzgar, susar kuşlar

Uykuya dalar balıklar

Ben içimde sevinci büyütürüm

Büyür kundaktaki çocuklar

Sevdalar büyür, sevda sığmaz olur yüreklere

Sen büyürsün gözlerimde

Kesilir soluklar

Sabah meltemleri kokunu getirir

Her yanı gül kokusu sarar

Seni solurum

Güneş doğar çekilirsin kabuğuna

Şekli değişir dünyanın 

Kokun gider

Ben yok olurum.', 'Sular karardığında  İnersin dolunay gibi sahillerime İçim ışır, içim ısınır Sevgin göz kırpar yakamozlarda bana Sen sonlandırırsın elemlerim...', ARRAY['Türk Edebiyatı','Şiir','İsmet Bora Binatlı']::text[], 8.5, '{"poet":"İsmet Bora Binatlı","poet_slug":"i-smet-bora-binatli","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/seni-soluyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdalı Gönül', 'sevdali-gonul-hikmet-uzun-nx0br', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kararmış geceyi bürür,envar-ı maha çevirir.

Ağarmış saçları boyar,zülf-ü siyaha çevirir.

Bu sevda bizde oldukca tüllenir gönül şavkımız,

Zapt eder cemal-i yare, hem kıblegaha çevirir.', 'Kararmış geceyi bürür,envar-ı maha çevirir. Ağarmış saçları boyar,zülf-ü siyaha çevirir. Bu sevda bizde oldukca tüllenir gönül şavkımız, Zap...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Uzun']::text[], 8.5, '{"poet":"Hikmet Uzun","poet_slug":"hikmet-uzun","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sevdali-gonul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Evet Diyorsan', 'evet-diyorsan-i-smet-bora-binatli-fut7m', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kuşlar yuva yapar ağaç dallarında

Ben senin göğsüne yuvalandım

Tut beni kollarında

Koy başımı göğsüne uyut beni

Sevdalı başım orada uyusun

Daha yakından duysun yüreğini

Ne olursun…

Uzatsam ellerimi sıcaklığımı hissedebilir misin? 

Çağırsam duyar, istesem gelir misin? 

Kapatıp gözlerini 

Beni yanı başında bulabilir misin? 

Sevdamı yüreğine koyup

Yüreğimde yaşayabilir misin? 

Bütün bunlara evet diyorsan

Bilgi sevmektesin

Bilgi sevilmektesin.', 'Kuşlar yuva yapar ağaç dallarında Ben senin göğsüne yuvalandım Tut beni kollarında Koy başımı göğsüne uyut beni Sevdalı başım orada uyusun D...', ARRAY['Türk Edebiyatı','Şiir','İsmet Bora Binatlı']::text[], 8.5, '{"poet":"İsmet Bora Binatlı","poet_slug":"i-smet-bora-binatli","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/evet-diyorsan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Züvalin olam', 'zuvalin-olam-ali-riza-unal-nn4cz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Agâhtır abdi acizarın nihanına, açıldı bir bir ol perde,

Meftum eyleme gayrı firakınla, cihanda meczup misali,

Bir nazarın nagâh eyledi,aşk bahçeside bu segameye,

Destur eyle visale-i keremgâha,gayrı züvâlin olam..

------

Not   Agâh:  haberdar, uyanık,kalbi uyanık,malumatlı,basiretli,bilen.

Nihan:  gizli, saklı,bulunmayan, mevcut olmayan,sır.

Meftum: sütten, memeden, kesilen çocuk,bebek.

Meczup: ilâhi aşk ile veya bir sevda sononda iradesini

               Kaybetmiş kişi.

Nagâh: birdenbire,ansızın,hemen.

Firak :  ayrılık, ayrılmak,hicran.

Segame: sigam(beyaz çiçekli ot.

Vuslat: visal: sevdiğine kavuşma,birleşme ulaşma,

                 Bitiştiren,bitişme.

Züval :   yab,yab, sallana sallana yürüyen kişi.

Destur: izin  müsade.

Keremgâh:nefaset,izzet,al-i cenâabena ihsan inayet,

Kıymetli şeyleri kemal-i rıza i nefisle verme,mecd ve şeref,cênâbı Hakk’a aft olunursa eltaf ve ihsanı ilâhi kast edilmiş olur,ihsan hakkında vasıf sursti ile zikrolunursa.mehasin-i ahlâk ve ef al kast olunur..', 'Agâhtır abdi acizarın nihanına, açıldı bir bir ol perde, Meftum eyleme gayrı firakınla, cihanda meczup misali, Bir nazarın nagâh eyledi,aşk ...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/zuvalin-olam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönlüme Akınca', 'gonlume-akinca-mehmet-sait-akkus-z8xcn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yüzüne baktığımda

İçimi yaktığımda

Gönlüme aktığında

Öylesine mutluyum

Sen yanımda olunca

Yüreğimi yakınca

Bende yara açınca

Öylesine hastayım

Senden bana gelenler

Bana deli diyenler

Arkamdan gülenler

Öylesine üzülürüm

Sana bir şey olursa

Bu büyü bozulursa

Tarihe yazılırsa

O zaman mutluyum

Gözlerimde eririken

Gönül sende biterken

Kuşluk vakti gelirken

Kapım sana açıktır

içime akıyorsun

Gönlümü yakıyorsun

Ne olursada olsun

hep seni seveceğim', 'Yüzüne baktığımda İçimi yaktığımda Gönlüme aktığında Öylesine mutluyum Sen yanımda olunca Yüreğimi yakınca Bende yara açınca Öylesine hastay...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Sait Akkuş']::text[], 8.5, '{"poet":"Mehmet Sait Akkuş","poet_slug":"mehmet-sait-akkus","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gonlume-akinca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Varacağım', 'sana-varacagim-i-smet-bora-binatli-9bdcu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sevdalara yelken  açıp

Fırtınaya tutuldu yüreğim

Aç kollarını limanına sığınacağım

Günler biterse ne gam

Sevgim bitmez sende

Sen bitmezsin

Seni solurum aldığım her nefeste

Kanımı yıkar, akıtırsın damarlarımda

Seninle severim hayatı

Seninle umutlanırım

Kanadı kırık bir kuş gibi yüreğim

Sana uçmak istiyor, çırpınıyorum

Yuvamı göğsüne kuracağım.

Aç kollarını

Fırtınalar yıldırmıyor sen varsan

Kırık kanatlar vazgeçirmiyor uçmaktan

Nerede olursan ol, unutma

Sana varacağım,

Sana varacağım.', 'Sevdalara yelken  açıp Fırtınaya tutuldu yüreğim Aç kollarını limanına sığınacağım Günler biterse ne gam Sevgim bitmez sende Sen bitmezsin S...', ARRAY['Türk Edebiyatı','Şiir','İsmet Bora Binatlı']::text[], 8.5, '{"poet":"İsmet Bora Binatlı","poet_slug":"i-smet-bora-binatli","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sana-varacagim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ruh Ve Musiki', 'ruh-ve-musiki-alper-kuruk-haz8d', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Razı olmazdı hapse hergün

Ten kafeste ruh.

Eğer olmasaydı musikî

Sessiz bülbül gibi

Ve yapraksız ağaç misâli

Ne olurdu ruun hâli? 

Tellerde nağmeler gezer

Ses gezer şarkılarda

Bir ölüm çöker ruha

Bir gezinti başlar ruh için

İlâhîlerle Allah''a...

Şarkılarla gezer aşk ülkelerinde

Türkülerle gezer Anadolu''mu,

Ruhlarla öpüşür ruhcasına

Böyle bir öpüşten

Bir derin musikî doğar,

Bir ölüm gelir tene

Ağlayanlar,ağlayanlar

Son bestesini söyler ruhun

En acı seslerin bestesidir bu

Acır duyanlar...

Acır duyanlar...', 'Razı olmazdı hapse hergün Ten kafeste ruh. Eğer olmasaydı musikî Sessiz bülbül gibi Ve yapraksız ağaç misâli Ne olurdu ruun hâli?  Tellerde ...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/ruh-ve-musiki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Izdıraplar İçinde', 'izdiraplar-i-cinde-ali-kaybal-3kzw6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kaderi, görelim örsün hain ağlarını,

Zamanı  gelince, ağartsa saçlarımızı,

Gülüp geçtim, görsem erkeğin ağladığını,

Kimselere göstermem, akan göz yaşlarımı.

Oluk, oluk kan olup içime akacağım,

Mahşer olsa da, kör kuyu bulup dökeceğim.

Kaderin yükü, çözüverse diz bağlarımı,

Yaşama gücünü veren umut dağlarımı,

Aramızdan çekip kopar gönül bağlarımı,

Kimselere göstermem akan göz yaşlarımı.

Oluk, oluk kan olup içime akacağım,

Martı gibi, ummana gizlice dökeceğim.', 'Kaderi, görelim örsün hain ağlarını, Zamanı  gelince, ağartsa saçlarımızı, Gülüp geçtim, görsem erkeğin ağladığını, Kimselere göstermem, aka...', ARRAY['Türk Edebiyatı','Şiir','Ali Kaybal']::text[], 8.5, '{"poet":"Ali Kaybal","poet_slug":"ali-kaybal","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/izdiraplar-icinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin Hasretin', 'senin-hasretin-mehmet-sait-akkus-te2w5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yanar bu beden cana can katanda

Anar seni hep uzanıp yatanda

Seninle el ele güneş batanda

Yad eder,akşam akşam sabah olanda

Ayrılığın ateş olup yakarken

Bekliyor seni hep güneş batarken

Göz yaşlarımda sel olup akarken

Elinde mendil yüzümü silerken

Senden yana,bu gönül yaralıdır

Dört tarafım aşkınla sarılıdır

Bilmem,belki ömür yarılıdır

Yanar yüreğim sanki yarelidir', 'Yanar bu beden cana can katanda Anar seni hep uzanıp yatanda Seninle el ele güneş batanda Yad eder,akşam akşam sabah olanda Ayrılığın ateş o...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Sait Akkuş']::text[], 8.5, '{"poet":"Mehmet Sait Akkuş","poet_slug":"mehmet-sait-akkus","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/senin-hasretin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tut Bir Mürşidi Kamilin Elinden!', 'tut-bir-mursidi-kamilin-elinden-i-brahim-halil-demir-ntd7p', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Mürşid te bir insandır, deyip geçme sakın,

Sofrası daim açıktır, gelir insanlar akın akın,

Herkes bilmez, bilen bilir, kalp gözleri açıktır onun,

Tut bir mürşidi kamilin elinden, ol insan gibi bir insan! 

Hal ve hareketlerin olur, sana en hassas terazi,

Ek gönüldeki sevgi tohumlarını, boş kalmasın arazi! 

Bilinmelidir ki, bu yola baş koyanların, olmaz kimseye garazı,

Tut bir mürşidi kamilin elinden, ol insan gibi bir insan! 

Görmezmisin Dimdik duruyor sütunsuz bir şekilde asuman?

Mürşit olmazsa, ben gibi bir insanın hali, olur pek yaman.

Duymazsam sesini, görmezsem gül yüzünü, olur başım duman,

Tut bir murşidi kamilin elinden, ol  insan gibi bir insan! 

Şükür etmek için milyonlarca hikmetler var karşımda,

İstesem de istemesem de, bir çok mahlukatın rızkı var naaşımda,

Daha önceden, envai türlü sorunlar vardı, bu günahkar başımda,

Tut bir mürşidi kamilin elinden, ol insan gibi bir insan! 

Öyle zatlar kurtarır insanı  her türlü bataklıklardan,

Dikenler içinden derdirir gülleri gönül bahçelerinden,

Aydınlanır tüm karanlıklar, çıkar hemen çıkmaz sokaklardan,

Tut bir mürşidi kamilin elinden, ol insan gibi bir insan! 

Bu yolun gerekliliğini yaparsan, ne kadar aciz olduğunu anlarsın,

Rencide ettiğin gönüller için, çok üzülür hayıflanırsın,

Allaha kul olamadığın için, gecenin sessizliğinde çok ağlarsın,

Tut bir mürşidi kamilin elinden, ol insan gibi bir insan! 

23/12/2005', 'Mürşid te bir insandır, deyip geçme sakın, Sofrası daim açıktır, gelir insanlar akın akın, Herkes bilmez, bilen bilir, kalp gözleri açıktır ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Halil Demir']::text[], 8.5, '{"poet":"İbrahim Halil Demir","poet_slug":"i-brahim-halil-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/tut-bir-mursidi-kamilin-elinden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Yapsam Duymuyorsun', 'ne-yapsam-duymuyorsun-ali-kaybal-zexsb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Beyaz kalsın dedin, kar yağdı gönlüm,

Gülün renginde yaprak açtı gönlüm,

Avuttun kalbi sen, dertlendi gönlüm,

Tutunsam kollarından duymuyorsun.

Ateş olsun dedin, nar koydu gönlüm,

Alev sarsın dedin, har doldu gönlüm,

Kuruttun aşkı, çağlar oldu gönlüm,

Tutunsam kollarından duymuyorsun.

Sevip saysın dedin, yer tuttu gönlüm,

Gönül kansın dedin, zor yattı gönlüm,

Vurursun gem dedin, gam kattı gönlüm,

Tutunsam kollarından duymuyorsun.', 'Beyaz kalsın dedin, kar yağdı gönlüm, Gülün renginde yaprak açtı gönlüm, Avuttun kalbi sen, dertlendi gönlüm, Tutunsam kollarından duymuyors...', ARRAY['Türk Edebiyatı','Şiir','Ali Kaybal']::text[], 8.5, '{"poet":"Ali Kaybal","poet_slug":"ali-kaybal","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ne-yapsam-duymuyorsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutluluk', 'mutluluk-mustafa-tas-germd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Mutluluk insanların en çok aradıkları ama en fazla kaybettikleri şeydi.

Çünkü kaçan mutluluklar hep gözlerinin önündeydi.

Görmedi.

Göremezdi...', 'Mutluluk insanların en çok aradıkları ama en fazla kaybettikleri şeydi. Çünkü kaçan mutluluklar hep gözlerinin önündeydi. Görmedi. Göremezdi...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Taş']::text[], 8.5, '{"poet":"Mustafa Taş","poet_slug":"mustafa-tas","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/mutluluk-124-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıkılsa Dünya', 'yikilsa-dunya-mehmet-ayhan-gunaydin-oatnk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'YIKILSA DÜNYA

Yıkılsa dünya, 

Umurumda olmaz arkadaş.

Yeter ki; 

Bir çocuğun, 

Olmasın gözlerinde, tek damla yaş.

M. Ayhan Günaydın.

    12 Aralık 2005

          Ankara', 'YIKILSA DÜNYA Yıkılsa dünya,  Umurumda olmaz arkadaş. Yeter ki;  Bir çocuğun,  Olmasın gözlerinde, tek damla yaş. M. Ayhan Günaydın.     12 ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ayhan Günaydın']::text[], 8.5, '{"poet":"Mehmet Ayhan Günaydın","poet_slug":"mehmet-ayhan-gunaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yikilsa-dunya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuklar', 'cocuklar-mehmet-ayhan-gunaydin-0abig', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ÇOCUKLAR

Şiir sizsiniz çocuklar.

Siz şiir gibisiniz.

Ah bir bilseniz çocuklar.

Çocuklar,

Ah bir bilseniz.

Küçükken siz,

Pek güzelsiniz.

Büyüyünce de öyle kalın emi

Biz beceremedik çocuklar,

Siz becerin emi.

M. Ayhan Günaydın.

    21 Aralık 2005 

          Ankara', 'ÇOCUKLAR Şiir sizsiniz çocuklar. Siz şiir gibisiniz. Ah bir bilseniz çocuklar. Çocuklar, Ah bir bilseniz. Küçükken siz, Pek güzelsiniz. Büyü...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ayhan Günaydın']::text[], 8.5, '{"poet":"Mehmet Ayhan Günaydın","poet_slug":"mehmet-ayhan-gunaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/cocuklar-45-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sosyete Hanımı', 'sosyete-hanimi-alper-kuruk-wdzkt', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Küçüklüğün gözlerimin önünde

Dünyaya şaşıyorum doğrusu...

Bir entarin vardı

Yamalı,yer yer yırtık

O yırtıklardan tenin gözükürdü

Namussuz gözler yok mu

Yırtık yerlerine bakardı.

Fakirdin ama neme lâzım

Güzeldin doğrusu...

Biliyordum namus korkusu

İçini yakardı...

Oranı,buranı örterdin az-çok.

Kurtardı o hayattan seni

O güzelliğin

Şimdi kocan zengin.

Sosyete hanımısın sen de 

Açık göğüslü tuvaletler içinde.

Dün fakirlik açmıştı oranı,buranı

Bugün sen kendi  elinle açıyorsun

Kalbinde mâzinin tesiri silinmiş değil

O eski hâline benzeyen kızcağızlara

Hâlâ acıyorsun...

Allah''ın verdiği nimeti tepme

Dikkat et hâline

Sosyetede sana açılan kollar

Allah''ınki gibi değildir

Ki o kollardan düşersen

Temenni etmem ki o yer yerindir...

Kurtulamazsın ölsen...', 'Küçüklüğün gözlerimin önünde Dünyaya şaşıyorum doğrusu... Bir entarin vardı Yamalı,yer yer yırtık O yırtıklardan tenin gözükürdü Namussuz gö...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/sosyete-hanimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecenin yüzü', 'gecenin-yuzu-mustafa-tas-wtsu2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Uyuyorum,

                olmuyor.

Sen, 

     bir yerlerden çıkıp

                geçiyorsun  karşıma.

Rüyalarım,

             her gece uzun.

Uykusuzum.

Bırak  bedenimi rahata varsın.

Kaç benden,

           kaçtığım gibi senden.

Duygusuzum.

Yaşadığım her gece,

                      bir şeyleri alıp gidiyor benden.

Oysa sen....

            Kurtulmak imkansız mı? 

Neden?', 'Uyuyorum,                 olmuyor. Sen,       bir yerlerden çıkıp                 geçiyorsun  karşıma. Rüyalarım,              her gece uzun...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Taş']::text[], 8.5, '{"poet":"Mustafa Taş","poet_slug":"mustafa-tas","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gecenin-yuzu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vefadan Yana', 'vefadan-yana-ali-kaybal-0rycv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gülü bırakıp giden vefasız bülbül değilim,

Vefası gönlümde sevgiyle yatacaksın sevgilim.

Dalına konup aşkı ilan ediyorsa dilim,

Benden gayrının aşkını atacaksın sevgilim.', 'Gülü bırakıp giden vefasız bülbül değilim, Vefası gönlümde sevgiyle yatacaksın sevgilim. Dalına konup aşkı ilan ediyorsa dilim, Benden gayrı...', ARRAY['Türk Edebiyatı','Şiir','Ali Kaybal']::text[], 8.5, '{"poet":"Ali Kaybal","poet_slug":"ali-kaybal","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/vefadan-yana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlasana', 'anlasana-meral-yagcioglu-uph2y', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'farz et ki 

ben bir gülüm

kırmızı gül

Senin gülün

Yüreğinde

Unuttuğun 

solmadan gülün

seviyorum yaz

her bir  yaprağına

mühürle dudağınla

ve aşk nağmeleriyle

yükle kelebek kanadına 

uçur bana

bekliyorum

kollarım açık

senin için çarpıyor

yaralı yüreğim

anlasana

gülün ölmek üzere 

13/12/2005', 'farz et ki  ben bir gülüm kırmızı gül Senin gülün Yüreğinde Unuttuğun  solmadan gülün seviyorum yaz her bir  yaprağına mühürle dudağınla ve ...', ARRAY['Türk Edebiyatı','Şiir','Meral Yağcıoğlu']::text[], 8.5, '{"poet":"Meral Yağcıoğlu","poet_slug":"meral-yagcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/anlasana-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nerde Gerçek', 'nerde-gercek-elvan-genc-nmmno', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Söylenmeyen aşklar, büyürler selvi gibi

Yaşanan sevgiler, kirlenir kılıfı gibi

Bölünür yüreğim, iki yüzlü dostlar gibi

Yaralanır gönül, uçamayan kuşlar gibi...

Nerde kaldı Aşkımın Yüceliği...

İnanmayana kim sattı sevgimi...

Nasıl arandı kalbimde riya! ! ! 

Kim beş para sandı bu yüreğimi...

Hilesiz sandım, sarıldım çınar gibi

İçleri kurtluymuş beni de devirdiler..

Yalanla kendini yüceltenler,

Bencillikleriyle aşkımı kirlettiler..

14.11.2005

*Bu şiir Annem Zülfiye Genç tarafından yazılmıştır.', 'Söylenmeyen aşklar, büyürler selvi gibi Yaşanan sevgiler, kirlenir kılıfı gibi Bölünür yüreğim, iki yüzlü dostlar gibi Yaralanır gönül, uçam...', ARRAY['Türk Edebiyatı','Şiir','Elvan Genç']::text[], 8.5, '{"poet":"Elvan Genç","poet_slug":"elvan-genc","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/nerde-gercek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçme Diyorlar', 'i-cme-diyorlar-ali-kaybal-3rab1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kadeh alacaksam elime bir bahane gerek,

Dertlerimi unutacağım bir meyhane gerek,

Bırak diyor herkes içmesen artık şu zıkkımı,

Bakıp avunacağım gözleri şahane gerek.', 'Kadeh alacaksam elime bir bahane gerek, Dertlerimi unutacağım bir meyhane gerek, Bırak diyor herkes içmesen artık şu zıkkımı, Bakıp avunacağ...', ARRAY['Türk Edebiyatı','Şiir','Ali Kaybal']::text[], 8.5, '{"poet":"Ali Kaybal","poet_slug":"ali-kaybal","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/icme-diyorlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevi Budur...', 'sevi-budur-elvan-genc-n9gxr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Para, pulmuş aslında 

Ruh vardır aslında..

Döndüğünde aslına,

Mendil salla, el salla..

Dedim gör ki, sevi budur..

Dön, dolaş, sondur bu tur...

Neyse halin, bilsin kahin..

Bakla salla, zar salla...

17.05.2003/İst.', 'Para, pulmuş aslında  Ruh vardır aslında.. Döndüğünde aslına, Mendil salla, el salla.. Dedim gör ki, sevi budur.. Dön, dolaş, sondur bu tur....', ARRAY['Türk Edebiyatı','Şiir','Elvan Genç']::text[], 8.5, '{"poet":"Elvan Genç","poet_slug":"elvan-genc","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sevi-budur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Felsefe', 'felsefe-alper-kuruk-k5ka0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hayatın sonunda ölüm olmasaydı

İnsanlığımdan şüphe ederdim doğrusu...

Süleyman''ın aradığı su

Dillere destan olur muydu? 

Ölüm olmasaydı

Allah''la kul nasıl belli olacaktı? 

Tatlının sonu acı olmasaydı 

Hayatın tadı damakta kalır mıydı? 

Hayâl olmasaydı

Hakikat,boynunu bükerdi insanların

Öksüzleşirdi insanlar.

Aşk olmasaydı

Kadın,erkek ne işe yararlardı? 

Şükretmek gerek Allah''a...

Ölümle bizi kul etti

Allah''lığını kabul ettirdi bize.

Kâh hayatın tadını

Kâh zehrini sürdü dilimize.

Hakikatin kimi sertti

Kimi dimdikti karşımızda

Hayâl,evet hayâl

Bir ikinci hayattı tertemiz

Yanıbaşımızda.

Aşk,aşk...

Kadını melek yaptı

Şeytan yaptı gözümüzde

Kalbimizde dumansız ateşler yaktı.

Kadın,ister melek olsun ister şeytan

Benim karım yalnızca bana baktı,

Sağolsun elimden tutacak

Bana baston olacak

Bir de çocuk bıraktı...', 'Hayatın sonunda ölüm olmasaydı İnsanlığımdan şüphe ederdim doğrusu... Süleyman''ın aradığı su Dillere destan olur muydu?  Ölüm olmasaydı Alla...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/felsefe-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sızı', 'sizi-ahmet-guven-mkv5a', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '1

Demre’nin kıysındayım

Mevsimlerden Güz

Aramızda Akdeniz

Yerimden yurdumdan edildim

Ekmeğimden suyumdan

Firari bir yolcuyum ben

Yüreğime gül düşmüş

Güvercin kanatlım

Hangi dağa vursam seni

Mendili ıslak

2

Türkçe konuşur

Anavison’un yaşlıları

Islanır gözleri Kosta amcanın

Mariya’nın

Kayseri’denmi gelmişler

İzmir’denmi

Hepsi birarada

Sordukları evleri bilmem

Akranlarını tamımam

Büyüyen kentlerin arasında

Kaybolan anılar

Elimde olsa tutar getirirdim

O anıları bu kardeş sofrasına

“Uzuysa uzo”

“Rakıysa rakı”

“Elenikoysa eleniko”

“Kahveyse kahve”

Yaşlanmış Kosta amca

İkiarada biderede

Kim demişti? 

“Yunan piçleri”

Kim demişti? 

“Türk piçleri”

Sahi nereliydi Kosta amca? 

Yüreği ikiye bölünmüştü

Biri bu kıyıda

Biri öbür kıyıda

3

Firari bir yolcuyum ben

Kahvenin telvesini suya tuttum

Bana yol gözüktü

Kulakları çınlasın

Kosta amcanın,Mariya’nın

Sağmı dersin

Uzo içiyormu gene

Benim içinde bir kadeh içsin

Halkların kardeşliği adına

Ahmet Güven  1991-2000', '1 Demre’nin kıysındayım Mevsimlerden Güz Aramızda Akdeniz Yerimden yurdumdan edildim Ekmeğimden suyumdan Firari bir yolcuyum ben Yüreğime gü...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Güven']::text[], 8.5, '{"poet":"Ahmet Güven","poet_slug":"ahmet-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/sizi-51-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seherlerde Ağlarmış', 'seherlerde-aglarmis-hamza-mamas-hv8yb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ağrı çekerde gece saatler boyu,

Sonunda nur topu olan güneş doğarmış.

Bütün anneler gibi…

Tan yeri ağarırken; seherlerde ağlarmış.

“başlamak bitirmenin yarısıymış” oysa; 

Zaman karanlıktan çıkmaya fırsat ararmış.

zuhur etimi fecr vakti,

ardından nur topu güneş doğarmış.

Mevcudata savaş açarmış geceler,

İğne düşse yere; karanlıklar nara atarmış.

Sonra seslere, maddeye beraat sayılan,

Nur topu bir güneş doğarmış.

Yine günlerden bir gün varmış,

Seher vakti; oğlunu ararmış,

Bir dikkatle bakmış ki…

Oğlunu başka seherler almış.

Başka analar bilmezmiş kadri kıymeti,

Güneş o gün arz’a son kez doğarmış.

Yer, gök mevcudat ağlarmış o gün,

O gün sahralar bile ağlarmış.

                  

                                                          23/01/2004-yomra', 'Ağrı çekerde gece saatler boyu, Sonunda nur topu olan güneş doğarmış. Bütün anneler gibi… Tan yeri ağarırken; seherlerde ağlarmış. “başlamak...', ARRAY['Türk Edebiyatı','Şiir','Hamza Mamaş']::text[], 8.5, '{"poet":"Hamza Mamaş","poet_slug":"hamza-mamas","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/seherlerde-aglarmis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düş Tadında', 'dus-tadinda-birsen-ates-jc4z8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'demirlemişken acılarıma

hüznümü

aklıma sen geliyorsun

korkuyorum sensizliğinde



dalıyorum hayallere

kaçıyor uykularım

dolaşıyorum yüzünde

takılıyor dudaklarında 

dudaklarım

kesiliyor soluğum

geçerken bedeninden

dudaklarımı titrek bir gece de

bırakıyorum 

yüreğinde

sıcak  nefeslerimi

düş tadında zehirli

23.12.05', 'demirlemişken acılarıma hüznümü aklıma sen geliyorsun korkuyorum sensizliğinde dalıyorum hayallere kaçıyor uykularım dolaşıyorum yüzünde tak...', ARRAY['Türk Edebiyatı','Şiir','Birsen Ateş']::text[], 8.5, '{"poet":"Birsen Ateş","poet_slug":"birsen-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/dus-tadinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cinaslı Horyatlar', 'cinasli-horyatlar-riyaz-demirci-0duy8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Nenemden gitti

Quru ne nemden gitti

Evimde ölan şadlıx

Oda nenemden gitti

Nenemden gider

Quru ne nemden gider

Men ölsem qardeşe ne

Giden nenemden gider

Nenemı men

Ne quru ne nemı men

Gurbetteydim ölende

Görmedım  nenemı men

Nenemdı yar

Gözlerıu nenemdı yar

Gurbette men öldisem

Axını nenem diyer

Nenesini

Yapmışam ne ne sini

Ölünce hasret çeker 

Görmeyen nenesini.', 'Nenemden gitti Quru ne nemden gitti Evimde ölan şadlıx Oda nenemden gitti Nenemden gider Quru ne nemden gider Men ölsem qardeşe ne Giden nen...', ARRAY['Türk Edebiyatı','Şiir','Riyaz Demirci']::text[], 8.5, '{"poet":"Riyaz Demirci","poet_slug":"riyaz-demirci","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/cinasli-horyatlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İntihar Mektubu', 'i-ntihar-mektubu-alper-kuruk-26wsu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sevgilim,

Bu yazdıklarım artık 

Son kelimelerim.

İnsanlık ne erişilmez saadet...

Şu aşk denilen şey olmasa

Tadı az olurdu saadetin sanırım.

Her bahçenin meyvasını yer gibi

Hayatın her saadetinden

Az da olsa bir pay aldım.

Hepsinin dil buruşturucu

Bir tadı vardı

Aşk yoktu da ondan...

Seni bana Allah gönderdi sandım

Sarhoş olmuştum ilk yudumda aşkından

Ne yazık ki aldndım.

Seni benden yine Allah aldı sandım

Keşke Allah alsaydı...

Zâlim Felek girmeseydi araya.

O sarhoşluk hâlâ üzerimde

Uyanmak istemiyorum

Şekerlendi hayatım.

Senin de kusurun yok bunda

Gönlün akağanmış ne yaparsın...

Sana şunu bil ki diyorum:

Şimdi ölüm bana senden daha yakın

Sen uzaklaşınca benden

Bu sarhoşluk içerisinde

Ölümün yaklaştığını biliyordum.

Azrail''e zahmet olmasın...

Ben ölümün kucağında

Ölüm tabancamın içinde

Bak,şakağımı öpüyor şimdi

Gel diye sallladım ona elimi

 Sana da elveda...elveda...', 'Sevgilim, Bu yazdıklarım artık  Son kelimelerim. İnsanlık ne erişilmez saadet... Şu aşk denilen şey olmasa Tadı az olurdu saadetin sanırım. ...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/intihar-mektubu-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benden Herşeyini Sakınırsın', 'benden-herseyini-sakinirsin-alper-kuruk-m44m8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Nasıl ifrit olmayayım? 

Nasıl deli olmayayım ben? 

Saçlarını okşamak istesem

Okşatmazsın

Gider kuaföre teslim edersin başını.

Elini elimin içine koy desem

Çekinirsin,naz edersin

Yabancınmışım gibi kaçarsın benden

Ama manikürcüye

Yumuk yumuk ellerini az mı oynattın? 

Bacakların güzel dedim

Ben kötülük düşünmesem de

Kötülük geldi içine

Sıyrılan eteklerini hışımla

Yüzüme kapı çarparcasına kapattın.

Örttün.

E...artık içimdeki şeytanı dürttün

Yalan mı? Ayakkabı boyatırken

Boyacıya bacaklarını uzattın...', 'Nasıl ifrit olmayayım?  Nasıl deli olmayayım ben?  Saçlarını okşamak istesem Okşatmazsın Gider kuaföre teslim edersin başını. Elini elimin i...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/benden-herseyini-sakinirsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnşallah..', 'i-nsallah-nurdane-diken-e0226', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yüreğimde bir ateş

Yanarım ateş, ateş

Dertlerim tepreş, tepreş

Gecelerim hep kalleş..

Üzüntüler oldu eş

Mezarın kendine eş

Verdiğin soğudu aş

Yaptığınız hep kalleş..

Yemeğinde olur taş

Lâf duymaz,asidir baş

Hayatın kaldı bak boş

Gezersin sen hep sarhoş..

Uyutursun, uyursun

Satarsın, yalanlarsın

Atarsın sen çoşarsın

Sen ne kadar ahmaksın..

Darağacı kurulur! 

Hak eden hep asılır! 

İhanet yerin bulur! 

Millet senden kurtulur....

27.08.05-13.20-İst...', 'Yüreğimde bir ateş Yanarım ateş, ateş Dertlerim tepreş, tepreş Gecelerim hep kalleş.. Üzüntüler oldu eş Mezarın kendine eş Verdiğin soğudu a...', ARRAY['Türk Edebiyatı','Şiir','Nurdane Diken']::text[], 8.5, '{"poet":"Nurdane Diken","poet_slug":"nurdane-diken","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/insallah-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Meşale', 'mesale-guler-ilgaz-gysnq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben sevginin gerçeğiyim

Binbir çiçek gibi

Her an her yerdeyim

Ben solmayan 

Taze bir demim

Çektikçe yaşanan an gibiyim

...................................

Ben sevginin gerçeğiyim

Binbir surat gibi

Her an her yerdeyim

Adanan zamanlara sunulan

Gördükçe yaşayan göz gibiyim

.......................................

Ben sevginin gerçeğiyim

Binbir ahd-ı vefa gibiyim

Her an her yerdeyim

Sunulan mekanlarda bitiveren

Gerçeği düşe karışan söz gibiyim

.......................................

Ben sevginin gerçeği

...................İçinden gelen

Binbir sunuyu önüne seren

Her an her yerde

Elinde tuttuğun meşale gibiyim', 'Ben sevginin gerçeğiyim Binbir çiçek gibi Her an her yerdeyim Ben solmayan  Taze bir demim Çektikçe yaşanan an gibiyim ........................', ARRAY['Türk Edebiyatı','Şiir','Güler Ilgaz']::text[], 8.5, '{"poet":"Güler Ilgaz","poet_slug":"guler-ilgaz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/mesale-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sende bulduğum', 'sende-buldugum-i-smail-arslan-2a5fw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir güzel tatlıca dur ki karşımda

Gözlerin konuşsun ruhum dinlensin

Nağmeler dökülsün billur sesinde

Kulaklarım duysun kalbim dinlensin.

Bir mana alır kelime seninle

Aşk gelir aklıma seni görünce

Severim seni ben kendi halimce

Aşkınla tutuşan gönlüm inlesin.

Kuru sevda değil sende bulduğum

Aşk ile hayattır senden umduğum

Canımdan ziyade seni sevdiğim

Koşarak yoluna indiğim sensin.', 'Bir güzel tatlıca dur ki karşımda Gözlerin konuşsun ruhum dinlensin Nağmeler dökülsün billur sesinde Kulaklarım duysun kalbim dinlensin. Bir...', ARRAY['Türk Edebiyatı','Şiir','İsmail Arslan']::text[], 8.5, '{"poet":"İsmail Arslan","poet_slug":"i-smail-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sende-buldugum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sadece bir dize..', 'sadece-bir-dize-elvan-genc-c1n5x', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ölüm silinmekse anılardan, yüreklerden; 

Binlerce insan ölü yaşıyor bilmeden..

*Bu dize Mustafa Duman tarafından üretilmiştir.', 'Ölüm silinmekse anılardan, yüreklerden;  Binlerce insan ölü yaşıyor bilmeden.. *Bu dize Mustafa Duman tarafından üretilmiştir....', ARRAY['Türk Edebiyatı','Şiir','Elvan Genç']::text[], 8.5, '{"poet":"Elvan Genç","poet_slug":"elvan-genc","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/sadece-bir-dize-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beklenen sevgili', 'beklenen-sevgili-i-smail-arslan-7fkfe', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yüreğimde bir kapanmaz yara var

Gözlerim yollarda hep seni arar

Dudaklarım durmadan ismini anar

Gel ne olursun gel,usandım artık

Havada kar nefeste de buhar var

Uçuşan tanede büyük esrar var

Kara kaşın ela gözün aşkın var

Gel gerçek ol,beni uyandır artık.

Kara gecede parlayan yıldız yok

Durmuş aklımda,senden başkası yok

Kar yağıyor şimdi izler bile yok

Yürü izlerinden gideyim artık.', 'Yüreğimde bir kapanmaz yara var Gözlerim yollarda hep seni arar Dudaklarım durmadan ismini anar Gel ne olursun gel,usandım artık Havada kar ...', ARRAY['Türk Edebiyatı','Şiir','İsmail Arslan']::text[], 8.5, '{"poet":"İsmail Arslan","poet_slug":"i-smail-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/beklenen-sevgili-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkularla Büyür Aşk', 'korkularla-buyur-ask-selahattin-yetgin-hoxb8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir kaynayan kazandır içimizdeki

Bizi bu tutkularla sallayan kürede

Vakur ama hazin bir yalnızlıktır

Hep sonrasındaki o titrek aşkın.

Kubbeler yükselir yüksek semada

Sonsuz bir yolculuğun şafağında

Ağır aksak ilerlerken kervanlarda

Yalnızlığı yaşar gecelerde şaşkın.

Gecenin damarlarında titrek 

Kelepçeler hücre karanlığında ürkek

Bitmeyen bir aşkın dövmesi gibi

Hop oturup hop kalkar taşkın yürek.

Bu köhne istasyonlarında yaşamın

Bulamıyasın diye hep saklanırım

Her devirde kılıçtan geçirdik diye aşkı

Korkularla büyür dilimizde hüzzam bir şarkı.', 'Bir kaynayan kazandır içimizdeki Bizi bu tutkularla sallayan kürede Vakur ama hazin bir yalnızlıktır Hep sonrasındaki o titrek aşkın. Kubbel...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Yetgin']::text[], 8.5, '{"poet":"Selahattin Yetgin","poet_slug":"selahattin-yetgin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/korkularla-buyur-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yitmekte İnsanoğlu!', 'yitmekte-i-nsanoglu-utku-demir-5bsbf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kendi kusurlarından kaçar insanoğlu

Hüzünleri unutma tasasında

Bilmez ki hüzün yaşları gerek

Kavuşmak için kaybedilmiş benliği 

Dertliden uzaklaşır insanoğlu 

Alacağım yoktur düşüncesiyle

Bilmez ki dertliye sarılmak gerek

Öğrenmek için çare olmanın sırrını

Yarasını başkasıyla kapatır insanoğlu 

Kurtuluş umudunda acıdan

Bilmez ki kalbin batışı gerek

Hissetmek için aşk yanılsamasını

Fakire yanaşmaz insanoğlu 

Küçümser riyakarca bakışlarında

Bilmez ki yorgunluk gerek

Kazanmak için mücadelenin gücünü

Sevilmeyi sever insanoğlu 

Değer vermeden karşısındakine

Bilmez ki sevmek gerek

Ulaşmak için sevgi iksirine

Yenmeye bağımlıdır insanoğlu 

Hilekarca başvurur her yola

Bilmez ki kazananı kutlamak gerek

Tatmak için haklılığın ödülünü

Unutma gerçekleri ey insanoğlu

Doğduğunda insansındır ama

Kaybedersin temizliğini sahip çıkmazsan

Doğruları taşıyamazsın zayıflığında

Yaşamadan duyumazsın hayatın nabzını

Dokunanazsın duyguların ihtişamlı anıtlarına', 'Kendi kusurlarından kaçar insanoğlu Hüzünleri unutma tasasında Bilmez ki hüzün yaşları gerek Kavuşmak için kaybedilmiş benliği  Dertliden uz...', ARRAY['Türk Edebiyatı','Şiir','Utku Demir']::text[], 8.5, '{"poet":"Utku Demir","poet_slug":"utku-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/yitmekte-insanoglu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık', 'yalnizlik-alper-kuruk-enhg2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yalnızlık benim için olmuş sanki

Yalnız deyince kendim gelir aklıma,

O kadar insan içinde bir adamım ki

Yalnızım,tekim,kendi başıma...

Ay gökte yıldızlar içinde yalnız

Ben yerde insanlar içinde öylesine,

Elimde birşey yok,hayâlde bir kız

Tutup götürür beni âşıklar gecesine.

Yalnızım ne desem yine de yalnız

Hâlimi görür,anlamazsınız...', 'Yalnızlık benim için olmuş sanki Yalnız deyince kendim gelir aklıma, O kadar insan içinde bir adamım ki Yalnızım,tekim,kendi başıma... Ay gö...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yalnizlik-318-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çelişki', 'celiski-sezen-un-jsuhc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'okyanusların derinliklerinde

parlak bir inci

sevdalanmış hırçın bir maviye

mavinin sevdası sığlar

sığlarınki ise

o ateş ufuklar

derinler sığa küsmüş

sığlar derine.

nasıl ayrılır bilinmez

iki yarım bir bütünde', 'okyanusların derinliklerinde parlak bir inci sevdalanmış hırçın bir maviye mavinin sevdası sığlar sığlarınki ise o ateş ufuklar derinler sığ...', ARRAY['Türk Edebiyatı','Şiir','Sezen Ün']::text[], 8.5, '{"poet":"Sezen Ün","poet_slug":"sezen-un","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/celiski-64-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çöp Tenekesi', 'cop-tenekesi-alper-kuruk-s03fe', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Senin için kadar 

Benim içim de türlü şeyle dolu

İkimizin de kaderi

İçimiz hep böyle dolup dolup

Boşalmak imiş.

Yalnız senden farkım var:

İçim temiz benim.

Bazı kötü şeyler 

İçime girerse de 

Seninki kadar değil

İşe yaramazlar sende.

Umut var,hayat var

Velhâsıl herşey var bende

Hemen hemen hepsi iyiden yana.

Ben iyiyim hamdolsun

Çöpüm sana,çöpler sana

Aşkolsun...', 'Senin için kadar  Benim içim de türlü şeyle dolu İkimizin de kaderi İçimiz hep böyle dolup dolup Boşalmak imiş. Yalnız senden farkım var: İç...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/cop-tenekesi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sebebi sensin', 'sebebi-sensin-i-smail-arslan-3x8pi', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Keskin bir yanık kokusu 

Kaplıyorsa ortalığı sessizce

Dumansız,sessiz ve sensiz

Sebebi sensin.

Yanıyor yüreğim kor kor,ateşli

Zaman sanki körük olmuşta üfler

Uçuşuyor ordan oraya

Üzerinde toplanan küller

Sebebi sensin.

Işıltılı gözlerimde sisler

Uzağı görmez yakını görmez

Sanki nisan da yağan yağmur

Gibi yanağımda ki yaşlar

Dudağımda ki tuz da olmasa

Beynim bunu ayırdetmez

Sebebi sensin

Çınar gibi yanıyorum içten içe

Hala yemyeşil dış görüntüm

Ve hala asırlar gibi yüce

Gel gör ki içten yıkılmışım

Sebebi sensin.

Bir gemiyim ummanda dolaşan

Yelkenler fora açıklardayım

Lakin sen fırtına,bora,tayfun

Bakmışsın ki denizin derinliğindeyim

Sebebi sensin.', 'Keskin bir yanık kokusu  Kaplıyorsa ortalığı sessizce Dumansız,sessiz ve sensiz Sebebi sensin. Yanıyor yüreğim kor kor,ateşli Zaman sanki kö...', ARRAY['Türk Edebiyatı','Şiir','İsmail Arslan']::text[], 8.5, '{"poet":"İsmail Arslan","poet_slug":"i-smail-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/sebebi-sensin-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son', 'son-sezen-un-8muqh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'renkler başka, yüzler başka

yüreklerdeki dertler bambaşka

hangi gönlün teline dokunsan

çalar acı türküsünü nameler başka

dudaklar gülümser gözler yaşlı

kime sorsan derdini, o en yaslı

bilmez insan insanı, gamını, tasasını

nerde unutulmuş sevinçler, yürekler hep paslı

acılar yaş olup düşerken her dem

gözler ufka dalar, ne gelen var ne giden

bir yaralı yürek kalır geriye, büyükten küçükten

o da parçalandıkça parçalanır, kaderi ezelden', 'renkler başka, yüzler başka yüreklerdeki dertler bambaşka hangi gönlün teline dokunsan çalar acı türküsünü nameler başka dudaklar gülümser g...', ARRAY['Türk Edebiyatı','Şiir','Sezen Ün']::text[], 8.5, '{"poet":"Sezen Ün","poet_slug":"sezen-un","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/son-113-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mahkumdan Gardiyana Mektuplar', 'mahkumdan-gardiyana-mektuplar-sezen-un-krr6s', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'hapisim ezelden.

haberim yok,

ne sevinçten ne kederden.

gardiyanım yanmış, ben yanmışım

yüreğim parça parça ama dimdik başım', 'hapisim ezelden. haberim yok, ne sevinçten ne kederden. gardiyanım yanmış, ben yanmışım yüreğim parça parça ama dimdik başım...', ARRAY['Türk Edebiyatı','Şiir','Sezen Ün']::text[], 8.5, '{"poet":"Sezen Ün","poet_slug":"sezen-un","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/mahkumdan-gardiyana-mektuplar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeniden', 'yeniden-taner-yusuf-bul-ydyo1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'yeniden

gördüm en acı halini 

insan denilen zavallının

pecmurde,zayıf ve çaresizdi

yeniden

en bunalık kararsızlık girdaplarında hedefsiz

kendine bile

acımasız

yeniden işittim

yüzyıllardır ağladığı gibi ağlıyor

korkak ruhu titriyor

kendinden

habersiz

yeniden

mutsuzluklar saçıyor

ölesiye endişeli,isteksiz

sevmekten,affetmekten aciz şerefsiz

utanmadan eziyordu

yeniden

ve bir kez daha öğrendim

insan maymundan geliyor,yani

hayvandan...

aralık 2005

ankara -5 derece', 'yeniden gördüm en acı halini  insan denilen zavallının pecmurde,zayıf ve çaresizdi yeniden en bunalık kararsızlık girdaplarında hedefsiz ken...', ARRAY['Türk Edebiyatı','Şiir','Taner Yusuf Bul']::text[], 8.5, '{"poet":"Taner Yusuf Bul","poet_slug":"taner-yusuf-bul","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yeniden-73-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ya Ağarmasaydı Saçlarımız...', 'ya-agarmasaydi-saclarimiz-alper-kuruk-lgqb4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yaşamak öğretti bize 

İyinin,kötünün ne olduğunu,

Günler getirdi kucak kucak

Sevâbı ve günahı,

Aldık nasibimizi her birinden

Ekmek kavgalarında,

Düşünecek vaktimiz mi kaldı

 Daha çok aldığımızı acaba hangisinden? 

Gençlik öğretti bize güya

Günahın sevâp olduğunu

Bir kaynayan kan uğruna

Girdik boyumuzdan uzun günahlara.

Ya ağarmasaydı saçlarımız? 

Ya buruşmasaydı çehre? 

Ne zaman kullanablirdik aklımızı

Yerli yere...', 'Yaşamak öğretti bize  İyinin,kötünün ne olduğunu, Günler getirdi kucak kucak Sevâbı ve günahı, Aldık nasibimizi her birinden Ekmek kavgaları...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ya-agarmasaydi-saclarimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılığın spazmik sonsuzluğu...', 'ayriligin-spazmik-sonsuzlugu-bahri-baran-s8sfs', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aç kapılarını gözlerinin

Küçücük kış alsın yerini baharın

Donsun bakışlarım gözlerinde

içimi bilmediğim bir ürperti sarsın

sonum sonsuzluğa köle...

ve zaman dursun

serpilsin gözyaşlarım kuru tenime

filizlensin mutluluklar 

Aç kapılarını gözlerinin

aç ki küçücük gece alsın yerini gündüzün

kıyametler kopsun yüreğimde

sorhoş olsun dünyanın merkezi

dayanamam bu ayrılığa 

ver saçlarını 

dolayacağım boğazına gölgemin

intihar edeceğim!', 'Aç kapılarını gözlerinin Küçücük kış alsın yerini baharın Donsun bakışlarım gözlerinde içimi bilmediğim bir ürperti sarsın sonum sonsuzluğa ...', ARRAY['Türk Edebiyatı','Şiir','Bahri Baran']::text[], 8.5, '{"poet":"Bahri Baran","poet_slug":"bahri-baran","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ayriligin-spazmik-sonsuzlugu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgili Şiirim Sevdamız Hiç Bitmesin', 'sevgili-siirim-sevdamiz-hic-bitmesin-huseyin-erdogan-etx9a', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'hem hayallerimde  hem de rüyalarımda

inan ki adın dudağımda her anımda

şiirim ben beni buldum senin aşkında

sen benim kalbimde esen bir rüzgarsın

artık sen benim için tek yarsın bir arsın

sen de benimle sevdamın doruğunda varsın

sen bende hiç bitmeyen müthiş bir heyecansın

şiirim sen benim gönlümde solmayacak baharsın

her sabah bana yeniden rengarenk açıyorsun

her gün bana bir başka bambaşka kokuyorsun

sen sevgi olup yüreğime akıyor akıyor akıyorsun

bir tek benim sevdamı başına taç diye takıyorsun

benim gözlerimle dünyaya daha mutlu bakıyorsun

şiirim aşkınla beni yaktıkça muhteşem yakıyorsun

beni sevdanla kendine ne de güzel bağlıyorsun

ne olursun sen de gülümse bana her sabah uyanınca 

sevgili şiirim sevdamız hiç bitmesin  ömrümüz boyunca

                                                                23.12.2005

                                                           Hüseyin Erdoğan', 'hem hayallerimde  hem de rüyalarımda inan ki adın dudağımda her anımda şiirim ben beni buldum senin aşkında sen benim kalbimde esen bir rüzg...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sevgili-siirim-sevdamiz-hic-bitmesin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eğilmedik Asla', 'egilmedik-asla-ali-darcan-evths', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yalnız kalınca düşüncelerimle…

İster istemez…

Seni düşünüyorum...

Boş değil bu tüm yaşananlar

Yoğun bir anlam yüklü kendi içinde…

Bize anlamsız gelsede

Birlikte senle… 

-Papatyalarımız,

-Güllerimiz,

-Tutkularımız 

-Heyecanlarımız,

Heyecan…

Tutku…

Çok fazla hem de sen düşlerimdeyken

Tutki umutsuzuz

Benimsiyoruz da bunu üstelik,

Tutki kabulleniyoruz…

Tutki bir şeyleri yaşıyoruz birlikte

Düşlerimizde…

Yaşandı da sanki 

Hani unutamadığımız

Yaşanan tüm güzellik/çirkinliklere karşın 

Sevindik,

Yanıldık, 

Gülümsedik,

Yenildik...

Heyecanlandık…

Tutkularla yoğrulduk…

Mutluluğumuzdu yaşadıklarımız

Kırıldık,

Dost kalmayı düşündük öncelikle

Yaşam boyu… 

AMA ASLA EĞİLMEDİK..

13.12.2005', 'Yalnız kalınca düşüncelerimle… İster istemez… Seni düşünüyorum... Boş değil bu tüm yaşananlar Yoğun bir anlam yüklü kendi içinde… Bize anlam...', ARRAY['Türk Edebiyatı','Şiir','Ali Darcan']::text[], 8.5, '{"poet":"Ali Darcan","poet_slug":"ali-darcan","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/egilmedik-asla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aç Ve Muhteris', 'ac-ve-muhteris-alper-kuruk-jezj1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Açım diyorsun 

Kuru ekmek ye diyorum

Tutmaz diyorsun.

Peynir-ekmek ye diyorum

Yetmez diyorsun.

Tabak tabak ye diyorum

Bitmez diyorsun.

Açım diyorsun

Doymam diyorsun.

Evi ye diyorum 

Doymam diyorsun.

Mahalleyi ye diyorum

Doymam diyorsun.

Semti ye diyorum 

Doymam diyorsun.

İstanbul''u ye...

Doymam...

Türkiye''yi ye...

Doymam...

Avrupayı ye...

Doymam...

Dünyayı ye...

Doymam...

Evreni ye diyorum 

Doymam diyorsun.

İyisi mi başını ye

Kurtulursun...', 'Açım diyorsun  Kuru ekmek ye diyorum Tutmaz diyorsun. Peynir-ekmek ye diyorum Yetmez diyorsun. Tabak tabak ye diyorum Bitmez diyorsun. Açım ...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/ac-ve-muhteris-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevene aşkolsun, sevilene de!', 'sevene-askolsun-sevilene-de-mikdat-bal-a4x0j', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sevgi duyguları nasır bağladı

Sevene aşkolsun, sevilene de! 

Hoş görü felç oldu, gönül ağladı

Sevene aşkolsun, sevilene de! 

Sevgi bir hazine asla bitmeyen

Cennete giremez iman etmeyen

İman etmemiştir sevgi gütmeyen

Sevene aşkolsun, sevilene de! 

Kur’an inanalar kardeştir diyor

Çoğu kalkıp bunu inkar ediyor

Şu insanlık hangi yöne gidiyor

Sevene aşkolsun, sevilene de!

O hayvan bu hayvan sanki indeyiz

Kin, nefret, husumet hangi dindeyiz? 

Nefsimize köle  “Kunda Kinde’yiz”

Sevene aşkolsun, sevilene de! 

İnsan mı kalmadı, kime bu hitap? 

Açıp bakan var mı ne diyor kitap

Ne saygı, ne hürmet, ne ar ne hicap

Sevene aşkolsun, sevilene de! 

Mikdat der gönüller yıkılır böyle

Hoş görü, dostluktan çıkılır böyle

Kin, nefret, düşmanlık ekilir böyle

Sevene aşkolsun, sevilene de!', 'Sevgi duyguları nasır bağladı Sevene aşkolsun, sevilene de!  Hoş görü felç oldu, gönül ağladı Sevene aşkolsun, sevilene de!  Sevgi bir hazin...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sevene-askolsun-sevilene-de-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hey Sevgili Seviyorum Seni Duy Sesimi', 'hey-sevgili-seviyorum-seni-duy-sesimi-kamil-soylemez-4vuj0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Tutuşupta,gidiyoruz ya kırlara

İstanbul''un kargaşası aralığında

Derin mavileri yara,yara..

Nasıl keyif alıyoruz anlatamamki sana

Yeşili  gözlerimize sara sara

Yılan gibi kıvrılıp giden yollarda

Ellerinin tutsaklığı ellerim 

Sımsıkı tutuşup,uçurtuyorken beni

Bir ateş basıyor tenimi

Sanki hiç dönmeyecekmişiz gibi geri

Mutluyuz şimdi

Bir ateş yakıp,karıştırıyorsak 

Ellerimizle kavuşarak

Bir nedeni olmalı 

Sevginin bir anlatımı

İç çekmelerin yanmaların kıvamı

Sevginin jz düşümü baharı

Türkü tadında kalmalı

Sen gözlerinde gözlerim 

Yüreğinde yüreğim kalmalı

Kokun almalı 

Ellerim okşarken saçlarını

Sarılıp,uçmalıyım kaf dağı ardı

Köy kızı giyimin kalmalı 

Salınıp,yürümenin sana yakışanı

Patatesleri yemesekte

Patlıcanı yedik.soğanı.biberi

Bir ızgara tadındaki bir de gün ile geceyi

Nasıl unuturum ki ben seni

Benim kızıldereli sevgilimi

O sıcacık gülüşlerin ve ellerinin narinliğini

Buzulları eritip,yakarsın yüreğimde

Bir tadı tuzu olmalı,kim istemezki

Geçen günlerde özleminle kavuşmaları

Seni seviyorum hey sevgilim duyuyormusun beni', 'Tutuşupta,gidiyoruz ya kırlara İstanbul''un kargaşası aralığında Derin mavileri yara,yara.. Nasıl keyif alıyoruz anlatamamki sana Yeşili  göz...', ARRAY['Türk Edebiyatı','Şiir','Kamil Söylemez']::text[], 8.5, '{"poet":"Kamil Söylemez","poet_slug":"kamil-soylemez","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/hey-sevgili-seviyorum-seni-duy-sesimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdiğim! ..', 'sevdigim-kadir-albayrak-o1ezj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yüreğime hazan düşürme artık

Son yaprak dalında kalsın sevdiğim

Bahara benzedin değişme artık

Sensizlik vuslata varsın sevdiğim

Sen gülden müşahhas canandan öte

Mevsimlere bahar cansın sevdiğim

Aramızda hasretin adı ne ise

Tutuştur hepsini yansın sevdiğim

Bir beyaz gül açmış dudaklarında

O sıcak buseni sakla sevdiğim

Şehr-i İstanbul’un bir akşamında

Usulca sunuver bana sevdiğim

O ipek saçların omuzlarından

Şelale misali aksın sevdiğim

O ela gözlerin “hüzün dağından”

Sislerin ardından baksın sevdiğim

Misk-ü amber kokar bedenin tenin

Yüreğim nefseder seni sevdiğim

Bin zevki sefası olsa alemin

Hayalin hepsine değer sevdiğim

Ömrümü adasam versem ne çıkar

Ahreti çıkardım gözden sevdiğim

Hak vaki olup da ölsem ne çıkar

Yaşamak ateşten közden sevdiğim

Gül yüzlüm bir daha gelmesin hazan

Tanrı-dır hasreti vuslatı yazan

Sen içim de cansın gönlüm de canan

Bir daha bırakıp gitme sevdiğim', 'Yüreğime hazan düşürme artık Son yaprak dalında kalsın sevdiğim Bahara benzedin değişme artık Sensizlik vuslata varsın sevdiğim Sen gülden m...', ARRAY['Türk Edebiyatı','Şiir','Kadir Albayrak']::text[], 8.5, '{"poet":"Kadir Albayrak","poet_slug":"kadir-albayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/sevdigim-79-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hırsız - Polis', 'hirsiz-polis-alper-kuruk-tepkt', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu yaşa gelinceye dek

Hırsızlık bilmezdim ben de 

Bütün çocuklar gibi.

Ama yok mu bu yaş

Yok mu bu çağ? 

Ve delikanlılık...

Hırsızlığı da öğretir insana...

Evet,hırsızım şimdi

Hem de azılı cinsinden.

İnanın bana

Kaç genç kızın 

Yükte hafif aşkta ağır

Kalbini çaldım.

Polisten hayır yok onlara

Ben hırsız,onlar polis

Hırsız-polis oynuyoruz tatlı tatlı

Eski çocuk şenliğimizle...', 'Bu yaşa gelinceye dek Hırsızlık bilmezdim ben de  Bütün çocuklar gibi. Ama yok mu bu yaş Yok mu bu çağ?  Ve delikanlılık... Hırsızlığı da öğ...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/hirsiz-polis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seviyorum Seni Hey Sevgili', 'seviyorum-seni-hey-sevgili-kamil-soylemez-y2zqf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Tutuşupta,gidiyoruz ya kırlara

