INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidersen', 'gidersen-akin-dursun-k17e1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'gidersen sevdiğim 

yeni bir mevsim doğar tenimde 

göz yaşlarım buz tutar

avuçlarımda kurur baharlar 

gidersen; gökyüzü rengini alıp da gider 

gidersen sevdiğim 

soluğum kurak bir toprağın 

can çekişi gibi kalır 

hiçbir işe yaramaz 

göğsümün tam ortasında duran korkuluk da 

çünkü hiçbir kuş konaklamaz bende artık 

kokunu bile getirmez hatta rüzgarlar 

gidersen; tenimde bir yaprak bile kımıldamaz 

kelimelerimi yosun kaplar 

gidersen; gittin sevdiğim…

sana dair ne varsa bende 

verdim hepsini yokluğuna 

bu masmavi sessizliğin ortasında 

bir kez çınlasın diye gülüşün kulaklarımda 

verdim, verdim ne varsa sana dair her şeyi  yokluğuna 

23.04.2005 / 22:45 İzmir', 'gidersen sevdiğim  yeni bir mevsim doğar tenimde  göz yaşlarım buz tutar avuçlarımda kurur baharlar  gidersen; gökyüzü rengini alıp da gider...', ARRAY['Türk Edebiyatı','Şiir','Akın Dursun']::text[], 8.5, '{"poet":"Akın Dursun","poet_slug":"akin-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/gidersen-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bul-ma-ca', 'bul-ma-ca-akin-dursun-gri0n', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'soldan sağa yazdım olmadı, 

yukardan aşağı yazdım dolmadı, 

hep bir şeyler eksik kaldı, 

tam buldum derken,

onu da  göz yaşlarım alıp götürdü. 

bana mürekkebi dağılmış 

sorular kaldı. 

21.06.2005 / 01:47 İzmir', 'soldan sağa yazdım olmadı,  yukardan aşağı yazdım dolmadı,  hep bir şeyler eksik kaldı,  tam buldum derken, onu da  göz yaşlarım alıp götürd...', ARRAY['Türk Edebiyatı','Şiir','Akın Dursun']::text[], 8.5, '{"poet":"Akın Dursun","poet_slug":"akin-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bul-ma-ca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni unutma', 'beni-unutma-refik-ozsoy-d2dao', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Günaydın sevdiğim

Kapındayım eziğim

Masum bir esaret bu durgun

Sana hasret yüreğim aşkına yorgun

Günaydın sevdiğim uyan 

Bu acımasızlığa ne olursun birazdaha dayan

Hani o parktaki ağaç varya

Her gece oradan bakardık dünyaya

İşte orada bekliyorum gül yüzlüm

Biraz aşinayım hoş gör beni

Biliyorum zor ama seviyorum seni

Pencerenin önündeki çiçekler küskün artık

Seninle son kez güneşin doğuşuna bakamadık

Ne vardı bu dünyayı terk edecek

Ne vardı ölüm oyununa bensiz girecek

Şimdi senin sevgini bana kim verecek

Uyan sevgilin ne olur bırakma beni

Özlemek değil bu benimki

İçimde bir acı sancı yüreğimdeki

Gidişinle ruhum ezildi birden bire

Dökemedim hasretini yazmadım kelimelere

Sabahları yanağımdan öpüp bana aşkım deyişin vardı ya

Artık yok herşeyim sonbahar yağmurlarında

Dünya sırtını dönmüş sanki bana

Beni unutma sevgilim beni unutma

                                        DEMRİCİ', 'Günaydın sevdiğim Kapındayım eziğim Masum bir esaret bu durgun Sana hasret yüreğim aşkına yorgun Günaydın sevdiğim uyan  Bu acımasızlığa ne ...', ARRAY['Türk Edebiyatı','Şiir','Refik Özsoy']::text[], 8.5, '{"poet":"Refik Özsoy","poet_slug":"refik-ozsoy","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/beni-unutma-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akşamlar', 'aksamlar-hasan-can-s7kth', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Akşamlar, içimde titreyen sessizlik,

Ruhumda bir çocuğun gülüşü,

Son nefesi bir aşığın,

Aydın bir sabahın öncesi.

Akşamlar, karanlığın adresi,

Yiten aşıkların son durağı,

Mavinin kayboluşu,

Düşlerin varoluşu.

Akşamlar, sessizliğin kaldırımlara yankısı,

Meçhullerin bilinmezliği,

Çaresizlerin görünmeyen yüzü,

Yoksulların yüreği...

Akşamlar, tehlikenin gelişi,

Ve gidişi sabaha varmadan,

Son oyunlar oynanan,

Ve son umutlar biten...

Akşamlar, hatırası yalnızlığın,

Akşamlar, tiryakisi acıların,

Akşamlar, bedeli ihanetin,

Akşamlar, yağmuru gözlerin.

Akşamlar, bitmeyen sonsuzluk,

Tükenmeyen sorumsuzluk.

Akşamlar, bitmeyen sefaletin savaşı,

Tükenmeyen yoksulun ahı.

Akşamlar, siz bu acılar için hep vardınız,

Akşamlar, sevgileri hep kuytunuzda sakladınız,

Akşamlar, yaşanan umutları diri diri gömdünüz,

Akşamlar, onca uğraşa rağmen çözülmediniz.', 'Akşamlar, içimde titreyen sessizlik, Ruhumda bir çocuğun gülüşü, Son nefesi bir aşığın, Aydın bir sabahın öncesi. Akşamlar, karanlığın adres...', ARRAY['Türk Edebiyatı','Şiir','Hasan Can']::text[], 8.5, '{"poet":"Hasan Can","poet_slug":"hasan-can","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/aksamlar-33-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Noel Baba', 'noel-baba-oguz-duzgun-xz729', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bilemez noel baba

acımı benim,

dindiremez

sahte oyucaklarıyla

güldüremez

yaşlı çocukluğumu

çığlıktan ateşlerini

dünyanın

söndüremez

bir mevlana gibi mesela

çocuklarını yurdumun

aşıkça döndüremez

inanmıyorum kızılderilileri

noel baba

öldüremez

nasreddin hoca gibi

noel baba,

 fakiri de

güldüremez

çam ağaçlarını 

hindileri

böyle hoyratça

kestiremez

noel baba 

ağlarken bebeler,

afrikada, asyada

''hoh hoh hoh'' gülemez', 'bilemez noel baba acımı benim, dindiremez sahte oyucaklarıyla güldüremez yaşlı çocukluğumu çığlıktan ateşlerini dünyanın söndüremez bir mevl...', ARRAY['Türk Edebiyatı','Şiir','Oğuz Düzgün']::text[], 8.5, '{"poet":"Oğuz Düzgün","poet_slug":"oguz-duzgun","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/noel-baba-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen benim sol yanımsın', 'sen-benim-sol-yanimsin-oguz-kagan-mirzabeyoglu-wrz86', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'sen benim sol yanımsın,

en isyankar,en çaresiz,

en aciz,en kırılgan,

sen benim en sessiz çığlığımsın.

sen,dünyamda ki; 

en onurlu kavgamsın, 

iyileşmez yaram,en utangaç sevdamsın 

gözlerinde boğulduğum; 

gülkurusu denizimsin. 

sen

unutmanın unutulduğu,

en güzel sonbaharısın gönlümün.

benim çelişkili dünyamın, 

en tutarlı ve gerçek anlamasın, 

ve eylemisin dünyamın. 

sen 

vazgeçilmez; 

devinimisin evrenin. 

sen beni ben yapansın. 

anlamısın yıllardır, 

anlayamadığım, dolduramadığım, 

yaşamın ve insanlığın...

ve sen 

hiç benim olamadın 

ve hiç bilemedin 

ne derece sevildiğini 

ve hiç bilemeyeceksin sol yanımdaki isyanları...', 'sen benim sol yanımsın, en isyankar,en çaresiz, en aciz,en kırılgan, sen benim en sessiz çığlığımsın. sen,dünyamda ki;  en onurlu kavgamsın,...', ARRAY['Türk Edebiyatı','Şiir','Oğuz Kağan Mirzabeyoğlu']::text[], 8.5, '{"poet":"Oğuz Kağan Mirzabeyoğlu","poet_slug":"oguz-kagan-mirzabeyoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/sen-benim-sol-yanimsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Annemi Şimdi Daha İyi Anlıyorum', 'annemi-simdi-daha-i-yi-anliyorum-munevver-senol-nj3zs', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Annemi şimdi daha iyi anlıyorum.

                             Kimi zaman işi gırgıra vurup, hayatı tiiye alıyordum.

                             AMMAA yanlız kaldığımda, zaman zaman ağlıyordum.

                             Sağlık elden uçtu gitti, dost sandığım onlar da bitti.

                              Dünyanın tadı tuzu da kalmadı, bunu da görüyorum.

                              Şimdi annemi daha iyi anlıyor ona hak veriyorum.

                               Allah''ım elim ayağım tutarken emanetini al derdi.

                              Yataklarda yatırma, kapılara baktırma derdi kızardım.

                              Ama şimdi aynı dilekleri kendim için diliyorum.

                              İnsan yükü ağır imiş bunu çok iyi biliyorum, ve hissediyorum.

Biraz karamsar oldu ama maalesef gerçekler böyle.', 'Annemi şimdi daha iyi anlıyorum.                              Kimi zaman işi gırgıra vurup, hayatı tiiye alıyordum.                         ...', ARRAY['Türk Edebiyatı','Şiir','Münevver Şenol']::text[], 8.5, '{"poet":"Münevver Şenol","poet_slug":"munevver-senol","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/annemi-simdi-daha-iyi-anliyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul''un Yangınları Yücedir', 'i-stanbul-un-yanginlari-yucedir-kevser-gulistan-cakir-qj1um', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu akşam

İstanbul''un bütün yangınları

Benim beynimde

Yeniden can bulmuş gibi

Düşüncelerimi çılgın alevler sarıyor..

Gökyüzünü boyamış

Alevlerin rengi

Ve hava gittikçe

Yanık kokusuyla doluyor

Bir yolunu bulup

Yüreğime düştü bütün korlar

İstanbul bu gece

Benim kalbimde yanıyor...', 'Bu akşam İstanbul''un bütün yangınları Benim beynimde Yeniden can bulmuş gibi Düşüncelerimi çılgın alevler sarıyor.. Gökyüzünü boyamış Alevle...', ARRAY['Türk Edebiyatı','Şiir','Kevser Gülistan Çakır']::text[], 8.5, '{"poet":"Kevser Gülistan Çakır","poet_slug":"kevser-gulistan-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/istanbul-un-yanginlari-yucedir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözyaşı Zamanı', 'gozyasi-zamani-utku-demir-0dy9e', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Zamanı olur mu sanırsın gözyaşlarının

Yola çıktıklarında krater zirvesinden

Engel dayanamaz taşkın akıntısına

Dizsen de önüne kayalarını,elmastan 

Çürütür belirsiz,pırlanta gözyaşları

Gönül ormanında çıplak bir göl

Damlalar kan kırmızı kollarında

Düşer kalbimden şıp şıp

Değerlenir yüklendikçe çığlıkları

Dönüşür gözyaşları saydamlığa

İşte size alışılmış bir senaryo

Herkes çekilsin bencil yuvasına

Tüm dertliler şairlere emanet

Koyulsun başlar yumuşak yastıklara

Yavaşlasın zamanın vedacı elleri

Kopuşunda bağlar sönük gecelerde

Takılırsın hüzünlerin attığı oltaya

Çeker seni yüreğinin derinlerine

Yüklenir masumane kırmızı damlalar

Vurgun yediğin noktada hıçkırıklar

Artık göl taşar sığmaz yatağına

Beyaz kağıtlara gözyaşları kalem

Sanki saçılır yanardağın lavları 

Renksiz şekiller yaratır mozayikte 

Rüyalara vurur yabana atılmaz demini', 'Zamanı olur mu sanırsın gözyaşlarının Yola çıktıklarında krater zirvesinden Engel dayanamaz taşkın akıntısına Dizsen de önüne kayalarını,elm...', ARRAY['Türk Edebiyatı','Şiir','Utku Demir']::text[], 8.5, '{"poet":"Utku Demir","poet_slug":"utku-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/gozyasi-zamani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acı tesadüf', 'aci-tesaduf-munevver-senol-uev4v', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yıllar sonra tesadüfen rastladım sana

                           Manalı bakarak dudağını bükmüştün.

                           Neler geçti içinden bilemiyorum.

                           Ah keşke imkanı olsaydı da.

                           Gerçekleri diyebilseydim sana.

                           Yanlış anlaşılırdı zararı olurdu hem sana hem bana.

                          Yıllarca çektiğim acıyı tarif edemem.

                           Kabir azabı dedİkleri bu mudur ola? 

                          Bizi ayıranlar buyursunlar sofraya.

                           Zafer yemeği onların yesinler doya doya.', 'Yıllar sonra tesadüfen rastladım sana                            Manalı bakarak dudağını bükmüştün.                            Neler geçti i...', ARRAY['Türk Edebiyatı','Şiir','Münevver Şenol']::text[], 8.5, '{"poet":"Münevver Şenol","poet_slug":"munevver-senol","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/aci-tesaduf-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bırak Beni Bağışlamayı sen Kendini bağışla', 'birak-beni-bagislamayi-sen-kendini-bagisla-eyup-selahattin-dalkiran-ovhp1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen orada üzülüyormusun sevgilim? 

Ne olur üzülme

Ben seni seviyorum

Acıda olsa uzak kalmamız

Belki bundada bir hayır vardır

Belki tüketeceğiz umutlarımızı,ümitlerimizi

Ama sen orada üzülme

Bırak yaşagıklarımızla yaşamız olalım

sonsuza değin rüyalar içinde sen ile ben

ellerimizi ellerimizde,dudaklarımızı dudaklarımızda

Tenlerimizi tenlerimizde hissederek yaşayalım

Sen kendini bağışla beni değil

Bilirmisin? 

Bana sunduğun en güzel hediyen 

acı oldu sevgilim acı

Yüreğimin kapısına nöbetçi oldular

Gelde uzaklaştır acılarını

Yarım kaldım sensiz acılar ile

Gel sarıl boynuma,ağlamak istiyorum omuzunda

Hadi gel yeter bu acılar yeter

Bilirsin beraber yaşadık

Aşka dair ne varsa

Bu sevginin,aşkın suçlusu sensin

ve Yüreğindir.

Hadi canım bu inadı bırak

Gel şu sevenin tekrar kalbine

Hiç bir veda bu kadar yakmamıştı  canımı

Ağlamaktan gözyaşlarım şaşırdı

böyle aşka,sevdaya

gel de gör halimi

Solmakta yüzüm zamansızca

Sessiz sedasız yok olmakta bedenim

Senle yaşanmayan günler içinde

Hadi gel bırak bu inadı ara beni

Ve yüreğini ve kendini bağışla bana karşı.', 'Sen orada üzülüyormusun sevgilim?  Ne olur üzülme Ben seni seviyorum Acıda olsa uzak kalmamız Belki bundada bir hayır vardır Belki tüketeceğ...', ARRAY['Türk Edebiyatı','Şiir','Eyüp Selahattin Dalkıran']::text[], 8.5, '{"poet":"Eyüp Selahattin Dalkıran","poet_slug":"eyup-selahattin-dalkiran","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/birak-beni-bagislamayi-sen-kendini-bagisla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aldanış', 'aldanis-birsen-ates-3puzk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'hırçın dalgalı  denizlerdeyim 

yüreğim aşkla dolu

kimliği yalancı sevdan

boğuldu bir gece fırtınada 

yalanların beyazdı 

masum değildin 

yağan karda! 

ki yağıyorsun,

yine de şehrimin üstüne 

ayazda,

titriyor bedenim yitik 

işlemiş suretin içime,

acıtsa da 

kaçıncı ihanetin 

kaçıncı aldanışım 

her seferinde yüreğinde soluklanışım 

25.12.2005', 'hırçın dalgalı  denizlerdeyim  yüreğim aşkla dolu kimliği yalancı sevdan boğuldu bir gece fırtınada  yalanların beyazdı  masum değildin  yağ...', ARRAY['Türk Edebiyatı','Şiir','Birsen Ateş']::text[], 8.5, '{"poet":"Birsen Ateş","poet_slug":"birsen-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/aldanis-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk mıydı?', 'ask-miydi-birsen-ates-syhnx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'sızıydın,

dinmek bilmeyen 

kanayan her daim 

sevdadan ibaret

özlenendin.

ne çok var 

sığmaz vurgun yüreğime 

sensizliğinde

üşüyen deliliklerim..

yalan da olsa,

söyle bu gece 

sevdiğini ölesiye 

d ü ş l e r d e dokunmak tenine

neşter tadı ö p ü ş l e r d e 

yalanda olsa söyle bu gece 

g ü l ü ş l e r d e,

ölümcül ve sahte 

25.12.2005', 'sızıydın, dinmek bilmeyen  kanayan her daim  sevdadan ibaret özlenendin. ne çok var  sığmaz vurgun yüreğime  sensizliğinde üşüyen delilikler...', ARRAY['Türk Edebiyatı','Şiir','Birsen Ateş']::text[], 8.5, '{"poet":"Birsen Ateş","poet_slug":"birsen-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ask-miydi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçilme Arzun', 'i-cilme-arzun-firat-ulker-g7osb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sonsuz anlarım

Sağmakla geçiyor seni

Bitiremiyorum bi türlü

İçindeki sütü

Doyumsuzluğumsun,,

Doymadığımsın,,

Doyamadığımsın..

O ağzı

O baldan tatlı ilk sütü

Memelerine abanarak

Şevkle içtiğim

Anamın ak sütünü bile

En fazla

Bir yıl süzdüm içime

Ama seni

Lıkır lıkır içtiğim halde

Bitmeyen iki şey var içimde

Sen ve içilme arzun..

                                                   25.12.05/03:34', 'Sonsuz anlarım Sağmakla geçiyor seni Bitiremiyorum bi türlü İçindeki sütü Doyumsuzluğumsun,, Doymadığımsın,, Doyamadığımsın.. O ağzı O balda...', ARRAY['Türk Edebiyatı','Şiir','Fırat Ülker']::text[], 8.5, '{"poet":"Fırat Ülker","poet_slug":"firat-ulker","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/icilme-arzun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Söz', 'son-soz-firat-ulker-8d3v8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ateşin yolundan gideriz

Ama yanmaktan korkarız

Düşünmeden sonunu

Alev alev koşarken

Bir damla su diye bağırırız

İçinde cayır cayır yanarken

Hey insanlar! 

Dünya çölünde

Hepimiz birer kaktüsüz

Geç olmadan

Öte dünyaya

Bi tas su biriktirin gövdenizde

Budur bizim,son sözümüz..

25.12.05/07:20', 'Ateşin yolundan gideriz Ama yanmaktan korkarız Düşünmeden sonunu Alev alev koşarken Bir damla su diye bağırırız İçinde cayır cayır yanarken ...', ARRAY['Türk Edebiyatı','Şiir','Fırat Ülker']::text[], 8.5, '{"poet":"Fırat Ülker","poet_slug":"firat-ulker","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/son-soz-34-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmez - Şiir Perisine', 'bilmez-siir-perisine-i-brahim-usta-qgnux', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Neden bu düşmanlık güzelliklere 

İnsanlık tükenmiş, öfke yok yere

Kiminin derdine sevilmek çare

Kimi çok sevilir sevmeyi bilmez.', 'Neden bu düşmanlık güzelliklere  İnsanlık tükenmiş, öfke yok yere Kiminin derdine sevilmek çare Kimi çok sevilir sevmeyi bilmez....', ARRAY['Türk Edebiyatı','Şiir','İbrahim Usta']::text[], 8.5, '{"poet":"İbrahim Usta","poet_slug":"i-brahim-usta","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/bilmez-siir-perisine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Gecem', 'son-gecem-hatice-guler-ni2nc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seninle nefes alıp verdiğim

Seninle adım adım gezdiğim

Havasını sen  diye içime çektiğim

Bu gece son gecem bu şehirde

Bu gece son seninle uyuduğum 

Bu gece son..

Son kez gözlerine değdi yüreğim

Son kez gözlerine baktı gözlerim...

Bu gece son gecem bu şehirde

Bu gece son seninle uyuduğum

Bu gece son...', 'Seninle nefes alıp verdiğim Seninle adım adım gezdiğim Havasını sen  diye içime çektiğim Bu gece son gecem bu şehirde Bu gece son seninle uy...', ARRAY['Türk Edebiyatı','Şiir','Hatice Güler']::text[], 8.5, '{"poet":"Hatice Güler","poet_slug":"hatice-guler","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/son-gecem-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ruhum', 'ruhum-firat-ulker-uzq3n', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seni ruhumla seviyorum

Çünkü onun kalbi

Hiç durmuyor

Ve bedenim

Onun emirlerini yerine getiren

Sadece bir cisim

Bayan! 

Sizin için n''apabilirim..', 'Seni ruhumla seviyorum Çünkü onun kalbi Hiç durmuyor Ve bedenim Onun emirlerini yerine getiren Sadece bir cisim Bayan!  Sizin için n''apabili...', ARRAY['Türk Edebiyatı','Şiir','Fırat Ülker']::text[], 8.5, '{"poet":"Fırat Ülker","poet_slug":"firat-ulker","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ruhum-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ucuz Kibrit Pahalı Sigara', 'ucuz-kibrit-pahali-sigara-firat-ulker-t5qpu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'O kadar erişilmez

O kadar güzeldin ki

Seni hem çok seviyordum

Hemde senden çok korkuyordum

Düşününce

Bağları çözülürdü uzuvlarımın

Ürpererek yığılırdım

Sana dokunmak istediğimde

Geceleri herkes çekilince

Geçtiğin yerleri okşardım

Öpmek istediğimde

Attığın izmaritlerin ucuna yapışır

Kaldığı yerden

Yanmaya başlardım

Saydam duvarlar vardı sanki etrafında

Yürürken,dururken

Kimse yanaşamazdı sana

Hatta utancımızdan bakamazdık bile

Muhteşemdin,çok güzeldin

Ve bir gün 

Bir gün ulaştım sana

Dünyadaki en pahalı sigarayı

En ucuz kibrit 

Yaktı sonunda

Ama geç kalmıştım

Çünkü beni tutan 

Seni bırakanın eliydi

Lanet herif

Tam ona kavuştum derken

Bırakılı rmı şimdi sigara

Hadi hadii

Çek bi nefes daha

Ciğerlerinin ifrazatı

Ağzından patladığında

Toz-duman

Kaybolacağız sonsuza..

21.12.05/02:45', 'O kadar erişilmez O kadar güzeldin ki Seni hem çok seviyordum Hemde senden çok korkuyordum Düşününce Bağları çözülürdü uzuvlarımın Ürpererek...', ARRAY['Türk Edebiyatı','Şiir','Fırat Ülker']::text[], 8.5, '{"poet":"Fırat Ülker","poet_slug":"firat-ulker","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/ucuz-kibrit-pahali-sigara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana Bu Aşkta Çektirdiklerin İçin', 'bana-bu-askta-cektirdiklerin-i-cin-eyup-selahattin-dalkiran-elfdi', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben sana mayıs''ta

Aşık olacağım her zaman.

Haziran''da sana 

çok sarılacağım.

Temmuz''da senin

sadece ellerini tutacağım.

Ağustos''ta beni sana

Bağlayan gözlerine bakacağım.

Eylül''de senden biraz

Uzak duracağım her ihtimale karşılık.

Ekim''de sorunlar yaratacağım

Beyninden sarsılman için.

Kasım''da aramalara mesafe koyacağım.

Sözlerimin içinde güzelliğe hasret diye.

Aralık''ta ise işte bunu hiç sorma

Seni hiç aramayacağım neden diye sorman için.

Hele seni yılbaşında hiçmi hiç aramam

Ya bayramda onuda unut tamamen.

Sadece arada bir,gizlice gözlerini

seyretmek için  uzaktan bakacağım

Gözlerin ne halde ne durumda diye.

Ocak''ta bir iki sefer 

arayacağım seni.

şubat''ta ayında seni 

Bir sefer daha arayacağım.

Sana seni ne zaman arayacağımı

allah bilir diyeceğim.

Sana çok ciddiyim diyeceğim

Gülerek içim acıyarak.

Sen oturup düşüneceksin

Dişlerinin arasına sıkıştırdığım

sekizinci renk ile.

Masanın üstünde duran portakala 

Benim gibi nefretle bakacaksın.

Salacaksın kendini caddelere hava almak için

Benim gibi ağlayacaksın gizli gizli.

Lanetler yağdıracaksın kendine

Sandalyesi siyah olan yerlere,çimenlere,binalara.', 'Ben sana mayıs''ta Aşık olacağım her zaman. Haziran''da sana  çok sarılacağım. Temmuz''da senin sadece ellerini tutacağım. Ağustos''ta beni sana...', ARRAY['Türk Edebiyatı','Şiir','Eyüp Selahattin Dalkıran']::text[], 8.5, '{"poet":"Eyüp Selahattin Dalkıran","poet_slug":"eyup-selahattin-dalkiran","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/bana-bu-askta-cektirdiklerin-icin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İbadet', 'i-badet-firat-ulker-jw9xf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Günahkar bir kulum

Yasak olan herşeyi yaptım

İçki,kumar,kul hakkı,zina

Allahım beni affet

Ömrümün kalan kısmını

Sana ibadetle geçireceğim

Onu seveceğim

Sen kabul et Rabbim

Elimden başkası gelmiyor..

Geceleri verdin

Dinlenelim diye

Gündüzleri verdin

İbadet edelim diye

Tanrım

Ben gece gündüz demeden

Onu seviyorum

Sen kabul et Rabbim

Yari severek

Sana geliyorum..

                         20.12.05/05:43', 'Günahkar bir kulum Yasak olan herşeyi yaptım İçki,kumar,kul hakkı,zina Allahım beni affet Ömrümün kalan kısmını Sana ibadetle geçireceğim On...', ARRAY['Türk Edebiyatı','Şiir','Fırat Ülker']::text[], 8.5, '{"poet":"Fırat Ülker","poet_slug":"firat-ulker","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ibadet-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ülfet', 'ulfet-mustafa-benkli-9ss50', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Takılıp kaldığım şiir dostlarını `okuma`dan dönüp, vakit bulamayınca, eski notlardan bu ülfet geçti elime dokunamadım, çünkü o gün işte böyle doğmuştu bu:

Bir ruh bu: Milletimin necîp gönül büstünde

İllâ ki, Milletimin âfakını kuşatan; 

Gönülden gönüllere serilen meşk postunda

Ezelden, tâ ebede hayat olup yaşatan! ...

İksîri hâ Itrî`den, hâ Dede Efendi`den; 

İsterse Abdülkadir Merâbî`ye dayansın,

Gönlün ülfet kurduğu bu bağı ferhûndeden

Hepsine akan gönül tâ derûnundan yansın...

Beslensin hayatiyet menbaîndan herkesin,

Meşrebi, nesebiyle mûtedil ikliminde; 

Barış`la, Cem`den mülhem gönülde meltem essin,

İsminden tedâiyle buluşma gülşeninde! ...

Saâdet sun! İsmi hâs olsa da, olmasa da,

Adın Sâdi`den yana Mesnevî`den beslensin! ...

Bir tahtı mekân vardır sürûrı müntehada,

Ruhta `Vahtedi Vücût`; Can`lar ordan seslensin! ...', 'Takılıp kaldığım şiir dostlarını `okuma`dan dönüp, vakit bulamayınca, eski notlardan bu ülfet geçti elime dokunamadım, çünkü o gün işte böyl...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Benkli']::text[], 8.5, '{"poet":"Mustafa Benkli","poet_slug":"mustafa-benkli","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ulfet-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neden', 'neden-kevser-gulistan-cakir-6i436', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen

Küçücük bir denizsin

Ve ben

Okyanusları sende boğulmak için aştım...

Huzur beni çağırırken

Ölmek için uğraştım...', 'Sen Küçücük bir denizsin Ve ben Okyanusları sende boğulmak için aştım... Huzur beni çağırırken Ölmek için uğraştım......', ARRAY['Türk Edebiyatı','Şiir','Kevser Gülistan Çakır']::text[], 8.5, '{"poet":"Kevser Gülistan Çakır","poet_slug":"kevser-gulistan-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/neden-204-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'G e l -n e-- o l u r-g e l', 'g-e-l-n-e-o-l-u-r-g-e-l-ali-riza-unal-v8cdt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir ateş attın küllenmiş yüreğime,

Gayrı bu yürek bir başka yanmada

Bir tufana tutuldu,bu aciz od özüm

Bu ne tatlı göz yaşı,dil seni anmada

Şimdi bir başka ağlıyor bu gönül 

Izdırap hüzün değil ama yanmada

Bilmedim açlığımı,otlaktaydı gözüm,

Kulun visâl buldu,her dem kanmada,

- Yaa Hayyyyyy! Celle Celâlû Hûuuu! --

Bir çağrışki,gönlüme feryad-ı çığlık doldu,

Sen kedine çekmede,çağırmda Halık-ı marifsin,

Gel ey can evimin ulusu,sen kullarına elbete arifsin.

Gel çabuk ol,döküldü ziyneti varım,bu inleyene sarraf-ı zarifsin,

Şaştı bu miskin,bir garip ölüm uykusunda bu ne sır-ı cemâl.

Gel bir leylan sebeb-i visâl,sen kemale münezzeh

Tarisin

Gel ey eşsiz suphan senin sevişin bir başka övüşün bir 

başka     --  gel  ne  olur gel--', 'Bir ateş attın küllenmiş yüreğime, Gayrı bu yürek bir başka yanmada Bir tufana tutuldu,bu aciz od özüm Bu ne tatlı göz yaşı,dil seni anmada ...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/g-e-l-n-e-o-l-u-r-g-e-l-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Selam Sana', 'selam-sana-hidir-altas-7i8pd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aşkından deliyem

Yolda divaneyem

Yanık yüreğimden

Selam sana selam hey

Sazımın telinden

Bin türlü derdimden

Sevecen kalbimden

Selam sana selam hey

Uykusuz gecemden

Anımın içinden

Bitmez ümidimden

Selam sana selam hey

AŞIK TURHANİ-ANTALYA', 'Aşkından deliyem Yolda divaneyem Yanık yüreğimden Selam sana selam hey Sazımın telinden Bin türlü derdimden Sevecen kalbimden Selam sana sel...', ARRAY['Türk Edebiyatı','Şiir','Hıdır Altaş']::text[], 8.5, '{"poet":"Hıdır Altaş","poet_slug":"hidir-altas","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/selam-sana-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Huzur', 'huzur-rifki-kaymaz-v8sfz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İçimde canlanan temiz duyguda

Ümit var, ışık var, sevinç var artık.

Yeşeren ağaçta, çağlayan suda,

Bir başka ahenk var, bir başka ışık.

Günlerim aydınlık, günlerim güzel

Her yanım, saadet, her yanım huzur

Ve bütün ruhumu kuşatan güzel

Dol ey içerime halka halka nur.', 'İçimde canlanan temiz duyguda Ümit var, ışık var, sevinç var artık. Yeşeren ağaçta, çağlayan suda, Bir başka ahenk var, bir başka ışık. Günl...', ARRAY['Türk Edebiyatı','Şiir','Rıfkı Kaymaz']::text[], 8.5, '{"poet":"Rıfkı Kaymaz","poet_slug":"rifki-kaymaz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/huzur-45-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Emanet', 'emanet-suleyman-vardar-mtfhr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bıraktığın beyaz gülü 

Öpüp öpüp kokluyorum

Ayrılığın bir sembolü

Yıllar varki saklıyorum

Tam göğsümün şurasında 

Kanayan kalp yarasında

Cüzdanımın arasında

Emaneti saklıyorum

Gözüme mil çekenleri

Aşkıma kin ekenleri

Kurusa da dikenleri

Emaneti saklıyorum

Gençliğimin muhtırası

Hayatımın faturası

Mazimin hatırası

Beyaz gülü saklıyorum', 'Bıraktığın beyaz gülü  Öpüp öpüp kokluyorum Ayrılığın bir sembolü Yıllar varki saklıyorum Tam göğsümün şurasında  Kanayan kalp yarasında Cüz...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Vardar']::text[], 8.5, '{"poet":"Süleyman Vardar","poet_slug":"suleyman-vardar","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/emanet-39-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bugün', 'bugun-salim-calik-19n2l', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bugün

            I

bugün 

benim dünyam

toprağım susuz

çatlıyor ellerim

kayalar teslim olmuş

yüreğimle bir başıma

dünyam bugün aç

ellerim susuz

toprağım çatlıyor

uyanık ölüyor insanlar

kötülük onur

onur yok artık

       II

ben beyazın beyazlığını

zencilerin dişlerinde

açlığı sayılabilir kaburgalarında

acımasızlığını tanrının

çatlamış topraklarda gördüm afrikada

ve karın aydan yağdığını

duyuverdim bir ispanyoldan

       III

kapansın

açlığın ve doymazlığın açtığı gözyaşı kapıları

bir daha açılmasın

      IV

yüreklerimiz 

en bereketli parçası doğanın

ve biz

tarla çevirircesine çevirdik

dikenli tellerle yüreklerimizi

       V

   ''Halk içinde muteber bir nesne

                                yok devlet gibi

     Olmaya devlet cihanda

                                 bir nefes sıhhat gibi''

                                              Kanuni Sultan Süleyman

sıhhatten de geçtik 

ey kanuni

açıldı diye

güvercin kanadı dudaklarımız

vuruldu güvercin yürekli canlarımız', 'Bugün             I bugün  benim dünyam toprağım susuz çatlıyor ellerim kayalar teslim olmuş yüreğimle bir başıma dünyam bugün aç ellerim su...', ARRAY['Türk Edebiyatı','Şiir','Salim Çalık']::text[], 8.5, '{"poet":"Salim Çalık","poet_slug":"salim-calik","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/bugun-81-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutulmayan', 'unutulmayan-huseyin-ozan-ozturk-2yp7i', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İlkgözağrım,gönül sızım,birtanem.

Duydum ki,yoluma bakmakta imiş...

Göğsünde hıçkırık,kirpiginde nem,

Gözlerinden kan-yaş dökmekte imiş...

Dilden dile dolaşırmış sevdası,

Duyulmuyormuş artık şen kahkahası,

Elem denizinin hicran dalgası,

Gönül duvarını yıkmakta imiş....

Kahrolsun bizleri ayıran gemi,

Beklermiş rıhtımda döneceğimi,

Zalım aşk güneşi,Güzçiçeğimi,

Tıpkı benim gibi yakmakta imiş..

İlk defa öpüşüp kucaklaştığımız,

El ele tutuşup dolaştığımız,

Yeminler edererek vedalaştığımız.

O yerde gözyaşı dökmekte imiş...', 'İlkgözağrım,gönül sızım,birtanem. Duydum ki,yoluma bakmakta imiş... Göğsünde hıçkırık,kirpiginde nem, Gözlerinden kan-yaş dökmekte imiş... D...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Ozan Öztürk']::text[], 8.5, '{"poet":"Hüseyin Ozan Öztürk","poet_slug":"huseyin-ozan-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/unutulmayan-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Madenciye', 'madenciye-salim-calik-bloc6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Madenciye

umutlar ayrılığı yaşıyor dostum

suya atılan kömür közü yüreğimiz

taş tozunun tükettiği

grizularda

       göçüklerde

cız eder bedenimiz

yürekler aahhh

umutlar ölümü yaşıyor dostum

istekle koşarak madene

yangına düşen su damlası yüreğimiz

galerilerde

       panalarda

           kuyu diplerinde

                 varagellerde

barajlara tutsak metanla yanyana

yüreğim ah eder

ah çare etmez

yaşadığım geceli gündüzlere

paydosun adı / geçmiş olsun

kömür tozunun kalem çektiği gözlere

                                                 8/ 1/ 95', 'Madenciye umutlar ayrılığı yaşıyor dostum suya atılan kömür közü yüreğimiz taş tozunun tükettiği grizularda        göçüklerde cız eder beden...', ARRAY['Türk Edebiyatı','Şiir','Salim Çalık']::text[], 8.5, '{"poet":"Salim Çalık","poet_slug":"salim-calik","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/madenciye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saat', 'saat-salim-calik-25hbi', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Saat

                 (Cemal Süraya''nın anısına) 

şair durur bir yerinde yaşamın

her ölüm erken ölümdür der

ömür saati durmaya yüz tutunca

bir başka şair

kapatır perdeyi gecenin ortasına

her ölüm yeni bir yaşamdır der

ömür saati durunca

                            8/ 1/ 92', 'Saat                  (Cemal Süraya''nın anısına)  şair durur bir yerinde yaşamın her ölüm erken ölümdür der ömür saati durmaya yüz tutunca b...', ARRAY['Türk Edebiyatı','Şiir','Salim Çalık']::text[], 8.5, '{"poet":"Salim Çalık","poet_slug":"salim-calik","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/saat-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Affet Sevgilim', 'affet-sevgilim-ferit-korkmaz-208b1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Adını eskisi kadar anmıyorum

Eskisi kadar adına şiir yazmıyorum

Sevemiyorum eskisi kadar

Anlatırdı her olay mazimizi,yaşadıklarımızı

Sokak aralarında eskisi kadar gezmiyorum

Banklarda soguk elimi ısıtmıyorum

Gözlerim eskisi kadar dalmıyor ufuklara

Sevemiyorum,sevemiyorum eskisi kadar

Yazmıyacaktım sayfalara sevdamızı

Anmayacaktım sevgimizi,mazimizi

anlatıyor banklar,sokaklar seni bana

Anlatıyor şarkılar seni bana...

Mısraları okuyamıyorum şiirlerin

Korkuyorum seni anmaktan

Korkuyorum uzunca eskilere dalmaktan

Korkuyorum,korkuyorum sevgilim

Ellerimiz ayrılsada unutmuyacaktık

Sevgimizi sancak gibi cıkartacaktık yukseklere

Ben sözumu tutamadım

Affet sevgilim Affet', 'Adını eskisi kadar anmıyorum Eskisi kadar adına şiir yazmıyorum Sevemiyorum eskisi kadar Anlatırdı her olay mazimizi,yaşadıklarımızı Sokak a...', ARRAY['Türk Edebiyatı','Şiir','Ferit Korkmaz']::text[], 8.5, '{"poet":"Ferit Korkmaz","poet_slug":"ferit-korkmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/affet-sevgilim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bırak artık bırak bizi', 'birak-artik-birak-bizi-ferit-korkmaz-sx79p', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yıllardır dilimizdesin

Çek git be gülüm çek git

Parçaladığın yetmezmiş gibi,vaktimizide çaldın

Her sabah seninle uyanmaktan

Güneşin batışına kadar seninle olmaktan

Sıkıldık be gülüm sıkıldık

Aileden yıllara değen düşünceyi

Hobi haline getiren düşünceyi

Haklıyı haksız yapan düşünceyi

İstemiyoruz,istemiyoruz be gülüm

Yakamızı bırak artık

Sağ-Sol sözcüklerini unutalım

Yaşatayalım bir daha kargaşalığı,ayrımcılığı

Bıktık artık,bıktık be gülüm

Dış savaş içinde değiliz

Gelişemeyen bir Devlet içindeyiz

Küçük kapasitemizle büyüdük onunla

Hep yola onunla başladık

Haksızda olsak,haklıda olsak onunla yürüdük

Çek git sağ-sol çek git

Hepimiz devletimiz için varız,Devlet bizim için

İkileme yapmayalım,kardeşiz hepimiz

Bırakın şu sorunları,bırakın şu köhne sözcükleri

Bırak artık bırak bizi sağ-sol

Seni bize kim musallat etti

Ezmeyecek,ezemeyeceksin ey kör sözcük ezemeyeceksin

Konuşmaya başlayan bebelerimizin

Saçları ağrmış dedelerimizin

Geleceğe ışık tutan gençlerimizin

Dilinde hep sen varsın

Hep sen varsın sağ-sol

Sen bırakmazsan biz bırakacağız

Tek yürek,tek cihan olacağız artık

Ezdirtmecegiz medeniyetimiz,i ezdirmiyeceğiz

Bırak artık bizi bırak sağ-sol

Evimizin her köşesine doğru yol diye cizdik seni

Mutluluğun, bağımsızlığın ta kendisi zannettik seni

Göremedik,göremedik gerçek yüzünü

Biz yaklaştık,sen sarıldın,bırakmadın bizi

Dost zannettik seni

Bırak artık bırak bizi sağ-sol

Kardeşçe sırlarımızın her cümlesinde seni andık

Sizlere danıştık geleceğimizi

Düşünmeden sana verdik,sana verdik sağ-sol

Araştırmadan,öğrenmeden odamızı aydınlatmana izin verdik

Haklıyı senden öğrendik

Doğruyu seninle kabullendik

Bırakın bırak artık ey insalık', 'Yıllardır dilimizdesin Çek git be gülüm çek git Parçaladığın yetmezmiş gibi,vaktimizide çaldın Her sabah seninle uyanmaktan Güneşin batışına...', ARRAY['Türk Edebiyatı','Şiir','Ferit Korkmaz']::text[], 8.5, '{"poet":"Ferit Korkmaz","poet_slug":"ferit-korkmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/birak-artik-birak-bizi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünyamızı Koruyalım', 'dunyamizi-koruyalim-suleyman-vardar-1k6yh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sahip çıkıp çevremize

                                               Biraz işe yarayalım

                                               Yeşil doğa cennet bize

                                               Dünyamızı koruyalım

                                                      Yaşamaktan bezmeyelim 

                                                      Karıncayı ezmeyelim

                                                      Sokakları üzmeyelim

                                                      Dünyamızı koruyalım

                                               Ormanları yakmayalım

                                               Heyalanı sokmayalım

                                               Felakete bakmayalım

                                               Dünyamızı koruyalım

                                                      Cazip moda hatırası

                                                      İşte ozan faturası 

                                                     Temizliğin tam sırası

                                                     Dünyamızı koruyalım 

                                               Süper gücün ilahları

                                               Bu kan kusan belaları

                                               Kırıp bütün silahları 

                                               Dünyamızı koruyalım

                                                    Geçmişten bir ders alalım

                                                    Gelin biraz yorulalım

                                                    Siyah beyaz bir olalım

                                                    Dünyamızı koruyalım', 'Sahip çıkıp çevremize                                                Biraz işe yarayalım                                                Yeşi...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Vardar']::text[], 8.5, '{"poet":"Süleyman Vardar","poet_slug":"suleyman-vardar","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/dunyamizi-koruyalim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeni Yıl ve Bayram', 'yeni-yil-ve-bayram-yusuf-ziyaeddin-sivaslioglu-2pqof', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yeni yıl ve Bayram

Geldi arka  arkaya

Ulaştığımız için bu günlere

Şükürler olsun Tanrı''ya

Yeni yılda yeni umutlar,

Diliyorum sizlere dostlar

Sağlık ve esenlik dilekleriyle

Yusuf Bayramınızı kutlar

(İstanbul,25 Aralık 2005)', 'Yeni yıl ve Bayram Geldi arka  arkaya Ulaştığımız için bu günlere Şükürler olsun Tanrı''ya Yeni yılda yeni umutlar, Diliyorum sizlere dostlar...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziyaeddin Sivaslıoğlu']::text[], 8.5, '{"poet":"Yusuf Ziyaeddin Sivaslıoğlu","poet_slug":"yusuf-ziyaeddin-sivaslioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yeni-yil-ve-bayram-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deniz Benim Arkadaşım', 'deniz-benim-arkadasim-hidir-altas-j6bvd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aşık oldum dalgasına

Canım kurban balığına

Selam senin insanına

Deniz benim arkadaşım

deniz benim dert yoldaşım

Sevdiğimdir martıları

Uzar gider kıyıları

Yüzer durur kayıkları

NAKARAT NAKARAT

Şiir yazdım senin için

Yanıyorum için için

Ölüyom ben senin için

NAKARAT NAKARAT

AŞIK TURHANİ-ANTALYA', 'Aşık oldum dalgasına Canım kurban balığına Selam senin insanına Deniz benim arkadaşım deniz benim dert yoldaşım Sevdiğimdir martıları Uzar g...', ARRAY['Türk Edebiyatı','Şiir','Hıdır Altaş']::text[], 8.5, '{"poet":"Hıdır Altaş","poet_slug":"hidir-altas","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/deniz-benim-arkadasim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bakma', 'bakma-mehmet-can-iow60', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bakma bana  derin gözlerinle..

Pişmanlıkları gözlerine manşet yapmışsın.

Okuyorum.

Gel desem, geleceksin.

Biliyorum.

Ama seni tanıyorum.

Gel demeden, bu sefer gidiyorum.', 'Bakma bana  derin gözlerinle.. Pişmanlıkları gözlerine manşet yapmışsın. Okuyorum. Gel desem, geleceksin. Biliyorum. Ama seni tanıyorum. Gel...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Can']::text[], 8.5, '{"poet":"Mehmet Can","poet_slug":"mehmet-can","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/bakma-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Empati', 'empati-twin-markus-33l0q', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İnsanlar

At dediler...

Deve,

Eşek,

Domuz,

Karga,dediler,

Hayvanlara....

Hayvanlar,insanlar gibi

Aynı imkana sahip olsalardı,

Neler derlerdi,

İnsanlara? ....', 'İnsanlar At dediler... Deve, Eşek, Domuz, Karga,dediler, Hayvanlara.... Hayvanlar,insanlar gibi Aynı imkana sahip olsalardı, Neler derlerdi,...', ARRAY['Türk Edebiyatı','Şiir','Twin Markus']::text[], 8.5, '{"poet":"Twin Markus","poet_slug":"twin-markus","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/empati-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çözemedim Esrarını', 'cozemedim-esrarini-suleyman-vardar-wnk4u', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Baktım yıldız gözlerine

Kıramadım ısrarını

Yandım yalan sözlerine

Çözemedim esrarını

Ne kimliğin kişiliğim

Ne sevgide peşinliğin

Yetmiyor ki dişiliğin

Çözemedim esrarını

Ziyan olan bu günleri

Veremezsin bana geri

Kendin söyle sahte peri

Çözemedim esrarını

Selam versem almıyorsun

Bekle diyor gelmiyorsun

Sevmek nedir bilmiyorsun

Çözemedim esrarını

Aklın ruhun sağda solda

Gönlün bilmem hangi dalda

Çıkmıyorsun hiçbir falda

Çözemedim esrarını', 'Baktım yıldız gözlerine Kıramadım ısrarını Yandım yalan sözlerine Çözemedim esrarını Ne kimliğin kişiliğim Ne sevgide peşinliğin Yetmiyor ki...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Vardar']::text[], 8.5, '{"poet":"Süleyman Vardar","poet_slug":"suleyman-vardar","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/cozemedim-esrarini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda', 'sevda-hidir-altas-re0vc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sevda beni öldürecek

Sevdiğime götürecek

Mezarımda gül bitecek

Yolmayın ah yolmayın

Sevda beni güldürmüyor

Hasretimi dindirmiyor

Kimse beni anlamıyor

Anlayın ah anlayın

Turhaniyem yandım artık

Yaşamaktan bıktım artık

Hayat bana zulüm artık

Vurun beni ah vurun beni

AŞIK TURHANİ-ANTALYA', 'Sevda beni öldürecek Sevdiğime götürecek Mezarımda gül bitecek Yolmayın ah yolmayın Sevda beni güldürmüyor Hasretimi dindirmiyor Kimse beni ...', ARRAY['Türk Edebiyatı','Şiir','Hıdır Altaş']::text[], 8.5, '{"poet":"Hıdır Altaş","poet_slug":"hidir-altas","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sevda-129-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beklemek İstediğim', 'beklemek-i-stedigim-muzaffer-tekbiyik-kqd1b', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sana şarkı yazardım,bestekarım olsaydı

Gül yüzünü güllerle,süslemek istediğim

Elçin olur kapında,seyre dalardım seni

Ellerini tutupta,beklemek istediğim

Ağlamak istediğim

Söylemek istediğim

Ömür boyu uğrunda

Beklemek  istediğim

Ne geç rastladım sana,sen ne kötü kadersin

Ben sevmek istesemde,kim bilir neler dersin

Küçük sevdiğim benim,hangi gönüllerdesin

Ömür boyu kapında,beklemek istediğim

Ağlamak istediğim

Söylemek istediğim

Ömür boyu uğrunda

Beklemek istediğim

Hayalden bile öte,bestesiz şarkılarım

Yalnız kağıtta kalır,acı hatıralarım

Seni hayalden başka,rüyadada anarım

Senden ötelerde,sessiz ağlamak istediğim

Ağlamak istediğim

Söylemek istediğim

Ömür boyu uğrunda

Beklemek istediğim', 'Sana şarkı yazardım,bestekarım olsaydı Gül yüzünü güllerle,süslemek istediğim Elçin olur kapında,seyre dalardım seni Ellerini tutupta,beklem...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Tekbıyık']::text[], 8.5, '{"poet":"Muzaffer Tekbıyık","poet_slug":"muzaffer-tekbiyik","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/beklemek-istedigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Giderken...', 'sen-giderken-esra-ekmekci-0ir8v', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Giderken gözlerime bak uzun uzun,

Gözlerin gözlerimde asılı ben sensizliği tadayım.

Öyle sarıl ki ayrılırken, kokun sinsin üstüme

Tenimde seni koklayıp,vuslata kadar

O kokunla yaşamı soluyayım.

Ağlamamak seni daha güçlü gösterecekse ağlama,

Ama bana da ağlama deme! 

Ağlayarak sindiriyorum içimden çıkmaya çalışan yüreğimi.

Boşa geçecek zamanımın cenazesi bu! 

Kaybedişim yitişim değil, kaybedişim özlemim.

Sensizliği sırtıma atıp taşırım, zor olmasa gerek

Yüreğinde aynı bensizlikle yorulma sakın,

Ben bıkmadan, yorulmadan burda seni bekliyor olucam...', 'Giderken gözlerime bak uzun uzun, Gözlerin gözlerimde asılı ben sensizliği tadayım. Öyle sarıl ki ayrılırken, kokun sinsin üstüme Tenimde se...', ARRAY['Türk Edebiyatı','Şiir','Esra Ekmekçi']::text[], 8.5, '{"poet":"Esra Ekmekçi","poet_slug":"esra-ekmekci","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sen-giderken-44-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Götürmek', 'goturmek-twin-markus-72atn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bakıyorum çevreme,

Götüren götürene....

Tüm bunları görünce,

İster istemez

Soruyorum,kendi kendime....

Ben ne götürdüm diye? ....

Bizim götüreceğimiz,

Yüce mevlamın 

Bize bahşettiği mide kadar....

Ama o da; 

Sadece bir öğün.....

Onun da gideceği yer malum....

Diyeceksin ki,

Kana karışanlar ne olacak? 

Eeeeee......

Müsaade ette

O kadar yaşayalım......', 'Bakıyorum çevreme, Götüren götürene.... Tüm bunları görünce, İster istemez Soruyorum,kendi kendime.... Ben ne götürdüm diye? .... Bizim götü...', ARRAY['Türk Edebiyatı','Şiir','Twin Markus']::text[], 8.5, '{"poet":"Twin Markus","poet_slug":"twin-markus","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/goturmek-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tik', 'tik-twin-markus-4hi2b', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kiminin elinde,

Kiminin belinde,

Kiminin dilinde,

Kiminin her yerinde....

Tik,tik,tik....

Bazıları doğustan,

Bazıları sonradan,

Bazıları kafadan,

Bazıları,karmadan....

Tik,tik,tik...

Tikiniz varsa,

Kendinizi saat gibi hissedin,

Tikiniz yoksa,

Kalbinizi dinleyin...', 'Kiminin elinde, Kiminin belinde, Kiminin dilinde, Kiminin her yerinde.... Tik,tik,tik.... Bazıları doğustan, Bazıları sonradan, Bazıları kaf...', ARRAY['Türk Edebiyatı','Şiir','Twin Markus']::text[], 8.5, '{"poet":"Twin Markus","poet_slug":"twin-markus","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/tik-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anjio', 'anjio-twin-markus-y73yq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şimdiye kadar

Kimse kalbime ulaşmadı mı

Diyorsunuz? 

Ya da damardan kimse girmedi? 

Kolayı var

Hemen anjio olun...

Doktor dese dese

İki şey söyleyecek

Bir şey demiyecek

Ya sizin iyi bir kalbiniz var diyecek

Bu iyi bir şey....

Ya da

Maalesef,kalbiniz kötü diyecek

Ama endişe etmeyin

Çaresi var; 

Stend

Balon

İleride yamaç paraşütü,belki de...

Ya da cerrahi müdahale....

Demiyeceği; 

Kalbinizin gerçek sahibi', 'Şimdiye kadar Kimse kalbime ulaşmadı mı Diyorsunuz?  Ya da damardan kimse girmedi?  Kolayı var Hemen anjio olun... Doktor dese dese İki şey ...', ARRAY['Türk Edebiyatı','Şiir','Twin Markus']::text[], 8.5, '{"poet":"Twin Markus","poet_slug":"twin-markus","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/anjio-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sıkma', 'sikma-twin-markus-wnf2c', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevdiğim,

Senden çok küçük

Bir ricam var

Ne olur beni sıkma...

Beni sıkacağına,

Git,portakalı sık

Limonu sık

İstersen greyfurt...

Ama ne olur beni sıkma...

İstersen,

Al eline hortumu

Tak çeşmeye

Tut çimlere

Çimlere sık

Ama ne olur beni sıkma...

Kesmedi,

Tak kemeri beline,

Sık son deliğine

Kemerini sık

Ama ne olur beni sıkma...

Bu da yetmezse,

Al tabancayı eline

Daya kafana,bir güzelce

Kafana sık

Ama ne olur beni sıkma...', 'Sevdiğim, Senden çok küçük Bir ricam var Ne olur beni sıkma... Beni sıkacağına, Git,portakalı sık Limonu sık İstersen greyfurt... Ama ne olu...', ARRAY['Türk Edebiyatı','Şiir','Twin Markus']::text[], 8.5, '{"poet":"Twin Markus","poet_slug":"twin-markus","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sikma-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayır', 'hayir-muzaffer-tekbiyik-1o594', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir gün gelsem kapına,yalvarmaya başlasam

Yıllar hep böyle geçse,yinede usanmasam

Diz çöküp hep önünde,ellerine kapansam

Yine hayırmı dersin,hiç acımadan bana

Vicdansız merhametsiz,zalim sevdiğim

Ne tutuyor ellerim,ne söylüyor dillerim

Biliyorum merhamet,aşk yeşertmez gönülde

Sevmaya engel varsa,sevmişsen gençliğinde

Ben yansam her gün sana,olurmusun derdinde

Yinede hayır dersin,hiç merhamet yok sende

Vicdansız merhametsiz,zalim sevdiğim

Ne söylüyor dillerim,ne tutuyor ellerim

Herşeyimden vaz geçip,kapına geliversem

Güneş yıldız ve aydan,bir demet veriversem

Okyanusa uzanan,bir saray sunuversem

Yinede hayır dersin,hiç merhamet yok sende

Kapıdan kovsanda,bacadan geleceğim

Kollarıma seni alıp,bir ömür seveceğim

(1997)', 'Bir gün gelsem kapına,yalvarmaya başlasam Yıllar hep böyle geçse,yinede usanmasam Diz çöküp hep önünde,ellerine kapansam Yine hayırmı dersin...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Tekbıyık']::text[], 8.5, '{"poet":"Muzaffer Tekbıyık","poet_slug":"muzaffer-tekbiyik","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/hayir-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Yeter', 'sana-yeter-baris-caglar-4nxim', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gözümün daldığı sen tek noktasın,

Aşkımın yandığı o büyük oktasın

Gecemin gündüzü olmayan yoktasın,

Ama varsın ya o bana yeter.

Gözüm kör olsaydı bakmasaydım gözüne,

Aşkım dışına değil o çok güzel özüne,

Özünden bana vermesen de yüzüme,

Yazıldın ya o bana yeter.

İşte uzaklardan aşkım göründün,

Yine bana düşman lekeye büründün.

Aşkımın peşinden bir an süründün,

Birazcık ağladın ya o bana yeter.

Bana olan sana,san olan bana yeter,

İkimizin herşeyi bu nokta da biter,

Sayende halim mecnundan beter,

Ama ben yeniyorum ya o bana yeter.

Gözüm kaçıyordu aşkım tuzak kurdu,

Tuzağın beni can evimden vurdu,

Vurulan gönlüm yaralıca durdu,

Ben yandım ya o sana yeter.', 'Gözümün daldığı sen tek noktasın, Aşkımın yandığı o büyük oktasın Gecemin gündüzü olmayan yoktasın, Ama varsın ya o bana yeter. Gözüm kör ol...', ARRAY['Türk Edebiyatı','Şiir','Barış Çağlar']::text[], 8.5, '{"poet":"Barış Çağlar","poet_slug":"baris-caglar","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sana-yeter-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kıyametin Ellerimden Olacak', 'kiyametin-ellerimden-olacak-ali-kalafat-w88i4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şimdi kim bilir neredesin? 

Degil ben 

Tanrı bile izini kaybetmiş

Kim bilir kimlerlesin 

Bilmiyorum sensiz bu halim ne olacak 

AMA

YA ŞİMDİ DÖN 

YA KIYAMETİN ELLERİMDEN OLACAK

Seni aramaya sabah erkenden cıktım sokağa

Bakkalından ekmek çaldıgımız 

Soguk sokaklarda aradım seni

Camlarına taş atıp kırdıgımız teyzelere sordum

Sürekli beni bekledigin parka gittim

Sen degil 

Sadece ismin duruyordu

Kör çakılarla kazıgım

O lanet suskun banklarda

Şimdi nerede oldugunu bilmiyorum

AMA

YA ŞİMDİ DÖN 

YA KIYAMETİN ELLERİMDEN OLACAK

Güvercin uçurdugumuz saçaklarda dolaştım

Martılara ekmek attıgımız liman kenarlarında 

İlk gittigimiz sinemanın önünde bekledim saatlerce

Gelmedin...

Herkesten farklı bir şey yapayım dedim

Seni soruyorum 

Bilmiyorlar ya yerini

BEN SENİ SORDUM İÇİME

KENDİM KENDİME VERECEK CEVAP BİLE BULAMADIM 

AMA

YA ŞİMDİ DÖN 

YA KIYAMETİN ELLERİMDEN OLACAK

Gazoz kapagı sakladıgımız duvar aralarını eşeledim 

Paslı tellerinden nişan yüzükleri 

yaptıgımız inşaatın önünden geçtim

Yoktun..

Çiçeklerini yoldugumuz bahçelere baktım

Sen hariç tüm çiçekler aynen yerindeydi 

Sonra çöp koladıgımız kaldırımları seyrettim

Her artıgın kokusu geldi 

Senin kokun hariç

Derin bir nefes çektim içime 

Herşey doldu cigerime

Bir sen içinde yoktun 

AMA

YA ŞİMDİ DÖN 

YA KIYAMETİN ELLERİMDEN OLACAK

Şimdi sen yoksun ben nereye giderim 

Ne yaparım o kocaman sensiz sessiz kimsesiz barakada

Sen gittin şimdi 

Peki kopayımmı ben tüm yaşantımdan? ? 

Gelemeyeceksen BENDE ŞİİR YAZARIM ÖYLEYSE

TEK OKUYUMLUK ŞİİRLER

TIPKI SENİN GİBİ

TIPKI BUNUN GİBİ

DÖNMEYECECEKSEN BARİ BİR CEVAP YAZ 

YADA 

YADA KIYAMETİN ELLERİMDEN OLACAK', 'Şimdi kim bilir neredesin?  Degil ben  Tanrı bile izini kaybetmiş Kim bilir kimlerlesin  Bilmiyorum sensiz bu halim ne olacak  AMA YA ŞİMDİ ...', ARRAY['Türk Edebiyatı','Şiir','Ali Kalafat']::text[], 8.5, '{"poet":"Ali Kalafat","poet_slug":"ali-kalafat","theme":"Türk Şiiri","is_hero":false,"total_lines":59,"source_url":"https://www.antoloji.com/kiyametin-ellerimden-olacak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Oluyorum', 'sen-oluyorum-birsen-ates-7yu52', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'can çekişiyor aşk  yine

kimliksiz hüzünleriyle içimde 

her gece yıkıyorum 

dinmeyen sızılarımı

kadehleriyle içkimde

	

düşüyorsun yine kirpiklerimden

her gece düşlerime

içimde dolaşırsın,

sarhoşluğumun düşleriyle

ben senin oluyorum

kadehler boşalıp

kendimi kaybettiğimde

içimde yalnız birisin

ben benliğimde kaybolunca

ben seni buluyorum

sen oluyorum

her gece sarhoşluğumda

kendimi kaybetmiş

daha kaç gece böyle,

seninle olmaya çalışacağım..

benim olman için

kendimden uzaklaşacağım

Şair Arkadaşım Ertuğrul Bayam''la bir şiir düeti

25.12.2005', 'can çekişiyor aşk  yine kimliksiz hüzünleriyle içimde  her gece yıkıyorum  dinmeyen sızılarımı kadehleriyle içkimde 	 düşüyorsun yine kirpik...', ARRAY['Türk Edebiyatı','Şiir','Birsen Ateş']::text[], 8.5, '{"poet":"Birsen Ateş","poet_slug":"birsen-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sen-oluyorum-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kar', 'kar-perihan-dosgul-neok2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dışarda kar var, hava buz gibi 

Ve sen yoksun,

Gözlerin, ellerin ve yüreğin çok uzaklarda,

Sensizlik, yüreklerde yara...

Sensizlik akıllara zarar,

sensizlik yok olmak,

Tükenmek, 

Sonsuzluğa 

Adım adım yaklaşmak...', 'Dışarda kar var, hava buz gibi  Ve sen yoksun, Gözlerin, ellerin ve yüreğin çok uzaklarda, Sensizlik, yüreklerde yara... Sensizlik akıllara ...', ARRAY['Türk Edebiyatı','Şiir','Perihan Dosgül']::text[], 8.5, '{"poet":"Perihan Dosgül","poet_slug":"perihan-dosgul","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/kar-73-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seninle Gidilmez', 'seninle-gidilmez-cemile-duzgun-xy3vv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Küfrün sele dönmüş,volkan misali,

Hüsran şaşkınlığım inkâr edilmez

Bu dünya sayende cadı masalı

Seninle cennete bile gidilmez...

Tatlı dil nerede,acısı dolu,

Besbelli çıldırmış,olmuşsun deli

İstemem o günde tutma bu Salı

Seninle cennete bile gidilmez...

Altmışında ankâ uçuruyorsun,

Ömrü,sahibinden kaçırıyorsun,

Gözümde gitgide küçülüyorsun

Seninle cennete bile gidilmez...

Bülbül nasıl şakır,düşmüşse derde? 

En son dönemeç bu,ne kaldı serde? 

Sevginin ve aşkın bittiği yerde,

Seninle cennete bile gidilmez...

Güven yoksa sevgi noktalanmaz mı? 

Bu acıyla ömür sektelenmez mi? 

Gönül gücenir de,nüktelenmez mi? 

Seninle cennete bile gidilmez...

Damla görmedim ki,neyime rahmet,

Artık lazım değil eyleme zahmet,

Mezarıma gelme,okuma rahmet,

Seninle cennete bile gidilmez...! 

Cemile DÜZGÜN   /  2004', 'Küfrün sele dönmüş,volkan misali, Hüsran şaşkınlığım inkâr edilmez Bu dünya sayende cadı masalı Seninle cennete bile gidilmez... Tatlı dil n...', ARRAY['Türk Edebiyatı','Şiir','Cemile Düzgün']::text[], 8.5, '{"poet":"Cemile Düzgün","poet_slug":"cemile-duzgun","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/seninle-gidilmez-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bakışları Ceylan Gibi sevdiğim', 'bakislari-ceylan-gibi-sevdigim-umut-gungor-ppfj3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne dedimse sır vermiyor yürekten,

Güzelliği almış beyaz melekten,

Ölüyordum geri döndüm direkten,

Bakışları ceylan gibi sevdiğim.

Bir söz olsun benceğize lütfetse,

Bakışıma nazar edip affetse,

Şu gönlümü yüreğine hapsetse,

Bakışları ceylan gibi sevdiğim.

Bakışları yüreğime iniyor,

Heyecanı bileğime biniyor,

Gül kokusu benliğime siniyor,

Bakışları ceylan gibi sevdiğim.', 'Ne dedimse sır vermiyor yürekten, Güzelliği almış beyaz melekten, Ölüyordum geri döndüm direkten, Bakışları ceylan gibi sevdiğim. Bir söz ol...', ARRAY['Türk Edebiyatı','Şiir','Ümüt Güngör']::text[], 8.5, '{"poet":"Ümüt Güngör","poet_slug":"umut-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bakislari-ceylan-gibi-sevdigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Git Diyorum Sana', 'git-diyorum-sana-ali-kalafat-5m8j3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Git artık uzaklara

Eger yaşamak istemiyorsan hatıralarımda 

Git işte boşa bekleme buralarda 

Dogmak istiyorsan bensiz yarınlarda 

GİT İŞTE 

GİT DİYORUM SANA

SAKIN DURMA BURALARDA

Peşimden koşar sanıyorsan tüm dünya

Git işte 

Sakın durma buralarda

Seveceksen yine ilkbaharlarda

Git durma

Tadacaksan bir parça mutluluk

GİT İŞTE 

GİT DİYORUM SANA 

SAKIN DURMA BURALARDA

Kaybettiklerine bir kez daha bakmayacaksan 

Dönüp arkandan haber sormayacaksan 

GİT İŞTE

GİT DİYORUM SANA 

SAKIN DURMA BURALARDA

Bir damla yaş dökmeyeceksen maziden kalanlara 

Git durma

Kimler kalır ardımda

Birileri bakar diye düşünmüyorsan 

Git durma

Aklına gelmeyen

Sebebini bilmedigin sorunları olursa

Git durma

Ve bunu için gidiyorsan 

Bunu sakın

AMA SAKIN BANA SORMA

SON SÖZÜMÜ DE DİNLEMİYORSAN 

VE İSTİYORSAN HALA................................... 

GİT İŞTE

GİT DİYORUM SANA

SAKIN DURMA BURALARDA

ANLATAMADIM İŞTE

DİLİM SÖYLEYEMİYOR AMA

BİLMİYORUM İŞTE

GİDECEKSEN HİÇ DURMA', 'Git artık uzaklara Eger yaşamak istemiyorsan hatıralarımda  Git işte boşa bekleme buralarda  Dogmak istiyorsan bensiz yarınlarda  GİT İŞTE  ...', ARRAY['Türk Edebiyatı','Şiir','Ali Kalafat']::text[], 8.5, '{"poet":"Ali Kalafat","poet_slug":"ali-kalafat","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/git-diyorum-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '..Alıştırdın..', 'alistirdin-i-brahim-ozcan-55-x0on1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Süzme gözlerinden akan yaşlarla dönerim,

Gelmez oldum, istesende istemesende artık.

Kaç baharı geçirdik, aylar yıllara vurdu,

Bana sevdayı sormamayı alıştırdın..

Bin kere ölmek, bir kere senden ayrılmak.

İkisi de aşkının ateşinde, kalbimi yakmak.

Geriye dönememek, uçuruma düşüp ölmekse; 

Kaç kez öldüm ben, artık bunu da alıştırdın..

Nankör gururum kıyamadı, uykundan uyandırmaya.

İnanmazdın gideceğime, kaç kere kapından döndüm bilemezsin.

Mutlu olasın diye gülüm, sevdana vazgeçtim. 

Acını mı çekmek, bunu da alıştırdın..

Ben çıkmazlara gittim, umutsuzum ama! 

Çok özledim, canımsın, delice ihtiyacım var aşkına.

Aşkın ötesinde gerçeği, yanmış kalbim korudu. 

Ben yine aynıyım, yine unuttuğun aşık, bunu da alıştırdın..

Yaprağım dalından koparıldı, bülbül ötmez artık.

Damarımdan akan kanım, kolumda dolaşmaz oldu.

Kalbinde ki deva, içimde dermansız kaldı.

Çok sevdim diye ahh çekmek, bunu da alıştırdın..

Arayanı yok, çıldırmış yokluğunda benliğim. 

Birden çıkıverip karşına, şaşırtmak seni.

Kokunu duymak üzerimde, aynı nefesi solumak tekrardan.

Hayal kurmak sana, bunu da alıştırdın..

Düştüm sanki mapusa, ne bu çekilen ceza,

Namus besmelesi onurum, kıblem doğruluk.

Kurban ettim, kalemimi kırdım, canımı verdim.

Sağken, ölümü yaşamak, bunu da alıştırdın..

Ruhumun derinlerine gizleyip, içimi dökmek sana.

Doyasıya sarılmak, ateşte olsan gel diyebilmek.

Davulların çalması, ölüme dek sevdayı nişanlamak.

Sevincin sedasındaki ayrılığa, dayanmayı da alıştırdın..

                                                                                (Hırçın) 

                                                                        11.04.2002 03; 45

                                                                                BURSA', 'Süzme gözlerinden akan yaşlarla dönerim, Gelmez oldum, istesende istemesende artık. Kaç baharı geçirdik, aylar yıllara vurdu, Bana sevdayı s...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Özcan 55']::text[], 8.5, '{"poet":"İbrahim Özcan 55","poet_slug":"i-brahim-ozcan-55","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/alistirdin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olur mu Can?', 'olur-mu-can-cemile-duzgun-1wh31', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yaz gününde dolu gibi

Çıkmazlarım erir mi can? 

Feleğin şans kolu gibi,

Bilmem beni korur mu can? 

Canıma can oldun diye

Sevgin sığmaz yüreğime,

Ey Allah’ım dileğime

Bilmem değer verir mi can? 

Kollarımı açtım desem,

Muhabbetler vereylesem

Yoluna turna tellesem

Acep haber varır mı can? 

Papatyalardan fal tutsam

Uğruna fincan kapatsam

Çaput sarsam,düğüm atsam

Bilmem kabul görür mü can? 

Gönüllerle,hatırlarla

Türbelerle, yatırlarla

Dua dolu satırlarla

Bilmem arşa erer mi can? 

Cemile Düzgün-10-02-04', 'Yaz gününde dolu gibi Çıkmazlarım erir mi can?  Feleğin şans kolu gibi, Bilmem beni korur mu can?  Canıma can oldun diye Sevgin sığmaz yüreğ...', ARRAY['Türk Edebiyatı','Şiir','Cemile Düzgün']::text[], 8.5, '{"poet":"Cemile Düzgün","poet_slug":"cemile-duzgun","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/olur-mu-can-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsana, yazana ve tanrıya dair dil sürçmesi...', 'i-nsana-yazana-ve-tanriya-dair-dil-surcmesi-zafer-zengin-etnika-f5jhq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '.

Medeniyete; 

Sessiz sakin köşesinde 

Düşünürken ne olacak hallerini 

Yerine bağırıyor 

Seni andık 

Sana taptık diyen işsizleri 

Koro halinde; 

-Seni andık 

-Sana taptık 

İş edinmişler düşen davalarda 

Avukatlık etmeyi 

Kafalarına vurmak bazılarının 

Varlığına inanın demeyi 

Sana ne 

Sana 

Ne 

Koro halinde; 

-seni andık 

-sana cinayetler yaptık 

-seni kattık 

ortada pişmanlık duyanların dert yanması; 

vaatlerinden bunaldık 

güzel şeylere kan,dık 

kanadık 

seni unuttuk hatırlamadık 

emreder; Nefsiniz için öldürmeyin 

koro halinde; 

-biz insan yakarız senin için 

-senin için 

-yüceltmiştin 

melekler bu duruşa secde eder // kan kıyamet cehalet 



Biz ateşi çaldığımızda 

Küçük çocuktu tanrı hala 

Yendi ciğerlerimiz 

Kartalı insan oldukça 

Sormayacağım 

Yazılı lanetleriniz kaç parça 

Sığdıramadınız insanı 

Koyamadınız ortasına 

Koro halinde başka gurubun söylencesi; 

Çok büyüğüz 

O en küçüğümüz 

Onun için kıymadık kimseye 

Bu yüzden temiz yüzümüz 

Semahtadır gönlümüz 

Gönümüze dönüşümüz 

- Varlığımıza, birliğimize, dirliğimize hü. 

O derdini anlattı; 

Beni yediniz dedi 

Bitir, diniz 

Rahat bırakın 

Çektirip gidin 

İzlerimi de silin 

Silah uçlarına sürmeyin beni 



Şiiri yazan hepsine acıyor; 

Görülürlerden sonra 

Alışamadık ona 

Küstü 

Gitti sonra 

Sessizlik... 





Şarkı söylemeyin 

Zikir çekmeyin 

Uyuyor dağında 





Bilinç en güzel miras insana 

Bir inç kaç bilinç sormayın 

Yazın şiiri koyun ortasına 

Beni insanla yan yana 

An,ın beni hatırlayın 

Kendime armağan diğer yarım 



Gece yeniden çökecek diye 

Karanlık beklemede 

Elinde sigarası 

Dalgın kafası 

Düşünüyor ve diyor ki; 

Dağlarım yıkılıyor ıssızlıktan 

Susun... 

''04', '. Medeniyete;  Sessiz sakin köşesinde  Düşünürken ne olacak hallerini  Yerine bağırıyor  Seni andık  Sana taptık diyen işsizleri  Koro halin...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":78,"source_url":"https://www.antoloji.com/insana-yazana-ve-tanriya-dair-dil-surcmesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Yoksan Bende Buralarda Durmayacagım', 'sen-yoksan-bende-buralarda-durmayacagim-ali-kalafat-zhqjf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Her gün gibi bu gün de bitti

Sanırım sabah erken kalkmakta yetmiyor 

Senin sebepsiz gitmelerine

Sen gittin belki ama

Sevgim yüzünden cürüm giymiş yüregini 

Kalbime kilitliyorum

Degil bi ömür 

Ebediyen müebbet giyeceksin 

Ve sen olmadan 

Melanet hırkamı naftalinleyip koyacagım

O ihtiyar mazinin çam sandıgına 

Çekip gitmelerine defter tutup

Hayatına çizik çektigin kalemini kıracagım

Ve sen olmadan ben de buralardada durmayacagım

Oysa sen yıldız toplardın hayalimde gökyüzünden

Bense içli içli şiir yazardım seni beklerken

Gökte feryat eden meleklere kulak asmazdım

Sen benim melegimken kim dinlerdi onları ve 

Her an ağlayan kapanmayan yaralarımı

Baglıyorum yeniden yeni dertlerimle

Yazdım bunu da bir yere 

Son olsun bu gitmen 

Bir daha gelme bitti tamam 

Bende asla unutmam 

Her birini ayrı bir yere sayacagım

Ve sen yoksan bende buralarda durmayacagım', 'Her gün gibi bu gün de bitti Sanırım sabah erken kalkmakta yetmiyor  Senin sebepsiz gitmelerine Sen gittin belki ama Sevgim yüzünden cürüm g...', ARRAY['Türk Edebiyatı','Şiir','Ali Kalafat']::text[], 8.5, '{"poet":"Ali Kalafat","poet_slug":"ali-kalafat","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/sen-yoksan-bende-buralarda-durmayacagim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Sevmek İstiyorum', 'seni-sevmek-i-stiyorum-perihan-dosgul-6kcuf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seni sevmek istiyorum

Yıllardır aç bu yürek sevdaya

İsminin  ne önemi var ki...

Bir ben, bir de kalbim bilecek sevdamı..

Kavuşmak istemez bu sevda...

Sadece aşkını özlemek,

Onu düşünmek, hüzünlenmek ister..

Bazende üşüyen yüreğini ısıtmak ister..

Ellerini tutarak değil, yüreğini tutarak

Görmek istemez,

Varlığını hissetmek ister bu kalp...', 'Seni sevmek istiyorum Yıllardır aç bu yürek sevdaya İsminin  ne önemi var ki... Bir ben, bir de kalbim bilecek sevdamı.. Kavuşmak istemez bu...', ARRAY['Türk Edebiyatı','Şiir','Perihan Dosgül']::text[], 8.5, '{"poet":"Perihan Dosgül","poet_slug":"perihan-dosgul","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/seni-sevmek-istiyorum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülüm Ol Diye', 'gulum-ol-diye-cemile-duzgun-qnggc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Şu fani dünyada,garip iklimde

Seni gördüm ışık ışık yol diye

Biçareydim, sevmek yoktu aklımda,

Serçe gönlüm sana kondu dal diye...

Meğer filizlerin küsmüş bahara

Değil gonca,yokmuş yaprağın yara

Belli ki yakmışlar,vermişler kora

Suyunu kesmişler hemen sol diye...

Köklerini sıkan ayrığı yolsam

Çisil çisil yağıp,özüne dolsam

Kızgın kuraklarda hep gölgen olsam

Gülistânım,irem gülüm ol diye...

Nefesimi senin ile bölerdim,

Kem okları,sinem ile elerdim,

Aklındaki gitmeleri silerdim

Bir ömür benimle,bana kal diye...

Say ki hiç açmamış bir açelyayım,

Kokusu sır gibi bir begonyayım,

Coşmanı bekleyen susuz deryayım,

Gönlüm sana hazır,işte dol diye...! 

Cemile Düzgün    10-02-05', 'Şu fani dünyada,garip iklimde Seni gördüm ışık ışık yol diye Biçareydim, sevmek yoktu aklımda, Serçe gönlüm sana kondu dal diye... Meğer fil...', ARRAY['Türk Edebiyatı','Şiir','Cemile Düzgün']::text[], 8.5, '{"poet":"Cemile Düzgün","poet_slug":"cemile-duzgun","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/gulum-ol-diye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acılar Büyütür Umutsuzlukları', 'acilar-buyutur-umutsuzluklari-nurten-tarim-petfn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Acılar büyütür umutsuzlukları

Yaşarken görürsün geleceği

Yürekte kurulur dokuma tezgahları

Duygular renk düşünceler balık ağı

Sırt heybesinde birikir geçmiş

Sevgiyle öpersin dokuyan elleri', 'Acılar büyütür umutsuzlukları Yaşarken görürsün geleceği Yürekte kurulur dokuma tezgahları Duygular renk düşünceler balık ağı Sırt heybesind...', ARRAY['Türk Edebiyatı','Şiir','Nurten Tarım']::text[], 8.5, '{"poet":"Nurten Tarım","poet_slug":"nurten-tarim","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/acilar-buyutur-umutsuzluklari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tuzakmış', 'tuzakmis-cemile-duzgun-rmsev', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sabah şebnemi gibi,

Çöl sıcağında yandım.

Bahar meltemi gibi

Esintilere kandım

Bir bahar şafağına,

Umutlarla uyandım.

Güneşe çılgın aşık,

Ayçiçeğine döndüm...

O güle heves ile

Kelebek olup kondum,

Renkler,şekiller hile,

Bir tuzakmış,aldandım...

Cemile Düzgün', 'Sabah şebnemi gibi, Çöl sıcağında yandım. Bahar meltemi gibi Esintilere kandım Bir bahar şafağına, Umutlarla uyandım. Güneşe çılgın aşık, Ay...', ARRAY['Türk Edebiyatı','Şiir','Cemile Düzgün']::text[], 8.5, '{"poet":"Cemile Düzgün","poet_slug":"cemile-duzgun","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/tuzakmis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mumkun Degil', 'mumkun-degil-tugba-simsek-wvpkk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aldigim nefes ictigim susun! 

Soluksuz yasamam susuz durmam mumkun degil...

Damarlarimdaki kanim tenimdeki canimsin! 

Kansiz yasamam seni uzmem mumkun degil...

Kalbimsin... Kalbime zarar veremem ki! 

Kalbim olmadan yasamam mumkun degil...

Ekmegimsin... Insan kac gun ac kalabilir ki! 

Sensiz kalmam mumkun degil...

Sevgimsin, ruhumsun, askimsin... Bitkisel hayatta kalip,

Sevginsiz, ruhunsuz, askinsiz kalmam mumkun degil...

Sen bensin! Bende senim! 

Sensiz olmam mumkun degil...

Ellerim ellerinin, gozlerim gozlerinin oldu! 

Ellerimisiz, gozlerimsiz yasamam mumkun degil...

19.01.2003  17:53', 'Aldigim nefes ictigim susun!  Soluksuz yasamam susuz durmam mumkun degil... Damarlarimdaki kanim tenimdeki canimsin!  Kansiz yasamam seni uz...', ARRAY['Türk Edebiyatı','Şiir','Tuğba Şimşek']::text[], 8.5, '{"poet":"Tuğba Şimşek","poet_slug":"tugba-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/mumkun-degil-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nedir ki Aşk?', 'nedir-ki-ask-birsen-ates-8p4hi', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'varamadığım farkına 

gelip geçerken yaşam

soğuk gecelerde 

üşümemek mi

onsuz yaşayamamak mı 

düşünmek mi sürekli

uzun gecelerde 

nedir ki aşk 

25.12.2005', 'varamadığım farkına  gelip geçerken yaşam soğuk gecelerde  üşümemek mi onsuz yaşayamamak mı  düşünmek mi sürekli uzun gecelerde  nedir ki aş...', ARRAY['Türk Edebiyatı','Şiir','Birsen Ateş']::text[], 8.5, '{"poet":"Birsen Ateş","poet_slug":"birsen-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/nedir-ki-ask-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anadolum Memleketim Sevdalım', 'anadolum-memleketim-sevdalim-ali-uygun-uiywe', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ANADOLUM MEMLEKETİM SEVDALIM

Anadolu’m, memleketim, sevdalım

Sevdamız yürekten bil, Anadolu

Sana cennet demek haksızlık olur

Yetersiz kalıyor dil Anadolu

Denizleri, ovaları, dağları

Hep bağrına basmış bütün çağları

Sana gıpta eder cennet bağları

Senin cemâline kul Anadolu

Karlar eriyince, buzlar solunca

Akarsular yatağına dolunca

Ağaçlar donanıp gelin olunca

Sevdamız depreşir, bil Anadolu

İstanbul’u görmek bir ömre değer

Büyüler insanı orada her yer

Boğazlar, saraylar, köşkler, camiler

Kültürlere beşik ol Anadolu

Antalya’m var, Akdeniz’in incisi

Bence dünyaların en birincisi

Sana gelir yabancısı, yerlisi

Dünyada en güzel il Anadolu

Şelale diyarı, Manavgat, Düden

Büyülenir kalır oraya giden

Kurşunlu, Karain, Aspendos, Side’n

Tarihe oradan gül Anadolu

Kapadokya “dersin”  uzaydan gelmiş

Orada periler kayayı delmiş

Taşları başına bir şapka giymiş

Dünya hârikası kal Anadolu

Güney Marmara’da Yeşil Bursa var

Tarih, medeniyet orda olmuş yar

Dünyada eşi yok Uludağ kadar

Nişanını benden al Anadolu

Çeşme, Kuşadası, Bodrum, Marmaris,

Her mevsim orada binlerce turist

Mersin, Gâziantep, Adana, Kilis

Her biri bahardan dal  Anadolu

Ölüdeniz’ine  hayran bir dünya

Fethiye, Kaş, Kalkan, Kale bir rüya

Kemer’de girmeden denize, suya

Olimpus’tan ateş al Anadolu

Ordan uzanalım Karadeniz’e

Halaylar tepelim burda diz dize

Samsun var, Trabzon, Giresun, Rize

Horon havaları çal Anadolu

Urfa, Diyarbakır, Siirt, Mardin’den

Dünya tutuşuyor senin derdinden

Bunca yıllık çilelerin ardından

Huzur denizine dal Anadolu

Ankara’m sen şehirlerin başısın

Yüce Ata’mızın mezar taşısın

Bütün bir dünyanın arkadaşısın

Kardeşliğe kucak ver Anadolu

Erzincan, Elazığ, Erzurum nere

Yazmakla sığmıyor kitap, deftere

Palandöken Dağı, Çifte Minâre

Daha neler neler, var Anadolu

Ağrı Dağı, Hasan Dağı, bak Ilgaz

Kartalkaya, Erciyes’e gelmez yaz

Gelin başı gibi her mevsim beyaz

Dört mevsim başında kar Anadolu 

Edirne yurdumun batı kapısı

Selimiye kâinatın yapısı

Verseler de dünyaların tapusu

İstemem başka bir yer Anadolu

Bolu’yu unutma, orda her şey var

Abant, Yedigöller, Gölcük ve dağlar

Orda göğe çıkmış sanki ormanlar

Cenneti oradan sor Anadolu

İzmir, Aydın, Burdur, Muğla, Denizli

Pamukkale’mizde bir cennet gizli

Burada güzeller hep ceylan gözlü

İçimize düştü kor Anadolu

Uşak, Eskişehir, Afyon, Kütahya

Uğramadan olmaz, Mevlana, Konya

Bir araya gelse bütün bir dünya

Bir şehrine gelir, dar Anadolu

Balıkesir, Bandırma’dan, Gönen’den

Demir attım ayrılamam ben senden

Bu canımız burda çıksın bedenden

Beni de sinene sar Anadolu

Saymadığım yerler bana küsmesin

Sitem edip sert rüzgarlar esmesin

Bize kızıp muhabbeti kesmesin

Dünyamız olmasın zar Anadolu

Anadolu’m, Memleketim, Sevdalım

Vefasız güzelden işte bu halım

Beni terkedersen sana vebalım

Sen olasın bana yar Anadolu

			2003

	(Sevdalar Çıkmazı’ndan) 

				Ali Uygun

			Ömer Seyfettin Lisesi

			Edb. Öğr. Gönen', 'ANADOLUM MEMLEKETİM SEVDALIM Anadolu’m, memleketim, sevdalım Sevdamız yürekten bil, Anadolu Sana cennet demek haksızlık olur Yetersiz kalıyo...', ARRAY['Türk Edebiyatı','Şiir','Ali Uygun']::text[], 8.5, '{"poet":"Ali Uygun","poet_slug":"ali-uygun","theme":"Türk Şiiri","is_hero":false,"total_lines":94,"source_url":"https://www.antoloji.com/anadolum-memleketim-sevdalim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dörtlük.6. [Ne kadar değişmişsin]', 'dortluk-6-ne-kadar-degismissin-ercan-akbay-dgxos', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne kadar değişmişsin,ben seni görmeyeli

   O eski sen değilsin,ben seni görmeyeli

   Saçın da başka yel var,elinde başka el var

   Beni çoktan silmişsin,ben seni görmeyeli....

                                       19.1.1996

                                        TRT Arşivindedir.', 'Ne kadar değişmişsin,ben seni görmeyeli    O eski sen değilsin,ben seni görmeyeli    Saçın da başka yel var,elinde başka el var    Beni çokt...', ARRAY['Türk Edebiyatı','Şiir','Ercan Akbay']::text[], 8.5, '{"poet":"Ercan Akbay","poet_slug":"ercan-akbay","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/dortluk-6-ne-kadar-degismissin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayal ettim seni', 'hayal-ettim-seni-tunay-karaca-w1pqh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'dün seni düşündüm! 

hayal ettim seni, seni görmeden! 

seni hissettim, seni kokladım 

sevdim seni, sanki yanımdaymışsın gibi 

görmediğim gözlerinin içi gülerken 

dokunmadığım tenini hissederken 

hiç duymadığım kokunu duyarken 

seni daha çok sevdim, daha çok özledim 

kötürüm olmuş duygularımı 

ayaklandıran sen oldun 

sayende yeniden doğdum 

sen yokken sana aşık oldum', 'dün seni düşündüm!  hayal ettim seni, seni görmeden!  seni hissettim, seni kokladım  sevdim seni, sanki yanımdaymışsın gibi  görmediğim gözl...', ARRAY['Türk Edebiyatı','Şiir','Tunay Karaca']::text[], 8.5, '{"poet":"Tunay Karaca","poet_slug":"tunay-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hayal-ettim-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Hayat Vardır...', 'bir-hayat-vardir-demir-erem-vkpbm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ağzıma bir yün yumağı tıkanmış,

Nefes alışım tesadüf,

Kulağıma bir ezgi mırıldanmış uyurken,

Dolanmış dilime sürüp gider öylece,

Sabah olmuş,

Bulutlar arasından sıyrılmış 

Bir tutam ışık aydınlatır odamı.

Bense,

Gördüğüm rüyanın etkisinde

Herkes yabancı, herkes yürürken üstüme

Karabasan sarmış bedenimi,

Çığlığım duyulmaz sanmışım.

Konuşmalar yabancı,

Derdimi anlatamaz saymışım,

Doğrulmuş yatağıma

Yanağımdan süzülenleri toplarken avucumda,

Yokluğumu tadarım.

Çabam,

Uzanmaktır başucumda duran sigaraya,

Aldığım ilk duman

Yaşadığımı kanıtlamaktır kendime.

Bir tanrı vardır,

Varlığını unutup

Kendimi yalnız saydığım,

Bir gün vardır önümde,

Bir şans vardır,

Af dilemek için tüm hatalarımdan,

Biri vardır bulamadığım,

Yada değerini bilemediğim,

Bir dünya vardır kendimi kanıtlayacağım,

Bir geçmişim vardır,

Arada bir hatırımı soran

Bir hayat vardır önümde,

Ardıma bakmadan yaşayacağım…', 'Ağzıma bir yün yumağı tıkanmış, Nefes alışım tesadüf, Kulağıma bir ezgi mırıldanmış uyurken, Dolanmış dilime sürüp gider öylece, Sabah olmuş...', ARRAY['Türk Edebiyatı','Şiir','Demir Erem']::text[], 8.5, '{"poet":"Demir Erem","poet_slug":"demir-erem","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/bir-hayat-vardir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen cansın', 'sen-cansin-tunay-karaca-x3bvz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ne olur gel bak şu halime! 

Ağlıyorum! ... 

Gözlerimden yaş değil sen süzülüyorsun 

Her damla bir hançer gibi yarıyor kalbimi 

Kalbim kanıyor! 

Kan değil kalbimden sen akıyorsun! 

Çırpınıyorum sensizlikten! 

İsmin çığlığım oluyor. 

Herkez duyup geliyor 

İçlerinde bir tek sen yoksun! 

Daha çok acıtıyor kalbimi yokluğun 

Ölüyorum yardım edin diyorum 

Hepsi uğraşıyor, olmuyor! 

Sensizlik canımı alıyor', 'Ne olur gel bak şu halime!  Ağlıyorum! ...  Gözlerimden yaş değil sen süzülüyorsun  Her damla bir hançer gibi yarıyor kalbimi  Kalbim kanıyo...', ARRAY['Türk Edebiyatı','Şiir','Tunay Karaca']::text[], 8.5, '{"poet":"Tunay Karaca","poet_slug":"tunay-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sen-cansin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karanlık Aydınlar!', 'karanlik-aydinlar-tunay-karaca-1teie', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'düşünebilen, idrak edebilen, iyiden kötüyü ayırabilen tek canlıdır insan oğlu. Kimileri kendine yol olarak seçer karanlığı ve kaybolup gider karanlığın için de, kimileri de eline mum alıp aydınlatmaya çalışır etrafını, elinde ki mumla başka mum tutacak insanlar ararlar, sadece çevreyi değil dünyayı aydınlatabilmek için, kimileri de o aydınlığa hiç bir katkısı olmadan mumsuz faydalanır o aydınlığın için de, hiç istemezler mum tutup aydınlatmayı, ama bu aydınlığı ben yarattım edasıyla dolanırlar dünya da. onlar riyakardır, fesattır, nifaktır onlar aydınlığa. aydınlığından nasiplendikleri mumun ışığına ihanet eder onlar, kendileri ışık saçmadığı halde, ışık saçanları aşağılarlar, karanlığın bekçilerine hizmet ederler sinsice. aslında karanlığı var edenler onlardır. aydınlığı öğretecekleri yerde karanlığa saplarlar karanlıkta kaybolmuş olanları. bin mum sahibini de lekeler o mumsuz aydın! ve kurunun yanında yanar yeşil aydınlıklar.', 'düşünebilen, idrak edebilen, iyiden kötüyü ayırabilen tek canlıdır insan oğlu. Kimileri kendine yol olarak seçer karanlığı ve kaybolup gider...', ARRAY['Türk Edebiyatı','Şiir','Tunay Karaca']::text[], 8.5, '{"poet":"Tunay Karaca","poet_slug":"tunay-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/karanlik-aydinlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Taşı Toprağı Altın İstanbul', 'tasi-topragi-altin-i-stanbul-emre-saricicek-b4hoj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ey, güzel memleketim.

Taşı toprağı altın, istanbul

Niceleri geldi geçti üzerinden.

Sen hala dimdik ayaktasın.

En güzel yeşilin, betonla doldu.

Masmavi denizin, bataklık oldu.

Sana zulm etmeye, kimin hakkı varki.

Bir ağaç yıkıldı, bir gece kondu.

Ceketini sırtlayan, düştü peşine.

Merhamet dileyen, vurdu dibine.

Çomağı elleyen, soktu gözüne.

Sen hala dimdik ayaktasın.

Ey güzel memleketim.

Taşı toprağı altın istanbul.

Daha neler yaşayıp göreceksin.

Bakalım ne kadar sabredeceksin.', 'Ey, güzel memleketim. Taşı toprağı altın, istanbul Niceleri geldi geçti üzerinden. Sen hala dimdik ayaktasın. En güzel yeşilin, betonla dold...', ARRAY['Türk Edebiyatı','Şiir','Emre Sarıçiçek']::text[], 8.5, '{"poet":"Emre Sarıçiçek","poet_slug":"emre-saricicek","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/tasi-topragi-altin-istanbul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir çift Göz', 'bir-cift-goz-mustafa-benkli-jcmet', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'mefûlü me/fâîlü

Rabbim kulu halketmış; 

İdrâk ile var etmış! ..

Vermiş ona hür bir fikr,

Etsin dua, hem, çok şükr! ..

Ersin O''na hakkıyla,

''AŞK''ın ana fikriyle! ..

Mutlak O''na aşktır AŞK! ..

Her aşk O''nadır müştak! ..

Bizden sadır olmuş aşk

Hakk''tan bize istihkak! ..

Benden, size, ey dostlar; 

Destûr ile bir not var:

Sıtkım ile tam içten,

Kalbim size ermişken

İkrar edeyim birden

Bir aşk hikâyem dilden:

Hemhâl olan ol nesne

Çarpmış idi her neyse? 

Birden bire hem şansta

oldum ona ben hasta! ..

Çarpıp çalarak sanki,

Benden alarak kalbi; 

İlk demde onun oldum,

Şoktan ise kurtuldum! ..

İlk aşk bana doktormuş; 

Rabbim bana hasr etmiş! ..

Bu aşk benim ilk aşkım

Heyhât! Ve de son aşkım! ..

Hem, aşk hala sürmekte,

Hakk''tan; onu bilmekle''..

Arzdan yana ruhsatmış; 

Ondan bana can katmış''..

Hikmet gibi gelmişti; 

Kalbim yola girmişti! ..

Doktor diyerek verdim; 

Oldum ona tav kendim! ..

Ben odda donup kaldım! ..

Öldüm ve de mest oldum! ...

Yağmur gibi bir rahmet

Buldum onu; pür dikkat! ..

Rahmet ki, ne rahmetmiş! ..

Hikmet ona râm etmiş! ..

Temmuz sıcağındayken

Kâm aldım o rahmetten! ..

Sırsıklam olup birden,

Sarsıp, geri döndürten

Aşkım beni çarptıkca; 

Sindim ona baktıkca! ..

Verdim ona bir yordam! ..

İrkildim o sırsıklam

Mahmur, masum haşyetten,

Mahküm ve de teslim''en; 

Aldım oradan ikrar; 

Verdim ona istikrar...

Aşkın özü AŞK bulmak:

Ma''bûd''da karar kılmak! ..

Son söz olarak tarzım:

Haddim mi benim arzım? 

Öz: Kaş ile göz derler

Hakk''tan; ulu dervişler! ..

Aldım bir ateş iksir,

Oldum ona ben yessir! ..

İsmen demedim baştan; 

Bahseyleyeyim ondan:

Gönlümde, o doktor; söz! ..

Remzen, adı: ''Bir Çift Göz''! ..', 'mefûlü me/fâîlü Rabbim kulu halketmış;  İdrâk ile var etmış! .. Vermiş ona hür bir fikr, Etsin dua, hem, çok şükr! .. Ersin O''na hakkıyla, ''...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Benkli']::text[], 8.5, '{"poet":"Mustafa Benkli","poet_slug":"mustafa-benkli","theme":"Türk Şiiri","is_hero":false,"total_lines":67,"source_url":"https://www.antoloji.com/bir-cift-goz-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SoN SaLıNıM', 'son-salinim-mine-ozdemirtas-3hifm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'son bir salınım işte / yer çekimine inat

hani umutla dönermiş ya dünya

en eskimiş 

yara izinden 

dışarı 

fışkırırken mağma

yine de

basmak zorunda kalırız ya

yer kabuğuna

hani umutla dönermiş ya dünya

en güçlü sevgileri

sürükleyen rüzgara

hangimiz

delice meydan okuyup

ve güvenerek

uçurtmamızı

teslim etmedik ki bir ara

işte 

öyle bir şey

son bir salınım bu / yer çekimine inat

aynadaki tılsım aramızda

göle salınmış maya 

bir masal düşü

ama

ya.......... tutarsa...! 

25/12/2005', 'son bir salınım işte / yer çekimine inat hani umutla dönermiş ya dünya en eskimiş  yara izinden  dışarı  fışkırırken mağma yine de basmak zo...', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/son-salinim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canım dostlarım..nette beni sevenlere.', 'canim-dostlarim-nette-beni-sevenlere-ercan-akbay-lsu3t', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sizlerle paylaştım,safi sözümü

   Sizlere açtım hep,gönül gözümü

   Bir kıvılcım yaktı,yürek közümü

   Sizlerle mutluyum,canım dostlarım...

   Belki çok uzaktan,belki yakından

   Ses verdiniz,sesime benim

   Süzüldük bal gibi,şiir şarkıdan

   Sizlerle mutluyum,canım dostlarım...

   Sizlerle var ettim,nice şiiri

   Sizlerle yok ettim,derdi,kederi

   Okudukça anın,her zaman beni

   Sizlerle mutluyum,canım dostlarım....

                                                 25.ARALIK.2005  İST.', 'Sizlerle paylaştım,safi sözümü    Sizlere açtım hep,gönül gözümü    Bir kıvılcım yaktı,yürek közümü    Sizlerle mutluyum,canım dostlarım... ...', ARRAY['Türk Edebiyatı','Şiir','Ercan Akbay']::text[], 8.5, '{"poet":"Ercan Akbay","poet_slug":"ercan-akbay","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/canim-dostlarim-nette-beni-sevenlere-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Yeniden', 'ask-yeniden-birsen-ates-mf5e2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'aşk,

yeniden

takıldın dilime.

kıyılarıma

sessiz sedasız geliverdin 

korkak küçük bir kızın

gözleriydim.

severken bilseydin 

kaybetmeyi

savaşım,

gölgemle 

dört duvar yalnızlığım

ağlayan gecelerimde

susamış topraklarım

ey aşk yeniden

takıldın gamzelerime

25.12.2005', 'aşk, yeniden takıldın dilime. kıyılarıma sessiz sedasız geliverdin  korkak küçük bir kızın gözleriydim. severken bilseydin  kaybetmeyi savaş...', ARRAY['Türk Edebiyatı','Şiir','Birsen Ateş']::text[], 8.5, '{"poet":"Birsen Ateş","poet_slug":"birsen-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ask-yeniden-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Turuncu kokulu resmin', 'turuncu-kokulu-resmin-elazigli-mustafa-kaya-cqbie', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'seninle konuşmak,

ve tüm konuşmalarımız,

çiçek açtı.

dört mevsim yaşadık

günlerdir

ve,

ay gibi doğdun 

acılarımın siyahına.

genzimi titretti,

denizin kokusundan çok

ayrılık saatleri.

çegincelerin

sadeliğin

kusursuz savaşın

fesleğen kokulu bakışın

evet ne varsa hepsi

o gülen resmin

hayatımın tek sevinci.

bırakıp gittin

karanlıkta kaldım

alışamadım gidişine

gök grileşti

deniz öfkelendi

şehir üşüdü

martılar küstü

rıhtımlar sessiz

ve,

geceler yıldızsız.

güneşin doğuşunu özlüyorum

seni düşünüyorum..

hani..

bir yana atmıştık uykuları

sabahları bulan fısıltılarımız

murada ermiş hallerimizle

ıstıraplarımız geçti.

ve gözlerimizin ışığı

bir göl kadar yeşildi.

ve,

gezindiğimiz her yerde

geçmişi unutmadık

dalgalarla boğuşan kuşlara

dönmüştük.

kahve gözlerine gelirdi

martılar

içimizi ısıtırdı

bir sahil bahçesi

ve,

huzur verirdi 

sesler arasında 

en güzeli Süleymaniye..

çaresiz seni bekliyeceğim

ufukta seni göreceğim

resmini alıp elime

o ağacın altına geleceğim

ve şimdi bu şehirde,

turuncu kokulu resmini 

maviye çizeceğim..

Mustafa kaya

26.12.2005 / Beykoz

www.mustafakaya.net', 'seninle konuşmak, ve tüm konuşmalarımız, çiçek açtı. dört mevsim yaşadık günlerdir ve, ay gibi doğdun  acılarımın siyahına. genzimi titretti...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":60,"source_url":"https://www.antoloji.com/turuncu-kokulu-resmin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sessizce çöllere doğar benim yalnızlığım', 'sessizce-collere-dogar-benim-yalnizligim-elazigli-mustafa-kaya-xawpw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'koşdum…koşdum..

tüm sahili.

kalabalığa,

çehremi gösterdim

kirlerimi yıkamaya

durdum 

yağmur boyunca..

ihanetimin tesellisi

mutsuz ruhuma

bir şimşeğin öfkesi.

ölüm dakikası

ömrüm gitti..

yaralarımı dağlamaya,

sisli ve kör bir ışık

bir sahte gayret

düştü.

zamanı mermere kaydettim.

merak edilmeye değmez

zarar gecelerim.

ve,

yalnızlığım,

solgun bir hastalık gibi 

sessizce çöllere doğan

ay gibi..

Mustafa kaya

26.12.2005 / kanlıca

www.mustafakaya.net', 'koşdum…koşdum.. tüm sahili. kalabalığa, çehremi gösterdim kirlerimi yıkamaya durdum  yağmur boyunca.. ihanetimin tesellisi mutsuz ruhuma bir...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/sessizce-collere-dogar-benim-yalnizligim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanardöner Yansı', 'yanardoner-yansi-nurdan-unsal-r7etx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'yanlar tutulu

yanardöner yansı

cezayı beklersen/çekersin

içinde/gizli cellat

elinde kamçı

bilinç bulur

bulunç ele verir

savaş kendinle

yitirdiğinde 

kendinle yetin

Sezar''ın çıkarı(mı)   ayrı değil

seninkinden/benimkinden

yazgı payı aynı

olabilirlik kestirilir

yarış yolu açık

baktığın y/ana dönersin

yanılgı payı ölçülü

yürek sağlamsa

çekilir kum sancısı

k/ayıp değil inlemek

acıma kendine

yılgıya ömür biçili

doğaçlama

konuş kendinle

görene

bir an bile yeter

bul gerisini içinde

dilinden anlayan

lal

bekleme boşuna

tanıklıktan kaçma

yansır 

gözünü kapama

yanlar tutulu

yanardöner yansı(ma)

25.12.2005', 'yanlar tutulu yanardöner yansı cezayı beklersen/çekersin içinde/gizli cellat elinde kamçı bilinç bulur bulunç ele verir savaş kendinle yitir...', ARRAY['Türk Edebiyatı','Şiir','Nurdan Ünsal']::text[], 8.5, '{"poet":"Nurdan Ünsal","poet_slug":"nurdan-unsal","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/yanardoner-yansi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çay İçme Vakitleri', 'cay-i-cme-vakitleri-hatice-bediroglu-qa675', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İnce belli cam bardakta

Çay içme vakitleri 

Dinleme anım sanki içimi 

Camlar açılmışta 

Sevdalı yaz rüzgârı dolmuş odaya 

Okşayarak ısıtmış bedenimi güneş

Katlıyor kendini mutluluk içimde

Küsüyor acılarım bir bir... 

Tadı hoş bir rahatlama sarıyor benliğimi 

Taşıyor denetimsiz sevinçler gözlerimden 

Bir martı ile dalıyorum yarenliğe 

Pamuk gibi bulutlar da seyahatteyim 

'' Düş Kuruyor Gece '' adlı kitabımdan - Ocak 2008 - 

www.haticebediroglu.net', 'İnce belli cam bardakta Çay içme vakitleri  Dinleme anım sanki içimi  Camlar açılmışta  Sevdalı yaz rüzgârı dolmuş odaya  Okşayarak ısıtmış ...', ARRAY['Türk Edebiyatı','Şiir','Hatice Bediroğlu']::text[], 8.5, '{"poet":"Hatice Bediroğlu","poet_slug":"hatice-bediroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/cay-icme-vakitleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda', 'sevda-sevim-yakici-pi5hu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sevda meşakkattir, sevda çiledir,

Sevda gürül gürül, yanabilmektir

Bu dünyada pişmek, sabır iledir

Sevda gözyaşıyla, yunabilmektir...

Sevda ile yanmak, herkese nasip

Olmaz kısmetsize, olmaz münasip

Sevda ocağında, olsa da hasib (*)       

Sevda az nimete, kanabilmektir…

Vuslatı beklenen yar elin olsa

Gözden kıskanılan tek gülün solsa

Hasret sızısıyla gözlerin dolsa

Sevda  derdi sabra banabilmektir

Zor olan kazanmak, kaybetmek değil,

Yapmak bir gönülü, zay etmek değil,

Kula eziyeti, huy etmek değil,

Sevda hoş görüyle, anabilmektir…

Mahpus olsa bile, bu can bedende,

Mukaddes düşleri, gaye edende,

Ruhlar bayram eder, aşka gidende,

Sevda canı O’na, sunabilmektir…



Gerisi Laf-ı güzaf diyorum 

yani sadece boş laf.', 'Sevda meşakkattir, sevda çiledir, Sevda gürül gürül, yanabilmektir Bu dünyada pişmek, sabır iledir Sevda gözyaşıyla, yunabilmektir... Sevda ...', ARRAY['Türk Edebiyatı','Şiir','Sevim Yakıcı']::text[], 8.5, '{"poet":"Sevim Yakıcı","poet_slug":"sevim-yakici","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sevda-130-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Şehirden Giderken', 'bu-sehirden-giderken-ufuk-bayraktar-bw4oh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '1

bu yürek hiç durmaz mı

bu yürek! 

nereden çıktı şimdi

bu giderayak sevmek? 



2

ben olmadan dolaşacaksın sokaklarda

öğle vakti çayını içeceksin ben olmadan.

gülecek yine o  hüzünlü gözlerin

inci dişlerin görünecek dudaklarının arasından

ben olmadan...

ben gittim sanacağım kendimi

aslında hep seninle olacağım.

gurbet ağır gelecek sana, bilirim

her yerini ezbere bildiğim o şehirde

ben de gurbette olacağım.

3

korkacaksın karanlıktan belki

bir geceyarısı arayacaksın

beni unutacaksın ya da; 

korkacağım seni bırakıp gitmelerden.', '1 bu yürek hiç durmaz mı bu yürek!  nereden çıktı şimdi bu giderayak sevmek?  2 ben olmadan dolaşacaksın sokaklarda öğle vakti çayını içecek...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Bayraktar']::text[], 8.5, '{"poet":"Ufuk Bayraktar","poet_slug":"ufuk-bayraktar","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bu-sehirden-giderken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acaba', 'acaba-cem-cagman-p16ut', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'acaba 

sen ne biçim sorusun

senden Allah korusun

yedin bitirdin beni

perişan ettin ömrümü

bir bilebilsem fikrini

vereceğim hükmümü

kaç gece sabaha dek

uyku tumadı gözüm

doğrumuyum yanlışmı

gülmüyor artık yüzüm', 'acaba  sen ne biçim sorusun senden Allah korusun yedin bitirdin beni perişan ettin ömrümü bir bilebilsem fikrini vereceğim hükmümü kaç gece ...', ARRAY['Türk Edebiyatı','Şiir','Cem Çağman']::text[], 8.5, '{"poet":"Cem Çağman","poet_slug":"cem-cagman","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/acaba-54-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmuyormuş..', 'olmuyormus-huseyin-ozcan-tmzev', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ben Allah''tan hiçbir şeyi, 

iki defa istememiştim. 

ilk kez defalarca seni istedim. 

bir şeyi çok istersen olmuyormuş 

çok doğru...... 

hata etmişim…………. 

13.08.1987 

hatıralar kabus gibi geldi yine…. 

üstelik en güzel günümde misafir……', 'ben Allah''tan hiçbir şeyi,  iki defa istememiştim.  ilk kez defalarca seni istedim.  bir şeyi çok istersen olmuyormuş  çok doğru......  hata...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Özcan']::text[], 8.5, '{"poet":"Hüseyin Özcan","poet_slug":"huseyin-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/olmuyormus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ba-na--NE', 'ba-na-ne-fatma-caglayan-vij29', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hiç merak etmedim seni 

Ne yersin ne içersin diye 

Yollarına da bakmadım 

Hiç işim olmaz 

Bana ne 

Ufuklara da bakmadım 

Dalmadım dakikalarca 

Acaba nerde diye de sormadım 

Hiç işim olmaz 

Bana ne 

Sana hiç kızmadım da 

Bulut olup yağmadım da 

Şimşekler de çakmadım 

Hiç işim olmaz 

Bana ne 

Uykusuz da kalmadım 

Ağlamadım da sessizce 

Dua da etmedim senin için 

Hiç işim olmaz 

Bana ne 

Ba-na--Ne

24 Aralık 2005', 'Hiç merak etmedim seni  Ne yersin ne içersin diye  Yollarına da bakmadım  Hiç işim olmaz  Bana ne  Ufuklara da bakmadım  Dalmadım dakikalarc...', ARRAY['Türk Edebiyatı','Şiir','Fatma Caglayan']::text[], 8.5, '{"poet":"Fatma Caglayan","poet_slug":"fatma-caglayan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/ba-na-ne-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'A-kadınlar hakkında!', 'a-kadinlar-hakkinda-mikdat-bal-xzwtk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kadınlar Hakkında!

Kadınlar hakkında yazıp çizmeyin

Beşikten mezara hocamız kadın

Dertler had safhada sizde üzmeyin

Cennete vesile, yücemiz kadın!

Kadın bir annedir, doğuran odur

Evladı büyütüp yoğuran odur

En tatlı lisanla çağıran odur

Hayata bağlayan gücümüz kadın

Hak hukukta farklı yol tutulmasın

Onların hakları unutulmasın

Sloganlar ile uyutulmasın

Gönül sultanımız tacımız kadın!

Yüce peygamberden bize vasiyet

Ezilmesin dedi zarif cinsiyet

Allah’ın emriyle olur ünsiyet 

En tatlı kavlimiz hecemiz kadın

Hakareti dilde hafif bularak

Bazı jargonları örnek alarak

Böyle yapmamalı insan olarak

Anamız, teyzemiz, bacımız kadın

Mikdadi aksaklık her cinste vardır

Onlar bize şeref, namustur ardır

Kız, gelin halamız, hanımdır yârdir

Sevgimiz, derdimiz acımız kadın

Şair Mikdat Bal', 'Kadınlar Hakkında! Kadınlar hakkında yazıp çizmeyin Beşikten mezara hocamız kadın Dertler had safhada sizde üzmeyin Cennete vesile, yücemiz ...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/kadinlar-hakkinda-yazip-cizmeyin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sakın deme ozanım', 'sakin-deme-ozanim-mikdat-bal-a2uo2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Diyorsan ki sağcıyım

Sağa ayıp olmaz mı? 

Yağcıyım diyeceksen

Yağa ayıp olmaz mı? 

Terstir her ne edersen

Sen böyle yan gidersen

Kalkıp çağdaşım dersen

Çağa ayıp olmaz mı? 

Yoldan sapan mı desem

Vahşi yaban mı desem

Dağda çoban mı desem

Dağa ayıp olmaz mı? 

Sakın deme ozanım

Çünkü ben de yazanım

Eğer dersen sazanım

Ağa ayıp olmaz mı? 

Ne var ne vereceksin

Daha çok göreceksin

Çorap mı öreceksin

Tığa ayıp olmaz mı? 

Örüyormuş tığ gibi

Duruyormuş dağ gibi

Büyüyormuş çığ gibi

Çığa ayıp olmaz mı? 

Söz dinleyip de alsan

Ne korkunçsun bir bilsen

Bağda korkuluk olsan

Bağa ayıp olmaz mı? 

Mikdat der kirlenirsen

Kalkıp kibirlenirsen

Yerde böbürlenirsen

Göğe ayıp olmaz mı?', 'Diyorsan ki sağcıyım Sağa ayıp olmaz mı?  Yağcıyım diyeceksen Yağa ayıp olmaz mı?  Terstir her ne edersen Sen böyle yan gidersen Kalkıp çağd...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/sakin-deme-ozanim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayır bana canım deme can deme', 'hayir-bana-canim-deme-can-deme-mikdat-bal-1xam8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hayır bana canım deme can deme

Ruhum havalarda, uçmasın gönül

Ateşlerde benim için yan deme

Bu aşk cehennemi açmasın gönül

Selam verdin artık geç git doluyum

Bir yârim var yanlız onun gülüyüm

Gönül bahçem viran oldu ölüyüm

Bu yaşımda bana saçmasın gönül

Yeter gayrı nedir senden çektiğim

Bu mevsimde mahsül vermez ektiğim

Sözlerine bu son olsun baktığım

Bu gaflet fazlaya kaçmasın gönül

Mikdat’ım dertliyim gözlerim nemli

Burada ağlayış değil önemli

Ağlatıp da kastın beni elemli

Lime lime edip biçmesin gönül', 'Hayır bana canım deme can deme Ruhum havalarda, uçmasın gönül Ateşlerde benim için yan deme Bu aşk cehennemi açmasın gönül Selam verdin artı...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hayir-bana-canim-deme-can-deme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalancı', 'yalanci-mikdat-bal-pxu50', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '...........

Güdüyordu köyün koyunlarını

Her sabah koyuna giderdi çoban

Sayalım marifet oyunlarını

Daha neler neler ederdi çoban

Çayırlar yakındı mesafe kısa

Davarı önünde elinde asa

Görenler sanırdı hazreti Musa

Yorulmadan koyun güderdi çoban

Her taraf yeşillik her yer çayırdı

Davar otlanırken kendi uyurdu

Bir terslik olmadı Allah kayırdı

Uyku çuvalından beterdi çoban

Bir gün düşündü ki eğlenmek gerek

Dalga geçmeliyim mizah ederek

Kurt saldırdı, imdat, imdat diyerek

Bağırıp çağırıp öterdi çoban

Köylüler duyunca koşup da geldi

Çoban görür görmez, sırıttı güldü

Köylüsü çobanı yalancı bildi

Allah’ın cezası  kederdi çoban

Yine tekrarladı yine yalanmış

Ücüncü seferi gerçek olanmış

Artık kendi etti kendi bulanmış

Kurtlara bir öğün yeterdi çoban', '........... Güdüyordu köyün koyunlarını Her sabah koyuna giderdi çoban Sayalım marifet oyunlarını Daha neler neler ederdi çoban Çayırlar yak...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yalanci-45-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Ölüm''ü Öldürmüşler*', 'olum-u-oldurmusler-arif-baltaci-j6f9g', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dün gece gördüm yolda 

Ölüm''ü öldürmüşler 

Karlı bir İstanbul akşamında

İki köpek eniği 

Koyun koyuna verip

Ölüm''le baş etmişler…

Şehrin sahipli kaldırımlarında

Sahipsiz çocuklar

El ele vererek 

Yağan kara gülmüşler

Dün gece gördüm işte 

Ölüm''ü öldürmüşler... 

İki yaşlı karı-koca

Cenazedeymişler

Biri ölü, biri sağ

Kabristana girmişler

Dün yine gördüm orda 

Ölüm''ü öldürmüşler…

Duaya açılmış evliyanın elleri

Vuslata ulaşmak için

Ard arda dizilmişler

Musallanın sürmek için 

Bir namazlık saltanatını

Büyük uğraş vermişler

Dün cenazendeydim baba

Ölüm''ü öldürmüşler…

26.12.2005 

Z.Kamil / İstanbul

Saat: 00:56', 'Dün gece gördüm yolda  Ölüm''ü öldürmüşler  Karlı bir İstanbul akşamında İki köpek eniği  Koyun koyuna verip Ölüm''le baş etmişler… Şehrin sah...', ARRAY['Türk Edebiyatı','Şiir','Arif Baltacı']::text[], 8.5, '{"poet":"Arif Baltacı","poet_slug":"arif-baltaci","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/olum-u-oldurmusler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hergün... Yine... Yeniden...', 'hergun-yine-yeniden-burhanettin-akdag-04e59', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İşte Sevgi, İşte Mavi 

Söyle gülüm, sence hangisi? 

Belki de her ikisi. Ne dersin? 

Sevgiyse eğer, 

Gel sevginin sonsuzluk vadisine

Çekinmeden gir, geç otur makamına 

Pembeler de hazırlanıp dizildiler sıra sıra 

Bak, bekliyor hepsi 

Sabırsızlar gönlüne akacak sefere 

Koşarak gel, 

Bekletme duygu kervanını. 

Sana, 

Dudağımdan sunduğum goncalarla birlikte 

Gönül ışıklarım da yağacak lapa lapa 

Okşayacak tenini hafifçe 

Umut meltemini üflerken kalbine 

Harelenerek dolanacak beline dans eden hayaller 

Coşacak bir baştan öbür başa sevdam 

Sımsıkı saracak hasretini. 

Maviyse eğer, 

Semanın ufku yetmeyecek uçmalara 

Gökyüzünün karanlığı delinirken 

Okyanusun deli dalgaları yetersiz kalıp 

Köpürecek hırsından, anlatamadığı için seni

Ağlayıp patlayacak kayalara. 

Dağların karlı zirveleri de yetmeyecek 

Öyle haykıramayacak ki sevdamı 

Hırsından kar olup yağacak

Yazın sıcağında, buram buram zülfüne 

Ilık sabah rüzgarları 

Kasırgaya dönecek getiremediği için sesini 

Sen bile, 

Sen olduğunu unutacak 

Şaşıracaksın doğanın buruk gözyaşlarına. 

Bakışlarının sabırsız gölgelerine sineceğim 

Masmavi akacağım beklentilerine 

Yeniden doğarken hayaline, 

Sevdayı giyinip geleceğim sana 

Mavinin berrak huzuru yayılırken ruhuna

Gönlümün asi zirvelerinde ışıldayacaksın 

Tutkularını,

Pervasızca haykıracaksın hançerenden 

Masmavi gülecek yüreğin,

Ağlayan gözlerimde.

. 

Ve sonunda sen, 

Maviye boyayacaksın sevdamı 

Sevgiyi yeşerteceksin umut yarınlarında 

Kızıl güller saçılacak heyecanlarıma 

Sevginde harlanırken, alevlenecek aşkım 

Geceler aydınlanacak hayalinle 

Sakinleşecek yüreğim, gün boyu seyrederken

Birer birer savulurken korkular 

Yıldızlar göz kırpacaklar semadan 

Her seherde çiçek olup açacaksın kalbime 

Şen gülüşünle pembeleşecek tan yeri. 

Mavi ışık gibi yağacaksın yarınlarıma, 

Özlenen şafaklarda, sabırla, hiç vazgeçmeden. 

Her gün,  Yine,  Yeniden… 

(Sevdamın Sloganıdır Bu Üç Kelime) 

(25.12.2005)', 'İşte Sevgi, İşte Mavi  Söyle gülüm, sence hangisi?  Belki de her ikisi. Ne dersin?  Sevgiyse eğer,  Gel sevginin sonsuzluk vadisine Çekinmed...', ARRAY['Türk Edebiyatı','Şiir','Burhanettin Akdağ']::text[], 8.5, '{"poet":"Burhanettin Akdağ","poet_slug":"burhanettin-akdag","theme":"Türk Şiiri","is_hero":false,"total_lines":61,"source_url":"https://www.antoloji.com/hergun-yine-yeniden-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayatı Tersten Yaşama Sanatı', 'hayati-tersten-yasama-sanati-mehmet-halil-q871s', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İnsandan çok hayvanlara güvenen

Ters akıtan coşkun suları.

Hazreti İsmail’in kimliğine bürünen

Hazreti kulların, kurbanları.

Benim ülkemin insanları.

Esirlerin, özgürler için çarpıştığı

İnsanların kurşunlara koştuğu

Kurşunların, sonsuz sultanlığı

Tembellerin rahatlığı ve mutluluğu

Çalışanların ise sürekli sınandığı

Çukur ayna gibi beyinlerinde

Alt-üst olmuş fizik kuralları

Benim ülkemin insanları.

Zenginleri barıştıkça

Fakirlerin dalaştığı….

Sermayenin birleştikçe,

İşçilerin ayrıştığı…

Ve herkesin kendi aklına inandığı…

Ve ezberlenmiş kendi doğruları ile

Kendilerini, 

dünyanın ekseni sandıkları

Benim ülkemin insanları.

Cismini yakıp, 

ismini bayrak yaptığımız

tembellerin zenginlikte,

Çalışanların açlıkta buluştuğu,

Başkası meyvesini toplarken

Gölgesinde yattığımız

Zengin kaynakları, 

Nadasa bırakılmış toprakları ile

Övündüğümüz güzel vatanımız

Seçmiş, kurtarıcı diye yılanları

Benim ülkemin insanları.

Üstünde bir bayrak olsun yeter

İsterse olmasın yorganı

Şükretmesini bilir… eğer,

Ekranda gösterirsen

Kendinden daha açları.

Ve yine ondan toplarsın,

Savaş mangalarına,

Silah tüccarlarına,

Batan şirketlere bağışları…

Bununla mutlu olur,

Benim ülkemin insanları.

Enkazlar altından fırlayıp

Bir ayağını cephede bırakıp

Yabancı uçakları üstünde alkışlayıp

Altıncı filoları, sevinçle kucaklayıp

IMF, ABD ve AB ye yalvarıp…

Bir milli maça bağlar umutları

Bir gol atınca patlar avuçları

Yırtılır gırtlakları…

benim ülkemin insanları.

Kutlar o geceyi

İçki şişeleri 

ve ucuz fahişeler arasında…

Düşünmez ailesi ne durumda.

Kendi kaç gol yedi…

Hiç gelmez aklına

Bir gol atınca patlar avuçları

Yırtılır gırtlakları…

Kurtarır namusu

Benim ülkemin insanları.', 'İnsandan çok hayvanlara güvenen Ters akıtan coşkun suları. Hazreti İsmail’in kimliğine bürünen Hazreti kulların, kurbanları. Benim ülkemin i...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Halil']::text[], 8.5, '{"poet":"Mehmet Halil","poet_slug":"mehmet-halil","theme":"Türk Şiiri","is_hero":false,"total_lines":63,"source_url":"https://www.antoloji.com/hayati-tersten-yasama-sanati-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın', 'askin-gokhan-oflazoglu-f3r6d', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevdiğinin yüreğine,

düşüncesine kaçarsın,

terkettiğin kendin, orda

biçare. Üzülme boşuna,

insana kendisi hediye 

edilmez. Ona kırgınlığınla

uyanır da anlarsın, geri

verilir aşkın, işte bu hediye.

26/12/2005', 'Sevdiğinin yüreğine, düşüncesine kaçarsın, terkettiğin kendin, orda biçare. Üzülme boşuna, insana kendisi hediye  edilmez. Ona kırgınlığınla...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Oflazoğlu']::text[], 8.5, '{"poet":"Gökhan Oflazoğlu","poet_slug":"gokhan-oflazoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/askin-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cızlavet...cız etmeler...', 'cizlavet-ciz-etmeler-zafer-zengin-etnika-jk8rv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '.

yağmur anlattı; 

küçüktüler

akıllarında öğrenmek varken

uzun yollar ardınca

suyuma buladım topraklarını

ıslattım saçlarını

bir parça yamalı elbiseleriyle

serçe kadar kaldılar karşımda

gülen yüzleriyle

küfür ediyorlardı

çamurda bıraktıkları

naylon giyeceklerine

cızlavet

hem siyah

hem lacivert

alabros saçları

siparişen düşmüş başlarına

yeni doğmuş kadar

hüzünlü bakıyorlar karşıya

bir umut sanki gözleri

bir sevda

bir kaçının yakasında

kırmızı katlı kurdela

okumaya gidiyoruz /bela

yaman hele kışa vurduğunda

ya bahar ya sonbahar

çıksınlar isterdim karşıma

çıkarlardı

alınlarında memleket türküsü

ve ilk aşklar yanlarında

ayaklarında ilk ayrılıklar

“seviyorum abi

onu görünce içim çoğalıyor

hani karpuz yerken

boğulasım tutuyor

bana bakıp gülmesin ne olur

aşk buysa

neden kimse anlatmıyor”

naz’a; 

dişlerin

hastalığımdan önce b’yazdı

bana yakıştı

sonra döküldüler

a’senin ki  gibiler

hani gamze nedir bilmezken

sende gördüm ilk ben

sonradan bin alay geçişler

jale’ye

sesin inceydi

benim ki ince kalın

ikimizin ortası

boyum boyundan az uzun

huyun kapris

zekan müflis

öğretmedin resim dersinde

biraz matematiğinden isterim

ya da olmazsa

bilemediğinde dayağını ben yerim

hem alışkın her yerim

ben tembelim…

25 09 2005

.', '. yağmur anlattı;  küçüktüler akıllarında öğrenmek varken uzun yollar ardınca suyuma buladım topraklarını ıslattım saçlarını bir parça yamal...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":63,"source_url":"https://www.antoloji.com/cizlavet-ciz-etmeler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnız Kalabalık', 'yalniz-kalabalik-gokhan-oflazoglu-2x50o', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bunca yalnız kalabalık 

yürek burkuyor, yollarda

ya da toplantılarda.

Dinlemeyen kulaklar,

gülen yüzler, coşkun

ifadeler, siyah bir aynaya

bakarlar, atomlaşır iletişim; 

ürkersiniz.

İyice sıklaştırın safları,

tek durun, ama, çarpsın

yüreğiniz. 

İnsan bu kadar azalırsa,

yalnız kalabalıklar üretirsiniz.

26/12/2005', 'Bunca yalnız kalabalık  yürek burkuyor, yollarda ya da toplantılarda. Dinlemeyen kulaklar, gülen yüzler, coşkun ifadeler, siyah bir aynaya b...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Oflazoğlu']::text[], 8.5, '{"poet":"Gökhan Oflazoğlu","poet_slug":"gokhan-oflazoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yalniz-kalabalik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ihanet-mi dusunmedim', 'ihanet-mi-dusunmedim-husamettin-guven-433sj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Inan yalniz seni sevdim

bir tek sana meyil verdim

hic kimseye yuzvermedim

ihanet-mi dusunmedim

yalniz seni,seni sevdim

ben kalbimi sana verdim

gozu acip seni gordum

ihanet-mi dusunmedim

yalanlara inanma sen

kimselere guvenme sen

ne olur beni bir dinlesen

ihanet-mi dusunmedim', 'Inan yalniz seni sevdim bir tek sana meyil verdim hic kimseye yuzvermedim ihanet-mi dusunmedim yalniz seni,seni sevdim ben kalbimi sana verd...', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Güven']::text[], 8.5, '{"poet":"Hüsamettin Güven","poet_slug":"husamettin-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ihanet-mi-dusunmedim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Bir Kez', 'son-bir-kez-naciye-bildim-ibw23', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ne olur kapını,yüzüme örtme,

Geçiyordum birkez, göreyim dedim.

Şu perişan olmuş halime gülme

Son birkez hatrını, sorayım dedim.

Giderken geriye, dönmem demiştim,

Yüzüne bir kere,bakmam demiştim.

Ne olur beni yanlış anlama,

Sözümden dönmedim,nasıldır dedim.

Seni benim kadar kimler seviyor? 

O güzel gözlerin,kime gülüyor? 

Ak düşmüş saçların,kimler okşuyor? 

Merak ettimde bir,sorayım dedim.

Ne olur hoş görüp,tut ellerimi

Benden kıskanma,o sıcak buseni.

Bağışlayıpta ver bana yerini,

Bir hayal olsada,gideyim dedim.', 'Ne olur kapını,yüzüme örtme, Geçiyordum birkez, göreyim dedim. Şu perişan olmuş halime gülme Son birkez hatrını, sorayım dedim. Giderken ger...', ARRAY['Türk Edebiyatı','Şiir','Naciye Bildim']::text[], 8.5, '{"poet":"Naciye Bildim","poet_slug":"naciye-bildim","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/son-bir-kez-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen kim sevmek kim', 'sen-kim-sevmek-kim-husamettin-guven-adtle', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'guzel dedim seni sevdim

insan bildim deger verdim

sense bana keder verdim

sen kim sevmek kim

ilk goruste asik oldum

kader deyip razi oldum

sense beni yalniz koydun

sen kim sevmek kim

ayrilmayi dusunmedim

kavga eder hic kusmezdim

valah seni ben cok sevdim

sen kim sevmek kim

tatli sohpet ediyordun

gorlerinle suzuyordun

zannetmistim seviyordun

sen kim sevmek kim

manaliydi o gozlerin

palavraymis hep sozlerin

sahtekarmis guluslerin

sen kim sevmek kim', 'guzel dedim seni sevdim insan bildim deger verdim sense bana keder verdim sen kim sevmek kim ilk goruste asik oldum kader deyip razi oldum s...', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Güven']::text[], 8.5, '{"poet":"Hüsamettin Güven","poet_slug":"husamettin-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sen-kim-sevmek-kim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Giderim', 'giderim-naciye-bildim-daa51', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir garip gönülle düştüm yollara,

Attığım adımla,nefret ekerim.

Sildim gözleri,hak verip fallara,

Sıcak bir yuvaya,hasret giderim...

Ardıma bakacak,güç bırakmadın

Bir yalan sevdayla,beni kandırdın.

Dünyamı kararttın,bitmez kederim

Sıcak bir yuvaya,hasret giderim...

Hatanı anlarsın belki diyerek,

Yaşımı sildim,tebessüm ederek.

Yokluğumda belki haklıydı,dersin

Sıcak bir yuvaya, hasret giderim...

Hakkını helal et,ışığı söndür

ben kendim kapıyı çeker giderim.

N''olur tanrım beni,bu yolda güldür

Sıcak bir yuvaya, hasret giderim...', 'Bir garip gönülle düştüm yollara, Attığım adımla,nefret ekerim. Sildim gözleri,hak verip fallara, Sıcak bir yuvaya,hasret giderim... Ardıma ...', ARRAY['Türk Edebiyatı','Şiir','Naciye Bildim']::text[], 8.5, '{"poet":"Naciye Bildim","poet_slug":"naciye-bildim","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/giderim-52-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tez gel be olum tez gel', 'tez-gel-be-olum-tez-gel-husamettin-guven-hpb5n', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'mutlulugu ara oldum

dert icinde ben kayp oldum

yasamak dan cok yoruldum

tez gel be olum tez gel

su alemde gulemiyorum

mutlulugu bilemiyorum

dertlerimi silemiyorum

tez gel be olum tez gel

yorgun bedenim seni bekler

sen gelince dertlerim ancak biter

olum sende yalniz gercekler

tez gel be olum tez gel', 'mutlulugu ara oldum dert icinde ben kayp oldum yasamak dan cok yoruldum tez gel be olum tez gel su alemde gulemiyorum mutlulugu bilemiyorum ...', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Güven']::text[], 8.5, '{"poet":"Hüsamettin Güven","poet_slug":"husamettin-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/tez-gel-be-olum-tez-gel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suçumu Bilmek İsterdim', 'sucumu-bilmek-i-sterdim-naciye-bildim-qpyam', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gözlerin doluydu,bakarken bana

Uzanıp yaşını, silmek istedim.

Valizin hazırlayıp,giderken daha

Sevdiğim suçumu,bilmek isterim.

Canımı istedin,ben vermedim mi? 

Sev beni dedin de,hayır mı dedim.

Ömrümü yoluna,hep semedim mi? 

Sevdiğim suçumu,bilmek isterim.

Uzattım elimi,geri çevirdin 

Yaşarken canımı,alıpta gittin.

Sen gittin ama,ben o anda bittim,

Sevgilim suçumu,bilmek isterim.

Arkanı dönüpte,birkez bakmadın

Adımı son defa bile anmadın.

Gaçan günlere,bir çizgi attın

Sevgili suçumu,bilmek isterdim.', 'Gözlerin doluydu,bakarken bana Uzanıp yaşını, silmek istedim. Valizin hazırlayıp,giderken daha Sevdiğim suçumu,bilmek isterim. Canımı istedi...', ARRAY['Türk Edebiyatı','Şiir','Naciye Bildim']::text[], 8.5, '{"poet":"Naciye Bildim","poet_slug":"naciye-bildim","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sucumu-bilmek-isterdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Kendime Çoktan Yettim', 'ben-kendime-coktan-yettim-naciye-bildim-95vzb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne fırtınalar savurdu beni,

Ne kara yeller,kasırgalar.

Bir volkan patladıda yüreğimde,

Yinede gözyaşlarım çağlamadılar.

Ne dünyalar çöktü gözlerimde,

Tek damla oldu,hayalim ellerime.

Gençliğim bir iğne,saplandı ciğerime

Zorda olsun güldüm,demedim kimseye.

Ne yollar aldı beni,koynuna

Ne yıldızlar,bir aydınlığına.

kapalı kapılar ardında

Susup kaldım yıllarca.

Hayat vurdu hep yüzüme,

Bense baş koydum dizine.

Elveda dedimde,herşeyime

Rastladınız mı hiç şikayetime.

Ben bana çoktan yettim,

Ben derdimi,içime ektim.

Yıllarca avutup kendi kendimi

Acımı,hıncımı gönlümde çektim...', 'Ne fırtınalar savurdu beni, Ne kara yeller,kasırgalar. Bir volkan patladıda yüreğimde, Yinede gözyaşlarım çağlamadılar. Ne dünyalar çöktü gö...', ARRAY['Türk Edebiyatı','Şiir','Naciye Bildim']::text[], 8.5, '{"poet":"Naciye Bildim","poet_slug":"naciye-bildim","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ben-kendime-coktan-yettim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Naçizane', 'nacizane-ergun-beksen-haz9q', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ben naçizane bir bedenim.

senin gibi mavi yıldızlarım olmadı hiç.

temelinde ter dökmedim, emek vermedim sen gibi

sonrasında hak etmedim yaşamayı başarı gururunu.

ben naçizane bir bedenim.

olmadı senin gibi sarı yıldızlarım, parlamadı fikirlerim.

desteğim yoktu sana yaratırken hayalini, 

tırnaklarınla kazırken umutlarını, ben yoktum.

ben naçizane bir bedenim.

sol yanımda bir boşluk hak ettim sadece,

içimde ezikliğini yaşadım geç kalmalarımın,

umuduna yol arkadaşı olamadığımın.', 'ben naçizane bir bedenim. senin gibi mavi yıldızlarım olmadı hiç. temelinde ter dökmedim, emek vermedim sen gibi sonrasında hak etmedim yaşa...', ARRAY['Türk Edebiyatı','Şiir','Ergün Bekşen']::text[], 8.5, '{"poet":"Ergün Bekşen","poet_slug":"ergun-beksen","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/nacizane-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Soyunup Senden Beni', 'soyunup-senden-beni-birsen-ates-3u0ey', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'sus artık yüreğim

bu kaçıncı aldanışım

kaçıncı yüreğimde s o l u k l a n ı ş ı n

i h a n e t i n

sırtımda saplı bir bıçak

senden gidiyorum

ne yıldızlarda asılı sevdam

nede sus kalışım gözlerinde

kayan yıldızlar gibi

düşüyorum yüreğinden

senden gidiyorum

gelmedi senden sesim

sesinde kaldı düşlerim

bu muydu istediğin

sevdalara dök kelimelerini

soyunup senden ben

giyiyorum hüzünlerimi

anlıyor musun

gidiyorum

26.12.05', 'sus artık yüreğim bu kaçıncı aldanışım kaçıncı yüreğimde s o l u k l a n ı ş ı n i h a n e t i n sırtımda saplı bir bıçak senden gidiyorum n...', ARRAY['Türk Edebiyatı','Şiir','Birsen Ateş']::text[], 8.5, '{"poet":"Birsen Ateş","poet_slug":"birsen-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/soyunup-senden-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Olmuş Ruhum', 'sen-olmus-ruhum-birsen-ates-51jw8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'yokluğun ölüm

suskunluğumda.

dört duvar yalnızlığım

gecelerce paylaştığım

yalnızlık dolu şarkılarım

soğuk ıslak gecelerimde 

ateş oldun ısındım

gidişlerinde

şiir oldum üşüdüm

baktıkça aynaya 

biraz sen olmuş ruhum

26.12.2005', 'yokluğun ölüm suskunluğumda. dört duvar yalnızlığım gecelerce paylaştığım yalnızlık dolu şarkılarım soğuk ıslak gecelerimde  ateş oldun ısın...', ARRAY['Türk Edebiyatı','Şiir','Birsen Ateş']::text[], 8.5, '{"poet":"Birsen Ateş","poet_slug":"birsen-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sen-olmus-ruhum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'canım Babama', 'canim-babama-naciye-bildim-ml0ix', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ekmeğime katık gibisin sanki,

Aklına gelmeyecek kadar yavanım,

Yavanım işte,bir o kadar da huysuzum

Bu günlerde..

Bir sabah,beni bekliyorsundur biliyorum,

Açıktır kolların.

Ve ben,ne haldeyim bir bilsen,bir görsen

Binlerce dizginle bağlanan bir kısrak gibi,

Uçsuz bucaksız kırlarda,

Koşmak için çırpınışım boşyere..Olduğum yerde..

Gözlerim daha yollarına koşmadan,

Seni arar oldu.

Ellerim uzanmış,ellerini tutacak gibi..

Yorgunum babam,Çok yorgunum,

Akmasın hiç dediğin gözyaşlarım

Yanaklarımda yorgun şimdi...

Ve ben bir mevsim daha sensizim,

Sensizim ve çaresizim.

Karlar kaplanmıştır şimdi,Ankara''yı

Ve lapa lapa düşüyordur kapımızın önüne.

Evimizin yokuşunda çocuklar,

Kızaklarda, dans ediyorlardır...

Birde küçük kardan adam varsa,bir köşede

Burnunda havuç,

Gözünde kömür,başında bere...

Ve birde,boynunu bükmüş birini gördünse eğer,

Yakmışındır,azrail gibi sigaranı

Çekmişindir,zehir gibi dumalarını.

Yine ben düştüm değilmi aklına? 

Limanlarında ne fırtınalar kopmuştur

Kimbilir....

Annem kuşlara su koyuyordur yine,

Balkonun bir köşesine,Susuzluktan ölmesinler diye.

Sonra bana benzettiği kuşlar geldimi balkona,

seni çağırıp:

-Bak yine geldi,diyordur...

Azraili birde beraber yakıyorsunuzdur,

Biliyorum...

Annemin,ela gözleri yeşilleniyordur,

Senin boğazına yumruk,yumruk takılıyordur

Özlem,hasret.

Ve benden

ve çocukluğumdan bahsediyorsunuzdur,

Benimde gurbette yanaklarım kızarıp,

beni andılar, diyorum..

sen gelsen bana,                                                                                  

Yüreği yaralı kızına,

Ekmeğine katık gibi

yarasına merhem gibi

Gözyaşına,mendil gibi..

Ne bileyim işte,

Hasretime ecel,gibi sen gelsen,babam...

Seni çok özledim babam,

Ocağında bir dilim ekmek tadını,

Isınmak için yaktığın kömür kokusunu

Heşeyini çok özledim...', 'Ekmeğime katık gibisin sanki, Aklına gelmeyecek kadar yavanım, Yavanım işte,bir o kadar da huysuzum Bu günlerde.. Bir sabah,beni bekliyorsun...', ARRAY['Türk Edebiyatı','Şiir','Naciye Bildim']::text[], 8.5, '{"poet":"Naciye Bildim","poet_slug":"naciye-bildim","theme":"Türk Şiiri","is_hero":false,"total_lines":56,"source_url":"https://www.antoloji.com/canim-babama-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen anlarsın...', 'sen-anlarsin-hasan-sahin-18xw0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Akdenizim

Adı saklım...

Aynı acının paydasıyız

Ve aynı toprağa düştü

Göz yaşımız....

Cinnet öyküleri yazmadık

İnandık inanılmayası öykülere 

Tuvallere işlenmiş sarmaşıklara dolandık

Türkü söyledik inadına

Bildik yara değil mi

Gelip dokunduğun yürekteki

Tüketmedin mi sende

Dar koridorlarda

Koca bir ömrü...

Bu yüzden tanıdık yüzüm sana

Ve bu yüzden yitip gidiyoruz

Okunmamış satırlarda', 'Akdenizim Adı saklım... Aynı acının paydasıyız Ve aynı toprağa düştü Göz yaşımız.... Cinnet öyküleri yazmadık İnandık inanılmayası öykülere ...', ARRAY['Türk Edebiyatı','Şiir','Hasan Şahin']::text[], 8.5, '{"poet":"Hasan Şahin","poet_slug":"hasan-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sen-anlarsin-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karalama....', 'karalama-hasan-sahin-qlo3v', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bulamadı adam

Sığınacak bir dua

Cılız adımlarla

Kaçtı mahşerden

Yıkıldı gök kubbe

Gittiği her yerde

Ardına düştü birden

Kaçtığı tüm korkular

Be hey dedi hayata

Yenilmişlik bunun adı

Ki telafisi yoktur artık

Çekti alevleri üstüne üstüne

Avuçlayıp geçmişi hırsla

Aradı küstürdüğü kaderi

Küstürdüğü kader değil

Olmayacak yıllarıymış', 'Bulamadı adam Sığınacak bir dua Cılız adımlarla Kaçtı mahşerden Yıkıldı gök kubbe Gittiği her yerde Ardına düştü birden Kaçtığı tüm korkular...', ARRAY['Türk Edebiyatı','Şiir','Hasan Şahin']::text[], 8.5, '{"poet":"Hasan Şahin","poet_slug":"hasan-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/karalama-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kim Görmüş 2', 'kim-gormus-2-kamil-at-ogheg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hadi sen korkularını kendinde yen

Hangi tarafmış sen yada ben

Bilerek gitsin ölüme canlı giden

Kim görmüş cenneti bilmem ne.

Doğruluk insan olanın özünde var

Korkudan tutulmaz hayal ayar

Bedenin kendini toprağa dayar

Kim görmüş cehennemi ölmem ne.

Zalimleri sadece insanlık silecek

İçinde kötülük olmadığını bilecek

Dünyaya mutlak doğruluk gelecek

Kim görmüş cenneti bilmem ne.

Kamil At, aklı olan sırları çözmeli

İnsan eskiyi değil, yeni gezmeli

Görünmeyene inanmam kim deli

Kim görmüş cehennemi ölmem ne.', 'Hadi sen korkularını kendinde yen Hangi tarafmış sen yada ben Bilerek gitsin ölüme canlı giden Kim görmüş cenneti bilmem ne. Doğruluk insan ...', ARRAY['Türk Edebiyatı','Şiir','Kamil At']::text[], 8.5, '{"poet":"Kamil At","poet_slug":"kamil-at","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kim-gormus-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '-Dersim-', 'dersim-ercan-cengiz-n6g3h', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'DERSİM

bu kaçıncı sancındır Dersim 

Munzur''un sesine bıraktığın 

bu kaçıncı sancın 

söyle bu kimin rüzgarıdır ki 

senin gülüşündedir gözü 

dağlarına vurunca dönen 

bu kaçıncı rüzgar 

kara bulutlar yoksa üzerinde 

gökyüzü mavi giyinmiştir 

ve Munzur berrak akar 

sana kaçıncı gelişim bu 

hazırlıksız 

habersiz de olsan 

gelmişim ya sana 

sen Dersim''sin tutarsın 

damarında sakladığın 

bu toprağın gücüsün 

bin yılların ağrısı da olsa 

Munzur''a bandırıp içersin 

topladığın güneşin aşkına 

sana sığınıyorum Dersim 

(Adsız Fırtınalar Doğuyor)', 'DERSİM bu kaçıncı sancındır Dersim  Munzur''un sesine bıraktığın  bu kaçıncı sancın  söyle bu kimin rüzgarıdır ki  senin gülüşündedir gözü  d...', ARRAY['Türk Edebiyatı','Şiir','Ercan Cengiz']::text[], 8.5, '{"poet":"Ercan Cengiz","poet_slug":"ercan-cengiz","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/dersim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vildanım Canım Benim', 'vildanim-canim-benim-emrevildan-dost-zj0v6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'düşüncemde yalnız sen varsın 

ve düşlerimde dudaklarını birkaç kez öptüm 

bazen seni yurdumun önünden gecerken görüyorum 

merhaba

aradığın ben miyim? 

bunu gözlerinde göremiyorum 

cehennemden cenneti, acılar içinden mavi gökyüzünü ne kadar anlayabilirim? 

soğuk çelik raylardan yeşil çayırları? 

bir maskeden gülümsemeyi? 

bunu gülüşünde göremiyorum 

sen benim ömrümce  isteyebileceğim en tatlı seysin 

yada ben bunu bilemeyecek kadar düşünüyorken seni

sen buna inanmayacak kadar zeki zannediyorsun kendini

hiç bişeyle değismek istemiyorum seni

kahramanlarınla hayaletlerini takas etmek zorunda kaldın mı hiç? 

ağaçlarla sıcak külleri? 

sıcak hava ile soğuk bir esintiyi? 

nasıl bişey olduğunu biliyorum

ve sen benim değişmek istemediğim süper kahramanımsın

beni değistiren dış dünyaya açılan kapımsın

sadece burda olmanı istiyorum yanımda

geç saatlere kadar uyuyuşunu izlemek istiyorum

babamın acısını sen de unutmak isterken

daha fazla çaresizliğime yenilmek istemiyorum 

çıktığım sahnede alkış almak istiyorum  artık

ama bunu oyunun sonunda ölerek yapmak istemiyorum

ve anlıyorum seni

güllerin soluyor benimkilerle birlikte biliyorum

gözlerinde bişeyler bitiyor görüyorum

ve söylediğin her ''hoşçakal'' ın

bir öncekinden  veda ya daha yakın bir anlam içerdiğini  de

ama herşey birbirine giriyor ayıramıyorum

böyle olmasını istemiyorum ama engel olamıyorum

birgün bittiğinde artık herşey

ve zamanın çarkı  geri döndürülemeyecek kadar paslandığında 

seni sevmeye devam etmek istiyorum

ve seni kaybedişimin nedenini söylemek şimdiden

seni tutamıyorum elimde 

çünkü sevgin beni aç susuz bırakıyor bi köşede

dövüyor hergün küçük çocuğu çılgına çeviriyor

ve kulağıma okadar bağırıyor ki 

ne dediğini bile duyamıyorum

anlayamıyorum seni o yüzden

nöbetçiliğimi yaparken yatağımın yanıbasımda öfkem

bana senle ilgili karanlık hikayeler anlatırken gördüğüm sen olamıyorsun daha fazla

söyleyemiyorum sana derdimi anlatamıyorum 

tek bir kelimeyi bile açıklayamıyorum senle ilgili

yapabildiğim tek sey sana kollarımı açmak

düşlerinde gördüğün ben değilim belki

ama bilmeni istiyorum seni çok özlüyorum

uykumda bile

ve bir gün elimden tutsan bile düşümde

ve götürmeye kalksan gitmek istediğim yerlere

ben senle burda  kalmak istiyorum

çünkü beni nasıl sevebileceğini biliyorum

ve sana defalarca seni seviyorum demek istiyorum 

nasıl nezamandır ve nerden olduğunu bilmeden

seni sevmek istiyorum nefes alır gibi 

saçlarında gün ışığını görmeyi çok istiyorum 

gözlerinde de sevgiyi acımayı değil

ve seni ne kadar çok önemsediğimi söylemek istiyorum 

çaresizliğimi değil

sana karşı yaptığım yanlış seylerin gözünü kör etmesine dayanamıyorum

ve bana karsı takındığın tutumun da öfkemi kırbaçlamasına

bazen kalbim yerinden fırlayacakmış gibi hissediyorum 

merhaba 

sana söylemem gerek 

nerede olduğunu merak ediyorum 

ve ne yaptığını 

bir yerlerde kendini yalnız mı hissediyorsun 

ya da birileri seni seviyor mu? 

bana kalbini nasıl kazanacağımı anlat 

çünkü hiçbir fikrim yok', 'düşüncemde yalnız sen varsın  ve düşlerimde dudaklarını birkaç kez öptüm  bazen seni yurdumun önünden gecerken görüyorum  merhaba aradığın b...', ARRAY['Türk Edebiyatı','Şiir','Emrevildan Dost']::text[], 8.5, '{"poet":"Emrevildan Dost","poet_slug":"emrevildan-dost","theme":"Türk Şiiri","is_hero":false,"total_lines":73,"source_url":"https://www.antoloji.com/vildanim-canim-benim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmeden', 'bilmeden-refik-senol-cetin-wcc4w', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir gün çekip gideceğim

Ve kimse ağlamayacak ardımdan

Şiirlerimi unutucaklar ilk

Ve gülüşümün en acıklı gamzelerini

Sevdamı anımsayacaklar bazen

Aşık adamdı

Güzel adamdı diyecekler ardımdan

Ardımdan ne küfürler edecekler

Çınlayan kulaklarımın umursamadığını 

Bilmeden

Kadınlar adımı hatırlayacak

Çocuklar yüzümü ve uzun boyumu

Selamımı hatırlayacak

Kimsenin umursamadığı

Hamal memet abim

Az kanbur duruşumu anlatacak

Yan komşum herkese

Sessiz olduğumu söyleyecek evimde

Bağıra bağıra içimi parçaladığımı

Bilmeden

Gideceğim kalanlara inat

Gitmek gerektiğinden

Erkekliğimden biraz

Biraz göz yaşımı gizlemek için

Saklanmak için gideceğim

Kendimi sobelemek için

Bir aşkı unutmak için gideceğim

Unuturken bir deftere kazımak için

Onu unutunca kendimi de unutacağımı 

bilmeden

Suskun acılara gömülüp sokağımı kahretmeden

Ve ahetmeden sabahları uyandıran simitçiye

Bozuk sokak lambama

Yamuk kaldırımına kızmadan

Adını değiştirenlere inat

Adresimi unutmadan gideceğim

Çocukluğum yanımda

Bavulumda ilk gençliğim

döner miyim dönmez miyim

bilmeden gideceğim', 'Bir gün çekip gideceğim Ve kimse ağlamayacak ardımdan Şiirlerimi unutucaklar ilk Ve gülüşümün en acıklı gamzelerini Sevdamı anımsayacaklar b...', ARRAY['Türk Edebiyatı','Şiir','Refik Şenol Çetin']::text[], 8.5, '{"poet":"Refik Şenol Çetin","poet_slug":"refik-senol-cetin","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/bilmeden-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fark ettin mi hiç?', 'fark-ettin-mi-hic-refik-senol-cetin-4udwr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İçimde gizlenen

Korkulardan arta kalan

Ve yalnızlığım sandığım

Eskimiş anılarımda saklanan

Cümleleri dize yapan

O gerçek

Gözlerinde saklı

Fark ettin mi hiç? 

Şimdi diyorum hep

Az sonra gidecek

Ardında bozuk para gibi

Harcanmış bir ben

Uyanıyorum sonra düşlerimden

Yoksun yanımda

Yalnızlığı sensizlik yapan

O gerçek

Gözlerinde saklı 

Fark ettin mi hiç? 

Uyutmaz bazen gece

Bazen olur olmaz düşler

Aldırmaz kaderim kimselere

Sen olsan yeter

Kıymet bulur aldığım nefes

Ve anlamı demlenir hayatın

Avuçlarında

Beni ben yapan 

O gerçek

Gözlerinde saklı

Fark ettin mi hiç?', 'İçimde gizlenen Korkulardan arta kalan Ve yalnızlığım sandığım Eskimiş anılarımda saklanan Cümleleri dize yapan O gerçek Gözlerinde saklı Fa...', ARRAY['Türk Edebiyatı','Şiir','Refik Şenol Çetin']::text[], 8.5, '{"poet":"Refik Şenol Çetin","poet_slug":"refik-senol-cetin","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/fark-ettin-mi-hic-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yemin', 'yemin-refik-senol-cetin-qwnk0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bulup da kaybettiğim şeyler adına

Öğrenip de unuttuğum gerçekler adına

Yaşayıp da öldürdüğüm hayatlar uğruna

Bilip de gizlediğim yalanlar uğruna

Susup da söylemediğim şarkılar adına

Duyup da yazmadığım şiirler adına

Gidip de gelmediğim diyarlar adına

Kendi adıma söylüyorum

Baştan ayağa

Tek hayatım var

Tek ölümüm

Hepsi 

Varım yoğum

Susum çığlığım

Aklım aptallığım

Yüreğim korkaklığım

Aşkım ayrılığım

Bitişim başlangıcım

Doğrum yalanım

Çocuğum kısırlığım

Geçmişim yarınım

Şimdim

Hepsi

Senin olsun

Yanındayım

Yemin olsun', 'Bulup da kaybettiğim şeyler adına Öğrenip de unuttuğum gerçekler adına Yaşayıp da öldürdüğüm hayatlar uğruna Bilip de gizlediğim yalanlar uğ...', ARRAY['Türk Edebiyatı','Şiir','Refik Şenol Çetin']::text[], 8.5, '{"poet":"Refik Şenol Çetin","poet_slug":"refik-senol-cetin","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/yemin-38-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O kollarımda', 'o-kollarimda-refik-senol-cetin-w9nci', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ay gizlendi sevgilimin göz kapaklarına

Ve mahkum kaldı bir rüyanın eşiğinde

Sabaha dek uyurken o kollarımda

Kime inanacağını şaşırır gölgem bazen

Bazen kim olduğunu senin yanında

Aşık adam, aşıktır, kendi yoktur aslında

Sessiz, uygun adım bekler yüreğim

Geleceksin bilir, gözleri hep yolda

Kimseye sezdirmeden türküler söyler

Sen görününe dek yatağımın başucunda

Odamda bir şehir dolusu insan uyur

Ellerim bir şiirde dolanır durur

Bilemezsin asla neden böyle

Ama sırtına sanki hep biri sarılır da uyur', 'Ay gizlendi sevgilimin göz kapaklarına Ve mahkum kaldı bir rüyanın eşiğinde Sabaha dek uyurken o kollarımda Kime inanacağını şaşırır gölgem ...', ARRAY['Türk Edebiyatı','Şiir','Refik Şenol Çetin']::text[], 8.5, '{"poet":"Refik Şenol Çetin","poet_slug":"refik-senol-cetin","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/o-kollarimda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Felicita', 'felicita-refik-senol-cetin-q153t', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'penceremde yabancı bir rüzgar

sanki koynumda nefesi

hiç tanımadığım dudakların

kimi alıp götürsem rüyalarıma

yalnızım

yine de yalnızım

ah kara yazı

ah kadınsızlığım

ah beni bilmez ellerin

beni görmez gözlerin

vefasızlığı sızım

kimi alıp getirsem yatağıma

kime gönlümde yer versem yalnızım

ah yalnızım', 'penceremde yabancı bir rüzgar sanki koynumda nefesi hiç tanımadığım dudakların kimi alıp götürsem rüyalarıma yalnızım yine de yalnızım ah ka...', ARRAY['Türk Edebiyatı','Şiir','Refik Şenol Çetin']::text[], 8.5, '{"poet":"Refik Şenol Çetin","poet_slug":"refik-senol-cetin","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/felicita-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir anlamı olmalı', 'bir-anlami-olmali-refik-senol-cetin-rif11', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir anlamı olmalı yaptıklarımızın

Ettiklerimizin

Edip de çektiklerimizin

Bir kıymeti kalmalı biz

Ölüp gidip

Gidip gelip ölüp

Ölüp gelip

Gidip ölüp

Dönüp durup

Söyleyip sustuklarımızın bir anlamı olmalı

Kaçıp gizlendiklerimizin

Ortaya serip

Düğümlediklerimizin

Şimdi bir ses var aklımda

Kafamda

Kulaklarımda

Ellerimde

Vücudumda dolanan bir ses

Bir ses ver diye inlerken sizin ruhlarınız 

Ve arınamazken yaptıklarından

Ben zenginlerin karunu

Gevezelerin kralı

Sizi kutsuyorum

Şiirlerimden pay alın kıskanacağınıza', 'Bir anlamı olmalı yaptıklarımızın Ettiklerimizin Edip de çektiklerimizin Bir kıymeti kalmalı biz Ölüp gidip Gidip gelip ölüp Ölüp gelip Gidi...', ARRAY['Türk Edebiyatı','Şiir','Refik Şenol Çetin']::text[], 8.5, '{"poet":"Refik Şenol Çetin","poet_slug":"refik-senol-cetin","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bir-anlami-olmali-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Med Cezir', 'med-cezir-refik-senol-cetin-da7g1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İçimde bir telaş bu akşam

Gizli yaralarım kanıyor yokluğunda

Sensiz bir türkü tutturmuş sokaklarım

Teninin sıcaklığı aklımda

Uyansam uykumdan canım almaz

Bilirim ki yanımda sevdiğim yatmaz

Dolunay vakti yarın, kuşlar susmaz

İçimde hasret bir gelir bir gider

Med cezir misali yüzün aklımda

Kıyılarıma vurur sureti şarkılar gibi

Durmaz ki gecenin içime akan

Bu koyu hasret rengi

Kime anlatsam derdimi

Yerini tutmaz biri gelir biri gider...

Hayli oldu sevgilim seni görmeyeli

Zaman doldu, vakit kavuşmak vakti

Şimdi gitsem sana, senden gelsem,

Sen durmasan öyle uzaklardan bakmasan

Anlasan ya derdimi söyletmesen

Susmasan geceleri aklımda

Ah o uzun kahrolası geceler var ya

Sokakları bitirdim şehirleri

Acılarını aldım ışıklı pencerelerin

Kaza yerlerine dualarımı verdim

Kaybettim bazı kendimi

Bazı kandırdım bilmeden

Bazı bile isteye yalanlar söyledim

Hasreti yaşamak ne zor bilir misin? 

İki kere yalnızsındır

İki kere boştur için

İki kadeh doldurur

İki kere sarhoş olursun

Zulümdür bu bilir misin? 

Belki serçe parmağında bile fark etmezsin? 

Neye yarar dediklerim,

Kim anlar? 

Sen bakma bana yaralıyım

Sevdalıyım

Dağlanmış yüreğim gözlerinle

Aşığınım

İki kere ölmekse cezam ölürüm ama

Hayli oldu sevgilim seni görmeyeli

Zaman doldu, vakit kavuşmak vakti

Gel... Bekliyorum seni...', 'İçimde bir telaş bu akşam Gizli yaralarım kanıyor yokluğunda Sensiz bir türkü tutturmuş sokaklarım Teninin sıcaklığı aklımda Uyansam uykumda...', ARRAY['Türk Edebiyatı','Şiir','Refik Şenol Çetin']::text[], 8.5, '{"poet":"Refik Şenol Çetin","poet_slug":"refik-senol-cetin","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/med-cezir-35-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adam olana..', 'adam-olana-refik-senol-cetin-9yyzw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şimdi duyduğum sesin...

Yeryüzü sensin...

Dolunaylar içimde dolanır 

Rüzgar esiridir 

Sensiz gözlerimin

Şaşarım halime

Gündüzümde sen

Gecemde sen

Aklımın içinde 

Yüreğimde sen

Şimdi duyduğum sesin...

İçimde bir yerlerde gizlisin

Giderek derinleşen bir dehlizte...

Düşünmedim değil

Sensizken ölümü

Ölümü düşünmek ölmek gibi sevdiğim

Düşünmedim değil

Yalnızken zulmünü

Aşıkken görmek mümkün değil

Gel gayrı

Gitmelerin yetmedi mi

Sona erdir acılarımı

Yaralarımı sar

Bunca hasret adam olana

Bir ömür yeter', 'Şimdi duyduğum sesin... Yeryüzü sensin... Dolunaylar içimde dolanır  Rüzgar esiridir  Sensiz gözlerimin Şaşarım halime Gündüzümde sen Gecemd...', ARRAY['Türk Edebiyatı','Şiir','Refik Şenol Çetin']::text[], 8.5, '{"poet":"Refik Şenol Çetin","poet_slug":"refik-senol-cetin","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/adam-olana-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ay Tutulsa', 'ay-tutulsa-birsen-ates-bf1gv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'hadi gel  n''olur 

ilk yazda bıraktım seni

öldüm de sana

gel diyemedim 

sayıkladığım düşlerimde

öyle bir yürek acısı  ki

sessiz 

sensiz evim

paranoid hallerim

anlamsız hayatım

bekliyorum ay tutulsa

ölüme yakın olduğumda

gerçekten g i d e c e ğ i m

26.12.2005', 'hadi gel  n''olur  ilk yazda bıraktım seni öldüm de sana gel diyemedim  sayıkladığım düşlerimde öyle bir yürek acısı  ki sessiz  sensiz evim ...', ARRAY['Türk Edebiyatı','Şiir','Birsen Ateş']::text[], 8.5, '{"poet":"Birsen Ateş","poet_slug":"birsen-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ay-tutulsa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünya da rahat yoktur', 'dunya-da-rahat-yoktur-mikdat-bal-sja4d', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dünya da rahat yoktur 

Bunda kerahat çoktur 

Dünyanın elemi çok 

Kalpte cerahat çoktur 

O döner biz döneriz 

Bir gün gelir söneriz 

Ne kadar yüksekteysek 

Bir çukura ineriz 

Ne kimseyi güldürür 

Ne de sefa buldurur 

Gün gelir hepimizi 

Kucağına doldurur 

Dünya döner dönektir 

Ona tapan inektir 

Hayatı veresiye 

Dert peşin ödenektir 

Zalimlere güldün ya 

Bize de az gül dünya 

Ah gariban fukara 

Dünya için öldün ya 

İşte size son sözüm 

Fazlasına yok lüzüm 

Kanaat zenginliktir 

Budur en kesin çözüm', 'Dünya da rahat yoktur  Bunda kerahat çoktur  Dünyanın elemi çok  Kalpte cerahat çoktur  O döner biz döneriz  Bir gün gelir söneriz  Ne kadar...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/dunya-da-rahat-yoktur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevişme Vaktiydi', 'sevisme-vaktiydi-birsen-ates-5adg8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'gelseydin

ruhumun sevişme vaktiydi 

çırılçıplaktı ay

oynaşıyordu 

denizle yakamoz 

gelseydin 

hazırdım senin olmaya

gelmedin

gelemedin

26.12.2005', 'gelseydin ruhumun sevişme vaktiydi  çırılçıplaktı ay oynaşıyordu  denizle yakamoz  gelseydin  hazırdım senin olmaya gelmedin gelemedin 26.12...', ARRAY['Türk Edebiyatı','Şiir','Birsen Ateş']::text[], 8.5, '{"poet":"Birsen Ateş","poet_slug":"birsen-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sevisme-vaktiydi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tahta', 'tahta-burhan-kucuk-h1v70', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Tahta

Gün doğarken kapından

Unutma bakmayı pervaza

Belli olmasa da

Taze bir iz vardır tahta da

Kuş sesleri vurur sabaha

Çalılıklar arasında gezinen

Dönüşür bildik bir ahşaba

Şah damarı kesilen

Burhan KÜÇÜK

Kdz.Ereğli-25.12.2005', 'Tahta Gün doğarken kapından Unutma bakmayı pervaza Belli olmasa da Taze bir iz vardır tahta da Kuş sesleri vurur sabaha Çalılıklar arasında ...', ARRAY['Türk Edebiyatı','Şiir','Burhan Küçük']::text[], 8.5, '{"poet":"Burhan Küçük","poet_slug":"burhan-kucuk","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/tahta-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ardından', 'ardindan-burhan-kucuk-tb8o6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ardından

Gri beyaz katlanmış çuval bezi

Kıvrımları taşlarla kaplı

Engebeli  bir arazi gibi

Akşama doğru / Sürgülü gönül kapısı

At sürdüm sırtı iğneli

Yüksek platolarda kalbin

Testere yüzü gibi engelli

Ardından sürüklendiğim kadın

Burhan KÜÇÜK

Kdz.Ereğli-25.12.2005', 'Ardından Gri beyaz katlanmış çuval bezi Kıvrımları taşlarla kaplı Engebeli  bir arazi gibi Akşama doğru / Sürgülü gönül kapısı At sürdüm sır...', ARRAY['Türk Edebiyatı','Şiir','Burhan Küçük']::text[], 8.5, '{"poet":"Burhan Küçük","poet_slug":"burhan-kucuk","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ardindan-47-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ünler', 'unler-suna-aras-fle6k', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ay neden gizler yüzünü? 

Geceler eğrilir üstümüze

Acı dinmez.

Analar döl yüklü bağırandır hayatı

Ölüler konuşmaz ki dedi öteki

İshak kuşu susmaz dedim

Son tren henüz kalkmadı.

Dedi

Aşk ve akrep

Yelkovan hilelidir

Yel gelir eser kalbim dondur adı ölümün

Gül ekmez acı döker

Deh sözüm diyemem ki

Bedeli mahpustur özgürlüğümün.

Dedim

Celali huyu var söz tutar oğlum

Cellâdına boy kırmaz

Anadolu ünler Pir Sultan baba

Yarını yol eyleyen dünü asla unutmaz', 'Ay neden gizler yüzünü?  Geceler eğrilir üstümüze Acı dinmez. Analar döl yüklü bağırandır hayatı Ölüler konuşmaz ki dedi öteki İshak kuşu su...', ARRAY['Türk Edebiyatı','Şiir','Suna Aras']::text[], 8.5, '{"poet":"Suna Aras","poet_slug":"suna-aras","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/unler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geri Dönüp ''Ölme'' Gülüm', 'geri-donup-olme-gulum-kadir-albayrak-ii1vu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sensizliğe gömdüm seni

Gayrı geri dönme gülüm

Sensizlikte buldum seni

Geri dönüp ölme gülüm

Sensizliktir ülkem benim

Kurban benim cellat benim

Sınır çizen kalem benim

İzin vermem girme gülüm

Sen de kalsın “sen” ne varsa

Eller onu ne sayarsa

O  yüreğin kaç  ayarsa

Satıp bana gelme gülüm

Götürdüğün kadar geri

Getirecek neyin var ki

Şimdi gönlüm öyle dar ki

Bana yer ver deme gülüm

Sensizlik de cananımsın

Gecem düşüm yatağımsın

Sen can değil “sen haramsın”

Çek elini tövbe gülüm

Benim sevdam ölümüne

Umut candır iklimine

Sevdim desen yeminine

Kanmam bile bile gülüm

Seni sevdim sensizlikte

Seni buldum sessizlikte

Umutların hasretiyle

Aramıza girme gülüm

Kül olmuşsun köz yaratma

Gönlüm mabet gel kanatma

Sen de ”ona el uzatma”

Beni katil etme gülüm', 'Sensizliğe gömdüm seni Gayrı geri dönme gülüm Sensizlikte buldum seni Geri dönüp ölme gülüm Sensizliktir ülkem benim Kurban benim cellat ben...', ARRAY['Türk Edebiyatı','Şiir','Kadir Albayrak']::text[], 8.5, '{"poet":"Kadir Albayrak","poet_slug":"kadir-albayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/geri-donup-olme-gulum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İs', 'i-s-gulsen-gonenc-0dvmo', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sararmış umutlar ısınırken,

''aslında''lara asılı kalmış

tümcelerin derin soğukluğu

ateşi kesti.

İlginç, ağlamadım bu kez.

İs kokusu sardı hücrelerimi - sevdiğim-; 

Canlandı ahşap evlerdeki yaşanmışlık,

Merdivenler, köşebaşındaki güvercinler,

Gölgeler, izler,

Çocukluğum.

Sadece biraz yorgunum.', 'Sararmış umutlar ısınırken, ''aslında''lara asılı kalmış tümcelerin derin soğukluğu ateşi kesti. İlginç, ağlamadım bu kez. İs kokusu sardı hüc...', ARRAY['Türk Edebiyatı','Şiir','Gülsen Gönenç']::text[], 8.5, '{"poet":"Gülsen Gönenç","poet_slug":"gulsen-gonenc","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/is-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğine Bir Nehir Gibi Aktığımsın', 'yuregine-bir-nehir-gibi-aktigimsin-huseyin-erdogan-2b72q', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'güneş yarından sonra

hiç batmasa 

veya

bir daha  doğmasa da

inan ki üzülmem  asla

çünkü sen

gündüzleri bile 

hiç sönmeyen 

bir yıldızsın benim dünyamda

dışarıda rüzgar esse ayaz çıksa da

yağmur yağsa karanlık olsa da

şiirim senin sevginle 

aydınlanırım ısınırım ben 

ömrüm boyunca yaşadıkça

yeter ki sen uzaktan da olsa

her sabah uyanınca gülümse bana

beni mahkum etme yokluğuna

bir gün bile 

dönüp bakmasan benden yana

hüzün dolar kalbime 

yüreğim boğulur yasa

ne olursun sevdiğim

sakın gönlüme hiç düşürme tasa

bil ki sen benim tek varlığımsın

gözlerinle yarınlara umutla baktığımsın

sevgimi yüreğine bir nehir gibi aktığımsın

                                                 26.12.2005

                                             Hüseyin Erdoğan', 'güneş yarından sonra hiç batmasa  veya bir daha  doğmasa da inan ki üzülmem  asla çünkü sen gündüzleri bile  hiç sönmeyen  bir yıldızsın ben...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/yuregine-bir-nehir-gibi-aktigimsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Havalardan, havalardan...', 'havalardan-havalardan-necla-aktan-pfxik', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne oldu bilemiyorum

Epeydir yazmazdı bu kalem 

Çıkmazdı ağzından bir tek kelam 

Şimdi yazmazsa uyuyamayan ben 

Havalardan, havalardan...

Kış geldi de buzlar mı çözüldü? 

Güneş açtı da kalem çiçeğe mi durdu? 

Biliyorum tuhaf olmasına tuhaf bir olgu 

Var bir şey de ne? 

Havalardandır,havalardan... 

25.12.2005', 'Ne oldu bilemiyorum Epeydir yazmazdı bu kalem  Çıkmazdı ağzından bir tek kelam  Şimdi yazmazsa uyuyamayan ben  Havalardan, havalardan... Kış...', ARRAY['Türk Edebiyatı','Şiir','Necla Aktan']::text[], 8.5, '{"poet":"Necla Aktan","poet_slug":"necla-aktan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/havalardan-havalardan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlasaydın Ne Vardı', 'anlasaydin-ne-vardi-yusuf-onder-bahceci-tduye', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Beni sever ele gider,

Sonra bana sitem eder,

Bu yol uzayıpta gider,

Mahşerin ucuna kadar.

Ben herşeyi biliyorum,

Sana sabır diliyorum,

Her şeyinle seviyorum,

Anlasaydın ne vardı.

Senden gelen herşey güzel,

Bu Dünya seninle güzel,

Sevgin şu kalbimde özel,

Anlasaydın ne vardı.

Birgün kesilir nefesim,

Gelmez olur sana sesim,

Gözümde kalır hevesim,

Anlasaydın ne vardı......', 'Beni sever ele gider, Sonra bana sitem eder, Bu yol uzayıpta gider, Mahşerin ucuna kadar. Ben herşeyi biliyorum, Sana sabır diliyorum, Her ş...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/anlasaydin-ne-vardi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşa!', 'yasa-necla-aktan-8qxmf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aman be kardeşim, 

Bakma azına çoğuna 

Kimseyi eliboş göndermedi ki yaradan 

Elindekiyle git yoluna 

Madem ki getirildin

Gün dolunca da götürüleceksin

Yaşa be kardeşim 

Şu sayılı günlerde 

İnsan gibi yaşa!

24.12.2005', 'Aman be kardeşim,  Bakma azına çoğuna  Kimseyi eliboş göndermedi ki yaradan  Elindekiyle git yoluna  Madem ki getirildin Gün dolunca da götü...', ARRAY['Türk Edebiyatı','Şiir','Necla Aktan']::text[], 8.5, '{"poet":"Necla Aktan","poet_slug":"necla-aktan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yasa-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Veni vidi vici', 'veni-vidi-vici-necla-aktan-85g2p', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Geldim

Gördüm

Yenemeden gideceğim 

Beni affet VICI 

Sana söz 

Yeniden geleceğim....

25.12.2005', 'Geldim Gördüm Yenemeden gideceğim  Beni affet VICI  Sana söz  Yeniden geleceğim.... 25.12.2005...', ARRAY['Türk Edebiyatı','Şiir','Necla Aktan']::text[], 8.5, '{"poet":"Necla Aktan","poet_slug":"necla-aktan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/veni-vidi-vici-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sıfır sekiz', 'sifir-sekiz-necla-aktan-ifdld', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sıfır sekiz 

Onsekiz arası 

hayatımız oldu 

Onsekiz 

Sıfır sekiz arasına ne oldu? 

