INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cinaslı Şiir', 'cinasli-siir-zek-i-budak-bjvbe', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gidecek biniyor ata

Ne de şanlı gelin Ayşe

Yiğitler naralar ata

''Ata binme gel in Ayşe''

Toplanın da ana ata

Bir gün bize gelin Ayşe

(Kadıköy / İstanbul - 1976)', 'Gidecek biniyor ata Ne de şanlı gelin Ayşe Yiğitler naralar ata ''Ata binme gel in Ayşe'' Toplanın da ana ata Bir gün bize gelin Ayşe (Kadıköy...', ARRAY['Türk Edebiyatı','Şiir','Zekâi Budak']::text[], 8.5, '{"poet":"Zekâi Budak","poet_slug":"zek-i-budak","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/cinasli-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Seni Vicdanınla Bırakıyorum', 'ben-seni-vicdaninla-birakiyorum-eyup-selahattin-dalkiran-ajm5g', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Utanmalısın hemde öyle utanmalısın ki

Sana duyulan bu aşka,sevgiye karşı

Sendeki vefasızlığa karşıda.

Yalanlarında güzeldi inan benim için

Sırf mutlu olduğum için susuyordum.

Hiç üzülmeni istemezdim inan.

Nede güzel masum pozlar yaratırdın

İşte o pozların beni güldürürdü içten

Yinede bırak diyordum o öyle mutlu

Biliyormusun herşey gözlerin içindi

Ama sana anlatılması zor bilirim.

Utanmalısın hemde öyle utanmalısın ki

sana duyulan bu aşka,sevgiye karşı

Sendeki vefasızlığa karşıda

Sen zannediyordun ki hayat yenilir

Ama bildiğin gibi değil hayat

Sen  kim bilir neler yapmaktasın şimdi.? 

Ama ben sana karşı,sensizlik ile

acıların en güzelini yaşatıyorum kendimde

Olsun ben böyle mutluyum

Senin Gözlerin,

Senin sözlerin için değer bunları yaşamaya

Biliyormusun

Hüzün çiçekleri o kadar güzelmişler ki

Haberim yokmuş ama inan bundan sonra

Her yanımı hüzün çiçekleri ile donatacağım

Güzel güzel koksunlar diye

Eminim ki

Kıyamet kopsa sen unutmayacaksın benim gibi

Sana sunulan aşkı,sevgiyi,mutluluğu

Utanmalısın diyorum yine,sana duyulan

aşka,sevgiye karşı

ve ben seni vicdanınla başbaşa bırakıyorum.

Hoşçakal.', 'Utanmalısın hemde öyle utanmalısın ki Sana duyulan bu aşka,sevgiye karşı Sendeki vefasızlığa karşıda. Yalanlarında güzeldi inan benim için S...', ARRAY['Türk Edebiyatı','Şiir','Eyüp Selahattin Dalkıran']::text[], 8.5, '{"poet":"Eyüp Selahattin Dalkıran","poet_slug":"eyup-selahattin-dalkiran","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/ben-seni-vicdaninla-birakiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben', 'ben-zek-i-budak-ey5nb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kızdırılmış kızdırılmış

Su verilmemiş çelikim ben

Bir damlacık suya değsem 

Volkanlarca patlarım

(Kadıköy / İstanbul - 1976)', 'Kızdırılmış kızdırılmış Su verilmemiş çelikim ben Bir damlacık suya değsem  Volkanlarca patlarım (Kadıköy / İstanbul - 1976)...', ARRAY['Türk Edebiyatı','Şiir','Zekâi Budak']::text[], 8.5, '{"poet":"Zekâi Budak","poet_slug":"zek-i-budak","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ben-227-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mevsimleri Yaşadım Sensiz', 'mevsimleri-yasadim-sensiz-eyup-selahattin-dalkiran-kh07n', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seni düşünürken

Üç mevsimi yaşadım

Güneş varken

Sanki sevgin ısıttı

Yağmur yağarken

Hasretin ağlattı

Kar yağarken 

Seni aradım

Sevginle,dudaklarınla

Isınmak için bir tanem.', 'Seni düşünürken Üç mevsimi yaşadım Güneş varken Sanki sevgin ısıttı Yağmur yağarken Hasretin ağlattı Kar yağarken  Seni aradım Sevginle,duda...', ARRAY['Türk Edebiyatı','Şiir','Eyüp Selahattin Dalkıran']::text[], 8.5, '{"poet":"Eyüp Selahattin Dalkıran","poet_slug":"eyup-selahattin-dalkiran","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/mevsimleri-yasadim-sensiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bitmez Bitanem', 'bitmez-bitanem-sacide-yaylaz-hm84d', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu sevda bu yürekte bitmez bitanem

Yollar uzak olsada kavuşmak zor olsada

Gözlerin gözlerimde,gözlerim gözlerindeyse

Bu sevda bu yürekte bitmez bitanem.

Umutsuz bir aşk olsada sevmeler sevgiler

Biliyorumki sevginin gücü herşeyi yener

Yeterki bu can  çıkmasın bu bedenden

Bu sevda bu yürekte bitmez bitanem.', 'Bu sevda bu yürekte bitmez bitanem Yollar uzak olsada kavuşmak zor olsada Gözlerin gözlerimde,gözlerim gözlerindeyse Bu sevda bu yürekte bit...', ARRAY['Türk Edebiyatı','Şiir','Sacide Yaylaz']::text[], 8.5, '{"poet":"Sacide Yaylaz","poet_slug":"sacide-yaylaz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bitmez-bitanem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadıköy vapurunda.', 'kadikoy-vapurunda-ercan-akbay-3u2ee', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aldırmadım,kendi karnımın açlığına,

   Simit atıp martıları doyurdum.

   Onlar da şaşıp kaldı,gözümün tokluğuna......

                                                Temmuz.....2004', 'Aldırmadım,kendi karnımın açlığına,    Simit atıp martıları doyurdum.    Onlar da şaşıp kaldı,gözümün tokluğuna......                       ...', ARRAY['Türk Edebiyatı','Şiir','Ercan Akbay']::text[], 8.5, '{"poet":"Ercan Akbay","poet_slug":"ercan-akbay","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kadikoy-vapurunda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Göklerin Kapısı', 'goklerin-kapisi-guzin-osmancik-nkfr4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Göklerin kapısı altın baklava

Kalbim çırpınır yana yana.

Erenler zikirle çıkarlar sana

Banada nasip et onu Allah''ım

Yedi yedi çıkılır bu yol

Önce kırılır kanat kol

Sağ, sol kanatlar kırklar.

Bir sırada bana ver Allah''ım

Önce turuncu renkli havuz.

Sonra fosfora boyanır beden

Kuşanırken kılıç cepken

Aç zincirleri bana da Allah''ım

Birer birer açılır alemler.

Alın yazısından başlayan kader

Kudret denizi, Makam-ı Mahmut, İndi İlâhide 

Son bulur varlık, bir ağacın dibinde

Artık ne kapı kaldı ne de melek

Dünya âlem neme gerek

Biri sende, ikisi bende kalsada

Onları da sana vermeyi nasip et Allah''ım

                                              Sonram', 'Göklerin kapısı altın baklava Kalbim çırpınır yana yana. Erenler zikirle çıkarlar sana Banada nasip et onu Allah''ım Yedi yedi çıkılır bu yol...', ARRAY['Türk Edebiyatı','Şiir','Güzin Osmancık']::text[], 8.5, '{"poet":"Güzin Osmancık","poet_slug":"guzin-osmancik","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/goklerin-kapisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalancı', 'yalanci-aysegul-bayrak-n0j3i', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Senin gözlerin

Senin dillerin

Senin sevginde

Yalanmış yalan', 'Senin gözlerin Senin dillerin Senin sevginde Yalanmış yalan...', ARRAY['Türk Edebiyatı','Şiir','Ayşegül Bayrak']::text[], 8.5, '{"poet":"Ayşegül Bayrak","poet_slug":"aysegul-bayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yalanci-46-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlenen İstanbul ''dur Gene de', 'ozlenen-i-stanbul-dur-gene-de-zek-i-budak-gk7md', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir Hasselt akşamında

Dolaşmak şöyle kenti bir

Uzaktaki sevgiliye

Göz etmek usullacık

Sonra beş adımda aşıp aşkı

Sevişeni seyre koyulmak

Yummak gözlerini şöyle bir

Yummak ve de hep düşünmek

Ki ikinci yaşamdır o

Napoliten bir kahvede

Hacht birayı yudumlamak

Ama nerde ihtişamı

Cânım Çiçek Pasajımın

Kokoreçi, fıstığı

Ve fıçı birasıyla

Ah İstanbul sen benim

Gözbebeklerimdesin hep

(Hasselt / BELGIQUE - 1977) 

(Bu şiir, Çiçek Pasajın çöküşünden çok evvel 

Belçika ''nın Hasselt kentinde yazılmıştır.)', 'Bir Hasselt akşamında Dolaşmak şöyle kenti bir Uzaktaki sevgiliye Göz etmek usullacık Sonra beş adımda aşıp aşkı Sevişeni seyre koyulmak Yum...', ARRAY['Türk Edebiyatı','Şiir','Zekâi Budak']::text[], 8.5, '{"poet":"Zekâi Budak","poet_slug":"zek-i-budak","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ozlenen-istanbul-dur-gene-de-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben', 'ben-sacide-yaylaz-ktip1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dün sevmedim

Bugün sevmiyorum

Yarın sevmeyeceğim

Ya sonra

Belki sevebilirim..', 'Dün sevmedim Bugün sevmiyorum Yarın sevmeyeceğim Ya sonra Belki sevebilirim.....', ARRAY['Türk Edebiyatı','Şiir','Sacide Yaylaz']::text[], 8.5, '{"poet":"Sacide Yaylaz","poet_slug":"sacide-yaylaz","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ben-228-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Arkadan Ücretini Gönderemeyen Var mı?', 'arkadan-ucretini-gonderemeyen-var-mi-mehme-arslan-m7t2z', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'istatistiklere gerek yok

dolmuş ücretlerinin veriliş şekline göre de

nerede olduğunu kestirebilirsin

yabancı da olsan

sonra verirsin diyorsa şoför

bil ki elli haneyi geçmeyen bi köydesin

indikten sonra veriyorsan yolculuk bedelini

anadolu''nun orta ölçekli bi ilçesindesin

ayağını basar basmaz istiyorsa şoför ücreti

büyükşehire hoşgeldin

bu reçete aşklar için de geçerlidir.

25/12/2005', 'istatistiklere gerek yok dolmuş ücretlerinin veriliş şekline göre de nerede olduğunu kestirebilirsin yabancı da olsan sonra verirsin diyorsa...', ARRAY['Türk Edebiyatı','Şiir','Mehme Arslan']::text[], 8.5, '{"poet":"Mehme Arslan","poet_slug":"mehme-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/arkadan-ucretini-gonderemeyen-var-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlamak', 'anlamak-murat-i-lgun-1jrxb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Baktı  zil  zurna  sarhoş kocasına

Nefret  acıya  döndü  birden

Acısı  gözyaşına,

İnce  ince  yağan  yağmur

Şarkı  söyledi  kederle

Ağladı  kadın

sesini  katıp  yağmurun  sesine,

Gökyüzü  değil

Dünya  ağlıyordu  onunla

Kocaman   gözyaşı  olmuştu

Dışardaki  evler

Bahçedeki  ağaçlar

Her  yer,

Baktı  yılların  yorgunluğuyla  kocasına

Anlamak  istiyordu  artık  onu

Acılara  katlanmak  için  anlamak,

Bir  dikişte  içti  masada ki  kadehi

Ve  sonra  tüm  şişeyi

İki  büyük  rakı  daha  vardı  dolapta

Masaya  getirip  baktı

Bakar  gibi  kanlı  bıçaklı  düşmanına

Tüm  ömrüne  ağladı  kadın

Zorluklarla  geçen  tüm  yıllarına

Ne  var, dedi

Ne  var  bunu  içmekte

Hayatımızı  zehir  etti,

anlamak  istiyordu  artık

Sadece  anlamak

Ve  bitirdi  iki  büyük  şişeyi  gözyaşlarıyla

Sabah  uyanamadı  kadın

Uyandı  ama  adam,

Bekledi  bir  gün

Ağzına  bir  damla  içki  sokmadan

Alkol  komasından  ölen

Bekledi   karısının  cesedi  başında,

Tek  çiçekte  kurumuştu  artık

İçinde ki  bozkırda,

Çıkartıp  sakladığı  silahını

Vurdu  tüm  boş  şişeleri,

Şimdi  ayaklarının  dibinde  yatan  karısı

Gözleri  boşluğa  bakan  cesediyle,

Neden  diyordu  neden, neden? 

Boğazını  sıkıp  duruyordu

Cevabını  bir  türlü  veremediği  bir  soru,

Dayayıp  birden  silahı  alnına

Bastı  tetiğe

Ve  başbaşa  kaldı  iki  ceset

Kırılmış  içki  şişeleriyle.', 'Baktı  zil  zurna  sarhoş kocasına Nefret  acıya  döndü  birden Acısı  gözyaşına, İnce  ince  yağan  yağmur Şarkı  söyledi  kederle Ağladı  ...', ARRAY['Türk Edebiyatı','Şiir','Murat İlgün']::text[], 8.5, '{"poet":"Murat İlgün","poet_slug":"murat-i-lgun","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/anlamak-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidiyor akuba / yor gezgini...', 'gidiyor-akuba-yor-gezgini-zafer-zengin-etnika-5u227', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '.

şehir ismi olur bir çiçek; 

akuba’ya gül düşüyor

mavi misketlerin sesinde

gidiyor akuba

köşeli yazıların dilinde

yuvarlanmayın

sarılırsınız

çevre mavzer

cevre kaleler içinde

dayanır kapınıza sızı

koç başının gülüşünde

kapıları kırılıyor şehrimin

resim çiziyor alevler buluta

yarım kalan şiirler bitiyor

eli şairi kaybediyor



susuz çamaşır kirini sevmişken; 

lekelemeli kendini

hırsı var ademden

söz kin düğümü

lekeyi kesmeli

odun iskelesine merhaba; 

öff çeker

ağların gümüş sesi

cep çakısı kalamar diler

gökyüzü bulup

sürtünse

çocuk atsa yere

çakmasın ışık

gözleri karanlıkta

büyü bebek

sana karakterler beklettik



chopin düşünürken; 

elimi kesmeyin

her tuşun ardında

varsın sekizde olsa notayla

besteler yapıyorum zamana

dayayın kulağınızı

göğsümün ortasına

-yaşıyor, buz getirin

enlemi kaydıkça

geriliyor kışta

uçmayı öğreniyor

buz tutan yerin kayganlığında

hepsi tekrar

nefes almayın…

28 11 2005

.', '. şehir ismi olur bir çiçek;  akuba’ya gül düşüyor mavi misketlerin sesinde gidiyor akuba köşeli yazıların dilinde yuvarlanmayın sarılırsını...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/gidiyor-akuba-yor-gezgini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostluğun Resmini Çizebilirmisin', 'dostlugun-resmini-cizebilirmisin-sacide-yaylaz-xcfl9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çizebilirmisin bana

Dostluğun resmini

Hangi rengi kullanırdın

Gökyüzü mavisini mi

Gece mavisini mi

Dur bir düşün bakalım

Yoksa güneşin rengini mi

Sıcacık içimizi ısıtan

Tuale sığarmı

Çizebilirmisin bana

Dostluğun resmini...', 'Çizebilirmisin bana Dostluğun resmini Hangi rengi kullanırdın Gökyüzü mavisini mi Gece mavisini mi Dur bir düşün bakalım Yoksa güneşin rengi...', ARRAY['Türk Edebiyatı','Şiir','Sacide Yaylaz']::text[], 8.5, '{"poet":"Sacide Yaylaz","poet_slug":"sacide-yaylaz","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/dostlugun-resmini-cizebilirmisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Göster Bana Ey Kitap', 'goster-bana-ey-kitap-suna-aras-hnbje', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gözlerinin gezindiği her karede aşk vardı

Gökyüzü görünmüyor dedi kadın

Kucaklayıp korkusunu kalkmıştı.

Aşk dedim

Kanatlansa sığmaz göğe göğün dar

Gözlerime gönderdiği bakışlar

İçimi acıtmıştı.

Bir parmak yalnızlıktı giden

Bedeninin sığıntısı penguen

Gölgesinde ömrünün ağırlığı

Başı adımlarından kalkmayan bir yaşam

Hayat

Sadece ona anlatılandı.

Tapındığı hiçbir kitapta yoktu

O iblisin öz kızı

Bir kalın günahtandı.

Işığı yasaklanmış bir canlı daha göster

Göster bana ey kitap.', 'Gözlerinin gezindiği her karede aşk vardı Gökyüzü görünmüyor dedi kadın Kucaklayıp korkusunu kalkmıştı. Aşk dedim Kanatlansa sığmaz göğe göğ...', ARRAY['Türk Edebiyatı','Şiir','Suna Aras']::text[], 8.5, '{"poet":"Suna Aras","poet_slug":"suna-aras","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/goster-bana-ey-kitap-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Düşündüren', 'beni-dusunduren-rahim-recep-akdora-jd7yy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'dilini yozlaştırır, utanır dininden

neymiş ki onun için vatan

ya bayrak

çık sokak ortasında yak

bir kadındı sokak ortasında dövülen.

(kadın dövülmez, biliriz hepimiz!)

sorguladık aylarca

aylarca görüntüledik

insanlık aradık

ezilmişlik aradık

küçümsenme aradık.

Kimdi bu kadını döven? 

bir polis

o polis kim

benim oğlum, senin kardeşin

görevi yasak ihlallerinin önlemek! 

senin, benim huzurumuzu korumak

sahi biz neden bunca hor görürüz polisimizi.

Görevi huzurumuzu korumaksa

Neden hep onu suçlu görmek isteriz? ! 

Bir nedeni var da ben mi bilmiyorum  yoksa

evet ben de evliyim. 

benimde var eşim

o da kadın 

o kadın çok geçmiştir Beyzıt meydanından

onu ne ben dövdüm

ne bir başkası 

ne de sokak ortasında polisler

sahi o kadını polisler neden dövmüşlerdi? ! 

tek taraflı hakimlik olmaz hemşehrim

Polisin:

''izinsiz gösteri yapmak yasalarımıza aykırıdır

dağılın arkadaşlar! ''

haykırışını duydun mu? 

duymadın çünkü orada yoktun.

medya bozuntuları da vermediler bu yakarışı.

efendileri buna izin vermezler

görevleri huzurumuzu koruyanlara çamur atmak

bunu emrediyor AB den gelen telefonlar

birde bayrak olayımız vardı Mersinde bir yerde

hani ''küçük çocuklar'' 

büyük ağabeylerinin ellerine tutuşturduğu bayrağımızı 

ayakları altına almışlardı.

sahi o çocukların eline bayrağımızı tutuşturanlar kimlerdi? ! 

hani kravatlı falan kişiler dediler de 

sonra kimse üstünde durmadı

gündemi 

bayrağımızı ayak altından kurtaran polisin alacağı ödül almıştı.

bir de bir maç olayımız var 

göstermiştik elimizden gelen çabayı

suçlamak için kendimizi 

''ulusal çıkarlarımızı koruyacaksak onu en iyi biz koruruz! '' diye

neredeyse asacaklardı Fatih hocayı

futbolcularımızı hain yaptılar neredeyse

sahi ne demeli bazı kanalların bu gayretine? ! 

bir de Orhan Pamuk çıktı karşımıza

hani çok okunan bir romancı varmış ya

kucağında mercimekleri görünce çüküsü kalkmış adamın

gitmiş avrupada: 

''Türkler bir milyon Ermeni, otuz bin Kürt katlettiler'' demiş.

defalarca toplu mezarlar bulundu doğuda

kemikleri defalarca  dünya aleme gösterildi.

ekmeğimizi yemiş bu kalem bozuntusu

nereden geldiyse beynini kemiren bit

inkar ediyor otuzbeşbin vatanı uğruna can vermiş şehidimizi

düpedüz yalan söylüyor it.

bir silkinelim arkadaşlar

kendimize gelelim uyanarak para sevdasından

görüyoruz AB li O çocukları gelip bizim yargımıza karışıyorlar

sahi o AB ciler kimi kere neden Edirne''ye gelmiyorlar

Tekirdağ''ına da gidebilirler pis kıçlarını güneşe göstermek için

uçakları o kadar süratli ki ancak Diyarbakır’da durabiliyorlar.

ve bizim bazı yazanlarımız hep onlara doğru yontuyor kalemlerini

bazı yorumlayanlarımız onlar lehine sarf ediyorlar sözlerini

son zamanlarda

işte bunlar beni düşündüren 

siz de benim gibi düşünüyor musunuz? 

yanılıyor muyum yoksa ben?', 'dilini yozlaştırır, utanır dininden neymiş ki onun için vatan ya bayrak çık sokak ortasında yak bir kadındı sokak ortasında dövülen. (kadın ...', ARRAY['Türk Edebiyatı','Şiir','Rahim Recep Akdora']::text[], 8.5, '{"poet":"Rahim Recep Akdora","poet_slug":"rahim-recep-akdora","theme":"Türk Şiiri","is_hero":false,"total_lines":78,"source_url":"https://www.antoloji.com/beni-dusunduren-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğamadım sabahına', 'dogamadim-sabahina-elazigli-mustafa-kaya-n9ovc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'hasretimi yükledim

bulutlara.

güngörmez soluklarım,

kan kirpiklerim,

dönüştü yağmura.

dudaklarına dizildim

damla olup,

sır dolu gökyüzünden.

gezindim,

suçlu ve hiçlikle .

yalnızlaştım

kokusuz sahillerde

ve,

denizimi kaybettim

bir martı sessizliğinde.

doğamadım,

dağ gibi sağlam ruhuna

senin sabahına…

Mustafa kaya

27.12.2005 / Sarayburnu

www.mustafakaya.net', 'hasretimi yükledim bulutlara. güngörmez soluklarım, kan kirpiklerim, dönüştü yağmura. dudaklarına dizildim damla olup, sır dolu gökyüzünden....', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/dogamadim-sabahina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zargana Balığıyım', 'zargana-baligiyim-metin-kaya-i-lhan-ip4nn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen; 

Sen hiç sabahın ilk saatlerinde

Karanlıkları henüz yırtmadan güneşin ışığı,

Bir tekneden baktın mı bir tanem

Denizde yakamozlar yaratan zargana balıklarına…

Hiç gördün mü? 

Kapkara deniz suyunda ki ay ışığı parıltılarını

Hiç duydun mu o esrarlı yakamozun sesini? 

Şırıltılar atarak ilerlerken zargana balıkları 

Teknenin kenarında sana ortak gibi

Karanlıkların esrarında...

Ama sonlarını düşünmeden ilerlerken

Teknenin kenarında yakamozlar saçarak

Az sonra bir tuzakta buluşacaklarını...

Tıpkı benim gibi

Tıpkı yüreğimdeki yakamozlar gibi...

Düşeceğimi düşünmeden senin tuzağına

Bilmeden yaklaşıyorum yaşamımın uzağına...

Yakamozlar saçarken yüreğimdeki titreşimler

Senden aldığı ay ışığı misali 

Sevginin kucağında can vermek için yarışıyor sanki zamanla

Tekne sen, ay ışığıda senden geliyor..

Sabahın karanlığını yırtmadan güneşin sımsıcak ışıkları

Sevdam okyanus sanki küçücük Karadeniz sahillerinde

Ecelim beklerken beni 

Bilmeden.. bilemeden yarışıyorum seninle sanki....

Hani? 

Tekne sendin.. ay ışığı senden geliyor ya hani? 

Seni sevindirmek için 

Yakamozlar saçıyorum ya sana şirin görünmek adına....

Ecelimin sonuna sevinçle koşuyorken karanlık sularda

Bakışlarımı göremezsin, sevgimi duyamazsın bilmeden..

Ölüme koşarak gidiyorum sevgilerimi sunarak sana

Tuzağına düşeceğim anı beklerken sen

Sana sevgilerimle son bakışlarımı atıyor olacağım ben...

Çünkü; 

Yakamozlarımın beni ele verdiğini bilmiyorum...

Bir zargana balığıyım ben....

                                                             (10.10.2005   Trabzon)', 'Sen;  Sen hiç sabahın ilk saatlerinde Karanlıkları henüz yırtmadan güneşin ışığı, Bir tekneden baktın mı bir tanem Denizde yakamozlar yarata...', ARRAY['Türk Edebiyatı','Şiir','Metin Kaya İlhan']::text[], 8.5, '{"poet":"Metin Kaya İlhan","poet_slug":"metin-kaya-i-lhan","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/zargana-baligiyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Nefes İstanbul 1', 'bir-nefes-i-stanbul-1-isik-aktas-r0aaz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'deli dedi görenler

yağmurun altında sigara mı içilir

içilir tabi

yine aşk geldi

bilmezlerki

İstanbul''du o

bir nefes İstanbul

ve

gönlüme yar düşünce

deniz

hüzün yeşili gri...

Ellerimde başka sevda kokusu

yüreğimde eski aşkın öyküsü

aklım lal oldu artık

rüzgara karşı

siyah saçlarımda bir yalnızlık türküsü

savruluyor

savruluyor

savruluyor...

                      27 Aralık 2005-12.45 / Beyoğlu', 'deli dedi görenler yağmurun altında sigara mı içilir içilir tabi yine aşk geldi bilmezlerki İstanbul''du o bir nefes İstanbul ve gönlüme yar ...', ARRAY['Türk Edebiyatı','Şiir','Işık Aktaş']::text[], 8.5, '{"poet":"Işık Aktaş","poet_slug":"isik-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bir-nefes-istanbul-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin derdinle soluk benzim', 'senin-derdinle-soluk-benzim-elazigli-mustafa-kaya-zapqz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'her hüznümü,

başka bir ağaçta yaşarım.

yemyeşil bayırlar

otlaklar kızıllaşır.

katlanırım acılara

nemrud’un ateşi bile olsa.

bir yola çıkar gibi

dizilmiş heyecanlarım

hayatımın müziği

sana güzelce yakalandığım.

beni ellerinle alkışlayan

sevginle kucaklayan 

ruhunun içindeki dünyaya,

gönlümü de alarak

akıcı bir ateş gibi

geliyorum,

resmini çektiğim odana 

sessizleştiğin gecene

duvarlara yaslanan yalnızlığına

bizi ışığıyla vuracak

mehtapla geliyorum..

saçlarını tutmak,

son sigaranı yakmak,

aynı minderi paylaşmak,

ağaçların huzuruna çıkmak için

geldim

sensiz uykulara alışkın değilim

ıslandıkça o kahve gözlerin

senin derdinle soluk benzim..

Mustafa kaya

27.12.2005 /  kavacık

www.mustafakaya.net', 'her hüznümü, başka bir ağaçta yaşarım. yemyeşil bayırlar otlaklar kızıllaşır. katlanırım acılara nemrud’un ateşi bile olsa. bir yola çıkar g...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/senin-derdinle-soluk-benzim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gemi', 'gemi-metin-kaya-i-lhan-rffnc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir gemi gidiyor

Sonsuzluk kokan sevdamın üzerinde; 

Bacasından aşk tütüyor...

Yakamozlar saçıyor  suyu yardığı yerden

Yakıtında ben varım; dumanında sen… 

Bir gemi gidiyor

Sonsuzluk kokan sevdamın üzerinde; 

Pervanelerinde hayat dönüyor...

Sevgiler saçıyor iz bıraktığı bembeyaz köpüklerde

Dümeninde ben varım; rotasında sen...

Bir gemi gidiyor 

Sonsuzluk kokan sevdamın üzerinde; 

Etrafında balıklardan halkalar...

Gülerek oynaşırken sevgi dolu bakarak

Gözlerinde ben varım; yüreklerinde sen...

Bir gemi gidiyor

Sonsuzluk kokan sevdamın üzerinde; 

Yelkenleri kalbim gibi kabarmış; 

Mutluluğa doğru pupayelken uçarken

Kumaşında ben varım; rüzgarında sen...

Bir gemi gidiyor

Sonsuzluk kokan sevdamın üzerinde; 

Dümen suyunda gözyaşlarım köpük köpük...

Güvertesine konmuş martıların boynu bükük...

Kalktığı limanda ben varım; son limanda sen...

Bir gemi gidiyor

Sonsuzluk kokan sevdamın üzerinde; 

Hüzünlü bir kuğu gibi beyaz beyaz, mavi sular üstünde...

Gözlerinden yaşlar damlıyor sanki..

Gözpınarlarında ben varım; düştüğü okyanusta sen...

Bir gemi gidiyor

Sonsuzluk kokan sevdamın üzerinde; 

Duman tütüyor bacasından, hasret sancısı gibi...

Gökyüzüne ismini yazıyor bir tanem,

Kaleminde ben varım, mürekkebinde sen...

Bir gemi gidiyor

Sonsuzluk kokan sevdamın üzerinde; 

Dalgalarını sayıyorum birer birer

Bir ömür sayar gibi

İlk nefesinde ben varım, son nefesinde sen...

                                                            (12.11.2005     Trabzon)', 'Bir gemi gidiyor Sonsuzluk kokan sevdamın üzerinde;  Bacasından aşk tütüyor... Yakamozlar saçıyor  suyu yardığı yerden Yakıtında ben varım; ...', ARRAY['Türk Edebiyatı','Şiir','Metin Kaya İlhan']::text[], 8.5, '{"poet":"Metin Kaya İlhan","poet_slug":"metin-kaya-i-lhan","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/gemi-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Karanfil Gülümsüyor', 'i-ki-karanfil-gulumsuyor-ercan-cengiz-143tv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İhanetin gizeminde mi kalır

Pervasız izini sürenler

Hava sisli 

Dumanın çökmesine kalmış

Yapılan o ince hesaplar 

Tutmayabilir de

Beyaz Dağ''da iki karanfil

Güneşte,

Yağmurda

Rüzgarlara karşı

Baş başa vermiş iki karanfil

Bir başka mevsimdedirler

Dersim''in ak yüzünde

Gülümserlerken

Bakılmazdı 

Dumanın kaplamasına

Ve ihanetin gizemine

Vura vura

Sabırla

Dağlara yüklenmiş 

İki karanfil

İradenin zaferinde

Birlikte yoğrulurlar...', 'İhanetin gizeminde mi kalır Pervasız izini sürenler Hava sisli  Dumanın çökmesine kalmış Yapılan o ince hesaplar  Tutmayabilir de Beyaz Dağ''...', ARRAY['Türk Edebiyatı','Şiir','Ercan Cengiz']::text[], 8.5, '{"poet":"Ercan Cengiz","poet_slug":"ercan-cengiz","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/iki-karanfil-gulumsuyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ninem ve Çınar', 'ninem-ve-cinar-metin-kaya-i-lhan-dth5p', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Tam 90 yaşındaki ninemden dinledim; bu aşk öyküsünü...

Yaşanası aşklar yaşamış ninem...

Uzun ömrünün kaynağı bu olsa gerek? 

İnsanı sevmemiş ninem; bahçede gökyüzünü delen çınar ağacını sevdiği gibi...

Evlâdım; derdi bana, bu çınar ağacını babam dikti...

Bana arkadaş olması için... En güzel arkadaş, ağaç olur diyerek...

Şimdi hayatta olmayan canyoldaşlarım ile tanıştık bu ağacın

Serin mi serin gölgesinde...

Oyunlar oynardık etrafında; incitmeye korkarak dost ağacımızı...

Bizim idi o, arkadaşımızdı bize gölgesini veren...

Sessizce konuşurdu bizimle sanki; güneşi bizim için gölgelerken...

Rahmetli anacığım kızınca bana, dalında konaklardım bu ağacın...

Anamın öfkesinin dinmesini beklerken...

Deden ile işte şu dalın altında, birbirimize vurulduk yavrum...

Bak dal bize gülümsüyor görüyormusun? 

Ben hissediyorum...

Senin bilmeyeceğin şekilde...

Yüzüğümüzü bile bu ağacın altında taktı büyüklerimiz...

Ömrümüz uzun olsun bu ağaç gibi diyerek...

Ne yazık ki deden ilk ve tek kez aldattı beni 

Bu dostumla başbaşa bırakıp ebediyete göçerek...

Ne rüzgarlarda sallandı ama yıkılmadı işte...

Ondan alırdık hayata bağlılığımızı, direnmeyi ve sevgiyi

Nasıl kurumasına izin veririm a yavrum, nasıl esirgerim ilgiyi...

Her dalında babam var, her yaprağında anacığım...

Tepesinden hâlâ daha bakar bana sımsıcak sevgi ile kocacığım...

Bunu yaşatmalıyız yavrum; kurumak istesede...

Gözyaşlarımla sularım onu ben yağmurlar yetmesede...

Benim hayatım bu ağaç; 

Hani derler ya insan hayali kadar yaşar diye...

Ben ölmeyeceğim yavrum, ölmeyeceğim..

Tıpkı bu çınar gibi yaşayacağım bende, ihanet etmeyeceğim arkadaşıma...

Ondan önce ölürsem eğer yavrum, işte şu dalı koparıp koyun

Yanı başıma..

Deden bekliyor beni bu dalın arkasında...', 'Tam 90 yaşındaki ninemden dinledim; bu aşk öyküsünü... Yaşanası aşklar yaşamış ninem... Uzun ömrünün kaynağı bu olsa gerek?  İnsanı sevmemiş...', ARRAY['Türk Edebiyatı','Şiir','Metin Kaya İlhan']::text[], 8.5, '{"poet":"Metin Kaya İlhan","poet_slug":"metin-kaya-i-lhan","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/ninem-ve-cinar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendi Yüzüne Küskün Çocuk', 'kendi-yuzune-kuskun-cocuk-melih-coskun-xu6td', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen, 

Kendi yüzüne küskün çocuk 

En güzeli sendedir sevmelerin 

İlk aşk gibi 

İlk pişmanlık gibi 

İlk sürgün gibi

Kaybolup gitmelerim gibisin 

Kimselerin bilmediği ıssızlığa, 

Ve ansızın çıkıp gelmelerim 

En büyüğü sendedir kederlerin 

Zamansız uzanmak gibi 

Toprağın sırılsıklam koynuna 

Mutluluk; 

Hiçbir zaman boyanmamış resim 

Sendedir bütün renkler...

Kederden gebermek de senindir 

Başkaldırıp kader diye sana dayattıkları yalana direnmek de

Sen,

Kendi yüzüne küskün çocuk

Herkes kadar seninde hakkındır 

Hakça yaşamak

Ve bölüşmek her lokmanı korkmadan...

2003', 'Sen,  Kendi yüzüne küskün çocuk  En güzeli sendedir sevmelerin  İlk aşk gibi  İlk pişmanlık gibi  İlk sürgün gibi Kaybolup gitmelerim gibisi...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/kendi-yuzune-kuskun-cocuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Buz parçası', 'buz-parcasi-metin-kaya-i-lhan-hgjwy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İçtiğim kadehlerde sımsıcak buz parçasısın

İçtikçe yüreğimde alev alev yanarsın..

Yüreğimdeki sevdan eritirken ruhumu 

Yudumlarım sevgini yüreğimde kanarsın...

..

Yanarken ruhum sensiz; sen hep uzaklardasın

Tane tane saydığım eriyen buzlardasın

Sen eriyip kadehlerle ciğerime akarken

Uzakta olsan bile buz gibi ruhumdasın...', 'İçtiğim kadehlerde sımsıcak buz parçasısın İçtikçe yüreğimde alev alev yanarsın.. Yüreğimdeki sevdan eritirken ruhumu  Yudumlarım sevgini yü...', ARRAY['Türk Edebiyatı','Şiir','Metin Kaya İlhan']::text[], 8.5, '{"poet":"Metin Kaya İlhan","poet_slug":"metin-kaya-i-lhan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/buz-parcasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Merdivensiz Bıraktın', 'merdivensiz-biraktin-metin-kaya-i-lhan-mcwec', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hicranımın ahına dağlar eridi

Tek senden ses gelmedi, beni yalnız bıraktın

Ağladım, feryad ettim boş yere... Yazık

Beni dipsiz kuyularda merdivensiz bıraktın...

...

Dağlar erisede, köpürsede denizler

Duymak istemeyene bir şey hissettiremezler...

Yaşlarımla sel alacak vücudumu...Yazık

Beni kör kuyularda merdivensiz bıraktın...

...

Tutunacak bir dal arar iken kabaran denizlerde

Kendimi buldum birden karanlık dehlizlerde

Kurtulmak için çabalarken boşuboşuna..Yazık

Beni uçsuz bucaksız kuyularda sensiz bıraktın...', 'Hicranımın ahına dağlar eridi Tek senden ses gelmedi, beni yalnız bıraktın Ağladım, feryad ettim boş yere... Yazık Beni dipsiz kuyularda mer...', ARRAY['Türk Edebiyatı','Şiir','Metin Kaya İlhan']::text[], 8.5, '{"poet":"Metin Kaya İlhan","poet_slug":"metin-kaya-i-lhan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/merdivensiz-biraktin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sayıklama - I', 'sayiklama-i-kenan-mim-eryigit-kk8s4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '____________Nerden çıktı bu rüzgar? 

____________Bir ağaç boynunu büktü 

____________Önce yapraklar

____________Sonra kuşlar uçuştu..

____________Meydan yere düştüm 

____________Yandı ciğer tutuştu..

____________Nerden çıktı bu rüzgar? 

Ateş düştüğü yeri yakar.

Su kendi yoluna akar.

Anlamsız sorunun cevabını

Kim verir, kim bakar? ..

Bu işin günahı sevabını

Kim ölçer, kim tartar? 

Ateş düştüğü yeri yakar.

____________''Yere düşünce cevher

____________Kaybeder mi kadrü kıymetten? ''

____________Sen asıl  haber ver

____________Büyük kıyametten! 

Akmayan sular gibi durgunum.

Yoldan geldim yorgunum.

Yandı yürek yandı

Ben tescilli vurgunum.

Akmayan sular gibi durgunum.

____________Ne sihirdir ne keramet

____________''Küçük lokma ye, küçük laf et..''

____________Bela geliyorum der mi? 

____________İstersen sen bu yolda devam et.

Havalar da soğudu, üşüyorum.

Büyük boşluk, mavera..

İçine düştükçe, düşüyorum.

Öteler ötesinde ne var? 

Semada kaç tane kara delik? 

Karıştırma-eşeleme

Dünyada bunun  adı: delilik

Akıl kıt, beyin nokta kadar.

Sığdıramam hiçbir yere 

Düşüncemin ufku çok dar.

Kara bulutlar perde perde

''Parmak ayı gösterirken

Baktığım o yerde

Hep parmağı görmüşüm..''

Dört bir yanımı çözülmez

Aşılmaz duvarla örmüşüm..

____________Nerden çıktı bu rüzgar? 

____________Bir ağaç boynunu büktü 

____________Sarı yapraklar rüzgarla raksetti.

____________Tek damla suda görüntü  aksetti

____________Ol mahiler göze  gözüktü

____________Nerden çıktı bu rüzgar? 

''Onlar ki; derya içindedirler

Deryayı bilmezler.''

Bu yaraya kimse olmaz melhem 

Bekleme, gözyaşın silmezler.

Daha var zamanı dediler

Kırklar yediler.. 

Beynimi yediler.

Tekir kediler..

Kırk küp kırkının da kulpu kırık

Ağla gözlerim ağla..

Hıçkırık üstüne hıçkırık..

Karalarını bağla..

Yeldeğirmenlerine savaş mı açılmış? 

Fesleğen kokuları ıtıra karışmış

Bu ne menem şeydir

Kafa yordum epeydir..

Çıkar baklayı ağzından çıkar

Sana hiç yakışmıyor bu tarz

Kim okur, kim bakar

Bu rica değil, bilfarz

…………………………………..

____________Nerden çıktı bu rüzgar? 

____________Bir ağaç boynunu büktü 

____________Önce yapraklar,

____________Sonra kuşlar uçuştu..

____________Meydan yere düştüm 

____________Yandı ciğer tutuştu.. 

____________Nerden çıktı bu rüzgar?', '____________Nerden çıktı bu rüzgar?  ____________Bir ağaç boynunu büktü  ____________Önce yapraklar ____________Sonra kuşlar uçuştu.. ______...', ARRAY['Türk Edebiyatı','Şiir','Kenan Mim Eryiğit']::text[], 8.5, '{"poet":"Kenan Mim Eryiğit","poet_slug":"kenan-mim-eryigit","theme":"Türk Şiiri","is_hero":false,"total_lines":77,"source_url":"https://www.antoloji.com/sayiklama-i-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özeniş', 'ozenis-zek-i-budak-75z04', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '- Ahmet RASİM ''e -

Üstat pek te ürkekmiş, birazcık fazla canım

Gün batarken ufukta bu telâş bu korku ne

''Geçe kalma erken gel, karışmam'' demiş hanım

Boş ver beyim n''olacak, iç bade bak keyfine

Şikâyetim olmazdı böylesi bir hatundan

Her akşam yollarımı bekleyecekse böyle

Müthiş bir haz alırdım bu her günki oyundan

Hiç bitmesin isterdim ne ilk ne de son perde

Oysa ne git diyen var, ne yolumu bekleyen

Yalnızlık acısına garip gönlüm neylesin

Hasretim o bir sese, her gün evden çıkarken

''Güle güle git'' desin, ''Akşam erken gel'' desin

(Kadıköy / İstanbul - Ağustos 1975)', '- Ahmet RASİM ''e - Üstat pek te ürkekmiş, birazcık fazla canım Gün batarken ufukta bu telâş bu korku ne ''Geçe kalma erken gel, karışmam'' dem...', ARRAY['Türk Edebiyatı','Şiir','Zekâi Budak']::text[], 8.5, '{"poet":"Zekâi Budak","poet_slug":"zek-i-budak","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ozenis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdalar', 'sevdalar-metin-kaya-i-lhan-ky9s6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'kollarımda kanatlanır hüzünlere sevdalar

yüreğime yaslanır 

bir dağa yaslanır gibi

nefesimde sonlanır kuru bir ömür gibi

sen olmayınca yanımda,

ruhumun hayat suyu bile kurur 

yaşatmaz beni, 

sana duyduğum sevdalar...

ayaklarım çekemez bu vücudu 

sensizliklerin kahrolası yüküyle

yüzümden düşen bin parçadır 

hasretinin ateşiyle

ellerimde mazim yüreğimde sen varken

nasıl yaşanır ki bilemem; 

nefesim sende olur

kalbim sende atarken...', 'kollarımda kanatlanır hüzünlere sevdalar yüreğime yaslanır  bir dağa yaslanır gibi nefesimde sonlanır kuru bir ömür gibi sen olmayınca yanım...', ARRAY['Türk Edebiyatı','Şiir','Metin Kaya İlhan']::text[], 8.5, '{"poet":"Metin Kaya İlhan","poet_slug":"metin-kaya-i-lhan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sevdalar-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlim Oku', 'i-lim-oku-timur-i-likan-ned6p', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İlim oku, ilimsiz kalma

At ilim okunu nice muhtaç gönüllere

Kimseyi ilimsiz bırakma

(28 Aralık 2005/ İstanbul)', 'İlim oku, ilimsiz kalma At ilim okunu nice muhtaç gönüllere Kimseyi ilimsiz bırakma (28 Aralık 2005/ İstanbul)...', ARRAY['Türk Edebiyatı','Şiir','Timur İlikan']::text[], 8.5, '{"poet":"Timur İlikan","poet_slug":"timur-i-likan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ilim-oku-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akrabayız', 'akrabayiz-mustafa-ceylan-xv71o', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '******Mitaku oyasin..! Biz hepimiz akrabayız..! ''

.....................................Kızıldereli Atasözü(Siyu Kabilesi) 

-I-

İki duvarız,

Akrabayız...

Çekilirsek kenara

Yere düşersin tavan...

Bozulur havan...

-II-

Kazmışssın kuyuyu sinemize

Döndükçe çıkrığın, doluyor kovan

Yukardan aşağı akmaz mı su...? 

Çölde mi kaldın yoksa...? 

Neden doyumsuzsun bu kadar...? 

-III-

Taş taş üstünde yükselip minare

Uzanır yâr''e...

Yükselen yere dayanır,

Ya düşen...? 

Bilmez misin bunu sen...? 

-IV-

Ayak, el, göz, kulak iki

Söyle bakalım

Tek mi seninki...? 

-V-

Tohumda başak, dalda yaprağız

''Böbürlenme boşuna dağım diye

Buluta değen karıncayız''

Yamaçların rüzgârı

Vız gelir bize...

-VI-

Piramitiz Mısır''da,

Sultanahmet'' te dikili taş...

Jülyen Sütunu''yuz Ankara'' da

Selimiye'' de Sinan...

Üst üste, yanyanayız

Yoktur birbirimizden şikâyetimiz

Görülmüş değil davamız

Çünkü, biz akrabayız...! 

Ya sen...?', '******Mitaku oyasin..! Biz hepimiz akrabayız..! '' .....................................Kızıldereli Atasözü(Siyu Kabilesi)  -I- İki duvarız, ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/akrabayiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yokluğunun Sarhoşuyum', 'yoklugunun-sarhosuyum-gulsen-agir-9rf7a', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yokluğunun sarhoşuyum

Hani onlar konuşurlar ya

Anlatıyorum, 

Bir ona, bir buna.

Yokluğunun sarhoşuyum

Hani onlar düşerler ya

Düşüyorum,

Bir çamura, bir suya.

Yokluğunun sarhoşuyum

Hani onlar yürürler ya

Sallanıyorum,

Bir o yana, bir bu yana.

Yokluğunun sarhoşuyum

Hani onlar gülerler ya 

Gülüyorum,

Bir kahkaha, bir kahkaha.

Yokluğunun sarhoşuyum

Hani onlar kederlenirler ya

Kederleniyorum,

Bir iç çekme, bir ağlama.', 'Yokluğunun sarhoşuyum Hani onlar konuşurlar ya Anlatıyorum,  Bir ona, bir buna. Yokluğunun sarhoşuyum Hani onlar düşerler ya Düşüyorum, Bir ...', ARRAY['Türk Edebiyatı','Şiir','Gülşen Ağır']::text[], 8.5, '{"poet":"Gülşen Ağır","poet_slug":"gulsen-agir","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yoklugunun-sarhosuyum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeter...!', 'yeter-cem-cagman-in84z', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'yeter çektirdiğin azap

bak da gör eserini

yaktın bütün bedenimi

kavrulmuş dala döndüm

ne rüyalar nede gerçek

bana huzur vermeyecek

bak ömür bitti bitecek

kurumuş göle döndüm

oyunundan bıktım artık

götürsen cennete bile

yeter çektiğim çile

erimiş muma döndüm', 'yeter çektirdiğin azap bak da gör eserini yaktın bütün bedenimi kavrulmuş dala döndüm ne rüyalar nede gerçek bana huzur vermeyecek bak ömür ...', ARRAY['Türk Edebiyatı','Şiir','Cem Çağman']::text[], 8.5, '{"poet":"Cem Çağman","poet_slug":"cem-cagman","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yeter-63-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanımdayken Sen..', 'yanimdayken-sen-zeliha-bicer-uxxe2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yanımda dururken sen 

Hani gelmişken, 

Hasretim bitmiş 

Sanırken ben.

Yanılmışım, desem

Gidişinin yükü varken,

Omuzlarımda.

Seni terketmek yine

Zor geliyor desem.

Desem ki; 

Gitme! 

Desem ki; hasretim

Desem ki; sevgilerim var

Haykırışlarımı içimde saklatma

Saklatma ey yar! ! 

Martılarım eşlik etsin bana

Salacak'' taki içmelerimize yine

Gitmesen, sen..

Gitmesen diyorum! 

Beni boğarken tüm bunlar

Gelsen bir bagbozumu yine bana

Gelmişsen diyorum hani

Gitme.. gitme.. gitme...', 'Yanımda dururken sen  Hani gelmişken,  Hasretim bitmiş  Sanırken ben. Yanılmışım, desem Gidişinin yükü varken, Omuzlarımda. Seni terketmek y...', ARRAY['Türk Edebiyatı','Şiir','Zeliha Bicer']::text[], 8.5, '{"poet":"Zeliha Bicer","poet_slug":"zeliha-bicer","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/yanimdayken-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mor takılmış / dışarıda hayat...', 'mor-takilmis-disarida-hayat-zafer-zengin-etnika-064e7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '.

ardından su dökülen bir kaç çeşit iş varken

sonuncusu geldi aklına

son bir yemek bırakıldı kapıya; 

siz birine ağlarken

ağlar çoğuna anneler

derinden

derinden

oyy guzum

yüzün öpem

mor takılmış

sonra dedi ki; 

bu kapalı alanda

bazen bir

bazen üç kalır yan yana

dışarı cıkarsam

gelmesin üstüme insanlar

korkuyorum abi

ağır gelir gülümseme

unuttum gülmeyide

çekilir perdesi göğün

gözleri gri bu yüzden

çekin ellerini yüzünden

mavi gülsün yeniden

oy guzum

gözün öpem

gül takılmış

dedi ki; 

yalıtıldı öykülerim

koptum ve ayrıştım korkuya

koşarken neler cıktı yoluma

anlatsam karanlık batar yanıma

sen dinleme abi

korkularım bana

anlar bilenler ‘gülmez

su can ‘şiirdir şimdi…

07 12 2005', '. ardından su dökülen bir kaç çeşit iş varken sonuncusu geldi aklına son bir yemek bırakıldı kapıya;  siz birine ağlarken ağlar çoğuna annel...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/mor-takilmis-disarida-hayat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzelim', 'guzelim-mustafa-ceylan-ahw1w', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gözlerin içimin yağmuru oldu

Gönül dağlarıma yağ be güzelim.

Bahar busesidir mahzun bakışın

Dalıma usulca değ be güzelim.

Bir baksan dert biter, kalmam hiç darda

Bulut yere iner, gezmez yukarda

Ay şafağı olup ala baharda

Kara gecelere doğ be güzelim.

Aşkın semasına yıldız ol çakıl

Yürek gümbürtünle iflâsta akıl

Kederlenme canım, göğsüme sokul

Çileni omzuma yığ be güzelim.

Kirpiğin altında ışıltı, sevinç

Benzeri bulunmaz, öylesi ilginç.

Sevdasız göklere havalanma hiç

Kuş olup avcuma sığ be güzelim.

Gözlerin Ceylan''ın ''mavi yağmur''u

Canına can katan, ışığı nuru.

Aramıza duvar ören gururu

Pamuk ellerinle sağ be güzelim.', 'Gözlerin içimin yağmuru oldu Gönül dağlarıma yağ be güzelim. Bahar busesidir mahzun bakışın Dalıma usulca değ be güzelim. Bir baksan dert bi...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/guzelim-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasret', 'hasret-mehmet-isik-m2026', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sensizliğin kaçıncı baharındayım,

Ateşteyim, kordayım,

Andıkça ismini,

Gördükçe hayalini,

Çıtırtılarla çalı gibi,

Tutuşmaktayım.

Alev saran orman gibi,

Cayır cayır yanmaktayım.

Kaç yıl oldu çiğ düşmeyeli,

Yapraklarım su görmeyeli,

Bahar yağmurlarını unuttum,

Gideli dallarımı kuruttun,

Olsun yinede gam değil; 

Geleceğinden umutluyum.

Eğer geldiğinde bulamazsan beni,

Kuruyan toprağımı sula,

Belki cismimi göremeyeceksin,

Çıkan yanık kokusu,

Sana ulaştıracak beni,

Buram buram hasret kokusu duyacaksın,

İşte o zaman sana nasıl yangın olduğumu anlayacaksın.', 'Sensizliğin kaçıncı baharındayım, Ateşteyim, kordayım, Andıkça ismini, Gördükçe hayalini, Çıtırtılarla çalı gibi, Tutuşmaktayım. Alev saran ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Işık']::text[], 8.5, '{"poet":"Mehmet Işık","poet_slug":"mehmet-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/hasret-314-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gar Lokantası', 'gar-lokantasi-zek-i-budak-dsci2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Baksana Yakup Baba haydi donat masayı

Kemancıya da söyle kuvvetli çeksin yayı

Önce şöyle bir ufak sonra ne varsa getir

Köfte fıstık pirzola az kavun biraz peynir

Boğazımdan bir ateş gibi akıp gitsin mey

Unutalım bu gece gamı kasaveti hey

Minik kar taneleri uçuşurken havada

Yüreğimiz ısınsın şu dar ahşap odada

Şakağımdan hararet vücuduma yayılsın

Coşup bayılsın gönlüm mutluluğa ayılsın

Şişedeki o sihir damarıma sürünsün

Herşey anlam kazansın herşey renge bürünsün

Gülle dolmuş sanayım virane bahçelerim

Bu esrarın camında renk bulsun gecelerim

O da ne Yakup Baba, sus artık hey kemancı

Kimdir karlar üstünde gezinen şu yabancı

Kömür kokulu garda kimi beklersin kadın

Bu halinle herkesi üzmek midir maksadın

Gök mavisi gözlerin sonsuzlara saplanmış

Ne o ağlıyor musun kirpiklerin ıslanmış

Sus ve hiç bir şey deme anladım derdin nedir

Seni bekleten zalim şimdi uzak yerdedir

Dönmez giden sevgili gün doğar tekrar batar

Gurbetten gelen sade hüzündür katar katar

Her vagon ümid dolu, her vagon kahır yüklü

Bilmem gelmeyenler mi bekleyenler mi haklı

Aşk denen tatlı hayâl bir çok kanlara girdi

Kimi intihar etti, kimi ise delirdi

Her katar bir yük yıkar ezilmiş yüreğine

Ve bir şeyler götürür hep derinden derine

Acep demir yığının poflaması nedendir

Senin derdin mi ya da onu böyle edendir

Kızgın siyah bacadan yükselen duman gibi

Dağıtmak mümkün olsa yürekten elemleri

Unutmamak ta acı, unutulmak ta acı

Hatıralar yürekte hiç dinmeyen bir sancı

Bekleyiş acısını ta derinden duyansın

Uyut eski arzunu yenileri uyansın

Siyah yaşmağı çıkar saçlarına güller tak

Unut artık geçmişi gelecek günlere bak

Ne o niye irkildin baktığın yönde ne var

Ardında neler saklar karla örtülü dağlar

Uzaktaki dumanla bir ümit mi belirdi

Giden geri gelseydi benim Ayşe''m gelirdi

Baksana Yakup Baba haydi donat masayı

Kemancıya da söyle kuvvetli çeksin yayı

Evvelâ iki ufak sonra ne varsa getir

Köfte fıstık pirzola çok kavun çok ta peynir

(Babaeski - 30 Ekim 1974)', 'Baksana Yakup Baba haydi donat masayı Kemancıya da söyle kuvvetli çeksin yayı Önce şöyle bir ufak sonra ne varsa getir Köfte fıstık pirzola ...', ARRAY['Türk Edebiyatı','Şiir','Zekâi Budak']::text[], 8.5, '{"poet":"Zekâi Budak","poet_slug":"zek-i-budak","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/gar-lokantasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Halim', 'halim-mustafa-ceylan-he4hq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dinmez bir uğultu kulaklarımda

Nerdesin ey melek, çıldıracağım...! 

Bıktım bu canımdan tövbe vallahi...! 

Vallahi kazanlar kaldıracağım...! 

Bilmiyor kimseler benim halimi

İçimdeki kabre koydum ölümü

Anlatsam derler ki: ''Ceylan ölü mü? ''

Kendi namazımı kıldıracağım.

Tutmuyor sol yanım, kanadım kırık

Boğazımda düğüm düğüm hıçkırık

Bir tebessüm etsem yarısı buruk

Gidişimle davul çaldıracağım.

Bilirim borcumu kimse ödemez

En yakınım rahmet olsun da demez

Şiirim bir Molla Kasım beklemez

Belki bir toruna bulduracağım

Yeter ey Ceylan''ım bu kadar yeter

Devler uğultuyla beyninde yatar

Herkes yazılanı işleyip tutar

Ömür bir balondur solduracağım.', 'Dinmez bir uğultu kulaklarımda Nerdesin ey melek, çıldıracağım...!  Bıktım bu canımdan tövbe vallahi...!  Vallahi kazanlar kaldıracağım...! ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/halim-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidişlerine Nokta Koymak Mümkün Olsaydı..', 'gidislerine-nokta-koymak-mumkun-olsaydi-zeliha-bicer-ja7v2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gidişlerine nokta koyabilmek  mümkün olsaydı,

Tüm noktalarımı onun için sarfederdim.

Sensizliklerimi virgül bile karşı koyamazdı

Sensizlik var ya bu sensizlik

Ne gün batımı, ne martı çığlığı

Ne de rakı kadehi durdurmuyor.

Ah bu bekleyiş, bu vedalar

Sensizlik bu

Ayan beyan..

Sensizlik bu işte!', 'Gidişlerine nokta koyabilmek  mümkün olsaydı, Tüm noktalarımı onun için sarfederdim. Sensizliklerimi virgül bile karşı koyamazdı Sensizlik v...', ARRAY['Türk Edebiyatı','Şiir','Zeliha Bicer']::text[], 8.5, '{"poet":"Zeliha Bicer","poet_slug":"zeliha-bicer","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/gidislerine-nokta-koymak-mumkun-olsaydi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana Herşey Senden Gelir, Sen Gelmezsin Nedendir', 'bana-hersey-senden-gelir-sen-gelmezsin-nedendir-zek-i-budak-i83ei', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Birlikte gökteki güne

Tarhana serdiğimiz yaz

Amma yazdı ha...

Gelinciğe veda papatyaya naz

Ettiğimiz yazdı o yaz

Tarhanayı bu yüzdendir sevdiğim

Güle bunca tutkunluğum sendendir

Senden gelen her bir mihnet kabûlüm

Gelirse ancak

Bana senden gelir ölüm

(Babaeski - 1975)', 'Birlikte gökteki güne Tarhana serdiğimiz yaz Amma yazdı ha... Gelinciğe veda papatyaya naz Ettiğimiz yazdı o yaz Tarhanayı bu yüzdendir sevd...', ARRAY['Türk Edebiyatı','Şiir','Zekâi Budak']::text[], 8.5, '{"poet":"Zekâi Budak","poet_slug":"zek-i-budak","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/bana-hersey-senden-gelir-sen-gelmezsin-nedendir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biteviye Şuurlu Bodos', 'biteviye-suurlu-bodos-akin-akca-j15s8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu ne hırs? 

Dünyada alacaklarını aldın

Bir de cennete mi karar kıldın …

Kiriş bu ne kırış …

Yeryüzüne bir güzel çöreklendin,

Kovulup da mı cennetten? 

Elekten zor akan un; 

sürülen eleğe, manda-kağnı..

Akıtılan un:

Aşağı yukarı

Fakat bayağı bir eni konu; 

Düşünebiliyorum onun

ne dediğini,

Evin hanımına..

Razı etmek için ona,

Kendisine evlenmeye:

“Hanım, 

Erkekler içmezse içki,

aldatmazsa

Öp de başına koy; 

Ama sen de 

Bana tavizler ver.

Gerekince yan

Masaya geç de otur.”

Böyle şirin görünmüş olacak

Bir gerikafa şahsiyet; 

Zaten yanakları da tombul,

Pardon tonbul.

’70 yıllarındaki

‘Geceyarısı Ekspresi etkisi

Sezilenleri’ kulağa, 

düşünen beyne

İşte, aynı şeyi diyor

Şimdiki bir ulema da:

“Biz, yapacağımızı yapıp 

yapalım da; olacağına

her şey elbet varır..”

… inkar edercesine 

kendi dünyevi vücudunu …

Ve devam ediyor

Yandaşlara açıklamalara:

“Eyvallah,

Haydi yola devam,

Ama aynen ılıman devam

Etki altına almaya

Mı çalıştı yoksa

28 aralık ’05 günü,

meclis başkanını

ve laf da mı

onun sekreterine atmıştı..

paşaların paşası edalı

alikıran başkesen -

hayvanat bahçesi ayıları gibi

değil oyuncu, patinaj

atamayan, kayalar üstü 

- bir dayı,

bir Kasımpaşalı? 

Çinçin bağlarına beklerim

Hele, Küpeli’nin Yeri’ne.

Göl yanı’nca

Bir restaurant (!)

Bir parti mangal 

Çeviririz güzelce.

Orda bekleyecek

Seni ağzı açılmış

Bir nevi bir mazgal

Cumhuriyet tarihinde

Bir ilkti.

Vücudu mecliste

Ama ruhunun

Kravatsız gömlekli

İlk ilik kısmı

Sıkıca kapalıydı.

Kendi bile fark edemedi.

Üstüne üstlük,

Şuurlama bodos

Fark edemediğini.

Uzak ara birkaç ancak

kolay hazırladı sonunu.

-

Türkiye gelişmeler üzerli

Kasımpaşalı’dan kasıt tek kişiye. Söz meclisten dışarı

Alt açıklama, eksisozluk’ten alındığı şekliyle:

Kasımpaşalı açıklamaları:

milliyet''te, radikal''de ve sabah''ta, bu isimli ve rte konulu yazı dizileri dönüşümlü olarak yayımlanmaktadır. 

 (bkz: kasımpaşalı eli maşalı) 

(bkz: recep tayyip erdogan) 

http://www.milliyet.com.tr/...11/13/magazin/amag.html', 'Bu ne hırs?  Dünyada alacaklarını aldın Bir de cennete mi karar kıldın … Kiriş bu ne kırış … Yeryüzüne bir güzel çöreklendin, Kovulup da mı ...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":88,"source_url":"https://www.antoloji.com/biteviye-suurlu-bodos-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mideye yutulan palamut masalı', 'mideye-yutulan-palamut-masali-akin-akca-1uyih', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Mideye yutulan Palamut masalı (Balıklar üzerine geliştirilen “yalan ''küçük-büyük’ alakalandırılmış hadisleri”n(d)  e, gerçeğin bir masalı - 

Mideye yutulup ‘bilinçlice’ yenilmediği yalanı kendisine açıklanılan, hazmedilmemiş palamut masalı)

Ormanda koru yolunda

Yuvarlanan meşe palamudu,

Sıçrayan sincap yedi

Aşağı, ulu orta, onu.

Sincap sonra içinde büyüdü,

Dev gibi oldu,

Palamut yedi onu bu sefer; 

Üstüne ağırlık çöküp

Bacakları bükülen sincap

Çöküp yere oturuverdi.

fark etmemişti, oturduğu

ağaç dibi; 

o ağaç yaylandı,

yayları görünür olmuş,

atmış,

bir yatak gibi -

sincabın üzerine.

Bir anda geri dönen,

Beklemeden sincap şaşırttı,

Çöreklenen ağacı ham etti

Ve midedeki palamut,

Hani o ilk hücreler gibi -

bitkisel yapılı,

hayvan hücrelerinin

yuttuğu

yutup da tüketmek bilmediği

vicdan çiğneyemediği

soy tüketmek denli

bir biyo geçiş noktası..

an tavırlı oldukları,

işte o hayvan hücrelerinin

yemeyip de

bıraktıkları mahsur …

- tutulmuş midede

palamut da fırladı dışarı

böylece, civciv,

neşe ve umut ile.', 'Mideye yutulan Palamut masalı (Balıklar üzerine geliştirilen “yalan ''küçük-büyük’ alakalandırılmış hadisleri”n(d)  e, gerçeğin bir masalı - ...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/mideye-yutulan-palamut-masali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Köy Yolu Uzun Hava Türküsü - Köy Masumiyeti''nden doğru Bilkur Dağtaşkıran', 'koy-yolu-uzun-hava-turkusu-koy-masumiyeti-nden-dogru-bilkur-dagtaskiran-akin-akca-gknbq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Tak eme to Manhattan! It’s a ‘Call o’Cthulhu’…That’s why, first the narrator’s gonna send me these people, then, later  i will destroy all the empty skyscrapers there: No one will gonna die. No one … But, it’s somewhat different, when we think the aeroplanes o’CIA on Iraqi skies: It’s not a silent bomb, like American soldiers did, do they have mercy? it’s not a biological war, even no envelopes o’humankind is gonna lost and forgotten… but its call of cthulhu; It’s not a necessity for everybody to fight, while –xtraoerd`ly.- one listens to muse(ic fuse

-

Ne güzeldir kapanışı köy yolları 

Hemzemin arterlerinin il hudutlarına …

: Gücü toplar isen

Yürür varırsın hemencik 

En yakın bir komşu kente! 

*

Bir takım kısmısı laflar dönüyor

Bugünlerde çevrede …

: Köylüyü küçük mü göstermeye çalışmakta

Bazı kendini bilmezler? 

Köylerden geçer giderim,

yazın, bazen,

Tatillere çıkışlarda

Bir tarlaya rastlarım ve onun

Makinisti bir traktör şöförüne

Ya da bir patates satıcısı

Görünür olur araba ile

Rüzgar uçurtuşta,

Şehir dışı otobanlarda -

bir ara durur

ve belki patates, soğan satın alırım; 

he he, plan porogram …

- Tek, sağ kol 

Camdan dışarı 

Sarkıtılı ama değil tabi sargılı

Bir vaziyette.

(Çünkü) 

O köylüler güzeldir! 

(Duyguları bir,

zekaları da buna uyanlardır.

onlar, duygularını zekalarının

kölesi yapanlar değillerdir) 

Hem de pek çoğundan,

Şehirlerdeki yaşayanların! 

*

Kocaman botlar giyeceğim

Buz dansında kayar gibi kaydırak..

Ve yaklaşan yılbaşı coşkusunda

Köyleri şehirle kapatan

Şanlı kar bembeyaz tortusunu -

dip demi gibi Türk kahvesinin, bakılan faldaki

- Yararak bir anda

Yürüyüp Everest’e geçeceğim

Nepal, Tibet, nerdeydi; 

Ne tarafta kaldı? 

Buna bile sevineceğim.

(O Goliath tipli robot

Coldplay mensuplarının

kendisi metal gövdesiden korkup kaçıp

uzaklaşışlarından sonra:

bunla bir ilgisi olabilir mi o robotun,

kendisi sessizliğe çekilir iken

uçandairelerine binip el, Coldplay sallarken? 

aldatmış olabilir mi, o robot onları? 

ancak tekrar geri dönüp ışın kementi 

attığınca o uçandaireye

ve indirdiğinde kendi öelikten midesine,

ıslık çalmıştı:

Bunu,

onları mideye indirdikten sonra yaptı.

yani bence,

onların hem ondan korkup

sonra da el sallamalarına

kızmış olmalıydı.

yediğine üzülmüş olacak ki,

tanrılar dağında gene yalnız kaldı

ve/yani ıslık çalmayı

böyle mi öğrenmiş olacak; 

klibinde,

‘Take’ şakısında Coldplay’in?) 

Köy masumiyetinde, Bilkur Dağtaşkıran; 

Kar paletleri botlarına takılı 

Ayakları yakalarında asılı; 

Sıktı taşı, suyunu onun içti

Ve her sıktığı taştan da aynı suyu içecek

Bir cesaret içinde taşımaktaydı; 

Ama her içtiğin su bir değil, elbet bilirdi.

Bunun için köyden yola çıktı.

Dağa çıktığında

Ulaştığında en zirveye,

Çağlayanın budayarak döküldüğü

O engin pınardan içecek

Saati kurup yönünü kolay bulduğu..

Dağları delerek, taşları sıkıp:

Bilkur Dağtaşkıran’dı adı …

Bunun için bazen kadehler devirdi; 

Ancak işte gerçek, saf suyu

Keşfedebilmek uğruna …

Çünkü köşesine çekilgen tesbihçiler

Yerlerinde hep saydı seğirttiler …

      Ulaştığında en zirveye,

   Çağlayanın budayarak döküldüğü

    O engin pınardan içecek

   Saati kurup yönünü kolay bulduğu..

    Dağları delerek, taşları sıkıp,

   Bulduğu suyunu.

Kimbilir belki de,

Anaforlardan sıyrılıp

Köycük banliyölere

Varmak istemekteydi …

Düş`ence kırkayaklar 

Bolu Dağı’nda; 

Sisler yarmada,

(‘) Kar kürümek sevmeyen 

Bir çeşit greyder, armada(‘)  –

güzel olan, karı y) ürümek; 

{varsın yürürken

de kürümüş,

oh, hava ne güzel:

(‘) hayat içi, hayat çekmeden(’) 

mi yaşam(ayı)  bulmuş? 

yok yağma, kaç kepçe 

bürüdü zaten bilememişti; 

dökülenlerden topladı,

işe giderken

arabanın üstünden 

kar ayıklamadı

ve ayrc. özel

olanı (da)  buydu

çünkü

“de” buydu, “da” buydu:

aslında farklılık

diye ir şey de yoktu …

kaşımız, gözümüz v.s.

vardı, çevremizi 

yalnızca dile getirenlerdi …

böyle bir yer olmalıydı

keşf edilmemiş henüz

evrenin merkezi; 

seyredip ballandırdığın

budaklandırdığın tat kazananı,

glikozdan kemirdiğin,

şekeri tüm yediğin}', 'Tak eme to Manhattan! It’s a ‘Call o’Cthulhu’…That’s why, first the narrator’s gonna send me these people, then, later  i will destroy all t...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":135,"source_url":"https://www.antoloji.com/koy-yolu-uzun-hava-turkusu-koy-masumiyeti-nden-dogru-bilkur-dagtaskiran-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben hüzünü çok sevdim', 'ben-huzunu-cok-sevdim-guzin-osmancik-4r4z0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben hüzünü hep sevdim.

Hüzünle düşündüm,

Hüzünle büyüdüm.

Hüzünle güldüm

Gördüğüm her şeyde 

Hüzün vadı

Yaşanan hayatlar da

Atılan kahkahalar da

En mutlu anlarda 

Ben hep hüzün gördüm

Gözler vardı, mahzun

Aşklar vadı, umutsuz.

Sevgiler yaşandı SON suz

Çocuklar vardı mutsuz

Onlarda hüzün gördüm

Ben hüzünü hep 

Sevdim

Hüzün benim adım

                 evvelim', 'Ben hüzünü hep sevdim. Hüzünle düşündüm, Hüzünle büyüdüm. Hüzünle güldüm Gördüğüm her şeyde  Hüzün vadı Yaşanan hayatlar da Atılan kahkahala...', ARRAY['Türk Edebiyatı','Şiir','Güzin Osmancık']::text[], 8.5, '{"poet":"Güzin Osmancık","poet_slug":"guzin-osmancik","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/ben-huzunu-cok-sevdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ay Şahidimiz Olsun 2', 'ay-sahidimiz-olsun-2-sacide-yaylaz-z8tde', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sessizce oturmuştu, deniz kenarında çakılların üzerine, güneş kavuşmak üzereydi sevgilisine, ha battı ha batacaktı, karanlık kucak açmıştı. Bekliyordu sessizce, usul usul gelen sevgilisi güneşi bekliyordu, sımsıkı sarmak için. Bir avuç taş aldı, avucundaki taşlara uzun uzun baktı: 

Oysa bugün ne kadar mutlu uyanmıştı uykusundan yüzünden gülümseme hiç eksilmemişti,mutluydu seviyordu hem de çok pek çok seviyordu, oysa olan olmuştu işte her şey bitmişti bir anda şimdi avuçlarında tuttuğu bir avuç çakıl taşına tekrar uzun uzun baktı, 

bir tanesini aldı,öylesine attı denize tekrar bir tane daha yine, yine sanki her attığı taşta hüznünü fırlatıp atıyordu. 

Olmadı tekrar bir avuç taş aldı, atık uzağa,uzağa daha da uzağa atmak istiyordu. 

Doğruldu ayağa kalktı, kızgındı, mutsuzdu, umutsuzdu bir taş aldı avucundan attı tekrar attı, her attığı taşın ardından dalga dalga yayılan halkalar durdu, tekrar baktı.Her halkada kendi hayatını gördü. 

İşte hayatım işte geçmişim dedi dalga dalga kuşatıyor beni kurtulmam lazım dedi ve 

bir taş aldı attı bu kez yeniden attı.Her dalgadan yeni bir umut, yeni bir yaşam olduğunu düşledi, evet evet her dalganın yayılıp büyümesi ona bir anda yılmamayı vazgeçmemeyi hüzünleri atması gerektiğini düşlerindeki sevdasına gerçeğe döndürmesi gerektiğini söylüyordu sanki.Bir anda havaya zıpladı, yürümeye başladı güneşin batışına doğru yürüdü, yürüdü. 

Yürümek yetmiyordu şimdi koşuyordu içindeki çocukça bir coşkuyla koşuyordu sonra durdu baktı, artık güneş görünmüyordu kavuşmuştu sevgilisine, gecenin kollarında kaybolmuştu sarılmıştı karanlık geceye, gecede mutluydu güneşine sarılmıştı sımsıkı kucaklamıştı. 

İçinde tekrar sabahki uyandığındaki heyecanı hissetti sessizce haykırdı seviyorum gel diye 

Gecenin sessizliğinde, 

Öyle bir dur ki karşımda, 

Soran gözlerle, ama yüzünde, 

Hafif bir tebessüm olsun. 

Sen miydin beni bekleyen, 

İşte geldim bak, 

Şimdi yüzleş benimle, 

Sevgimden mi, yoksa 

Benden mi, şüphe ediyorsun 

Söyle bileyim, 

Ben karşındayım de 

Kaldır başını gözlerime bak 

Orda kendini göreceksin 

Tut bak ellerimi,ellerim 

Zaten hep senin ellerindeydi, 

Ya yüreğimi hiç sorma, 

O zaten seninleydi, 

Seni sevdi, seni bekledi de

Gecenin sessizliğinde. 

Öyle haykır ki sevgini 

Ay şahidimiz olsun, 

Yıldızlar dans etsin, 

Gecenin sessizliğin de 

Seni beklediğime değsin...', 'Sessizce oturmuştu, deniz kenarında çakılların üzerine, güneş kavuşmak üzereydi sevgilisine, ha battı ha batacaktı, karanlık kucak açmıştı. ...', ARRAY['Türk Edebiyatı','Şiir','Sacide Yaylaz']::text[], 8.5, '{"poet":"Sacide Yaylaz","poet_slug":"sacide-yaylaz","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/ay-sahidimiz-olsun-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hem Kumarda Kaybettim Hem Aşkta', 'hem-kumarda-kaybettim-hem-askta-selim-eysioglu-207nx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '''Kumarda kaybeden aşkta kazanır'' derler ya,

Bile bile kaybettim ben hep kumarda.

Fakat sonunda; 

Hem kumarda kaybeden oldum, hem aşkta.

(28.12.2005  02:10    /   ANKARA)', '''Kumarda kaybeden aşkta kazanır'' derler ya, Bile bile kaybettim ben hep kumarda. Fakat sonunda;  Hem kumarda kaybeden oldum, hem aşkta. (28....', ARRAY['Türk Edebiyatı','Şiir','Selim Eyşioğlu']::text[], 8.5, '{"poet":"Selim Eyşioğlu","poet_slug":"selim-eysioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/hem-kumarda-kaybettim-hem-askta-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kahverengi Hırka...', 'kahverengi-hirka-sibel-uygun-mfmy8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sana her kavuştuğumda bir korku düşüyor içime...

Biliyorum, özlediğim kadar yanındayım.

Hasretlere boyun büküyor  umutlarım...

Her zaman olduğu gibi,

Yine bir ayrılık sahnesindeyiz,

Güldüğümüz kadar ağlıyoruz.

Çaresizliğimize sığınıyoruz her dafasında...

İstemeden veda ederken sana; 

Bir masum bakışın kalmış aklımda,

Bir de üzerindeki kahverengi hırka...', 'Sana her kavuştuğumda bir korku düşüyor içime... Biliyorum, özlediğim kadar yanındayım. Hasretlere boyun büküyor  umutlarım... Her zaman old...', ARRAY['Türk Edebiyatı','Şiir','Sibel Uygun']::text[], 8.5, '{"poet":"Sibel Uygun","poet_slug":"sibel-uygun","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/kahverengi-hirka-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sırdaki Gaip(,) Esa(n) s Sitem - Tuhaf şiir', 'sirdaki-gaip-esa-n-s-sitem-tuhaf-siir-akin-akca-uczxi', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Eğer boş zamanınız y(ç) oksa, ruhunuzu kaybediyorsunuz demektir.

-

I.

Suyla sigarayı yakıp üstüne ekmeğimi bandım

Ama ocakta teflon vardı; 

Kir pas tutmadı, ben onun yalancısıyım.

Sahilden geçiyordum; 

Kumları sayıyordun, ama yoktun:

Sordum ‘kim bu? ’ diye, bana cvp kimse veremedi.

Kendimi yanıtlamıştım, anladım.

Peki; bendeki ben, senden hariç bir 

Benden öte kimdim? 

Ne dünü ne yarını,

Varsaydığın bir bugünü …

Öyle oyunlar olur ki geceleri bur`da,

Anlık doğumunuz yetmez sınırsız düşünlere; 

Bir anda doğar her şey ve onlanır sizde.

Hayat, yaşamak için çok kısa; 

Önemlisi, sevdiğini yakalamaya çok çabuktur -

Gidiş o gelişlerde …

- Bir avuçluk 

Çekme’ce kibrit çubuktur,

İnsanı insanoğlu birden katsayılatıveren -

Çinli kalamar çiğ yutan dönencelerde 

- Ve sonra alınır karekökünüz …

Bunu daha ama sonra anlarsınız,

Anlarsınız ki henüz doğmamışsınız.

Çünkü doğmamış olmak güzeldir,

İseniz siz böyle bir döngüye sahip edilir ….

O zamanlar için ve hep,

Doğumlar her tek bir yere,

Hem de yer tutamamaktır çengelde sözde milliyetçi.

Çok da iyi bir şey olduğunu

Söylemeye çalışıyor olduğumu dillendirmeye becerir

Bulunur göründüğüm bir an’ı; asla sanmayın, ne var ki …

Böyle bir garip şeydir işte,

Neyin ne olduğundan emin olmasan bile … 

Ölsen kime pee, akşama ezan,

Asla bende sanmazsın ki bunu

Camide ses tellerimde

Sergilediklerimden ötürü

Ses kazanır bir ses sadece yüreğimde

II.

Bir piyano çizmek istiyorum,

Papa’lara haklı kafa tutan Bruno ve Michelangelo

Ve gibi Copernicus ve 

hatta dile getiren bunları önceden, bir kahin,

Jon Done gibi: 

İşte bu verilerin bütünü ortasından,

Bulursan bir anlam buldum diyebilirsin.

Yoksa şiirde konu her şeydir diyemezsin.

Aynı, pi sayısı ve 3.14 …

Uzayıp gider ama kendi bağlantıları kendisinde gizildir! 

Bu yüzden hep bir varolan var ve olacak

Ve sadece bu yüzden yok olacak hep yokolan:

Tam yokolan öyle de gider, 

ne diyelim kendi onların seçimleri; 

ama tüm bir cereyana kapılan ki gözlerini açan,

gözlerini açmakla asla çıkmayacaktır bir kozadan –

bu bir masumiyet kaybı değildir

böyle varolmuş, hep geçitler bulabilecektir.

Bu nokta, bilimle dinin kesişim alanı.

Piyanoyu bulursun bu köprülerde işte..

eğer canın çekmişse.

böyle varolmuş, hep geçitler bulabilecektir.

ve düşünün hele, *

belki de ölüm bundan iyiler için var olagelmiştir.

Almak ile duyguların bağı incecik. **

Her insan güzeli alabilmiştir amma

Sevdiklerine de dağıtabilecek midir? 

Şu halde zihnimizi genişletmek lazım,

Sarkan dili gibi Einstein’in fotolara gülerek …

Aslında zihni sarkıyor:

Anlayan anlar; bir nevi, utandırmayı dile getirmekte …

Çünkü çıplak koşan Arşimet sokaklarda,

Arşidük müdür sanki suyun kaldırma 

kuvvetini bulduğunda küvetinde -

yok, yok holigan değildir

- Şu halde zihnimizi genişletmek lazım:

Vermek için sahip olduğumuz (bulunduğumuz

Ve onun ayrıca tam da öbeğinde bulunduğumuz

Ki bulduklarımız ile bulmadıklarımız da cabası) 

Koridorlar daracık.

Aldığın şey, boş olmamalı bir de; 

Boşluk alan, boşluk üretir de ileride.

Orijinalitesi olmayan bir marjinal bile sen asla olma:

Sensin, tamamen-sen zaten:

Vaktin olacak.

Şimdi ise, olmalısın sarf sen kendin.

Uykuyu sever görünürsün,

Katar da uykularına iyi birini,

“en kötü kabusumdu bu” pek kolay dillenebilirsin

Ancak sonra dile getireceksindir,

“ sen kötüsün” de …

Böyle altın bir yüreği

Bırakır mıyım hiç dersin? 

Aksine, kabuslarına bile kabul beni edersin.

Çalışmamız için verilen, hayat bizlere; 

Rağmen küçükken, bebekken olmasına daha rahat:

Sanat, kayıp olmaz,

Çevremizdekiler hep öyle bir düzen.

Nerden geldiyse aklıma şu 3. bölüm; 

Pek yapmam, hemen hiç, ama,

Olayı biraz geniş plana yayıp da

Dünya’ya ay’dan yayık ayranı gibi baktığımızda:

Naçiz kendi beynimi ekler isek Jodi ile 

Sharon’un yüksek iq değerlerine

Ve böylece bir yorum getirirsem; 

Diyebiliriz ki:

Evet, erkekler hem toplayıcı ve avcı hem de

Ve hissettirmek için burada erkeklere de, kadınlar da:

: Bir şey var ki fakat; 

Kimse kendisini sınırlamamalıdır

Cinsi ne olursa, hatta.

Yüksek bir kabulleniş var doğasında

Anne olmadığında bile belki, dişi doğanın.

Erkeklerse, ne olursa olsun atılgan kaplan -

genellemek hata, genellemek suç, genellemek hata! 

- Ancak düşmeyelim yapılan aynı hatalara

Bari biz de; 

Genelleme olmadığı, lafın sonunda gelecek:

Doğasında da kadın da çiçekler açtırmalıdır,

Kendi başına, üstelik kendi.

Mesela ele alalım televizyon şovlarına

Çıkan insanları.

Yılan gibi ince, kıvraklaşmış

Göbek atan erkek dansözleri henüz 

sayısından sayabilirim ama 

uzaylı gibisinden 

orantısız bir entarisel siyahi çirkinlikle

özenmiş metalistliğe tipliler çoğaldı,

Müzikleri ise boşalmadı

O şarkıcıların, zaten içleri doğarken boş değildi

Sonradan boşaldı, ikisinin arasında bir yerde...

Bomboş …

Buna aksi bir örnek tarzından; 

Ciddi bir erkekle kalitesiz markajlı kahkahalar 

atan bir kadın

Çıktı, bir kanalda, örneğin bu gece –

Rastlamıştım rastgele.

Erkek-kadın ters-düz ruhsal tepkimelerinde

Aksi de oluyor, olmuyor değil tabi.

Bu dediklerimizi ele alacak olursak; 

İşittiğini dinler genelde sakince bayanlar,

Sinirlenirse de kötü olur ha,

Erkeklerse saldırgan taraflarından

Ödün verebilirler saygın bir mekana

Mola verdiklerinde,

Bir olasılık dahilinde -

Kuruyemiş ile Keto meselesi gibi

- Damarlarına ama basacak biri olacaksa da,

Kolay belki gaza gelebilirler.

Bunları tasvip etmek mümkün elbette değil ancak

Eğer olayı yapıcı tarafından ele alacak olursak; 

Bayanlar da yoğun tepkiler koymalı

Önem verdikleri bir konu üzerinde –

İlle bağırıp, çağırmak çünkü

Değil gereken bunun için; 

Tavır koymak gerekli -

Duruş sergilemek.

Kararlı olmak zamanı, 

sessiz gelse da olur. 

Kadın, ifade edilebilir; 

Sevmek ve sevmemek (olarak) ,

Erkekse, bu bazı koşullarda; 

Düşünmek ile çabalamak. 

Fakat lafın sonunda geliyor kanıt:

Neden seven bir kadın; 

Düşünmesin, bırakabilsin ki düşünceyi

belli koşullar altında,

hayata devam ediyorsa,

işine, tıpış …

Azimse irade, içtenlikse içtenlik; 

Bunların hepsi de aynı değil mi 

(değim’li, uzak ara ama hep ulaşımlı) 

Sanki kadında ve erkekte …

Eğer bir insan sevgiyi reddetmişse,

Yöneltilmiştir belki gelecekte

Ve tabi ki de ama kalmıştır geçmişte; 

Seçmediğinse ise korkuyu (

demek ara bir yerlerde

)  Güçlü şüpheleri şüphesiz artık 

Onun kararları olmayacaktır –

özgür kendi kurduğu köprülerde bir ileti.

Umutsuzluklar açısından kaybedilebilecek

Bir vakte vakit kaybetmemeye yani

Olumsuzluklara zaman tanımamaya

Bir çeşit bir öngörü 

Umut sıyırmak olabilmektedir.

Yer, içer, koşar, oynarız, kendi başın; 

İhtiyacımız olan her şey yanımızdayken –

Hayat denen.

Sevilecek değer bir şeyler 

Bulduğumuzda,

Yine de yön değiştirmemeliyiz.

Aslında beyazın siyahtan ayrışması

Tam olarak değilken bu,

Biz yönü değil, rüzgarı değiştiririz.

Farklı kişi de almayız ele, yani; 

O anlamda değil. Tam anlamıyla:

O anlamda barınmayan aksi tam anlamıyla; 

Sırf ki kendi başımıza koşmuyoruzdur

Yani artık, fakat gene oynuyoruzdur,

Hayatla tepişip, coşuyoruzdur ise yaşamda.', 'Eğer boş zamanınız y(ç) oksa, ruhunuzu kaybediyorsunuz demektir. - I. Suyla sigarayı yakıp üstüne ekmeğimi bandım Ama ocakta teflon vardı;  ...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":204,"source_url":"https://www.antoloji.com/sirdaki-gaip-esa-n-s-sitem-tuhaf-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alamor', 'alamor-nevin-kalafatoglu-6zdur', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'duydumu bilmiyordum...

yüreğimin sesinden başka bir ses

yitik güzlerin sessizliğindeydi çığlıklarım

bir mavi deniz görmüştüm 

benim sevdiğim mavilerdendi, rengi alamor

köpükleri turkuaz

çırpıntısında suların rengi kar beyaz

dinlediğim sarkılar

söylediğim sözler 

yansıdı 

dalgalardan mor deniz

vurdu dağlarımdan çakıltaşlarıma

içinde yıllanmış anılar 

şiirlerde saklanan imgelerdi alamor

mavinin, denizin sesiydi 

hıçkırıklarımda katledilmiş 

susmuş prangalar

mor bir aşktı kitlediğim baharlar

ben sustum sevgili sonsuza kadar

bir sarkı dinlerken ismi lal

nedensiz heyecanlarım, susku yankılar

senin kıyıların mavi

benim içim mor yar

henüz hüzünlerdeyiz biz ikimiz 

gelemesin 

özlediğimiz baharlar...





28/12/2005

SİDE', 'duydumu bilmiyordum... yüreğimin sesinden başka bir ses yitik güzlerin sessizliğindeydi çığlıklarım bir mavi deniz görmüştüm  benim sevdiğim...', ARRAY['Türk Edebiyatı','Şiir','Nevin Kalafatoğlu']::text[], 8.5, '{"poet":"Nevin Kalafatoğlu","poet_slug":"nevin-kalafatoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/alamor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mektuplar-27 (M.S.) 27/12/2005', 'mektuplar-27-m-s-27-12-2005-mahzun-doga-37alp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kıyamet dindi.

Gerçeklerin yüzü kızarmış.

Utanıyor zaman.

Yüzümüze bakamıyor yüzsüz hayat.

Kaçıp gizlenmiş bir yerlere İstanbul.

Utanası tutmuş ilk defa.

Ve kırılmış şimdi bizi bilen tüm eşyalar.

Adımlarını bilen yerler buz tutmuş.

Gidişine ters dönmüş her şey.

Gülüyoruz.

Kalışıma kahkahalar sıralıyoruz.

Gittin.

“Gittin” demeyeceğim.

Gittin.

“Ardında koca bir kimsesizlik bıraktın” demeyeceğim.

Ardında koca bir kimsesizlik bıraktın.

Yalan dünyanın en büyük yalancılarıyız işte.

Hiç kimseye “O “gitti” demeyeceğim.

O gitti...

Gittin.

Bakışlarım yırtılıyor.

Dudaklarım paramparça

Ellerim un ufak. 

Kalbim çıldırmış.

Sen gitmişsin.

Hepçe batmışız yokluğuna.

Ciğerlerimizde su kalmadı mavi kadın, 

kalmadı.

Bütün denizleri kurudu martıların.

Kaplumbağalar uçamıyor.

Sabır oyalıyor bizi.

Bize göre değil beklemek.

Dön gel kadın.

Dön gel.

Durma ne olursun.

Dön gel.

Gel.

Gel.

Ge.

g.

...

Hatırlanıp yakan ne çok an döktün geçtiğin yerlere.

Hiçbir yere bakılmıyor.

Hiçbir yerde durulmuyor.

Nesneler yarım.

Her şey felaket olmuş.

İstanbul hasta.

Beyoğlu ölüyor.

Odamızda zehirli bir ölüm var.

Asırlarca seni ölmeliyim

Çağlarca sarılmalıyız.

Hiç gelmemiş gibi kalmamalıyız.

Doymalı sana.

Seni çoğalmalı.

Seni daha çok olmalı.

Dön gel.

Gitme.

Dur.

Kal.

Götür beni.

Al.

Götür beni de.

Gitmediğin yere.', 'Kıyamet dindi. Gerçeklerin yüzü kızarmış. Utanıyor zaman. Yüzümüze bakamıyor yüzsüz hayat. Kaçıp gizlenmiş bir yerlere İstanbul. Utanası tut...', ARRAY['Türk Edebiyatı','Şiir','Mahzun Doğa']::text[], 8.5, '{"poet":"Mahzun Doğa","poet_slug":"mahzun-doga","theme":"Türk Şiiri","is_hero":false,"total_lines":63,"source_url":"https://www.antoloji.com/mektuplar-27-m-s-27-12-2005-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül Doktorları', 'gonul-doktorlari-mustafa-benkli-9a2n0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kürsüden insan gönlüne inmesini bilen, gönül sarrafı bir zat, zarif bir uslûpla hitaben: ''Gönül doktorları'' ithafıyla kalplere merdiven kurmuştu... Gönlümü tiril tiril eden bu ithaf beni gönüllerle rabıtalı, gönüllere hitap eden o zümreye yöneltti ki o zümre şairlerdir; bunu size ithafen içimde kurduğum kurgumu dile getireyim dedim; Adı da  ''Gönül Doktorları'' olsun.

.........................................................................

Kürsüden gönüllere bu zarif seslenişten

Dupduru bir yöneliş bu gönlümü çevirdi...

Şairâne bir ruhla tâ kalbimin içinden

Siz; şu şiir dostları gönlümden geçiverdi; 

Bu ruhtaki incelik ruhumu sardı birden! 

Aranızda beni de barındıran dostlarım

Bilin; günlerim değil, gecelerim de dolu; 

Yaramın merhemine; arar, sizde rastlarım! 

Gönülleriniz ılık meltem yeliyle dolu; 

Gönül almayı bilen benim güzel dostlarım...

Sevgisi merhametle yoğrulup gönül yuyan,

O, gönülden gönüle meltem esintisinden

Gönüllere serinlik, yaraya şifa yayan

Ruh sızdığı sezilir sizin kaleminizden...

Bu ruha saygı duyar anlayan anlamayan! 

İşte ben bu minnetle katıldım aranıza; 

Yarama neşter olur her gün kalemleriniz,

O neşterin darbesi şifadır yaramıza; 

Kürsüdenki ithafa en lâyık sizlersiniz

Bu gönül doktorluğu lâyıktır nâmınıza...

Ey gönlümün doktoru şairler, şaîreler

Siz gönül kırmazsınız; iki cihan bir olsa! ..

Olsa ki duyasınız, birinizden bir şeyler; 

Değer mi üstlemeye? meğer ki aslı olsa! 

Siz; ey, kavgadan ari ve münteha değerler...

Ben bu hislerle dolu, sımsıcak selamlarla

Selamlarım sizleri; siz ey, gönül erleri! 

Cemiyette yeriniz ölçülmez makamlarla..

Gönle zeval gelirse çıkarsınız ileri...

Yeriniz kazanılmış ruhî imtihanlarla! 

............................................................

Selâm, sevgi ve sagılarımla... Gönlümün doktoru, ruhumun ilham preileri...', 'Kürsüden insan gönlüne inmesini bilen, gönül sarrafı bir zat, zarif bir uslûpla hitaben: ''Gönül doktorları'' ithafıyla kalplere merdiven kurm...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Benkli']::text[], 8.5, '{"poet":"Mustafa Benkli","poet_slug":"mustafa-benkli","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/gonul-doktorlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küçük Bebek-3', 'kucuk-bebek-3-akin-akca-h4sc7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Doğulacak bebek karında oyalanmaz,

Küvezde durmaz sağılacak bebek.

Koşar biberona karnı doyuracak,

Sevgi tazeleyecek annesine koşar.

Önlük çektiler yakasına bir ilkokul,

Eti bisküvi, hayat maması yedirdiler.

Muamma gibisinden gelir bazı haller; 

Ağladı, dudak burdu, yedi, uyudu.

Gülerek uyandı, bir iyice gerindi.

Bir koca adam aynada olmuştu.

Kırdı aynayı, birleştirdi parçaları.

Gülerek; neden uyanmıştı, anladı.

M.Kemalpaşa tatlısalı şekerfare; 

Kalorili yiyimsel, fıldırfış takip edilişi.', 'Doğulacak bebek karında oyalanmaz, Küvezde durmaz sağılacak bebek. Koşar biberona karnı doyuracak, Sevgi tazeleyecek annesine koşar. Önlük ç...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kucuk-bebek-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tomurcuk', 'tomurcuk-akin-akca-9kuey', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Mavinin bağrıcağzından doğan pembe tomurcuk,

Açık mavi kılcallarıyla sarmalanmış çekirdek kendinin,

Dalga dalga açık maviler bir ilk sınırından salınmış.

Sonra ateş yandı ama kahverengi renkli arkaplan,

Sarmış bu parlak sarı yananı… iki adamsa gölgeler; 

Biri oturmuş o köz aleve, ayakta diğeri kaçamak:

Elinde testi gibi bir şey tutmakta, olmayan kafası

Bir kedi veya o, seramikten ve parlak simsiyah.

Ya da kafası gömülmüş vücut içre, bedeni yanmakta.

Birden beliren üç martı sanki kar müjdesi oldu! 

Kızıl bir göğün içine giren vakti büyücünün sütunlarda

Alt-yer tutmuşluğun -evreni mi tutuyor kendinden 

Yüksek yerlere- tüm bir tapınağa atfedilişliğin,

Tek eliyle hem de, diğer elinde deli baltası cansız …

Kansız, kimsenin kanını akıtmamış bir bahtsız, şanslı:

Büyücü olmasından belli, onda silaha ne gerek vardı? 

-

“KS Çalışma 4” res.1

“KS Çalışma 11” res.2

“KS Çalışma 7” res.3

Resimler link: http://www.aksiseda.com/sizin_resimler/default.asp', 'Mavinin bağrıcağzından doğan pembe tomurcuk, Açık mavi kılcallarıyla sarmalanmış çekirdek kendinin, Dalga dalga açık maviler bir ilk sınırın...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/tomurcuk-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlim oku', 'i-lim-oku-i-lhami-arslantas-84zho', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İlim oku olma nefsin kurbanı,

Alın terin ile kaynat çorbanı,

Kendi elin ile bulma zorbanı,

El oğlu yolunu şaşırabilir.

Kendi hayatına olma firari,

Kendi iradenle verip kararı,

Zamana ayarla gözle yararı,

El oğlu malını aşırabilir.

Yeise bulaşma yolunu değiş,

Zevale görünme halini değiş,

Mizanın dengele dilini değiş,

El oğlu solunu şişirebilir.

Doğruları oku yalanla dolma,

Mülayim de olma katı da olma,

Fazla konuşarak dilinle bulma,

El oğlu dilini pişirebilir.

Güzel ahlakını kirletip bozma

Zan edip zan ile tarihin yazma

baltasın bleyip bir kanlı çizme

El oğlu kolunu düşürebilir

Der İlhami yolun ışıkla donat,

Kendini yenile namerde inat,

Her sözün sohbetin olmalı sanat,

El oğlu gözünden düşürebilir', 'İlim oku olma nefsin kurbanı, Alın terin ile kaynat çorbanı, Kendi elin ile bulma zorbanı, El oğlu yolunu şaşırabilir. Kendi hayatına olma f...', ARRAY['Türk Edebiyatı','Şiir','İlhami Arslantaş']::text[], 8.5, '{"poet":"İlhami Arslantaş","poet_slug":"i-lhami-arslantas","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ilim-oku-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ardı sıra..', 'ardi-sira-hasan-sahin-bibgu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir çocuğun gülüşüne gizledim hayatı

İnadına yaşanmış günlere yaslanıp..

Parklara girmedik ama

Şenlendirdik koridorları

Gücümüz yettiğince....

Güneşlere yetişemedik telaştan

Hüznümüzü koyup da cebimize

Kuytularda serdik içimizi Ay''a

Bahar''ın geldiğini duyardık sadece

Birileri fısıldarsa kulağımıza

Kar boran kapatmışken

Yüreğimizin yollarını

Biz fırtınada yaptık pikniğimizi

Ve suya değmedi ellerimiz

Gelen yaza öykünerek..

O güldü hayata bildiğince

Koşar adım giderken zaman

Biz gizlendik içine

Yok sayarak imkansızı

Gülüşünü bıraktı ardı sıra

Ve yenilmişliğin buruk yarasını

Gizlide unuttuk sanırım

Hayatın manasını', 'Bir çocuğun gülüşüne gizledim hayatı İnadına yaşanmış günlere yaslanıp.. Parklara girmedik ama Şenlendirdik koridorları Gücümüz yettiğince.....', ARRAY['Türk Edebiyatı','Şiir','Hasan Şahin']::text[], 8.5, '{"poet":"Hasan Şahin","poet_slug":"hasan-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/ardi-sira-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu kadın neden ağlıyor?', 'bu-kadin-neden-agliyor-i-lhami-arslantas-rwbr6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aklına neler takılmış? 

Umutlarımı yıkılmış? 

Gözlerinden kan dökülmüş? 

Bu kadın neden ağlıyor? 

Sebebini sordunuz mu? 

Kafanızı yordunuz mu? 

İdrakına vardınız mı? 

Bu kadın neden ağlıyor? 

   Dert bağlarsa içi şaşma,

   Ağıt eder sanki koşma. 

   İki gözü iki çeşme,

   Bu kadın neden ağlıyor? 

Çeyizleri mi yakılmış? 

Kötü gözle mi bakılmış? 

Tatlı canı mı sıkılmış? 

Bu kadın neden ağlıyor? 

El oğlundan mı mustarip? 

Bir yerde sığınç mı garip? 

Birisini yerip yerip, 

Bu kadın neden ağlıyor? 

Der ilhami üzer beni,

Medet diye süzer beni,

Ezim ezim ezer beni,

Bu kadın neden ağlıyor', 'Aklına neler takılmış?  Umutlarımı yıkılmış?  Gözlerinden kan dökülmüş?  Bu kadın neden ağlıyor?  Sebebini sordunuz mu?  Kafanızı yordunuz m...', ARRAY['Türk Edebiyatı','Şiir','İlhami Arslantaş']::text[], 8.5, '{"poet":"İlhami Arslantaş","poet_slug":"i-lhami-arslantas","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bu-kadin-neden-agliyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Diktatör Aşk', 'diktator-ask-ahmet-agdere-abeag', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Biz aşkı bebek gülüşünde,

Ve gece ağlayışında bildik; 

Öylesine masum, şefkatli..

Biz aşkı bir çiçek teninde,

Tomurcuklanan dalında bildik; 

Geleceğe ümit beslerken..

Ve biz aşkı bir çift gözde,

Sadece gözlemleyerek bildik; 

Ellerimiz gitmemişti mahreme..

Şimdi öylesine suçlu, zalim,

Önü geceden daha da isli; 

Açıkça, bir diktatörden öte ki..', 'Biz aşkı bebek gülüşünde, Ve gece ağlayışında bildik;  Öylesine masum, şefkatli.. Biz aşkı bir çiçek teninde, Tomurcuklanan dalında bildik; ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ağdere']::text[], 8.5, '{"poet":"Ahmet Ağdere","poet_slug":"ahmet-agdere","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/diktator-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Nefesim Ol da Git', 'son-nefesim-ol-da-git-guzin-eye-dundar-obu4g', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ayrılık  bir yanında

hasrete durmuş

eksilen yarımı

al da öyle git

kendime sarılmaktan

bedenim donmuş

dudakta son nefesim 

ol da öyle git

korkma sakın 

saklandığın hayattan

güneş in göğsüne 

düştüğü andan

bir sazın telinde 

sevda olmaktan

gündüzü geceye 

sar da öyle git...', 'ayrılık  bir yanında hasrete durmuş eksilen yarımı al da öyle git kendime sarılmaktan bedenim donmuş dudakta son nefesim  ol da öyle git kor...', ARRAY['Türk Edebiyatı','Şiir','Güzin Eye Dündar']::text[], 8.5, '{"poet":"Güzin Eye Dündar","poet_slug":"guzin-eye-dundar","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/son-nefesim-ol-da-git-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizligin Ilk Mevsimi', 'sensizligin-ilk-mevsimi-mehmet-yilmaz-0ujmt', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sensizligin ilk mevsimini yasiyorum. 

Bahar arkamda kaldi, 

Hani derler ya her mevsimin ayri güzellikleri vardir. 

Güzelligide arkamda biraktim. 

Kis mevsiminde yüregim. 

Ve kanlarim o kadar belli oluyor ki bembeyaz karin üstünde 

Enkazi kalmamis üstümden. 

Hangi depremi yasiyor yüregim bilmiyorum. 

Cikmaza girdim. 

Askta olan yalanlar tüm bedenimi örtmeye yetti. 

Kokunu sürdügüm duvarlar üstüme üstüme geliyor. 

Uyuyamiyorum eskisi gibi, 

Rüyalarinda tadi yok. 

Yalniz kaldim limani olmayan gemi gibi. 

Kimse ugramasin artik bana. 

Her Demir atan 

Bir baska bogdu beni. 

Gömdü en derinlere sevgimi. 

Hici yasadim dalgalarin üstünde. 

Gitmeliyim...', 'Sensizligin ilk mevsimini yasiyorum.  Bahar arkamda kaldi,  Hani derler ya her mevsimin ayri güzellikleri vardir.  Güzelligide arkamda birak...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Yılmaz']::text[], 8.5, '{"poet":"Mehmet Yılmaz","poet_slug":"mehmet-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sensizligin-ilk-mevsimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben ve Ben', 'ben-ve-ben-mehmet-yilmaz-a5e5a', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kayip bir adim var bu sahte sehirde

Simdi onu ariyorum sessizce.

Ama umutsuzum,

Cünkü, yelkovanla akrebin iliskisine benziyor arayisim.

Ben ariyorum o kaciyor.

Ben, benden kaciyor,

Icimdeki dügümü cözebilecek tek sey.

O da kaciyor benden.

Aslinda ismim buralarda bir yerlerde gizleniyor.

Ne olacagini bilmeden,

Bunca zaman hic gülmeden,

Yasayabilir mi ki icimdeki ben,

Dönüp gidersem, caresiz kalir

Bir türlü yasayamayan,

Ama hep düslenen sevdalarda gizlenen

Rüyalarda avare olmus derbeder ben.

Kayip bir isim,kayip bir siir,

Satir aralarinda bulmaya calisan ben.

Kendi kendime küsen,

Kendi kendine yasamaya calisan...

Benden geldigim yerlerde daha cok vardi benden.

Ama gözyaslari vardir hep yüreginde gizlenen,

Kirpiklerinde mesken tutmus,dudaklarinda nehir olmus ben.

Hep beni ben diye bilirdim,

Bir yanim köhne bir hayati sürdürürken,

Diger tarafim yasanmisligi anlatiyordu derinden.

Agacmis, yapraklarin altinda ezilen.

Dallari üstüme düsmüs, dallari kiran,ben.

Altinda ezilen, enkazi kalkmamis üzerimden.

Toza topraga bürünmüs,

Icimdeki depremi yaratan, kayip bir sehrin emsali olmus ben.

Simdi yasiyorum bensizlige inat,

Suc benim degil,beni benle yipratan, 

anlamini bulamadigim hayat.

Beni benle yasamak varken,

Aydinligimi götürmüs benden.

Ben benden cok uzaklarda yasarken.

Kayip ilani verecegim yüregimden.

Yoksa bensizligim ölüm olacak,

Beraber ölmek varken.', 'Kayip bir adim var bu sahte sehirde Simdi onu ariyorum sessizce. Ama umutsuzum, Cünkü, yelkovanla akrebin iliskisine benziyor arayisim. Ben ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Yılmaz']::text[], 8.5, '{"poet":"Mehmet Yılmaz","poet_slug":"mehmet-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/ben-ve-ben-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rahibe Dudaklı', 'rahibe-dudakli-burhan-kucuk-y8dzz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Rahibe Dudaklı

Ay ışığı / sonatına

Karar kıldığı zaman

Gri mavi hüzün düşer

Tavuk gezintisi akşamlara

Lotus gözlü kadın

Döner özüne

Başını yastığa koyduğunda

İlham verir

Rahibe dudaklarıyla

Öpüşen mısralara

Burhan KÜÇÜK

Kdz.Ereğli-28.12.2005', 'Rahibe Dudaklı Ay ışığı / sonatına Karar kıldığı zaman Gri mavi hüzün düşer Tavuk gezintisi akşamlara Lotus gözlü kadın Döner özüne Başını y...', ARRAY['Türk Edebiyatı','Şiir','Burhan Küçük']::text[], 8.5, '{"poet":"Burhan Küçük","poet_slug":"burhan-kucuk","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/rahibe-dudakli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'a-Senin için Türkiye’m', 'a-senin-icin-turkiye-m-mikdat-bal-sugi1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Senin için Türkiye’m

Yolunda ölsem de verilmez hakkın 

Ölüyorum senin için Türkiye’m 

Ne kadar uzaksan o kadar yakın 

Geliyorum senin için Türkiye’m 

Hep özledim memleketi, sılamı

Halen belli fuzulidir ilamı 

En samimi duygularla selamı

Salıyorum senin için Türkiye’m

Tek seni sevmektir benim hünerim 

Aşkınla yanarım yoksa sönerim 

Kalsam da ölsem de sana dönerim 

Kalıyorum senin için Türkiye’m 

Gözlerimi açtım ilk seni gördüm 

O gündür bu gündür hep seni sordum 

Özlüyorum seni ey benim yurdum 

Soluyorum senin için Türkiye’m 

Özlüyorum baba, kardeş bacımı

Bir gurbetçi anlar ancak acımı

Gam kederden tutam, tutam sacımı

Yoluyorum senin için Türkiye’m

Mikdadi’yim seni gönlümde sandım 

Canım, ruhum sensin hep seni andım 

Her an kalbimdesin sevginle kandım 

Doluyorum senin için Türkiye’m 

Ozan Mikdadi', 'Senin için Türkiye’m Yolunda ölsem de verilmez hakkın  Ölüyorum senin için Türkiye’m  Ne kadar uzaksan o kadar yakın  Geliyorum senin için T...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/a-senin-icin-turkiye-m-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oyna Yavrum Oyna', 'oyna-yavrum-oyna-sahin-erturk-uosw3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İşlerin tıkırında

Oyna yavrum oyna

Ziller takıp oyna

Kaşıklarla oyna

Davullarla oyna

Cümbüşlerle oyna

Tavernada oyna

Layla''larda oyna

Yılbaşında oyna

Düğünlerde oyna

Bayramlarda oyna

Kandillerde oyna

Felaketlerde oyna

Ölümlerde oyna

RİKİ Martinle oyna

Davut Güloğluyla oyna

Dansöz gibi oyna

Oyna yavrum oyna

Depremler oluyor

Savaşlar durmuyor

Açlıktan,soğuktan

İnsanlar,çocuklar ölüyor

Müslüman kanı durmuyor

Asler,Polis şehit düşüyor

Utanmadan,sıkılmadan

Hayvanlar gibi, 

Oyna yavrum oyna

(28.12.2005)', 'İşlerin tıkırında Oyna yavrum oyna Ziller takıp oyna Kaşıklarla oyna Davullarla oyna Cümbüşlerle oyna Tavernada oyna Layla''larda oyna Yılbaş...', ARRAY['Türk Edebiyatı','Şiir','Şahin Ertürk']::text[], 8.5, '{"poet":"Şahin Ertürk","poet_slug":"sahin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/oyna-yavrum-oyna-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üzüm Ve Toprağın Aşkı', 'uzum-ve-topragin-aski-osman-demircan-qqnuh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Her  üzüm  toprağa  aşıktır  aslında.

Kökleriyle  dilediğince  yayılmak

Dallarını  serbestçe  uzatmak

Yapraklarını  güneşle  doyurmak  ister.

Her  üzüm  toprağa  aşıktır  aslında.

Bir  avuç  toprakta  ömür  sürmek  ister.

Salkımlarını  tane  tane  lezzetle  doyurmak

Her  üzüm  kendini  çoğaltmak  ister.

Üzümün  gücü  şaraba  yansımaz  aslında.

O, gönüllerin  aşkla  sarhoş  olmasını  ister.', 'Her  üzüm  toprağa  aşıktır  aslında. Kökleriyle  dilediğince  yayılmak Dallarını  serbestçe  uzatmak Yapraklarını  güneşle  doyurmak  ister...', ARRAY['Türk Edebiyatı','Şiir','Osman Demircan']::text[], 8.5, '{"poet":"Osman Demircan","poet_slug":"osman-demircan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/uzum-ve-topragin-aski-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vehbi Koç-"siz hiç ay aşığında ağladınız mı" Kitabından', 'vehbi-koc-siz-hic-ay-asiginda-agladiniz-mi-kitabindan-omer-ekinci-micingirt-c36hr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Özgürlük kölesi dünya fâni de 

Unutma yârini unutulursun 

Sultan Süleymanlar nerde hâni de 

Mevsim bittiği gün o’nu bulursun 

Nefsin burgacında batma batağa 

Vehbi Koç nerede ve Sakıp ağa 

Hesapsız kitapsız yatma yatağa 

Nasıl yaşar isen öyle ölürsün 

Kendime feryadım kendime âhım 

Çocuksu nidayla ıslat ilahım 

Affeyle Allah’ım affet Allah’ım 

Duyan işiten sen, hâşâ bilirsin

Sen Affedicisin affı seversin', 'Özgürlük kölesi dünya fâni de  Unutma yârini unutulursun  Sultan Süleymanlar nerde hâni de  Mevsim bittiği gün o’nu bulursun  Nefsin burgacı...', ARRAY['Türk Edebiyatı','Şiir','Ömer Ekinci Micingirt']::text[], 8.5, '{"poet":"Ömer Ekinci Micingirt","poet_slug":"omer-ekinci-micingirt","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kendime-110-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnız Gül', 'yalniz-gul-cengiz-kapusuz-0fpg5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevgi bahçemin köşesinde,

Yalnız bir gül vardı.

O gülün halinden,

Birtek bülbül anlardı.

O gülün yalnızlığına,

İlham kaynağı oldu bir tek,

Bülbülün nağmelerine,

Sonsuza dek......', 'Sevgi bahçemin köşesinde, Yalnız bir gül vardı. O gülün halinden, Birtek bülbül anlardı. O gülün yalnızlığına, İlham kaynağı oldu bir tek, B...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Kapusuz']::text[], 8.5, '{"poet":"Cengiz Kapusuz","poet_slug":"cengiz-kapusuz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yalniz-gul-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Bilemezsin Küçüğüm', 'sen-bilemezsin-kucugum-sahin-erturk-hy8m2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Senin doğduğun gün

Benim öldüğüm yıldı

Sen yaşama merhaba

Ben hayata elveda

Sen bilemezsin küçüğüm

Hayal bile edemezsin

Senin yaşın,boyun kadar

Acı,hasret çektim ben

Ağırlığından daha fazla

Gözyaşı akıttım? 

Ben,senin gibi

Sevmeyi 

Kitaplardan öğrenmedim

Bilmem aldatmayı

Bilmem Televole yaşamayı

Sen bilemezsin küçüğüm

Bilemezsin

Benim gibi sevmeyi

Karşılıksız sevmeyi

Umutsuzca beklemeyi? 

Yaşın yetmez

Aklın ermez

Mantığın kabul etmez

Bir ölüyü

Tam otuz yıldır sevmenin

Zorluğunu sen bilemezsin

Bilemezsin küçüğüm

Bilemezsin...

(28.12.2005-Yeni)', 'Senin doğduğun gün Benim öldüğüm yıldı Sen yaşama merhaba Ben hayata elveda Sen bilemezsin küçüğüm Hayal bile edemezsin Senin yaşın,boyun ka...', ARRAY['Türk Edebiyatı','Şiir','Şahin Ertürk']::text[], 8.5, '{"poet":"Şahin Ertürk","poet_slug":"sahin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/sen-bilemezsin-kucugum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlat İstanbul', 'anlat-i-stanbul-hakki-hakan-kaya-eqlst', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben içimdeki çığlıkları

dindirirken

İstanbul''dan yükselir 

binlerce çığlık

ben içimdeki aşkları 

öldürürken

İstanbul''da doğar 

binlerce aşık

bilemedim 

kim daha hüzünlü

İstanbul''da yaşadıklarım mı? 

İstanbul''da yaşananlar mı?', 'Ben içimdeki çığlıkları dindirirken İstanbul''dan yükselir  binlerce çığlık ben içimdeki aşkları  öldürürken İstanbul''da doğar  binlerce aşık...', ARRAY['Türk Edebiyatı','Şiir','Hakkı Hakan Kaya']::text[], 8.5, '{"poet":"Hakkı Hakan Kaya","poet_slug":"hakki-hakan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/anlat-istanbul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bambaşka Bahar', 'bambaska-bahar-alper-kuruk-4gbbq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yeşili yeşil eden Allah

Sana çok şükürler olsun.

Yeşil göz gördüğüm anda 

Bambaşka bahar başlar ufkumda

Sihirli bakış dolu...

Güzel kokular hep o baharındır

Zevk desen üstelik öyle,

Her gözün daldığı hülya

Her gönüldeki umut

Güzelliklerle dolu yarındır.

Gün ışığıyla al al

Aşık sabrıyla sapsarıdır o bahar.

Aç yeşil gözlerini

Gözlerinin içinde bahar ve ben

Tek sensin aşkı öksüz eden...', 'Yeşili yeşil eden Allah Sana çok şükürler olsun. Yeşil göz gördüğüm anda  Bambaşka bahar başlar ufkumda Sihirli bakış dolu... Güzel kokular ...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bambaska-bahar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm', 'olum-alper-kuruk-9348s', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Can vücuda girdiğinde

Heves dolu bir giyiniş

Başlar çıplaklığı örterekten.

Yerinde can dururken

Gönül geniş.

Bir de

Can burnun ucuna gelmeye görsün

Gönül daralır

Geliş tersi bir gidiş.

Ölüm acı ve kara

Ama giydirir beyaz,

Alışır bu insanlar

Herşeye biraz biraz...', 'Can vücuda girdiğinde Heves dolu bir giyiniş Başlar çıplaklığı örterekten. Yerinde can dururken Gönül geniş. Bir de Can burnun ucuna gelmeye...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/olum-246-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cennet', 'cennet-siddik-usturbelli-oixal', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Cennet yüzlüm Cennet gözlüm

Sen Cennet''ten güzelmisin

Tatlı dillim doğru sözlüm 

Sen Cennet''ten güzelmisin

Dursun kalbim dönsün dünya 

Sen başıma oldun bela

Söndürmüyor beni Mevla

Sen Cennet''ten güzelmisin

Sen Cennet''ten güzel olsan 

Gül bahçeler senin olsa

Köşkün sarayın bol olsa 

Bensiz Cennet istermisin', 'Cennet yüzlüm Cennet gözlüm Sen Cennet''ten güzelmisin Tatlı dillim doğru sözlüm  Sen Cennet''ten güzelmisin Dursun kalbim dönsün dünya  Sen b...', ARRAY['Türk Edebiyatı','Şiir','Sıddık Usturbelli']::text[], 8.5, '{"poet":"Sıddık Usturbelli","poet_slug":"siddik-usturbelli","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/cennet-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Engerek', 'engerek-tevfik-karinca-h5k90', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yıktım zannetsem de bazı tabuları

Anladım ki kıramamışım kabukları

Değişmiyor insanın bazı huyları

Sevda bu kadar lanet şey

İnansam da sana gönülden

İnsansın korkuyorum 

Ya dönersen sözünden

Boşver diyorum bazen kendime

Kendi bilir yaparsa hata

Bu kadar çok seviliyorken

Bunca yıl verdiğimiz emeğe

Sevgi saygı muhabbete

Başka biri için değerse

Ne yarsın ne insan  benzersin engerek''e', 'Yıktım zannetsem de bazı tabuları Anladım ki kıramamışım kabukları Değişmiyor insanın bazı huyları Sevda bu kadar lanet şey İnansam da sana ...', ARRAY['Türk Edebiyatı','Şiir','Tevfik Karınca']::text[], 8.5, '{"poet":"Tevfik Karınca","poet_slug":"tevfik-karinca","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/engerek-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kanlım', 'kanlim-saadet-un-6sdp7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'izmarit artığı berbat anlarımda

yüreğim ağzımda

dönüşler gözlüyorum

beni soluyor çıldırasıya

ızbandut çocuklar

döşümde

iflah olmaz sancılarla

ilelebet hüzünlere

merdiven dayıyorum

kanlım oluyor sevdam...

kıyımda kalmış

az buçuk mutluluklara

son hıçkırığımdan

sevgiler yolluyorum', 'izmarit artığı berbat anlarımda yüreğim ağzımda dönüşler gözlüyorum beni soluyor çıldırasıya ızbandut çocuklar döşümde iflah olmaz sancılarl...', ARRAY['Türk Edebiyatı','Şiir','Saadet Ün']::text[], 8.5, '{"poet":"Saadet Ün","poet_slug":"saadet-un","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kanlim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Ayrılık', 'son-ayrilik-alper-kuruk-3gq6d', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hasreti benliğimle 

Ayrılık potasında kaynatıp

Bir yolculuğa çkıyorsun.

Beni elemli görünce

Eskiden cayardın ansızın

Buna benzemeyen yolculuklarından.

Benim üzgümü görsen de

Caymak olmaz şimdi bu yoldan

Anlıyorum,haklısın...

Yolcunun arkasından su dökerler

Tez dönsün diye.

İşte döküyorum ardından

Göz yaşlarımı selcesine

Ne gelen var ne dönen..

Seni bana değil

Beni sana götürecek bu sular...

Öbürlerinden farkı bu ayrılğında

Bir başka acı var niye?', 'Hasreti benliğimle  Ayrılık potasında kaynatıp Bir yolculuğa çkıyorsun. Beni elemli görünce Eskiden cayardın ansızın Buna benzemeyen yolculu...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/son-ayrilik-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Kitap', 'ben-kitap-sair-dyjn-l2832', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben Kitap

Ben bir kitabım, 

Arkamdan içimi okuyup hayat tezgâhından aldığın

Daha ilk sayfamda tutulduğun

Ve elinden bırakamadığın.

Ben bir kitabım,

Belki de bazı sayfalarımı beğenmediğin

Yarıda bırakmak istediğin

Ve masanın üzerine atıverdiğin.

Ben bir kitabım,

Dayanamayıp tekrar okumaya başladığın

Asıl anlamımı anladığın

Ve elinden bırakmaya kıyamadığın.

Ben bir kitabım,

Sayende düşünülen

İnsanların insan olmadığı yerde, kitap olarak var olan

Ve senin düşüncelerine giren.', 'Ben Kitap Ben bir kitabım,  Arkamdan içimi okuyup hayat tezgâhından aldığın Daha ilk sayfamda tutulduğun Ve elinden bırakamadığın. Ben bir k...', ARRAY['Türk Edebiyatı','Şiir','Şair Dyjn']::text[], 8.5, '{"poet":"Şair Dyjn","poet_slug":"sair-dyjn","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ben-kitap-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüya Bile Olsa Güzel', 'ruya-bile-olsa-guzel-yusuf-onder-bahceci-omajj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seni dün rüyamda gördüm,

Saçlarını tel tel ördüm,

Seni sevdim cân diyordun,

Rüya bile olsa güzel.

Gözlerine dalıp gittim,

Seni sevdim çabuk gittin,

Giderken de veda ettin,

Rüya bile olsa güzel.

Sözlerinde sitem vardı,

Gönlümü bir hüzün sardı,

Yalnız seni sevdim dedin,

Rüya bile olsa güzel.

Rüya gördüm yorarım ben,

Seni kimden sorarım ben,

Rüyalarda görürüm ben,

Rüya bile olsa güzel.....', 'Seni dün rüyamda gördüm, Saçlarını tel tel ördüm, Seni sevdim cân diyordun, Rüya bile olsa güzel. Gözlerine dalıp gittim, Seni sevdim çabuk ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ruya-bile-olsa-guzel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mor Salkım Ve Erguvan Ağacı', 'mor-salkim-ve-erguvan-agaci-ebru-demir-uwm7i', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir Cumartesi Geldi Mevsimlerin Baharı

Mor Salkımın İçinde İnce Bir Sızı

Mor Salkım Sarmaşıkların En Arsızı

Kendisine Muhtaç Bedenleri

Sevgiyle Sarar Kolları

Mor Salkım Karşılıklı Sevgiye Aç, Hali Acınılası

Tüm İhanetlere İnat Sevgiyle Büyütüyor Dallarını…

Bir Cumartesi Geldi Bahar Aşkı

Mor Salkımın İçinde İnce Bir Sızı

Mor Salkımın Gözleri Katran Karası

Onun İçin Varsa Yoksa Uzayıp Giden Kendi Dalları

Ki Bu Yüzdendir Görmemesi

Ardında Duran Erguvan Ağacını

Bir Cumartesi Çıkageldi Erguvan Ağacı

Mor Salkımın İçinde İnce Bir Sızı

Tüm Çiçekleriyle Erguvan Ağacı

Umutlandırdı, Mutlandırdı Mol Salkımı

Uzanabilir Miydi Kolları, Sarabilir Miydi Dalları

Bu Aşk Kokan Erguvan Agacını

Mor Salkım Bütün Gayretiyle Kendini Zorladı

Lakin Uzanamadı Kolları, Saramadı Dalları

İşte O Zaman Anladı Nafile Çabasını

Ve Köklerinin Asla Yerden Kalkmayacağını

Yine O Cumartesi Gitti Erguvan Ağacı

Mor Salkımın Eline Kalansa Onulmaz Bir Acı…', 'Bir Cumartesi Geldi Mevsimlerin Baharı Mor Salkımın İçinde İnce Bir Sızı Mor Salkım Sarmaşıkların En Arsızı Kendisine Muhtaç Bedenleri Sevgi...', ARRAY['Türk Edebiyatı','Şiir','Ebru Demir']::text[], 8.5, '{"poet":"Ebru Demir","poet_slug":"ebru-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/mor-salkim-ve-erguvan-agaci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bitkisel Hayat', 'bitkisel-hayat-dilek-ozturk-k1yxx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sevdiğim sensizlik  zora girdi iyice.

Ellerim hep titriyor,

Bedenimde bir soğukluk,

Gözlerimde yaşlar,

Dilimde adın,

Yüreğimde sancın…

Bitmez bir sessizlik içinde seni bekliyorum,

Ve bu sessizlik kulaklarımı yormakta.

Gözlerim hayalinin etrafında,

Ayırt edemiyorum senden başka hiçbir şeyi.

İsyan etsem kime ne,

Yada ağlasam delice.

Sessizce çekip gitsem kim anlar yokluğumu? 

Ama  bitkisel hayattayım ve kendi kendime gidemiyorum bile…

Ben sensizliğe mahkum ve mahkumiyetim bilinmemekte.

Ben sana hasret ve hasretim hiç dinmemekte.

Bertaraf ettim kendimi.

Sensiz her şeyden çektim elimi.

Yalnızlığın en koyu yerindeyim,

Sessiz bir sensizlik içinde.

Yaralarım ve ağrılarım var,

Bunları umursamaz tavırlarımda.

Olmamanın dışında hiçbir zorluk acıtmıyor artık beni.

Her şey anlamını yitireli epey oldu çünkü.

Sensizliğin bitkisel hayatındayım artık.

Birilerinin fişimi çekmesini bekliyorum,

Yada gelmen gibi bir mucizeyi…

                                                                                                                                                                     27 aralık 2005

                                                                                                                                                                            Dilek', 'Sevdiğim sensizlik  zora girdi iyice. Ellerim hep titriyor, Bedenimde bir soğukluk, Gözlerimde yaşlar, Dilimde adın, Yüreğimde sancın… Bitme...', ARRAY['Türk Edebiyatı','Şiir','Dilek Öztürk']::text[], 8.5, '{"poet":"Dilek Öztürk","poet_slug":"dilek-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/bitkisel-hayat-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duvak', 'duvak-saadet-un-d0koc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bir gelin kapıda

telli duvaklı

gözleri gözlerime bakar

umudu toprağa dönük

sevmiştir umutlarımı

içime, içime akar', 'bir gelin kapıda telli duvaklı gözleri gözlerime bakar umudu toprağa dönük sevmiştir umutlarımı içime, içime akar...', ARRAY['Türk Edebiyatı','Şiir','Saadet Ün']::text[], 8.5, '{"poet":"Saadet Ün","poet_slug":"saadet-un","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/duvak-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekle', 'bekle-memed-ayaz-xdzi8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '''caanıma ''

Düştüm yollarına

Ellerimde sen kokusu

Karnım boş

Gönlüm sen dolu…

Çiçekler topladım sana yağmurdan

Birde ben..

Sarıldım şemsiyeme, koşarak GELİYORUM…

Keldağ

Aralık-2005', '''caanıma '' Düştüm yollarına Ellerimde sen kokusu Karnım boş Gönlüm sen dolu… Çiçekler topladım sana yağmurdan Birde ben.. Sarıldım şemsiyeme...', ARRAY['Türk Edebiyatı','Şiir','Memed Ayaz']::text[], 8.5, '{"poet":"Memed Ayaz","poet_slug":"memed-ayaz","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bekle-43-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bulutlara', 'bulutlara-alper-kuruk-rlbkn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ey,başımın üstündeki bulutlar

İçimden geçenleri bir bir

Gözlerimle üstünüze yazsam

Ona götürür müsünüz? 

Ben bilmiyorum şimdi o nerde? 

Ama siz göğünden geçeceksiniz

Ey bulutlar siz

O kadar çok sevdiklerimizsiniz

Ki  başımız üstünde yeriniz var

Ve daima başımız üstünde gezersiniz.

Bulutlar,ey bulutlar

Varın,iletin gözlerimle dediklerimi

Eğer o görmezlikten gelirse

Suratınızı asın ona

Kararın kalbim gibi

Daha umursamazsa

Ne olur benim yerime ağlayın

Islatın göz yaşlarınızla onu yağmur yağmur

Ama,üşütmeyin sakın...', 'Ey,başımın üstündeki bulutlar İçimden geçenleri bir bir Gözlerimle üstünüze yazsam Ona götürür müsünüz?  Ben bilmiyorum şimdi o nerde?  Ama ...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/bulutlara-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Tek Tebessümün Bile', 'bir-tek-tebessumun-bile-huseyin-erdogan-kcp5c', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'her gün güneş yeniden doğsa 

pırıl pırıl bir sabah olsa da

zifiri karanlıktır benim dünyam

eğer sen yoksan yanımda

ömrüm boyunca

ellerini hiç tutamasam da

yalnızca sensin benim hülyam

sensin gecelerimdeki tek rüyam

gönül bahçemde 

bahar yelleri estikçe

sen benim ömrümce 

mis gibi kokacak sardunyamsın

ölünceye değin hiç bitmeyecek

emsalsiz eşsiz sevdamsın

gonca güller farklı açar

senin her gülüşünde

rengarenk gelir bahar

kırlara bahçelere

kokuların en güzelleri

senden yayılır her yere

uzaktan da olsa

bir tek tebessümün bile

çaredir bendeki bin derde

bazan dalar gider gözlerim

senden yana

baktığım her yerde

yalnızca sen varsın cana

kollarımla seni bir kez bile 

sımsıkıcasına saramasam da

şiirim vallahi razı olurum buna

yeter ki hiç kimse değmesin sana

                                 28.12.2005

                             Hüseyin Erdoğan', 'her gün güneş yeniden doğsa  pırıl pırıl bir sabah olsa da zifiri karanlıktır benim dünyam eğer sen yoksan yanımda ömrüm boyunca ellerini hi...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/bir-tek-tebessumun-bile-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilek', 'dilek-memed-ayaz-44qo9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '''caanıma ''

Uğurlardan mim düşürdüm rüzgara	

Sen ki bir başına esemeyesin

Kulağından çekip astım gönlümü

Sen ki rüyasından eksilmeyesin

Dar’a saldın şu uslanmaz aklımı

Nar’a verdin bende hoyrat gönlümü

Bende sandım, sende buldum aslımı

Bensiz

          Bu cihanı dilemeyesin…..

Keldağ

Aralık-2005', '''caanıma '' Uğurlardan mim düşürdüm rüzgara	 Sen ki bir başına esemeyesin Kulağından çekip astım gönlümü Sen ki rüyasından eksilmeyesin Dar’a...', ARRAY['Türk Edebiyatı','Şiir','Memed Ayaz']::text[], 8.5, '{"poet":"Memed Ayaz","poet_slug":"memed-ayaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/dilek-111-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlayanlar', 'aglayanlar-alper-kuruk-1oxbk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Damla damla vişne kanı

Tuzlu tuzlu yaşlı gözler,

Duymazlar ki sustursunlar 

İçin için ağlayanı.

Aşk günleri demet demet

Anılarda ıslanmış,

Geçen her gün tüter elbet

Burcu burcu burunda.

Sarı sarı yeşil yaprak

Solgun solgun pembe beniz,

Kara kara kara toprak

Meğer biz de sendeniz.

Bizi bize bağlayanı

Bizim için ağlayanı

Ağlatmasın Tanrı''m gayrı...', 'Damla damla vişne kanı Tuzlu tuzlu yaşlı gözler, Duymazlar ki sustursunlar  İçin için ağlayanı. Aşk günleri demet demet Anılarda ıslanmış, G...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/aglayanlar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat', 'hayat-memed-ayaz-uwn14', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '''caanıma ''

Gözleri süt bakar gecenin

Kokusu bala çalar

Sevda kör açar tüm çiçeklerini

Ama gözlüklülerine de rastlanır..

Velhasılı hayat gariptir…

Birazda kısa boylu

Keldağ

Aralık-2005', '''caanıma '' Gözleri süt bakar gecenin Kokusu bala çalar Sevda kör açar tüm çiçeklerini Ama gözlüklülerine de rastlanır.. Velhasılı hayat gari...', ARRAY['Türk Edebiyatı','Şiir','Memed Ayaz']::text[], 8.5, '{"poet":"Memed Ayaz","poet_slug":"memed-ayaz","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/hayat-274-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'UB-046 Dönüşüm! ..', 'ub-046-donusum-mehmet-coban-e6bla', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bütün siyasi fikirler

İnsanlığa sunulan dinler

İdeolojiler, izmler

En güzel duygularla 

Sunulur insanlara 

Temellerinde insanlık

Temellerinde kardeşlik

Adalet gözetilir yasalarında 

Ama sonradan 

Ne olmuşsa olur

Araya çıkarlar girer

Yok, olur ilkeler 

Birer, birer, birer

Ortada kalan dogmalardır

Saçmalıkla dolu kurallardır

Güzel şeylerin üzeri örtülmüştür

İnsanların benlikleriyle örülmüştür

Aşıp ulaşamazsın güzelliklere

Üzülürsün sadece yok olan fikirlere

İnsanlara sunulan fikirlerin özünde

“İnsanların ilkelere aykırı yaptığı şeyler

İnsanın kendi benliğine hesapla döner

İnsanın ilkelere göre yaptığı şeyler

İnsana, insanlığa hayırla döner”

Bu özleri ararım her yerde

Hep karşıma çıkan ise,

“İlkeler, insanlardan fedakârlık isterken

Gördüm, insanları ilkeleri kurban ederken”

Beklesin artık insanlık yeniden

Kurtarıcı mı gelecek bir daha, neden? 

Ey insan, biz değil miyiz? 

Bütün güzellikleri yok eden! ..

28.12.2005-İzmir', 'Bütün siyasi fikirler İnsanlığa sunulan dinler İdeolojiler, izmler En güzel duygularla  Sunulur insanlara  Temellerinde insanlık Temellerind...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Çoban']::text[], 8.5, '{"poet":"Mehmet Çoban","poet_slug":"mehmet-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/ub-046-donusum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tek Sen Söyle', 'tek-sen-soyle-alper-kuruk-8kar5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Tek senin ağzından duymak istiyorum

Bütün kelimeleri...

Sen daha güzel heceliyor

Daha güzel söylüyorsun.

Söylediğin en kötü sıfatlar bile

O kadar iyi ve güzel ki...

Aşkın gözü kördür

Kulağı sağır.

Her kötü sözün

Bana güzelliğin kadar güzel geliyor

Ah! aşk bir de dilsiz olsaydı

Ne dillere destan olurdu

Ne masallara konu...', 'Tek senin ağzından duymak istiyorum Bütün kelimeleri... Sen daha güzel heceliyor Daha güzel söylüyorsun. Söylediğin en kötü sıfatlar bile O ...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/tek-sen-soyle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Sevdim Severim', 'seni-sevdim-severim-yusuf-onder-bahceci-g00ht', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gönül ferman dinlemez,

Sevdi ama söylemez,

Hiç kimseyi dinlemez,

Seni sevdim severim.

Seni sevdim seviyorum,

Sana gönül veriyorum,

Sevdim ama demiyorum,

Seni sevdim severim.

Rüyalarda görsem seni,

Seviyorum desem seni,

Verem ettin beni beni,

Seni sevdim severim.

Güzel sevdim severim,

Var gücümle överim,

Senden ayrı neylerim,

Seni sevdim severim.....', 'Gönül ferman dinlemez, Sevdi ama söylemez, Hiç kimseyi dinlemez, Seni sevdim severim. Seni sevdim seviyorum, Sana gönül veriyorum, Sevdim am...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/seni-sevdim-severim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeni Yıl Yeni Kahır', 'yeni-yil-yeni-kahir-funda-sengul-gdyq0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir yıl daha bitti ama iyi ama kötü bitti

Takvim acımasızca yırtmakta gençliğimi

Herkes yeni yıl coşkusu içinde,bilmiyorlar ki

Ömrün bitiyor,yaptığın koca bir hiç,acaba niye sevinçli

Her yıl birşeyler koparıp alıyor senden

Niye bu sevinç bir de amelsiz,tövbesizsen 

Vatanın için,uyutanları destekleyip,uyumuşsan

Neden bu sevinç,gelecek nesil için bir şey yapmadıysan 

Boş geçen bir yıl daha bitti diye hayıflansana

TÜRK ''e sövenler baş tacı ediliyor,duysana

Her geçen yıl özbenliğin daha fazla unutturuluyorsa

Bu yeni yıl sevinci nedir,ALLAH aşkına! ! ! .......', 'Bir yıl daha bitti ama iyi ama kötü bitti Takvim acımasızca yırtmakta gençliğimi Herkes yeni yıl coşkusu içinde,bilmiyorlar ki Ömrün bitiyor...', ARRAY['Türk Edebiyatı','Şiir','Funda Şengül']::text[], 8.5, '{"poet":"Funda Şengül","poet_slug":"funda-sengul","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yeni-yil-yeni-kahir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerime Bakıp Gitti', 'gozlerime-bakip-gitti-yusuf-onder-bahceci-kq5bk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gözlerinde yaşlar vardı,

Gizli gizli ağlıyordu,

Derdi nedir soramadım,

Gözlerime bakıp gitti.

Gelde şimdi kahrolma,

Gül gibi sararıp solma,

Özlemlerim özde kaldı,

Gözlerime bakıp gitti.

Derdi ile ölürüm ben,

Onu nasıl görürüm ben,

O da sever bilirim ben,

Gözlerime bakıp gitti.

Şimdi onu sormazmıyım,

Deli gönül bilmezmiyim,

Ben yolunda ölmezmiyim,

Gözlerime bakıp gitti.', 'Gözlerinde yaşlar vardı, Gizli gizli ağlıyordu, Derdi nedir soramadım, Gözlerime bakıp gitti. Gelde şimdi kahrolma, Gül gibi sararıp solma, ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gozlerime-bakip-gitti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şu Bir Bardak Şarapta VI', 'su-bir-bardak-sarapta-vi-i-brahim-balci-elb5k', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir göçmen kuştur gönül,ne sahibidir kimsenin

Ne de meyillidir kulluğuna, ebediyyen birisinin

Şu bir bardak şarapta sadakat buldu ruhum

Sen ki ey Panelope,kadim bir sadık kulsun

Mümkün mü unutmak,kıskanmamak uçan kuştan

Öpemeden,koklamadan,salkım saçak sarılmadan

Şu bir bardak şarapta mutluluk buldu ruhum

Sen ki ey güneş yüzlüm,kadim bir Atropos’sun

Aşk,doğmazmış yeniden,dirilirmiş sadece

Bilmem senin halini,tutkuyla doğdu bende

Şu bir bardak şarapta Sertacı buldu ruhum

Sen ki ey  kızıl saçlı karnımdaki Yunus’sun', 'Bir göçmen kuştur gönül,ne sahibidir kimsenin Ne de meyillidir kulluğuna, ebediyyen birisinin Şu bir bardak şarapta sadakat buldu ruhum Sen ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Balcı']::text[], 8.5, '{"poet":"İbrahim Balcı","poet_slug":"i-brahim-balci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/su-bir-bardak-sarapta-vi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hatırlamalı', 'hatirlamali-asli-yildiran-hor49', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sana sapladığım hançer 

yaralıdı beni de 

bak kanıyor yüreğim damla damla

Sana fırlattığım ok geri döndü 

saplandı yüreğime

Şimdi ağlamak boşa, çare yok 

Ağlatan ağlayacak,yakan yanacak bu ateşte

boşuna çırpınmalar biliyorum

boğulacak kim ittiyse birilerini bu okyanusa

Sana sapladığım hançer 

yaraladı beni de

yaktığım ateşler yaktı beni de alev alev

sana edilen sözler geri dönüp 

karşıma dikildiler...

Şimdi ağlamak boşa biliyorum

Ağlatan ağlayacak,yakan yanacak bu ateşte

boğulacak kim ittiyse birilerini bu denize

mavisine gömülürken nefessiz kaldığında 

hatırlamalı insan kimleri boğduysa bu sularda...

28.12.2005 - Hatırlamalı insan kanattığı serçeleri,soldurduğu çiçekleri', 'Sana sapladığım hançer  yaralıdı beni de  bak kanıyor yüreğim damla damla Sana fırlattığım ok geri döndü  saplandı yüreğime Şimdi ağlamak bo...', ARRAY['Türk Edebiyatı','Şiir','Aslı Yıldıran']::text[], 8.5, '{"poet":"Aslı Yıldıran","poet_slug":"asli-yildiran","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/hatirlamali-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zulmüm Kendime', 'zulmum-kendime-alper-kuruk-e2hvu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir bulut gelir kapkara 

Bir yağmur başlar arkasından

Bir gün başlar toprak kokulu

Ve biter kimi neş''e kimi dert dolu.

Bir bahar gelir kırıtarak

Ardısıra bir kızgın yaz

Ve beni kızdırır hayata karşı

Gelgelelim ruhu açmaz.

Göğümden bir bulut geçer

Aklımdan hayata küsmek geçer

Gönlümden bir tatlı umut geçer

Bir kızar,bir melek kesilirim

İnanın aklımdan kötülük geçmez

Kendime zulmüm hep böyle benim.', 'Bir bulut gelir kapkara  Bir yağmur başlar arkasından Bir gün başlar toprak kokulu Ve biter kimi neş''e kimi dert dolu. Bir bahar gelir kırıt...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/zulmum-kendime-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadınlığım', 'kadinligim-saadet-un-7l2iz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ey güçlülüğüm! 

ey mağrurluğum! 

ey kadınlığım! 

ey kadınlığımın çizgili yüzü, ak saçları,

deforme olmuş vücut ölçüleri

ey yorgunluğum! 

ey bitkinliğim! 

ey geceleri mat sabahları şah olan ruhum

bu güçlülüğün

bu savaşın

bu er meydanlarına inişin niye? 

sen değil miydin ki! 

bir babanın ayak izleri altında ezilen

sen değil miydin ki! 

bir erkek barbarlığında tükenen

ve sen değil misin ki

anıların uyandırdığı seslerden bile ürperen

bir çocuk ruhuyla

yaşayan

korkan

korktukça da sığınacak yer arayan

ey kadınlığım! 

çok mu yalnızsın? 

çocukların birer birer büyüdü de

kopardı mı ellerinden ellerini

yoksa unuttular mı

yalnız onlarla tek bir dünya oluşturduğunu

sevgiler aramayıp

sevgisiz aşksız bir dünyaya oy verdiğini

bak işte! bu odan

çelik dolabın çelik etajerin ve masan

ve ranza bozuntusu karyolan

haydi gel

gir yüreğimdeki mahzenine

haberin ola

yakışmıyor

pembe gözlüklerin kara gözlerine

ey kadınlığım! 

ne olmaktasın ne durumdasın ki

yüreğinde saklı duygularını

böyle ulu orta yerlere sermektesin

meçhullere dalmakta

duygusuz duyarsız resim karelerinde

bir yudum gülümseme aramaktasın

lanet olsun! 

e be kadınlığım! 

sus be kadınlığım! 

boşuna söylememiş el oğlu

kendine sarıl! diye

peki bu acizliğin niye? 

haydi durma

tut halayının başını

bas zılgıtını

kuşan yine tepeden tırnağa

kadınsı yiğitliğini

kutla kadınlığım, kutla kadınlığının,

tek kişilik oyununu...', 'ey güçlülüğüm!  ey mağrurluğum!  ey kadınlığım!  ey kadınlığımın çizgili yüzü, ak saçları, deforme olmuş vücut ölçüleri ey yorgunluğum!  ey ...', ARRAY['Türk Edebiyatı','Şiir','Saadet Ün']::text[], 8.5, '{"poet":"Saadet Ün","poet_slug":"saadet-un","theme":"Türk Şiiri","is_hero":false,"total_lines":57,"source_url":"https://www.antoloji.com/kadinligim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kavuşma', 'kavusma-alper-kuruk-o76of', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Anamın fedakârlığını unutmam hiç

Sütünü paylaştım çocukluğumda

Uykusunu böldüm geceleri...

Anam günlerini bana hasretti.

Felek bizi ayırdığı gün

Koca erkek olsam da

Yine büyümemiştim anamın nazarında

Bilirim,ayrılığın acısını duyurmamak için

Benim duyacağım acıyı da o çekti

Kendi acısına üstelik.

Anamı o acılar mahvetti...

Bu kavuşma sahnemize gülmeyin

Ben erkektim,ağlayamazdım

Öylesine gülüp geçiştirdim

Ama anam tutamazdı gayrı yaşlarıı...

Anam şimdiye dek yine iyi sabretti

Anam bunca yıldır bana hasretti...', 'Anamın fedakârlığını unutmam hiç Sütünü paylaştım çocukluğumda Uykusunu böldüm geceleri... Anam günlerini bana hasretti. Felek bizi ayırdığı...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kavusma-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sabredebilirim sensizlige...', 'sabredebilirim-sensizlige-tarik-teke-g0rsn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'derin denizlerin sükunetini

ve maviligini buldum gözlerinde

onlar kadar etkileyici

ve onlar kadar dinlendiriciler bence

işte aklımdan gitmeyen o maviligin hayaliyle

dalıyorum bende uzaklara ve derinlere..

bilemiyorum daha ne kadar sabredebilirm sensizlige

ve ne kadar yaşayabilirim bu hayalle

ama,,şimdi önünde diz çöken tüm benligimle

hayalin gerçege dönüşmesini bekliyorum belkide..

MART/2005', 'derin denizlerin sükunetini ve maviligini buldum gözlerinde onlar kadar etkileyici ve onlar kadar dinlendiriciler bence işte aklımdan gitmey...', ARRAY['Türk Edebiyatı','Şiir','Tarık Teke']::text[], 8.5, '{"poet":"Tarık Teke","poet_slug":"tarik-teke","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sabredebilirim-sensizlige-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Sevdasından Ölsen', 'sevdasindan-olsen-temel-duran-7k1a0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aşklar parmak izi  gibidir derler

Hiçbiri birine  benzemez imiş

Gözden akan yaşla  ıslansa yerler

Toprak nankör ise  ot bitmez imiş

Akıl kontör değil yüklenmez derler

Kullanan sonradan doldurmaz imiş

Yiğide bir sevda musallat olsa

Ne akıl ne yürek kar etmez imiş

Sevdasından ölsen  çürüse beden

Yarda insaf yoksa  inanmaz imiş

Gariban doğmuşsan ne gelir elden

Biçare dünyada gülemez imiş

Felek bülbül edip figana salar

Ah-ı figanını yar duymaz imiş

Mecalin tüketip ummana salar

Meğer çektiklerin az gelir imiş

Kulağına küpe olsun evladım

Hiç kimse nasihat istemez imiş

Azrail  gelince duymaz imdadın

Yar senin yerine can vermez imiş

İnsan karşılıksız  severse eğer

Aşkın zincirini  kıramaz imiş

Boş yere kendini  tüketme yeter

Alına yazılan  değişmez imiş', 'Aşklar parmak izi  gibidir derler Hiçbiri birine  benzemez imiş Gözden akan yaşla  ıslansa yerler Toprak nankör ise  ot bitmez imiş Akıl kon...', ARRAY['Türk Edebiyatı','Şiir','Temel Duran']::text[], 8.5, '{"poet":"Temel Duran","poet_slug":"temel-duran","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sevdasindan-olsen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İktidar', 'i-ktidar-turgay-ceritoglu-5w6sn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'yalnızlık bir seçimdir 

tek oyla iktidar olan 

diretilmiş, istenmiş ne yazılmışsa 

bizle alakalı/habersiziz 

doğru... 

derin yaralar aldım 

senle girdiğim meydan savaşlarında 

ama benim bütün kayıplarım 

masa başlarında 

sırf sen yoksun diye 

doğru dürüst vaatler yok işin içinde 

içi koca bir boşlukla dopdolu 

hatta yamalı 

biraz azgın 

çok çok yorgun umutlar 

intihar eder usumda 

inan bu her neyse 

ve her kimdeyse fırçalar 

tam zamanıdır tavşan kanı gecelerin 

ebruli yalanlar çarpar duvarlara 

arar bulur, sarıp sarmalar bizi 

bir sessizlik peydahlar gece, 

korkutur ikimizi.', 'yalnızlık bir seçimdir  tek oyla iktidar olan  diretilmiş, istenmiş ne yazılmışsa  bizle alakalı/habersiziz  doğru...  derin yaralar aldım  ...', ARRAY['Türk Edebiyatı','Şiir','Turgay Ceritoğlu']::text[], 8.5, '{"poet":"Turgay Ceritoğlu","poet_slug":"turgay-ceritoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/iktidar-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadın da Bir İnsan', 'kadin-da-bir-i-nsan-timur-i-likan-44ttj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Erkek de bir insan

Kadın da bir insan

Konuştukları hep bir lîsan

Öyleyse birini diğerinden 

Niçin ayrı tutar ki  insan? 

(28 Aralık 2005/ İstanbul)', 'Erkek de bir insan Kadın da bir insan Konuştukları hep bir lîsan Öyleyse birini diğerinden  Niçin ayrı tutar ki  insan?  (28 Aralık 2005/ İs...', ARRAY['Türk Edebiyatı','Şiir','Timur İlikan']::text[], 8.5, '{"poet":"Timur İlikan","poet_slug":"timur-i-likan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/kadin-da-bir-insan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acele Sahibinden - 1', 'acele-sahibinden-1-ahmet-unal-cam-lwhf3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yer darlığından gönlümde

Sahibinden hüzünler, acele', 'Yer darlığından gönlümde Sahibinden hüzünler, acele...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ünal Çam']::text[], 8.5, '{"poet":"Ahmet Ünal Çam","poet_slug":"ahmet-unal-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/acele-sahibinden-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kara Tren', 'kara-tren-latif-oz-l7t8a', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kara tren uzar gider

Ciğerparem ezer gider

Yuvamızı bozar gider

Alma tren ver yarimi

Boş evlerden sor halimi

Kara tren duman olur

Yar yarası yaman olur

Onu da gurbet el alır

Alma tren alma tren

Evim yurdum oldu viran', 'Kara tren uzar gider Ciğerparem ezer gider Yuvamızı bozar gider Alma tren ver yarimi Boş evlerden sor halimi Kara tren duman olur Yar yarası...', ARRAY['Türk Edebiyatı','Şiir','Latif Öz']::text[], 8.5, '{"poet":"Latif Öz","poet_slug":"latif-oz","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/kara-tren-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acele Sahibinden - 2', 'acele-sahibinden-2-ahmet-unal-cam-dw5n6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sahte dostluklar

Tükenmiş umutlar

Vadesi dolmuş

      çocukluk düşleri

Kullanılmamış

     mutluluk gülüşleri

Ardına bile bakmadan

        yarin gidişleri

Kötü hatıralarım

Mahzun bakışlarım

Kurumuş göz yaşlarım

……sessiz isyanlarım

Bitmemiş şiirlerim

Yalnızlığı alnından 

            Öpüşlerim

yeni boşalmış gönlüm

Kısaca,zayi olmuş ömrüm

Bitmeden bu hüzün dolu gece

     …..sahibinden acele', 'Sahte dostluklar Tükenmiş umutlar Vadesi dolmuş       çocukluk düşleri Kullanılmamış      mutluluk gülüşleri Ardına bile bakmadan         ya...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ünal Çam']::text[], 8.5, '{"poet":"Ahmet Ünal Çam","poet_slug":"ahmet-unal-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/acele-sahibinden-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Afonisiz Çığlık', 'afonisiz-ciglik-tulay-sustam-b4v9b', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'sendeki 

kalıcılığımı uğurladım

yüreğimin koridorlarından

el salladım

güvercin kanadıyla

bir martı; 

göz kırptı yalnızlığıma

sırtımı sana döndüm

şimdi daha beyazım



27 aralık

şiirim kendime', 'sendeki  kalıcılığımı uğurladım yüreğimin koridorlarından el salladım güvercin kanadıyla bir martı;  göz kırptı yalnızlığıma sırtımı sana dö...', ARRAY['Türk Edebiyatı','Şiir','Tülay Sustam']::text[], 8.5, '{"poet":"Tülay Sustam","poet_slug":"tulay-sustam","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/afonisiz-ciglik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söyle Şimdi Ne Dersin', 'soyle-simdi-ne-dersin-yusuf-onder-bahceci-up3q5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Güllermi güzel, senmi güzelsin,

Bu kalbimi böyle üzer gidersin,

Söyle şimdi sen ne dersin,

Kalbimdeki bu sevdaya.

Gizli gizli ağlıyorum sevdiğim,

Seni sevdim yaralıyım sevdiğim,

Sensin benim gönül verip sevdiğim,

Söyle şimdi ne dersin.

Senin için cân veririm sevdiğim,

Seni sevdim cân bildiğim sevdiğim,

Elimden birşey gelmiyor ki sevdiğim,

Söyle şimdi ne dersin.

Ölene dek ağlarım ben sevdiğim,

Bir köşede ölürüm ben sevdiğim,

Kimse sormaz kimdir diye sevdiğim,

Söyle şimdi ne dersin...', 'Güllermi güzel, senmi güzelsin, Bu kalbimi böyle üzer gidersin, Söyle şimdi sen ne dersin, Kalbimdeki bu sevdaya. Gizli gizli ağlıyorum sevd...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/soyle-simdi-ne-dersin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık', 'yalnizlik-demet-tarakci-l1fvr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yalnızlık

Ne azap ne de sitem bu 

Kim aşmışki yalnızlığı

Kendine göre acımasızlık 

Ona göre kıskançlık

Yalnız kalınca birini ararsın

Ararsın ararsın bulamazsın

Başından geçenleri yazmaya kalkarsın

Hep yazar hep yazarsın

Sana akıl veremeyince

Yine yalnız, mutsuz,umutsuz kalırsın.

Birden belki birgün diye düşünürsün

Ama sen de umutsuzdursun

Birgün karşına biri çıkar 

Elini kolunu bağlar

Yine yazarsın

Mutluluktan sana akıl verdiginin üstüne basarsın

Birşeyler olur

Bir oraya bir buraya bakarsın

Ve yine yalnız kaldığını anlarsın

Geçirdigin güzel günleri 

Düşünür avunmaya çalışırsın

Kendine bakar 

Hala iki kolun iki ayağın olduğunu anlarsın

Ama hep birşeyi düşünmek işine gelmez

O da hep kalbinde fazlalık vardır

O fazlalık senden bircok sey almıştır

Kalbinin yarısının hala onda oldugunu unutmamışsındır

Herkesi kandırıp kandırıp durursun

Ama kendini kandıramadığını düşünemezsin

Eline somut bir delil çıkarmaya çalışırsın

Ararsın ararsın ve sonunda bulursun 

Buldugun sey unutturur kendini

Çünkü hala yalnızsın...', 'Yalnızlık Ne azap ne de sitem bu  Kim aşmışki yalnızlığı Kendine göre acımasızlık  Ona göre kıskançlık Yalnız kalınca birini ararsın Ararsın...', ARRAY['Türk Edebiyatı','Şiir','Demet Tarakçı']::text[], 8.5, '{"poet":"Demet Tarakçı","poet_slug":"demet-tarakci","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/yalnizlik-320-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tebessümün Yeter Bana', 'tebessumun-yeter-bana-savas-dincbas-c4f45', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'yüzündeki tebessümü

özlüyorum inan bana

gül demiyorum

kahkaha da istemem

tebessümün yeter bana

hüzün sana yakışmıyor

sen gülünce güzelsin

bir küçük gülüşünle

gül bahçesine bedelsin

gül demiyorum

kahkaha da istemem

tebessümün yeter bana...', 'yüzündeki tebessümü özlüyorum inan bana gül demiyorum kahkaha da istemem tebessümün yeter bana hüzün sana yakışmıyor sen gülünce güzelsin bi...', ARRAY['Türk Edebiyatı','Şiir','Savaş Dinçbaş']::text[], 8.5, '{"poet":"Savaş Dinçbaş","poet_slug":"savas-dincbas","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/tebessumun-yeter-bana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu da benden olsun', 'bu-da-benden-olsun-baykal-kaanalp-09vzt', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'gelecekte bir çarpıntımız olacak

herhangi bir yerimizde

belki bunlar için çok erken

belki de geç kalınmış bir durak

yaman çelişkimiz olacak

kendi ellerimizle doldurduğumuz

küfelerimiz yanımızda kokacak

taşımaya cesaretimiz kalmayacak

bir fırtına ki bizi de ayıklayan

kendimiz oluşumuzdan

olamayışımızdan belki de

kullanabilirmiyiz her türlü

pinpirik cefayı

yakmak için günahlarımızı

çırpındığımız gelecekte

ateş bile bazen soğuyacak

buz kalıbı tenimizde

hala var olan umudumuz

sönmüş volkanların altına gizlenmiş

tutuşturulmayı bekliyor olacak

bir nesil boyu ateşli çırayla

saklı tutuyorum dokunulmazlığını

sesimin, rengimin, soluğumun

ihtiyacım olduğunda yeniden

ortaya dökebilmek için

sınırları çizilmemiş cesaretimle

korkusuzluğuyla gerginliğimin

gerilmişliğimin bir kancayla

ufak ufak yaklaşan

azar azar çoğalan

kof rengi bulutsuzluğunu

ödemsizliğin sınırına

dikiyorum şimdiden

bu da benden olsun', 'gelecekte bir çarpıntımız olacak herhangi bir yerimizde belki bunlar için çok erken belki de geç kalınmış bir durak yaman çelişkimiz olacak ...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/bu-da-benden-olsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dokunmaz Bana', 'dokunmaz-bana-temel-duran-h17v7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bırakıp aşkımı  giderim sanma

Bir cennet bahçesi  verseler bana

Sensiz olacaksa  yaşarım sanma

Şu ulu cihanı  verseler bana

Sen yoksan gözümde  yaşlar diner mi

Sevdan yüreğimde atsam gider mi

Düşlediğim hayat  sensiz geçer mi

Neye yarar karun deseler bana

Yazık etmeyelim  bu böyle sürmez

Bak geçiyor hayat  bir daha gelmez

Bu can sevdi seni asla vazgeçmez

Sonsuz ömür vaad etseler bana

Bir şiir yazmaktı  niyetim sana

Benim canım taştan demirden sanma

İnan ki çok sevdim  kıyma bu cana

Kalbim parçalansa  dokunmaz bana

Temel reis derki düşmem tasaya

Aşkın yüreğimde koskoca kaya

sensiz gitmem bilki öte dünyaya

Vakit doldu hadi deseler bana', 'Bırakıp aşkımı  giderim sanma Bir cennet bahçesi  verseler bana Sensiz olacaksa  yaşarım sanma Şu ulu cihanı  verseler bana Sen yoksan gözüm...', ARRAY['Türk Edebiyatı','Şiir','Temel Duran']::text[], 8.5, '{"poet":"Temel Duran","poet_slug":"temel-duran","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/dokunmaz-bana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmiyorum Bilmiyorum', 'bilmiyorum-bilmiyorum-yusuf-onder-bahceci-vvjbb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu şiirler sevdiğime,

Sevip gönül verdiğime,

Güzel olmuş dermi ki,

Bilmiyorum bilmiyorum.

Bu şiirleri okurmu ki,

Onu sevdim bilirmi ki,

Bana dua edermi ki,

Bilmiyorum bilmiyorum.

Onu sevdim dermi ki,

Gönül verdim dermi ki,

Ona selam dermi ki,

Bilmiyorum bilmiyorum.

Seven kalbi bilirmi ki,

Bana yazmış dermi ki,

Güzel olmuş dermi ki,

Bilmiyorum bilmiyorum.', 'Bu şiirler sevdiğime, Sevip gönül verdiğime, Güzel olmuş dermi ki, Bilmiyorum bilmiyorum. Bu şiirleri okurmu ki, Onu sevdim bilirmi ki, Bana...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bilmiyorum-bilmiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşmanı Böyle Kovduk', 'dusmani-boyle-kovduk-i-brahim-pataz-a3lb8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bölge bölge paylaşıldı yurdumuz,

Kuvvetler dererek, kovduk düşmanı.

Ne cephane vardı, ne de ordumuz,

Çeteler kurarak,  kovduk düşmanı.

Toplandık,  biz bize, aldık kararı,

Gecikmeden, uyguladık kuralı,

Kimin oluyorsa,Türk’e zararı,

Hakkını vererk, kovduk düşmanı.

İngiliz, Fransız, Yunan arsızı,

Tutsak yaşamaya, zorladı bizi,

Dolma tüfeklere, söylettik sözü,

Hesabı sorarak, kovduk düşmanı

Sahiplenip, evi, barkı, sarayı,

Seçtirdiler bize, akla karayı,

Bizim yöntemlerle, bizim yarayı,

Em yaptık sararak,  kovduk düşmanı.

Başta, yokluk, kıtlık, soğuk, var, yaman,

Beyaz kar döşekti, bulutlar yorgan,

Ülkemizde, kutsallara uzanan,

Elleri kırarak, kovduk düşmanı.

Tutuklandı, aydınımız, merdimiz,

Katmer katmer oldu, arttı derdimiz,

Yediden yetmişe, her bir ferdimiz,

Emekler vererek kovduk düşmanı.

Gayret ile, yoklukları, yok ettik,

Karalanan bahtımızı, ak ettik,

Köleliğe çıkan yolu, fark ettik,

Yarini görerek, kovduk düşmanı.

Düşmanlar, dört yandan vurdular bize,

Bir beden, bir kafa olduk biz bize,,

Ne bulduysak aldık, ellerimize,

Önününe durarak, kovduk düşmanı.

Fransa  nerede? Düziçi  nere? 

Vatana can kurban, bizdeki töre,

Yurdumuza, üşüşünce kefere,

Leşini sererk, kovduk düşmanı.

Kinlerini, köye kente saçtılar,

Şehit edip, kanımızı içtiler,

Yakıp, yıkıp, def oldular kaçtılar,

İzini  sürerek, kovduk düşmanı

.

ELEMİ hepimiz geçmiştik  serden

Hücum ettik her birimiz bir yerden

Ne toptan sakındık ne de mermiden

Göksümüz gererek kovduk düşmanı.

İbrahim PATAZ

      23/12/2005 ADANA', 'Bölge bölge paylaşıldı yurdumuz, Kuvvetler dererek, kovduk düşmanı. Ne cephane vardı, ne de ordumuz, Çeteler kurarak,  kovduk düşmanı. Topla...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Pataz']::text[], 8.5, '{"poet":"İbrahim Pataz","poet_slug":"i-brahim-pataz","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/dusmani-boyle-kovduk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çapa', 'capa-baykal-kaanalp-fp3l6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bir çapa ayağıma takılan

hasretlik çökerken

ayazın içinden kopup gelen

sürüklenen,hemsiz

bir oda boyu yalnızlığım

etrafım boş,ağaçsız

yalınlığına aldırmıyorum

hafıza kaybımın

şirin gözükmüyor gözüme

taktığım binbir çile

örgüsüz,hayta,sökülmüş

sıkştırılmaya gelmeyen

bir çapa yerinden sökemediğim

ince işçiliği çok iyi

kazımaz beni ve rötarımı

zamanında varır mevzisine', 'bir çapa ayağıma takılan hasretlik çökerken ayazın içinden kopup gelen sürüklenen,hemsiz bir oda boyu yalnızlığım etrafım boş,ağaçsız yalınl...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/capa-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şömineden Fırlayan Ateş', 'somineden-firlayan-ates-hulya-endogan-3fklo', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Orman evinin salonunda

Kapının tam karşısında

İçinden  ateş fırlatan şömine

Sanki ormandaki yanlızlığını, kızgınlığını anlatmak ister gibi

İçindeki odunların tek tek yanması,

Sanki kendisini tek tek ifade etmek ister gibi,

Orman evinin  şöminesi

 Alev alev yanması

Sanki tek başına üşüdüğünü haykırır gibi,

Orman evinin şöminesi

Önüne serilmiş halıyla kendini renklendirmek ister gibi,

Orman evinin şöminesi kenarlarındaki kırılan tuğlalarla

Zamana nasılda göğüs gerdiğini gösterir gibi...', 'Orman evinin salonunda Kapının tam karşısında İçinden  ateş fırlatan şömine Sanki ormandaki yanlızlığını, kızgınlığını anlatmak ister gibi İ...', ARRAY['Türk Edebiyatı','Şiir','Hülya Endoğan']::text[], 8.5, '{"poet":"Hülya Endoğan","poet_slug":"hulya-endogan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/somineden-firlayan-ates-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstediğim Son', 'i-stedigim-son-i-smail-erden-7hq5p', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'dilediğim mevladan 

ayakta ölmek

kanlı elbisemle

kefensiz gömülmek

bir temmuz akşamı olsun

gökyüzünde dolunay

hafif esen rüzgarla

cırcır böceginin sesi

istemem ne ağıtlar

ne bir mezar taşı

oğullarım atsın iki kürek

atılacaksa toprağımı', 'dilediğim mevladan  ayakta ölmek kanlı elbisemle kefensiz gömülmek bir temmuz akşamı olsun gökyüzünde dolunay hafif esen rüzgarla cırcır böc...', ARRAY['Türk Edebiyatı','Şiir','İsmail Erden']::text[], 8.5, '{"poet":"İsmail Erden","poet_slug":"i-smail-erden","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/istedigim-son-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acı Aşk', 'aci-ask-serkan-asilbas-qsn0k', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İki türlü aşk vardır.

Mutlu aşk ve acı aşk,

Ben bunlardan mutlu aşkı hiç yaşamadım.

Mesela; Seninle hiç el ele yürümedim.

Seninle hiç göz göze, diz dize oturmadım.

Saçlarını hiç okşamadım.

İsmini kulaklarına hiç fısıldamadım.

Soğuk ve karlı bir havada,

Ellerini ellerimle hiç ısıtamadım.

Sana hayatı sensiz yaşayamayacağımı söyleyemedim.

Mesela; Seni gördüğüm zaman sana aşkımı anlatamadım.

Yanında yürüdüğüm halde sana hiç bakamadım.

Sana komşunun bahçesinden,

Koparttığım gülleri hiç veremedim.

Seninle hiçbir zaman çay ve kahve içemedim.

Sana hiç güzelsin diyemedim.

Mutlu aşk ve acı aşk.

Ben bunlardan mutlu aşkı hiç yaşamadım.

Sana seni sevdiğimi hiç söyleyemedim.

Sana hiç telefon edemedim.

Sana sevgi,aşk ve mutluluk cümleleri fısıldayamadım.

Sana hiç şiir yazamadım.

Çünkü sen hiç benim olmadın.

Çünkü sen beni hiç sevmedin.

Çünkü senin hiçbir zaman  benden haberin olmadı.

Mutlu aşk ve acı aşk.

Ben bunlardan mutlu aşkı hiç yaşamadım.

Ben, ben sadece acı aşkı yaşadım.', 'İki türlü aşk vardır. Mutlu aşk ve acı aşk, Ben bunlardan mutlu aşkı hiç yaşamadım. Mesela; Seninle hiç el ele yürümedim. Seninle hiç göz gö...', ARRAY['Türk Edebiyatı','Şiir','Serkan Asılbaş']::text[], 8.5, '{"poet":"Serkan Asılbaş","poet_slug":"serkan-asilbas","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/aci-ask-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sorman Gerek', 'sorman-gerek-yusuf-onder-bahceci-prgwc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seni nasıl sevdiğimi,

Sevenlere sorman gerek,

Sevda için ölünürmü,

Gönüllere girmen gerek.

Nasılda sevmiştim seni,

Bitirdiler beni beni,

Seni seven kalbimi,

Bilenlere sorman gerek.

Seni sevdim seveceğim,

Senin için öleceğim,

İşte sevgim diyeceğim,

Ölenlere sorman gerek.

Ben Mecnun''um çöllerde,

Sordum Gülüm nerede,

Onu gördüm ellerde,

Ellere sorman gerek.', 'Seni nasıl sevdiğimi, Sevenlere sorman gerek, Sevda için ölünürmü, Gönüllere girmen gerek. Nasılda sevmiştim seni, Bitirdiler beni beni, Sen...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sorman-gerek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşayacağım', 'yasayacagim-serdar-ahmet-guzel-1x2p6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yaşa diyorsun bana sevdan için sevdalığın için

Sen istersinde ölürmüyüm artık, canım sevdiğim! 

İşlemez bana ne kar ne boran nede fırtına

Bu kalp ölmez sen istemedikten sonra

Ne süngü, ne bıçak, nede bomba 

Hükmü yoktur artık hiçbir silahın, düşmanın

Hiç biri işlemez senin sahip olduğun dosta

Bu kalp ölmez sen istemedikten sonra

Cehennemler kudursa, şeytanlar çarpsa

Bütün dünya orduları üzerime varsa

Kemiklerim kırılsa, vücudum parçalansa

Bu kalp ölmez sen istemedikten sonra

Kılıçlar tüm bedenime saplansın

Vücudum paramparça olsun

Yılanlar  her yerimi soksun dursun

Bu kalp ölmez sen istemedikten sonra

Toplansın tüm beşeriyet, hepsi üzerime varsın

Mikroplar saldırsın ciğerlerime varsın

Felek uğraş versin durmasın

Bu kalp ölmez sen istemedikten sonra

28.12.2005 Saat:12.00', 'Yaşa diyorsun bana sevdan için sevdalığın için Sen istersinde ölürmüyüm artık, canım sevdiğim!  İşlemez bana ne kar ne boran nede fırtına Bu...', ARRAY['Türk Edebiyatı','Şiir','Serdar Ahmet Güzel']::text[], 8.5, '{"poet":"Serdar Ahmet Güzel","poet_slug":"serdar-ahmet-guzel","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yasayacagim-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akşamın', 'aksamin-halil-colak-07hwp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Akşamın yeni doğmuş yıldızlarına

Cananın derinden hülyalı bakışlarında

Hisseder kaderin ağırlığını omuzlarında

Anlatır küllenmiş aşkları tarihin sayfalarında

Efsanelerde anlatılır tutkulu nice aşklar

Zamana mal olur o tutkulu candan sevgiler

Dilden dile dolaşır aşkla ilgili menkıbeler

Hak aşıkların rastlanır hayat hikayelerinde

Bütün sevenler, çileceker zülüm görür ilahi aşkta

Allah için yapılan gönülden yapılan ilahi meşkte

Mecnun gibi ararsın leylanı gönül çölünde

Yunus gibi yer edersin  gönül kapılarında

Sığın Rabbine gönülden korkma kimseden

Sevgi muhabbetini al Hz.Muhammed Mustafa’dan

Felah vardır yaydığı islamın mübarek nurundan

Girmezsin artık hak olan cananım cehennem kapısından 

Halil Çolak 29.12.2005 Ankara', 'Akşamın yeni doğmuş yıldızlarına Cananın derinden hülyalı bakışlarında Hisseder kaderin ağırlığını omuzlarında Anlatır küllenmiş aşkları tar...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/aksamin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düştü...', 'dustu-ahmet-ozyilmaz-fdwkj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'gözlerin en güzel düştü.

kor gibi gönlüme düştü.

kolay alınmaz sanırdım,

bir kez baktın, kalbim düştü! ..

27 Aralık 2005

Afyonkarahisar', 'gözlerin en güzel düştü. kor gibi gönlüme düştü. kolay alınmaz sanırdım, bir kez baktın, kalbim düştü! .. 27 Aralık 2005 Afyonkarahisar...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Özyılmaz']::text[], 8.5, '{"poet":"Ahmet Özyılmaz","poet_slug":"ahmet-ozyilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/dustu-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sadece Senin Hayatın...!', 'sadece-senin-hayatin-pinar-koc-fgqh7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gözlerinden geçmişini okudum,

Ve yıllar sonraki geleceğini….

Bir dağ patikasıydı sanki hayatın! 

İnişli çıkışlı yaşantının izlerini buldum

Buruk tebessümünde…

Bir acı,bir hüzün vardı dudağının kenarında,

Ve kımıldıyordu sanki mühürlü dudakların resminde…

Geleceğini fısıldıyordu sanki usul usul…

Umutlarını ve gerçekleşecek hayallerini…

Gözlerini derinliklerinde kaybolduğumu sandım,

Arasında kaldım geçmişinin ve geleceğinin…

Hangisine elimi uzatmalıydım? ? ? 

Geçmişinde kaybolup,geleceğine mi bakmalıydım,

Yoksa,

Geleceğine gidip,ağlamalı mıydım kapılar ardındaki 

Geçmişine…

Geleceğini fısıldıyordu usul usul dudakların

Bir dağ patikasıydı sanki hayatın,

İnişli çıkışlı yaşantının izlerini buldum

Derin gözlerinin, 

Derinliklerinde….

                                                                             28.12.05      05:40', 'Gözlerinden geçmişini okudum, Ve yıllar sonraki geleceğini…. Bir dağ patikasıydı sanki hayatın!  İnişli çıkışlı yaşantının izlerini buldum B...', ARRAY['Türk Edebiyatı','Şiir','Pınar Koç']::text[], 8.5, '{"poet":"Pınar Koç","poet_slug":"pinar-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sadece-senin-hayatin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bipolar Düşüncelerim...', 'bipolar-dusuncelerim-pinar-koc-80xl6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yağmur bulutları gibiydi,

Gözlerindeki gecikmiş hüznün…

Yıllar öncesindendi belki içindeki yarım sızı…

Yarım hissettin belki yıllar öncesini,

Ama yarım kalmamalı yıllar sonrası…

Karanlık bir gecede,

Kim bilir nerde,nasıl,kaç yaşındaydın? 

İçindeki çocuğun kaç yaşındaydı? 

Ve sen kaçıncı’yas’ındaydın? 

Yağmur bulutları gibiydi

Yüzündeki geçici gülüşün! ! ! 

Ve yıllar sonrasıydı belki

Gözlerimdeki gelincik süzülüşün….

                                                                                     28.12.05   05:40

(bipolar=duygu durum bozukluğu)', 'Yağmur bulutları gibiydi, Gözlerindeki gecikmiş hüznün… Yıllar öncesindendi belki içindeki yarım sızı… Yarım hissettin belki yıllar öncesini...', ARRAY['Türk Edebiyatı','Şiir','Pınar Koç']::text[], 8.5, '{"poet":"Pınar Koç","poet_slug":"pinar-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bipolar-dusuncelerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu tabanlar nice çarık eskitti', 'bu-tabanlar-nice-carik-eskitti-mikdat-bal-9113b', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu tabanlar nice çarık eskitti

Neler çektim bu kafanın yüzünden

Nereye tuttuysam işim ters gitti

Bezdim bıktım bu kafanın yüzünden

Çektiklerim yüreğimi dağlattı

Kör eyledi zalimlere bağlattı

Dost sandığım çoğu beni ağlattı

Çok yaş döktüm bu kafanın yüzünden

İki yüzlü yüzsüzlerden bin beter

Sana güler ama kalpte kin güder

Riyakarda madde için din gider

Yanlış baktım bu kafanın yüzünden

Maske ile bana kanca taktılar

Gafletimden boğazımı sıktılar

Adam sandıklarım “madam” çıktılar

Hep bön çıktım bu kafanın yüzünden

Mikdat’ım ben gönlüm harap çok gördüm

Ne kafamı çalıştırdım ne yordum

İyi adam müslümandır diyordum

Çok borç taktım bu kafanın yüzünden', 'Bu tabanlar nice çarık eskitti Neler çektim bu kafanın yüzünden Nereye tuttuysam işim ters gitti Bezdim bıktım bu kafanın yüzünden Çektikler...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bu-tabanlar-nice-carik-eskitti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırılan Bir Tek Kiremit...', 'kirilan-bir-tek-kiremit-pinar-koc-wrwl0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kırıldım! 

Evinin çatısındaki kırmızı bir kiremittim belki

Ve düştüm,

Ve kırıldım…

Uzun zaman fark etmedin

Beni ve kırılmışlığımı….

Ta ki………

Bir sağanak yağmur sonrası

Evinde,

İnatçı bir yağmur damlasının

Yüzüne damlayıp,

Yanaklarından süzülmesine dek…

                                                                                    28.12.05   05:45', 'Kırıldım!  Evinin çatısındaki kırmızı bir kiremittim belki Ve düştüm, Ve kırıldım… Uzun zaman fark etmedin Beni ve kırılmışlığımı…. Ta ki………...', ARRAY['Türk Edebiyatı','Şiir','Pınar Koç']::text[], 8.5, '{"poet":"Pınar Koç","poet_slug":"pinar-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kirilan-bir-tek-kiremit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin İçin Öldüm Be', 'senin-i-cin-oldum-be-yusuf-onder-bahceci-iqzp3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sade seni sevmedim,

Senin için öldüm be,

Sevgim dilimde değil,

Kalbimin içinde be.

Seni de sever sandım,

Sandımda nasıl yandım,

Bir rüyaymış uyandım,

Senin için öldüm be.

Seni sevdim tüm kalbimle,

Bu kâlp esir bedenimde,

Beni bırakıpta gidende,

Ölmüşüm ben öldüm be.

Ne olurdu sevseydin,

Bana gönül verseydin,

Seni sevdim deseydin,

Ölüyorum öldüm be.....', 'Sade seni sevmedim, Senin için öldüm be, Sevgim dilimde değil, Kalbimin içinde be. Seni de sever sandım, Sandımda nasıl yandım, Bir rüyaymış...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/senin-icin-oldum-be-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fidanlara kalsın Gözlerindeki Yangın', 'fidanlara-kalsin-gozlerindeki-yangin-ahmet-degirmenci-7t7wx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sukunette rüzgar

meltemleri salıyor üzerime

kalan aşk oluyor

her faniden baki

terkedene bakma sen 

kışlar üç ay sürer

soğuk mahkum edemez seni.....

yanma yüreğim yanma

az kaldı bahara

kaldırımlara yakışıyor kar

fidanlara kalsın 

gözlerindeki yangın

susuz kalmasın çiçekler

bir demette benim için topla

adını unutan vefasıza

seni yalnız bırakanlar utansın', 'Sukunette rüzgar meltemleri salıyor üzerime kalan aşk oluyor her faniden baki terkedene bakma sen  kışlar üç ay sürer soğuk mahkum edemez se...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Degirmenci']::text[], 8.5, '{"poet":"Ahmet Degirmenci","poet_slug":"ahmet-degirmenci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/fidanlara-kalsin-gozlerindeki-yangin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haticem', 'haticem-sedat-yukseker-eryf1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yine akşam..yine karanlık

bir yatak odasında

sensizliğe içiyorum

yokluğun buğulu sisini..

Yedi sene bana,

yediremedi gül yüzünü,

sonsuz bakışını.

Ve ben her karanlıkta 

aç kalyorum senin deniz gülüşüne,

yokluğuna; sonsuzluğuna daralıyorum.

Küçültemiyorum ama yüreğimi..

Artıkça karanlık,

daha da büyüyor denizce hasretim..

Gül yüzlüm,sonsuz bakışlım; 

bir veda ertesi değil bu,

bir başıboşluğun pençesinde 

incinmek değil...

Sana nedenini veremediğimin öfkesi,

sana,

seni seviyorum diyemeyişimin...

Senden bana kalanı,

bilemezsin.

Duvarlar ayna olmuyor,

göremezsin.

Bir bebeğin gülüşünde,

seni seviyorum deyişimi,

duyamazsın.

Duyamassın,

denizimde ağladığımda,

gelip gözyaşımı silemezsin.

işte çiziyorum; 

senden bana kalanı,

benden alıp götürdüğünü

,bizden alıp götürdüklerini

değil; 

küçük bir Anadolu şehrinde,

elin elimde,

yüzün yüzümde,

ben ölümüne sarhoş.......', 'Yine akşam..yine karanlık bir yatak odasında sensizliğe içiyorum yokluğun buğulu sisini.. Yedi sene bana, yediremedi gül yüzünü, sonsuz bakı...', ARRAY['Türk Edebiyatı','Şiir','Sedat Yükseker']::text[], 8.5, '{"poet":"Sedat Yükseker","poet_slug":"sedat-yukseker","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/haticem-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vuslat', 'vuslat-serap-demirturk-4k24s', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sadece  bir selam vermektir dileğim..rahatsızlık değil..istemeyen gönle girmek hiç değil..Bilesin ki yar, gözlerinde bulmuştum yüreğindeki beni ve sözlerinde kaybettiğimi anladım içindeki sevgimi...Ne garip duygu şu aşk. Fıratın azgın suları durulmadı...durulan yüreklerdeki coşkudur ey yar...Güzel olan...bir atımlık mesafeden vuramadan yüreği, soluklanıp giderken gözlerdeki sevgidir..güzel olan, konuk olduğunda gönle -bir fincan kahve kadar bile olsa -hatırda kalmaktır..ve güzel olan yar...yar diye diye  vurup mızrabın teline sevdayı kaleme alıp ölümsüzleştirmektir -bir gün öleceğini bilircesine yürekte-...Sitemim yoktur, özlemim söylenmez, umudumsa ta ezelden girmemiş ki içime...Varıp söylemek isterdim seni bilen ellere yüreğinin güzelliğini..diyemem...Gelip görmek isterdim bahçendeki nergisleri...gelemem...Sen bil..bil ki her daim ak güvercinler konar ya balkonlara bir lokma ekmek için..Sen bil..o kuşların yüreğindedir bir lokma ekmekle giren sevgi..Yüreğe giren sevginin de çıkmayacağını dünya bilsin...Vuslat neymiş, bunu yıldızlar görsün.', 'Sadece  bir selam vermektir dileğim..rahatsızlık değil..istemeyen gönle girmek hiç değil..Bilesin ki yar, gözlerinde bulmuştum yüreğindeki b...', ARRAY['Türk Edebiyatı','Şiir','Serap Demirtürk']::text[], 8.5, '{"poet":"Serap Demirtürk","poet_slug":"serap-demirturk","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/vuslat-57-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '** Güneş ve Yağmur**', 'gunes-ve-yagmur-seyhmus-sevilmez-srctp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Güneşli bir günde sırılsıklam âşık oldum

Yağmurlu bir günde ise kavrularak aşktan oldum.

Hani güneşten yüzün, gülümserdi ya yüzüme,

Sevda tohumlarını salıvermişti özüme..

Mevsimlerin adını bilmeden

Dallanıp budaklandı aşk.

Zaman mekân dinlemeden

Gâh ıslandı, gâh yanıp kavruldu âşık.

Mahremliği tutu güneşin,

Kara bulutlardan peçesini çekti yüzüne.

Kalan bir demet şuanı kaybetmemek için 

Dalıverdim gözüne, ama faydasız…

Kısa süren oyun bitti ve 

Perde……

Şimdi 

Kimseler görmesin diye

Yağmur yağınca ağlarım.

Sensiz zemheri günlerde

Yüreğimi dağlarım.  

Artık güneş doğsa bile, kör gözleri bağlamaz

Hangi deli demiş, güya” Erkekler hiç ağlamaz”

Hiç durmadan yağsa 

Bütün yollar batak çamur dahi olsa, fark etmez…

Seni düşünürken ağlamalıyım bu gece…

Gözyaşlarımı gizleyen bir yağmur eşliğinde.

28.12.2005/ Batman', 'Güneşli bir günde sırılsıklam âşık oldum Yağmurlu bir günde ise kavrularak aşktan oldum. Hani güneşten yüzün, gülümserdi ya yüzüme, Sevda to...', ARRAY['Türk Edebiyatı','Şiir','Şeyhmus Sevilmez']::text[], 8.5, '{"poet":"Şeyhmus Sevilmez","poet_slug":"seyhmus-sevilmez","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/gunes-ve-yagmur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çaresi Varmıdır ki', 'caresi-varmidir-ki-yusuf-onder-bahceci-2q2ir', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ağlayan bu gözlerin,

Kırılan şu kalplerin,

Karşılıksız sevginin,

Çaresi varmıdır ki.

Yıkılan gönüllerin,

Kalbindeki yaranın,

Yürekteki yangının,

Çaresi varmıdır ki.

Ayrılan bu yolların,

Aşılmayan dağların,

İyolmayan dertlerin,

Çaresi varmıdır ki.

Bulan varsa beri gelsin,

Beri gelsin bana desin,

Sonra cânımı istesin,

Çaresi varmıdır ki....', 'Ağlayan bu gözlerin, Kırılan şu kalplerin, Karşılıksız sevginin, Çaresi varmıdır ki. Yıkılan gönüllerin, Kalbindeki yaranın, Yürekteki yangı...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/caresi-varmidir-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Koridorlar', 'koridorlar-hamza-mamas-f2u00', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Karanlık ve upuzun koridorlara hapis olmuş düşlerim.

Her tarafı çıkılmaz; her tarafı kapalı koridorlar…

Emiyor sanki damarlarımdaki son kanı bile bu yol,

Başlamakla bitirmek arasında bir hiç varlığım; 

                                Sen resmimi çerçeveye koy.

Sessiz bir inilti,

Acı bir feryat var ruh derinliğimde.

Çıkmaz yollar; 

Ve hep uçuruma açılıyor koridorlar.

Rengi belirgin değil ufkun,

Tanımadım asisini ve mavisini denizlerin,

                          Bildiğim tek şey kapkaranlık koridorlar.

Yalvarmak yanlış ise ben hep yanlış yaptım…

Sonsuz ve karanlık koridorlar içinde; 

Beni ölüme; 

Hata ölüm içere ölüme götürüyorlar sandım.

Çıktım,

Çattım,

Açıktım,

Yalvardım…

Lakin hep yalnız kaldım.

Umutlandım; 

Unutulduğumu da geç anladım.

Artık yaşadığıma inanmakla inanmamak arasında bir yerde; 

Belki de öğle vakti ben hala gecedeyim.

Bitmeyecek…

Uzadıkça uzayan bu koridorlar.

Ömrüm diyorum ya; 

Olmayan ömrümde bitecek belki,

                     İşte o gün bitecek koridorlar. 

Tiz bir sesle feryat ediyor yüreğim bu hengame içinde,

Kalabalıklardan yoksun koridorlarda duygular yoğun.

Gelen olmuyor, 

Gidene de üzülmüyorum.

Ancak ve ancak gelenlerden sonra gidenlerle vedalaşabiliyorum,

                                                 Bekliyorum açılsın bu koridorlar.

Labirentte kaybolmuş bir fare gibi; 

Ne gidişimi,

Nede nereye gidişimin olduğunu bilmiyorum.

Benim dünyam ufak, daracık ve kapkaranlık…

Ömrüme kafes olan lanet bir koridor.

                            Yaşamak bu ise yaşlılığı bana sor.

Bu koridorlar farklı…

Farklı bu koridorlar.

Doğmayan  evladın acısı bir duvar; 

Olmayan babanın hasreti bir sur.

Değil ağlamak gülmek bile bir kusur.

Işıktan yana yok hiçbir belirti umutlar bitmiş.

                        Bütün yoklar etrafıma birikmiş.

Dert yanmak doğrumudur bilmiyorum ya…

Yok etmek adına bütün yoklar benliğimde birikmiş.

Ne gece,

Nede gündüzü biliyorum.

Bu garip ahval ile sürünüp gidiyorum.

Güneş aydınlıkmış,

Gece karanlık; anlatamaz.

                            Bu alemi bana tanıtamazlar.', 'Karanlık ve upuzun koridorlara hapis olmuş düşlerim. Her tarafı çıkılmaz; her tarafı kapalı koridorlar… Emiyor sanki damarlarımdaki son kanı...', ARRAY['Türk Edebiyatı','Şiir','Hamza Mamaş']::text[], 8.5, '{"poet":"Hamza Mamaş","poet_slug":"hamza-mamas","theme":"Türk Şiiri","is_hero":false,"total_lines":57,"source_url":"https://www.antoloji.com/koridorlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Denizlerce (İsmail Haydar Aksoy)', 'denizlerce-i-smail-haydar-aksoy-i-smail-aksoy-bse4s', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '''Gitmekle kalmak arası sızılarla 

Durul bende'' dedi kadın 

''Arın bende 

Solu bende 

Bin ruhumda bin yürek 

Tüm sevdaları yak bende'' dedi kadın 

''Sana bir dünya veriyorum 

Dokun 

Yaşa 

Çoğal benle'' dedi kadın 

Akdeniz''in kızıydı O 

Elleri çam ve püren kokardı 

Soluğu tarçın ve kekik 

Memeleri 

Toros Dağları''nın karlı dorukları 

Bembeyaz turunçlar asılı 

Durur düşlerin ağacında 

Saçları harman yerinde savrulan başaklar 

Ve dölyatağı dar bir kanal 

Bir okyanus gibi 

Çalkalandı adam dölyatağının kayalıklarında 

Ve duruldu sonra 

Sevdi ve seviyor adam kadını 

Yasak bir elma olarak algılamadı adam kadını hiç 

İştahla dişledi etini ve etenesini 

Şehvet ve sevginin sarmalandığı 

Avuntusuz bir tutkuyla 

Kavradı kadını 

Sevdi ve seviyor adam 

Duruldu adam kadında 

Arındı 

Soludu kadında 

Bin ruhunda bin yürekti 

Tüm sevdaları yaktı O''nda 

Adama bir dünya vermişti kadın 

Baktı adam 

Dokundu 

Yaşadı 

Çoğaldı kadınla ve kadında 

Sevdi adam kadını denizlerce 

(25-28 Aralık 2005 / Antalya - Denizli) .', '''Gitmekle kalmak arası sızılarla  Durul bende'' dedi kadın  ''Arın bende  Solu bende  Bin ruhumda bin yürek  Tüm sevdaları yak bende'' dedi kad...', ARRAY['Türk Edebiyatı','Şiir','İsmail Aksoy']::text[], 8.5, '{"poet":"İsmail Aksoy","poet_slug":"i-smail-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/denizlerce-ismail-haydar-aksoy-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaçamamaklarım', 'kacamamaklarim-baran-baransel-0j53t', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Canım isteyince yazarım ben,

Canım isterse yatarım,

Daha canım isterse,

Yakarım bir cigara,

Dumanından dost yaparım.

Kime ne yahu? 

Ayrıca kime, ne zararı var? 

Kelebeği dokunmadan sevmenin.

“Festival gibi olmalı sevişmeler” demenin hesabını

Kim sorabilir ki benden? 

Kâh gündüzleri meze yaparım gecelerime,

Kâh akşamları bir şarap kadehine

Esir düşürürüm.

Mecburiyetlerim de var birden çok,

Sallamakla düşmez yakamdan hiçbirisi,

Ama onların içinde birisi,

Kuralsız, yasaksız, tahammülü yok,

Zaman, mekân hak getire,

Herşeye noktalı bir virgül koyup; 

Yâr! .. Seni düşünürüm…', 'Canım isteyince yazarım ben, Canım isterse yatarım, Daha canım isterse, Yakarım bir cigara, Dumanından dost yaparım. Kime ne yahu?  Ayrıca k...', ARRAY['Türk Edebiyatı','Şiir','Baran Baransel']::text[], 8.5, '{"poet":"Baran Baransel","poet_slug":"baran-baransel","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kacamamaklarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalbim Kırık Seni Sevdim', 'kalbim-kirik-seni-sevdim-yusuf-onder-bahceci-swe9p', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu Dünya''da seni sevdim,

Seni sevdim, seni övdüm,

Benim sevgim kalbimde,

Kalbim kırık seni sevdim.

Seni gördüm, seni sevdim,

Seni cânım, cânım bildim,

Sense gidip elin oldun,

Kalbim kırık, seni sevdim.

Seni nasıl severim ben,

Senin için ölürüm ben,

Sana Gülüm derim ben,

Kalbim kırık seni sevdim.

Seni sevdim evvel, ezel,

Sensin bu gönlümde güzel,

Seni görür ağlar, gözler,

Kalbim kırık seni sevdim.', 'Bu Dünya''da seni sevdim, Seni sevdim, seni övdüm, Benim sevgim kalbimde, Kalbim kırık seni sevdim. Seni gördüm, seni sevdim, Seni cânım, cân...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kalbim-kirik-seni-sevdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitme', 'gitme-hasan-kutsal-eker-zpy1x', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Özlemin tortusu çöküyor yüreğime

Gidişin korkumun çıplakllığında

Apansız giriyor düşlerime

Ölümcül karlar yağıyor üstüme

Sensizliğin hiçliğinde umutlarım

Mutsuz baharlara gebeyim

Gerginliğin odağında tutuklu

Düş gücü sınırlı kararsız korkak

Nisan yağmurlarında sırılsıklam

Gelişin körpe bir bahar şimdi

Gidişin kızılca kıyamet olacak', 'Özlemin tortusu çöküyor yüreğime Gidişin korkumun çıplakllığında Apansız giriyor düşlerime Ölümcül karlar yağıyor üstüme Sensizliğin hiçliği...', ARRAY['Türk Edebiyatı','Şiir','Hasan Kutsal Eker']::text[], 8.5, '{"poet":"Hasan Kutsal Eker","poet_slug":"hasan-kutsal-eker","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/gitme-145-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anladım ki Batal* Gönlün Kapısındaki Kilit Karlar Atında Umut', 'anladim-ki-batal-gonlun-kapisindaki-kilit-karlar-atinda-umut-kamil-aydemir-13l94', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ah hep bizim kanımızla mı beslenecek bit

sanki şu kalbi delik cimri hayat kudurmuş it

ben bugünden yarına savrulurken ılgıt ılgıt

ömrüm ağıtlara yenilmiş zılgıt

şimdi benim gibi yapayalnız

benim gibi virane

kocabey köyündeki doğduğum ev

razıyım beni köyün gibi sev

ihlamur çayı kokulu kış günleri

evimizin camına öpücük konduran

               bahçemizin gülleri

ne kilim dokuduğu kilkit

ne de buğulu sesi annemin

eve kafkaslar gibi dönüşü babamın

onca güzellik 

afişlenen gençliğim gibi yitik

ah kalbimin çiçeği

evin bir köşesinde

yastık altı düşlerinde olmamda

beni mutlu eder şimdilik

ayvanlarda makam hüzzam

sabahla pencereden içeri sızan

akşama doğru da süzülerek dağları aşan

güneş gibisin (tıpkı)   düşlerimin kadını

sımsıcak gülüşün ıstır da içimi

dokunamam uzansam

ihanet etmiş olurum aşka

bu sevdayı susarsam

her köşesinde bir anım

her köşesinde çocukluğum

zor taşınır hüzün olsa da yokluğum

ben köyümüzdeki evin her yanına sızmışım

tıpkı senin bana sızdığın gibi

benim sana

köydeki evimizi 

en son gördüğümde anladım ki

biraz da hayırsızmışım

senin gibi

onca çaresizliğimle

onca yorgunluğumla

ve de berbat halimla

ve de seni mutluluğun doruklarına taşıyacak sevgimle

sığınmak istedim gönlüne

hangi anahtarıyla denediysem sevginin

açamadım gönlün kapısını

anladım ki batal gönlün kapısındaki kilit

şimdi karlar altında umut

üşür yarınlarım

hadi en ıslak yanımdan tut

beni sevgi sıcağında kurut

bakışların kaçak tütün

yüreğim nemli kirpit

* Batal: Bozuk', 'ah hep bizim kanımızla mı beslenecek bit sanki şu kalbi delik cimri hayat kudurmuş it ben bugünden yarına savrulurken ılgıt ılgıt ömrüm ağıt...', ARRAY['Türk Edebiyatı','Şiir','Kamil Aydemir']::text[], 8.5, '{"poet":"Kamil Aydemir","poet_slug":"kamil-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/anladim-ki-batal-gonlun-kapisindaki-kilit-karlar-atinda-umut-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanık Sevdam', 'yanik-sevdam-cengiz-kapusuz-tm85y', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yanık sevdam,kara bahtım...

Dün yine seni düşündüm.

Son gecemizde gidiyorum demiştin ya! 

Sabahında yapayalnız kaldığımı...

Çıkamadım arkana yanık sevdam.

Tutamadım ellerini kal diye,

Bakamadım gözlerine,

Yüreğim takılı kaldı izlerine...

Sigaramdaki duman yanık sevdam,

Senin hayalini çiziyordu sanki.

İçime çektiğim her nefes,

İçinde yalnızlığım olan kafes.

Gecelerin sensiz karanlığında,

Odada kokan senlerle avunuyorum.

Sen olmayınca Yanık sevdam,

Tan ağartısıyla kayboluyorum.....', 'Yanık sevdam,kara bahtım... Dün yine seni düşündüm. Son gecemizde gidiyorum demiştin ya!  Sabahında yapayalnız kaldığımı... Çıkamadım arkana...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Kapusuz']::text[], 8.5, '{"poet":"Cengiz Kapusuz","poet_slug":"cengiz-kapusuz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yanik-sevdam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zile', 'zile-mehmet-ayhan-gunaydin-mzm78', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ZİLE

Anadolu’da bir ova,

Ve,

Ovanın tam ortasında,

Bir tepe.

Tepenin üstüne oturtulmuş,

Bir kale.

Kalenin etrafına dolanmış,

Evler.

Ve 

İçindekiler.

Şekli tarifi böyle; 

İşte Zile.

Her daim gözümde 

Tütüyor da, hala.

Fırsat buldukça,

Alıyorum soluğu,

Baba ocağında.

Hem artık yaşlandık,

Bu şehirde geçti çocukluğum.

Yaştan olsa gerek,

Maziyi özlüyor ruhum.

Zile’de sembol kale.

Çık kaleye bir izle.

Omuz omuza vermişte,

Eski evler.

Zamana direnmekteler.

Kalenin yakınında eskiler,

Eskinin ardında yeniler.

Bu şehri anlatan yapılar; 

Camiler, hanlar, hamamlar,

Eskiden taş döşeli sokaklar.

Eski ve yeni evler,

İçindeler, Zile’deler.

Şehrin kuzeyi, doğusu 

Güneyi ve batısı,

Ayrı bir resim verir.

Kale’den bakınca Zile,

Dile gelir, dillendirir.

Nedense? Daha çoktur,

Üç yönde,

Eski evler.

Üç yönde daha çoktur,

Omuz omuza verip de,

Zamana direnenler.

Ve batı; 

Batı da eskinin ardında

Nedense? Daha çoktur.

Birbiri üstüne,

Dizilmiş,

Kibrit kutusu gibi evler.

Ben eskiyi,

Ve eski çok olduğundan,

Kalenin çevresini 

Daha çok seviyorum.

Eski daha çok olduğundan, 

Olsa gerek.

Bu resim,

Bana daha sıcak, daha benden geliyor,

Sanki daha çok, bizi, bize söylüyor. 

Ve evler daha çok omuz omuza,

Eskinin de ruhunu anlatıyor.

Öyle sanıyorum, öyle hissediyorum,

Böyledir belki, 

Nedense? 

Öyle düşünüyorum.

Eski evlerin genelde,

Çift kanatlı kapıları var.

Her kapının ayrı bir kişiliği,

Ayrı da bir hikayesi var.

Her kapıda tok ses veren,

Bir de çın diyen, 

Tokmakları var.

Küçükleri de düşünmüş eskiler,

Onların, boyuna göre olanı da var.

Erkek tok olanı çalar.

Kadın çınlayanı,

Çocuksa boyuna,

Göre olanı çalar.

Çalınınca bilsin diye evdekiler.

Gelen erkek mi, kadın mı? 

Bilip öyle çıksın diye avludan,

Çeki düzen versin kendine.

Gelenin evdekine,

Evdekinin de gelene,

Saygısından. Anlaşılan.

Adı hayat; her evin bir avlusu, 

Avlusunda şınavatı var.

Bir köşe de gater gater odunu,

Hayat da, bir köşede tandırı da var.

Şınavat ta üzüm ezilir,

Tandırda pekmez kaynatılır.

Odun gateri yanında,

Tandırda, işkefe de yapılır.

Unutmamak lazım bir de,

Pekmezle köme basılır.

Gatmeri ve de batı,

Bunlar da  Zile’ye hastır.

Evler omuz omuza, insanlar da öyleydi,

Her evin her hali herkesçe bilinirdi.

Yalnız saygılıydı birbirine, 

Hissettirilmez di dardakine,

Zorluklar böyle, birlikte göğüslenirdi.

Bir hanede yalnız kim, bilinirdi,

Ya da o gün tencere kaynatamamışsa biri.

Bir yol bulunur, mutlak davet edilirdi, 

Allah ne verdiyse o da birlikte yenilirdi.

Zile’nin iki ayrı zamanı vardı 

Güzel di, hala da güzeldir.

Biri bağ bozumu, diğeri kiraz zamanı, 

Güzeldir ve Zile’ye özeldir.

Yazın kiraz zamanı,

Bağlarda festival olurdu.

Güzün, Bağ Bozumu sonrası,

Şehirde, Panayır kurulurdu.

Mahallede çoluk çocuk,

Hep birlikte oynanırdı.

Her sokakta büyükler,

İşler birlikte yapılırdı.

Ne varsa paylaşılırdı,

Hüzünde ve, neşede.

Yoksul olan kollanırdı,

Her zaman ve her yerde.

Sembol demiştim ya size,

Zile’nin sembolüdür  kale.

Çocukken bizde, 

Genelde

Kale de oyun kurardık.

Yazın top oynar,

Kışın çokça kayardık.

Enek oynardık bir de,

Çelik çomak da vardı.

Bir de gazoz kapaklarını,

Taşla, bir daireden çıkarırdık.

Bilgisayar yoktu o zaman,

Ne de internet kafe.

Tek başımıza değil,

Biz birlikte oynardık.

Acıkınca da fark etmez,

En yakın kapıyı çalardık.

Kapıya çıkan kadına, 

Sürüyle çocuk.

Hep bir ağızdan, derdik.

-Biz acıktık ebe.

Ebeyse derdi bize

-Ebeniz size gurban,

-Size şimdi sofra kurarım,

-Eccük bekleyin hele.

Biz beklerdik avluda,

Ya da sokak ortasında.

Biraz sonra, gelirdi ebe,

Bir sini üstünde,

Dürülmüş işkefelerle.

Kimi zaman içinde 

Salça olurdu işkefenin.

Kiminde de çökelik dürülürdü içine,

O güzelim nimetin.

Dedim ya; ya çökelik ya salça,

Yumulurduk onca çocuk,

Bir arada, ya sokak ortasında

Ya da avluda 

Cümbür cemaat, çoluk çocuk.

Şimdi düşünüyorum da,

Mühim olan sofra değil,

İsteğe verilen, sıcacık karşılıktı.

Nevale kıt olsa da,

O ne güzel azıktı.

Baharda başlayınca yağmurlar,

Mahallede bütün çocuklar.

Bir tekerleme eşliğinde,

Sokağa fırlardık.

Tekerlemeyse şöyle; 

‘Yağıyor yağmur, teknede hamur,

Ver Allah’ım ver, sicim gibi yağmur’.

Yağmur sonrası her evden.

Kiminden yağ, bulgur da kiminden.

Biz çocuklar toplardık.

Toplanan malzemeyi,

Bir eve bırakırdık.

Pişirirdi, bir yenge

Topladığımız malzemeyle

Bizim yemeğimizi.

Sokağın ortasına soframızı kurardık,

Bütün çocuklar birlikte,

Bulgura kaşık çalardık.

İşte ben çocukluğumdaki,

O şehri arıyorum.

Eskiden böyleydi,

Şimdiyse özlüyorum.

Eskiden Zileli’de ruh buydu,

Zile’de bu ruhta bir şehir.

Öğrenirse yeni nesil,

Bu ruhla dolar belki, 

Kim bilir.

Sizden bir ricam var.

Burada yaşayanlar.

Geçmişe sahip çıkın,

Bu şehrin hatırası var.

Eskiyi bilin, 

Yeniyi öyle şekillendirin.

Bilmezsek geçmişi,

Yeninin kıymeti de olmaz, bilin.

Kural bu konan göçüyor,

Ömür çok hızlı geçiyor.

Yavaş yavaş sıra artık,

Bizlere de geliyor.

Zile ise asırlardır ayakta,

Zamana direniyor.

Asırlardır ayakta,

Asırlardır bekliyor.

Allah imkan versin,

Binlerce yıl olduğu gibi,

Kıyamete dek beklesin.

Bizim olan bu şehir,

Bu ruhla dolsun yeniden

Dolsun, öyle beklesin.

Hatırlasın şimdikiler,

Tüm bunları şöyle bir. 

Şimdi yeni yetişenler,

Önemini kavrasın.

Bu ruh ki önemlidir.

Yeni nesil okusun 

Önce bir okusun.

Sonra çıksın kaleye,

Baksın şöyle Zile’ye.

Ve; 

Eskinin,

Ve, 

Bu şehrin,

Kıymetini bilsin.

Bu ruhla işte,

Zile’ye değer versin! ! ! 

M. Ayhan Günaydın.', 'ZİLE Anadolu’da bir ova, Ve, Ovanın tam ortasında, Bir tepe. Tepenin üstüne oturtulmuş, Bir kale. Kalenin etrafına dolanmış, Evler. Ve  İçin...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ayhan Günaydın']::text[], 8.5, '{"poet":"Mehmet Ayhan Günaydın","poet_slug":"mehmet-ayhan-gunaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":233,"source_url":"https://www.antoloji.com/zile-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
