INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Balon Gibi Şişirdiler', 'balon-gibi-sisirdiler-sahin-erturk-mlfrm', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Alladılar,pulladılar

Balon gibi şişirdiler

Zirvelere çıkardılar

